import { PassStatus, PaymentStatus, Role } from '../src/types/enums';
import { hashPassword } from '../src/utils/password';
import { activatePass } from '../src/services/pass.service';
import { prisma, seasonBounds, SEASON_YEAR, daysAhead } from './seed/helpers';
import { trackSeed } from './seed/tracks';
import { hoursWeekSeed } from './seed/hoursWeek';
import { hoursFor, trackEventSeed } from './seed/trackProfiles';
import { trackPhotoSeed } from './seed/trackPhotos';
import { trackReviewSeed } from './seed/trackReviews';
import { tierSeed, userSeed, perkSeed, followSeed } from './seed/people';
import { seedActivity } from './seed/activity';

const DEFAULT_PASSWORD = process.env.SEED_DEFAULT_PASSWORD || 'dialed123';

async function wipe() {
  // FK-safe order: children before parents.
  await prisma.auditLog.deleteMany();
  await prisma.perkRedemption.deleteMany();
  await prisma.perk.deleteMany();
  await prisma.trackFollow.deleteMany();
  await prisma.trackReviewPhoto.deleteMany();
  await prisma.trackReview.deleteMany();
  await prisma.scanEvent.deleteMany();
  await prisma.redemption.deleteMany();
  await prisma.reservation.deleteMany();
  await prisma.payment.deleteMany();
  await prisma.allotment.deleteMany();
  await prisma.pass.deleteMany();
  await prisma.passTier.deleteMany();
  await prisma.scanStation.deleteMany();
  await prisma.trackContract.deleteMany();
  await prisma.trackEvent.deleteMany();
  await prisma.trackPhoto.deleteMany();
  await prisma.track.deleteMany();
  await prisma.season.deleteMany();
  await prisma.session.deleteMany();
  await prisma.user.deleteMany();
}

async function main() {
  console.log('Wiping existing data...');
  await wipe();

  // ---- Season ----
  const season = await prisma.season.create({
    data: { year: SEASON_YEAR, ...seasonBounds, isActive: true },
  });

  // ---- Tiers ----
  const tiers: Record<string, { id: string; priceCents: number; extraDaysPerTrack: number }> = {};
  for (const t of tierSeed) {
    const tier = await prisma.passTier.create({ data: t });
    tiers[t.slug] = { id: tier.id, priceCents: tier.priceCents, extraDaysPerTrack: tier.extraDaysPerTrack };
  }

  // ---- Tracks + contracts + stations ----
  const tracks: Record<string, { id: string; name: string }> = {};
  const stations: Record<string, string> = {};
  for (const t of trackSeed) {
    const { contract, ...trackData } = t;
    const track = await prisma.track.create({
      data: {
        ...trackData,
        // The venue's week, as JSON — see seed/hoursWeek.ts. A venue with no
        // week on file keeps `hoursWeek` null and its profile shows the single
        // summary line instead of a week.
        hoursWeek: hoursWeekSeed[t.slug] ? JSON.stringify(hoursWeekSeed[t.slug]) : null,
        contracts: { create: { seasonId: season.id, ...contract } },
        stations: {
          create: { name: 'Ticket Window', apiKey: `stn_${t.slug.replace(/[^a-z0-9]+/g, '_')}_ticket` },
        },
      },
      include: { stations: true },
    });
    tracks[t.slug] = { id: track.id, name: track.name };
    stations[t.slug] = track.stations[0].id;

    // The venue's gallery — the photographs its profile page opens with. An
    // owner adds or reorders from the console; these are just the starting set.
    const photos = trackPhotoSeed[t.slug] ?? [];
    for (const [i, p] of photos.entries()) {
      await prisma.trackPhoto.create({
        data: {
          trackId: track.id,
          url: `/tracks/photos/${t.slug}/${p.file}`,
          category: p.category,
          caption: p.caption ?? null,
          sortOrder: i,
        },
      });
    }
  }

  // ---- Track profile events ----
  // The dated half of a venue profile. Only the venues with a seeded schedule
  // get rows; the rest show the empty state until their owner adds one.
  // Stored at noon UTC so the day never slips across a timezone; the hours a
  // date runs are kept separately as minutes past midnight on that day, so a
  // date is timed or all-day without either reading the other's clock.
  const atNoon = (d: Date) => new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate(), 12));
  for (const e of trackEventSeed) {
    const track = tracks[e.trackSlug];
    if (!track) continue;
    const hours = hoursFor(e);
    await prisma.trackEvent.create({
      data: {
        trackId: track.id,
        title: e.title,
        description: e.description ?? null,
        kind: e.kind,
        startsAt: atNoon(daysAhead(e.inDays)),
        endsAt: e.days ? atNoon(daysAhead(e.inDays + e.days - 1)) : null,
        ...hours,
      },
    });
  }

  // ---- Users ----
  const passwordHash = await hashPassword(DEFAULT_PASSWORD);
  const users: Record<string, { id: string; name: string }> = {};
  for (const u of userSeed) {
    const user = await prisma.user.create({
      data: {
        name: u.name,
        email: u.email,
        role: u.role,
        passwordHash,
        location: u.location ?? null,
        phone: u.phone ?? null,
        avatarUrl: `/avatars/${u.key}.svg`,
        operatorTrackId: u.trackSlug ? tracks[u.trackSlug].id : null,
      },
    });
    users[u.key] = { id: user.id, name: user.name };
  }

  // ---- Passes ----
  const passes: Record<string, { id: string; expiresAt: Date }> = {};
  for (const u of userSeed) {
    if (u.role !== Role.RIDER) continue;
    const tier = tiers[u.tier!];

    if (u.expired) {
      // A previous-season pass, already expired.
      const prevYear = SEASON_YEAR - 1;
      const pass = await prisma.pass.create({
        data: {
          userId: users[u.key].id,
          tierId: tier.id,
          seasonId: season.id,
          seasonYear: prevYear,
          status: PassStatus.EXPIRED,
          activatedAt: new Date(Date.UTC(prevYear, 0, 15)),
          expiresAt: new Date(Date.UTC(prevYear, 11, 31, 23, 59, 59)),
        },
      });
      passes[u.key] = { id: pass.id, expiresAt: pass.expiresAt };
      await prisma.payment.create({
        data: {
          userId: users[u.key].id,
          passId: pass.id,
          tierId: tier.id,
          amountCents: tier.priceCents,
          status: PaymentStatus.PAID,
          createdAt: new Date(Date.UTC(prevYear, 0, 15)),
        },
      });
      continue;
    }

    const pass = await prisma.pass.create({
      data: {
        userId: users[u.key].id,
        tierId: tier.id,
        seasonId: season.id,
        seasonYear: SEASON_YEAR,
        status: PassStatus.PENDING,
        expiresAt: seasonBounds.endsAt,
      },
    });
    await prisma.payment.create({
      data: {
        userId: users[u.key].id,
        passId: pass.id,
        tierId: tier.id,
        amountCents: tier.priceCents,
        status: PaymentStatus.PAID,
      },
    });
    const activated = await activatePass(pass.id);
    passes[u.key] = { id: activated.id, expiresAt: activated.expiresAt };
  }

  // ---- Perks ----
  for (const p of perkSeed) {
    const { tierSlug, ...rest } = p;
    await prisma.perk.create({
      data: { ...rest, tierId: tierSlug ? tiers[tierSlug].id : null },
    });
  }

  // ---- Riders' reviews (the venue pages' community wall) ----
  // The venue's own photos above stand in as the frame each rider attached, so
  // the wall is not empty on a fresh seed. One review per rider per venue — the
  // seed must not repeat a userKey for the same trackSlug. See
  // seed/trackReviews.ts.
  for (const r of trackReviewSeed) {
    const track = tracks[r.trackSlug];
    const user = users[r.userKey];
    const file = trackPhotoSeed[r.trackSlug]?.[r.photoIndex]?.file;
    if (!track || !user || !file) continue;
    // Written on different days back through the season, so the wall does not
    // read as one batch created by the seed run.
    const writtenAt = new Date(Date.now() - r.daysAgo * 24 * 60 * 60 * 1000);
    await prisma.trackReview.create({
      data: {
        trackId: track.id,
        userId: user.id,
        rating: r.rating,
        body: r.body,
        createdAt: writtenAt,
        updatedAt: writtenAt,
        photos: {
          create: [{ url: `/tracks/photos/${r.trackSlug}/${file}`, sortOrder: 0 }],
        },
      },
    });
  }

  // ---- Follows (the free tier's surface) ----
  for (const f of followSeed) {
    await prisma.trackFollow.create({
      data: { userId: users[f.key].id, trackId: tracks[f.trackSlug].id },
    });
  }

  // ---- Activity ----
  await seedActivity({
    prisma,
    seasonId: season.id,
    seasonYear: SEASON_YEAR,
    tracks,
    stations,
    users,
    passes,
  });

  // ---- Summary ----
  const counts = {
    season: await prisma.season.count(),
    tracks: await prisma.track.count(),
    contracts: await prisma.trackContract.count(),
    photos: await prisma.trackPhoto.count(),
    reviews: await prisma.trackReview.count(),
    tiers: await prisma.passTier.count(),
    users: await prisma.user.count(),
    passes: await prisma.pass.count(),
    allotments: await prisma.allotment.count(),
    follows: await prisma.trackFollow.count(),
    reservations: await prisma.reservation.count(),
    redemptions: await prisma.redemption.count(),
    scanEvents: await prisma.scanEvent.count(),
    perks: await prisma.perk.count(),
    payments: await prisma.payment.count(),
  };
  console.log('Seed complete:', counts);
  console.log(`\nAll seeded accounts use the password: ${DEFAULT_PASSWORD}`);
  console.log('  Rider   : quinn@example.com (Free — follows three tracks)');
  console.log('  Rider   : alex@example.com (Moto Pass)');
  console.log('  Rider   : jordan@example.com (Moto Pass — mid-season, reservation on file)');
  console.log('  Rider   : sam@example.com (Moto Pass — out of days at 221 MX)');
  console.log('  Rider   : riley@example.com (Moto Pass — reservations on file)');
  console.log('  Rider   : taylor@example.com (Moto Pass)');
  console.log('  Rider   : casey@example.com (Moto Pass)');
  console.log('  Rider   : morgan@example.com (Expired pass)');
  console.log('  Operator: ops@221mx.example.com');
  console.log('  Operator: ops@eastbend.example.com');
  console.log('  Operator: ops@sobmx.example.com');
  console.log('  Admin   : admin@motopass.example.com');
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });

import { PrismaClient } from '@prisma/client';
import { RedemptionKind, ReservationStatus, ScanResult } from '../../src/types/enums';
import { dayKey, daysAgo, daysAhead } from './helpers';

interface Ctx {
  prisma: PrismaClient;
  seasonId: string;
  seasonYear: number;
  tracks: Record<string, { id: string; name: string }>;
  stations: Record<string, string>; // trackSlug -> stationId
  users: Record<string, { id: string; name: string }>;
  passes: Record<string, { id: string; expiresAt: Date }>;
}

/** A gate entry at `hour` on the given day. The operator's hourly read and the
    activity log both print on the venue's own clock, so the seed builds the
    timestamp in local time and the two agree. Riders arrive in the morning, so
    the ledger carries a real hour rather than midnight. */
function at(day: Date, hour: number): Date {
  return new Date(day.getUTCFullYear(), day.getUTCMonth(), day.getUTCDate(), hour, 0, 0, 0);
}

/** Seed a believable slice of reservations, redemptions, denials and payments. */
export async function seedActivity(ctx: Ctx) {
  const { prisma, tracks, stations, users, passes, seasonYear } = ctx;

  const trackId = (slug: string) => tracks[slug].id;
  const passId = (key: string) => passes[key].id;
  const userId = (key: string) => users[key].id;

  // ---- Reservations -------------------------------------------------------
  const reservations = [
    { user: 'jordan', track: 'east-bend-motorsports', date: daysAhead(4), status: ReservationStatus.CONFIRMED, consumed: true },
    { user: 'jordan', track: 'top-gun-mx', date: daysAhead(11), status: ReservationStatus.CONFIRMED, consumed: false },
    { user: 'riley', track: 'sobmx', date: daysAhead(2), status: ReservationStatus.CONFIRMED, consumed: true },
    { user: 'alex', track: 'top-gun-mx', date: daysAhead(6), status: ReservationStatus.CONFIRMED, consumed: false },
    { user: 'sam', track: 'east-bend-motorsports', date: daysAgo(9), status: ReservationStatus.COMPLETED, consumed: true },
    { user: 'sam', track: 'sobmx', date: daysAgo(3), status: ReservationStatus.CANCELLED, consumed: false },
    { user: 'priya', track: 'budds-creek-motocross-park', date: daysAhead(5), status: ReservationStatus.CONFIRMED, consumed: false },
  ];

  const createdReservations: Record<string, string> = {};
  for (const r of reservations) {
    const rec = await prisma.reservation.create({
      data: {
        userId: userId(r.user),
        trackId: trackId(r.track),
        passId: passId(r.user),
        date: dayKey(r.date),
        status: r.status,
        dayConsumed: r.consumed,
        dayConsumedAt: r.consumed ? r.date : null,
      },
    });
    createdReservations[`${r.user}:${r.track}:${r.date.toISOString().slice(0, 10)}`] = rec.id;
  }

  // ---- Redemptions (each one decrements the right track's allotment) ------
  const redemptions = [
    // Today's gate: Alex's third day at 221 MX (the half-price day), then Taylor.
    { user: 'alex', track: '221-mx', day: daysAgo(0), kind: RedemptionKind.DISCOUNT, amount: 2750, hour: 8 },
    { user: 'taylor', track: '221-mx', day: daysAgo(0), kind: RedemptionKind.FREE, amount: 0, hour: 10 },
    { user: 'alex', track: '221-mx', day: daysAgo(21), kind: RedemptionKind.FREE, amount: 0, hour: 9 },
    { user: 'alex', track: '221-mx', day: daysAgo(7), kind: RedemptionKind.FREE, amount: 0, hour: 9 },
    { user: 'alex', track: 'brushy-mountain-motor-sports-park', day: daysAgo(14), kind: RedemptionKind.FREE, amount: 0, hour: 10 },
    { user: 'jordan', track: 'east-bend-motorsports', day: daysAgo(9), kind: RedemptionKind.FREE, amount: 0, hour: 8 },
    { user: 'jordan', track: '221-mx', day: daysAgo(12), kind: RedemptionKind.FREE, amount: 0, hour: 8 },
    { user: 'jordan', track: '221-mx', day: daysAgo(5), kind: RedemptionKind.DISCOUNT, amount: 2750, hour: 10 },
    { user: 'riley', track: 'sobmx', day: daysAgo(4), kind: RedemptionKind.FREE, amount: 0, hour: 9 },
    { user: 'riley', track: 'brushy-mountain-motor-sports-park', day: daysAgo(18), kind: RedemptionKind.FREE, amount: 0, hour: 13 },
    { user: 'riley', track: 'top-gun-mx', day: daysAgo(2), kind: RedemptionKind.FREE, amount: 0, hour: 8 },
    { user: 'sam', track: 'east-bend-motorsports', day: daysAgo(9), kind: RedemptionKind.FREE, amount: 0, hour: 7 },
    { user: 'sam', track: '221-mx', day: daysAgo(3), kind: RedemptionKind.FREE, amount: 0, hour: 9 },
    { user: 'sam', track: '221-mx', day: daysAgo(2), kind: RedemptionKind.FREE, amount: 0, hour: 9 },
    // Sam has now used every free day AND the discounted extra day at 221 MX.
    { user: 'sam', track: '221-mx', day: daysAgo(1), kind: RedemptionKind.DISCOUNT, amount: 2750, hour: 8 },
    { user: 'taylor', track: 'unadilla-mx', day: daysAgo(6), kind: RedemptionKind.FREE, amount: 0, hour: 8 },
    { user: 'taylor', track: 'redbud-mx', day: daysAgo(13), kind: RedemptionKind.DISCOUNT, amount: 2400, hour: 14 },
    // The newer paid accounts: days actually ridden, on their own local venues.
    { user: 'devon', track: '221-mx', day: daysAgo(11), kind: RedemptionKind.FREE, amount: 0, hour: 9 },
    { user: 'devon', track: 'top-gun-mx', day: daysAgo(4), kind: RedemptionKind.FREE, amount: 0, hour: 8 },
    { user: 'harper', track: 'redbud-mx', day: daysAgo(5), kind: RedemptionKind.FREE, amount: 0, hour: 8 },
    { user: 'marcus', track: 'washougal-mx-park', day: daysAgo(8), kind: RedemptionKind.FREE, amount: 0, hour: 7 },
    { user: 'elena', track: 'glen-helen-raceway', day: daysAgo(9), kind: RedemptionKind.FREE, amount: 0, hour: 8 },
    { user: 'theo', track: 'austin-motocross-park', day: daysAgo(7), kind: RedemptionKind.FREE, amount: 0, hour: 9 },
    { user: 'priya', track: 'the-wick-338', day: daysAgo(12), kind: RedemptionKind.FREE, amount: 0, hour: 10 },
  ];

  for (const r of redemptions) {
    const day = dayKey(r.day);
    await prisma.redemption.create({
      data: {
        userId: userId(r.user),
        passId: passId(r.user),
        trackId: trackId(r.track),
        stationId: stations[r.track],
        kind: r.kind,
        day,
        redeemedAt: at(day, r.hour),
        amountChargedCents: r.amount,
      },
    });

    if (r.kind === RedemptionKind.FREE) {
      await prisma.allotment.updateMany({
        where: { userId: userId(r.user), trackId: trackId(r.track), seasonYear },
        data: { freeDaysUsed: { increment: 1 } },
      });
    } else if (r.kind === RedemptionKind.DISCOUNT) {
      await prisma.allotment.updateMany({
        where: { userId: userId(r.user), trackId: trackId(r.track), seasonYear },
        data: { discountDaysUsed: { increment: 1 } },
      });
    }

    await prisma.scanEvent.create({
      data: {
        trackId: trackId(r.track),
        stationId: stations[r.track],
        passId: passId(r.user),
        userId: userId(r.user),
        riderName: users[r.user].name,
        result: ScanResult.APPROVED,
        reasonCode: r.kind === RedemptionKind.DISCOUNT ? 'APPROVED_DISCOUNT' : 'APPROVED',
        reason: r.kind === RedemptionKind.DISCOUNT ? 'Approved: discounted extra day.' : 'Approved.',
        kind: r.kind,
        amountChargedCents: r.amount,
        createdAt: at(day, r.hour),
      },
    });
  }

  // ---- Denied scans (each with a distinct, correct reason) ---------------
  const denials = [
    {
      user: 'sam',
      track: '221-mx',
      reasonCode: 'NO_DAYS_REMAINING',
      reason: `No days remaining at ${tracks['221-mx'].name} this season.`,
      day: daysAgo(0),
      hour: 9,
    },
    {
      user: 'sam',
      track: '221-mx',
      reasonCode: 'ALREADY_USED_TODAY',
      reason: 'Pass already used today at this track.',
      day: daysAgo(0),
      hour: 11,
    },
    {
      user: 'morgan',
      track: 'east-bend-motorsports',
      reasonCode: 'PASS_EXPIRED',
      reason: 'Pass expired. Renew to ride this season.',
      day: daysAgo(1),
      hour: 8,
    },
    {
      user: 'alex',
      track: 'east-bend-motorsports',
      reasonCode: 'RESERVATION_REQUIRED',
      reason: 'This track requires a reservation for today. Book in the rider portal.',
      day: daysAgo(2),
      hour: 8,
    },
  ];

  for (const d of denials) {
    await prisma.scanEvent.create({
      data: {
        trackId: trackId(d.track),
        stationId: stations[d.track],
        passId: passes[d.user]?.id,
        userId: userId(d.user),
        riderName: users[d.user].name,
        result: ScanResult.DENIED,
        reasonCode: d.reasonCode,
        reason: d.reason,
        createdAt: at(dayKey(d.day), d.hour),
      },
    });
  }
}

import { PrismaClient } from '@prisma/client';

export const prisma = new PrismaClient();

/** A date-only ride day, as UTC midnight. Reads UTC components, so it names an
    existing instant — never call it for "today". */
export function dayKey(d: Date | string): Date {
  const date = typeof d === 'string' ? new Date(d) : d;
  return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()));
}

/** Today on the venue's own clock, as a UTC-midnight day key, so the demo rows
    line up with the gate (whose day rolls over at local midnight). */
export function todayKey(): Date {
  const now = new Date();
  return new Date(Date.UTC(now.getFullYear(), now.getMonth(), now.getDate()));
}

export function daysAgo(n: number): Date {
  const d = todayKey();
  d.setUTCDate(d.getUTCDate() - n);
  return d;
}

export function daysAhead(n: number): Date {
  const d = todayKey();
  d.setUTCDate(d.getUTCDate() + n);
  return d;
}

export const SEASON_YEAR = new Date().getUTCFullYear();

export const seasonBounds = {
  startsAt: new Date(Date.UTC(SEASON_YEAR, 0, 1)),
  endsAt: new Date(Date.UTC(SEASON_YEAR, 11, 31, 23, 59, 59)),
};

/**
 * The venue's regular week — the seven days behind its `hours` line.
 *
 * `hours` on a track row is one summary line ("Practice 9am–4pm"), which is what
 * the network rail and the panel read. The venue profile's Hours card lays out a
 * whole week, so each venue needs a per-day line: this table is that week.
 *
 * A venue's own `hours` string is the value on every day it runs, and `Closed`
 * goes on the days it does not. The pattern (weekend-only practice, midweek-plus,
 * or open every day) is the demo's own read of how a park of that kind runs —
 * nothing here is scraped — so keep it consistent with the row's `hours` line and
 * with its `status` / `statusNote`: a venue seeded CLOSED mid-week must actually
 * be Closed on those days.
 */
export type HoursWeek = {
  mon: string;
  tue: string;
  wed: string;
  thu: string;
  fri: string;
  sat: string;
  sun: string;
};

const CLOSED = 'Closed';

/** Open Friday–Sunday: the weekend-practice venues. */
const WEEKEND = ['fri', 'sat', 'sun'];
/** Open Wednesday–Sunday: venues that also run a midweek practice day. */
const MIDWEEK = ['wed', 'thu', 'fri', 'sat', 'sun'];
/** Open every day: venues that run seven days. */
const DAILY = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];

/** The venue's line on each day it runs, `Closed` on the rest. */
const week = (days: string[], hours: string): HoursWeek => {
  const day = (d: string) => (days.includes(d) ? hours : CLOSED);
  return {
    mon: day('mon'),
    tue: day('tue'),
    wed: day('wed'),
    thu: day('thu'),
    fri: day('fri'),
    sat: day('sat'),
    sun: day('sun'),
  };
};

export const hoursWeekSeed: Record<string, HoursWeek> = {
  // --- The original seven ---------------------------------------------------
  // 221 MX runs practice on the weekend around its race series.
  '221-mx': week(WEEKEND, 'Practice 9am–4pm'),
  'east-bend-motorsports': week(MIDWEEK, 'Practice 8am–3pm'),
  'top-gun-mx': week(MIDWEEK, 'Practice 9am–5pm'),
  'brushy-mountain-motor-sports-park': week(MIDWEEK, '8am–6pm'),
  sobmx: week(WEEKEND, 'Practice 9am–4pm'),

  // --- The later seed expansion --------------------------------------------
  'glen-helen-raceway': week(MIDWEEK, 'Practice 8am–4pm'),
  'washougal-mx-park': week(MIDWEEK, 'Practice 9am–4pm'),
  'thunder-valley-motocross-park': week(MIDWEEK, 'Practice 9am–5pm'),
  // Arizona runs its summer gate early, before the heat.
  'arizona-cycle-park': week(MIDWEEK, 'Practice 7am–2pm'),
  'moriarty-motocross': week(WEEKEND, 'Practice 9am–4pm'),
  'austin-motocross-park': week(MIDWEEK, 'Practice 8am–3pm'),
  'redbud-mx': week(WEEKEND, 'Practice 9am–4pm'),
