/**
 * The hours a kind runs when an entry names none of its own. Gates open before
 * racing and a clinic is a half day, so the window follows the kind; an `OTHER`
 * date carries none at all and reads in the all-day row, which is what a
 * booked-out venue is: shut all day, not on a schedule.
 */
export const KIND_HOURS: Record<TrackEventKind, [string, string] | null> = {
  PRACTICE: ['09:00', '16:00'],
  RACE: ['07:00', '17:00'],
  CLINIC: ['10:00', '14:00'],
  RIDE_DAY: ['09:00', '15:00'],
  OTHER: null,
};

/** `HH:MM` as minutes past midnight — how a date's hours are stored. */
export function toMinutes(hhmm: string) {
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

/** The window a seeded date runs: its own hours, else its kind's, else all-day. */
export function hoursFor(e: { kind: TrackEventKind; from?: string; to?: string }) {
  const own = e.from && e.to ? ([e.from, e.to] as [string, string]) : KIND_HOURS[e.kind];
  return own
    ? { startMinutes: toMinutes(own[0]), endMinutes: toMinutes(own[1]) }
    : { startMinutes: null, endMinutes: null };
}

/* eslint-disable no-console */
/**
 * End-to-end acceptance check against the running API (localhost:4010).
 * Exercises every acceptance criterion with real HTTP calls.
 */
import { issueQrToken } from '../src/utils/qr';
import { prisma } from '../src/utils/prisma';

const BASE = 'http://localhost:4010/api';
const PASSWORD = 'dialed123';

/**
 * A date-only key on the venue's own clock. `toISOString()` is UTC, so after
 * 8 PM Eastern it names tomorrow — which made the reservation and day-status
 * sections fail every evening (see `references/gate-day-is-the-venue-day.md`).
 */
const localDay = (d: Date = new Date()) =>
  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

let passCount = 0;
let failCount = 0;

function check(label: string, ok: boolean, detail = '') {
  if (ok) {
    passCount++;
    console.log(`  PASS  ${label}${detail ? ` — ${detail}` : ''}`);
  } else {
    failCount++;
    console.log(`  FAIL  ${label}${detail ? ` — ${detail}` : ''}`);
  }
}

class Client {
  cookie = '';
  async call<T = any>(path: string, method = 'GET', body?: unknown): Promise<T> {
    const res = await fetch(`${BASE}${path}`, {
      method,
      headers: {
        'Content-Type': 'application/json',
        ...(this.cookie ? { Cookie: this.cookie } : {}),
      },
      body: body ? JSON.stringify(body) : undefined,
    });
    const setCookie = res.headers.getSetCookie?.() ?? [];
    for (const c of setCookie) {
      const [pair] = c.split(';');
      if (pair.startsWith('moto_sid=')) this.cookie = pair;
    }
    return (await res.json()) as T;
  }
  async login(email: string) {
    const r = await this.call('/auth/login', 'POST', { email, password: PASSWORD });
    if (!r.success) throw new Error(`login failed for ${email}: ${r.message}`);
    return r;
  }
}

async function main() {
  console.log('\n=== Moto Pass — acceptance run ===\n');

  const rider = new Client();
  const mx221Op = new Client();
  const eastBendOp = new Client();
  const admin = new Client();

  await mx221Op.login('ops@221mx.example.com');
  await eastBendOp.login('ops@eastbend.example.com');
  await admin.login('admin@motopass.example.com');

  // ---------------------------------------------------------------------
  console.log('1. Rider buys a pass, gets a QR');
  const email = `acceptance_${Date.now()}@example.com`;
  const reg = await rider.call('/auth/register', 'POST', {
    name: 'Acceptance Rider',
    email,
    password: 'testpass123',
  });
  check('register rider', reg.success, email);

  // ---------------------------------------------------------------------
  console.log('\n1b. A new account is on the free tier: the network, not a ride');
  const freePass = await rider.call('/me/pass');
  check(
    'a new account lands on the free tier',
    freePass.data?.pass?.tier?.slug === 'free' && freePass.data?.pass?.gated === true,
    freePass.data?.pass?.tier?.name
  );
  check(
    'the free pass snapshots no per-track days',
    freePass.data.entitlements.length === 0,
    `${freePass.data.entitlements.length} entitlements`
  );

  const freeNetwork = await rider.call('/tracks');
  check('the network flags the viewer as gated', freeNetwork.data.gated === true);
  check(
    'the contract terms are withheld server-side, not just hidden',
    freeNetwork.data.tracks.length > 0 &&
      freeNetwork.data.tracks.every((t: any) => t.includedDays === null && t.discountRate === null),
    `${freeNetwork.data.tracks.length} tracks`
  );
  check(
    'the free rider still gets the venue status',
    freeNetwork.data.tracks.every((t: any) => typeof t.status === 'string' && t.status.length > 0)
  );

  // The live network size — every count below is read off it, so the suite
  // holds as partner venues are added or dropped.
  const NET = freeNetwork.data.tracks.length;

  const mx221 = freeNetwork.data.tracks.find((t: any) => t.slug === '221-mx');
  const follow = await rider.call(`/me/follows/${mx221.id}`, 'POST');
  check('a free rider can follow a track', follow.success && follow.data.following === true, follow.message);
  const follows = await rider.call('/me/follows');
  check(
    'the follow lands on the follows list',
    follows.data.follows.length === 1 && follows.data.follows[0].slug === '221-mx',
    follows.data.follows.map((f: any) => f.slug).join(',')
  );
  const unfollow = await rider.call(`/me/follows/${mx221.id}`, 'DELETE');
  check('and can stop following it', unfollow.success && unfollow.data.following === false, unfollow.message);

  const freeQr = await rider.call('/me/qr-token');
  const freeScan = await mx221Op.call('/operator/scan', 'POST', { token: freeQr.data.token });
  check(
    'a free pass cannot ride — the scan is refused',
    freeScan.data?.reasonCode === 'TRACK_NOT_PARTICIPATING',
    freeScan.data?.reason
  );

  const tiers = await rider.call('/tiers');
  const base = tiers.data.tiers.find((t: any) => t.slug === 'base');
  check('base tier available', Boolean(base), base?.name);

  const checkout = await rider.call('/payments/checkout', 'POST', { tierId: base.id });
  check('checkout created', checkout.success && Boolean(checkout.data?.paymentId), checkout.data?.devMode ? 'dev mode (placeholder Stripe keys)' : 'live session');

  const sim = await rider.call(`/payments/dev/simulate/${checkout.data.paymentId}`, 'POST');
  check('payment round-trips → pass activated', sim.success && sim.data?.pass?.status === 'ACTIVE', sim.message);

  const myPass = await rider.call('/me/pass');
  check('pass has per-track entitlements', myPass.data.entitlements.length === NET, `${myPass.data.entitlements.length} of ${NET} tracks`);
  check(
    'the bought pass supersedes the free one',
    myPass.data.pass.tier.slug === 'base' && myPass.data.pass.gated === false,
    myPass.data.pass.tier.name
  );

  const qr = await rider.call('/me/qr-token');
  check('QR token issued', qr.success && qr.data.token.includes('.'), `nonce ${qr.data?.nonce?.slice(0, 8)}…`);

  // ---------------------------------------------------------------------
  console.log('\n2. Track scan succeeds and decrements the right track');
  const before = myPass.data.entitlements.find((e: any) => e.trackSlug === '221-mx');
  const scan1 = await mx221Op.call('/operator/scan', 'POST', { token: qr.data.token });
  check('scan APPROVED', scan1.data?.approved === true, scan1.data?.reason);
  check(
    '221 MX remaining decremented',
    scan1.data?.remainingFreeDays === before.freeDaysRemaining - 1,
    `${before.freeDaysRemaining} → ${scan1.data?.remainingFreeDays}`
  );

  const afterPass = await rider.call('/me/pass');
  const after = afterPass.data.entitlements.find((e: any) => e.trackSlug === '221-mx');
  check('ledger persisted', after.freeDaysUsed === before.freeDaysUsed + 1, `used ${after.freeDaysUsed}`);
  const other = afterPass.data.entitlements.find((e: any) => e.trackSlug === 'east-bend-motorsports');
  check('other tracks untouched', other.freeDaysUsed === 0, `East Bend used ${other.freeDaysUsed}`);

  // ---------------------------------------------------------------------
  console.log('\n3. Blocked scans show the correct reason');
  const qr2 = await rider.call('/me/qr-token');
  const dup = await mx221Op.call('/operator/scan', 'POST', { token: qr2.data.token });
  check('same-day rescan blocked', dup.data?.reasonCode === 'ALREADY_USED_TODAY', dup.data?.reason);

  // The gate's other way in for that same rider: a logged re-entry. Nothing
  // is spent — the day went at the first scan — so the allotment stands.
  const riderRow = await prisma.user.findFirst({ where: { email } });
  const reentry = await mx221Op.call('/operator/reenter', 'POST', { riderId: riderRow!.id });
  check(
    'same-day re-entry approved',
    reentry.data?.approved === true && reentry.data?.reasonCode === 'RE_ENTRY',
    reentry.data?.reason
  );
  const afterReentry = await rider.call('/me/pass');
  const reent = afterReentry.data.entitlements.find((e: any) => e.trackSlug === '221-mx');
  check('re-entry spends no day', reent.freeDaysUsed === after.freeDaysUsed, `used ${reent.freeDaysUsed}`);

  const sam = new Client();
  await sam.login('sam@example.com');
  const samQr = await sam.call('/me/qr-token');
  const outOfDays = await mx221Op.call('/operator/scan', 'POST', { token: samQr.data.token });
  check('out-of-days blocked', outOfDays.data?.reasonCode === 'NO_DAYS_REMAINING', outOfDays.data?.reason);

  const morganPass = await prisma.pass.findFirst({
    where: { user: { email: 'morgan@example.com' } },
  });
  const expiredToken = issueQrToken(morganPass!.id, morganPass!.userId).token;
  const expired = await mx221Op.call('/operator/scan', 'POST', { token: expiredToken });
  check('expired pass blocked', expired.data?.reasonCode === 'PASS_EXPIRED', expired.data?.reason);

  const forged = await mx221Op.call('/operator/scan', 'POST', {
    token: `${expiredToken.split('.')[0]}.deadbeef`,
  });
  check('forged signature rejected', forged.data?.reasonCode === 'BAD_SIGNATURE', forged.data?.reason);

  const staleToken = issueQrToken(morganPass!.id, morganPass!.userId, -10).token;
  const stale = await mx221Op.call('/operator/scan', 'POST', { token: staleToken });
  check('replayed/expired QR token rejected', stale.data?.reasonCode === 'EXPIRED', stale.data?.reason);

  const crossTrack = await eastBendOp.call('/operator/scan', 'POST', { token: qr2.data.token });
  check('reservation-required track blocks walk-up', crossTrack.data?.reasonCode === 'RESERVATION_REQUIRED', crossTrack.data?.reason);

  // ---------------------------------------------------------------------
  console.log('\n3b. The network is motocross only, and one pass covers all of it');
  const network = await rider.call('/tracks');
  check(
    'every venue in the network is an MX track',
    network.data.tracks.length > 0 && network.data.tracks.every((t: any) => t.category === 'MX'),
    `${network.data.tracks.length} tracks`
  );
  check(
    'the network carries 25 or more tracks',
    network.data.tracks.length >= 25,
    `${network.data.tracks.length} tracks`
  );
  check(
    'only one tier is sold, alongside the free tier',
    (await rider.call('/tiers')).data.tiers.filter((t: any) => !t.isDefault).length === 1
  );

  const taylor = new Client();
  await taylor.login('taylor@example.com');
  const taylorPass = await taylor.call('/me/pass');
  check(
    'the pass covers every venue in the network',
    taylorPass.data.entitlements.length === network.data.tracks.length,
    `${taylorPass.data.entitlements.length} venues`
  );

  // ---------------------------------------------------------------------
  console.log('\n4. Reservation is honored at check-in');
  const today = localDay();
  const eastBend = afterPass.data.entitlements.find((e: any) => e.trackSlug === 'east-bend-motorsports');
  const resv = await rider.call('/me/reservations', 'POST', { trackId: eastBend.trackId, date: today });
  check('reservation confirmed', resv.success && resv.data?.reservation?.status === 'CONFIRMED', resv.data?.message);
  check('day deducted at confirm (ON_CONFIRM policy)', resv.data?.dayConsumed === true, `dayConsumed=${resv.data?.dayConsumed}`);

  const qr3 = await rider.call('/me/qr-token');
  const honored = await eastBendOp.call('/operator/scan', 'POST', { token: qr3.data.token });
  check('reserved day honored at scan', honored.data?.approved === true, honored.data?.reason);
  check(
    'no double-decrement on check-in',
    honored.data?.remainingFreeDays === eastBend.freeDaysRemaining - 1,
    `${eastBend.freeDaysRemaining} → ${honored.data?.remainingFreeDays}`
  );

  // cancel/reschedule
  const resv2 = await rider.call('/me/reservations', 'POST', {
    trackId: eastBend.trackId,
    date: localDay(new Date(Date.now() + 5 * 864e5)),
  });
  const moved = await rider.call(`/me/reservations/${resv2.data.reservation.id}/reschedule`, 'POST', {
    date: localDay(new Date(Date.now() + 9 * 864e5)),
  });
  check('reservation reschedule works', moved.success, moved.message);
  const cancelled = await rider.call(`/me/reservations/${resv2.data.reservation.id}/cancel`, 'POST');
  check('reservation cancel works', cancelled.success, cancelled.message);

  // ---------------------------------------------------------------------
  console.log('\n5. Admin edits a contract and sees reports');
  const seasons = await admin.call('/admin/seasons');
  const seasonId = seasons.data.seasons[0].id;
  const before2 = await admin.call('/admin/tracks');
  const eastBendTrack = before2.data.tracks.find((t: any) => t.slug === 'east-bend-motorsports');
  const contract = await admin.call(`/admin/tracks/${eastBendTrack.id}/contract`, 'PUT', {
    seasonId,
    includedDays: 3,
    discountDayEnabled: true,
    discountDayNumber: 4,
    discountRate: 0.4,
    discountDaysAllowed: 2,
    extraDayPriceCents: 7000,
    reservationRequired: false,
    dayConsumePolicy: 'ON_CHECKIN',
    isActive: true,
    notes: 'Acceptance edit',
  });
  check('contract updated', contract.success && contract.data.contract.includedDays === 3, `included=${contract.data?.contract?.includedDays}, rate=${contract.data?.contract?.discountRate}`);

  const reports = await admin.call('/admin/reports');
  check('reports return per-track redemptions', Array.isArray(reports.data.perTrack) && reports.data.perTrack.length === NET, `${reports.data.totals.redemptions} redemptions total`);
  check('reports include revenue', typeof reports.data.totals.revenueCents === 'number', `$${(reports.data.totals.revenueCents / 100).toFixed(2)}`);

  // ---------------------------------------------------------------------
  console.log('\n6. Only the free and the paid tier exist');
  const tierList = (await rider.call('/tiers')).data.tiers;
  check(
    'the tier list carries exactly the free and the paid tier',
    tierList.length === 2 && tierList.filter((t: any) => t.isDefault).length === 1,
    tierList.map((t: any) => t.slug).join(' ')
  );

  // ---------------------------------------------------------------------
  console.log('\n7. QuickBooks export is importable');
  const manifest = await admin.call('/admin/quickbooks/manifest');
  check('manifest lists 3 exports', manifest.data.exports.length === 3, manifest.data.exports.map((e: any) => `${e.kind}:${e.rowCount}`).join(' '));

  const csvRes = await fetch(`${BASE}/admin/quickbooks/export?type=payments&format=csv`, {
    headers: { Cookie: admin.cookie },
  });
  const csv = await csvRes.text();
  const lines = csv.trim().split(/\r?\n/);
  check('payments CSV has header + rows', lines.length > 1 && lines[0].includes('Customer Name'), `${lines.length - 1} rows`);
  check('CSV column count consistent', new Set(lines.map((l) => l.split(',').length)).size === 1, `${lines[0].split(',').length} columns`);

  // ---------------------------------------------------------------------
  console.log('\n8. Security & ops');
  const anon = await fetch(`${BASE}/admin/reports`);
  check('admin route rejects anonymous', anon.status === 401, `HTTP ${anon.status}`);
  const riderToAdmin = await rider.call('/admin/reports');
  check('rider cannot reach admin routes', riderToAdmin.success === false, riderToAdmin.message);
  const riderToScan = await rider.call('/operator/scan', 'POST', { token: qr3.data.token });
  check('rider cannot use the scanner', riderToScan.success === false, riderToScan.message);

  const webhookNoSig = await fetch(`${BASE}/payments/webhook`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ type: 'checkout.session.completed' }),
  });
  check('stripe webhook refuses unsigned payloads', [400, 503].includes(webhookNoSig.status), `HTTP ${webhookNoSig.status}`);

  // ---------------------------------------------------------------------
  console.log('\n9. Operator posts the gate per day');
  const todayStr = localDay();
  const tomorrowD = new Date();
  tomorrowD.setDate(tomorrowD.getDate() + 1);
  const tomorrowStr = localDay(tomorrowD);
  // The live line before this section — restored at the end, whatever the seed holds.
  const beforeGate = (await rider.call('/tracks/221-mx')).data?.track;
  const postTomorrow = await mx221Op.call('/owner/track/day-status', 'POST', {
    day: tomorrowStr,
    status: 'WEATHER_HOLD',
    statusNote: 'Rain overnight — gate opens once it dries',
  });
  check('tomorrow takes a caution post', postTomorrow.success === true, postTomorrow.message);
  const one = await rider.call('/tracks/221-mx');
  check(
    'the venue serves tomorrow’s scheduled read',
    one.data?.track?.tomorrowStatus?.status === 'WEATHER_HOLD' &&
      one.data?.track?.tomorrowStatus?.day === tomorrowStr,
    JSON.stringify(one.data?.track?.tomorrowStatus)
  );
  check(
    'the live line still reads today',
    one.data?.track?.status === beforeGate?.status,
    one.data?.track?.status
  );
  const net = await rider.call('/tracks');
  const row221 = net.data?.tracks?.find((t: any) => t.slug === '221-mx');
  check(
    'the network carries tomorrow’s read too',
    row221?.tomorrowStatus?.status === 'WEATHER_HOLD',
    row221?.tomorrowStatus?.day
  );
  const postToday = await mx221Op.call('/owner/track/day-status', 'POST', {
    day: todayStr,
    status: 'CLOSED',
    statusNote: 'Day-status check',
  });
  check('today posts', postToday.success === true, postToday.message);
  const oneToday = await rider.call('/tracks/221-mx');
  check('a posted today becomes the live read', oneToday.data?.track?.status === 'CLOSED', oneToday.data?.track?.status);
  const riderPost = await rider.call('/owner/track/day-status', 'POST', { day: tomorrowStr, status: 'OPEN' });
  check('a rider cannot post the gate', riderPost.success === false, riderPost.message);
  const badDay = await mx221Op.call('/owner/track/day-status', 'POST', { day: 'someday', status: 'OPEN' });
  check('a bad date is refused', badDay.success === false, badDay.message);
  const badStatus = await mx221Op.call('/owner/track/day-status', 'POST', { day: tomorrowStr, status: 'FLOODED' });
  check('a bad read is refused', badStatus.success === false, badStatus.message);
  // Restore — the suites and the demo read 221 MX as this run found it.
  await mx221Op.call(`/owner/track/day-status?day=${todayStr}`, 'DELETE');
  await mx221Op.call('/owner/track', 'PATCH', {
    status: beforeGate?.status ?? 'OPEN',
    statusNote: beforeGate?.statusNote ?? '',
  });
  await mx221Op.call(`/owner/track/day-status?day=${tomorrowStr}`, 'DELETE');
  const restored = await rider.call('/tracks/221-mx');
  check(
    'the gate is put back as found',
    restored.data?.track?.status === beforeGate?.status && restored.data?.track?.tomorrowStatus == null,
    restored.data?.track?.status
  );

  // ---------------------------------------------------------------------
  console.log('\n18. A rider calendar reads the follows list');
  // The registered rider follows nothing yet — the calendar is empty, and it
  // fills and empties with the follow control itself.
  const emptyCal = await rider.call('/me/calendar');
  check('a rider with no follows has an empty calendar', emptyCal.success && emptyCal.data?.events?.length === 0);
  const catalog = await rider.call('/tracks');
  const candidates = (catalog.data?.tracks ?? []).slice(0, 6);
  let host: any = null;
  let hostEvents: any[] = [];
  for (const t of candidates) {
    const one = await rider.call(`/tracks/${t.slug}`);
    const events = one.data?.track?.events ?? [];
    if (events.length > 0) {
      host = t;
      hostEvents = events;
      break;
    }
  }
  const unfollowed = candidates.find((t: any) => t.id !== host?.id);
  await rider.call(`/me/follows/${host.id}`, 'POST');
  const filled = await rider.call('/me/calendar');
  check(
    "a followed track's dates land on the calendar",
    filled.data?.events?.length === hostEvents.length && hostEvents.length > 0,
    `${filled.data?.events?.length} of ${hostEvents.length}`
  );
  check(
    'every date names the venue it belongs to',
    (filled.data?.events ?? []).every((e: any) => e.trackId === host.id && e.trackName === host.name && e.trackSlug === host.slug)
  );
  check(
    'an unfollowed track stays off it',
    (filled.data?.events ?? []).every((e: any) => e.trackId === host.id) &&
      (await rider.call(`/me/calendar?trackId=${unfollowed.id}`)).data?.events?.length === 0
  );
  const opCal = await mx221Op.call('/me/calendar');
  check('an operator has no calendar to read', opCal.success === false, opCal.message);
  await rider.call(`/me/follows/${host.id}`, 'DELETE');
  check(
    'unfollowing a track takes its dates off the calendar',
    (await rider.call('/me/calendar')).data?.events?.length === 0
  );

  // ---------------------------------------------------------------------
  console.log(`\n=== ${passCount} passed, ${failCount} failed ===\n`);
  await prisma.$disconnect();
  process.exit(failCount === 0 ? 0 : 1);
}

main().catch(async (e) => {
  console.error('Acceptance run crashed:', e);
  await prisma.$disconnect();
  process.exit(1);
});

/* Verify the claims in web/src/lib/demoAccounts.ts against the seeded DB. */
import { prisma } from '../src/utils/prisma';

let fails = 0;
function check(label: string, ok: boolean, detail = '') {
  if (!ok) fails++;
  console.log(`${ok ? 'OK  ' : 'FAIL'}  ${label}${detail ? ` — ${detail}` : ''}`);
}

async function main() {
  // --- Rider — Free (quinn): the default tier, and the only tier with no days
  const quinn = await prisma.user.findUnique({
    where: { email: 'quinn@example.com' },
    include: { passes: { include: { tier: true }, orderBy: { seasonYear: 'desc' }, take: 1 } },
  });
  const freeTier = quinn!.passes[0].tier;
  check('quinn is on the Free tier', freeTier.slug === 'free', freeTier.name);
  check('the Free tier is the default', freeTier.isDefault === true);
  check('the Free tier is free', freeTier.priceCents === 0, String(freeTier.priceCents));
  check('the Free tier carries no extra days', freeTier.extraDaysPerTrack === 0);
  const exactlyOneDefault = await prisma.passTier.count({ where: { isDefault: true } });
  check('exactly one tier is the default', exactlyOneDefault === 1, String(exactlyOneDefault));
  const quinnAllotments = await prisma.allotment.count({ where: { userId: quinn!.id } });
  check('the Free tier snapshots no days at all', quinnAllotments === 0, `${quinnAllotments} allotments`);
  const quinnFollows = await prisma.trackFollow.findMany({
    where: { userId: quinn!.id },
    include: { track: true },
  });
  check('quinn follows three tracks', quinnFollows.length === 3, quinnFollows.map((f) => f.track.name).join(', '));

  // --- The one paid tier: the Moto Pass ($400/yr, $50/mo, presale 25% off)
  const moto = await prisma.passTier.findUnique({ where: { slug: 'base' } });
  check('the paid tier is the Moto Pass', moto?.name === 'Moto Pass', moto?.name);
  check('the Moto Pass costs $400 a year', moto?.priceCents === 40000, String(moto?.priceCents));
  check('the Moto Pass is $50 a month', moto?.monthlyPriceCents === 5000, String(moto?.monthlyPriceCents));
  check('the presale is 25% off the annual price', moto?.earlyBirdPriceCents === 30000, String(moto?.earlyBirdPriceCents));
  check(
    'the presale opens Nov 16 and full price runs from Dec 2',
    moto?.earlyBirdStartsAt?.toISOString().slice(0, 10) === '2026-11-16' &&
      moto?.earlyBirdEndsAt?.toISOString().slice(0, 10) === '2026-12-02',
    `${moto?.earlyBirdStartsAt?.toISOString().slice(0, 10)} → ${moto?.earlyBirdEndsAt?.toISOString().slice(0, 10)}`
  );
  const factoryGone = await prisma.passTier.findUnique({ where: { slug: 'factory' } });
  check('the Factory tier is gone', factoryGone === null);
  const soldTiers = await prisma.passTier.count({ where: { isDefault: false } });
  check('exactly one tier is sold', soldTiers === 1, `${soldTiers} sellable`);

  // --- Rider — Moto Pass (alex)
  const alex = await prisma.user.findUnique({
    where: { email: 'alex@example.com' },
    include: { passes: { include: { tier: true }, orderBy: { seasonYear: 'desc' }, take: 1 } },
  });
  const alexTier = alex!.passes[0].tier;
  check('alex is on the Moto Pass tier', alexTier.slug === 'base', alexTier.name);
  check('the Moto Pass has no extra days per track', alexTier.extraDaysPerTrack === 0);

  // --- Rider — Moto Pass, in season (jordan)
  const jordan = await prisma.user.findUnique({
    where: { email: 'jordan@example.com' },
    include: { passes: { include: { tier: true }, orderBy: { seasonYear: 'desc' }, take: 1 } },
  });
  const jordanTier = jordan!.passes[0].tier;
  check('jordan is on the Moto Pass tier', jordanTier.slug === 'base', jordanTier.name);

  const basePerks = await prisma.perk.count({ where: { tierId: null } });
  check('every perk is network-wide', basePerks === 5, `${basePerks} network-wide`);

  const jordanResv = await prisma.reservation.findFirst({
    where: {
      userId: jordan!.id,
      status: 'CONFIRMED',
      track: { contracts: { some: { reservationRequired: true } } },
    },
    include: { track: true },
  });
  check(
    'jordan has a reservation at a reservation-required track',
    Boolean(jordanResv),
    jordanResv?.track.name
  );

  // --- The network is motocross only, and one pass covers all of it
  const parkTracks = await prisma.track.count({ where: { category: 'OFFROAD_PARK' } });
  check('no off-road parks are seeded', parkTracks === 0, `${parkTracks} parks`);
  const networkCount = await prisma.track.count();
  check('the network carries 25 or more tracks', networkCount >= 25, `${networkCount} tracks`);
  const alexAllotments = await prisma.allotment.count({ where: { userId: alex!.id } });
  check('the pass snapshots an allotment at every track', alexAllotments === networkCount, `${alexAllotments} of ${networkCount}`);

  // --- Rider — out of days (sam)
  const sam = await prisma.user.findUnique({ where: { email: 'sam@example.com' } });
  const ridge = await prisma.track.findUnique({ where: { slug: '221-mx' } });
  const samRidge = await prisma.allotment.findFirst({
    where: { userId: sam!.id, trackId: ridge!.id },
  });
  check(
    'sam has used every included day at 221 MX',
    samRidge!.freeDaysUsed >= samRidge!.includedDays,
    `${samRidge!.freeDaysUsed}/${samRidge!.includedDays}`
  );
  check(
    'sam has used the discounted extra day at 221 MX too',
    samRidge!.discountDaysUsed >= samRidge!.discountDaysAllowed,
    `${samRidge!.discountDaysUsed}/${samRidge!.discountDaysAllowed}`
  );
  check(
    'sam therefore has zero days left there',
    Math.max(samRidge!.includedDays - samRidge!.freeDaysUsed, 0) === 0 &&
      Math.max(samRidge!.discountDaysAllowed - samRidge!.discountDaysUsed, 0) === 0
  );
  const samOther = await prisma.allotment.findMany({
    where: { userId: sam!.id, NOT: { trackId: ridge!.id } },
  });
  check('sam still has days at other tracks (so it is track-specific)', samOther.some((a) => a.includedDays - a.freeDaysUsed > 0));

  // --- Rider — expired (morgan)
  const morgan = await prisma.user.findUnique({
    where: { email: 'morgan@example.com' },
    include: { passes: { orderBy: { seasonYear: 'desc' } } },
  });
  const mPass = morgan!.passes[0];
  check('morgan has no ACTIVE pass', !morgan!.passes.some((p) => p.status === 'ACTIVE'));
  check('morgan\u2019s latest pass is EXPIRED', mPass.status === 'EXPIRED', mPass.status);
  check(
    'morgan\u2019s pass is a previous season',
    mPass.seasonYear === new Date().getUTCFullYear() - 1,
    String(mPass.seasonYear)
  );

  // --- Operator
  const op = await prisma.user.findUnique({
    where: { email: 'ops@221mx.example.com' },
    include: { operatorTrack: true },
  });
  check('operator role is OPERATOR', op!.role === 'OPERATOR', op!.role);
  check(
    'operator is pinned to 221 MX',
    op!.operatorTrack?.slug === '221-mx',
    op!.operatorTrack?.name
  );

  // --- Admin
  const admin = await prisma.user.findUnique({ where: { email: 'admin@motopass.example.com' } });
  check('admin role is ADMIN', admin!.role === 'ADMIN', admin!.role);
  const compTier = await prisma.passTier.findUnique({ where: { slug: 'comp' } });
  check('no comp tier exists — only the free and the paid tier', compTier === null);

  console.log(`\n${fails === 0 ? 'ALL CLAIMS VERIFIED' : `${fails} CLAIM(S) WRONG`}`);
  await prisma.$disconnect();
  process.exit(fails === 0 ? 0 : 1);
}

main().catch(async (e) => {
  console.error(e);
  await prisma.$disconnect();
  process.exit(1);
});

/* eslint-disable no-console */
/**
 * API checks for the track-owner console (localhost:4010).
 *
 * The profile page and the console UI are covered by `web/scripts/verify-profile.cjs`.
 * What that cannot reach is the ownership model underneath, which is the part
 * worth pinning: who may write a venue's profile, and that a WRITE is scoped to
 * the caller's own track rather than to whatever id the client sent.
 *
 * Runs against the seeded demo DB and leaves it as it found it (it only edits
 * fields it puts back, and removes every event it adds).
 */
const BASE = 'http://localhost:4010/api';
const PASSWORD = 'dialed123';

let passCount = 0;
let failCount = 0;

function check(label: string, ok: boolean, detail = '') {
  if (ok) {
    passCount++;
    console.log(`  PASS  ${label}${detail ? ` — ${detail}` : ''}`);
  } else {
    failCount++;
    console.log(`  FAIL  ${label}${detail ? ` — ${detail}` : ''}`);
  }
}

class Client {
  cookie = '';
  async call<T = any>(path: string, method = 'GET', body?: unknown): Promise<{ status: number; json: T }> {
    const res = await fetch(`${BASE}${path}`, {
      method,
      headers: {
        'Content-Type': 'application/json',
        ...(this.cookie ? { Cookie: this.cookie } : {}),
      },
      body: body ? JSON.stringify(body) : undefined,
    });
    for (const c of res.headers.getSetCookie?.() ?? []) {
      const [pair] = c.split(';');
      if (pair.startsWith('moto_sid=')) this.cookie = pair;
    }
    return { status: res.status, json: (await res.json()) as T };
  }
  get<T = any>(path: string) {
    return this.call<T>(path);
  }
  async login(email: string) {
    const r = await this.call('/auth/login', 'POST', { email, password: PASSWORD });
    if (!r.json.success) throw new Error(`login failed for ${email}: ${r.json.message}`);
  }
}

const PNG =
  'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8DwHwAFAAH/q842iQAAAABJRU5ErkJggg==';

async function main() {
  console.log('\n=== Moto Pass — track-owner console ===\n');

  const anon = new Client();
  const rider = new Client();
  const mx221Op = new Client();
  const eastBendOp = new Client();
  const admin = new Client();

  await rider.login('quinn@example.com');
  await mx221Op.login('ops@221mx.example.com');
  await eastBendOp.login('ops@eastbend.example.com');
  await admin.login('admin@motopass.example.com');

  // ---- Who may touch the console at all ---------------------------------
  const anonRead = await anon.get('/owner/track');
  check('anonymous cannot read the console', anonRead.status === 401, `HTTP ${anonRead.status}`);
  const riderRead = await rider.get('/owner/track');
  check('a rider cannot read the console', riderRead.status === 403, `HTTP ${riderRead.status}`);
  const riderWrite = await rider.call('/owner/track', 'PATCH', { hours: 'never' });
  check('a rider cannot write a profile', riderWrite.status === 403, `HTTP ${riderWrite.status}`);

  // ---- An operator resolves to its own pinned venue ---------------------
  const mine = await mx221Op.get('/owner/track');
  check('an operator reads its own venue', mine.json.data?.track?.slug === '221-mx', mine.json.data?.track?.slug);
  check(
    'the console payload carries the profile fields',
