  );

  // A rider's own pass terms are not in this payload — it is the owner's view.
  const riderProfile = await rider.get('/tracks/221-mx');
  check(
    'a free rider reads the profile without the pass terms',
    riderProfile.json.data?.track?.includedDays === null && riderProfile.json.data?.gated === true
  );

  // ---- A write is scoped to the caller's track, whatever id was sent -----
  const eastBendBefore = await eastBendOp.get('/owner/track');
  const eastBendId = eastBendBefore.json.data.track.id;
  const bx = await mx221Op.call('/owner/track', 'PATCH', {
    description: 'scoped write check',
    trackId: eastBendId,
  });
  check('the write succeeds', bx.json.success === true, bx.json.message);
  const eastBendAfter = await eastBendOp.get('/owner/track');
  check(
    'an operator cannot write another venue by naming its id',
    eastBendAfter.json.data.track.description !== 'scoped write check',
    eastBendAfter.json.data.track.description
  );
  check('the write landed on the caller’s own venue', bx.json.data.track.slug === '221-mx', bx.json.data.track.slug);

  // Put it back.
  await mx221Op.call('/owner/track', 'PATCH', { description: mine.json.data.track.description ?? '' });
  const restored = await mx221Op.get('/owner/track');
  check('the profile copy is back as seeded', restored.json.data.track.description === mine.json.data.track.description);

  // ---- An empty string clears a field; status never clears --------------
  await mx221Op.call('/owner/track', 'PATCH', { statusNote: 'clear me' });
  let now = await mx221Op.get('/owner/track');
  check('a status note can be set', now.json.data.track.statusNote === 'clear me');
  await mx221Op.call('/owner/track', 'PATCH', { statusNote: '' });
  now = await mx221Op.get('/owner/track');
  check('an empty status note clears to null', now.json.data.track.statusNote === null, String(now.json.data.track.statusNote));
  const badStatus = await mx221Op.call('/owner/track', 'PATCH', { status: 'MELTED' });
  check('an unknown status is refused', badStatus.status === 400, `HTTP ${badStatus.status}`);

  // ---- Asset upload -----------------------------------------------------
  const upload = await mx221Op.call('/owner/track/assets', 'POST', { kind: 'logo', dataUrl: PNG });
  const url: string = upload.json.data?.url ?? '';
  check('an image upload returns a served path', url.startsWith('/api/uploads/'), url || upload.json.message);
  const served = await fetch(`http://localhost:4010${url}`);
  check('the uploaded file is served back', served.status === 200, `HTTP ${served.status}`);
  const notImage = await mx221Op.call('/owner/track/assets', 'POST', { kind: 'logo', dataUrl: 'data:text/plain;base64,aGk=' });
  check('a non-image upload is refused', notImage.status === 400, notImage.json.message);
  await mx221Op.call('/owner/track', 'PATCH', { logoUrl: '' });

  // ---- Gallery photos are scoped the same way ---------------------------
  const seeded = await mx221Op.get('/owner/track');
  const seededPhotos: { id: string; sortOrder: number }[] = seeded.json.data?.track?.photos ?? [];
  check('the owner reads its own venue gallery', seededPhotos.length >= 5, `${seededPhotos.length} photos`);
  check(
    'the gallery comes back in the owner\u2019s order',
    seededPhotos.every((p, i) => p.sortOrder === i),
    seededPhotos.map((p) => p.sortOrder).join(',')
  );

  const anonPhoto = await anon.call('/owner/track/photos', 'POST', { url: '/tracks/221-mx.jpg' });
  check('an anonymous visitor cannot add a photo', anonPhoto.status === 401, `HTTP ${anonPhoto.status}`);
  const riderPhoto = await rider.call('/owner/track/photos', 'POST', { url: '/tracks/221-mx.jpg' });
  check('a rider cannot add a photo', riderPhoto.status === 403, `HTTP ${riderPhoto.status}`);

  const addedPhoto = await mx221Op.call('/owner/track/photos', 'POST', {
    url: '/tracks/photos/221-mx/01.jpg',
    category: 'RACE_DAY',
  });
  const photoId: string = addedPhoto.json.data?.photo?.id ?? '';
  check('an operator adds a photo', Boolean(photoId), addedPhoto.json.message);
  check(
    'a new photo lands at the end of the gallery',
    addedPhoto.json.data?.photo?.sortOrder === seededPhotos.length,
    String(addedPhoto.json.data?.photo?.sortOrder)
  );
  const badCategory = await mx221Op.call('/owner/track/photos', 'POST', { url: '/x.jpg', category: 'NOPE' });
  check('an unknown photo category is refused', badCategory.status === 400, `HTTP ${badCategory.status}`);

  const crossPhotoEdit = await eastBendOp.call(`/owner/track/photos/${photoId}`, 'PATCH', { caption: 'hijacked' });
  check('another operator cannot edit a photo', crossPhotoEdit.status === 404, `HTTP ${crossPhotoEdit.status}`);
  const crossPhotoDelete = await eastBendOp.call(`/owner/track/photos/${photoId}`, 'DELETE');
  check('another operator cannot delete a photo', crossPhotoDelete.status === 404, `HTTP ${crossPhotoDelete.status}`);

  const captioned = await mx221Op.call(`/owner/track/photos/${photoId}`, 'PATCH', {
    caption: 'Ownership check',
    category: 'FACILITY',
  });
  check(
    'the owner labels its own photo',
    captioned.json.data?.photo?.caption === 'Ownership check' && captioned.json.data?.photo?.category === 'FACILITY'
  );
  const clearedCaption = await mx221Op.call(`/owner/track/photos/${photoId}`, 'PATCH', { caption: '' });
  check('an empty caption clears to nothing', clearedCaption.json.data?.photo?.caption === null);

  const halfOrder = await mx221Op.call('/owner/track/photos/reorder', 'POST', {
    ids: [...seededPhotos.map((p) => p.id), photoId].reverse().slice(1),
  });
  check('a reorder must name the whole gallery', halfOrder.status === 400, `HTTP ${halfOrder.status}`);

  const reversed = [...seededPhotos.map((p) => p.id), photoId].reverse();
  const reordered = await mx221Op.call('/owner/track/photos/reorder', 'POST', { ids: reversed });
  check(
    'reordering rewrites the gallery order',
    (reordered.json.data?.photos ?? []).map((p: { id: string }) => p.id).join(',') === reversed.join(',')
  );
  const publicOrder = await anon.get('/tracks/221-mx');
