    'the public page reads the gallery in that order',
    (publicOrder.json.data?.track?.photos ?? []).map((p: { id: string }) => p.id).join(',') === reversed.join(',')
  );
  const restoredOrder = await mx221Op.call('/owner/track/photos/reorder', 'POST', {
    ids: [...seededPhotos.map((p) => p.id), photoId],
  });
  check('the gallery order goes back', restoredOrder.json.success === true);

  const removedPhoto = await mx221Op.call(`/owner/track/photos/${photoId}`, 'DELETE');
  check('the owner removes its own photo', removedPhoto.json.success === true, removedPhoto.json.message);
  const publicAfterPhoto = await anon.get('/tracks/221-mx');
  check(
    'the removed photo is off the public page',
    (publicAfterPhoto.json.data?.track?.photos ?? []).length === seededPhotos.length
  );

  // ---- Events are scoped the same way ----------------------------------
  const addRes = await mx221Op.call('/owner/track/events', 'POST', { title: 'Ownership check', startsAt: '2030-01-05' });
  const eventId: string = addRes.json.data?.event?.id ?? '';
  check('an operator adds an event', Boolean(eventId), addRes.json.message);
  check(
    'a bare date is stored once, at noon UTC',
    (addRes.json.data?.event?.startsAt ?? '').includes('T12:00:00'),
    addRes.json.data?.event?.startsAt
  );

  const crossDelete = await eastBendOp.call(`/owner/track/events/${eventId}`, 'DELETE');
  check('another operator cannot delete it', crossDelete.status === 404, `HTTP ${crossDelete.status}`);
  const crossEdit = await eastBendOp.call(`/owner/track/events/${eventId}`, 'PATCH', { title: 'hijacked' });
  check('another operator cannot edit it', crossEdit.status === 404, `HTTP ${crossEdit.status}`);

  const badOrder = await mx221Op.call(`/owner/track/events/${eventId}`, 'PATCH', {
    startsAt: '2030-03-01',
    endsAt: '2030-02-01',
  });
  check('an event cannot end before it starts', badOrder.status === 400, badOrder.json.message);

  // ---- The hours a date runs -------------------------------------------
  // Hours travel as minutes past midnight and are written as a pair, so a date
  // is timed or all-day — the owner's week grid draws one or the other.
  const timed = await mx221Op.call(`/owner/track/events/${eventId}`, 'PATCH', {
    startMinutes: 540,
    endMinutes: 960,
  });
  check(
    'a date can be given its own hours',
    timed.json.success === true &&
      timed.json.data.event.startMinutes === 540 &&
      timed.json.data.event.endMinutes === 960,
    JSON.stringify([timed.json.data?.event?.startMinutes, timed.json.data?.event?.endMinutes])
  );
  const publicTimed = await fetch(`${BASE}/tracks/221-mx`).then((r) => r.json());
  const servedHours = (publicTimed.data.track.events ?? []).find((e: { id: string }) => e.id === eventId);
  check(
    'the hours reach the public profile',
    servedHours?.startMinutes === 540 && servedHours?.endMinutes === 960,
    JSON.stringify([servedHours?.startMinutes, servedHours?.endMinutes])
  );
  const crossedHours = await mx221Op.call(`/owner/track/events/${eventId}`, 'PATCH', {
    startMinutes: 960,
    endMinutes: 540,
  });
  check('a date cannot end before it starts its own day', crossedHours.status === 400, crossedHours.json.message);
  const allDay = await mx221Op.call(`/owner/track/events/${eventId}`, 'PATCH', {
    startMinutes: null,
    endMinutes: null,
  });
  check(
    'clearing the pair makes it all-day',
    allDay.json.success === true && allDay.json.data.event.startMinutes === null && allDay.json.data.event.endMinutes === null,
    JSON.stringify([allDay.json.data?.event?.startMinutes, allDay.json.data?.event?.endMinutes])
  );

  const hidden = await mx221Op.call(`/owner/track/events/${eventId}`, 'PATCH', { isActive: false });
  check('an event can be hidden', hidden.json.success === true && hidden.json.data.event.isActive === false);
  const publicAfter = await fetch(`${BASE}/tracks/221-mx`).then((r) => r.json());
  check(
    'a hidden event is off the public profile',
    !(publicAfter.data.track.events ?? []).some((e: { id: string }) => e.id === eventId)
  );

  const removed = await mx221Op.call(`/owner/track/events/${eventId}`, 'DELETE');
  check('the owner removes its own event', removed.json.success === true, removed.json.message);

  // ---- Admin parity ----------------------------------------------------
  const adminNoTrack = await admin.get('/owner/track');
  check('an admin must name a venue', adminNoTrack.status === 400, `HTTP ${adminNoTrack.status}`);
  const adminPicks = await admin.get(`/owner/track?trackId=${eastBendId}`);
  check('an admin can open any venue', adminPicks.json.data?.track?.slug === 'east-bend-motorsports', adminPicks.json.data?.track?.slug);

  // ---- Public read -----------------------------------------------------
  const list = await anon.get('/tracks');
  check(
    'the directory payload carries the new profile fields',
    (list.json.data.tracks ?? []).every((t: Record<string, unknown>) => 'bannerUrl' in t && 'logoUrl' in t && 'youtube' in t)
  );
  const missing = await anon.get('/tracks/nope-not-a-track');
  check('an unknown slug 404s', missing.status === 404, `HTTP ${missing.status}`);

  console.log(`\n=== ${passCount} passed, ${failCount} failed ===`);
  process.exit(failCount === 0 ? 0 : 1);
}

main().catch((e) => {
