import express from 'express';
import fs from 'fs';
import helmet from 'helmet';
import cors from 'cors';
import compression from 'compression';
import morgan from 'morgan';
import cookieParser from 'cookie-parser';
import rateLimit from 'express-rate-limit';

import config from './config';
import { apiRoutes } from './routes';
import { attachUser } from './middleware/auth';
import { errorHandler } from './middleware/errorHandler';
import { stripeWebhook } from './controllers/payments.controller';
import logger from './utils/logger';

export function createApp() {
  const app = express();

  app.set('trust proxy', 1);
  app.use(helmet({ crossOriginResourcePolicy: false }));
  app.use(cors({ origin: config.corsOrigin, credentials: true }));
  app.use(compression());
  if (!config.isProd) app.use(morgan('dev'));

  // Stripe webhook MUST get the raw body for signature verification —
  // register it before the JSON body parser.
  app.post(
    '/api/payments/webhook',
    express.raw({ type: 'application/json' }),
    stripeWebhook
  );

  app.use(express.json({ limit: '1mb' }));
  app.use(express.urlencoded({ extended: true }));
  app.use(cookieParser());

  // Uploaded profile art is POSTed as a base64 data URL, so that one route gets
  // a much larger body ceiling than the rest of the API.
  app.use('/api/owner/track/assets', express.json({ limit: '8mb' }));
  app.use('/api/me/track-reviews', express.json({ limit: '8mb' }));

  // Banner/logo files the owner console writes. Mounted under /api so the dev
  // proxy (and the tailnet origin) reach them without a second origin.
  fs.mkdirSync(config.uploads.dir, { recursive: true });
  app.use(config.uploads.publicPath, express.static(config.uploads.dir, { maxAge: '1h' }));

  app.use(
    '/api',
    rateLimit({
      windowMs: 60_000,
      limit: 300,
      standardHeaders: true,
      legacyHeaders: false,
      // Never throttle the QR scan endpoint — operators need instant feedback.
      skip: (req) => req.path.startsWith('/operator/scan'),
    })
  );

  app.use(attachUser);
  app.use('/api', apiRoutes);

  app.use((_req, res) => {
    res.status(404).json({ success: false, message: 'Not found.' });
  });

  app.use(errorHandler);

  logger.info(`CORS origin: ${config.corsOrigin}`);
  return app;
}

