import { Response, NextFunction } from 'express';
import { z } from 'zod';
import {
  DayConsumePolicy,
  PassStatus,
  Role,
  DAY_CONSUME_POLICY_VALUES,
  PASS_STATUS_VALUES,
  ROLE_VALUES,
  TRACK_CATEGORY_VALUES,
} from '../types/enums';
import { AuthRequest } from '../types';
import { prisma } from '../utils/prisma';
import { success, error, paginated } from '../utils/apiResponse';
import { activatePass } from '../services/pass.service';
import { hoursWeekSchema } from '../lib/hoursWeek';

function slugify(s: string) {
  return s
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '');
}

