// Tracks & contracts
// ---------------------------------------------------------------------------

export const adminListTracks = async (_req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const tracks = await prisma.track.findMany({
      include: {
        contracts: { include: { season: true }, orderBy: { season: { year: 'desc' } } },
        _count: { select: { reservations: true, redemptions: true } },
      },
      orderBy: { name: 'asc' },
    });
    res.json(success({ tracks }));
  } catch (err) {
    next(err);
  }
};

const contractSchema = z.object({
  seasonId: z.string().uuid(),
  includedDays: z.number().int().min(0).max(60),
  discountDayEnabled: z.boolean(),
  discountDayNumber: z.number().int().min(1).max(60),
  discountRate: z.number().min(0).max(1),
  discountDaysAllowed: z.number().int().min(0).max(60),
  extraDayPriceCents: z.number().int().min(0),
  reservationRequired: z.boolean(),
  dayConsumePolicy: z.enum(DAY_CONSUME_POLICY_VALUES),
  isActive: z.boolean().optional(),
  notes: z.string().max(1000).optional(),
});

const trackSchema = z.object({
  name: z.string().trim().min(2),
  description: z.string().max(2000).optional(),
  city: z.string().optional(),
  region: z.string().optional(),
  address: z.string().optional(),
  country: z.string().optional(),
  lat: z.number().optional(),
  lng: z.number().optional(),
  website: z.string().optional(),
  instagram: z.string().optional(),
  facebook: z.string().optional(),
  youtube: z.string().optional(),
  tiktok: z.string().optional(),
  email: z.string().optional(),
  phone: z.string().optional(),
  bannerUrl: z.string().optional(),
  logoUrl: z.string().optional(),
  imageUrl: z.string().optional(),
  hours: z.string().optional(),
  /** The venue's week as JSON — `{"mon":"Practice 9am–4pm", …}`; owner-editable too. */
  hoursWeek: hoursWeekSchema.optional(),
  statusNote: z.string().optional(),
  /** The operator's own message to riders — read in the network panel. */
  riderMessage: z.string().optional(),
  nextEvent: z.string().optional(),
  /** OPEN | WEATHER_HOLD | CLOSED — the operational line, owner-editable too. */
  status: z.enum(['OPEN', 'WEATHER_HOLD', 'CLOSED']).optional(),
  /** The venue's type — 'MX' (the network is motocross only). */
  category: z.enum(TRACK_CATEGORY_VALUES).optional(),
  isActive: z.boolean().optional(),
  contract: contractSchema.optional(),
});

export const adminCreateTrack = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const body = trackSchema.parse(req.body);
    const slug = slugify(body.name);
    // Everything the schema accepts goes straight onto the row, so a new profile
    // field never has to be wired into this handler by hand.
    const { contract, ...rest } = body;
    const track = await prisma.track.create({
      data: {
        ...rest,
        name: body.name,
        slug,
        country: body.country ?? 'US',
        isActive: body.isActive ?? true,
        ...(contract ? { contracts: { create: contract } } : {}),
      },
      include: { contracts: true },
    });
    await prisma.auditLog.create({
      data: { actorId: req.user!.id, action: 'CREATE', entity: 'Track', entityId: track.id },
    });
    res.status(201).json(success({ track }, 'Track created.'));
  } catch (err) {
    next(err);
  }
};

export const adminUpdateTrack = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const id = req.params.id as string;
    const body = trackSchema.partial().parse(req.body);
    const existing = await prisma.track.findUnique({ where: { id } });
    if (!existing) return res.status(404).json(error('Track not found.'));

    const { contract, ...trackData } = body;
    const track = await prisma.track.update({
      where: { id },
      data: {
        ...trackData,
        ...(body.name ? { slug: slugify(body.name) } : {}),
      },
      include: { contracts: true },
    });
    await prisma.auditLog.create({
      data: { actorId: req.user!.id, action: 'UPDATE', entity: 'Track', entityId: id, meta: JSON.stringify(body) },
    });
    res.json(success({ track }, 'Track updated.'));
  } catch (err) {
    next(err);
  }
};

/** Upsert a track's contract for a season — allotment, discount, reservation rule. */
export const adminUpsertContract = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const trackId = req.params.id as string;
    const body = contractSchema.parse(req.body);
    const track = await prisma.track.findUnique({ where: { id: trackId } });
    if (!track) return res.status(404).json(error('Track not found.'));

    const contract = await prisma.trackContract.upsert({
      where: { trackId_seasonId: { trackId, seasonId: body.seasonId } },
      create: { trackId, ...body },
      update: body,
      include: { season: true },
    });
    await prisma.auditLog.create({
      data: {
        actorId: req.user!.id,
        action: 'UPSERT_CONTRACT',
        entity: 'TrackContract',
        entityId: contract.id,
        meta: JSON.stringify(body),
      },
    });
    res.json(success({ contract }, 'Contract saved.'));
  } catch (err) {
    next(err);
  }
};

/**
 * Re-snapshot contract terms onto every allotment for a season.
 * Deliberately explicit: contract edits never silently rewrite riders' days.
 */
export const adminSyncAllotments = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const seasonId = req.params.seasonId as string;
    const contracts = await prisma.trackContract.findMany({ where: { seasonId, isActive: true } });
    let updated = 0;
    for (const c of contracts) {
      const res2 = await prisma.allotment.updateMany({
        where: { trackId: c.trackId, seasonYear: (await prisma.season.findUnique({ where: { id: seasonId } }))!.year },
        data: {
          includedDays: c.includedDays,
          discountDayEnabled: c.discountDayEnabled,
          discountDayNumber: c.discountDayNumber,
          discountRate: c.discountRate,
          discountDaysAllowed: c.discountDaysAllowed,
          extraDayPriceCents: c.extraDayPriceCents,
          reservationRequired: c.reservationRequired,
          dayConsumePolicy: c.dayConsumePolicy,
        },
      });
      updated += res2.count;
    }
