export const adminListUsers = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const page = Math.max(Number(req.query.page) || 1, 1);
    const limit = Math.min(Math.max(Number(req.query.limit) || 25, 1), 200);
    const search = (req.query.search as string) || undefined;
    const role = req.query.role as Role | undefined;

    const where = {
      ...(role ? { role } : {}),
      ...(search
        ? {
            OR: [
              { name: { contains: search, mode: 'insensitive' as const } },
              { email: { contains: search, mode: 'insensitive' as const } },
            ],
          }
        : {}),
    };

    const [users, total] = await Promise.all([
      prisma.user.findMany({
        where,
        include: {
          passes: { orderBy: { seasonYear: 'desc' }, take: 1, include: { tier: true } },
          operatorTrack: { select: { id: true, name: true } },
        },
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      prisma.user.count({ where }),
    ]);

    res.json(
      paginated(
        users.map((u) => ({
          id: u.id,
          name: u.name,
          email: u.email,
          role: u.role,
          isActive: u.isActive,
          operatorTrack: u.operatorTrack,
          latestPass: u.passes[0]
            ? {
                id: u.passes[0].id,
                status: u.passes[0].status,
                seasonYear: u.passes[0].seasonYear,
                tierName: u.passes[0].tier.name,
                expiresAt: u.passes[0].expiresAt,
              }
            : null,
        })),
        total,
        page,
        limit
      )
    );
  } catch (err) {
    next(err);
  }
};

