export const adminReports = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const seasonYear = Number(req.query.seasonYear) || new Date().getUTCFullYear();

    const [tracks, redemptions, passes, payments] = await Promise.all([
      prisma.track.findMany({ select: { id: true, name: true } }),
      prisma.redemption.findMany({
        where: { day: { gte: new Date(Date.UTC(seasonYear, 0, 1)), lte: new Date(Date.UTC(seasonYear, 11, 31, 23, 59, 59)) } },
      }),
      prisma.pass.findMany({ where: { seasonYear }, include: { tier: true } }),
      prisma.payment.findMany({ where: { status: 'PAID' } }),
    ]);

    const perTrack = tracks.map((t) => {
      const rows = redemptions.filter((r) => r.trackId === t.id);
      return {
        trackId: t.id,
        trackName: t.name,
        redemptions: rows.length,
        freeDays: rows.filter((r) => r.kind === 'FREE').length,
        discountDays: rows.filter((r) => r.kind === 'DISCOUNT').length,
        trackRevenueCents: rows.reduce((sum, r) => sum + r.amountChargedCents, 0),
      };
    });

    const tierCounts = new Map<string, number>();
    for (const p of passes) {
      tierCounts.set(p.tier.name, (tierCounts.get(p.tier.name) ?? 0) + 1);
    }

    const revenueCents = payments.reduce((s, p) => s + p.amountCents, 0);
    const seasonPayments = await prisma.payment.findMany({
      where: { createdAt: { gte: new Date(Date.UTC(seasonYear, 0, 1)) }, status: 'PAID' },
    });

    res.json(
      success({
        seasonYear,
        totals: {
          tracks: tracks.length,
          activePasses: passes.filter((p) => p.status === 'ACTIVE').length,
          totalPasses: passes.length,
          redemptions: redemptions.length,
          revenueCents: seasonPayments.reduce((s, p) => s + p.amountCents, 0),
          allTimeRevenueCents: revenueCents,
        },
        perTrack,
        tierBreakdown: [...tierCounts.entries()].map(([name, count]) => ({ name, count })),
      })
    );
  } catch (err) {
    next(err);
  }
};

