import { Request, Response, NextFunction } from 'express';
import { z } from 'zod';
import { PassStatus, Role } from '../types/enums';
import { prisma } from '../utils/prisma';
import { hashPassword, comparePassword } from '../utils/password';
import {
  createSession,
  destroySession,
  setSessionCookie,
  clearSessionCookie,
} from '../services/session.service';
import { AuthRequest } from '../types';
import { success, error } from '../utils/apiResponse';
import config from '../config';
import { activatePass } from '../services/pass.service';

/**
 * Put a brand-new account on the default (free) tier for the live season. A
 * free pass is a real ACTIVE pass with an empty ledger — it is what makes the
 * account read as "Free" everywhere, and `getCurrentPass` demotes it the moment
 * the rider buys a paid tier.
 */
async function grantDefaultTier(userId: string) {
  const tier = await prisma.passTier.findFirst({
    where: { isDefault: true, isActive: true },
    orderBy: { sortOrder: 'asc' },
  });
  if (!tier) return;
  const season = await prisma.season.findFirst({
    where: { isActive: true },
    orderBy: { year: 'desc' },
  });
  if (!season) return;
  const pass = await prisma.pass.create({
    data: {
      userId,
      tierId: tier.id,
      seasonId: season.id,
      seasonYear: season.year,
      status: PassStatus.PENDING,
      expiresAt: season.endsAt,
    },
  });
  await activatePass(pass.id);
}

export const registerSchema = z.object({
  name: z.string().trim().min(2, 'Name is required'),
  email: z.string().trim().email('A valid email is required'),
  password: z.string().min(8, 'Password must be at least 8 characters'),
  phone: z.string().trim().optional(),
});

export const loginSchema = z.object({
  email: z.string().trim().email(),
  password: z.string().min(1, 'Password is required'),
});

function publicUser(u: {
  id: string;
  name: string;
  email: string;
  role: string;
  location: string | null;
  avatarUrl: string | null;
  operatorTrackId: string | null;
}) {
  return {
    id: u.id,
    name: u.name,
    email: u.email,
    role: u.role as Role,
    location: u.location,
    avatarUrl: u.avatarUrl,
    operatorTrackId: u.operatorTrackId,
  };
}

export const register = async (req: Request, res: Response, next: NextFunction) => {
  try {
    const { name, email, password, phone } = registerSchema.parse(req.body);
    const existing = await prisma.user.findUnique({ where: { email } });
    if (existing) return res.status(409).json(error('An account with that email already exists.'));

    const user = await prisma.user.create({
      data: {
        name,
        email,
        phone,
        passwordHash: await hashPassword(password),
        role: Role.RIDER,
      },
    });

    // Every new rider lands on the default (free) tier: the network, the track
    // statuses and the follows list — no included days and no member discount.
    await grantDefaultTier(user.id);

    const { token, expiresAt } = await createSession(user.id, {
      userAgent: req.headers['user-agent'],
      ip: req.ip,
    });
    setSessionCookie(res, token, expiresAt);
    res.status(201).json(success({ user: publicUser(user) }, 'Account created.'));
  } catch (err) {
    next(err);
  }
};

export const login = async (req: Request, res: Response, next: NextFunction) => {
  try {
    const { email, password } = loginSchema.parse(req.body);
    const user = await prisma.user.findUnique({ where: { email } });
    if (!user || !user.isActive) {
      return res.status(401).json(error('Invalid email or password.'));
    }
    const ok = await comparePassword(password, user.passwordHash);
    if (!ok) return res.status(401).json(error('Invalid email or password.'));

    const { token, expiresAt } = await createSession(user.id, {
      userAgent: req.headers['user-agent'],
      ip: req.ip,
    });
    setSessionCookie(res, token, expiresAt);
    res.json(success({ user: publicUser(user) }, 'Signed in.'));
  } catch (err) {
    next(err);
  }
};

export const logout = async (req: Request, res: Response, next: NextFunction) => {
  try {
