import { NextFunction, Response } from 'express';
import { z } from 'zod';
import { AuthRequest } from '../types';
import { prisma } from '../utils/prisma';
import { success, error } from '../utils/apiResponse';
import { Role } from '../types/enums';
import { storeDataUrl, removeUploadedFile } from './owner.controller';

/**
 * Riders' reviews of a venue.
 *
 * The owner's gallery is the venue's curated art: ordered, categorised, 24 max.
 * A review is the other half of the same idea — a rider's considered account of
 * riding there: a body of text, a 1–5 rating, and up to six frames they shot.
 *
 * One review per rider per venue, enforced by the unique index and checked here
 * so the refusal reads as a sentence. A rider **edits** that same review after
 * the fact — the body, the rating, the frames — but cannot post a second one.
 * The venue may pull any review from its community page, an admin may pull any.
 *
 * Uploads reuse the owner console's store — a base64 data URL written into the
 * uploads dir and served back under /api/uploads — so there is one storage path
 * and one size ceiling for every image in the app.
 */

/** One review may carry this many frames. */
const MAX_PHOTOS = 6;
/** A review's body is an account, not an essay. */
const MAX_BODY = 2000;

const createSchema = z.object({
  trackId: z.string().min(1),
  rating: z.number().int().min(1).max(5),
  body: z.string().max(MAX_BODY),
  dataUrls: z.array(z.string()).max(MAX_PHOTOS).optional(),
});

const updateSchema = z.object({
  rating: z.number().int().min(1).max(5).optional(),
  body: z.string().max(MAX_BODY).optional(),
});

const photoSchema = z.object({
  dataUrl: z.string(),
  caption: z.string().max(140).optional(),
});

/** The shape both the public page and the community console read. */
export interface ReviewPhotoRead {
  id: string;
  url: string;
  caption: string | null;
}

export interface TrackReviewRead {
  id: string;
  rating: number;
  body: string;
  createdAt: Date;
  updatedAt: Date;
  userId: string;
  riderName: string;
  riderAvatarUrl: string | null;
  photos: ReviewPhotoRead[];
}

/** The relation both reads use — newest review first, frames in the rider's order. */
export const reviewSelect = {
  id: true,
  rating: true,
  body: true,
  createdAt: true,
  updatedAt: true,
  userId: true,
  user: { select: { name: true, avatarUrl: true } },
  photos: {
    orderBy: [{ sortOrder: 'asc' }, { createdAt: 'asc' }],
    select: { id: true, url: true, caption: true },
  },
} as const;

/** Flatten a joined review row into the read above. */
export function toTrackReviewRead(r: {
  id: string;
  rating: number;
  body: string;
  createdAt: Date;
  updatedAt: Date;
  userId: string;
  user: { name: string; avatarUrl: string | null };
  photos: { id: string; url: string; caption: string | null }[];
}): TrackReviewRead {
  return {
    id: r.id,
    rating: r.rating,
    body: r.body,
    createdAt: r.createdAt,
    updatedAt: r.updatedAt,
    userId: r.userId,
    riderName: r.user.name,
    riderAvatarUrl: r.user.avatarUrl,
    photos: r.photos.map((p) => ({ id: p.id, url: p.url, caption: p.caption })),
  };
}

/** Write each data URL into the uploads dir, refusing the first one that fails.
 *  Anything already written when a later frame is refused is cleaned up, so a
 *  half-saved review does not leave orphans behind. */
function storeAll(
  slug: string,
  dataUrls: string[]
): { urls: string[] } | { status: number; message: string } {
  const urls: string[] = [];
  for (const dataUrl of dataUrls) {
    const saved = storeDataUrl(slug, 'review', dataUrl, null);
    if ('status' in saved) {
      for (const url of urls) removeUploadedFile(url);
      return saved;
    }
    urls.push(saved.url);
  }
  return { urls };
}

/** Rider: write the one review they are allowed on this venue. A second attempt
 *  is refused — the rider updates the review they already have. */
export const addReview = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const body = createSchema.parse(req.body);
    const track = await prisma.track.findUnique({
      where: { id: body.trackId },
      select: { id: true, slug: true, name: true, isActive: true },
    });
    if (!track || !track.isActive) return res.status(404).json(error('Track not found.'));

    const mine = await prisma.trackReview.findUnique({
      where: { userId_trackId: { userId: req.user!.id, trackId: track.id } },
      select: { id: true },
    });
    if (mine) {
      return res
        .status(409)
        .json(error('You have already reviewed this track — update your review instead.'));
    }

    const dataUrls = body.dataUrls ?? [];
    const stored = storeAll(track.slug, dataUrls);
    if ('status' in stored) return res.status(stored.status).json(error(stored.message));

    const review = await prisma.trackReview.create({
      data: {
        trackId: track.id,
        userId: req.user!.id,
        rating: body.rating,
        body: body.body.trim(),
        photos: {
          create: stored.urls.map((url, i) => ({ url, sortOrder: i })),
        },
      },
      select: reviewSelect,
    });
    await prisma.auditLog.create({
      data: { actorId: req.user!.id, action: 'CREATE', entity: 'TrackReview', entityId: review.id },
    });
    res.status(201).json(success({ review: toTrackReviewRead(review) }, 'Review posted.'));
  } catch (err) {
    next(err);
  }
};

/** Rider: update the review they already wrote — its words and its stars. The
 *  frames are added and removed through their own routes below. */
export const updateOwnReview = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const id = req.params.id as string;
    const body = updateSchema.parse(req.body);
    const mine = await prisma.trackReview.findFirst({
      where: { id, userId: req.user!.id },
      select: { id: true },
    });
    if (!mine) return res.status(404).json(error('Review not found.'));

    const review = await prisma.trackReview.update({
      where: { id: mine.id },
      data: {
        ...(body.rating !== undefined ? { rating: body.rating } : {}),
        ...(body.body !== undefined ? { body: body.body.trim() } : {}),
      },
      select: reviewSelect,
    });
    await prisma.auditLog.create({
      data: { actorId: req.user!.id, action: 'UPDATE', entity: 'TrackReview', entityId: review.id },
    });
    res.json(success({ review: toTrackReviewRead(review) }, 'Review updated.'));
  } catch (err) {
    next(err);
  }
};

/** Rider: attach one more frame to their review. */
export const addReviewPhoto = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const id = req.params.id as string;
    const body = photoSchema.parse(req.body);
    const mine = await prisma.trackReview.findFirst({
      where: { id, userId: req.user!.id },
      select: { id: true, track: { select: { slug: true } }, _count: { select: { photos: true } } },
    });
    if (!mine) return res.status(404).json(error('Review not found.'));
    if (mine._count.photos >= MAX_PHOTOS) {
      return res
        .status(400)
        .json(error(`A review carries ${MAX_PHOTOS} photos — remove one first.`));
    }

    const saved = storeDataUrl(mine.track.slug, 'review', body.dataUrl, null);
    if ('status' in saved) return res.status(saved.status).json(error(saved.message));

    const photo = await prisma.trackReviewPhoto.create({
      data: {
        reviewId: mine.id,
        url: saved.url,
        caption: body.caption?.trim() || null,
        sortOrder: mine._count.photos,
      },
      select: { id: true, url: true, caption: true },
    });
    await prisma.auditLog.create({
      data: { actorId: req.user!.id, action: 'CREATE', entity: 'TrackReviewPhoto', entityId: photo.id },
    });
    res.status(201).json(success({ photo }, 'Photo added to your review.'));
  } catch (err) {
    next(err);
  }
};

/** Rider: take one frame off their own review. The review itself stays. */
export const deleteOwnReviewPhoto = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const reviewId = req.params.id as string;
    const photoId = req.params.photoId as string;
    const photo = await prisma.trackReviewPhoto.findFirst({
      where: { id: photoId, reviewId, review: { userId: req.user!.id } },
      select: { id: true, url: true },
    });
    if (!photo) return res.status(404).json(error('Photo not found.'));

    await prisma.trackReviewPhoto.delete({ where: { id: photo.id } });
    removeUploadedFile(photo.url);
    await prisma.auditLog.create({
      data: { actorId: req.user!.id, action: 'DELETE', entity: 'TrackReviewPhoto', entityId: photoId },
    });
    res.json(success({ id: photoId }, 'Photo removed from your review.'));
  } catch (err) {
    next(err);
  }
};

/**
 * Venue: pull any review from its own community page.
 *
 * Resolves the venue the way the rest of the console does — an operator is
 * pinned to its track, an admin names one — so an operator cannot reach into
 * another venue's reviews by guessing an id. Every uploaded frame goes with it;
 * seeded frames are left alone (`removeUploadedFile` only touches /api/uploads).
 */
export const ownerDeleteReview = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const user = req.user!;
    const trackId =
      user.role === Role.ADMIN
        ? (req.query.trackId as string | undefined) ?? user.operatorTrackId ?? null
        : user.operatorTrackId ?? null;
    if (!trackId) return res.status(400).json(error('No track is pinned to this account.'));

    const id = req.params.id as string;
    const review = await prisma.trackReview.findFirst({
      where: { id, trackId },
      select: { id: true, photos: { select: { url: true } } },
    });
    if (!review) return res.status(404).json(error('Review not found.'));

    await prisma.trackReview.delete({ where: { id: review.id } });
    for (const p of review.photos) removeUploadedFile(p.url);
    await prisma.auditLog.create({
      data: { actorId: user.id, action: 'DELETE', entity: 'TrackReview', entityId: id },
    });
    res.json(success({ id }, 'Review removed.'));
  } catch (err) {
    next(err);
  }
};

import { NextFunction, Response } from 'express';
import { z } from 'zod';
import fs from 'fs';
import path from 'path';
import { randomUUID } from 'crypto';
import {
  PassStatus,
  TrackEventKind,
  TrackPhotoCategory,
  TrackStatus,
  Role,
  TRACK_EVENT_KIND_VALUES,
  TRACK_PHOTO_CATEGORY_VALUES,
} from '../types/enums';
import { AuthRequest } from '../types';
import { prisma } from '../utils/prisma';
import { success, error } from '../utils/apiResponse';
import config from '../config';
import { hoursWeekSchema } from '../lib/hoursWeek';
import { dayKey, todayKey } from '../utils/dates';

/**
 * Track-owner console.
 *
 * The owner of a partner track is the OPERATOR account pinned to it
 * (`User.operatorTrackId`), so every handler resolves "my track" from the
 * session rather than trusting a track id from the client. An ADMIN may act on
 * any track by naming it (`?trackId=` on reads, `trackId` in the body on
 * writes) — the org console has no per-track profile editor of its own.
 *
 * What an owner may edit is cut deliberately: the profile copy and links, the
 * live status line, and the events. `name`, `slug`, `lat`/`lng`, `category` and
 * `isActive` stay admin-only — the slug is load-bearing across the seed and the
 * verify scripts.
 */

/** The track this caller is editing, or null when nothing is pinned and no id was given. */
function resolveTrackId(req: AuthRequest): string | null {
  const user = req.user!;
  if (user.role === Role.ADMIN) {
    const fromQuery = typeof req.query.trackId === 'string' ? req.query.trackId : undefined;
    const fromBody = typeof req.body?.trackId === 'string' ? req.body.trackId : undefined;
    return fromQuery || fromBody || null;
  }
  return user.operatorTrackId ?? null;
}

async function loadOwnedTrack(req: AuthRequest, res: Response) {
  const trackId = resolveTrackId(req);
  if (!trackId) {
    res.status(400).json(error('No track is pinned to this account.'));
    return null;
  }
  const track = await prisma.track.findUnique({
    where: { id: trackId },
    include: {
      events: { orderBy: { startsAt: 'asc' } },
      dayStatuses: { orderBy: { day: 'asc' } },
      photos: { orderBy: [{ sortOrder: 'asc' }, { createdAt: 'asc' }] },
      contracts: { include: { season: true }, orderBy: { season: { year: 'desc' } } },
    },
  });
  if (!track) {
    res.status(404).json(error('Track not found.'));
    return null;
  }
  return track;
}

/** The profile fields an owner (or an admin acting for them) may set. */
const profileSchema = z.object({
  description: z.string().max(2000).optional(),
  city: z.string().max(120).optional(),
  region: z.string().max(60).optional(),
  address: z.string().max(200).optional(),
  country: z.string().max(60).optional(),
  website: z.string().max(300).optional(),
  instagram: z.string().max(300).optional(),
  facebook: z.string().max(300).optional(),
  youtube: z.string().max(300).optional(),
  tiktok: z.string().max(300).optional(),
  email: z.string().max(200).optional(),
  phone: z.string().max(60).optional(),
  bannerUrl: z.string().max(300).optional(),
  logoUrl: z.string().max(300).optional(),
  imageUrl: z.string().max(300).optional(),
  hours: z.string().max(200).optional(),
  /** The venue's week as JSON — `{"mon":"Practice 9am–4pm", …}`; '' clears it. */
  hoursWeek: hoursWeekSchema.optional(),
  status: z.enum(['OPEN', 'WEATHER_HOLD', 'CLOSED']).optional(),
  statusNote: z.string().max(200).optional(),
  /** The operator's own message to riders — read in the network panel. */
  riderMessage: z.string().max(500).optional(),
  nextEvent: z.string().max(200).optional(),
});

/** An empty string clears an optional field — the console sends '' for a cleared input. */
const orNull = (v: string | undefined) => (v === undefined ? undefined : v.trim() === '' ? null : v.trim());

export const ownerGetTrack = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const track = await loadOwnedTrack(req, res);
    if (!track) return;
    res.json(success({ track }));
  } catch (err) {
    next(err);
  }
};

export const ownerUpdateTrack = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const existing = await loadOwnedTrack(req, res);
    if (!existing) return;
    const body = profileSchema.parse(req.body);

    const data: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(body)) {
      if (value === undefined) continue;
      // status is a non-null enum; everything else clears to null on ''.
      data[key] = key === 'status' ? value : orNull(value as string);
    }

    const track = await prisma.track.update({
      where: { id: existing.id },
      data,
      include: {
        events: { orderBy: { startsAt: 'asc' } },
        dayStatuses: { orderBy: { day: 'asc' } },
        photos: { orderBy: [{ sortOrder: 'asc' }, { createdAt: 'asc' }] },
      },
    });
    await prisma.auditLog.create({
      data: {
        actorId: req.user!.id,
        action: 'UPDATE_PROFILE',
        entity: 'Track',
        entityId: track.id,
        meta: JSON.stringify(Object.keys(data)),
      },
    });
    res.json(success({ track }, 'Profile saved.'));
  } catch (err) {
    next(err);
  }
};

// ---------------------------------------------------------------------------
// Day statuses — the gate per date
// ---------------------------------------------------------------------------

const dayStatusSchema = z.object({
  /** Bare day (`YYYY-MM-DD`) — lands at noon UTC so it never slips a date. */
  day: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'Pick a date.'),
  status: z.enum(['OPEN', 'WEATHER_HOLD', 'CLOSED']),
  statusNote: z.string().max(200).optional(),
});

/**
 * One day's gate read: post caution for tomorrow, close for the weekend, or
 * mark today open. An upsert — a day holds one read, and posting it again
 * replaces it.
 *
 * When the day arrives its read becomes the venue's live line: the operator
 * posts tomorrow's gate today and the page flips itself overnight.
 */
export const ownerUpsertDayStatus = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const track = await loadOwnedTrack(req, res);
    if (!track) return;
    const body = dayStatusSchema.parse(req.body);
    const day = toDate(body.day);
    const note = body.statusNote === undefined ? undefined : orNull(body.statusNote);

    const row = await prisma.trackDayStatus.upsert({
      where: { trackId_day: { trackId: track.id, day } },
      update: { status: body.status, ...(note !== undefined ? { statusNote: note } : {}) },
      create: { trackId: track.id, day, status: body.status, statusNote: note ?? null },
    });

    // A day that has arrived IS the gate: its read becomes the live line, so
    // the network page, the map and the venue profile flip with it. Compared
    // by calendar day — a row sits at noon UTC, midnight keys at 00:00.
    if (dayKey(day).getTime() <= todayKey().getTime()) {
      await prisma.track.update({
        where: { id: track.id },
        data: { status: body.status, ...(note !== undefined ? { statusNote: note } : {}) },
      });
    }
    await prisma.auditLog.create({
      data: {
        actorId: req.user!.id,
        action: 'SET_DAY_STATUS',
        entity: 'TrackDayStatus',
        entityId: row.id,
        meta: JSON.stringify({ trackId: track.id, day: body.day, status: body.status }),
      },
    });
    res.status(201).json(success({ dayStatus: row }, 'Day status saved.'));
  } catch (err) {
    next(err);
  }
};

/** A day with no read follows the live line — clearing drops its row. */
export const ownerClearDayStatus = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const track = await loadOwnedTrack(req, res);
    if (!track) return;
    const day = typeof req.query.day === 'string' ? req.query.day : '';
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) {
      return res.status(400).json(error('Pick a date.'));
    }
    await prisma.trackDayStatus.deleteMany({
      where: { trackId: track.id, day: toDate(day) },
    });
    await prisma.auditLog.create({
      data: {
        actorId: req.user!.id,
        action: 'CLEAR_DAY_STATUS',
        entity: 'TrackDayStatus',
        entityId: track.id,
        meta: JSON.stringify({ trackId: track.id, day }),
      },
    });
    res.json(success({ day }, 'Day status cleared.'));
  } catch (err) {
    next(err);
  }
};

// ---------------------------------------------------------------------------
// Events
// ---------------------------------------------------------------------------

const eventSchema = z.object({
  title: z.string().trim().min(2).max(160),
  description: z.string().max(1000).optional(),
  kind: z.enum(TRACK_EVENT_KIND_VALUES).default(TrackEventKind.PRACTICE),
  /** ISO date or datetime; a bare day lands at local noon so it never slips a date. */
  startsAt: z.string().min(4),
  endsAt: z.string().optional().nullable(),
  /**
   * The hours a date runs, in minutes past midnight on that date's own day
   * (venue-local — no zone in the way). Both ends move together: a date is
   * either timed or all-day, never half of each.
   */
  startMinutes: z.number().int().min(0).max(1439).nullable().optional(),
  endMinutes: z.number().int().min(0).max(1439).nullable().optional(),
  isActive: z.boolean().optional(),
});

/**
 * A bare calendar day is stored at noon UTC. An event is a day, not an instant:
 * pinning it to midday keeps the stored date the same one whichever timezone
 * reads it back, so the console's date input round-trips exactly.
 */
function toDate(value: string) {
  const bare = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (bare) return new Date(Date.UTC(Number(bare[1]), Number(bare[2]) - 1, Number(bare[3]), 12));
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) throw new Error(`Invalid date: ${value}`);
  return d;
}

/** An event cannot end before it starts — the console can otherwise leave the
 *  two date inputs crossed after a start date is moved forward. */
function orderError(startsAt: Date, endsAt: Date | null): string | null {
  return endsAt && endsAt.getTime() < startsAt.getTime()
    ? 'An event cannot end before it starts.'
    : null;
}

/**
 * The hours of a date are one choice, so they arrive together and are written
 * together: a single-day date that ends before it starts is refused, and a
 * multi-day run's hours belong to its first day, so the end is left alone.
 */
function hoursError(
  start: number | null,
  end: number | null,
  singleDay: boolean
): string | null {
  if (start === null || end === null) return null;
  if (!singleDay) return null;
  return end <= start ? 'A date cannot end before it starts.' : null;
}

/** The hours a write leaves behind, both ends or neither. */
function hoursOf(body: { startMinutes?: number | null; endMinutes?: number | null }) {
  if (body.startMinutes === null || body.endMinutes === null) {
    return { startMinutes: null, endMinutes: null };
  }
  return { startMinutes: body.startMinutes ?? null, endMinutes: body.endMinutes ?? null };
}

export const ownerCreateEvent = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const track = await loadOwnedTrack(req, res);
    if (!track) return;
    const body = eventSchema.parse(req.body);
    const startsAt = toDate(body.startsAt);
    const endsAt = body.endsAt ? toDate(body.endsAt) : null;
    const outOfOrder = orderError(startsAt, endsAt);
    if (outOfOrder) return res.status(400).json(error(outOfOrder));
    const hours = hoursOf(body);
    const badHours = hoursError(
      hours.startMinutes ?? null,
      hours.endMinutes ?? null,
      endsAt === null || endsAt.getTime() === startsAt.getTime()
    );
    if (badHours) return res.status(400).json(error(badHours));
    const event = await prisma.trackEvent.create({
      data: {
        trackId: track.id,
        title: body.title,
        description: body.description ?? null,
        kind: body.kind,
        startsAt,
        endsAt,
        ...hours,
        isActive: body.isActive ?? true,
      },
    });
    await prisma.auditLog.create({
      data: { actorId: req.user!.id, action: 'CREATE', entity: 'TrackEvent', entityId: event.id },
    });
    res.status(201).json(success({ event }, 'Event added.'));
  } catch (err) {
    next(err);
  }
};

export const ownerUpdateEvent = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const track = await loadOwnedTrack(req, res);
    if (!track) return;
    const id = req.params.id as string;
    const existing = await prisma.trackEvent.findUnique({ where: { id } });
    if (!existing || existing.trackId !== track.id) {
      return res.status(404).json(error('Event not found.'));
    }
    const body = eventSchema.partial().parse(req.body);
    const nextStart = body.startsAt ? toDate(body.startsAt) : existing.startsAt;
    const nextEnd =
      body.endsAt !== undefined ? (body.endsAt ? toDate(body.endsAt) : null) : existing.endsAt;
    const outOfOrder = orderError(nextStart, nextEnd);
    if (outOfOrder) return res.status(400).json(error(outOfOrder));
    const nextHours = hoursOf({
      startMinutes: body.startMinutes !== undefined ? body.startMinutes : existing.startMinutes,
      endMinutes: body.endMinutes !== undefined ? body.endMinutes : existing.endMinutes,
    });
    const badHours = hoursError(
      nextHours.startMinutes ?? null,
      nextHours.endMinutes ?? null,
      nextEnd === null || nextEnd.getTime() === nextStart.getTime()
    );
    if (badHours) return res.status(400).json(error(badHours));
    const event = await prisma.trackEvent.update({
      where: { id },
      data: {
        ...(body.title !== undefined ? { title: body.title } : {}),
        ...(body.description !== undefined ? { description: body.description || null } : {}),
        ...(body.kind !== undefined ? { kind: body.kind } : {}),
        ...(body.startsAt ? { startsAt: nextStart } : {}),
        ...(body.endsAt !== undefined ? { endsAt: nextEnd } : {}),
        ...(body.startMinutes !== undefined || body.endMinutes !== undefined ? nextHours : {}),
        ...(body.isActive !== undefined ? { isActive: body.isActive } : {}),
      },
    });
    res.json(success({ event }, 'Event saved.'));
  } catch (err) {
    next(err);
  }
};

export const ownerDeleteEvent = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const track = await loadOwnedTrack(req, res);
    if (!track) return;
    const id = req.params.id as string;
    const existing = await prisma.trackEvent.findUnique({ where: { id } });
    if (!existing || existing.trackId !== track.id) {
      return res.status(404).json(error('Event not found.'));
    }
    await prisma.trackEvent.delete({ where: { id } });
    await prisma.auditLog.create({
      data: { actorId: req.user!.id, action: 'DELETE', entity: 'TrackEvent', entityId: id },
    });
    res.json(success({ id }, 'Event removed.'));
  } catch (err) {
    next(err);
  }
};

// ---------------------------------------------------------------------------
// Banner / logo upload
// ---------------------------------------------------------------------------

const DATA_URL = /^data:image\/(png|jpeg|jpg|webp|gif|avif);base64,([A-Za-z0-9+/=]+)$/;
const EXT: Record<string, string> = { png: 'png', jpeg: 'jpg', jpg: 'jpg', webp: 'webp', gif: 'gif', avif: 'avif' };

/**
 * The console has no bucket, so an uploaded image arrives as a data URL, is
 * written into the server's uploads dir under a random name, and comes back as
 * a path under /api/uploads — which is what lands in `bannerUrl`/`logoUrl`, and
 * in a gallery photo's `url`.
 *
 * `replacePrefix` removes any older file in the same slot first (banner/logo are
 * one slot each); photos pass null because a venue has many.
 */
export function storeDataUrl(
  slug: string,
  kind: string,
  dataUrl: string,
  replacePrefix: string | null
): { url: string } | { status: number; message: string } {
  const match = DATA_URL.exec(dataUrl.trim());
  if (!match) return { status: 400, message: 'Upload a PNG, JPG, WEBP, GIF or AVIF image.' };
  const bytes = Buffer.from(match[2], 'base64');
  if (bytes.length > config.uploads.maxBytes) {
    return { status: 413, message: 'That image is too large — keep it under 5 MB.' };
  }
  fs.mkdirSync(config.uploads.dir, { recursive: true });
  if (replacePrefix) {
    for (const f of fs.readdirSync(config.uploads.dir)) {
      if (f.startsWith(replacePrefix)) fs.rmSync(path.join(config.uploads.dir, f), { force: true });
    }
  }
  const file = `${slug}-${kind}-${randomUUID().slice(0, 8)}.${EXT[match[1]]}`;
  fs.writeFileSync(path.join(config.uploads.dir, file), bytes);
  return { url: `${config.uploads.publicPath}/${file}` };
}

/** A photo URL the owner uploaded lives under the uploads dir — drop the file
 *  when the row goes, so the directory does not grow forever. */
export function removeUploadedFile(url: string) {
  const prefix = `${config.uploads.publicPath}/`;
  if (!url.startsWith(prefix)) return;
  const name = path.basename(url);
  fs.rmSync(path.join(config.uploads.dir, name), { force: true });
}

export const ownerUploadAsset = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const track = await loadOwnedTrack(req, res);
    if (!track) return;
    const body = z
      .object({
        kind: z.enum(['banner', 'logo']),
        dataUrl: z.string(),
      })
      .parse(req.body);

    const saved = storeDataUrl(track.slug, body.kind, body.dataUrl, `${track.slug}-${body.kind}-`);
    if ('status' in saved) return res.status(saved.status).json(error(saved.message));
    res.status(201).json(success({ url: saved.url }, 'Image uploaded.'));
  } catch (err) {
    next(err);
  }
};

// ---------------------------------------------------------------------------
// Gallery photos
// ---------------------------------------------------------------------------

/** A venue's gallery is bounded — beyond this the profile is a photo dump, not
 *  a profile. The console hides the add control at the cap. */
const MAX_PHOTOS = 24;

const photoAddSchema = z.object({
  /** Either an uploaded data URL or an image URL already hosted elsewhere. */
  dataUrl: z.string().optional(),
  url: z.string().max(600).optional(),
  category: z.enum(TRACK_PHOTO_CATEGORY_VALUES).default(TrackPhotoCategory.TRACK),
  caption: z.string().max(200).optional(),
});

const photoEditSchema = z.object({
  category: z.enum(TRACK_PHOTO_CATEGORY_VALUES).optional(),
  caption: z.string().max(200).optional(),
});

export const ownerAddPhoto = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const track = await loadOwnedTrack(req, res);
    if (!track) return;
    if (track.photos.length >= MAX_PHOTOS) {
      return res.status(400).json(error(`A venue gallery holds ${MAX_PHOTOS} photos — remove one first.`));
    }
    const body = photoAddSchema.parse(req.body);

    let url = body.url?.trim() ?? '';
    if (body.dataUrl) {
      const saved = storeDataUrl(track.slug, 'photo', body.dataUrl, null);
      if ('status' in saved) return res.status(saved.status).json(error(saved.message));
      url = saved.url;
    }
    if (!url) return res.status(400).json(error('Pick a file or paste an image URL.'));

    const photo = await prisma.trackPhoto.create({
      data: {
        trackId: track.id,
        url,
        category: body.category,
        caption: body.caption?.trim() || null,
        sortOrder: track.photos.length ? Math.max(...track.photos.map((p) => p.sortOrder)) + 1 : 0,
      },
    });
    await prisma.auditLog.create({
      data: { actorId: req.user!.id, action: 'CREATE', entity: 'TrackPhoto', entityId: photo.id },
    });
    res.status(201).json(success({ photo }, 'Photo added.'));
  } catch (err) {
    next(err);
  }
};

export const ownerUpdatePhoto = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const track = await loadOwnedTrack(req, res);
    if (!track) return;
    const id = req.params.id as string;
    if (!track.photos.some((p) => p.id === id)) {
      return res.status(404).json(error('Photo not found.'));
    }
    const body = photoEditSchema.parse(req.body);
    const photo = await prisma.trackPhoto.update({
      where: { id },
      data: {
        ...(body.category !== undefined ? { category: body.category } : {}),
        ...(body.caption !== undefined ? { caption: body.caption.trim() || null } : {}),
      },
    });
    res.json(success({ photo }, 'Photo saved.'));
  } catch (err) {
    next(err);
  }
};

/** The gallery order is the row order, so a move is a rewrite of `sortOrder`. */
export const ownerReorderPhotos = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const track = await loadOwnedTrack(req, res);
    if (!track) return;
    const body = z.object({ ids: z.array(z.string()) }).parse(req.body);
    const owned = new Set(track.photos.map((p) => p.id));
    if (body.ids.length !== owned.size || body.ids.some((id) => !owned.has(id))) {
      return res.status(400).json(error('That is not this venue’s whole gallery.'));
    }
    for (const [i, id] of body.ids.entries()) {
      await prisma.trackPhoto.update({ where: { id }, data: { sortOrder: i } });
    }
    const photos = await prisma.trackPhoto.findMany({
      where: { trackId: track.id },
      orderBy: [{ sortOrder: 'asc' }, { createdAt: 'asc' }],
    });
    res.json(success({ photos }, 'Gallery reordered.'));
  } catch (err) {
    next(err);
  }
};

export const ownerDeletePhoto = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const track = await loadOwnedTrack(req, res);
    if (!track) return;
    const id = req.params.id as string;
    const existing = track.photos.find((p) => p.id === id);
    if (!existing) return res.status(404).json(error('Photo not found.'));
    await prisma.trackPhoto.delete({ where: { id } });
    removeUploadedFile(existing.url);
    await prisma.auditLog.create({
      data: { actorId: req.user!.id, action: 'DELETE', entity: 'TrackPhoto', entityId: id },
    });
    res.json(success({ id }, 'Photo removed.'));
  } catch (err) {
    next(err);
  }
};

