// Followers
// ---------------------------------------------------------------------------

const DAY_MS = 864e5;

/**
 * The operator's audience: every account following the venue, the pass each one
 * holds, and how much it has actually ridden here.
 *
 * Following is the one thing a free account can do, so this list is the venue's
 * soft pipeline — riders watching the gate before they buy beside members who
 * are already through it every weekend. Read-only: a follow is the rider's to
 * give and to take, so there is no control here, only the read.
 *
 * The pass is picked the way `getCurrentPass` picks it (a paid active pass beats
 * the free default, then any active, then the latest), so a follower's badge
 * here agrees with the badge on their own profile.
 */
export const ownerFollowers = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const trackId = resolveTrackId(req);
    if (!trackId) {
      return res.status(400).json(error('No track is pinned to this account.'));
    }
    const track = await prisma.track.findUnique({
      where: { id: trackId },
      select: { id: true, name: true, slug: true },
    });
    if (!track) return res.status(404).json(error('Track not found.'));

    const follows = await prisma.trackFollow.findMany({
      where: { trackId },
      include: {
        user: { select: { id: true, name: true, email: true, location: true, avatarUrl: true } },
      },
      orderBy: { createdAt: 'desc' },
    });
    const userIds = follows.map((f) => f.userId);

    // Two reads for the whole page rather than one per follower: every pass the
    // audience holds, and how many days each of them has ridden at this venue.
    const passes = userIds.length
      ? await prisma.pass.findMany({
          where: { userId: { in: userIds } },
          include: { tier: true },
          orderBy: [{ seasonYear: 'desc' }, { createdAt: 'desc' }],
        })
      : [];
    const rides = userIds.length
      ? await prisma.redemption.groupBy({
          by: ['userId'],
          where: { trackId, userId: { in: userIds } },
          _count: { _all: true },
          _max: { day: true },
        })
      : [];

    const passFor = (userId: string) => {
      const mine = passes.filter((p) => p.userId === userId);
      const active = mine.filter((p) => p.status === PassStatus.ACTIVE);
      const paid = active
        .filter((p) => !p.tier.isDefault)
        .sort((a, b) => b.tier.priceCents - a.tier.priceCents)[0];
      return paid ?? active[0] ?? mine[0] ?? null;
    };

    const followers = follows.map((f) => {
      const pass = passFor(f.userId);
      const ride = rides.find((r) => r.userId === f.userId);
      return {
        id: f.id,
        userId: f.userId,
        name: f.user.name,
        email: f.user.email,
        location: f.user.location,
        avatarUrl: f.user.avatarUrl,
        followedAt: f.createdAt,
        tierName: pass?.tier.name ?? null,
        // Paying means an active pass that is not the free tier — a lapsed or
        // still-pending pass counts alongside a free account here.
        paid: Boolean(pass && pass.status === PassStatus.ACTIVE && !pass.tier.isDefault),
        passStatus: pass?.status ?? null,
        visits: ride?._count._all ?? 0,
        lastRideDay: ride?._max.day ?? null,
      };
    });

    // What the community has written about the venue. A third read for the whole
    // page: the riders' reviews, newest first, with who wrote each and the frames
    // they attached. One per rider, so this list is bounded by the audience.
    const reviews = await prisma.trackReview.findMany({
      where: { trackId },
      orderBy: { createdAt: 'desc' },
      select: {
        id: true,
        rating: true,
        body: true,
        createdAt: true,
        updatedAt: true,
        userId: true,
        user: { select: { name: true, avatarUrl: true } },
        photos: {
          orderBy: [{ sortOrder: 'asc' }, { createdAt: 'asc' }],
          select: { id: true, url: true, caption: true },
        },
      },
    });

    const since = new Date(Date.now() - 30 * DAY_MS);
    res.json(
      success({
        track,
        summary: {
          total: followers.length,
          newLast30: followers.filter((f) => f.followedAt >= since).length,
          paying: followers.filter((f) => f.paid).length,
          free: followers.filter((f) => !f.paid).length,
          riddenHere: followers.filter((f) => f.visits > 0).length,
          reviews: reviews.length,
        },
        followers,
        reviews: reviews.map((r) => ({
          id: r.id,
          rating: r.rating,
          body: r.body,
          createdAt: r.createdAt,
          updatedAt: r.updatedAt,
          userId: r.userId,
          riderName: r.user.name,
          riderAvatarUrl: r.user.avatarUrl,
          photos: r.photos.map((p) => ({ id: p.id, url: p.url, caption: p.caption })),
        })),
      })
    );
  } catch (err) {
    next(err);
  }
};

/** The status values a profile may be set to — exported for the admin route's schema. */
export const TRACK_STATUS_VALUES = [TrackStatus.OPEN, TrackStatus.WEATHER_HOLD, TrackStatus.CLOSED] as const;

import { Response, NextFunction } from 'express';
import { AuthRequest } from '../types';
import { prisma } from '../utils/prisma';
import { success, error } from '../utils/apiResponse';
import { getCurrentPass, getEntitlements } from '../services/pass.service';
import { issueQrToken } from '../utils/qr';
import { PassStatus, Role } from '../types/enums';

/** Rider: current pass summary + expiry + tier. */
export const myPass = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const seasonYear = req.query.seasonYear ? Number(req.query.seasonYear) : undefined;
    const pass = await getCurrentPass(req.user!.id, seasonYear);
    if (!pass) return res.json(success({ pass: null, entitlements: [] }));

    const entitlements = await getEntitlements(req.user!.id, pass.id);
    res.json(
      success({
        pass: {
          id: pass.id,
          status: pass.status,
          seasonYear: pass.seasonYear,
          tier: {
            id: pass.tier.id,
            name: pass.tier.name,
            slug: pass.tier.slug,
            isDefault: pass.tier.isDefault,
          },
          /** True on the free tier: no included days, no member discount. */
          gated: pass.tier.isDefault,
          purchasedAt: pass.purchasedAt,
          activatedAt: pass.activatedAt,
          expiresAt: pass.expiresAt,
          daysUntilExpiry: Math.max(
            Math.ceil((pass.expiresAt.getTime() - Date.now()) / 86_400_000),
            0
          ),
        },
        entitlements,
      })
    );
  } catch (err) {
    next(err);
  }
};

/** Rider: short-lived, signed QR token (rotates to prevent screenshot replay). */
export const qrToken = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const pass = await getCurrentPass(req.user!.id);
    if (!pass) return res.status(404).json(error('No pass found for this account.'));
    if (pass.status !== PassStatus.ACTIVE) {
      return res
        .status(409)
        .json(error(`Pass is ${pass.status.toLowerCase()} — a QR code is not available.`));
    }
    const { token, expiresAt, nonce } = issueQrToken(pass.id, req.user!.id);
    res.json(success({ token, expiresAt, nonce, passId: pass.id }));
  } catch (err) {
    next(err);
  }
};

/** Rider: scan / redemption history. */
export const myHistory = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const redemptions = await prisma.redemption.findMany({
      where: { userId: req.user!.id },
      include: { track: true },
      orderBy: { redeemedAt: 'desc' },
      take: 100,
    });
    res.json(
      success({
        redemptions: redemptions.map((r) => ({
          id: r.id,
          trackName: r.track.name,
          trackWebsite: r.track.website,
          kind: r.kind,
          day: r.day,
          redeemedAt: r.redeemedAt,
          amountChargedCents: r.amountChargedCents,
        })),
      })
    );
  } catch (err) {
    next(err);
  }
};

/** Rider: denied scan attempts (so they can see why a scan failed). */
export const myDeniedScans = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const events = await prisma.scanEvent.findMany({
      where: { userId: req.user!.id, result: 'DENIED' },
