/** Rider: perks & discount codes attached to the pass. */
export const myPerks = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const pass = await getCurrentPass(req.user!.id);
    const now = new Date();
    const perks = await prisma.perk.findMany({
      where: {
        isActive: true,
        OR: [{ tierId: null }, ...(pass ? [{ tierId: pass.tierId }] : [])],
        AND: [
          { OR: [{ validFrom: null }, { validFrom: { lte: now } }] },
          { OR: [{ validTo: null }, { validTo: { gte: now } }] },
        ],
      },
      include: { track: true },
      orderBy: { title: 'asc' },
    });
    const used = await prisma.perkRedemption.findMany({
      where: { userId: req.user!.id },
      select: { perkId: true },
    });
    const usedSet = new Set(used.map((u) => u.perkId));
    res.json(
      success({
        perks: perks.map((p) => ({
          id: p.id,
          code: p.code,
          title: p.title,
          description: p.description,
          discountType: p.discountType,
          value: p.value,
          trackId: p.trackId,
          trackName: p.track?.name ?? null,
          trackWebsite: p.track?.website ?? null,
          redeemed: usedSet.has(p.id),
        })),
      })
    );
  } catch (err) {
    next(err);
  }
};

/** Rider: redeem a perk code (validated server-side). */
export const redeemPerk = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const code = String(req.params.code || '').toUpperCase();
    const perk = await prisma.perk.findUnique({ where: { code } });
    if (!perk || !perk.isActive) return res.status(404).json(error('That code is not valid.'));

    const already = await prisma.perkRedemption.findFirst({
      where: { perkId: perk.id, userId: req.user!.id },
    });
    if (already) return res.status(409).json(error('You have already redeemed this offer.'));

    const now = new Date();
    if (perk.validFrom && perk.validFrom > now) {
      return res.status(400).json(error('This offer is not active yet.'));
    }
    if (perk.validTo && perk.validTo < now) {
      return res.status(400).json(error('This offer has expired.'));
    }

    await prisma.perkRedemption.create({ data: { perkId: perk.id, userId: req.user!.id } });
    res.json(success({ perk: { code: perk.code, title: perk.title } }, 'Offer redeemed.'));
  } catch (err) {
    next(err);
  }
};

// ---------------------------------------------------------------------------
// Following a track — the one thing a free-tier account does with the network.
// ---------------------------------------------------------------------------

function publicFollow(f: {
  trackId: string;
  createdAt: Date;
  track: {
    slug: string;
    name: string;
    city: string | null;
    region: string | null;
    status: string;
    statusNote: string | null;
    hours: string | null;
    nextEvent: string | null;
  };
}) {
  return {
    trackId: f.trackId,
    slug: f.track.slug,
    name: f.track.name,
    city: f.track.city,
    region: f.track.region,
    status: f.track.status,
    statusNote: f.track.statusNote,
    hours: f.track.hours,
    nextEvent: f.track.nextEvent,
    followedAt: f.createdAt,
  };
}

/** Rider: the tracks this account follows. Operators cannot follow — they own
 *  a venue and read its audience on the followers page instead. */
export const myFollows = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    if (req.user!.role === Role.OPERATOR) {
      return res.status(403).json(error('Operator accounts cannot follow tracks.'));
    }
    const rows = await prisma.trackFollow.findMany({
      where: { userId: req.user!.id },
      include: { track: true },
      orderBy: { createdAt: 'desc' },
    });
    res.json(success({ follows: rows.map(publicFollow) }));
  } catch (err) {
    next(err);
  }
};

/** Rider: follow a track. Idempotent — following twice is not an error.
 *  Operators cannot follow: an operator account owns a venue rather than
 *  following it. */
export const followTrack = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    if (req.user!.role === Role.OPERATOR) {
      return res.status(403).json(error('Operator accounts cannot follow tracks.'));
    }
    const trackId = String(req.params.trackId || '');
    const track = await prisma.track.findUnique({ where: { id: trackId } });
    if (!track || !track.isActive) return res.status(404).json(error('Track not found.'));

    const row = await prisma.trackFollow.upsert({
      where: { userId_trackId: { userId: req.user!.id, trackId } },
      create: { userId: req.user!.id, trackId },
      update: {},
      include: { track: true },
    });
    res.json(success({ following: true, follow: publicFollow(row) }, `Following ${track.name}.`));
  } catch (err) {
    next(err);
  }
};

/** Rider: stop following a track. Operators cannot follow, like the follow itself. */
export const unfollowTrack = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    if (req.user!.role === Role.OPERATOR) {
      return res.status(403).json(error('Operator accounts cannot follow tracks.'));
    }
    const trackId = String(req.params.trackId || '');
    await prisma.trackFollow.deleteMany({ where: { userId: req.user!.id, trackId } });
    res.json(success({ following: false }, 'No longer following that track.'));
  } catch (err) {
    next(err);
  }
};

/**
 * Rider: the calendar — every active date at the tracks this account follows,
 * each one carrying the venue it belongs to.
 *
 * It is the follows list read as a schedule, so it comes and goes with the same
 * control: a rider on any tier (free included) gets their own calendar, and a
 * track they stop following leaves it. `?trackId=` narrows the read to one of
 * the tracks they follow, which is what the page's track filter asks for.
 */
export const myCalendar = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    if (req.user!.role === Role.OPERATOR) {
      return res.status(403).json(error('Operator accounts cannot follow tracks.'));
    }
    const asked = req.query.trackId ? String(req.query.trackId) : null;
    const rows = await prisma.trackFollow.findMany({
      where: { userId: req.user!.id, ...(asked ? { trackId: asked } : {}) },
      include: { track: true },
      orderBy: { createdAt: 'desc' },
    });
    const follows = rows.map(publicFollow);
    const events = rows.length
      ? await prisma.trackEvent.findMany({
          where: { isActive: true, trackId: { in: rows.map((r) => r.trackId) } },
          orderBy: { startsAt: 'asc' },
        })
      : [];
    // The venue rides on the date: a calendar of several tracks has to name the
    // track each date belongs to, and the page reads the slug for the link and
    // the category for the badge.
    const byId = new Map(rows.map((r) => [r.trackId, r.track]));
    res.json(
      success({
        follows,
        events: events.map((e) => {
          const t = byId.get(e.trackId);
          return {
            id: e.id,
            title: e.title,
            description: e.description,
            kind: e.kind,
            startsAt: e.startsAt,
            endsAt: e.endsAt,
            startMinutes: e.startMinutes,
            endMinutes: e.endMinutes,
            trackId: e.trackId,
            trackSlug: t?.slug ?? '',
            trackName: t?.name ?? '',
            trackCategory: t?.category ?? null,
          };
        }),
      })
    );
  } catch (err) {
    next(err);
  }
};

import { Request, Response, NextFunction } from 'express';
import { z } from 'zod';
import Stripe from 'stripe';
import { PassStatus, PaymentStatus } from '../types/enums';
import { AuthRequest } from '../types';
import { prisma } from '../utils/prisma';
import { success, error } from '../utils/apiResponse';
import config from '../config';
import { activatePass } from '../services/pass.service';
import logger from '../utils/logger';

const stripe = config.stripe.secretKey && !config.stripe.secretKey.includes('placeholder')
  ? new Stripe(config.stripe.secretKey, { apiVersion: '2024-12-18.acacia' as Stripe.LatestApiVersion })
  : null;

/**
 * Create a checkout session for a pass tier.
 * Creates a PENDING pass + PENDING payment first, then a Stripe Checkout
 * Session pointing at it. The pass is only activated by the webhook.
 */
export const createCheckout = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const body = z.object({ tierId: z.string().uuid() }).parse(req.body);

    const tier = await prisma.passTier.findUnique({ where: { id: body.tierId } });
    if (!tier || !tier.isActive) return res.status(404).json(error('That pass tier is unavailable.'));

    const season = await prisma.season.findFirst({
      where: { isActive: true },
      orderBy: { year: 'desc' },
    });
    if (!season) return res.status(400).json(error('No active season is configured.'));

    const pass = await prisma.pass.create({
      data: {
        userId: req.user!.id,
        tierId: tier.id,
        seasonId: season.id,
        seasonYear: season.year,
        status: PassStatus.PENDING,
        expiresAt: season.endsAt,
      },
    });

    // Early-bird pricing wins while it is still in effect.
    const earlyBirdActive =
      tier.earlyBirdPriceCents != null && (!tier.earlyBirdEndsAt || tier.earlyBirdEndsAt > new Date());
    const amountCents = earlyBirdActive ? tier.earlyBirdPriceCents! : tier.priceCents;

    const payment = await prisma.payment.create({
      data: {
        userId: req.user!.id,
        passId: pass.id,
        tierId: tier.id,
        amountCents,
        status: PaymentStatus.PENDING,
      },
    });

    if (!stripe) {
      // Dev mode: no real keys. Return the session id so the dev-simulate
      // endpoint (or a real webhook once keys are set) can complete it.
      return res.json(
        success(
          {
            devMode: true,
            passId: pass.id,
            paymentId: payment.id,
            sessionId: `dev_session_${payment.id}`,
            amountCents,
            message:
              'Stripe keys are placeholders — use the dev simulator to complete this purchase, or set real keys in .env.',
          },
          'Checkout created (dev mode).'
        )
      );
    }

    const origin = config.corsOrigin;
    const session = await stripe.checkout.sessions.create({
      mode: 'payment',
      customer_email: req.user!.email,
      line_items: [
        {
          quantity: 1,
          price_data: {
            currency: 'usd',
            unit_amount: amountCents,
            product_data: {
              name: `${tier.name} — ${season.year} Annual Pass`,
              description: tier.tagline ?? undefined,
            },
          },
        },
      ],
      metadata: { passId: pass.id, paymentId: payment.id, userId: req.user!.id, tierId: tier.id },
      success_url: `${origin}/rider?checkout=success&pass=${pass.id}`,
      cancel_url: `${origin}/pricing?checkout=cancelled`,
    });

    await prisma.pass.update({ where: { id: pass.id }, data: { stripeSessionId: session.id } });
    await prisma.payment.update({
      where: { id: payment.id },
      data: { stripeSessionId: session.id },
    });

    res.json(success({ url: session.url, sessionId: session.id, passId: pass.id, amountCents }));
  } catch (err) {
    next(err);
  }
};

/** Shared completion logic used by both the webhook and the dev simulator. */
export async function completePayment(args: {
  passId: string;
  paymentId: string;
  stripeSessionId?: string;
  stripePaymentIntentId?: string;
  stripeCustomerId?: string;
  stripeEventId?: string;
}) {
  await prisma.payment.update({
    where: { id: args.paymentId },
    data: {
      status: PaymentStatus.PAID,
      stripeSessionId: args.stripeSessionId,
      stripePaymentIntentId: args.stripePaymentIntentId,
      stripeCustomerId: args.stripeCustomerId,
      stripeEventId: args.stripeEventId,
    },
  });
  await prisma.pass.update({
    where: { id: args.passId },
    data: {
      stripeSessionId: args.stripeSessionId,
      stripeCustomerId: args.stripeCustomerId,
      stripeSubscriptionId: args.stripePaymentIntentId,
    },
  });
  const activated = await activatePass(args.passId);
  logger.info(`Pass activated via payment: ${activated.id}`);
  return activated;
}

/**
 * Stripe webhook. Mounted with express.raw so the signature can be verified.
 */
export const stripeWebhook = async (req: Request, res: Response) => {
  const signature = req.headers['stripe-signature'] as string | undefined;

  if (!stripe || !config.stripe.webhookSecret || config.stripe.webhookSecret.includes('placeholder')) {
    logger.warn('Stripe webhook received but Stripe is not configured.');
    return res.status(503).json(error('Stripe is not configured.'));
  }
  if (!signature) return res.status(400).json(error('Missing Stripe signature.'));

  let event: Stripe.Event;
  try {
    event = stripe.webhooks.constructEvent(req.body, signature, config.stripe.webhookSecret);
  } catch (err: any) {
    logger.warn(`Stripe webhook signature verification failed: ${err.message}`);
    return res.status(400).json(error(`Webhook signature verification failed.`));
  }

  try {
    switch (event.type) {
      case 'checkout.session.completed': {
        const session = event.data.object as Stripe.Checkout.Session;
        const md = session.metadata ?? {};
        if (md.passId && md.paymentId) {
          await completePayment({
            passId: md.passId,
            paymentId: md.paymentId,
            stripeSessionId: session.id,
            stripePaymentIntentId: String(session.payment_intent ?? ''),
            stripeCustomerId: String(session.customer ?? ''),
            stripeEventId: event.id,
          });
        }
        break;
      }
      case 'checkout.session.expired': {
        const session = event.data.object as Stripe.Checkout.Session;
        const md = session.metadata ?? {};
        if (md.paymentId) {
          await prisma.payment.update({
            where: { id: md.paymentId },
            data: { status: PaymentStatus.FAILED },
          });
          await prisma.pass.update({ where: { id: md.passId }, data: { status: PassStatus.CANCELLED } });
        }
        break;
      }
      case 'charge.refunded': {
        const charge = event.data.object as Stripe.Charge;
        await prisma.payment.updateMany({
          where: { stripePaymentIntentId: charge.payment_intent as string },
          data: { status: PaymentStatus.REFUNDED },
        });
        break;
      }
      default:
        logger.debug(`Unhandled Stripe event: ${event.type}`);
    }
    res.json({ received: true });
  } catch (err: any) {
    logger.error(`Stripe webhook handling failed: ${err.message}`);
    res.status(500).json(error('Webhook handling failed.'));
  }
};

/**
 * Dev-only simulator: drives the same completion path as the webhook so the
 * purchase → activation round trip can be verified without live Stripe keys.
 */
export const devSimulatePayment = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    if (config.isProd) return res.status(404).json(error('Not found.'));
    const paymentId = req.params.paymentId as string;
    const payment = await prisma.payment.findUnique({ where: { id: paymentId } });
    if (!payment || !payment.passId) return res.status(404).json(error('Payment not found.'));
    if (payment.status === PaymentStatus.PAID) {
      return res.status(409).json(error('That payment is already complete.'));
    }
    if (payment.userId !== req.user!.id && req.user!.role === 'RIDER') {
      return res.status(403).json(error('Not your payment.'));
    }
    const pass = await completePayment({
      passId: payment.passId,
      paymentId: payment.id,
      stripeSessionId: payment.stripeSessionId ?? `dev_session_${payment.id}`,
      stripeEventId: `dev_evt_${payment.id}`,
    });
    res.json(success({ pass }, 'Payment completed (dev simulator) — pass activated.'));
  } catch (err) {
    next(err);
  }
};

