import { Response, NextFunction } from 'express';
import { AuthRequest } from '../types';
import { prisma } from '../utils/prisma';
import { success, error } from '../utils/apiResponse';
import { toCsv } from '../utils/csv';
import { formatDay } from '../utils/dates';

/**
 * QuickBooks integration layer.
 *
 * Exports users, subscriptions (passes) and payments in shapes that map to
 * QuickBooks Online import templates (Customers, Invoices, Sales Receipts).
 * Structured so a live API sync can be layered on later: each row carries the
 * QuickBooks-facing field names plus an external key for reconciliation.
 */

type ExportKind = 'customers' | 'subscriptions' | 'payments';

async function buildCustomers() {
  const users = await prisma.user.findMany({ orderBy: { createdAt: 'asc' } });
  return users.map((u) => ({
    'Customer Name': u.name,
    Company: '',
    'Display Name': u.name,
    'Primary Email': u.email,
    'Primary Phone': u.phone ?? '',
    'External Key': u.id,
    'Notes / Role': u.role,
    Active: u.isActive ? 'Yes' : 'No',
  }));
}

async function buildSubscriptions() {
  const passes = await prisma.pass.findMany({
    include: { user: true, tier: true, season: true },
    orderBy: { purchasedAt: 'asc' },
  });
  return passes.map((p) => ({
    'Customer Name': p.user.name,
    'Primary Email': p.user.email,
    'Product/Service': `${p.tier.name} Annual Pass`,
    'Season': String(p.seasonYear),
    'Subscription Status': p.status,
    'Start Date': formatDay(p.activatedAt ?? p.purchasedAt),
    'End Date': formatDay(p.expiresAt),
    'Qty': '1',
    'Rate': (p.tier.priceCents / 100).toFixed(2),
    'Amount': (p.tier.priceCents / 100).toFixed(2),
    'External Key': p.id,
    'Tier': p.tier.slug,
  }));
}

async function buildPayments() {
  const payments = await prisma.payment.findMany({
    include: { user: true, tier: true },
    orderBy: { createdAt: 'asc' },
  });
  return payments.map((p) => ({
    'Customer Name': p.user.name,
    'Primary Email': p.user.email,
    'Transaction Date': formatDay(p.createdAt),
    'Payment Method': 'Stripe',
    'Reference #': p.stripePaymentIntentId ?? p.stripeSessionId ?? p.id,
    'Memo': p.tier ? `${p.tier.name} Annual Pass` : 'Pass purchase',
    'Amount': (p.amountCents / 100).toFixed(2),
    'Status': p.status,
    'External Key': p.id,
  }));
}

const builders: Record<ExportKind, () => Promise<Record<string, string>[]>> = {
  customers: buildCustomers,
  subscriptions: buildSubscriptions,
  payments: buildPayments,
};

export const quickbooksExport = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const kind = (req.query.type as ExportKind) || 'customers';
    const format = (req.query.format as string) || 'json';
    if (!builders[kind]) {
      return res.status(400).json(error('type must be one of customers, subscriptions, payments.'));
    }

    const rows = await builders[kind]();

    if (format === 'csv') {
      res.setHeader('Content-Type', 'text/csv; charset=utf-8');
      res.setHeader(
        'Content-Disposition',
        `attachment; filename="quickbooks-${kind}-${formatDay(new Date())}.csv"`
      );
      return res.send(toCsv(rows));
    }

    res.json(
      success({
        export: kind,
        generatedAt: new Date().toISOString(),
        rowCount: rows.length,
        columns: rows[0] ? Object.keys(rows[0]) : [],
        rows,
      })
    );
  } catch (err) {
    next(err);
  }
};

/** A single manifest describing every available export. */
export const quickbooksManifest = async (_req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const [customers, subscriptions, payments] = await Promise.all([
      buildCustomers(),
      buildSubscriptions(),
      buildPayments(),
    ]);
    res.json(
      success({
        generatedAt: new Date().toISOString(),
        exports: [
          { kind: 'customers', label: 'Customers', rowCount: customers.length, columns: Object.keys(customers[0] ?? {}) },
          { kind: 'subscriptions', label: 'Subscriptions (Invoices)', rowCount: subscriptions.length, columns: Object.keys(subscriptions[0] ?? {}) },
          { kind: 'payments', label: 'Payments (Sales Receipts)', rowCount: payments.length, columns: Object.keys(payments[0] ?? {}) },
        ],
      })
    );
  } catch (err) {
    next(err);
  }
};

import { Response, NextFunction } from 'express';
import { z } from 'zod';
import { ReservationStatus } from '../types/enums';
import { AuthRequest } from '../types';
import { prisma } from '../utils/prisma';
import { success, error } from '../utils/apiResponse';
import { getCurrentPass } from '../services/pass.service';
import { dayKey, todayKey } from '../utils/dates';

const createSchema = z.object({
  trackId: z.string().uuid(),
  date: z.string().min(8), // YYYY-MM-DD
  note: z.string().max(500).optional(),
});

export const listReservations = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const reservations = await prisma.reservation.findMany({
      where: { userId: req.user!.id },
      include: { track: true },
      orderBy: [{ date: 'desc' }, { createdAt: 'desc' }],
    });
    res.json(success({ reservations }));
  } catch (err) {
    next(err);
  }
};

export const createReservation = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const { trackId, date, note } = createSchema.parse(req.body);
    const pass = await getCurrentPass(req.user!.id);
    if (!pass || pass.status !== 'ACTIVE') {
      return res.status(409).json(error('You need an active pass to make a reservation.'));
    }

    const day = dayKey(date);
    if (day.getTime() < todayKey().getTime()) {
      return res.status(400).json(error('You cannot reserve a day in the past.'));
    }
    if (day.getTime() > pass.expiresAt.getTime()) {
      return res.status(400).json(error('That date is outside your pass season.'));
    }

    const allotment = await prisma.allotment.findUnique({
      where: {
        userId_trackId_seasonYear: { userId: req.user!.id, trackId, seasonYear: pass.seasonYear },
      },
    });
    if (!allotment) {
      return res.status(400).json(error('Your pass is not valid at that track.'));
    }

    const dup = await prisma.reservation.findFirst({
      where: {
        userId: req.user!.id,
        trackId,
        date: day,
        status: { in: [ReservationStatus.PENDING, ReservationStatus.CONFIRMED] },
      },
    });
    if (dup) return res.status(409).json(error('You already have a reservation at this track that day.'));

    const freeRemaining = Math.max(allotment.includedDays - allotment.freeDaysUsed, 0);
    const discountRemaining = Math.max(
      allotment.discountDaysAllowed - allotment.discountDaysUsed,
      0
    );
    if (freeRemaining <= 0 && !(allotment.discountDayEnabled && discountRemaining > 0)) {
      return res.status(409).json(error('No days remaining at this track this season.'));
    }

    const consumeNow = allotment.dayConsumePolicy === 'ON_CONFIRM' && freeRemaining > 0;

    const reservation = await prisma.$transaction(async (tx) => {
      const r = await tx.reservation.create({
        data: {
          userId: req.user!.id,
          trackId,
          passId: pass.id,
          date: day,
          status: ReservationStatus.CONFIRMED,
          note,
          dayConsumed: consumeNow,
          dayConsumedAt: consumeNow ? new Date() : null,
        },
        include: { track: true },
      });
      if (consumeNow) {
        await tx.allotment.update({
          where: { id: allotment.id },
          data: { freeDaysUsed: { increment: 1 } },
        });
      }
      return r;
    });

    res.status(201).json(
      success(
        {
          reservation,
          dayConsumed: consumeNow,
          message: consumeNow
            ? 'Reserved — one day has been deducted from your allotment at this track.'
            : 'Reserved — your day will be deducted at check-in.',
        },
        'Reservation confirmed.'
      )
    );
  } catch (err) {
    next(err);
  }
};

async function releaseConsumedDay(reservationId: string, userId: string) {
  const r = await prisma.reservation.findUnique({ where: { id: reservationId } });
  if (!r || !r.dayConsumed) return;
  const allotment = await prisma.allotment.findUnique({
    where: { userId_trackId_seasonYear: { userId, trackId: r.trackId, seasonYear: (await prisma.pass.findUnique({ where: { id: r.passId } }))!.seasonYear } },
  });
  if (!allotment) return;
  await prisma.allotment.update({
    where: { id: allotment.id },
    data: { freeDaysUsed: Math.max(allotment.freeDaysUsed - 1, 0) },
  });
}

export const cancelReservation = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const id = req.params.id as string;
    const r = await prisma.reservation.findUnique({ where: { id } });
    if (!r) return res.status(404).json(error('Reservation not found.'));
    if (r.userId !== req.user!.id && req.user!.role === 'RIDER') {
      return res.status(403).json(error('You cannot modify that reservation.'));
    }
    if (r.status === ReservationStatus.CANCELLED) {
      return res.status(409).json(error('That reservation is already cancelled.'));
    }
    if (r.status === ReservationStatus.COMPLETED) {
      return res.status(409).json(error('That reservation has already been used.'));
    }

    await prisma.reservation.update({
      where: { id },
      data: { status: ReservationStatus.CANCELLED },
    });
    if (r.dayConsumed) await releaseConsumedDay(id, r.userId);
    res.json(success(null, 'Reservation cancelled.'));
  } catch (err) {
    next(err);
  }
};

export const rescheduleReservation = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const id = req.params.id as string;
    const { date } = z.object({ date: z.string().min(8) }).parse(req.body);
    const r = await prisma.reservation.findUnique({ where: { id } });
    if (!r) return res.status(404).json(error('Reservation not found.'));
    if (r.userId !== req.user!.id && req.user!.role === 'RIDER') {
      return res.status(403).json(error('You cannot modify that reservation.'));
    }
    if (r.status === ReservationStatus.COMPLETED) {
      return res.status(409).json(error('That reservation has already been used.'));
    }

    const day = dayKey(date);
    if (day.getTime() < todayKey().getTime()) {
      return res.status(400).json(error('You cannot reschedule to a past date.'));
    }

    const updated = await prisma.reservation.update({
      where: { id },
      data: { date: day, status: ReservationStatus.CONFIRMED },
      include: { track: true },
    });
    res.json(success({ reservation: updated }, 'Reservation rescheduled.'));
  } catch (err) {
    next(err);
  }
};

import { Response, NextFunction } from 'express';
import { z } from 'zod';
import { AuthRequest } from '../types';
import { prisma } from '../utils/prisma';
import { success, error } from '../utils/apiResponse';
import { validateScan, completeReentry, gateDecision, gateStanding } from '../services/scan.service';
import { ReservationStatus } from '../types/enums';
import { getCurrentPass } from '../services/pass.service';
import { issueQrToken } from '../utils/qr';
import { dayKey, addDays, todayKey, seasonBounds } from '../utils/dates';
import { checkAnyLookupText, checkLookupInput, lookupQuerySchema } from '../utils/lookupInput';

/** How many of a rider's past redeemed days the gate view lists. */
const HISTORY_LIMIT = 6;

const scanSchema = z
  .object({
    token: z.string().min(10, 'Pass code is required').optional(),
    /** The other way in: the gate finds the rider and redeems their pass. */
    riderId: z.string().uuid().optional(),
    stationId: z.string().uuid().optional(),
    overrideReservation: z.boolean().optional(),
  })
  .refine((b) => Boolean(b.token) || Boolean(b.riderId), {
    message: 'A pass code or a rider is required',
    path: ['token'],
  });

/**
 * Resolve which track + station this scan belongs to.
 * Operators are pinned to their own track; admins may target any station.
 */
async function resolveStation(req: AuthRequest, stationId?: string) {
  if (stationId) {
    const station = await prisma.scanStation.findUnique({
      where: { id: stationId },
      include: { track: true },
    });
    if (!station || !station.isActive) return null;
    if (req.user!.role === 'OPERATOR' && req.user!.operatorTrackId !== station.trackId) {
      return null;
    }
    return station;
  }
  if (req.user!.role === 'OPERATOR' && req.user!.operatorTrackId) {
    const station = await prisma.scanStation.findFirst({
      where: { trackId: req.user!.operatorTrackId, isActive: true },
      include: { track: true },
    });
    if (station) return station;
    // Operator without a configured station still scans for their track.
    const track = await prisma.track.findUnique({ where: { id: req.user!.operatorTrackId } });
    if (!track) return null;
    return { id: null, trackId: track.id, name: 'Ticket window', track } as any;
  }
  return null;
}

export const scanValidate = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const body = scanSchema.parse(req.body);
    const station = await resolveStation(req, body.stationId);
    if (!station) {
      return res
        .status(400)
        .json(error('No scanning station is configured for your account. Ask an admin to assign one.'));
    }

    // The gate has two ways in: a scanned QR code, or a rider the operator
    // found by phone / email / id. A lookup mints the same short-lived signed
    // token the rider's own portal would, so both paths run the one validator
    // and every rule below (same day, allotment, reservation) is shared.
    let token = body.token;
    if (!token && body.riderId) {
      const [pass, rider] = await Promise.all([
        getCurrentPass(body.riderId),
        prisma.user.findUnique({ where: { id: body.riderId }, select: { name: true } }),
      ]);
      if (!pass) {
        // A rider with no pass on the account is a gate event too — keep it in
        // the ledger the operator reads back.
        await prisma.scanEvent.create({
          data: {
            trackId: station.trackId,
            stationId: station.id,
            userId: body.riderId,
            riderName: rider?.name ?? null,
            result: 'DENIED',
            reasonCode: 'NO_PASS',
            reason: 'This rider has no pass on their account.',
            operatorId: req.user!.id ?? null,
          },
        });
        const outcome = {
          result: 'DENIED' as const,
          reasonCode: 'NO_PASS',
          reason: 'This rider has no pass on their account.',
          approved: false,
          rider: rider ? { id: body.riderId, name: rider.name, email: '' } : undefined,
          track: { id: station.trackId, name: station.track.name },
        };
        return res.json(success(outcome));
      }
      token = issueQrToken(pass.id, pass.userId).token;
    }

    const outcome = await validateScan({
      token: token as string,
      trackId: station.trackId,
      stationId: station.id,
      operatorId: req.user!.id,
      overrideReservation: body.overrideReservation,
    });

    res.status(outcome.approved ? 200 : 200).json(success(outcome));
  } catch (err) {
    next(err);
  }
};

/**
 * TEST ONLY — mock a successful scan.
 *
 * The station's real doors both need a rider in hand: a phone to scan, or a
 * name to look up. This one skips both and answers with an approved outcome
 * built from a random rider who really holds a paying pass at this track, so
 * the outcome band, the rider block and the day counters can be walked with
 * nobody at the window.
 *
 * It writes nothing: no redemption, no allotment move, no scan event. That is
 * deliberate — the seed's day ledger is exactly what the demo accounts are
 * built on (who is out of days, who already rode today at 221 MX), and a mock
 * that spent days would rot those states after a handful of taps. The reason
 * line says so, so a reader can never mistake it for a real check-in.
 */
export const mockScan = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const body = z.object({ stationId: z.string().uuid().optional() }).parse(req.body ?? {});
    const station = await resolveStation(req, body.stationId);
    if (!station) {
      return res
        .status(400)
        .json(error('No scanning station is configured for your account. Ask an admin to assign one.'));
    }

    const now = Date.now();
    const allotments = await prisma.allotment.findMany({
      where: { trackId: station.trackId },
      include: { pass: { include: { tier: true, user: true } } },
      take: 500,
    });
    // A paying pass only — the free tier has no days to hand over.
    const pool = allotments.filter(
      (a) => a.pass.status === 'ACTIVE' && a.pass.expiresAt.getTime() > now && !a.pass.tier.isDefault
    );
    if (pool.length === 0) {
      return res.status(409).json(error('No rider holds a paying pass at this track. Reseed the demo data.'));
    }

    const pick = pool[Math.floor(Math.random() * pool.length)];
    const { pass } = pick;
    const freeRemaining = Math.max(pick.includedDays - pick.freeDaysUsed, 0);
    const outcome = {
      result: 'APPROVED' as const,
      approved: true,
      reasonCode: 'APPROVED',
      reason: 'Mock approval — no day was recorded.',
      kind: 'FREE' as const,
      amountChargedCents: 0,
      rider: { id: pass.user.id, name: pass.user.name, email: pass.user.email },
      track: { id: station.trackId, name: station.track.name },
      pass: {
        id: pass.id,
        status: pass.status,
        seasonYear: pass.seasonYear,
        expiresAt: pass.expiresAt.toISOString(),
        tierName: pass.tier.name,
      },
      includedDays: pick.includedDays,
      remainingFreeDays: freeRemaining,
      discountDaysRemaining: Math.max(pick.discountDaysAllowed - pick.discountDaysUsed, 0),
      mock: true,
    };
    res.json(success(outcome));
  } catch (err) {
    next(err);
  }
};

/**
 * Operator: let a rider back through today's gate. The day is already spent,
 * so this is a logged pass-through only — no allotment moves, nothing is owed.
 * It reads the same station the scan does, so an operator can only re-enter at
 * their own track.
 */
export const reenterRider = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const body = z
      .object({ riderId: z.string().uuid(), stationId: z.string().uuid().optional() })
      .parse(req.body);
    const station = await resolveStation(req, body.stationId);
    if (!station) {
      return res
        .status(400)
        .json(error('No scanning station is configured for your account. Ask an admin to assign one.'));
    }
    const outcome = await completeReentry({
      riderId: body.riderId,
      trackId: station.trackId,
      stationId: station.id,
      operatorId: req.user!.id,
    });
    res.json(success(outcome));
  } catch (err) {
    next(err);
  }
};

/**
 * Operator: find a rider at the gate. Phone, name, email or account id — the
 * things a rider can be asked at the window. The gate's search sends one
 * `field` per search, so an email search never returns a name match; with no
 * `field` it falls back to any of them. Only riders who hold a pass are worth
 * listing, so each hit carries the pass's standing at this track.
 */
export const searchRiders = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const query = lookupQuerySchema.parse(req.query);
    const field = query.field;
    /* The panel runs the same rules before it sends. A key that still arrives
       malformed is refused here, so no bad text ever reaches the query: an
       empty one is simply no rows, a bad one is a 400. */
    const check = field ? checkLookupInput(field, query.q) : checkAnyLookupText(query.q);
    const q = check.text;
    if (!check.ok) {
      return q.length === 0
        ? res.json(success({ q, riders: [] }))
        : res.status(400).json(error(check.message, [{ field: 'q', message: check.message }]));
    }
    const trackId = query.trackId || req.user!.operatorTrackId || undefined;

    // Phone numbers are stored as digits, so a query typed with dashes still
    // matches once its own digits are pulled out. Text matches are
    // case-insensitive explicitly: SQLite's LIKE ignored case for ASCII, and
    // PostgreSQL's does not, so without `mode` a gate typing "Ops@..." or "amy"
    // would stop finding the rider it used to.
    const digits = q.replace(/\D/g, '');
    const where: Record<string, unknown>[] =
      field === 'email'
        ? [{ email: { contains: q, mode: 'insensitive' } }]
        : field === 'name'
          ? [{ name: { contains: q, mode: 'insensitive' } }]
          : field === 'phone'
            ? [{ phone: { contains: digits } }]
            : [
                { email: { contains: q, mode: 'insensitive' } },
                { name: { contains: q, mode: 'insensitive' } },
                { id: q },
                ...(digits.length >= 3 ? [{ phone: { contains: digits } }] : []),
              ];
    if (where.length === 0) return res.json(success({ q, riders: [] }));

    const users = await prisma.user.findMany({
      where: { role: 'RIDER', isActive: true, OR: where },
      select: { id: true, name: true, email: true, phone: true, avatarUrl: true },
      orderBy: { name: 'asc' },
      take: 8,
    });
    const ids = users.map((u) => u.id);
    const today = todayKey();

    const [passes, allotments, track, redeemedToday, bookedToday] = await Promise.all([
      ids.length
        ? prisma.pass.findMany({
            where: { userId: { in: ids } },
            include: { tier: true },
            orderBy: [{ seasonYear: 'desc' }, { createdAt: 'desc' }],
          })
        : Promise.resolve([]),
      ids.length && trackId
        ? prisma.allotment.findMany({ where: { userId: { in: ids }, trackId } })
        : Promise.resolve([]),
      trackId
        ? prisma.track.findUnique({ where: { id: trackId }, select: { name: true } })
        : Promise.resolve(null),
      // The same-day rule and the reservation rule, read up front so the
      // panel can say what would stop a redeem before the operator taps.
      ids.length && trackId
        ? prisma.redemption.findMany({
            where: { userId: { in: ids }, trackId, day: today },
            select: { userId: true, kind: true, redeemedAt: true },
          })
        : Promise.resolve([]),
      ids.length && trackId
        ? prisma.reservation.findMany({
            where: {
              userId: { in: ids },
              trackId,
              date: today,
              status: { in: [ReservationStatus.CONFIRMED, ReservationStatus.PENDING] },
            },
            select: { id: true, userId: true, dayConsumed: true },
          })
        : Promise.resolve([]),
    ]);

    /* The redeemed days behind the standing: the operator sees what the rider
       has already spent here without leaving the gate view. Six most recent
       per rider, plus the whole-season count. Scoped to this track, because
       the day count beside it is this track's allotment — an account-wide list
       would read as days spent against a balance it never touched. */
    const historyWhere = (userId: string) => ({
      userId,
      ...(trackId ? { trackId } : {}),
    });
    const histories = await Promise.all(
      users.map(async (u) => ({
        userId: u.id,
        rows: await prisma.redemption.findMany({
          where: historyWhere(u.id),
          include: { track: { select: { name: true } } },
          orderBy: [{ day: 'desc' }, { redeemedAt: 'desc' }],
          take: HISTORY_LIMIT,
        }),
        total: await prisma.redemption.count({ where: historyWhere(u.id) }),
      }))
    );

    const riders = users.map((u) => {
      const mine = passes.filter((p) => p.userId === u.id);
      const active = mine.filter((p) => p.status === 'ACTIVE');
      // Same preference as getCurrentPass: an active paid pass wins over the
      // default (free) one, so the gate sees the pass the rider bought.
      const pass =
        active.filter((p) => !p.tier.isDefault).sort((a, b) => b.tier.priceCents - a.tier.priceCents)[0] ??
        active[0] ??
        mine[0] ??
        null;
      const allotment = allotments.find(
        (a) => a.userId === u.id && a.seasonYear === (pass?.seasonYear ?? -1)
      );
      const redemption = redeemedToday.find((r) => r.userId === u.id) ?? null;
      const reservation = bookedToday.find((r) => r.userId === u.id) ?? null;

      // One verdict, from the scan's own rules — the panel and the window can
      // never disagree about whether this rider gets in.
      const decision = gateDecision({
        pass: pass ? { status: pass.status, expiresAt: pass.expiresAt } : null,
        trackName: track?.name ?? 'this track',
        redeemedToday: Boolean(redemption),
        allotment: allotment ?? null,
        reservation: reservation
          ? { id: reservation.id, dayConsumed: reservation.dayConsumed }
          : null,
      });
      const standing = gateStanding(decision, {
        redeemedTodayAt: redemption?.redeemedAt ?? null,
        redeemedTodayKind: redemption?.kind ?? null,
        reservationBooked: Boolean(reservation),
        allotment: allotment ?? null,
      });

      return {
        id: u.id,
        name: u.name,
        email: u.email,
        phone: u.phone,
        avatarUrl: u.avatarUrl,
        pass: pass
          ? {
              tierName: pass.tier.name,
              // The default (free) tier carries no allotments, so it has no
              // days to redeem anywhere; the panel reads this instead of the
              // TRACK_NOT_PARTICIPATING denial it would otherwise show.
              freeTier: pass.tier.isDefault,
              status: pass.status,
              seasonYear: pass.seasonYear,
              expiresAt: pass.expiresAt.toISOString(),
            }
          : null,
        includedDays: allotment?.includedDays ?? null,
        remainingFreeDays: allotment
          ? Math.max(allotment.includedDays - allotment.freeDaysUsed, 0)
          : null,
        standing,
        /* The days already spent, newest first, with the season's own count so
           a capped list never reads as the whole story. */
        history: (histories.find((h) => h.userId === u.id)?.rows ?? []).map((r) => ({
          id: r.id,
          day: r.day.toISOString(),
          trackName: r.track.name,
          kind: r.kind,
          amountChargedCents: r.amountChargedCents,
          redeemedAt: r.redeemedAt.toISOString(),
        })),
        historyCount: histories.find((h) => h.userId === u.id)?.total ?? 0,
      };
    });

    res.json(success({ q, riders }));
  } catch (err) {
    next(err);
  }
};

/** Operator: today's check-ins at their track. */
export const todayCheckins = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const trackId =
      (req.query.trackId as string) || req.user!.operatorTrackId || undefined;
    if (!trackId) return res.status(400).json(error('No track specified.'));

    const today = todayKey();
    const redemptions = await prisma.redemption.findMany({
      where: { trackId, day: today },
      include: { user: { select: { name: true, email: true } } },
      orderBy: { redeemedAt: 'desc' },
    });
    const denied = await prisma.scanEvent.findMany({
      where: { trackId, result: 'DENIED', createdAt: { gte: today } },
      orderBy: { createdAt: 'desc' },
      take: 50,
    });
    res.json(
      success({
        date: today,
        checkins: redemptions.map((r) => ({
          id: r.id,
          riderName: r.user.name,
          riderEmail: r.user.email,
          kind: r.kind,
          redeemedAt: r.redeemedAt,
          amountChargedCents: r.amountChargedCents,
        })),
        deniedCount: denied.length,
        denied: denied.map((d) => ({
          id: d.id,
          riderName: d.riderName,
          reasonCode: d.reasonCode,
          reason: d.reason,
          createdAt: d.createdAt,
        })),
      })
    );
  } catch (err) {
    next(err);
  }
};

/** Operator/admin: full redemption + scan log with filters. */
export const redemptionLog = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const trackId = (req.query.trackId as string) || req.user!.operatorTrackId || undefined;
    const limit = Math.min(Number(req.query.limit) || 100, 500);

    const [redemptions, scans] = await Promise.all([
      prisma.redemption.findMany({
        where: trackId ? { trackId } : {},
        include: { track: true, user: { select: { name: true, email: true } } },
        orderBy: { redeemedAt: 'desc' },
        take: limit,
      }),
      prisma.scanEvent.findMany({
        where: trackId ? { trackId } : {},
        include: { track: true },
        orderBy: { createdAt: 'desc' },
        take: limit,
      }),
    ]);

    res.json(
      success({
        // The server's own day key, so the dashboard's Today scope lines up
        // with the ledgers it is filtering.
        date: todayKey(),
        redemptions: redemptions.map((r) => ({
          id: r.id,
          riderName: r.user.name,
          riderEmail: r.user.email,
          trackName: r.track.name,
          trackWebsite: r.track.website,
          kind: r.kind,
          day: r.day,
          redeemedAt: r.redeemedAt,
          amountChargedCents: r.amountChargedCents,
        })),
        scans: scans.map((s) => ({
          id: s.id,
          riderName: s.riderName,
          trackName: s.track.name,
          trackWebsite: s.track.website,
          result: s.result,
          reasonCode: s.reasonCode,
          reason: s.reason,
          kind: s.kind,
          createdAt: s.createdAt,
        })),
      })
