const WEEKDAY_LABELS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const STAT_WINDOW_DAYS = 30;
/** The longest day run worth drawing as columns; a season is read as a
    summary, not a bar per day. */
const STAT_MAX_DAY_RUN = 31;

/** The reads the operator's timeframe pill offers: the gate today, the
    trailing month, the season to date. */
type StatRange = 'today' | 'window' | 'season';

const RANGE_LABEL: Record<StatRange, string> = {
  today: 'Today',
  window: 'Last 30 days',
  season: 'Season to date',
};

function readRange(raw: unknown): StatRange {
  return raw === 'today' || raw === 'window' || raw === 'season' ? raw : 'season';
}

type StatRedemption = {
  userId: string;
  day: Date;
  kind: string;
  amountChargedCents: number;
  redeemedAt: Date;
  user: { name: string };
};

type StatScan = {
  result: string;
  reasonCode: string | null;
  reason: string | null;
  createdAt: Date;
};

/**
 * Every figure for one slice of the ledgers. The timeframe pill picks the
 * slice; this builds the whole read off the same rows, so the summary, the day
 * run, the weekday bars, the hour bars and the rider list can never disagree
 * with each other. `firstVisit` carries each rider's first season visit so
 * "first time here" stays true for a short range.
 */
function summarise(
  redemptions: StatRedemption[],
  scans: StatScan[],
  firstVisit: Map<string, number>,
  fromMs: number
) {
  const ridesByRider = new Map<string, number>();
  const collectedByRider = new Map<string, number>();
  const ridesByDay = new Map<number, number>();
  const byKind: Record<string, number> = { FREE: 0, DISCOUNT: 0 };
  const weekday = WEEKDAY_LABELS.map((label) => ({ label, checkins: 0 }));
  const hours = Array.from({ length: 24 }, (_, hour) => ({ hour, checkins: 0 }));
  let collectedCents = 0;

  for (const r of redemptions) {
    const t = r.day.getTime();
    ridesByRider.set(r.userId, (ridesByRider.get(r.userId) ?? 0) + 1);
    ridesByDay.set(t, (ridesByDay.get(t) ?? 0) + 1);
    if (r.amountChargedCents) {
      collectedCents += r.amountChargedCents;
      collectedByRider.set(r.userId, (collectedByRider.get(r.userId) ?? 0) + r.amountChargedCents);
    }
    if (byKind[r.kind] != null) byKind[r.kind] += 1;
    weekday[r.day.getUTCDay()].checkins += 1;
    // Hours are bucketed on the venue's own clock — the same frame the day keys
    // and the activity log's timestamps read — so a rider's bar hour matches the
    // time printed beside it.
    hours[r.redeemedAt.getHours()].checkins += 1;
  }

  const checkins = redemptions.length;
  const riders = ridesByRider.size;
  const rideDays = ridesByDay.size;
  const repeatRiders = [...ridesByRider.values()].filter((n) => n > 1).length;
  const approved = scans.filter((s) => s.result === 'APPROVED').length;
  const round1 = (n: number) => Math.round(n * 10) / 10;

  const topRiders = [...ridesByRider.entries()]
    .map(([userId, visits]) => {
      const row = redemptions.find((r) => r.userId === userId);
      return {
        name: row?.user.name ?? 'Rider',
        visits,
        paidCents: collectedByRider.get(userId) ?? 0,
      };
    })
    .sort((a, b) => b.visits - a.visits || b.paidCents - a.paidCents)
    .slice(0, 5);

  const denials = new Map<string, { code: string | null; reason: string | null; count: number }>();
  for (const s of scans) {
    if (s.result !== 'DENIED') continue;
    const key = s.reasonCode || s.reason || 'OTHER';
    const hit = denials.get(key) ?? { code: s.reasonCode, reason: s.reason, count: 0 };
    hit.count += 1;
    denials.set(key, hit);
  }

  return {
    summary: {
      checkins,
      riders,
      collectedCents,
      rideDays,
      perRideDay: rideDays ? round1(checkins / rideDays) : 0,
      repeatRiders,
      repeatRate: riders ? Math.round((repeatRiders / riders) * 100) : 0,
      newRiders: [...firstVisit.values()].filter((t) => t >= fromMs).length,
      avgVisits: riders ? round1(checkins / riders) : 0,
      scans: scans.length,
      approved,
      denied: scans.length - approved,
      approvalRate: scans.length ? Math.round((approved / scans.length) * 100) : null,
    },
    kinds: byKind,
    weekday,
    hours,
    topRiders,
    denials: [...denials.values()].sort((a, b) => b.count - a.count).slice(0, 5),
    ridesByDay,
  };
}

/**
 * Operator/admin: the venue's operating read — the gate today, the trailing
 * month, or the season to date, chosen by the timeframe pill; when riders
 * actually turn up; and who they are. Every figure is counted off the
 * redemption + scan ledgers at request time; nothing here is stored.
 */
export const trackStats = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const trackId = (req.query.trackId as string) || req.user!.operatorTrackId || undefined;
    if (!trackId) return res.status(400).json(error('No track specified.'));
    const range = readRange(req.query.range);

    const track = await prisma.track.findUnique({
      where: { id: trackId },
      select: { id: true, name: true, slug: true },
    });
    if (!track) return res.status(404).json(error('Track not found.'));

    const today = todayKey();
    const seasonYear = new Date().getUTCFullYear();
    const { startsAt: seasonStart } = seasonBounds(seasonYear);

    // The whole season is read once — a range is a slice of it, and the
    // season-long rows are what tell "first time here" apart from "been here".
    const [redemptions, scans, followers, upcoming] = await Promise.all([
      prisma.redemption.findMany({
        where: { trackId, day: { gte: seasonStart, lte: today } },
        select: {
          userId: true,
          day: true,
          kind: true,
          amountChargedCents: true,
          redeemedAt: true,
          user: { select: { name: true } },
        },
      }),
      prisma.scanEvent.findMany({
        where: { trackId, createdAt: { gte: seasonStart } },
        select: { result: true, reasonCode: true, reason: true, createdAt: true },
      }),
      prisma.trackFollow.count({ where: { trackId } }),
      prisma.trackEvent.findMany({
        where: { trackId, isActive: true, startsAt: { gte: today } },
        orderBy: { startsAt: 'asc' },
        take: 12,
        select: { title: true, kind: true, startsAt: true, startMinutes: true, endMinutes: true },
      }),
    ]);

    const firstVisit = new Map<string, number>();
    for (const r of redemptions) {
      const t = r.day.getTime();
      const seen = firstVisit.get(r.userId);
      if (seen == null || t < seen) firstVisit.set(r.userId, t);
    }

    const windowStart = addDays(today, -(STAT_WINDOW_DAYS - 1));
    const from = range === 'today' ? today : range === 'window' ? windowStart : seasonStart;
    const fromMs = from.getTime();
    const fromDay = from.toISOString().slice(0, 10);
    const todayIso = today.toISOString().slice(0, 10);

    const rangeReds = redemptions.filter((r) => r.day >= from);
    const rangeScans = scans.filter((s) => s.createdAt >= from);
    const read = summarise(rangeReds, rangeScans, firstVisit, fromMs);

    // A day-by-day run is only drawn for a range short enough to read as
    // columns; the season answers in figures instead.
    const span = Math.round((today.getTime() - fromMs) / 86400000) + 1;
    const days =
      span <= STAT_MAX_DAY_RUN
        ? Array.from({ length: span }, (_, i) => {
            const d = addDays(from, i);
            return {
              day: d.toISOString().slice(0, 10),
              checkins: read.ridesByDay.get(d.getTime()) ?? 0,
            };
          })
        : [];

    const next = upcoming[0] ?? null;
    res.json(
      success({
        trackId: track.id,
        trackName: track.name,
        trackSlug: track.slug,
        seasonYear,
        asOf: todayIso,
        range: {
          key: range,
          label: RANGE_LABEL[range],
          from: fromDay,
          to: todayIso,
        },
        summary: read.summary,
        kinds: read.kinds,
        days,
        weekday: read.weekday,
        hours: read.hours,
        topRiders: read.topRiders,
        denials: read.denials,
        audience: {
          followers,
          upcoming: upcoming.length,
          nextEvent: next
            ? {
                title: next.title,
                kind: next.kind,
                day: next.startsAt.toISOString().slice(0, 10),
                startMinutes: next.startMinutes,
                endMinutes: next.endMinutes,
              }
            : null,
        },
      })
    );
  } catch (err) {
    next(err);
  }
};

import { Request, Response, NextFunction } from 'express';
import { prisma } from '../utils/prisma';
import { success, error } from '../utils/apiResponse';
import { PassStatus, Role, TrackEventKind } from '../types/enums';
import { AuthRequest } from '../types';
import { getCurrentPass } from '../services/pass.service';
import { parseHoursWeek } from '../lib/hoursWeek';
import { addDays, dayKey, todayKey } from '../utils/dates';

/** A posted day read, as the public API serves it. */
export interface DayStatusRead {
  day: string;
  status: string;
  statusNote: string | null;
}

const toRead = (r: { day: Date; status: string; statusNote: string | null }): DayStatusRead => ({
  day: r.day.toISOString().slice(0, 10),
  status: r.status,
  statusNote: r.statusNote,
});

/**
 * The gate a rider reads: today's posted read when the operator set one,
 * else the venue's live line. Tomorrow's caution stays scheduled — it flips
 * the live line when the day arrives (see the owner controller), so the
 * network reads today and nothing else.
 */
function effectiveStatus(
  live: { status: string; statusNote: string | null },
  rows: { day: Date; status: string; statusNote: string | null }[]
): { status: string; statusNote: string | null } {
  const today = todayKey().getTime();
  const row = rows.find((r) => dayKey(r.day).getTime() === today);
  return row ? { status: row.status, statusNote: row.statusNote } : live;
}

/** The posted read `daysAhead` days out, or null when none is scheduled. */
function dayAfterRead(
  rows: { day: Date; status: string; statusNote: string | null }[],
  daysAhead: number
): DayStatusRead | null {
  const want = addDays(todayKey(), daysAhead).getTime();
  const row = rows.find((r) => dayKey(r.day).getTime() === want);
  return row ? toRead(row) : null;
}

/** A venue's next race, as the network serves it — the inspector's callout. */
export interface NextRaceRead {
  title: string;
  /** The race's own day, `YYYY-MM-DD` (events sit at noon UTC, so it round-trips). */
  day: string;
  startMinutes: number | null;
  endMinutes: number | null;
}

const toRaceRead = (r: {
  title: string;
  startsAt: Date;
  startMinutes: number | null;
  endMinutes: number | null;
}): NextRaceRead => ({
  title: r.title,
  day: r.startsAt.toISOString().slice(0, 10),
  startMinutes: r.startMinutes,
  endMinutes: r.endMinutes,
});

/**
 * The overnight flip, run on every public read: a scheduled day that has
 * arrived writes itself onto the venue's live line, so the network, the map
 * and the profile agree even when nobody posted today by hand. Capped — one
 * venue, one write — and only past rows the live line has not caught yet.
 */
async function promoteArrivedDayStatuses(): Promise<void> {
  // Everything before tomorrow midnight — all rows up to and including today
  // (rows sit at noon UTC, so `<= today at 00:00` would miss today's own row).
  const rows = await prisma.trackDayStatus.findMany({
    where: { day: { lt: addDays(todayKey(), 1) } },
    include: { track: { select: { id: true, status: true, statusNote: true } } },
    orderBy: { day: 'desc' },
  });
  const today = todayKey().getTime();
  const seen = new Set<string>();
  for (const r of rows) {
    if (dayKey(r.day).getTime() > today) continue;
    if (seen.has(r.trackId)) continue;
    seen.add(r.trackId);
    if (r.track.status === r.status && r.track.statusNote === r.statusNote) continue;
    await prisma.track.update({
      where: { id: r.trackId },
      data: { status: r.status, statusNote: r.statusNote },
    });
  }
}

/**
 * Whether this viewer is a rider on the free tier (or with no live pass at all).
 * A free account gets the directory — the venue, where it is and what it is
 * doing — but not the pass's own terms, so the included days and the member
 * discount are withheld from the response rather than merely hidden in the UI.
 * Anonymous visitors and paying riders see the full contract terms.
 *
 * `?terms=public` opts out of the gate. It exists for the pricing page, whose
 * figures *are* the anonymous marketing copy: a free rider reading it is being
 * sold the pass, so withholding the day totals there would only break the pitch.
 */
async function viewerGated(req: Request) {
  if (req.query.terms === 'public') return false;
  const user = (req as AuthRequest).user;
  if (!user || user.role !== Role.RIDER) return false;
  const pass = await getCurrentPass(user.id);
  return !pass || pass.status !== PassStatus.ACTIVE || pass.tier.isDefault;
}

/** Public: list active tracks — venue status for everyone, contract terms for
 *  anyone but a free-tier rider. */
export const listTracks = async (req: Request, res: Response, next: NextFunction) => {
  try {
    const season = await prisma.season.findFirst({ where: { isActive: true }, orderBy: { year: 'desc' } });
    await promoteArrivedDayStatuses();
    const tracks = await prisma.track.findMany({
      where: { isActive: true },
      include: {
        contracts: season ? { where: { seasonId: season.id, isActive: true } } : false,
        dayStatuses: {
          where: { day: { gte: todayKey() } },
          orderBy: { day: 'asc' },
        },
      },
      orderBy: { name: 'asc' },
    });
    const user = (req as AuthRequest).user;
    const gated = await viewerGated(req);
    // Each venue's next race, in one read: the rail's inspector calls it out,
    // while the venue profile's own schedule stays the long view.
    const raceRows = await prisma.trackEvent.findMany({
      where: { isActive: true, kind: TrackEventKind.RACE, startsAt: { gte: todayKey() } },
      orderBy: { startsAt: 'asc' },
      select: { trackId: true, title: true, startsAt: true, startMinutes: true, endMinutes: true },
    });
    const nextRace = new Map<string, (typeof raceRows)[number]>();
    for (const r of raceRows) if (!nextRace.has(r.trackId)) nextRace.set(r.trackId, r);
    // Following is not an operator action, so only everyone else's follows
    // land on the payload — an operator reads every flag as false.
    const follows = user && user.role !== Role.OPERATOR
      ? new Set((await prisma.trackFollow.findMany({ where: { userId: user.id } })).map((f) => f.trackId))
      : new Set<string>();
    res.json(
      success({
        seasonYear: season?.year ?? null,
        gated,
        tracks: tracks.map((t) => {
          const c = t.contracts[0];
          const gate = effectiveStatus(t, t.dayStatuses);
          return {
            id: t.id,
            slug: t.slug,
            name: t.name,
            description: t.description,
            city: t.city,
            region: t.region,
            address: t.address,
            lat: t.lat,
            lng: t.lng,
            website: t.website,
            instagram: t.instagram,
            facebook: t.facebook,
            youtube: t.youtube,
            tiktok: t.tiktok,
            imageUrl: t.imageUrl,
            bannerUrl: t.bannerUrl,
            logoUrl: t.logoUrl,
            category: t.category,
            status: gate.status,
            statusNote: gate.statusNote,
            // The operator's own message to riders, when they left one — the
            // panel's note above the facts. Null keeps it off the panel.
            riderMessage: t.riderMessage,
            // Tomorrow's posted read, when the operator has scheduled one —
            // the network lists today, and this is the heads-up beside it.
            tomorrowStatus: dayAfterRead(t.dayStatuses, 1),
            hours: t.hours,
            // The venue's week behind that line — null when none is on file.
            hoursWeek: parseHoursWeek(t.hoursWeek),
            nextEvent: t.nextEvent,
            // The venue's next race on file, when one is coming — null for a
            // venue whose owner keeps no schedule.
            nextRace: nextRace.has(t.id) ? toRaceRead(nextRace.get(t.id)!) : null,
            gated,
            following: follows.has(t.id),
            // Withheld for free-tier riders — the pass's own terms.
            includedDays: gated ? null : c?.includedDays ?? 0,
            discountDayEnabled: gated ? false : c?.discountDayEnabled ?? false,
            discountDayNumber: gated ? null : c?.discountDayNumber ?? null,
            discountRate: gated ? null : c?.discountRate ?? null,
            discountDaysAllowed: gated ? null : c?.discountDaysAllowed ?? null,
            extraDayPriceCents: gated ? null : c?.extraDayPriceCents ?? null,
            reservationRequired: c?.reservationRequired ?? false,
          };
        }),
      })
    );
  } catch (err) {
    next(err);
  }
};

/** Public: one partner track's venue profile — its own art, hours, links and
 *  events, plus the pass's terms there for anyone but a free-tier rider. */
export const getTrack = async (req: Request, res: Response, next: NextFunction) => {
  try {
    const slug = req.params.slug as string;
    const season = await prisma.season.findFirst({ where: { isActive: true }, orderBy: { year: 'desc' } });
    await promoteArrivedDayStatuses();
    const track = await prisma.track.findUnique({
      where: { slug },
      include: {
        events: { where: { isActive: true }, orderBy: { startsAt: 'asc' } },
        photos: { orderBy: [{ sortOrder: 'asc' }, { createdAt: 'asc' }] },
        reviews: {
          orderBy: { createdAt: 'desc' },
          select: {
            id: true,
            rating: true,
            body: true,
            createdAt: true,
            updatedAt: true,
            userId: true,
            user: { select: { name: true, avatarUrl: true } },
            photos: {
              orderBy: [{ sortOrder: 'asc' }, { createdAt: 'asc' }],
              select: { id: true, url: true, caption: true },
            },
          },
        },
        contracts: season ? { where: { seasonId: season.id, isActive: true } } : false,
        dayStatuses: {
          where: { day: { gte: todayKey() } },
          orderBy: { day: 'asc' },
        },
      },
    });
    if (!track || !track.isActive) return res.status(404).json(error('Track not found.'));

    const user = (req as AuthRequest).user;
    const gated = await viewerGated(req);
    const c = track.contracts[0];
    const gate = effectiveStatus(track, track.dayStatuses);
    const following = user && user.role !== Role.OPERATOR
      ? Boolean(await prisma.trackFollow.findUnique({ where: { userId_trackId: { userId: user.id, trackId: track.id } } }))
      : false;

    res.json(
      success({
        seasonYear: season?.year ?? null,
        gated,
        following,
        track: {
          id: track.id,
          slug: track.slug,
          name: track.name,
          description: track.description,
          city: track.city,
          region: track.region,
          address: track.address,
          country: track.country,
          lat: track.lat,
          lng: track.lng,
          website: track.website,
          instagram: track.instagram,
          facebook: track.facebook,
          youtube: track.youtube,
          tiktok: track.tiktok,
          email: track.email,
          phone: track.phone,
          imageUrl: track.imageUrl,
          bannerUrl: track.bannerUrl,
          logoUrl: track.logoUrl,
          category: track.category,
          status: gate.status,
          statusNote: gate.statusNote,
          // The operator's own message to riders, when they left one.
          riderMessage: track.riderMessage,
          // Tomorrow's posted read, when the operator has scheduled one.
          tomorrowStatus: dayAfterRead(track.dayStatuses, 1),
          // Every scheduled day from today on — what the profile's calendar
          // paints onto its dates.
          dayStatuses: track.dayStatuses.map(toRead),
          hours: track.hours,
          hoursWeek: parseHoursWeek(track.hoursWeek),
          nextEvent: track.nextEvent,
          events: track.events.map((e) => ({
            id: e.id,
            title: e.title,
            description: e.description,
            kind: e.kind,
            startsAt: e.startsAt,
            endsAt: e.endsAt,
            // Minutes past midnight on the date's own day, or null for an
            // all-day date — the profile shows the hours, the calendar draws them.
            startMinutes: e.startMinutes,
            endMinutes: e.endMinutes,
          })),
          // The venue's gallery, in the owner's order. The profile page opens
          // on the first frame, so an empty list is the only "no photos" state.
          photos: track.photos.map((p) => ({
            id: p.id,
            url: p.url,
            caption: p.caption,
            category: p.category,
          })),
          // What riders have written about the venue, newest first — the venue
          // page's community wall. Public: it is not a pass term.
          reviews: track.reviews.map((r) => ({
            id: r.id,
            rating: r.rating,
            body: r.body,
            createdAt: r.createdAt,
            updatedAt: r.updatedAt,
            userId: r.userId,
            riderName: r.user.name,
            riderAvatarUrl: r.user.avatarUrl,
            photos: r.photos.map((p) => ({ id: p.id, url: p.url, caption: p.caption })),
          })),
          // The pass's own terms — withheld from a free-tier rider, like /tracks.
          includedDays: gated ? null : c?.includedDays ?? 0,
          discountDayEnabled: gated ? false : c?.discountDayEnabled ?? false,
          discountDayNumber: gated ? null : c?.discountDayNumber ?? null,
          discountRate: gated ? null : c?.discountRate ?? null,
          discountDaysAllowed: gated ? null : c?.discountDaysAllowed ?? null,
          extraDayPriceCents: gated ? null : c?.extraDayPriceCents ?? null,
          reservationRequired: c?.reservationRequired ?? false,
        },
      })
    );
  } catch (err) {
    next(err);
  }
};

