import { createApp } from './app';
import config from './config';
import { prisma } from './utils/prisma';
import logger from './utils/logger';

async function main() {
  const app = createApp();

  const server = app.listen(config.port, config.host, () => {
    logger.info(`Moto Pass API listening on http://${config.host}:${config.port}`);
  });

  const shutdown = async (signal: string) => {
    logger.info(`${signal} received — shutting down.`);
    server.close(async () => {
      await prisma.$disconnect();
      process.exit(0);
    });
  };
  process.on('SIGINT', () => shutdown('SIGINT'));
  process.on('SIGTERM', () => shutdown('SIGTERM'));
}

main().catch((err) => {
  logger.error('Fatal startup error', err);
  process.exit(1);
});

/**
 * The venue week: one shape, read by the API, written by the owner console.
 *
 * Stored on `Track.hoursWeek` as JSON (`{"mon":"Practice 9am–4pm", …}`) so the
 * seven days travel as one column; parsed here so no caller has to know that.
 * Keys are always Mon..Sun in that order, and a day the venue does not run
 * reads `Closed` rather than blank.
 */
import { z } from 'zod';

export const HOURS_WEEK_KEYS = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'] as const;
export type HoursWeekKey = (typeof HOURS_WEEK_KEYS)[number];
export type HoursWeek = Record<HoursWeekKey, string>;

/** A week off a track row — null when the venue has none on file (or it is junk). */
export function parseHoursWeek(raw: string | null | undefined): HoursWeek | null {
  if (!raw) return null;
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return null;
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;
  const src = parsed as Record<string, unknown>;
  const week = {} as HoursWeek;
  for (const key of HOURS_WEEK_KEYS) {
    const value = src[key];
    if (typeof value !== 'string') return null;
    week[key] = value.trim() === '' ? 'Closed' : value.trim();
  }
  return week;
}

/** What the console posts: the JSON string for a week, or null when it clears one. */
export const hoursWeekSchema = z
  .string()
  .max(1200)
  .refine((v) => v.trim() === '' || parseHoursWeek(v) !== null, 'hoursWeek must be a Mon–Sun map');

import { NextFunction, Response } from 'express';
import { Role } from '../types/enums';
import { AuthRequest } from '../types';
import { resolveSession } from '../services/session.service';
import config from '../config';
import { error } from '../utils/apiResponse';

/** Attach req.user when a valid session cookie is present. Never blocks. */
export async function attachUser(req: AuthRequest, _res: Response, next: NextFunction) {
  try {
    const token = req.cookies?.[config.session.cookieName];
    const session = await resolveSession(token);
    if (session) {
      req.user = {
        id: session.user.id,
        email: session.user.email,
        name: session.user.name,
        role: session.user.role as Role,
        operatorTrackId: session.user.operatorTrackId,
      };
    }
  } catch {
    // ignore — treated as anonymous
  }
  next();
}

export function authenticate(req: AuthRequest, res: Response, next: NextFunction) {
  if (!req.user) return res.status(401).json(error('Authentication required.'));
  next();
}

export function authorize(...roles: Role[]) {
  return (req: AuthRequest, res: Response, next: NextFunction) => {
    if (!req.user) return res.status(401).json(error('Authentication required.'));
    if (roles.length && !roles.includes(req.user.role)) {
      return res.status(403).json(error('You do not have permission to do that.'));
    }
    next();
  };
}

import { NextFunction, Request, Response } from 'express';
import { ZodError } from 'zod';
import { Prisma } from '@prisma/client';
import logger from '../utils/logger';
import config from '../config';
import { error } from '../utils/apiResponse';

// eslint-disable-next-line @typescript-eslint/no-unused-vars
export function errorHandler(err: any, _req: Request, res: Response, _next: NextFunction) {
  let status = 500;
  let message = 'Something went wrong.';
  let errors: unknown;

  if (err instanceof ZodError) {
    status = 400;
    message = 'Validation failed.';
    errors = err.issues.map((i) => ({ field: i.path.join('.'), message: i.message }));
  } else if (err instanceof Prisma.PrismaClientKnownRequestError) {
    if (err.code === 'P2002') {
      status = 409;
      message = 'That record already exists.';
    } else if (err.code === 'P2025') {
      status = 404;
      message = 'Record not found.';
    } else if (err.code === 'P2003' || err.code === 'P2014') {
      status = 400;
      message = 'Related record constraint failed.';
    }
  } else if (err?.name === 'JsonWebTokenError' || err?.name === 'TokenExpiredError') {
    status = 401;
    message = 'Invalid or expired token.';
  } else if (typeof err?.status === 'number') {
    status = err.status;
    message = err.message || message;
  }

  if (status >= 500) logger.error(`Unhandled error: ${err?.message}`, err);
  else logger.warn(`Request error (${status}): ${err?.message}`);

  res.status(status).json(
    error(message, errors ?? (config.isProd ? undefined : { detail: String(err?.message || err) }))
  );
}

import { NextFunction, Request, Response } from 'express';
import { AnyZodObject, ZodError } from 'zod';
import { error } from '../utils/apiResponse';

function handle(err: unknown, res: Response, next: NextFunction) {
  if (err instanceof ZodError) {
    return res.status(400).json(
      error(
        'Validation failed.',
        err.issues.map((i) => ({ field: i.path.join('.'), message: i.message }))
      )
    );
  }
  next(err);
}

/** Validate + coerce req.body against a Zod schema (mutates req.body). */
export function validate(schema: AnyZodObject) {
  return (req: Request, res: Response, next: NextFunction) => {
    try {
      req.body = schema.parse(req.body);
      next();
    } catch (err) {
      handle(err, res, next);
    }
  };
}

/** Validate + coerce req.query against a Zod schema (mutates req.query). */
export function validateQuery(schema: AnyZodObject) {
  return (req: Request, res: Response, next: NextFunction) => {
    try {
      const parsed = schema.parse(req.query);
      Object.assign(req.query, parsed);
      next();
    } catch (err) {
      handle(err, res, next);
    }
  };
}

