import { PassStatus } from '../types/enums';
import { prisma } from '../utils/prisma';
import { seasonBounds } from '../utils/dates';

/**
 * Activate a pass: mark ACTIVE, set calendar-year expiry, and snapshot the
 * contract terms for every participating track into per-user Allotment rows.
 * Snapshotting means a later contract edit never silently rewrites a rider's
 * remaining days for a season already in flight.
 *
 * A paid pass snapshots an allotment at every active partner track; no
 * allotment row is what makes the scan refuse a venue, so coverage and the
 * ledger stay in one place.
 *
 * The default (free) tier snapshots nothing: no included days and no member
 * discount are what separate it from a paid pass, so it activates with an empty
 * ledger and a free account only ever sees the network, never a day count.
 */
export async function activatePass(passId: string) {
  const pass = await prisma.pass.findUnique({
    where: { id: passId },
    include: { tier: true, season: true },
  });
  if (!pass) throw Object.assign(new Error('Pass not found'), { status: 404 });

  const { endsAt } = seasonBounds(pass.seasonYear);

  return prisma.$transaction(async (tx) => {
    if (pass.tier.isDefault) {
      return tx.pass.update({
        where: { id: pass.id },
        data: {
          status: PassStatus.ACTIVE,
          activatedAt: pass.activatedAt ?? new Date(),
          expiresAt: endsAt,
        },
      });
    }

    const contracts = await tx.trackContract.findMany({
      where: {
        seasonId: pass.seasonId,
        isActive: true,
        track: { isActive: true },
      },
    });

    for (const c of contracts) {
      await tx.allotment.upsert({
        where: {
          userId_trackId_seasonYear: {
            userId: pass.userId,
            trackId: c.trackId,
            seasonYear: pass.seasonYear,
          },
        },
        create: {
          userId: pass.userId,
          trackId: c.trackId,
          passId: pass.id,
          seasonId: pass.seasonId,
          seasonYear: pass.seasonYear,
          includedDays: c.includedDays + pass.tier.extraDaysPerTrack,
          discountDayEnabled: c.discountDayEnabled,
          discountDayNumber: c.discountDayNumber,
          discountRate: c.discountRate,
          discountDaysAllowed: c.discountDaysAllowed,
          extraDayPriceCents: c.extraDayPriceCents,
          reservationRequired: c.reservationRequired,
          dayConsumePolicy: c.dayConsumePolicy,
        },
        update: {
          passId: pass.id,
          includedDays: c.includedDays + pass.tier.extraDaysPerTrack,
        },
      });
    }

    return tx.pass.update({
      where: { id: pass.id },
      data: {
        status: PassStatus.ACTIVE,
        activatedAt: pass.activatedAt ?? new Date(),
        expiresAt: endsAt,
      },
    });
  });
}

export interface EntitlementRow {
  trackId: string;
  trackName: string;
  trackSlug: string;
  /** From the track's profile; null when the track has no site on file. */
  trackWebsite: string | null;
  /** From the track's profile; null when the track has no photo on file. */
  trackImageUrl: string | null;
  includedDays: number;
  freeDaysUsed: number;
  freeDaysRemaining: number;
  discountDayEnabled: boolean;
  discountDayNumber: number;
  discountRate: number;
  extraDayPriceCents: number;
  discountPriceCents: number;
  discountDaysAllowed: number;
  discountDaysUsed: number;
  reservationRequired: boolean;
  dayConsumePolicy: string;
}

/** Per-track entitlement + remaining days for a rider's active pass. */
export async function getEntitlements(userId: string, passId: string): Promise<EntitlementRow[]> {
  const pass = await prisma.pass.findUnique({ where: { id: passId } });
  if (!pass) return [];
  const rows = await prisma.allotment.findMany({
    where: { userId, seasonYear: pass.seasonYear },
    include: { track: true },
    orderBy: { track: { name: 'asc' } },
  });
  return rows.map((a) => ({
    trackId: a.trackId,
    trackName: a.track.name,
    trackSlug: a.track.slug,
    trackWebsite: a.track.website,
    trackImageUrl: a.track.imageUrl,
    includedDays: a.includedDays,
    freeDaysUsed: a.freeDaysUsed,
    freeDaysRemaining: Math.max(a.includedDays - a.freeDaysUsed, 0),
    discountDayEnabled: a.discountDayEnabled,
    discountDayNumber: a.discountDayNumber,
    discountRate: a.discountRate,
    extraDayPriceCents: a.extraDayPriceCents,
    discountPriceCents: Math.round(a.extraDayPriceCents * (1 - a.discountRate)),
    discountDaysAllowed: a.discountDaysAllowed,
    discountDaysUsed: a.discountDaysUsed,
    reservationRequired: a.reservationRequired,
    dayConsumePolicy: a.dayConsumePolicy,
  }));
}

/**
 * Get the rider's current active (or latest) pass for a season. A paid pass
 * always wins over the default (free) one, so upgrading a free account does not
 * leave the free pass shadowing the pass the rider actually bought.
 */
export async function getCurrentPass(userId: string, seasonYear?: number) {
  const where: Record<string, unknown> = { userId };
  if (seasonYear) where.seasonYear = seasonYear;
  const passes = await prisma.pass.findMany({
    where,
    include: { tier: true, season: true },
    orderBy: [{ seasonYear: 'desc' }, { createdAt: 'desc' }],
  });
  const active = passes.filter((p) => p.status === PassStatus.ACTIVE);
  const paid = active
    .filter((p) => !p.tier.isDefault)
    .sort((a, b) => b.tier.priceCents - a.tier.priceCents)[0];
  return paid ?? active[0] ?? passes[0] ?? null;
}

import {
  PassStatus,
  RedemptionKind,
  ReservationStatus,
  ScanResult,
} from '../types/enums';
import { prisma } from '../utils/prisma';
import { verifyQrToken } from '../utils/qr';
import { dayKey, todayKey } from '../utils/dates';
import { getCurrentPass } from './pass.service';

export interface ScanOutcome {
  result: ScanResult;
  reasonCode: string;
  reason: string;
  approved: boolean;
  kind?: RedemptionKind;
  amountChargedCents?: number;
  rider?: { id: string; name: string; email: string };
  track?: { id: string; name: string };
  pass?: { id: string; status: string; seasonYear: number; expiresAt: string; tierName: string };
  remainingFreeDays?: number;
  includedDays?: number;
  discountDaysRemaining?: number;
  redemptionId?: string;
}

/** The allotment fields the gate's decision reads. Structural, so a Prisma
    `Allotment` row passes straight in. */
export type GateAllotment = {
  includedDays: number;
  freeDaysUsed: number;
  discountDayEnabled: boolean;
  discountRate: number;
  discountDaysAllowed: number;
  discountDaysUsed: number;
  extraDayPriceCents: number;
  reservationRequired: boolean;
  dayConsumePolicy: string;
};

/** Everything the ticket window can know *before* it redeems: the rules the
    scan below walks, decided off the same rows. */
export interface GateInputs {
  /** null when the rider holds no pass at all. */
  pass: { status: string; expiresAt: Date } | null;
  trackName: string;
  /** A redemption already on today's ledger for this rider at this track. */
  redeemedToday: boolean;
  allotment: GateAllotment | null;
  reservation: { id: string; dayConsumed: boolean } | null;
  /** Admin/operator override for the reservation requirement. */
  overrideReservation?: boolean;
  now?: number;
}

/** What a redeem would hand over, or the denial that stops it. */
export type GateDecision =
  | { type: 'deny'; reasonCode: string; reason: string }
  | {
      type: 'redeem';
      kind: RedemptionKind;
      amountChargedCents: number;
      decrement: 'free' | 'discount' | 'none';
      reservationId?: string;
    };

/**
 * The gate's verdict for one rider — the single place the scan's rules live.
 * `validateScan` executes what this returns and the operator's rider search
 * renders it as the rider's standing, so the panel can never promise a day the
 * server would refuse, and the two can't drift apart.
 *
 * Order is the validator's own: pass state, same-day rule, allotment,
 * reservation, then free → discounted → nothing left.
 */
export function gateDecision(inp: GateInputs): GateDecision {
  const { pass, allotment, reservation, trackName } = inp;
  const now = inp.now ?? Date.now();

  if (!pass) {
    return { type: 'deny', reasonCode: 'NO_PASS', reason: 'This rider has no pass on their account.' };
  }
  if (pass.status === PassStatus.CANCELLED) {
    return { type: 'deny', reasonCode: 'PASS_CANCELLED', reason: 'This pass has been cancelled.' };
  }
  if (pass.status === PassStatus.PENDING) {
    return { type: 'deny', reasonCode: 'PASS_NOT_ACTIVATED', reason: 'This pass has not been activated yet.' };
  }
  if (pass.status === PassStatus.EXPIRED || pass.expiresAt.getTime() < now) {
    return {
      type: 'deny',
      reasonCode: 'PASS_EXPIRED',
      reason: `Pass expired on ${pass.expiresAt.toISOString().slice(0, 10)}.`,
    };
  }
  if (inp.redeemedToday) {
    return { type: 'deny', reasonCode: 'ALREADY_USED_TODAY', reason: 'Pass already used today at this track.' };
  }
  if (!allotment) {
    return { type: 'deny', reasonCode: 'TRACK_NOT_PARTICIPATING', reason: 'This pass is not valid at this track.' };
  }

  const freeRemaining = Math.max(allotment.includedDays - allotment.freeDaysUsed, 0);
  const discountRemaining = Math.max(allotment.discountDaysAllowed - allotment.discountDaysUsed, 0);

  if (reservation && reservation.dayConsumed) {
    // Day already spent at confirmation — this scan is the check-in.
    return {
      type: 'redeem',
      kind: RedemptionKind.FREE,
      amountChargedCents: 0,
      decrement: 'none',
      reservationId: reservation.id,
    };
  }
  if (!reservation && allotment.reservationRequired && !inp.overrideReservation) {
    return {
      type: 'deny',
      reasonCode: 'RESERVATION_REQUIRED',
      reason: 'This track requires a reservation for today. Book in the rider portal.',
    };
  }
  if (reservation && allotment.dayConsumePolicy === 'ON_CONFIRM' && !reservation.dayConsumed) {
    // Policy ON_CONFIRM but day not yet consumed (e.g. confirmed outside flow) — consume now.
    return {
      type: 'redeem',
      kind: RedemptionKind.FREE,
      amountChargedCents: 0,
      decrement: 'free',
      reservationId: reservation.id,
    };
  }
  if (freeRemaining > 0) {
    return {
      type: 'redeem',
      kind: RedemptionKind.FREE,
      amountChargedCents: 0,
      decrement: 'free',
      reservationId: reservation?.id,
    };
  }
  if (allotment.discountDayEnabled && discountRemaining > 0) {
    const price = Math.round(allotment.extraDayPriceCents * (1 - allotment.discountRate));
    return {
      type: 'redeem',
      kind: RedemptionKind.DISCOUNT,
      amountChargedCents: price,
      decrement: 'discount',
      reservationId: reservation?.id,
    };
  }
  return {
    type: 'deny',
    reasonCode: 'NO_DAYS_REMAINING',
    reason: `No days remaining at ${trackName} this season.`,
  };
}

/** A rider's standing at the gate: the verdict above, plus the counters and
    the day they already rode, in the shape the operator's panel renders. */
export interface GateStanding {
  /** true when nothing stands between this rider and a redeemed day. */
  ok: boolean;
  reasonCode: string | null;
  reason: string | null;
  /** What a redeem would hand over: a free day or a paid extra day. */
  kind: 'FREE' | 'DISCOUNT' | null;
  amountChargedCents: number | null;
  /** Today's entry at this track, if there already is one. */
  redeemedTodayAt: string | null;
  redeemedTodayKind: string | null;
  reservationRequired: boolean;
  reservationBooked: boolean;
  includedDays: number | null;
  freeDaysRemaining: number | null;
  discountDaysRemaining: number | null;
}

/** Build the panel's read off the decision, so the wording of a block is
    always the sentence a scan would print. */
export function gateStanding(
  decision: GateDecision,
  extras: {
    redeemedTodayAt?: Date | null;
    redeemedTodayKind?: string | null;
    reservationRequired?: boolean;
    reservationBooked?: boolean;
    allotment?: GateAllotment | null;
  } = {}
): GateStanding {
  const a = extras.allotment ?? null;
  return {
    ok: decision.type === 'redeem',
    reasonCode: decision.type === 'deny' ? decision.reasonCode : null,
    reason: decision.type === 'deny' ? decision.reason : null,
    kind: decision.type === 'redeem' ? (decision.kind as 'FREE' | 'DISCOUNT') : null,
    amountChargedCents: decision.type === 'redeem' ? decision.amountChargedCents : null,
    redeemedTodayAt: extras.redeemedTodayAt ? extras.redeemedTodayAt.toISOString() : null,
    redeemedTodayKind: extras.redeemedTodayKind ?? null,
    reservationRequired: extras.reservationRequired ?? a?.reservationRequired ?? false,
    reservationBooked: extras.reservationBooked ?? false,
    includedDays: a?.includedDays ?? null,
    freeDaysRemaining: a ? Math.max(a.includedDays - a.freeDaysUsed, 0) : null,
    discountDaysRemaining: a ? Math.max(a.discountDaysAllowed - a.discountDaysUsed, 0) : null,
  };
}

interface ScanInput {
  token: string;
  trackId: string;
  stationId?: string | null;
  operatorId?: string | null;
  /** Admin/operator override for the reservation requirement (recorded in the log). */
  overrideReservation?: boolean;
}

async function logEvent(input: {
  trackId: string;
  stationId?: string | null;
  passId?: string | null;
  userId?: string | null;
  riderName?: string | null;
  result: ScanResult;
  reasonCode: string;
  reason: string;
  kind?: RedemptionKind | null;
  remainingFreeDays?: number | null;
  amountChargedCents?: number;
  operatorId?: string | null;
}) {
  await prisma.scanEvent.create({
    data: {
      trackId: input.trackId,
      stationId: input.stationId ?? null,
      passId: input.passId ?? null,
      userId: input.userId ?? null,
      riderName: input.riderName ?? null,
      result: input.result,
      reasonCode: input.reasonCode,
      reason: input.reason,
      kind: input.kind ?? null,
      remainingFreeDays: input.remainingFreeDays ?? null,
      amountChargedCents: input.amountChargedCents ?? 0,
      operatorId: input.operatorId ?? null,
    },
  });
}

function deny(
  input: ScanInput,
  reasonCode: string,
  reason: string,
  ctx: Partial<ScanOutcome> = {}
): Promise<ScanOutcome> {
  return logEvent({
    trackId: input.trackId,
    stationId: input.stationId,
    passId: ctx.pass?.id,
    userId: ctx.rider?.id,
    riderName: ctx.rider?.name,
    result: ScanResult.DENIED,
    reasonCode,
    reason,
    operatorId: input.operatorId,
  }).then(() => ({ result: ScanResult.DENIED, reasonCode, reason, approved: false, ...ctx }));
}

/**
 * Validate a scan server-side. The client never sends a pre-computed verdict —
 * it sends the QR token; everything below runs against the live ledger.
 */
export async function validateScan(input: ScanInput): Promise<ScanOutcome> {
  // 1. Signature + expiry (anti-replay: tokens are short-lived + nonced).
  const verified = verifyQrToken(input.token);
  if (!verified.ok) {
    return deny(input, verified.reasonCode, verified.reason);
  }
  const { p: passId, u: userId } = verified.payload;

  // 2. Load the pass + rider + tier + track context.
  const pass = await prisma.pass.findUnique({
    where: { id: passId },
    include: { user: true, tier: true },
  });
  if (!pass || pass.userId !== userId) {
    return deny(input, 'PASS_NOT_FOUND', 'Pass not found for this rider.');
  }

  const track = await prisma.track.findUnique({ where: { id: input.trackId } });
  if (!track) return deny(input, 'TRACK_NOT_FOUND', 'Scanning station is not linked to a track.');

  const rider = { id: pass.user.id, name: pass.user.name, email: pass.user.email };
  const passInfo = {
    id: pass.id,
    status: pass.status,
    seasonYear: pass.seasonYear,
    expiresAt: pass.expiresAt.toISOString(),
    tierName: pass.tier.name,
  };
  const ctx: Partial<ScanOutcome> = { rider, track: { id: track.id, name: track.name }, pass: passInfo };

  // 3. Pass state, then every rule below, come from `gateDecision` — the one
  // copy of them, which the operator's rider search reads too.
  const today = todayKey();

  // 4–7. The rules themselves live in one place so the operator's rider
  // search can print the same verdict before the tap. Read every row the
  // decision needs, then let it decide.
  const [todaysReds, allotment, reservation] = await Promise.all([
    // Same-day rule: a pass covers one ride day at this track.
    prisma.redemption.findMany({
      where: { userId, trackId: track.id, day: today },
      select: { kind: true },
    }),
    prisma.allotment.findUnique({
      where: {
        userId_trackId_seasonYear: { userId, trackId: track.id, seasonYear: pass.seasonYear },
      },
    }),
    prisma.reservation.findFirst({
      where: {
        userId,
        trackId: track.id,
        date: today,
        status: { in: [ReservationStatus.CONFIRMED, ReservationStatus.PENDING] },
      },
    }),
  ]);

  const freeRemaining = allotment
    ? Math.max(allotment.includedDays - allotment.freeDaysUsed, 0)
    : 0;
  const discountRemaining = allotment
    ? Math.max(allotment.discountDaysAllowed - allotment.discountDaysUsed, 0)
    : 0;
  const baseCtx: Partial<ScanOutcome> = {
    ...ctx,
    ...(allotment
      ? {
          includedDays: allotment.includedDays,
          remainingFreeDays: freeRemaining,
          discountDaysRemaining: discountRemaining,
        }
      : {}),
  };

  const decision = gateDecision({
    pass: { status: pass.status, expiresAt: pass.expiresAt },
    trackName: track.name,
    redeemedToday: todaysReds.length > 0,
    allotment,
    reservation: reservation ? { id: reservation.id, dayConsumed: reservation.dayConsumed } : null,
    overrideReservation: input.overrideReservation,
  });

  if (decision.type === 'deny') {
    return deny(input, decision.reasonCode, decision.reason, baseCtx);
  }

  return completeRedemption(input, {
    pass,
    rider,
    trackId: track.id,
    kind: decision.kind,
    amountChargedCents: decision.amountChargedCents,
    decrement: decision.decrement,
    reservationId: decision.reservationId,
    ctx: baseCtx,
  });
}

async function completeRedemption(
  input: ScanInput,
  args: {
    pass: {
      id: string;
      userId: string;
      seasonId: string;
      seasonYear: number;
    };
    rider: { id: string; name: string; email: string };
    trackId: string;
    kind: RedemptionKind;
    amountChargedCents: number;
    decrement: 'free' | 'discount' | 'none';
    reservationId?: string;
    ctx: Partial<ScanOutcome>;
  }
): Promise<ScanOutcome> {
  const today = todayKey();
  const { pass, rider, trackId, kind, amountChargedCents, decrement } = args;

  const result = await prisma.$transaction(async (tx) => {
    const redemption = await tx.redemption.create({
      data: {
        userId: rider.id,
        passId: pass.id,
        trackId,
        stationId: input.stationId ?? null,
        kind,
        day: today,
        amountChargedCents,
        operatorId: input.operatorId ?? null,
        reservationId: args.reservationId ?? null,
      },
    });

    const allotment = await tx.allotment.update({
      where: {
        userId_trackId_seasonYear: {
          userId: rider.id,
          trackId,
          seasonYear: pass.seasonYear,
        },
      },
      data:
        decrement === 'free'
          ? { freeDaysUsed: { increment: 1 } }
          : decrement === 'discount'
            ? { discountDaysUsed: { increment: 1 } }
            : {},
    });

    if (args.reservationId) {
      await tx.reservation.update({
        where: { id: args.reservationId },
        data: {
          status: ReservationStatus.COMPLETED,
          dayConsumed: true,
          dayConsumedAt: new Date(),
        },
      });
    }

    return { redemption, allotment };
  });

  const freeRemaining = Math.max(result.allotment.includedDays - result.allotment.freeDaysUsed, 0);
  const discountRemaining = Math.max(
    result.allotment.discountDaysAllowed - result.allotment.discountDaysUsed,
    0
  );
  await logEvent({
    trackId,
    stationId: input.stationId,
    passId: pass.id,
    userId: rider.id,
    riderName: rider.name,
    result: ScanResult.APPROVED,
    reasonCode: kind === RedemptionKind.DISCOUNT ? 'APPROVED_DISCOUNT' : 'APPROVED',
    reason:
      kind === RedemptionKind.DISCOUNT
        ? `Approved — discounted extra day ($${(amountChargedCents / 100).toFixed(2)} due at the window).`
        : 'Approved.',
    kind,
    remainingFreeDays: freeRemaining,
    amountChargedCents,
    operatorId: input.operatorId,
  });

  return {
    // ctx first: the freshly recomputed counters below must win over any
    // pre-scan snapshot carried in ctx.
    ...args.ctx,
    result: ScanResult.APPROVED,
    approved: true,
    reasonCode: kind === RedemptionKind.DISCOUNT ? 'APPROVED_DISCOUNT' : 'APPROVED',
    reason:
      kind === RedemptionKind.DISCOUNT
        ? 'Approved — discounted extra day.'
        : 'Approved.',
    kind,
    amountChargedCents,
    redemptionId: result.redemption.id,
    remainingFreeDays: freeRemaining,
    includedDays: result.allotment.includedDays,
    discountDaysRemaining: discountRemaining,
  };
}

/**
 * Re-entry: the rider already spent today's visit at this track and is coming
 * back through the gate. Nothing moves — the day was taken at the first scan,
 * no allotment is decremented and no money is owed — so this only writes the
 * pass-through to the same event log the scans read back, which keeps today's
 * record of the gate whole.
 *
 * The rules are the scan's own pass checks plus the inverse same-day rule: a
 * rider with no entry today has nothing to re-enter, and is told so.
 */
export async function completeReentry(args: {
  riderId: string;
  trackId: string;
  stationId?: string | null;
  operatorId?: string | null;
}): Promise<ScanOutcome> {
  /** `deny` and `logEvent` read only the track, station and operator. */
  const gate = {
    token: '',
    trackId: args.trackId,
    stationId: args.stationId ?? null,
    operatorId: args.operatorId ?? null,
  };

  const rider = await prisma.user.findUnique({
    where: { id: args.riderId },
    select: { id: true, name: true, email: true },
  });
  if (!rider) {
    return deny(gate, 'NO_PASS', 'This rider has no pass on their account.');
  }

  const pass = await getCurrentPass(rider.id);
  const ctx: Partial<ScanOutcome> = {
    rider,
    pass: pass
      ? {
          id: pass.id,
          status: pass.status,
          seasonYear: pass.seasonYear,
          expiresAt: pass.expiresAt.toISOString(),
          tierName: pass.tier.name,
        }
      : undefined,
  };

  if (!pass) {
    return deny(gate, 'NO_PASS', 'This rider has no pass on their account.', ctx);
  }
  if (pass.status === PassStatus.CANCELLED) {
    return deny(gate, 'PASS_CANCELLED', 'This pass has been cancelled.', ctx);
  }
  if (pass.status === PassStatus.PENDING) {
    return deny(gate, 'PASS_NOT_ACTIVATED', 'This pass has not been activated yet.', ctx);
  }
  if (pass.status === PassStatus.EXPIRED || pass.expiresAt.getTime() < Date.now()) {
    return deny(gate, 'PASS_EXPIRED', `Pass expired on ${pass.expiresAt.toISOString().slice(0, 10)}.`, ctx);
  }

  // The inverse same-day rule: a re-entry is a second way through the same
  // day's gate, so there has to have been a first.
  const entry = await prisma.redemption.findFirst({
    where: { userId: rider.id, trackId: args.trackId, day: todayKey() },
    select: { id: true },
  });
  if (!entry) {
    return deny(gate, 'NOT_REDEEMED_TODAY', 'No entry to re-enter today at this track.', ctx);
  }

  const reason = 'Re-entry. The day was already redeemed, nothing was charged.';
  await logEvent({
    trackId: args.trackId,
    stationId: args.stationId ?? null,
    passId: pass.id,
    userId: rider.id,
    riderName: rider.name,
    result: ScanResult.APPROVED,
    reasonCode: 'RE_ENTRY',
    reason,
    operatorId: args.operatorId ?? null,
  });

  return {
    ...ctx,
    result: ScanResult.APPROVED,
    approved: true,
    reasonCode: 'RE_ENTRY',
    reason,
  };
}

import crypto from 'crypto';
import { Response } from 'express';
import config from '../config';
import { prisma } from '../utils/prisma';
import { addDays } from '../utils/dates';

export function hashToken(token: string): string {
  return crypto.createHash('sha256').update(token).digest('hex');
}

export async function createSession(
  userId: string,
  meta: { userAgent?: string; ip?: string } = {}
): Promise<{ token: string; expiresAt: Date }> {
  const token = crypto.randomBytes(32).toString('hex');
  const expiresAt = addDays(new Date(), config.session.ttlDays);
  await prisma.session.create({
    data: {
      userId,
      tokenHash: hashToken(token),
      userAgent: meta.userAgent?.slice(0, 250),
      ip: meta.ip,
      expiresAt,
    },
  });
  return { token, expiresAt };
}

export async function resolveSession(token: string | undefined) {
  if (!token) return null;
  const session = await prisma.session.findUnique({
    where: { tokenHash: hashToken(token) },
    include: { user: true },
  });
  if (!session) return null;
  if (session.expiresAt.getTime() < Date.now()) {
    await prisma.session.delete({ where: { id: session.id } }).catch(() => undefined);
    return null;
  }
  if (!session.user.isActive) return null;
  return session;
}

export async function destroySession(token: string | undefined) {
  if (!token) return;
  await prisma.session.deleteMany({ where: { tokenHash: hashToken(token) } });
}

export function setSessionCookie(res: Response, token: string, expiresAt: Date) {
  res.cookie(config.session.cookieName, token, {
    httpOnly: true,
    sameSite: 'lax',
    secure: config.isProd,
    expires: expiresAt,
    path: '/',
  });
}

export function clearSessionCookie(res: Response) {
  res.clearCookie(config.session.cookieName, { path: '/' });
}

/**
 * Enum values for the SQLite-backed schema.
 *
 * SQLite has no native enum type, so Prisma stores these as String and the
 * allowed values are defined here — used as both a value object and a type,
 * mirroring the `import { X } from '@prisma/client'` API the app code expects.
 */

function makeEnum<const T extends readonly string[]>(...values: T) {
  return values.reduce(
    (acc, v) => {
      (acc as Record<string, string>)[v] = v;
      return acc;
    },
    {} as { [K in T[number]]: K }
  );
}

export const Role = makeEnum('RIDER', 'OPERATOR', 'ADMIN');
export type Role = (typeof Role)[keyof typeof Role];

export const PassStatus = makeEnum('PENDING', 'ACTIVE', 'EXPIRED', 'CANCELLED');
export type PassStatus = (typeof PassStatus)[keyof typeof PassStatus];

export const ReservationStatus = makeEnum(
  'PENDING',
  'CONFIRMED',
  'CANCELLED',
  'COMPLETED',
  'NO_SHOW'
