export interface ApiEnvelope<T> {
  success: boolean;
  message: string;
  data?: T;
  errors?: unknown;
}

export interface Pagination {
  page: number;
  limit: number;
  total: number;
  totalPages: number;
}

export function success<T>(data: T, message = 'OK') {
  return { success: true, message, data };
}

export function error(message: string, errors?: unknown) {
  return { success: false, message, ...(errors !== undefined ? { errors } : {}) };
}

export function paginated<T>(items: T[], total: number, page: number, limit: number) {
  return {
    success: true,
    message: 'OK',
    data: items,
    pagination: {
      page,
      limit,
      total,
      totalPages: Math.max(Math.ceil(total / limit), 1),
    },
  };
}

/** Minimal RFC-4180 CSV writer — quotes fields when needed. */
export function toCsv(rows: Record<string, unknown>[]): string {
  if (!rows.length) return '';
  const headers = Object.keys(rows[0]);
  const escape = (v: unknown) => {
    const s = v === null || v === undefined ? '' : String(v);
    return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
  };
  const lines = [headers.map(escape).join(',')];
  for (const row of rows) {
    lines.push(headers.map((h) => escape(row[h])).join(','));
  }
  return lines.join('\r\n') + '\r\n';
}

/**
 * Date helpers. Ride days are date-only keys stored as UTC midnight.
 *
 * `dayKey` reads the *UTC* components of what it is handed, so it is only for
 * naming an existing instant ("which calendar day is this timestamp?"). Feeding
 * it `new Date()` to mean "today" is wrong: at 9:54 PM Eastern the clock is
 * already 02:54Z tomorrow, so the day key comes out a day ahead. Use
 * `todayKey()` for today.
 */

export function dayKey(d: Date | string): Date {
  const date = typeof d === 'string' ? new Date(d) : d;
  return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()));
}

/**
 * Today on the venue's own clock: the local year/month/date, stored as a
 * UTC-midnight key so it compares directly against `day` columns. A redemption
 * filed at 9:54 PM belongs to the night it happened, not to tomorrow, so the
 * gate's day rolls over at local midnight.
 */
export function todayKey(): Date {
  const now = new Date();
  return new Date(Date.UTC(now.getFullYear(), now.getMonth(), now.getDate()));
}

export function addDays(d: Date, days: number): Date {
  const copy = new Date(d);
  copy.setUTCDate(copy.getUTCDate() + days);
  return copy;
}

export function isSameDay(a: Date, b: Date): boolean {
  return a.getTime() === b.getTime();
}

export function seasonBounds(year: number): { startsAt: Date; endsAt: Date } {
  // Calendar-year season: Jan 1 00:00 UTC through Dec 31 23:59:59 UTC.
  return {
    startsAt: new Date(Date.UTC(year, 0, 1, 0, 0, 0)),
    endsAt: new Date(Date.UTC(year, 11, 31, 23, 59, 59)),
  };
}

export function formatDay(d: Date | string): string {
  const date = typeof d === 'string' ? new Date(d) : d;
  return date.toISOString().slice(0, 10);
}

const levels = { debug: 10, info: 20, warn: 30, error: 40 } as const;
type Level = keyof typeof levels;

const colors: Record<Level, string> = {
  debug: '\x1b[36m',
  info: '\x1b[32m',
  warn: '\x1b[33m',
  error: '\x1b[31m',
};
const RESET = '\x1b[0m';

const threshold: number =
  levels[(process.env.LOG_LEVEL as Level) in levels ? (process.env.LOG_LEVEL as Level) : 'info'];

function write(level: Level, msg: string, meta?: unknown) {
  if (levels[level] < threshold) return;
  const line = `${colors[level]}[${level.toUpperCase()}]${RESET} ${new Date().toISOString()} ${msg}`;
  const fn = level === 'error' ? console.error : level === 'warn' ? console.warn : console.log;
  if (meta !== undefined) fn(line, meta);
  else fn(line);
}

export const logger = {
  debug: (m: string, meta?: unknown) => write('debug', m, meta),
  info: (m: string, meta?: unknown) => write('info', m, meta),
  warn: (m: string, meta?: unknown) => write('warn', m, meta),
  error: (m: string, meta?: unknown) => write('error', m, meta),
};

export default logger;

