import crypto from 'crypto';
import config from '../config';

/**
 * QR scan tokens.
 *
 * The rider portal never renders a static, long-lived payload. It requests a
 * short-lived token from the server (GET /api/pass/qr-token) which is signed
 * with the server's QR secret and carries an expiry + random nonce. A
 * screenshot of an old QR therefore fails validation, and every scan is
 * re-validated server-side against the live ledger — the client never decides
 * whether a pass is good.
 *
 * Payload (base64url JSON): { p: passId, u: userId, n: nonce, e: expiryEpoch }
 * Token: <payload>.<hmac>
 */

export interface QrPayload {
  p: string; // passId
  u: string; // userId
  n: string; // nonce (anti-replay)
  e: number; // expiry, unix seconds
}

function b64url(input: Buffer | string): string {
  return Buffer.from(input).toString('base64url');
}

function sign(payloadB64: string): string {
  return crypto
    .createHmac('sha256', config.qr.signingSecret)
    .update(payloadB64)
    .digest('base64url');
}

export function issueQrToken(passId: string, userId: string, ttlSeconds?: number): {
  token: string;
  expiresAt: string;
  nonce: string;
} {
  const ttl = ttlSeconds ?? config.qr.ttlSeconds;
  const now = Math.floor(Date.now() / 1000);
  const payload: QrPayload = {
    p: passId,
    u: userId,
    n: crypto.randomBytes(12).toString('hex'),
    e: now + ttl,
  };
  const payloadB64 = b64url(JSON.stringify(payload));
  const token = `${payloadB64}.${sign(payloadB64)}`;
  return { token, expiresAt: new Date(payload.e * 1000).toISOString(), nonce: payload.n };
}

export type QrVerifyResult =
  | { ok: true; payload: QrPayload }
  | { ok: false; reasonCode: 'MALFORMED' | 'BAD_SIGNATURE' | 'EXPIRED'; reason: string };

export function verifyQrToken(token: string): QrVerifyResult {
  if (!token || typeof token !== 'string' || !token.includes('.')) {
    return { ok: false, reasonCode: 'MALFORMED', reason: 'Malformed pass code.' };
  }
  const [payloadB64, sig] = token.split('.');
  const expected = sign(payloadB64);
  const a = Buffer.from(sig || '');
  const b = Buffer.from(expected);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    return { ok: false, reasonCode: 'BAD_SIGNATURE', reason: 'Invalid pass code signature.' };
  }
  let payload: QrPayload;
  try {
    payload = JSON.parse(Buffer.from(payloadB64, 'base64url').toString('utf8'));
  } catch {
    return { ok: false, reasonCode: 'MALFORMED', reason: 'Malformed pass code.' };
  }
  if (!payload?.p || !payload?.u || !payload?.e) {
    return { ok: false, reasonCode: 'MALFORMED', reason: 'Malformed pass code.' };
  }
  if (Math.floor(Date.now() / 1000) > payload.e) {
    return {
      ok: false,
      reasonCode: 'EXPIRED',
      reason: 'Pass code expired — ask the rider to refresh their QR code.',
    };
  }
  return { ok: true, payload };
}

