// Deterministic PRNG (mulberry32) seeded from a string key, so a given account
// always renders the same pattern.
function rngFrom(str) {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  let a = h >>> 0;
  return function next() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const GRID = 5; // 5x5, left half randomized then mirrored
const SIZE = 400;
const CELL = SIZE / GRID;
const INSET = 6; // gutter between pixels
const RADIUS = 5;

function svg(key, p) {
  const rnd = rngFrom(key);

  // Left half of the grid (cols 0..2), then mirrored to cols 3..4.
  const on = [];
  const hot = [];
  for (let row = 0; row < GRID; row++) {
    for (let col = 0; col < Math.ceil(GRID / 2); col++) {
      const filled = rnd() < 0.52;
      on[row * GRID + col] = filled;
      hot[row * GRID + col] = filled && rnd() < 0.3;
    }
  }
  for (let row = 0; row < GRID; row++) {
    for (let col = 0; col < Math.floor(GRID / 2); col++) {
      const src = row * GRID + (GRID - 1 - col);
      on[src] = on[row * GRID + col];
      hot[src] = hot[row * GRID + col];
    }
  }

  // Guarantee some ink so no account renders an empty tile.
  if (!on.some(Boolean)) on[Math.floor(rnd() * GRID) * GRID + 2] = true;

  const pixels = [];
  for (let row = 0; row < GRID; row++) {
    for (let col = 0; col < GRID; col++) {
      const i = row * GRID + col;
      if (!on[i]) continue;
      const fill = hot[i] ? p.accent : p.jersey;
      const x = col * CELL + INSET;
      const y = row * CELL + INSET;
      const w = CELL - INSET * 2;
      pixels.push(`<rect x="${x}" y="${y}" width="${w}" height="${w}" rx="${RADIUS}" fill="${fill}"/>`);
    }
  }

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${SIZE} ${SIZE}" width="${SIZE}" height="${SIZE}" role="img">
  <defs>
    <linearGradient id="bg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="${p.bg1}"/>
      <stop offset="1" stop-color="${p.bg2}"/>
    </linearGradient>
  </defs>
  <rect width="${SIZE}" height="${SIZE}" fill="url(#bg)"/>
  ${pixels.join('\n  ')}
</svg>
`;
}

const out = path.join(__dirname, '..', 'public', 'avatars');
fs.mkdirSync(out, { recursive: true });
for (const [key, p] of Object.entries(palettes)) {
  fs.writeFileSync(path.join(out, `${key}.svg`), svg(key, p));
}
console.log(`wrote ${Object.keys(palettes).length} pixel-pattern avatars to ${out}`);

