/* Compare dash/gap patterns for the Redeem Pass edge. */
const path = require('path');
const fs = require('fs');
const os = require('os');
const { chromium } = require('playwright-core');

const PATTERNS = [
  ['6 on / 4 off', 6, 4],
  ['6 on / 5 off', 6, 5],
  ['8 on / 6 off', 8, 6],
  ['10 on / 6 off', 10, 6],
];

function field([label, dash, gap]) {
  const layers = ['90deg', '90deg', '0deg', '0deg']
    .map((a) => `repeating-linear-gradient(${a}, #ff8a3f 0 ${dash}px, transparent ${dash}px ${dash + gap}px)`)
    .join(',\n      ');
  return `
  <div class="item">
    <div class="cap">${label}</div>
    <div class="scan-redeem" style="--dash:${layers}; color:#e8eaed; background:#14171c;
      border-radius:6px; padding:32px 24px; text-align:center; font:600 17px/1 system-ui, sans-serif;">
      Redeem Pass
      <span class="edge" style="--dash:${layers};"></span>
    </div>
  </div>`;
}

const html = `<!doctype html><meta charset="utf-8">
<style>
  body { margin:0; padding:22px; background:#0d0f12; color:#8b93a1; font:13px/1.4 system-ui, sans-serif; }
  .item { margin-bottom:18px; }
  .cap { margin:0 0 6px; font:600 11px/1 ui-monospace, monospace; letter-spacing:.08em; text-transform:uppercase; color:#8b93a1; }
  .scan-redeem { position:relative; }
  .edge { position:absolute; inset:0; border-radius:6px; pointer-events:none; background-image:var(--dash);
    background-size:100% 1px,100% 1px,1px 100%,1px 100%;
    background-position:0 0,0 100%,0 0,100% 0; background-repeat:no-repeat; }
</style>
${PATTERNS.map(field).join('')}`;

(async () => {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  let exe = null;
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium_headless_shell-')) continue;
    const p = path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell');
    if (fs.existsSync(p)) { exe = p; break; }
