/* Headless verification of the rider's calendar (/tracks/calendar).
 *
 * The one surface: the dates at the tracks the account follows, read as the
 * week the venue's owner reads — same shell, same week grid, same cards —
 * with no editor behind it. A rider on any tier gets it (following is the free
 * tier's whole surface), and the read comes and goes with the follow control.
 *
 *   cd web && npm run verify:calendar    (dev server on :5180, API on :4010)
 *
 * The run WRITES one follow and puts it back: the free demo account (quinn)
 * unfollows a track through the API, reads that its dates left, then
 * re-follows it. If the run dies midway, reseed before trusting the demo data:
 *   cd server && npm run seed
 *
 * Uses playwright-core with an explicit browser path so it works with the
 * browsers already in ~/.cache/ms-playwright and downloads nothing.
 */
const fs = require('fs');
const path = require('path');
const os = require('os');
const { chromium } = require('playwright-core');

const BASE = process.env.CALENDAR_BASE || 'http://localhost:5180';

let pass = 0;
let fail = 0;
const check = (label, ok, detail = '') => {
  if (ok) {
    pass++;
    console.log(`  PASS  ${label}${detail ? ` — ${detail}` : ''}`);
  } else {
    fail++;
    console.log(`  FAIL  ${label}${detail ? ` — ${detail}` : ''}`);
  }
};

function findBrowser() {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium_headless_shell-')) continue;
    const p = path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell');
    if (fs.existsSync(p)) return p;
  }
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium-')) continue;
    const p = path.join(root, dir, 'chrome-linux64', 'chrome');
    if (fs.existsSync(p)) return p;
  }
  return null;
}

async function login(page, email) {
  await page.goto(`${BASE}/login`, { waitUntil: 'networkidle' });
  await page.fill('#email', email);
  await page.fill('#password', 'dialed123');
  await page.click('button[type="submit"], form button');
  await page.waitForTimeout(1200);
}

const open = async (page, url) => {
  await page.goto(`${BASE}${url}`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(900);
};

/** The shape both calendars should carry — asked of the live page, so a
 *  restyle that renames one of them fails the parity check rather than
 *  drifting quietly. */
const SHELL = [
  '.cal-top',
  '.cal-title h1',
  '.cal-editor[data-week]',
  '.cal-editor[data-month]',
  '.event-editor',
  '.event-list-head',
  '.wk',
  '.wk-grid',
  '.wk-dow',
  '.wk-allday-label',
  '.wk-times',
  '.wk-col',
];

/** What only the page that writes carries — it must not be on the rider's.
 *  A card's cover (`event-open`) is not one of them any more: both calendars
 *  open a sheet from a card, and the rider's is the read-only one, so the
 *  markers are the editor's own affordances — the Add Event control and the
 *  editor sheet — rather than the button that opens a read. */
const EDITOR = ['.cal-top button.primary', '.event-sheet:not(.event-read)', '.wk-slot', 'input', 'select[name="ev-kind"]'];

const shape = (page, selectors) =>
  page.evaluate((sels) => Object.fromEntries(sels.map((s) => [s, !!document.querySelector(s)])), selectors);

const cardVenues = (page) =>
  page.$$eval('.rider-cal .event-card-venue', (as) => [...new Set(as.map((a) => a.textContent.trim()))]);

