/* Headless verification of the site cursor, on every page.
 *
 * The cursor is a canvas + a blend-mode square, and neither a typecheck nor a
 * build can see it: it has to paint. This drives a real headless Chromium, moves
 * the pointer with real events, and reads the pixels back — the square's 6px
 * footprint, the tail that gathers while the pointer moves and clears when it
 * stops, the hairline square's hover and pressed states, and the two gates
 * (reduced motion, coarse pointer) that are supposed to switch it off.
 *
 *   cd web && npm run verify:cursor        (dev server must be running on :5180)
 *
 * Uses playwright-core with an explicit browser path so it works with the
 * browsers already in ~/.cache/ms-playwright and downloads nothing.
 */
const fs = require('fs');
const path = require('path');
const os = require('os');
const { chromium } = require('playwright-core');

const BASE = process.env.CURSOR_BASE || 'http://localhost:5180';
const ACCENT = [255, 138, 63]; // --accent, Moto Pass orange

/* The cursor has a kill switch in the component (`CURSOR_ENABLED`). While it is
   off nothing mounts, so this suite has nothing to read — it says so and exits
   clean instead of failing twenty checks against an absent layer. Read the flag
   from the component itself so the two can never disagree. */
const COMPONENT = path.join(__dirname, '..', 'src', 'components', 'CanvasCursor.tsx');
function cursorEnabled() {
  if (!fs.existsSync(COMPONENT)) return true;
  const src = fs.readFileSync(COMPONENT, 'utf8');
  return !/const\s+CURSOR_ENABLED\s*=\s*false/.test(src);
}

function findBrowser() {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  if (!fs.existsSync(root)) return null;
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium_headless_shell-')) continue;
    const p = path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell');
    if (fs.existsSync(p)) return p;
    const alt = path.join(root, dir, 'chrome-linux', 'headless_shell');
    if (fs.existsSync(alt)) return alt;
  }
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium-')) continue;
    const p = path.join(root, dir, 'chrome-linux64', 'chrome');
    if (fs.existsSync(p)) return p;
  }
  return null;
}

let fails = 0;
function check(label, ok, detail = '') {
  if (!ok) fails++;
  console.log(`${ok ? 'OK  ' : 'FAIL'}  ${label}${detail ? ` — ${detail}` : ''}`);
}

/** Everything the canvas has painted, as a footprint plus the strongest pixel. */
async function painted(page) {
  return page.evaluate(() => {
    const c = document.getElementById('canvas-cursor');
    if (!c) return null;
    const ctx = c.getContext('2d');
    const d = ctx.getImageData(0, 0, c.width, c.height).data;
    let n = 0;
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -1;
    let maxY = -1;
    let alpha = 0;
    let colour = null;
    for (let i = 0; i < d.length; i += 4) {
      if (d[i + 3] <= 8) continue;
      n++;
      const px = (i / 4) % c.width;
      const py = Math.floor(i / 4 / c.width);
      if (px < minX) minX = px;
      if (px > maxX) maxX = px;
      if (py < minY) minY = py;
      if (py > maxY) maxY = py;
      if (d[i + 3] > alpha) {
        alpha = d[i + 3];
        colour = [d[i], d[i + 1], d[i + 2]];
      }
    }
    return n
      ? { n, box: [minX, minY, maxX, maxY], w: maxX - minX + 1, h: maxY - minY + 1, alpha, colour }
      : { n: 0, box: null, w: 0, h: 0, alpha: 0, colour: null };
  });
}

async function squareState(page) {
  return page.evaluate(() => {
    const el = document.getElementById('canvas-cursor-hover');
    if (!el) return null;
    const st = getComputedStyle(el);
    const m = (st.transform.match(/matrix\(([^)]+)\)/) || [])[1];
    const scale = m ? parseFloat(m.split(',')[0]) : 1;
    return {
      opacity: parseFloat(st.opacity),
      scale,
      blend: st.mixBlendMode,
      background: st.backgroundColor,
      borderWidth: parseFloat(st.borderTopWidth),
      borderColour: st.borderTopColor,
      height: st.height,
      pressed: el.classList.contains('pressed'),
      pointerEvents: st.pointerEvents,
    };
  });
}

/** Settle the pointer somewhere and let the ease finish (it is 0.18 a frame). */
async function settle(page, x, y) {
  await page.mouse.move(x, y, { steps: 1 });
  // 0.82 per frame leaves ~1.5px after 30 frames, so a half-second is NOT
  // settled — the ease needs the better part of a second to converge.
  await page.waitForTimeout(900);
}

async function main() {
  if (!cursorEnabled()) {
    console.log('site cursor is switched off (CURSOR_ENABLED = false in CanvasCursor.tsx)');
    console.log('nothing to verify — flip the flag to true to re-run these checks');
    process.exit(0);
  }
  const exe = findBrowser();
  if (!exe) {
    console.error('No Playwright Chromium found in ~/.cache/ms-playwright.');
    process.exit(1);
  }
  const browser = await chromium.launch({ executablePath: exe });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });

  const errors = [];
  page.on('pageerror', (e) => errors.push(String(e)));

  /* --- it mounts, and it is only paint ------------------------------------ */
  await page.goto(`${BASE}/`, { waitUntil: 'networkidle' });
  await page.waitForSelector('#canvas-cursor', { timeout: 15000 });
  await page.waitForSelector('#canvas-cursor-hover', { timeout: 15000 });
  check('the canvas and the hairline square are mounted', true);

  const layers = await page.evaluate(() => {
    const c = document.getElementById('canvas-cursor');
    const h = document.getElementById('canvas-cursor-hover');
    const cs = getComputedStyle(c);
    const hs = getComputedStyle(h);
    return {
      canvasPE: cs.pointerEvents,
      canvasPos: cs.position,
      squarePE: hs.pointerEvents,
      canvasZ: +cs.zIndex,
      squareZ: +hs.zIndex,
      sheetZ: 1200, // the app's sheet layer
      native: getComputedStyle(document.body).cursor,
    };
  });
  check('neither layer takes a click', layers.canvasPE === 'none' && layers.squarePE === 'none',
    JSON.stringify(layers));
  check('both ride over the sheets and toasts', layers.canvasZ > 1200 && layers.squareZ > layers.canvasZ,
    `canvas ${layers.canvasZ}, square ${layers.squareZ}`);
  check('the native pointer is left alone', layers.native === 'auto' || layers.native === 'default',
    layers.native);

  /* --- the square on the pointer ------------------------------------------ */
  await settle(page, 620, 700);
  const rest = await painted(page);
  check('a still pointer paints a single mark', rest.n > 0 && rest.n <= 140, JSON.stringify(rest));
  // A half-pixel origin bleeds one extra antialiased column, so 6 or 7 reads.
  const nine = (v) => v === 6 || v === 7;
  check('the mark is the 6px square', nine(rest.w) && nine(rest.h), `${rest.w}x${rest.h}`);
  check('the mark is centred on the pointer',
    rest.box && Math.abs((rest.box[0] + rest.box[2]) / 2 - 620) <= 1 && Math.abs((rest.box[1] + rest.box[3]) / 2 - 700) <= 1,
    JSON.stringify(rest.box));
  check('the mark is the accent colour',
    rest.colour && rest.colour.every((v, i) => Math.abs(v - ACCENT[i]) <= 3), JSON.stringify(rest.colour));

  /* --- the tail: gathers at speed, gone at rest ---------------------------- */
  await page.mouse.move(300, 420, { steps: 1 });
  await page.waitForTimeout(300);
  await page.mouse.move(900, 460, { steps: 24 });
  const moving = await painted(page);
  const stillMoving = await painted(page);
  check('a moving pointer trails', moving.w > 40, `span ${moving.w}x${moving.h}`);
  check('the trail is fainter than the square', moving.n / Math.max(1, moving.w) > 1.2 && moving.h < 40,
    `${moving.n} px over ${moving.w}x${moving.h}`);

  await page.waitForTimeout(700);
  const stopped = await painted(page);
  check('the trail clears when the pointer stops', stopped.w <= 12 && stopped.h <= 12,
    `${stopped.w}x${stopped.h}`);
  void stillMoving;

  /* --- over something clickable ------------------------------------------- */
  const link = await page.$('header a[href="/"]');
  const box = await link.boundingBox();
  await settle(page, Math.round(box.x + box.width / 2), Math.round(box.y + box.height / 2));
  await page.waitForTimeout(400);
  const hover = await squareState(page);
  const hoverPixels = await painted(page);
  check('the hairline square comes up over a link', hover.opacity > 0.6, JSON.stringify(hover));
  check('it desaturates what it covers', hover.blend === 'saturation', hover.blend);
  // Chrome's computed border-width rounds 1.25px to 1px; the hairline is the point.
  check('it is a hairline with no ink at rest', hover.borderWidth >= 1 && hover.borderWidth <= 1.5 && hover.borderColour.replace(/ /g, '') === 'rgba(0,0,0,0)',
    `${hover.borderWidth}px ${hover.borderColour}`);
  check('it is square and about 2rem tall', hover.height === '31.99px' || hover.height === '32px',
    hover.height);
  check('the square on the pointer hands over to it', hoverPixels.n === 0 || hoverPixels.alpha < 40,
    JSON.stringify(hoverPixels));

  /* --- pressed ------------------------------------------------------------ */
  await page.mouse.down();
  await page.waitForTimeout(250);
  const pressed = await squareState(page);
  const pressedPixels = await painted(page);
  const shot = path.join(__dirname, '..', 'cursor-verification.png');
  await page.screenshot({ path: shot });
  check('a press flips the square to its pressed read', pressed.pressed, JSON.stringify(pressed));
  check('the fill drops and the hairline takes ink',
    pressed.background.replace(/ /g, '') === 'rgba(0,0,0,0)' && pressed.blend === 'normal' &&
      pressed.borderColour.replace(/ /g, '') !== 'rgba(0,0,0,0)',
    `${pressed.background} / ${pressed.blend} / ${pressed.borderColour}`);
  check('it snaps in smaller than its hover size', pressed.scale > 0.4 && pressed.scale < 0.9,
    String(pressed.scale));
  check('the square on the pointer comes back while pressed', nine(pressedPixels.w) && nine(pressedPixels.h),
    `${pressedPixels.w}x${pressedPixels.h}`);
  await page.mouse.up();
  await page.waitForTimeout(300);
  const released = await squareState(page);
  check('releasing puts the pressed read away', !released.pressed, JSON.stringify(released));

  /* --- over a button: the grey square is gone ----------------------------- */
  // The desaturating block reads as a grey rectangle stamped across the fill of
  // a CTA, and the press stamped the same square wherever the click landed — so
  // over a button neither the resting square nor the press reads.
  const btn = await page.$('button.primary');
  await btn.scrollIntoViewIfNeeded();
  const bb = await btn.boundingBox();
  await settle(page, Math.round(bb.x + bb.width / 2), Math.round(bb.y + bb.height / 2));
  await page.waitForTimeout(400);
  const onButton = await squareState(page);
  check('no square over a button at rest', onButton.opacity < 0.05, JSON.stringify(onButton));

  await page.mouse.down();
  await page.waitForTimeout(250);
  const btnPressed = await squareState(page);
  const btnPressedPixels = await painted(page);
  check('clicking a button stamps no square either', btnPressed.pressed && btnPressed.opacity < 0.05,
    JSON.stringify(btnPressed));
  check('and no square on the pointer comes back while it is down',
    btnPressedPixels.n === 0 || btnPressedPixels.alpha < 40, JSON.stringify(btnPressedPixels));
  await page.mouse.up();
  await page.waitForTimeout(250);

  /* --- the ink follows the accent token ----------------------------------- */
  await page.goto(`${BASE}/pricing`, { waitUntil: 'networkidle' });
  await settle(page, 400, 700);
  const before = await painted(page);
  await page.evaluate(() => document.documentElement.style.setProperty('--accent', '#3fd0ff'));
  await settle(page, 420, 700);
  const after = await painted(page);
  check('the ink follows --accent', after.colour && after.colour[2] > 200 && after.colour[0] < 120,
    `before ${JSON.stringify(before.colour)} after ${JSON.stringify(after.colour)}`);

  /* --- on a retina screen ------------------------------------------------- */
  // Worth its own context: at dpr 2 the backing store is twice the viewport, and
  // a canvas left at its intrinsic size lays out at 2560x1800 CSS px instead —
  // which reads as a mark that is right in the top-left corner and drifts further
  // off the pointer the further you move. Measure it, do not assume it.
  const retina = await browser.newContext({
    viewport: { width: 1280, height: 900 },
    deviceScaleFactor: 2,
  });
  const hi = await retina.newPage();
  await hi.goto(`${BASE}/`, { waitUntil: 'networkidle' });
  await hi.waitForSelector('#canvas-cursor', { timeout: 15000 });
  const layer = await hi.evaluate(() => {
    const c = document.getElementById('canvas-cursor');
    const r = c.getBoundingClientRect();
    return { dpr: window.devicePixelRatio, attr: [c.width, c.height], rect: [Math.round(r.width), Math.round(r.height)], viewport: [window.innerWidth, window.innerHeight] };
  });
  check('the layer is the viewport in CSS px at dpr 2',
    layer.dpr === 2 && layer.attr[0] === layer.viewport[0] * 2 &&
      layer.rect[0] === layer.viewport[0] && layer.rect[1] === layer.viewport[1],
    JSON.stringify(layer));

  await settle(hi, 1180, 840);
  const far = await hi.evaluate(() => {
    const c = document.getElementById('canvas-cursor');
    const d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data;
    let minX = Infinity, minY = Infinity, maxX = -1, maxY = -1;
    for (let i = 0; i < d.length; i += 4) {
      if (d[i + 3] <= 8) continue;
      const px = (i / 4) % c.width;
      const py = Math.floor(i / 4 / c.width);
      if (px < minX) minX = px;
      if (px > maxX) maxX = px;
      if (py < minY) minY = py;
      if (py > maxY) maxY = py;
    }
    const r = document.getElementById('canvas-cursor-hover').getBoundingClientRect();
    return {
      centre: [(minX + maxX) / 2 / window.devicePixelRatio, (minY + maxY) / 2 / window.devicePixelRatio],
      // The square's own box, so the -50% centring inside its transform is not
      // mine to re-derive.
      squareAt: [r.left + r.width / 2, r.top + r.height / 2],
    };
  });
  check('the mark lands on the pointer at dpr 2, far from the origin',
    Math.abs(far.centre[0] - 1180) <= 1.5 && Math.abs(far.centre[1] - 840) <= 1.5, JSON.stringify(far.centre));
  check('the hairline square lands on it too',
    Math.abs(far.squareAt[0] - 1180) <= 1 && Math.abs(far.squareAt[1] - 840) <= 1, JSON.stringify(far.squareAt));
  await retina.close();

  /* --- the two gates ------------------------------------------------------ */
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await page.goto(`${BASE}/`, { waitUntil: 'networkidle' });
  check('reduced motion gets no cursor',
    (await page.$('#canvas-cursor')) === null && (await page.$('#canvas-cursor-hover')) === null);

  await page.emulateMedia({ reducedMotion: null });
  await page.setViewportSize({ width: 390, height: 780 });
  await page.goto(`${BASE}/`, { waitUntil: 'networkidle' });
  const fineHere = await page.evaluate(() => matchMedia('(hover: hover) and (pointer: fine)').matches);
  if (!fineHere) check('a coarse pointer gets no cursor', (await page.$('#canvas-cursor')) === null);
  else check('a narrow window keeps the fine-pointer cursor', true);

  /* --- nothing thrown along the way --------------------------------------- */
  check('no page errors', errors.length === 0, errors.slice(0, 2).join(' | '));

  await browser.close();
  console.log(`\n${fails === 0 ? 'all checks passed' : `${fails} check(s) failed`}`);
  console.log(`screenshot: ${shot}`);
  process.exit(fails ? 1 : 0);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

