/* Headless verification of the network page and its map, at /tracks.
 *
 * The map is the one screen that cannot be verified by typecheck + build alone:
 * Leaflet has to mount, tiles have to load from OpenStreetMap with no API key,
 * and each pin's fill has to map to the right venue type. This drives a real
 * headless Chromium and asserts all of it.
 *
 *   cd web && npm run verify:map        (dev server must be running on :5180)
 *
 * Uses playwright-core with an explicit browser path so it works with the
 * browsers already in ~/.cache/ms-playwright and downloads nothing.
 */
const fs = require('fs');
const path = require('path');
const os = require('os');
const { chromium } = require('playwright-core');

const BASE = process.env.MAP_BASE || 'http://localhost:5180';
const API = process.env.MAP_API || 'http://localhost:4010';
const PASSWORD = 'dialed123';

function findBrowser() {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  if (!fs.existsSync(root)) return null;
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium_headless_shell-')) continue;
    const p = path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell');
    if (fs.existsSync(p)) return p;
    const alt = path.join(root, dir, 'chrome-linux', 'headless_shell');
    if (fs.existsSync(alt)) return alt;
  }
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium-')) continue;
    const p = path.join(root, dir, 'chrome-linux64', 'chrome');
    if (fs.existsSync(p)) return p;
  }
  return null;
}

let fails = 0;
function check(label, ok, detail = '') {
  if (!ok) fails++;
  console.log(`${ok ? 'OK  ' : 'FAIL'}  ${label}${detail ? ` — ${detail}` : ''}`);
}
function expect(label, actual, want) {
  const keys = Object.keys(want);
  check(label, keys.every((k) => (actual[k] || 0) === want[k]), `got ${JSON.stringify(actual)} want ${JSON.stringify(want)}`);
}

/** How many elements match, retried across a navigation. The dev server
 *  full-reloads whenever a source file is saved underneath the suite, which
 *  tears down the execution context mid-read; a settled page reads the same
 *  count, so this waits for the reload rather than failing on it. */
async function countOf(page, sel, tries = 6) {
  for (let i = 0; i < tries; i++) {
    try {
      return await page.$$eval(sel, (n) => n.length);
    } catch {
      await page.waitForLoadState('load').catch(() => {});
      await page.waitForTimeout(300);
    }
  }
  return -1;
}

/** How many venues the public network holds, read from the API at run time.
 *  The suite must not write the size down: venues come and go, and every count
 *  below (rail rows, pins, the "N of NET" read-outs) is this same number. */
async function networkCount() {
  const r = await fetch(`${API}/api/tracks?terms=public`);
  const d = await r.json();
  return (d?.data?.tracks ?? []).length;
}

async function login(page, email) {
  await page.goto(`${BASE}/login`, { waitUntil: 'networkidle' });
  await page.waitForSelector('form #email');
  await page.fill('#email', email);
  await page.fill('#password', PASSWORD);
  await Promise.all([
    page.waitForURL((u) => !u.pathname.startsWith('/login'), { timeout: 20000 }),
    page.click('form button.primary'),
  ]);
}

/** The header search folds to a single icon until it is clicked; a test that
 *  types into the field has to unfold it first (it is not on the page until
 *  then), and it hands the field the caret when it opens. */
async function unfoldSearch(page) {
  if (!(await page.$('.hs-trigger'))) return;
  await page.click('.hs-trigger');
  await page.waitForSelector('.header-search input', { timeout: 5000 });
}

/** The rail's slices sit behind the filter control now: it opens a sheet, and a
 *  pick applies the slice and puts the sheet away. Reading the slice's own state
 *  costs the same round trip, so these three are the only way in. */
async function openFilter(page) {
  if (!(await page.$('.rail-filter'))) return false;
  await page.click('.rail-filter');
  await page.waitForSelector('.rail-filter-sheet .day-filter', { timeout: 5000 });
  return true;
}
/** Escape puts the sheet away without picking anything. */
async function closeFilter(page) {
  await page.keyboard.press('Escape');
  await page.waitForTimeout(200);
}
/** The pills' own read — `label:aria-pressed` in DOM order — or [] when the rail
 *  offers no slice at all (a visitor, and any list with nothing to slice). */
async function slicePills(page) {
  if (!(await openFilter(page))) return [];
  const out = await page.$$eval('.rail-filter-sheet .day-filter button', (b) =>
    b.map((x) => `${x.textContent.trim()}:${x.getAttribute('aria-pressed')}`)
  );
  await closeFilter(page);
  return out;
}
/** Pick a slice: the sheet's own button applies it and closes the sheet. */
async function setSlice(page, label) {
  if (!(await openFilter(page))) return false;
  await page.click(`.rail-filter-sheet .day-filter button:has-text("${label}")`);
  await page.waitForTimeout(400);
  return true;
}

/** The rail opens on the whole network for a paid rider; the sections below
 *  read the whole network, so this makes sure All is the live slice. */
async function showAll(page) {
  await setSlice(page, 'All');
}

/** Pin fill, plus how many carry the dashed outline. The network is motocross
 *  only, so every pin wears the accent; the dashed cue is the one non-colour
 *  state — a shut venue for a free account, an uncovered one for a rider. */
async function pinCounts(page) {
  const m = await page.$$eval('.map-pin-wrap', (els) =>
    els.map((el) => {
      // A pin is a bare dot with its fill inline; its venue's name rides on
      // `data-name`, since the tooltip that shows it exists only once opened.
      const dot = el.querySelector('.map-pin-dot');
      const st = dot ? dot.getAttribute('style') || '' : '';
      return { label: dot ? dot.getAttribute('data-name') || '' : '', bg: (st.match(/background:([^;]+)/) || [])[1] || '', dashed: st.includes('dashed') };
    })
  );
  // Leaflet injects the badge html raw, so the colour stays as authored: the
  // pin fill reads the accent token `--accent` (accept the token or its hex).
  const norm = (s) => s.replace(/\s/g, '').toLowerCase();
  const counts = { mx: 0, dashed: 0 };
  for (const x of m) {
    const bg = norm(x.bg);
    if (bg.includes('var(--accent)') || bg.includes('#ff8a3f') || bg.includes('rgb(255,138,63)')) counts.mx++;
    if (x.dashed) counts.dashed++;
  }
  return { counts, badges: m.map((x) => x.label).join(',') };
}

/** Signed in, sitting on the network page, with the map mounted and drawn. */
async function openMap(browser, email) {
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await login(page, email);
  await page.goto(`${BASE}/tracks`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.leaflet-container', { timeout: 15000 });
  await page.waitForSelector('.map-pin-wrap', { state: 'attached', timeout: 15000 });
  await page.waitForTimeout(1200);
  return page;
}

/** Geographic footprint of the tiles Leaflet has loaded, from their z/x/y URLs. */
async function tileFootprint(page) {
  const srcs = await page.$$eval('.leaflet-tile', (els) => els.map((e) => e.src));
  const tiles = [];
  for (const src of srcs) {
    const m = src.match(/\/(\d+)\/(\d+)\/(\d+)\.png/);
    if (!m) continue;
    const z = +m[1];
    const n = 2 ** z;
    // Tile centre → lat/lng (Web Mercator inverse).
    const lng = ((+m[2] + 0.5) / n) * 360 - 180;
    const lat = (Math.atan(Math.sinh(Math.PI * (1 - (2 * (+m[3] + 0.5)) / n))) * 180) / Math.PI;
    tiles.push({ z, lat, lng });
  }
  const zooms = {};
  for (const t of tiles) zooms[t.z] = (zooms[t.z] || 0) + 1;
  const modeZoom = Object.entries(zooms).sort((a, b) => b[1] - a[1])[0]?.[0];
  return {
    count: tiles.length,
    zoom: modeZoom ? +modeZoom : null,
    lat: tiles.reduce((s, t) => s + t.lat, 0) / (tiles.length || 1),
    lng: tiles.reduce((s, t) => s + t.lng, 0) / (tiles.length || 1),
  };
}

async function main() {
  const exe = findBrowser();
  if (!exe) {
    console.error('No Playwright Chromium found in ~/.cache/ms-playwright. Run: npx playwright install chromium-headless-shell');
    process.exit(1);
  }
  const browser = await chromium.launch({ executablePath: exe });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });

  // The one number every count below is measured against — read off the API,
  // never written down here.
  const NET = await networkCount();
  check('the network the suite measures against is read at run time', NET > 0, `${NET} venues`);

  const tiles = [];
  page.on('response', (r) => {
    if (r.url().includes('tile.openstreetmap.org')) tiles.push(r.status());
  });
  const errors = [];
  page.on('pageerror', (e) => errors.push(String(e.message)));

  // ---- Rider with days everywhere except one discounted-only track -------
  await login(page, 'alex@example.com');
  await page.goto(`${BASE}/tracks`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.leaflet-container', { timeout: 15000 });
  await page.waitForSelector('.map-pin-wrap', { state: 'attached', timeout: 15000 });
  await page.waitForTimeout(2500);

  check('leaflet map mounted', await page.$eval('.leaflet-container', () => true).catch(() => false));
  check('zoom control rendered', await page.$eval('.leaflet-control-zoom', () => true).catch(() => false));
  check('dark tile filter applied', (await page.$eval('.leaflet-tile-pane', (e) => getComputedStyle(e).filter)) !== 'none');
  const bad = tiles.filter((s) => s !== 200).length;
  check('OSM tiles load keyless (referrer origin)', tiles.filter((s) => s === 200).length > 0 && bad === 0, `${tiles.filter((s) => s === 200).length} ok / ${bad} bad`);
  // The network is motocross only and the paid pass carries every venue, so the
  // rail opens on the whole network — there is no slice the tier leaves out.
  const railRows = await page.$$eval('.day-row', (r) => r.length);
  check('the rail opens on the whole network', railRows === NET, `${railRows} rows`);
  check(
    'no venue is outside the pass',
    (await page.$$eval('.day-row.not-covered', (r) => r.length)) === 0
  );
  check(
    'the rail and the pins hold the same network',
    (await page.$$eval('.day-row .day-name', (n) => n.map((e) => e.textContent.trim()).sort().join(','))) ===
      (await page.$$eval('.map-pin-wrap', (els) => els.map((e) => e.querySelector('.map-pin-dot')?.getAttribute('data-name') || '').sort().join(',')))
  );
  // ---- The venue's gate light --------------------------------------------
  // Every line leads with the venue's gate light — open, caution or closed —
  // and the light's read is the operator's own post for the day, with the
  // generic line for that status standing in when they have not made one. The
  // read is checked against the API's own copy of the day rather than against a
  // written-down one, so the seed can move.
  const GENERIC_READ = {
    OPEN: 'Open today.',
    WEATHER_HOLD: 'Caution today — check with the venue before you drive out.',
    CLOSED: 'Closed today.',
  };
  const apiTracks = await (await fetch(`${API}/api/tracks?terms=public`)).json();
  const gate = new Map((apiTracks?.data?.tracks ?? []).map((t) => [t.name, t]));
  const lights = await page.$$eval('.day-row', (rows) =>
    rows.map((r) => {
      const light = r.querySelector('.day-light');
      return {
        name: r.querySelector('.day-name').textContent.trim(),
        cls: light ? light.className : '',
        label: light?.querySelector('.day-light-tip b')?.textContent || '',
        read: (light?.querySelector('.day-light-tip span')?.textContent || '').trim(),
      };
    })
  );
  check(
    'every line leads with the venue’s gate light',
    lights.length === NET && lights.every((l) => /^day-light is-(open|caution|closed)$/.test(l.cls)),
    `${lights.length} lights`
  );
  const wrongRead = lights.filter((l) => {
    const t = gate.get(l.name);
    if (!t) return true;
    const want = (t.statusNote || '').trim() || GENERIC_READ[t.status];
    return !want || l.read !== want || l.label !== { OPEN: 'Open', WEATHER_HOLD: 'Caution', CLOSED: 'Closed' }[t.status];
  });
  check(
    'each light reads the operator’s post, or the generic line for its status',
    wrongRead.length === 0,
    wrongRead.map((l) => `${l.name}: ${l.read}`).join(' | ')
  );
  // The read opens over the line it belongs to, never clipped by the list's own
  // scroller — and it opens at all, though the line is one big overlay button
  // under it.
  const hoverLight = (await page.$('.day-row .day-light.is-caution')) || (await page.$('.day-row .day-light'));
  await hoverLight.hover();
  await page.waitForTimeout(300);
  const read = await hoverLight.evaluate((el) => {
    const t = el.querySelector('.day-light-tip');
    const r = t.getBoundingClientRect();
    const grid = document.querySelector('.day-grid').getBoundingClientRect();
    return {
      shown: getComputedStyle(t).opacity === '1' && r.width > 0,
      inside: r.left >= grid.left - 1 && r.right <= grid.right + 1 && r.top >= grid.top - 1 && r.bottom <= grid.bottom + 1,
      // The read is a card: it has to paint over the line it opens across, covering
      // that line's dot rather than sliding under it. Nothing ever points at the read
      // itself (pointer-events: none), so paint order is read as the light's z-index
      // against that neighbour's, with the card's own box over the dot's.
      covers: (() => {
        const row = el.closest('.day-row');
        const down = r.top >= el.getBoundingClientRect().bottom - 1;
        const nb = (down ? row?.nextElementSibling : row?.previousElementSibling)?.querySelector('.day-light');
        if (!nb) return true; // no line that way for the read to cover
        const n = nb.getBoundingClientRect();
        const overDot = r.left <= n.left && r.right >= n.right && r.top <= n.top && r.bottom >= n.bottom;
        const above = +getComputedStyle(el).zIndex > +getComputedStyle(nb).zIndex;
        return overDot && above;
      })(),
    };
  });
  check('hovering the light opens the read inside the rail', read.shown && read.inside, JSON.stringify(read));
  check('the read covers the line below it', read.covers, JSON.stringify(read));
  // ---- The rail's slice pill ---------------------------------------------
  // One axis, left to right: everything, then the venues this rider follows.
  // The Included slice only exists while a running pass leaves a venue out, and
  // the paid pass carries every venue in the motocross network, so a rider sees
  // the whole network and the follows list — nothing else.
  const filterPills = await slicePills(page);
  check(
    'the rail carries the All | Following slice pill',
    filterPills.join('|') === 'All:true|Following:false',
    filterPills.join('|')
  );
  // Days left is a ticket count, not a bar of blocks: one ticket mark, then
  // `N left` — the days still to tear off at that venue — with the full sentence on
  // the meter's title (and read aloud by its label).
  const dayReads = await page.$$eval('.day-row .day-meter', (els) =>
    els.map((e) => ({
      ticket: e.querySelectorAll('svg.day-ticket').length,
      count: (e.querySelector('.ticket-count strong')?.textContent || '').trim(),
      title: e.getAttribute('title') || '',
    }))
  );
  check(
    'days left reads as a ticket and its count',
    dayReads.length === NET &&
      dayReads.every((r) => r.ticket === 1 && /^\d+$/.test(r.count)) &&
      dayReads.every((r) => /^\d+ of \d+ days left$/.test(r.title)),
    `${dayReads.length} meters`
  );
  check('no row draws the old segment bar', (await page.$$eval('.seg-bar', (n) => n.length)) === 0);
  check('the bar carries no track count', (await page.$$eval('.day-count', (n) => n.length)) === 0);
  await setSlice(page, 'Following');
  // Alex follows nothing, so the filtered list is the empty state, not a blank rail.
  const alexFollowRows = await page.$$eval('.day-row', (r) => r.length);
  check('Following narrows the rail to the followed venues', alexFollowRows === 0, `${alexFollowRows} rows`);
  check('an unfollowed rail says so', /Not following a track yet/.test(await page.textContent('.pass-aux')));
  check(
    'the slice pill is one axis, not two stacked filters',
    (await slicePills(page)).map((p) => p.split(':')[1]).join('|') === 'false|true'
  );
  check('the slice leaves the map alone', (await page.$$eval('.map-pin-wrap', (n) => n.length)) === NET);
  await setSlice(page, 'All');
  check(
    'All restores the whole network',
    (await page.$$eval('.day-row', (n) => n.length)) === NET &&
      (await page.$$eval('.day-row.not-covered', (n) => n.length)) === 0
  );


  // ---- The network search, in the app header ------------------------------
  // The field rides in the shell now, not the rail: it answers for the whole
  // app (the panel under it lists the ranked matches, and picking one opens
  // that venue) and it narrows the rail's rows exactly as the All / Following
  // filter does — never the pins.
  check(
    'the search rides in the app header as one icon',
    (await page.$$eval('.header-search .hs-trigger', (n) => n.length)) === 1 &&
      (await page.$$eval('.header-search input', (n) => n.length)) === 0
  );
  await unfoldSearch(page);
  check(
    'clicking the icon opens the field, with the caret in it',
    (await page.$$eval('.header-search input', (n) => n.length)) === 1 &&
      (await page.evaluate(() => document.activeElement?.classList.contains('hs-field'))) === true
  );
  // A click away (nothing typed) folds it back to the one icon.
  await page.evaluate(() => document.dispatchEvent(new MouseEvent('mousedown', { bubbles: true })));
  await page.waitForTimeout(150);
  check(
    'clicking away with nothing typed folds the field back to the icon',
    (await page.$$eval('.header-search .hs-trigger', (n) => n.length)) === 1 &&
      (await page.$$eval('.header-search input', (n) => n.length)) === 0
  );
  await unfoldSearch(page);
  await page.fill('.header-search input', 'top gun');
  await page.waitForTimeout(300);
  const gunRows = await page.$$eval('.day-row .day-name', (n) => n.map((e) => e.textContent.trim()));
  check(
    'search narrows the rail to the matches',
    gunRows.length === 1 && gunRows[0] === 'Top Gun MX',
    gunRows.join(' | ')
  );
  check('the rail reads out how much the query left', new RegExp(`1 of ${NET}`).test(await page.textContent('.day-search-note')));
  const panelNames = await page.$$eval('.hs-row .hs-name', (n) => n.map((e) => e.textContent.trim()));
  check('the header panel lists the match', panelNames.length === 1 && panelNames[0] === 'Top Gun MX', panelNames.join(' | '));
  check('the panel shows what was typed', (await page.$$eval('.hs-row mark.hs-hit', (n) => n.length)) > 0);
  check('the panel counts the matches against the network', new RegExp(`1 of ${NET}`).test(await page.textContent('.hs-summary')));
  check('search leaves the map alone', (await page.$$eval('.map-pin-wrap', (n) => n.length)) === NET);

  // The tokens of a query are requirements, not one substring: "top nc" is Top
  // Gun in North Carolina, and "top wa" is nothing at all.
  await page.fill('.header-search input', 'top nc');
  await page.waitForTimeout(300);
  check('every token of a query has to land', (await page.$$eval('.day-row', (n) => n.length)) === 1);
  await page.fill('.header-search input', 'top wa');
  await page.waitForTimeout(300);
  check(
    'a query whose tokens do not all land finds nothing',
    /No tracks match/.test(await page.textContent('.pass-aux'))
  );

  // The search reaches past the name: where a venue is, what type it is.
  await page.fill('.header-search input', 'NC');
  await page.waitForTimeout(300);
  check(
    'search matches where a venue is, not just its name',
    (await page.$$eval('.day-row', (n) => n.length)) > 1
  );
  await page.fill('.header-search input', 'motocross');
  await page.waitForTimeout(300);
  check('search reaches the venue type', (await page.$$eval('.day-row', (n) => n.length)) === NET);

  await page.fill('.header-search input', 'zzzz');
  await page.waitForTimeout(300);
  check('a search with no match says so', /No tracks match/.test(await page.textContent('.pass-aux')));
  check(
    'the empty rail keeps its own way back',
    (await page.$$eval('.pass-aux button.ghost.small', (n) => n.length)) === 1
  );
  await page.click('.pass-aux button.ghost.small');
  await page.waitForTimeout(300);
  check(
    'clearing the search restores the network',
    (await page.$$eval('.day-row', (n) => n.length)) === NET
  );

  // Picking a match opens that venue on the network page, with the query spent
  // and the field folded back to the one icon.
  await unfoldSearch(page);
  await page.fill('.header-search input', 'washougal');
  await page.waitForTimeout(300);
  await page.click('.hs-row');
  await page.waitForTimeout(600);
  check('picking a match opens the venue', /track=washougal/.test(page.url()), page.url());
  check(
    'the pick spends the query and folds the field back to the icon',
    (await page.$$eval('.header-search input', (n) => n.length)) === 0 &&
      (await page.$$eval('.header-search .hs-trigger', (n) => n.length)) === 1
  );
  check('the panel closes behind the pick', (await page.$$eval('.hs-panel', (n) => n.length)) === 0);

  // Back to the plain network page for the sections that follow.
  await page.goto(`${BASE}/tracks`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.day-row', { timeout: 15000 });
  await showAll(page);

  // The pass lives in the top-bar account menu now: round portrait → badge + Help + Sign out.
  check('the top bar carries a round account button', (await page.$$eval('.acct-btn', (n) => n.length)) === 1);
  check('the account menu starts closed', (await page.$$eval('.acct-pop', (n) => n.length)) === 0);
  await page.click('.acct-btn');
  await page.waitForSelector('.acct-pop', { timeout: 5000 }).catch(() => {});
  check('the account menu opens the pass badge', (await page.$$eval('.acct-pop .pass-id-inner', (n) => n.length)) === 1);
  // The QR is no longer drawn in the menu: the badge carries a trigger, and the
  // live code opens on its own layer so it can be held up at the gate.
  const qrBtn = (await page.textContent('.acct-pop .pass-qr-btn').catch(() => ''))?.trim();
  check('the badge offers View QR Code', qrBtn === 'View QR Code', qrBtn);
  check('the menu no longer draws the QR itself', (await page.$$eval('.acct-pop .pass-code canvas', (n) => n.length)) === 0);
  await page.click('.acct-pop .pass-qr-btn');
  // QRCode.toCanvas paints after the token arrives, so give the canvas a beat.
  await page.waitForSelector('.qr-sheet .pass-code canvas', { timeout: 8000 }).catch(() => {});
  check('View QR Code opens the QR modal', (await page.$$eval('.qr-sheet .pass-code canvas', (n) => n.length)) === 1);
  check('the modal drops the account menu', (await page.$$eval('.acct-pop', (n) => n.length)) === 0);
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);
  check('Escape closes the QR modal', (await page.$$eval('.qr-sheet', (n) => n.length)) === 0);
  await page.click('.acct-btn');
  await page.waitForSelector('.acct-pop', { timeout: 5000 }).catch(() => {});
  const acctLinks = await page.$$eval('.acct-pop .acct-link', (n) => n.map((e) => e.textContent.trim()));
  check('the menu offers Help and Sign out', acctLinks.join('|') === 'Help|Sign out', acctLinks.join('|'));
  check('the pass card is off the page body', (await page.$$eval('.pass-page .pass-id-inner', (n) => n.length)) === 0);
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);
  check('Escape closes the account menu', (await page.$$eval('.acct-pop', (n) => n.length)) === 0);
  check('map leads the DOM (rail stacks under it on narrow screens)', (await page.$$eval('.pass-layout.with-map > *', (els) => els.map((e) => e.className).join('|'))).startsWith('pass-map'));

  // ---- The rail's pass strip ----------------------------------------------
  // The rail opens on who is reading, with the list's own two controls in the
  // same row: the filter (an icon that opens the slices) then the sort. The
  // pass's own way out (the QR sheet) lives in the account menu, not on the
  // canvas.
  check(
    'the rail names the rider and their tier',
    /Alex Rivera · Moto Pass/.test(await page.textContent('.rail-pass')),
    await page.textContent('.rail-pass-name')
  );
  check(
    'the rail head carries no control on the identity itself',
    (await page.$$eval('.rail-pass-id button, .rail-pass-qr', (n) => n.length)) === 0
  );
  check(
    'the sort rides in the rail head, not a band of its own',
    (await page.$$eval('.rail-pass .day-sort', (n) => n.length)) === 1 &&
      (await page.$$eval('.day-bar', (n) => n.length)) === 0
  );
  check(
    'the filter is an icon to the left of the sort',
    await page.$$eval('.rail-tools > *', (n) => n.map((e) => e.className).join('|')).then(
      (c) => c.startsWith('rail-filter|day-sort-wrap')
    ),
    await page.$$eval('.rail-tools > *', (n) => n.map((e) => e.className).join('|'))
  );

  const alex = await pinCounts(page);
  check('one marker per venue in the network', alex.badges.split(',').length === NET, `badges ${alex.badges}`);
  check(
    'markers carry track names, not bare day counts',
    alex.badges.split(',').every((b) => b.length > 0 && !/^\d+$/.test(b)),
    alex.badges
  );
  // One colour and no more: every venue in the motocross network reads the
  // accent, and the paid pass carries them all, so no pin is dashed.
  expect(`${NET} accent MX pins, none dashed`, alex.counts, { mx: NET, dashed: 0 });
  check(
    'the map carries no legend over the canvas',
    (await countOf(page, '.map-pane-legend')) === 0
  );
  check('the map pane carries no header strip', (await page.$$eval('.map-pane-head', (n) => n.length)) === 0);
  await page.screenshot({ path: 'map-verification.png' });

  // ---- A rail row picks its venue -----------------------------------------
  // The row is a pick, not a navigation: a click opens that venue's inspector
  // over the map's right edge and leaves the list it came from standing, its own
  // line marked. The venue's profile is one click further, from the inspector's
  // own link.
  const picked = 'Top Gun MX';
  const clickPin = async (name) => {
    // Leaflet is lazy-loaded: the rail can be up while the badges are still
    // drawing, and the pin root is a 0x0 icon so 'attached' is the right wait.
    await page.waitForSelector('.map-pin-wrap', { state: 'attached', timeout: 15000 }).catch(() => {});
    return page.$$eval(
      '.map-pin-wrap',
      (els, want) => {
        const el = els.find((e) => e.querySelector('.map-pin-dot')?.getAttribute('data-name') === want);
        if (el) el.click();
        return !!el;
      },
      name
    );
  };
  const rowHandles = await page.$$('.day-row');
  let clicked = false;
  for (const row of rowHandles) {
    const text = (await row.textContent()) || '';
    if (text.includes(picked)) {
      await row.$eval('.day-open', (b) => b.click());
      clicked = true;
      break;
    }
  }
  await page.waitForSelector('.venue-float .track-panel', { timeout: 10000 }).catch(() => {});
  check(
    `clicking the ${picked} row opens its inspector`,
    clicked && (await page.$$eval('.venue-float .track-panel', (n) => n.length)) === 1
  );
  check('the inspector names the venue', (await page.textContent('.venue-float .track-panel-body h2')).trim() === picked);
  check('the rail keeps its list while the inspector is open', (await page.$$eval('.day-row', (n) => n.length)) === NET);
  check(
    'the row it came from reads as the picked one',
    (await page.$$eval('.day-row.selected .day-name', (n) => n.map((e) => e.textContent.trim()).join(''))) === picked
  );
  check('picking a row is not a page change', new URL(page.url()).pathname === '/tracks', page.url());
  // The pick also brings the venue to the middle of the canvas. The rail floats
  // over the left edge and the inspector over the right at the same width, so
  // the map pane's own centre is what a centred pick is measured against. A pan
  // alone would not do it: at the country scale the viewport is wider than the
  // US bounds, so the pick has to come in to a closer zoom to move at all.
  await page.waitForTimeout(1500);
  const centred = await page.evaluate(() => {
    const pane = document.querySelector('.map-pane').getBoundingClientRect();
    const pin = document.querySelector('.map-pin-wrap.on')?.getBoundingClientRect();
    if (!pin) return null;
    return {
      dx: Math.round(pin.x + pin.width / 2 - (pane.x + pane.width / 2)),
      dy: Math.round(pin.y + pin.height / 2 - (pane.y + pane.height / 2)),
    };
  });
  check(
    `picking ${picked} brings it to the middle of the map`,
    !!centred && Math.abs(centred.dx) <= 3 && Math.abs(centred.dy) <= 3,
    centred ? `${centred.dx}px across, ${centred.dy}px down` : 'no lit pin to measure'
  );
  await page.screenshot({ path: 'map-centred-pick.png' });
  // A second click on the same line puts the inspector away again, and the map
  // goes back to every pin lit.
  const pickRow = (name) =>
    page.$$eval(
      '.day-row',
      (rows, want) => {
        const r = rows.find((x) => x.textContent.includes(want));
        if (r) r.querySelector('.day-open').click();
        return !!r;
      },
      name
    );
  await pickRow(picked);
  await page.waitForTimeout(500);
  check('a second click on the picked row puts the inspector away', (await page.$$eval('.venue-float', (n) => n.length)) === 0);
  check('and the map goes back to every pin lit', (await page.$$eval('.map-pin-wrap.dim', (n) => n.length)) === 0);
  // The venue's own profile is one click on from the inspector: pick it again.
  await pickRow(picked);
  await page.waitForSelector('.venue-float .track-links-btn', { timeout: 5000 }).catch(() => {});
  await page.click('.venue-float .track-links-btn');
  await page.waitForSelector('.profile-head', { timeout: 10000 }).catch(() => {});
  check(
    'the inspector link opens the venue profile',
    /^\/tracks\/[a-z0-9-]+$/.test(new URL(page.url()).pathname),
    page.url()
  );
  check('the profile names the venue', (await page.textContent('.profile-head h1')).trim() === picked);

  // ---- A pin picks the same venue -----------------------------------------
  // The badge is the map's other pick: it opens the same inspector, lifts its
  // own pin out of the rest, and the close control puts the inspector away and
  // re-lights the map.
  await page.goto(`${BASE}/tracks`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.day-row', { timeout: 15000 });
  await showAll(page);
  // The frame the whole network is fitted to, read off the untouched page: the
  // bare click below has to hand this exact scale back.
  await page.waitForTimeout(600);
  const frameZoom = (await tileFootprint(page)).zoom;
  await clickPin(picked);
  await page.waitForSelector('.track-close', { timeout: 5000 }).catch(() => {});
  check('a pin pick opens the same inspector', (await page.$$eval('.venue-float .track-panel', (n) => n.length)) === 1);
  check('a pin pick leaves the list standing too', (await page.$$eval('.day-row', (n) => n.length)) === NET);
  // The pin is the map's own entry to a pick, so it centres the same venue the
  // row does — measured off the page it was just reloaded on, i.e. from the
  // country scale the map starts at.
  await page.waitForTimeout(1500);
  const pinCentred = await page.evaluate(() => {
    const pane = document.querySelector('.map-pane').getBoundingClientRect();
    const pin = document.querySelector('.map-pin-wrap.on')?.getBoundingClientRect();
    if (!pin) return null;
    return {
      dx: Math.round(pin.x + pin.width / 2 - (pane.x + pane.width / 2)),
      dy: Math.round(pin.y + pin.height / 2 - (pane.y + pane.height / 2)),
    };
  });
  check(
    'a pin pick centres the venue too',
    !!pinCentred && Math.abs(pinCentred.dx) <= 3 && Math.abs(pinCentred.dy) <= 3,
    pinCentred ? `${pinCentred.dx}px across, ${pinCentred.dy}px down` : 'no lit pin to measure'
  );
  // A bare click on the map — a click that lands on no pin and on none of the
  // chrome floating over the canvas — is the third way out of a pick: the
  // inspector goes away, every pin comes back up, and the map returns to the
  // frame the whole network was fitted to, so the reader is not left at metro
  // scale with the rest of the country out of sight.
  await page.waitForTimeout(400);
  const bare = await page.evaluate(() => {
    const pane = document.querySelector('.map-pane').getBoundingClientRect();
    for (const [fx, fy] of [[0.5, 0.62], [0.46, 0.72], [0.54, 0.42], [0.5, 0.3]]) {
      const x = Math.round(pane.x + pane.width * fx);
      const y = Math.round(pane.y + pane.height * fy);
      const el = document.elementFromPoint(x, y);
      if (el && el.closest('.leaflet-container') && !el.closest('.map-pin-wrap') && !el.closest('.map-chrome')) {
        return { x, y };
      }
    }
    return null;
  });
  check('the canvas has a bare spot to click', !!bare);
  await page.mouse.click(bare.x, bare.y);
  await page.waitForTimeout(1200);
  check('a bare map click puts the inspector away', (await page.$$eval('.venue-float', (n) => n.length)) === 0);
  check('a bare map click re-lights every pin', (await page.$$eval('.map-pin-wrap.dim', (n) => n.length)) === 0);
  const backOut = await tileFootprint(page);
  check(
    'a bare map click zooms back out to the whole network',
    backOut.zoom !== null && backOut.zoom === frameZoom,
    `z ${backOut.zoom} (frame was z ${frameZoom})`
  );

  // The inspector's own close control is the third way out, so it is measured on
  // an inspector that is open: pick the pin again first.
  await clickPin(picked);
  await page.waitForSelector('.track-close', { timeout: 5000 }).catch(() => {});
  await page.click('.track-close');
  await page.waitForTimeout(400);
  check('the close control puts the inspector away', (await page.$$eval('.venue-float', (n) => n.length)) === 0);
  check('the close control re-lights every pin', (await page.$$eval('.map-pin-wrap.dim', (n) => n.length)) === 0);

  // ---- A pin pick brings its own row into the rail -------------------------
  // The map carries the whole network; the rail shows only as many rows as the
  // window is tall, so a pin for a venue low in the list would open an inspector
  // whose own line sits off the scroller. The pick scrolls the list to it — and
  // leaves the list where it is when the row is already on it.
  await page.$eval('.day-grid', (el) => el.scrollTo(0, 0));
  await page.waitForTimeout(150);
  const rowNames = await page.$$eval('.day-row .day-name', (n) => n.map((e) => e.textContent.trim()));
  const lastRowName = rowNames[rowNames.length - 1];
  const setRowState = await page.evaluate(() => {
    const grid = document.querySelector('.day-grid');
    const rows = [...document.querySelectorAll('.day-row')];
    const f = grid.getBoundingClientRect();
    const last = rows[rows.length - 1].getBoundingClientRect();
    const first = rows[0].getBoundingClientRect();
    return { lastOff: last.bottom > f.bottom, firstOn: first.top >= f.top && first.bottom <= f.bottom };
  });
  check(
    `the rail starts with ${lastRowName} off its view`,
    setRowState.lastOff && setRowState.firstOn,
    `last off: ${setRowState.lastOff} / first on: ${setRowState.firstOn}`
  );
  await clickPin(lastRowName);
  const broughtIn = await page
    .waitForFunction(
      () => {
        const grid = document.querySelector('.day-grid');
        const row = document.querySelector('.day-row.selected');
        if (!grid || !row) return false;
        const f = grid.getBoundingClientRect();
        const r = row.getBoundingClientRect();
        return r.top >= f.top - 1 && r.bottom <= f.bottom + 1;
      },
      null,
      { timeout: 5000 }
    )
    .then(() => true)
    .catch(() => false);
  check(`a pin pick scrolls ${lastRowName} into the rail`, broughtIn);
  check(
    'the picked row is the one the rail was moved to',
    (await page.$eval('.day-row.selected .day-name', (n) => n.textContent.trim())) === lastRowName
  );
  const railScroll = await page.$eval('.day-grid', (el) => el.scrollTop);
  check('the rail moved itself, not the page', railScroll > 0, `scrollTop ${railScroll}`);
  check('the page itself did not scroll', (await page.evaluate(() => window.scrollY)) === 0);
  await page.screenshot({ path: 'map-rail-scrolled.png' });
  // A pin for a venue already on the rail leaves the list where the reader put
  // it — the scroll is a rescue, not a jump on every pick.
  await page.click('.track-close');
  await page.$eval('.day-grid', (el) => el.scrollTo(0, 0));
  await page.waitForTimeout(150);
  await clickPin(rowNames[0]);
  await page.waitForSelector('.day-row.selected', { timeout: 5000 }).catch(() => {});
  await page.waitForTimeout(600);
  check(
    'a pin for a row already on the rail leaves the list alone',
    (await page.$eval('.day-grid', (el) => el.scrollTop)) === 0 && setRowState.firstOn
  );
  await page.click('.track-close');
  await page.waitForTimeout(300);

  // Every venue in the motocross network is carried by the paid pass, so there
  // is no not-covered venue to open read-only: the free tier's read-only panel
  // is asserted in its own section below.

  // ---- The inspector is the map's pick ------------------------------------
  // The badge is the map's other control: a click opens that venue's inspector
  // over the canvas, lifts its own pin out of the rest and leaves the list
  // standing; hovering the pin merely names the venue. No popup on a click.
  const pinHit = await clickPin(picked);
  await page.waitForSelector('.track-panel', { timeout: 5000 }).catch(() => {});
  check('clicking a pin opens its inspector', pinHit && (await page.$$eval('.track-panel', (n) => n.length)) === 1);
  check('the panel names the track', (await page.textContent('.track-panel-body h2')).trim() === picked);
  // The day facts row is gone from the fact list: the count rides the day meter
  // beneath it, whose title reads "<left> of <total> days left".
  check(
    'the panel numbers the days left',
    /of \d+ days left/.test(
      await page.$$eval('.track-panel .day-meter', (els) => els.map((e) => e.getAttribute('title') || '').join('|'))
    )
  );
  check('the day list stays beside the panel on a pin pick', (await page.$$eval('.day-row', (n) => n.length)) === NET);
  const pinLit = await page.$$eval('.map-pin-wrap', (els) => els.filter((e) => !e.classList.contains('dim')).length);
  const pinDim = await page.$$eval('.map-pin-wrap.dim', (n) => n.length);
  check('a pin pick dims the other tracks', pinLit === 1 && pinDim === 24, `${pinLit} lit / ${pinDim} dimmed`);
  check(
    'the lit pin is the picked track',
    (await page.$$eval('.map-pin-wrap', (els) => els.filter((e) => !e.classList.contains('dim')).map((e) => e.querySelector('.map-pin-dot')?.getAttribute('data-name') || '')[0])) === picked
  );
  check('a pin click opens no popup', (await page.$$eval('.leaflet-popup', (n) => n.length)) === 0);
  check(
    'the panel offers no way to book a day',
    (await page.$$eval('.track-panel a[href^="/tracks/reservations"]', (n) => n.length)) === 0
  );
  await page.waitForSelector('.track-links-btn', { timeout: 5000 }).catch(() => {});
  // The socials are glyph buttons now: their name rides on the anchor's own
  // label, so read textContent where there is one and aria-label where not.
  const linkLabels = await page.$$eval('.track-links-btn', (els) =>
    els.map((e) => (e.textContent.trim() || e.getAttribute('aria-label') || '').trim())
  );
  check(
    `${picked} links out to its own site and feeds`,
    linkLabels.includes('Website') && linkLabels.includes('Instagram') && linkLabels.includes('Facebook'),
    linkLabels.join('|')
  );
  check(
    'the inspector keeps one text button and squares off the socials',
    (await page.$$eval('.track-panel-links .track-links-btn:not(.track-links-icon)', (n) => n.length)) === 1 &&
      (await page.$$eval('.track-panel-links .track-links-icon', (n) => n.length)) === 3
  );
  check(
    'and every social glyph rides inside its own 1px frame',
    (await page.$$eval('.track-panel-links .track-links-icon', (els) =>
      els.every((e) => e.querySelector('svg') !== null && Math.round(e.getBoundingClientRect().width) === 31)
    ))
  );
  // The name in the head is the second door into the venue's profile: it must
  // point where the Track profile button points.
  check(
    'the venue name in the head links to its own profile',
    (await page.$eval('.track-panel-head h2 a.track-name-link', (a) => a.getAttribute('href'))) ===
      (await page.$eval('.track-panel-links a.track-links-btn:not(.track-links-icon)', (a) =>
        a.getAttribute('href')
      ))
  );
  await page.screenshot({ path: 'map-track-panel.png' });

  // Back on the network, pick the same venue again for the hover and bounds
  // checks below.
  await page.goto(`${BASE}/tracks`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.day-row', { timeout: 15000 });
  await showAll(page);
  await clickPin(picked);
  await page.waitForSelector('.track-panel', { timeout: 5000 }).catch(() => {});

  // Hovering a pin names the venue: the label pills are gone from the map, so
  // the tooltip is the one place a dot says which track it is.
  const hovered = await page.$$eval('.map-pin-wrap', (els, want) => {
    const el = els.find((e) => e.querySelector('.map-pin-dot')?.getAttribute('data-name') === want);
    if (el) el.dispatchEvent(new MouseEvent('mouseover', { bubbles: true }));
    return !!el;
  }, picked);
  await page.waitForTimeout(600);
  const tips = await page.$$eval('.leaflet-tooltip.map-tip', (n) => n.map((e) => e.textContent.trim()));
  check('hovering a pin names the venue in a tooltip', hovered && tips.includes(picked), tips.join(' | ') || 'no tooltip');
  check('a pin is a bare dot, with no label to read', (await page.$$eval('.map-pin-wrap .map-pin-dot', (n) => n.length)) === NET);

  // Back to the list for the bounds checks below.
  await page.click('.track-close').catch(() => {});
  await page.waitForTimeout(400);

  // ---- The map is pinned to the US ---------------------------------------
  // Zoom out as far as the control allows, then try to drag the country off
  // screen. maxBounds + minZoom must keep the view over the States.
  // The map opens at the country floor, so the control is already disabled —
  // a click on a disabled control blocks until Playwright's actionability
  // timeout, ten times over. Bound each press and stop once the floor is hit.
  for (let i = 0; i < 10; i++) {
    const atFloor = await page.$eval('.leaflet-control-zoom-out', (e) =>
      e.classList.contains('leaflet-disabled')
    ).catch(() => true);
    if (atFloor) break;
    await page.click('.leaflet-control-zoom-out', { timeout: 2000 }).catch(() => {});
    await page.waitForTimeout(250);
  }
  await page.waitForTimeout(2000);
  const zoomedOut = await tileFootprint(page);
  check('zoom-out stops at the country scale floor', zoomedOut.zoom >= 4, `z ${zoomedOut.zoom}`);

  const box = await page.$eval('.leaflet-container', (e) => {
    const r = e.getBoundingClientRect();
    return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
  });
  for (let i = 0; i < 3; i++) {
    await page.mouse.move(box.x, box.y);
    await page.mouse.down();
    await page.mouse.move(box.x + 1400, box.y + 1100, { steps: 20 });
    await page.mouse.up();
    await page.waitForTimeout(500);
  }
  await page.waitForTimeout(1500);
  const dragged = await tileFootprint(page);
  check(
    'dragging cannot pull the map off the US',
    dragged.lat > 20 && dragged.lat < 55 && dragged.lng > -135 && dragged.lng < -55,
    `centre ${dragged.lat.toFixed(2)}, ${dragged.lng.toFixed(2)}`
  );
  await page.screenshot({ path: 'map-us-bounds.png' });

  // ---- Track exhausted: the rail greys it, the map does not --------------
  const sam = await openMap(browser, 'sam@example.com');
  await showAll(sam);
  expect('out-of-days rider: every pin the accent, none dashed', (await pinCounts(sam)).counts, { mx: NET, dashed: 0 });
  // The exhausted track is the day row marked spent — no included days and no
  // discounted days left — and it drops to the bottom of the list.
  const spent = await sam.$$eval('.day-row.spent', (rows) => rows.map((r) => r.textContent.trim()));
  check('the greyed track is the exhausted one', spent.length === 1 && /221 MX/.test(spent[0]), spent.join(' | '));

  // ---- No active pass: the network reads like the public one --------------
  // A lapsed pass has no season left to read terms from, so the rail lists every
  // venue without terms rather than dimming the whole network grey. (The venue's
  // own status *pill* came off the gated rail in `b6d80f9`, so a row here ends at
  // the name, the location and the gate *light* — the map's dashes carry what is
  // shut.)
  const morgan = await openMap(browser, 'morgan@example.com');
  check('expired pass shows the notice', /No active pass/.test(await morgan.textContent('.banner')));
  check(
    'the expired pass lists every venue in the network',
    (await morgan.$$eval('.day-row', (r) => r.length)) === NET
  );
  check(
    'no venue is greyed out for a lapsed pass',
    (await morgan.$$eval('.day-row.spent, .day-row.not-covered', (r) => r.length)) === 0
  );
  check(
    'a lapsed pass gets no day ledger',
    (await morgan.$$eval('.day-meter, .seg-bar', (e) => e.length)) === 0
  );
  expect('expired pass: every pin the accent, none dashed', (await pinCounts(morgan)).counts, { mx: NET, dashed: 0 });
  check(
    'a lapsed pass is offered no Included slice',
    (await slicePills(morgan)).every((p) => !p.startsWith('Included:'))
  );

  // ---- Free tier: one accent colour, no legend over the canvas ----
  // A free account gets the same venue-type map every rider does; the rail has no
  // days to count, so its rows end at the venue's name and location and the day
  // meters stay out of it entirely.
  const quinn = await openMap(browser, 'quinn@example.com');
  check(
    'the free pass carries no legend over the canvas either',
    (await countOf(quinn, '.map-pane-legend')) === 0
  );
  check('the free pass says what it is', /free pass/i.test(await quinn.textContent('.banner')));
  // No days to count, so the rail just lists the network — the day meters stay
  // out of it, and the venue's own gate light stays in, because a venue's status
  // is public however little the pass carries.
  const quinnRows = await quinn.$$eval('.day-row', (r) => r.length);
  check('the free pass lists every venue in the network', quinnRows === NET, `${quinnRows} rows`);
  check(
    'a free rider reads the network’s gate lights',
    (await quinn.$$eval('.day-row .day-light', (l) => l.length)) === NET
  );
  check(
    'a free rider gets no day ledger',
    (await quinn.$$eval('.day-meter, .seg-bar', (e) => e.length)) === 0
  );
  // The rail carries no follow control: following a venue happens in the
  // inspector its row opens (and on the venue's own profile), so a row stays a
  // name, a location and the pass's own read.
  check(
    'a rail row carries no follow control',
    (await quinn.$$eval('.day-row .follow-toggle, .day-body button', (n) => n.length)) === 0
  );
  // A follower's rail can be narrowed to what they follow — quinn follows three.
  await setSlice(quinn, 'Following');
  const quinnFollowRows = await quinn.$$eval('.day-row .day-name', (n) => n.map((e) => e.textContent.trim()));
  check('Following keeps the followed venues', quinnFollowRows.length === 3, quinnFollowRows.join(' | '));
  check(
    'the followed venues are the seeded ones',
    /221 MX/.test(quinnFollowRows.join(' ')) && /Top Gun MX/.test(quinnFollowRows.join(' ')),
    quinnFollowRows.join(' | ')
  );
  await setSlice(quinn, 'All');
  check('All puts the network back', (await quinn.$$eval('.day-row', (n) => n.length)) === NET);
  check(
    'the free pass is offered no Included slice',
    (await slicePills(quinn)).every((p) => !p.startsWith('Included:'))
  );
  // A free rider picks a venue the same way: the rail opens it read-only.
  const quinnPin = await quinn.$$eval('.map-pin-wrap', (els) => {
    const el = els[0];
    if (el) el.click();
    return !!el;
  });
  await quinn.waitForSelector('.track-panel', { timeout: 5000 }).catch(() => {});
  check(
    'a free rider opens a venue panel from the map',
    quinnPin && (await quinn.$$eval('.track-panel', (n) => n.length)) === 1
  );
  check(
    'a free rider is offered no way to book a day',
    (await quinn.$$eval('.track-panel a[href^="/tracks/reservations"]', (n) => n.length)) === 0
  );
  // The free tier carries no contracted terms, so the panel withholds them
  // rather than printing zeroes: no day ledger, no discounted day, no member
  // rate. (It used to name the tier in a note of its own; that line is gone, so
  // the check pins the withholding itself.)
  check(
    'the free panel withholds the pass’s terms',
    (await quinn.$$eval('.track-panel .track-panel-days, .track-panel .day-meter', (n) => n.length)) === 0 &&
      !/Days Remaining|Discounted day|Extra days/.test(await quinn.textContent('.track-panel'))
  );
  await quinn.click('.track-close');
  await quinn.waitForTimeout(300);
  await quinn.screenshot({ path: 'map-free-tier.png' });

  // ---- A visitor: the network page is public, following is not -------------
  // /tracks serves everyone; a signed-out visitor reads the same network, with
  // no terms to read on a row — the venue's gate light stays on it — and the
  // account-only parts (follow controls, the Following filter) stay off the page.
  const guest = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  guest.on('pageerror', (e) => errors.push(String(e.message)));
  await guest.goto(`${BASE}/tracks`, { waitUntil: 'networkidle' });
  await guest.waitForSelector('.leaflet-container', { timeout: 15000 });
  await guest.waitForSelector('.day-row', { timeout: 15000 });
  check('a visitor lands on the network page', guest.url().endsWith('/tracks'), guest.url());
  check('a visitor sees every venue', (await guest.$$eval('.day-row', (n) => n.length)) === NET);
  check('a visitor gets the map too', (await guest.$$eval('.map-pin-wrap', (n) => n.length)) === NET);
  check(
    'a visitor reads a bare venue row, not terms',
    (await guest.$$eval('.day-row .status-pill, .day-row .day-meter', (n) => n.length)) === 0
  );
  check(
    'a visitor is offered no follow control',
    (await guest.$$eval('.day-row .follow-toggle', (n) => n.length)) === 0
  );
  // One slice is no choice: with nothing to narrow to, the rail carries no
  // filter icon at all — and so no pills behind one.
  check(
    'a visitor’s rail head names the network and offers no filter',
    (await guest.textContent('.rail-pass-name')) === 'The network' &&
      (await guest.$$eval('.rail-filter, .day-filter', (n) => n.length)) === 0
  );
  // The search field is public, and it lives in the app header: a visitor
  // narrows the network the same way a signed-in rider does — off the same
  // folded icon, which opens on a click.
  check(
    'a visitor is offered the search icon',
    (await guest.$$eval('.header-search .hs-trigger', (n) => n.length)) === 1
  );
  await unfoldSearch(guest);
  await guest.fill('.header-search input', 'washougal');
  await guest.waitForTimeout(300);
  check(
    'a visitor can search the network',
    (await guest.$$eval('.day-row', (n) => n.length)) === 1
  );
  await guest.press('.header-search input', 'Escape');
  await guest.waitForTimeout(300);
  check(
    'a visitor is offered no way to book a day',
    (await guest.$$eval('a[href^="/tracks/reservations"]', (n) => n.length)) === 0
  );
  // The signed-out front door is the shell's quiet action now, not a banner:
  // a visitor reads the network and is offered sign-in from the header.
  check(
    'the visitor is offered sign-in',
    (await guest.$('.header-signin')) !== null &&
      /Sign in/.test(await guest.textContent('.header-signin'))
  );
  // The old public directory is gone: /tracks is the network page now.
  check('there is no contract table on the network page', (await guest.$$eval('table', (n) => n.length)) === 0);
  await guest.screenshot({ path: 'tracks-visitor.png' });

  // ---- The console roles have their own tables ----------------------------
  // The track search is the rider's and the visitor's: the operator and admin
  // consoles work off their own lists, so the field stays out of their header —
  // even on the network page, where signing in lands them.
  const ops = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  ops.on('pageerror', (e) => errors.push(String(e.message)));
  await login(ops, 'ops@221mx.example.com');
  await ops.waitForTimeout(800);
  check(
    'the operator header carries no track search',
    (await ops.$$eval('.header-search', (n) => n.length)) === 0
  );
  // An operator's home is the dashboard; the network is one nav click away and
  // stays readable to them, with the field still out of their header.
  await ops.goto(`${BASE}/tracks`, { waitUntil: 'networkidle' });
  await ops.waitForSelector('.day-row', { timeout: 15000 });
  check('the operator still reaches the network', ops.url().includes('/tracks'), ops.url());
  check(
    'the operator header carries no track search on the network page',
    (await ops.$$eval('.header-search', (n) => n.length)) === 0
  );
  const admin = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  admin.on('pageerror', (e) => errors.push(String(e.message)));
  await login(admin, 'admin@motopass.example.com');
  await admin.waitForTimeout(800);
  check(
    'the admin header carries no track search',
    (await admin.$$eval('.header-search', (n) => n.length)) === 0
  );

  // ---- The theme toggle, in the footer's legal row -----------------------
  // One control flips the whole app between the dark ground (the default) and
  // the light one. Dark is the absence of `data-theme`, the choice is stored,
  // and the map stops inverting OSM's tiles on the light ground.
  check(
    'the footer carries the one theme toggle',
    (await page.$$eval('.theme-toggle', (n) => n.length)) === 1 &&
      (await page.$$eval('footer .theme-toggle', (n) => n.length)) === 1 &&
      (await page.$$eval('header .theme-toggle', (n) => n.length)) === 0
  );
  check(
    'the app opens on the dark ground',
    (await page.evaluate(() => document.documentElement.dataset.theme || '')) === ''
  );
  await page.click('.theme-toggle');
  await page.waitForTimeout(250);
  check(
    'the toggle flips the ground to light and stores the choice',
    (await page.evaluate(() => document.documentElement.dataset.theme)) === 'light' &&
      (await page.evaluate(() => localStorage.getItem('motopass.theme'))) === 'light'
  );
  check(
    'the light ground paints the light palette, not just the attribute',
    (await page.evaluate(() => getComputedStyle(document.body).backgroundColor)) === 'rgb(245, 246, 248)'
  );
  check(
    'the map takes OSM tiles as they come on the light ground',
    (await page.$eval('.leaflet-tile-pane', (e) => getComputedStyle(e).filter)) === 'none'
  );
  check('the toggle leaves the header search in place', (await page.$$eval('.header-search', (n) => n.length)) === 1);
  // The stored choice is applied by the script in index.html before React
  // mounts, so a light page never flashes the dark palette on a reload.
  await page.reload({ waitUntil: 'domcontentloaded' });
  check(
    'a stored light theme survives a reload, applied before first paint',
    (await page.evaluate(() => document.documentElement.dataset.theme)) === 'light'
  );
  await page.click('.theme-toggle');
  await page.waitForTimeout(250);
  check(
    'the toggle flips back to dark and clears the stored choice',
    (await page.evaluate(() => document.documentElement.dataset.theme || '')) === '' &&
      (await page.evaluate(() => localStorage.getItem('motopass.theme'))) === null
  );

  // ---- The rider's own position pin ---------------------------------------
  // Landing on /tracks asks the browser for a position by default, and the fix
  // lands as the map's one pin that is not a venue: its own class, its own
  // neutral fill, above the venue dots. Both answers the browser can give are
  // driven here — a context granted a position, and one with nothing to give.
  const geoErrors = [];
  const geoCtx = await browser.newContext({
    viewport: { width: 1280, height: 900 },
    permissions: ['geolocation'],
    geolocation: { latitude: 35.85, longitude: -81.9 },
  });
  const geo = await geoCtx.newPage();
  geo.on('pageerror', (e) => geoErrors.push(String(e.message)));
  const mePoint = (p) =>
    p.$eval('.map-me-wrap .map-me-dot', (el) => {
      const r = el.getBoundingClientRect();
      return { x: Math.round(r.x), y: Math.round(r.y) };
    });
  await geo.goto(`${BASE}/tracks`, { waitUntil: 'networkidle' });
  await geo.waitForSelector('.leaflet-container', { timeout: 15000 });
  let firstFix = null;
  try {
    await geo.waitForSelector('.map-me-wrap', { state: 'attached', timeout: 20000 });
    firstFix = await mePoint(geo);
  } catch {
    /* reported below */
  }
  check('landing asks the browser for a position, and pins the answer', Boolean(firstFix));
  check(
    'the position pin is not a venue pin',
    (await geo.$$eval('.map-pin-wrap', (n) => n.length)) === NET &&
      (await geo.$$eval('.map-me-wrap', (n) => n.length)) === 1 &&
      (await geo.$eval('.map-me-dot', (e) => e.getAttribute('data-name'))) === 'Your location'
  );
  check(
    'the position pin wears no venue colour',
    (await geo.$eval('.map-me-dot', (e) => getComputedStyle(e).backgroundColor)) === 'rgb(232, 234, 237)'
  );
  check(
    'the map carries the one position control, reading as on',
    (await geo.$$eval('.map-locate', (n) => n.length)) === 1 &&
      (await geo.textContent('.map-locate')).trim() === 'My location' &&
      (await geo.getAttribute('.map-locate', 'aria-pressed')) === 'true'
  );
  await geo.click('.map-locate');
  await geo.waitForTimeout(300);
  check(
    'the control puts the pin away',
    (await geo.$$eval('.map-me-wrap', (n) => n.length)) === 0 &&
      (await geo.getAttribute('.map-locate', 'aria-pressed')) === 'false'
  );
  await geo.click('.map-locate');
  await geo.waitForTimeout(400);
  check(
    'and brings it back without a second ask',
    (await geo.$$eval('.map-me-wrap', (n) => n.length)) === 1 &&
      (await geo.getAttribute('.map-locate', 'aria-pressed')) === 'true'
  );
  await geo.screenshot({ path: 'tracks-position-pin.png' });

  // The pin is placed from what the browser reports, not from the network: the
  // same page loaded with a Colorado fix moves it across the map.
  const coCtx = await browser.newContext({
    viewport: { width: 1280, height: 900 },
    permissions: ['geolocation'],
    geolocation: { latitude: 39.5, longitude: -98.35 },
  });
  const co = await coCtx.newPage();
  co.on('pageerror', (e) => geoErrors.push(String(e.message)));
  await co.goto(`${BASE}/tracks`, { waitUntil: 'networkidle' });
  await co.waitForSelector('.map-me-wrap', { state: 'attached', timeout: 20000 }).catch(() => {});
  const secondFix = await mePoint(co).catch(() => null);
  check(
    'the pin moves with the position the browser reports',
    Boolean(firstFix && secondFix) && Math.abs(firstFix.x - secondFix.x) > 100,
    `${JSON.stringify(firstFix)} → ${JSON.stringify(secondFix)}`
  );

  // Nothing to give: the control reports the refusal rather than a silent pin.
  const offCtx = await browser.newContext({ viewport: { width: 1280, height: 900 } });
  const off = await offCtx.newPage();
  off.on('pageerror', (e) => geoErrors.push(String(e.message)));
  await off.goto(`${BASE}/tracks`, { waitUntil: 'networkidle' });
  await off.waitForTimeout(2500);
  check(
    'a refused position reads on the control, with no pin',
    (await off.textContent('.map-locate')).trim() === 'Location blocked' &&
      (await off.getAttribute('.map-locate', 'aria-pressed')) === 'false' &&
      (await off.getAttribute('.map-locate', 'disabled')) === '' &&
      (await off.$$eval('.map-me-wrap', (n) => n.length)) === 0
  );
  // The tailnet link is served over plain http, and a browser only shares a
  // position on a secure page: that origin gets the honest label and no ask.
  const plainCtx = await browser.newContext({
    viewport: { width: 1280, height: 900 },
    permissions: ['geolocation'],
    geolocation: { latitude: 35.85, longitude: -81.9 },
  });
  const plain = await plainCtx.newPage();
  plain.on('pageerror', (e) => geoErrors.push(String(e.message)));
  await plain.addInitScript(() => {
    Object.defineProperty(window, 'isSecureContext', { configurable: true, get: () => false });
  });
  await plain.goto(`${BASE}/tracks`, { waitUntil: 'networkidle' });
  await plain.waitForSelector('.leaflet-container', { timeout: 15000 });
  await plain.waitForTimeout(2000);
  check(
    'an insecure origin is told why it gets no pin',
    (await plain.textContent('.map-locate')).trim() === 'Needs HTTPS' &&
      (await plain.getAttribute('.map-locate', 'aria-pressed')) === 'false' &&
      (await plain.$$eval('.map-me-wrap', (n) => n.length)) === 0
  );
  check('no JS errors while the map asks for a position', geoErrors.length === 0, geoErrors.join(' | '));
  await plainCtx.close();
  await geoCtx.close();
  await coCtx.close();
  await offCtx.close();

  check('no JS errors on the pass page', errors.length === 0, errors.join(' | '));

  await browser.close();
  console.log(`\n${fails === 0 ? 'ALL MAP CHECKS PASSED' : `${fails} MAP CHECK(S) FAILED`}`);
  process.exit(fails === 0 ? 0 : 1);
}

main().catch((e) => {
  console.error('harness error:', e);
  process.exit(1);
});

/* Headless verification of the pricing page (/pricing).
 *
 * The page carries one real interaction (buy), a billing toggle that switches
 * the paid card's headline between the annual pass and its monthly
 * alternative, and an audience toggle (hidden for now) that swaps the whole
 * body. The things worth asserting are structural: the two rider cards, the
 * billing toggle and the figures it moves, the compare table, the partner
 * sheet in the tracks view, the live contract figures quoted in that sheet,
 * and nothing throwing.
 *
 *   cd web && npm run verify:pricing     (dev server on :5180)
 *
 * Uses playwright-core with an explicit browser path so it works with the
 * browsers already in ~/.cache/ms-playwright and downloads nothing.
 */
const fs = require('fs');
const path = require('path');
const os = require('os');
const { chromium } = require('playwright-core');

const BASE = process.env.PRICING_BASE || 'http://localhost:5180';
const API = process.env.PRICING_API || 'http://localhost:4010';

function findBrowser() {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  if (!fs.existsSync(root)) return null;
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium_headless_shell-')) continue;
    const p = path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell');
    if (fs.existsSync(p)) return p;
    const alt = path.join(root, dir, 'chrome-linux', 'headless_shell');
    if (fs.existsSync(alt)) return alt;
  }
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium-')) continue;
    const p = path.join(root, dir, 'chrome-linux64', 'chrome');
    if (fs.existsSync(p)) return p;
  }
  return null;
}

let fails = 0;
function check(label, ok, detail = '') {
  if (!ok) fails++;
  console.log(`${ok ? 'OK  ' : 'FAIL'}  ${label}${detail ? ` — ${detail}` : ''}`);
}

/** How many venues the public network holds, read from the API at run time.
 *  The partner sheet quotes the live figure, so the suite reads the same one
 *  rather than writing the size down. */
async function networkCount() {
  const r = await fetch(`${API}/api/tracks?terms=public`);
  const d = await r.json();
  return (d?.data?.tracks ?? []).length;
}

/** Sign in as a seeded demo account — the demo password is dialed123. */
async function login(page, email) {
  await page.context().clearCookies();
  await page.goto(`${BASE}/login`, { waitUntil: 'networkidle' });
  await page.waitForSelector('form #email');
  await page.fill('#email', email);
  await page.fill('#password', 'dialed123');
  await Promise.all([
    page.waitForURL((u) => !u.pathname.startsWith('/login'), { timeout: 20000 }),
    page.click('form button.primary'),
  ]);
}

async function main() {
  const exe = findBrowser();
  if (!exe) {
    console.error('No Playwright Chromium found in ~/.cache/ms-playwright.');
    process.exit(1);
  }
  const browser = await chromium.launch({ executablePath: exe });
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push(String(e.message)));

  // The partner sheet quotes "N of NET tracks" — the NET half is read here.
  const NET = await networkCount();

  await page.goto(`${BASE}/pricing`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.tier-card', { timeout: 15000 });

  // ---- Billing toggle ----------------------------------------------------
  // One switch above the rider cards moves the paid card's headline between
  // the annual pass and its monthly alternative. Annual is the default — it is
  // the saving — and the switch is the page's one interaction besides buy.
  // The form is the reference layout's: a label either side of a track, the
  // thumb resting on the term in force. The labels are the real controls.
  const billing = await page.$$eval('.billing-switch .bs-opt', (b) =>
    b.map((x) => ({
      label: x.querySelector('.pill-label')?.textContent.trim() ?? x.textContent.trim(),
      save: x.querySelector('.pill-save')?.textContent.trim() ?? null,
      pressed: x.getAttribute('aria-pressed'),
    }))
  );
  check('the billing switch offers Monthly and Annual', billing.map((t) => t.label).join(',') === 'Monthly,Annual', billing.map((t) => t.label).join(','));
  check('annual is on by default', billing[0].pressed === 'false' && billing[1].pressed === 'true', billing.map((t) => t.pressed).join(','));
  // The annual side names the saving, counted off the live contracts — the
  // switch's own read, not a hard-coded figure.
  check('the annual label names its saving', /^Save \d+%$/.test(billing[1].save ?? ''), String(billing[1].save));
  check('only the annual side carries a saving', billing[0].save === null, String(billing[0].save));
  // The switch's track: rounded, with a thumb resting on the annual end until
  // the billing term moves.
  const trackStyle = await page.$eval('.billing-switch .bs-track', (el) => getComputedStyle(el).borderRadius);
  check('the switch draws a rounded track', parseFloat(trackStyle) >= 100, trackStyle);
  const thumbAtRest = await page.$eval('.billing-switch .bs-track', (el) => el.dataset.side);
  check('the thumb rests on the annual side by default', thumbAtRest === 'annual', String(thumbAtRest));
  // The track is the switch, not a picture of one: clicking it moves the term.
  const trackRole = await page.$eval('.billing-switch .bs-track', (el) => `${el.tagName}:${el.getAttribute('role')}:${el.getAttribute('aria-checked')}`);
  check('the track is a real switch', trackRole === 'BUTTON:switch:true', trackRole);
  await page.click('.billing-switch .bs-thumb');
  await page.waitForTimeout(250);
  const afterTrack = await page.$eval('.billing-switch .bs-track', (el) => el.dataset.side);
  const afterTrackPaid = await page.$eval('.tier-card.popular .amount', (el) => el.textContent.trim());
  check('clicking the switch moves the billing term', afterTrack === 'monthly' && afterTrackPaid === '$50', `${afterTrack} / ${afterTrackPaid}`);
  await page.click('.billing-switch .bs-thumb');
  await page.waitForTimeout(250);
  const backTrack = await page.$eval('.billing-switch .bs-track', (el) => el.dataset.side);
  check('clicking the switch again returns to annual', backTrack === 'annual', String(backTrack));
  // The move is a slide, not a jump: the thumb's box travels the track and the
  // property is transitioned, so the eye can follow the term change.
  const thumbBox = () =>
    page.$eval('.billing-switch .bs-thumb', (el) => {
      const r = el.getBoundingClientRect();
      return { x: Math.round(r.x), y: Math.round(r.y), prop: getComputedStyle(el).transitionProperty };
    });
  const atAnnual = await thumbBox();
  await page.click('.billing-switch .bs-thumb');
  await page.waitForTimeout(400);
  const atMonthly = await thumbBox();
  check(
    'the thumb slides across the track between the terms',
    atAnnual.x - atMonthly.x >= 20 && atMonthly.y === atAnnual.y,
    `annual x=${atAnnual.x} -> monthly x=${atMonthly.x}, y ${atAnnual.y}/${atMonthly.y}`
  );
  check('the slide is a transition, not a jump', atAnnual.prop.includes('transform'), atAnnual.prop);
  await page.click('.billing-switch .bs-thumb');
  await page.waitForTimeout(400);

  // The thumb is the raised grey marker, so its label reads in body ink rather
  // than the accent — and hover never moves the term in force off that ink.
  const thumbFill = await page.$eval('.billing-switch .bs-thumb', (el) => getComputedStyle(el).backgroundColor);
  check('the switch thumb wears the grey lift', thumbFill === 'rgb(75, 81, 90)', thumbFill);
  // The label ink is transitioned with the thumb, so the read has to wait for
  // the colour to settle before it is compared.
  await page.hover('.billing-switch .bs-opt:has-text("Annual")');
  await page.waitForTimeout(400);
  const selectedHover = await page.$eval('.billing-switch .bs-opt[aria-pressed="true"]', (el) => getComputedStyle(el).color);
  check('hovering the term in force keeps its body ink', selectedHover === 'rgb(232, 234, 237)', selectedHover);
  await page.hover('.billing-switch .bs-opt:has-text("Monthly")');
  await page.waitForTimeout(400);
  const unselectedHover = await page.$eval('.billing-switch .bs-opt[aria-pressed="false"]', (el) => getComputedStyle(el).color);
  check('hovering the quiet label lifts it to body ink', unselectedHover === 'rgb(232, 234, 237)', unselectedHover);
  await page.mouse.move(10, 700);
  await page.waitForTimeout(150);

  // ---- Riders view -------------------------------------------------------
  const cards = await page.$$eval('.tier-card', (els) =>
    els.map((el) => ({
      name: el.querySelector('h2')?.textContent.trim(),
      popular: el.classList.contains('popular'),
      unit: el.querySelector('.unit')?.textContent.trim(),
      capacity: el.querySelector('.capacity')?.textContent.trim(),
      bullets: [...el.querySelectorAll('.tier-list li')].map((li) => li.textContent.trim()),
      includes: el.querySelector('.tier-includes')?.textContent.trim() || null,
      border: getComputedStyle(el).borderColor,
    }))
  );
  check('riders view shows the page title', (await page.textContent('h1')) === 'Pick your pass');
  check('two rider plans render', cards.length === 2, cards.map((c) => c.name).join(', '));
  check(
    'plan order is Free Pass, Moto Pass',
    cards.map((c) => c.name).join(',') === 'Free Pass,Moto Pass',
    cards.map((c) => c.name).join(',')
  );
  check('exactly one plan is flagged', cards.filter((c) => c.popular).length === 1);
  check('the flagged plan is Moto Pass', cards.find((c) => c.popular)?.name === 'Moto Pass');
  check('flagged plan uses the accent border', cards.find((c) => c.popular)?.border === 'rgb(255, 138, 63)', cards.find((c) => c.popular)?.border);
  check('unflagged plan keeps the neutral border', cards[0].border === 'rgb(38, 43, 52)', cards[0].border);
  check('every plan states the yearly term', cards.every((c) => c.unit === 'per year'), cards.map((c) => c.unit).join(' | '));
  check('the plans differ in day totals', new Set(cards.map((c) => c.capacity)).size === 2, cards.map((c) => c.capacity).join(' | '));
  check('the free plan is priced Free, not $0', cards[0].name === 'Free Pass' && /^Free$/.test(await page.$eval('.tier-card .amount', (e) => e.textContent.trim())));
  check(
    'the free plan carries no included days',
    /no included days/i.test(cards[0].capacity),
    cards[0].capacity
  );
  check('the free plan heads its list with its own line', cards[0].includes === 'Free plan includes:', cards[0].includes);
  check('Moto Pass folds in the free tier', cards[1].includes === 'Everything in Free +', cards[1].includes);
  check('checklist icons are drawn SVG, not glyphs', (await page.$$eval('.tier-list svg', (s) => s.length)) === cards.reduce((n, c) => n + c.bullets.length, 0));
  check('no unicode check glyphs in the page text', !/[✓✔]/.test(await page.textContent('body')));

  // ---- The billing toggle moves the paid card's figures ------------------
  // Annual is the default: the headline is the yearly price and the note names
  // the presale. Monthly shows the monthly price and what the annual saves.
  const paidCard = () =>
    page.$eval('.tier-card.popular', (el) => ({
      amount: el.querySelector('.amount')?.textContent.trim(),
      unit: el.querySelector('.unit')?.textContent.trim(),
      note: [...el.querySelectorAll('.tier-price .unit')].map((u) => u.textContent.replace(/\s+/g, ' ').trim()).join(' | '),
    }));
  const annual = await paidCard();
  check('annual shows the yearly price', annual.amount === '$400' && annual.unit === 'per year', `${annual.amount} / ${annual.unit}`);
  check(
    'annual notes the presale and the full price',
    /Presale Nov 16/.test(annual.note) && /25% off/.test(annual.note) && /Full price Dec 2/.test(annual.note),
    annual.note
  );
  await page.click('.billing-switch .bs-opt:has-text("Monthly")');
  await page.waitForTimeout(250);
  const monthly = await paidCard();
  check('monthly shows the monthly price', monthly.amount === '$50' && monthly.unit === 'per month', `${monthly.amount} / ${monthly.unit}`);
  check('monthly notes what the annual saves', /Annual saves \$200 a year/.test(monthly.note), monthly.note);
  const afterMonthly = await page.$$eval('.billing-switch .bs-opt', (b) => b.map((x) => x.getAttribute('aria-pressed')));
  check('the toggle state follows the billing period', afterMonthly[0] === 'true' && afterMonthly[1] === 'false', afterMonthly.join(','));
  const thumbMoved = await page.$eval('.billing-switch .bs-track', (el) => el.dataset.side);
  check('the thumb follows the billing period', thumbMoved === 'monthly', String(thumbMoved));
  await page.click('.billing-switch .bs-opt:has-text("Annual")');
  await page.waitForTimeout(250);
  const backAnnual = await paidCard();
  check('switching back restores the yearly price', backAnnual.amount === '$400' && backAnnual.unit === 'per year', `${backAnnual.amount} / ${backAnnual.unit}`);

  // ---- Compare table -----------------------------------------------------
  // One column per plan, one row per capability that either differs or is
  // shared — the marks must agree with the cards above it.
  const cmpHead = await page.$$eval('.compare-table thead th', (t) => t.map((x) => x.textContent.trim()));
  check(
    'compare table names one column per plan',
    cmpHead.join(',') === 'Capability,Free Pass,Moto Pass',
    cmpHead.join(',')
  );
  const cmpRows = await page.$$eval('.compare-table tbody tr', (rows) =>
    rows.map((r) => ({
      label: r.querySelector('th')?.textContent.trim(),
      cells: [...r.querySelectorAll('td')].map((c) => ({
        text: c.textContent.trim(),
        mark: !!c.querySelector('svg'),
      })),
    }))
  );
  const cmpRow = (label) => cmpRows.find((r) => r.label === label);
  const cmpText = (label) => (cmpRow(label)?.cells ?? []).map((c) => c.text).join(',');
  const cmpMarks = (label) => (cmpRow(label)?.cells ?? []).map((c) => c.mark).join(',');
  check('compare table lists eight capabilities', cmpRows.length === 8, cmpRows.map((r) => r.label).join(' | '));
  check(
    'compare table carries the differing and the shared rows',
    ['Price per year', 'Included days at every track', 'Live venue status and hours', 'Follow the tracks you ride'].every(
      (l) => cmpRows.some((r) => r.label === l)
    ),
    cmpRows.map((r) => r.label).join(' | ')
  );
  check('every row reads across both plans', cmpRows.every((r) => r.cells.length === 2));
  check('the free plan reads Free, not $0', cmpText('Price per year').startsWith('Free'), cmpText('Price per year'));
  check(
    'day totals match the cards',
    cmpText('Rideable days across the network') ===
      cards.map((c, i) => (i === 0 ? '0' : (c.capacity.match(/^\d+/) || [''])[0])).join(','),
    cmpText('Rideable days across the network')
  );
  check('the free plan carries no contract days', cmpMarks('Included days at every track') === 'false,true', cmpMarks('Included days at every track'));
  check('member extra-day pricing excludes the free plan', cmpMarks('Member price on extra days') === 'false,true', cmpMarks('Member price on extra days'));
  check('advance reservations exclude the free plan', cmpMarks('Advance reservations where required') === 'false,true', cmpMarks('Advance reservations where required'));
  check('neither plan offers extra days', cmpText('Extra days at every track') === '—,—', cmpText('Extra days at every track'));
  check('the shared capabilities are marked for every plan', cmpMarks('Live venue status and hours') === 'true,true' && cmpMarks('Follow the tracks you ride') === 'true,true', `${cmpMarks('Live venue status and hours')} / ${cmpMarks('Follow the tracks you ride')}`);
  check('marks are drawn, not glyphs', !/[✓✔]/.test(await page.textContent('.compare-table')));

  // What every plan carries reads first: the shared rows sit above the deltas.
  const shared = cmpRows.filter((r) => r.cells.every((c) => c.mark));
  check(
    'the rows every plan marks lead the table',
    shared.length > 0 && cmpRows.findIndex((r) => !r.cells.every((c) => c.mark)) === shared.length,
    cmpRows.map((r) => (r.cells.every((c) => c.mark) ? `${r.label}:all` : r.label)).join(' | ')
  );

  await page.screenshot({ path: 'pricing-verification.png', fullPage: true });

  // ---- Tracks view -------------------------------------------------------
  // The Riders / Tracks pill-toggle is temporarily hidden (see
  // src/lib/featureFlags.ts), so the partner sheet is reached by URL.
  await page.goto(`${BASE}/pricing?for=tracks`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.track-sheet', { timeout: 10000 });
  check('tracks view swaps the title', (await page.textContent('h1')) === 'For partner tracks');
  check('tracks view drops the plan columns', (await page.$$eval('.tier-card', (e) => e.length)) === 0);
  check('tracks view shows no tier prices', (await page.$$eval('.amount', (e) => e.length)) === 0);

  const sections = await page.$$eval('.track-sheet h2', (h) => h.map((x) => x.textContent.trim()));
  check('sheet has the three labelled sections', sections.join(' | ') === 'What you control | What you get | What the station checks', sections.join(' | '));

  const specLists = await page.$$eval('.sheet-cols .spec-list', (lists) =>
    lists.map((l) =>
      [...l.querySelectorAll('div')].map((r) => ({
        term: r.querySelector('dt').textContent.trim(),
        def: r.querySelector('dd').textContent.trim(),
      }))
    )
  );
  const termRows = specLists[0] ?? [];
  const givesRows = specLists[1] ?? [];
  const givesDefs = givesRows.map((r) => r.def);
  check('five contract levers listed', termRows.length === 5, termRows.map((r) => r.term).join(' | '));
  check('every lever is labelled', termRows.every((r) => r.term.length > 2));
  check('three things a track gets', givesDefs.length === 3, String(givesDefs.length));

  const steps = await page.$$eval('.step-list li', (li) => li.map((x) => x.textContent.trim()));
  check('scan order lists all eight checks', steps.length === 8, steps.join(' | '));
  const markers = await page.$$eval('.step-list .n', (li) => li.map((x) => x.textContent.trim()));
  check('scan order is numbered', markers.join(',') === '1,2,3,4,5,6,7,8', markers.join(','));

  // Terse means fragments, not sentences — guard the length of every string.
  const words = (s) => s.trim().split(/\s+/).length;
  const lead = await page.textContent('.sheet-lead');
  const longestDef = Math.max(...termRows.map((r) => words(r.def)), ...givesDefs.map(words));
  const longestStep = Math.max(...steps.map(words));
  check('sheet lead is a single short line', words(lead) <= 10, `${words(lead)} words: ${lead}`);
  check('spec values stay terse', longestDef <= 14, `longest ${longestDef} words`);
  check('scan checks stay terse', longestStep <= 9, `longest ${longestStep} words`);

  // The grid stretches both columns; compare their actual content extents.
  // The left column carries an extra heading and rule, so "level" means within
  // a fifth of the taller column rather than identical.
  const extents = await page.$$eval('.sheet-cols > *', (cols) =>
    cols.map((c) => {
      const kids = [...c.children];
      const first = kids[0].getBoundingClientRect();
      const last = kids[kids.length - 1].getBoundingClientRect();
      return Math.round(last.bottom - first.top);
    })
  );
  const slack = Math.max(...extents) * 0.2;
  check('the two sheet columns run close to level', Math.abs(extents[0] - extents[1]) <= slack, `left ${extents[0]}px, right ${extents[1]}px, slack ${Math.round(slack)}px`);

  const sheetText = await page.textContent('.track-sheet');
  check('sheet quotes the live day range', /2 to 4 across the network/.test(sheetText), (sheetText.match(/\d+ to \d+ across the network/) || [''])[0]);
  check('sheet quotes the live discount range', /50% off today/.test(sheetText), (sheetText.match(/\d+%( to \d+%)? off/) || [''])[0]);
  check('sheet quotes the live reservation count', new RegExp(`8 of ${NET} tracks`).test(sheetText), (sheetText.match(/\d+ of \d+ tracks/) || [''])[0]);
  check('sheet states where the money lands', /collect the member price at the window/.test(sheetText));

  const hrefs = await page.$$eval('a', (a) => a.map((x) => new URL(x.href).pathname));
  check('tracks view links to the network and operator sign-in', hrefs.includes('/tracks') && hrefs.includes('/login'), hrefs.join(','));
  check('no unicode check glyphs in the tracks view', !/[✓✔]/.test(await page.textContent('body')));
  await page.screenshot({ path: 'pricing-tracks.png', fullPage: true });

  // ---- The sheet reflows at mobile ---------------------------------------
  await page.setViewportSize({ width: 390, height: 900 });
  await page.waitForTimeout(300);
  check('no horizontal overflow at 390px (tracks)', !(await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth + 1)));
  const stacked = await page.$$eval('.sheet-cols > *', (s) => {
    const [a, b] = s.map((x) => x.getBoundingClientRect());
    return b.top >= a.bottom - 1;
  });
  check('sheet columns stack at 390px', stacked);
  const rowStacks = await page.$eval('.spec-list > div', (r) => {
    const [dt, dd] = [...r.children].map((c) => c.getBoundingClientRect());
    return dd.top >= dt.bottom - 1;
  });
  check('spec rows stack label over text at 390px', rowStacks);

  // ---- Back to riders, then riders mobile -------------------------------
  await page.goto(`${BASE}/pricing`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.tier-card', { timeout: 10000 });
  check('the riders view restores the plans', (await page.$$eval('.tier-card', (e) => e.length)) === 2);
  await page.waitForTimeout(200);
  check('no horizontal overflow at 390px (riders)', !(await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth + 1)));
  await page.screenshot({ path: 'pricing-mobile.png', fullPage: true });

  // ---- The discounted-day label reads as a discount ---------------------
  // The venue profile no longer states the pass terms, so the guard reads them
  // where a pass holder meets them: the network page's panel for that venue.
  // The network is motocross only and every venue offers its third day at 50%,
  // so the label must read the rate as a discount (`rate * 100`), never the
  // price fraction (`(1 - rate) * 100`) — at 50% the two agree, but a venue
  // whose label drifted off the contract still shows here as a bare percent.
  await login(page, 'alex@example.com');
  await page.goto(`${BASE}/tracks?track=budds-creek-motocross-park`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.track-panel', { timeout: 15000 });
  const termsText = await page.textContent('.track-panel');
  check('discounted days are labelled as the discount, not the price fraction', /50% off/.test(termsText) && !/\b0% off/.test(termsText), (termsText.match(/\d+% off/g) || []).join(','));

  check('no JS errors on the pricing page', errors.length === 0, errors.join(' | '));

  await browser.close();
  console.log(`\n${fails === 0 ? 'ALL PRICING CHECKS PASSED' : `${fails} PRICING CHECK(S) FAILED`}`);
  process.exit(fails === 0 ? 0 : 1);
}

main().catch((e) => {
  console.error('harness error:', e);
  process.exit(1);
});

/* Headless verification of the track profile page and the owner console.
 *
 * Two surfaces, one feature:
 *   /tracks/:slug      — the venue profile a rider or visitor reads: banner,
 *                        gallery, mark, its name (linked to the venue's own
 *                        site, when it keeps one), and the venue's calendar.
 *                        The pass's terms for the track are not stated here —
 *                        they read on the network page's panel.
 *   /operator/profile  — the owner console that fills that page in: profile
 *                        copy, art upload, social links, live status, and the
 *                        season — read-only there, the way a rider reads it.
 *   /operator/calendar — where the season is written: the same month grid with
 *                        that month's dates beside it as an editor.
 *
 *   cd web && npm run verify:profile     (dev server on :5180, API on :4010)
 *
 * The console run WRITES to the seeded demo DB (221 MX's profile and events) and
 * puts every field back at the end — if it fails midway, reseed before trusting
 * the demo data:  cd server && npm run seed
 *
 * Uses playwright-core with an explicit browser path so it works with the
 * browsers already in ~/.cache/ms-playwright and downloads nothing.
 */
const fs = require('fs');
const path = require('path');
const os = require('os');
const { chromium } = require('playwright-core');

const BASE = process.env.PROFILE_BASE || 'http://localhost:5180';
const API = process.env.PROFILE_API || 'http://localhost:4010';

/** The operator's community page can be paused by a const in the web app. Read
 *  that flag from the source, so the suite and the app can never disagree; a
 *  missing file reads as enabled, so a moved module fails loudly rather than
 *  silently skipping its checks. */
const FLAGS_FILE = path.join(__dirname, '..', 'src', 'lib', 'featureFlags.ts');
const COMMUNITY_ENABLED = !(
  fs.existsSync(FLAGS_FILE) &&
  /export\s+const\s+COMMUNITY_ENABLED\s*=\s*false/.test(fs.readFileSync(FLAGS_FILE, 'utf8'))
);

/** The venue's gallery as the API serves it — the suite reads its counts from
 *  here so a venue gaining or losing a photo does not break the contract. */
async function galleryOf(slug) {
  const r = await fetch(`${API}/api/tracks/${slug}`);
  const d = await r.json();
  return d?.data?.track?.photos ?? [];
}

/** The venue's schedule as the API serves it, grouped by the month each date
 *  falls in (UTC), plus the one the calendar should open on. Dates carry no
 *  count in the suite: the seed sets them relative to the run, so the checks
 *  read the payload rather than pinning a number. */
async function scheduleOf(slug) {
  const r = await fetch(`${API}/api/tracks/${slug}`);
  const d = await r.json();
  const events = d?.data?.track?.events ?? [];
  const today = new Date().toISOString().slice(0, 10);
  const byMonth = new Map();
  for (const e of events) {
    const key = e.startsAt.slice(0, 7);
    if (!byMonth.has(key)) byMonth.set(key, []);
    byMonth.get(key).push(e);
  }
  return {
    events,
    byMonth,
    next: events.find((e) => e.startsAt.slice(0, 10) >= today) ?? null,
    busiest: [...byMonth.entries()].sort((a, b) => b[1].length - a[1].length)[0] ?? null,
  };
}

/** The venue's week as the API serves it, keyed Mon..Sun. */
const HOURS_WEEK_KEYS = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];

async function weekOf(slug) {
  const r = await fetch(`${API}/api/tracks/${slug}`);
  const d = await r.json();
  return d?.data?.track?.hoursWeek ?? null;
}

/** How many venues the public network holds, read from the API at run time.
 *  The suite must not write the size down: venues come and go, and every count
 *  below (rows, venue pickers) is measured against this same number. */
async function networkCount() {
  const r = await fetch(`${API}/api/tracks?terms=public`);
  const d = await r.json();
  return (d?.data?.tracks ?? []).length;
}

/** The venue's own copy as the API serves it — what the console run puts back. */
async function descriptionOf(slug) {
  const r = await fetch(`${API}/api/tracks/${slug}`);
  const d = await r.json();
  return d?.data?.track?.description ?? '';
}

/** One field off the venue as the API serves it. */
async function trackField(slug, key) {
  const r = await fetch(`${API}/api/tracks/${slug}`);
  const d = await r.json();
  return d?.data?.track?.[key] ?? null;
}

/** The venue's next date as the API serves it (YYYY-MM-DD, noon UTC). */
async function nextDateOf(slug) {
  const r = await fetch(`${API}/api/tracks/${slug}`);
  const d = await r.json();
  const today = new Date().toISOString().slice(0, 10);
  const next = (d?.data?.track?.events ?? []).find((e) => e.startsAt.slice(0, 10) >= today);
  return next ? next.startsAt.slice(0, 10) : today;
}

/** The key the reader's own day reads as — JS hands the week back starting Sunday. */
function todayKey() {
  return ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'][new Date().getDay()];
}

/** The week as the profile lays it out: one row a day, in page order. */
const readWeek = (page) =>
  page.$$eval('.hours-week-block .hours-row', (rows) =>
    rows.map((r) => ({
      day: r.querySelector('dt abbr')?.textContent.trim() ?? '',
      value: r.querySelector('dd').textContent.trim(),
      today: r.classList.contains('is-today'),
    }))
  );

/** Step the calendar with its own chevrons until it shows `key` (YYYY-MM). */
async function openMonth(page, key) {
  for (let i = 0; i < 36; i++) {
    const at = await page.getAttribute('.event-cal', 'data-month');
    if (at === key) return true;
    await page.click(at && at > key ? '.cal-head .cal-nav:first-child' : '.cal-head .cal-nav:last-child');
    await page.waitForTimeout(220);
  }
  return false;
}

/** The Monday of the week a `YYYY-MM-DD` day falls in — the week grid's own key. */
function weekStartOf(day) {
  const d = new Date(`${day}T12:00:00Z`);
  d.setUTCDate(d.getUTCDate() - ((d.getUTCDay() + 6) % 7));
  return d.toISOString().slice(0, 10);
}

/** `540` -> `09:00` — the grid's own clock, for reading a marked slot back. */
function clockTime(minutes) {
  return `${String(Math.floor(minutes / 60)).padStart(2, '0')}:${String(minutes % 60).padStart(2, '0')}`;
}

/** `09:00`, `9am` or `9:15pm` -> minutes past midnight; `null` for neither. */
function toMinutes(t) {
  const m = String(t).trim().match(/^(\d{1,2})(?::(\d{2}))?\s*(am|pm)?$/i);
  if (!m) return null;
  const mins = Number(m[2] ?? 0);
  if (!m[3]) return Number(m[1]) * 60 + mins;
  return ((Number(m[1]) % 12) + (m[3].toLowerCase() === 'pm' ? 12 : 0)) * 60 + mins;
}

/** `11:00–16:00` (or `11am–4pm`) -> `[660, 960]` — a slot's two ends in minutes. */
function slotSpan(label) {
  return label.split('\u2013').map(toMinutes);
}

/** The hour height the week grid draws at — `HOUR_H` in `WeekGrid.tsx`. */
const WEEK_HOUR_H = 46;

/** Where an owner can mark a slot: the first hour of the week with no date
 *  drawn over it, as viewport coordinates. The grid is scrolled into view
 *  first — the pointer cannot reach what is off screen — and an hour under a
 *  chip is skipped, because that chip answers the click itself. */
async function freeHour(page) {
  await page.$eval('.wk-grid', (g) => g.scrollIntoView({ block: 'center' }));
  await page.waitForTimeout(250);
  return page.evaluate((HOUR_H) => {
    const cols = [...document.querySelectorAll('.wk-col')];
    const stamps = [...document.querySelectorAll('.wk-time')].map((t) => t.textContent.trim());
    const at = (t) => {
      const m = t.match(/^(\d{1,2})(?::(\d{2}))?\s*(am|pm)?$/i);
      if (!m) return null;
      const mins = Number(m[2] ?? 0);
      if (!m[3]) return Number(m[1]) * 60 + mins;
      return ((Number(m[1]) % 12) + (m[3].toLowerCase() === 'pm' ? 12 : 0)) * 60 + mins;
    };
    const from = at(stamps[0]);
    const last = at(stamps[stamps.length - 1]);
    for (let c = 0; c < cols.length; c++) {
      const box = cols[c].getBoundingClientRect();
      for (let m = from + 60; m + 60 <= last; m += 60) {
        const y = box.top + ((m - from) / 60) * HOUR_H + 4;
        if (y < 4 || y > window.innerHeight - 4) continue;
        // An hour already taken by a date is not the owner's to mark: the chip
        // under the pointer would answer the click itself.
        const el = document.elementFromPoint(box.left + box.width / 2, y);
        if (!el || el.closest('.wk-chip')) continue;
        return { x: box.left + box.width / 2, y, col: c, start: m };
      }
    }
    return null;
  }, WEEK_HOUR_H);
}


/** Step the owner's calendar page until it shows the week holding `day` — the
 *  page draws a fortnight either side of a date, not a month, so the profile
 *  helper above cannot drive it. */
async function openCalendarWeek(page, day) {
  const want = weekStartOf(day);
  for (let i = 0; i < 60; i++) {
    const at = await page.getAttribute('.cal-editor', 'data-week');
    if (at === want) return true;
    // `>> nth=` rather than `:first-child`/`:last-child`: the week bar carries
    // Today (and the marked slot's read) after the two chevrons, so neither
    // chevron is ever the last child of the bar.
    await page.click(at && at > want ? '.wk-bar .cal-nav >> nth=0' : '.wk-bar .cal-nav >> nth=1');
    await page.waitForTimeout(200);
  }
  return false;
}

/** Every page the month shows: one row-list of titles per page of dates. */
async function pagesInMonth(page, key) {
  if (!(await openMonth(page, key))) return [];
  const pages = [];
  for (let i = 0; i < 20; i++) {
    pages.push(await page.$$eval('.event-row b', (b) => b.map((x) => x.textContent.trim())));
    const more = await page.$('.cal-pager .cal-nav:last-child:not([disabled])');
    if (!more) break;
    await more.click();
    await page.waitForTimeout(220);
  }
  return pages;
}


function findBrowser() {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  if (!fs.existsSync(root)) return null;
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium_headless_shell-')) continue;
    const p = path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell');
    if (fs.existsSync(p)) return p;
    const alt = path.join(root, dir, 'chrome-linux', 'headless_shell');
    if (fs.existsSync(alt)) return alt;
  }
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium-')) continue;
    const p = path.join(root, dir, 'chrome-linux64', 'chrome');
    if (fs.existsSync(p)) return p;
  }
  return null;
}

let fails = 0;
function check(label, ok, detail = '') {
  if (!ok) fails++;
  console.log(`${ok ? 'OK  ' : 'FAIL'}  ${label}${detail ? ` — ${detail}` : ''}`);
}

async function login(page, email) {
  // Switching accounts: drop the previous session's cookie first, or the app
  // bounces the already-signed-in visitor away from /login.
  await page.context().clearCookies();
  await page.goto(`${BASE}/login`, { waitUntil: 'networkidle' });
  await page.waitForSelector('form #email');
  await page.fill('#email', email);
  await page.fill('#password', 'dialed123');
  await Promise.all([
    page.waitForURL((u) => !u.pathname.startsWith('/login'), { timeout: 20000 }),
    page.click('form button.primary'),
  ]);
}

async function main() {
  const exe = findBrowser();
  if (!exe) {
    console.error('No Playwright Chromium found in ~/.cache/ms-playwright.');
    process.exit(1);
  }
  const browser = await chromium.launch({ executablePath: exe });
  const page = await browser.newPage({ viewport: { width: 1280, height: 1000 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push(String(e.message)));

  // The one number every count below is measured against — read off the API,
  // never written down here.
  const NET = await networkCount();
  check('the network the suite measures against is read at run time', NET > 0, `${NET} venues`);

  // ---- The network page leads to a profile ------------------------------
  // The old public directory table is gone, and a row in the rail is a pick: it
  // opens that venue's inspector over the map, and the inspector's own link is
  // the way on to the venue's profile.
  await page.goto(`${BASE}/tracks`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.day-row', { timeout: 15000 });
  check('the network page lists a row per venue', (await page.$$eval('.day-row', (n) => n.length)) === NET);
  // The line carries the venue's place and nothing else — the gate note
  // ("Book ahead" on the venues that require a reservation) was removed at the
  // user's request, so no row annotates how you get in.
  const subs = await page.$$eval('.day-row .day-sub', (s) =>
    s.map((x) => x.textContent.trim())
  );
  check('every row states where the venue is', subs.length === NET && subs.every((t) => t.includes(', ')));
  check('no row carries a gate note', subs.every((t) => !/book ahead|walk-up/i.test(t)));
  check('the row line is the place alone', subs.every((t) => t.split(' · ').length === 1));

  // A row picks its venue; the venue's own profile (not its site) is one click
  // on, from the inspector's own link.
  await (await page.$('.day-row .day-open')).evaluate((b) => b.click());
  await page.waitForSelector('.venue-float .track-panel', { timeout: 10000 });
  check('a row opens the venue inspector', (await page.$$eval('.venue-float .track-panel', (n) => n.length)) === 1);
  await page.click('.venue-float .track-links-btn');
  await page.waitForSelector('.profile-head', { timeout: 10000 });
  const onProfile = new URL(page.url()).pathname;
  check('the inspector opens the profile, not the site', /^\/tracks\/[a-z0-9-]+$/.test(onProfile), onProfile);

  // ---- The public profile ------------------------------------------------
  const photos221 = await galleryOf('221-mx');
  check('221 MX is seeded with a gallery', photos221.length >= 5, `${photos221.length} photos`);
  await page.goto(`${BASE}/tracks/221-mx`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.profile-head', { timeout: 10000 });
  check('the profile names the venue', (await page.textContent('.profile-head h1')).trim() === '221 MX');
  check('the profile carries its mark', (await page.$('.profile-head .track-logo')) !== null);

  // The page opens on the venue's photo gallery: one frame at size, the rest of
  // the block beside it, and the way into the whole set on the last tile.
  await page.waitForSelector('.photo-gallery', { timeout: 10000 });
  check('the profile opens on the venue gallery', (await page.$('.photo-gallery')) !== null);
  check('the gallery has no stray banner slot', (await page.$('.profile-banner')) === null);
  check(
    'the hero frame is the venue\u2019s first photo',
    (await page.$eval('.photo-hero img', (i) => i.getAttribute('src'))) === `/tracks/photos/221-mx/01.jpg`
  );
  check('the hero is tagged as the featured frame', /Featured/i.test(await page.textContent('.photo-tag')));
  const tiles = await page.$$eval('.photo-tile img', (i) => i.map((x) => x.getAttribute('src')));
  check('the block beside the hero holds photos of the same venue', tiles.length >= 4, `${tiles.length} tiles`);
  check(
    'every tile is one of the venue\u2019s own photos',
    tiles.every((u) => /^\/tracks\/photos\/221-mx\/\d\d\.jpg$/.test(u)),
    tiles.join(' | ')
  );
  const moreLabel = (await page.textContent('.photo-more-label')).trim();
  check(
    'the last tile carries the whole count',
    moreLabel === `All Photos (${photos221.length})`,
    moreLabel
  );

  // The viewer: a tile opens it on that frame, it steps, and it closes.
  await page.click('.photo-tile >> nth=0');
  await page.waitForSelector('.lightbox', { timeout: 5000 });
  check('a tile opens the viewer on that photo', /2 \/ \d+/.test(await page.textContent('.lightbox-bar')));
  await page.click('.lightbox-nav.next');
  await page.waitForTimeout(300);
  check('the viewer steps forward', /3 \/ \d+/.test(await page.textContent('.lightbox-bar')));
  await page.keyboard.press('Escape');
  await page.waitForTimeout(400);
  check('Escape closes the viewer', (await page.$('.lightbox')) === null);
  await page.click('.photo-hero');
  await page.waitForSelector('.lightbox', { timeout: 5000 });
  check('the hero opens the viewer on the first photo', /1 \/ \d+/.test(await page.textContent('.lightbox-bar')));
  await page.screenshot({ path: 'profile-gallery-lightbox.png' });
  // Clicking off the photo (the letterboxing around it) closes, as does the × button.
  const stage = await page.$('.lightbox-stage');
  const box = await stage.boundingBox();
  const img = await page.$('.lightbox-stage img');
  const ibox = await img.boundingBox();
  await page.mouse.click(box.x + 4, box.y + box.height - 4);
  await page.waitForTimeout(400);
  check(
    'clicking off the photo closes the viewer',
    (await page.$('.lightbox')) === null || ibox.height >= box.height - 8,
    `stage ${Math.round(box.height)}px, photo ${Math.round(ibox.height)}px`
  );
  if (await page.$('.lightbox')) await page.keyboard.press('Escape');
  await page.waitForTimeout(400);
  await page.click('.photo-hero');
  await page.waitForSelector('.lightbox', { timeout: 5000 });
  await page.click('.lightbox-close');
  await page.waitForTimeout(400);
  check('the × button closes the viewer', (await page.$('.lightbox')) === null);

  // The profile is the venue, not its terms: the gate/terms rail is gone, so the
  // pass's own terms read only on the network page's panel. The venue's status
  // and its week are the profile's own facts.
  check('the profile carries no gate/terms rail', (await page.$$eval('.profile-side', (n) => n.length)) === 0);
  check('the profile states the location', /Union Mills, NC/.test(await page.textContent('.profile-meta')));

  // The venue's week: seven seeded days with the reader's own day marked, so
  // "can I ride today" is read off the page rather than counted to.
  const week = await weekOf('221-mx');
  const weekRows = await readWeek(page);
  check('the profile lays out the venue\u2019s week', weekRows.length === 7, `${weekRows.length} rows`);
  check(
    'the week runs Mon to Sun',
    weekRows.map((r) => r.day).join(',') === 'Mon,Tue,Wed,Thu,Fri,Sat,Sun',
    weekRows.map((r) => r.day).join(',')
  );
  check(
    'every day reads the hours on file',
    Boolean(week) && HOURS_WEEK_KEYS.every((k, i) => weekRows[i].value === week[k]),
    weekRows.map((r) => r.value).join(' | ')
  );
  const todayAt = HOURS_WEEK_KEYS.indexOf(todayKey());
  check(
    'the reader\u2019s own day is the one marked',
    weekRows.filter((r) => r.today).length === 1 && weekRows[todayAt].today,
    `marked row ${weekRows.findIndex((r) => r.today)}`
  );
  check(
    'the venue\u2019s description reads above the week',
    (await page.$('.profile-main .profile-desc')) !== null
  );

  // The Location & Hours block: the venue on a map, the address it is reached
  // at, the week it runs and the card of ways in. 221 MX keeps no website on
  // file, so its card lists no site row — the omission is the check.
  await page.waitForSelector('.loc .leaflet-container', { timeout: 10000 });
  check('the profile draws the venue on a map', (await page.$('.loc .leaflet-container')) !== null);
  check(
    'the venue\u2019s own dot sits on the map',
    (await page.$('.loc .map-pin-dot[data-name="221 MX"]')) !== null
  );
  // The place rides on the directions row's own line now that the block is
  // map-beside-card; the full address the venue publishes contains it.
  check(
    'the location block names the place on file',
    /Union Mills, NC/.test(await page.textContent('.loc-line'))
  );
  const dirHref = await page.getAttribute('.loc-dir-btn', 'href');
  check(
    'directions carry the venue\u2019s own coordinates',
    Boolean(dirHref) && dirHref.includes('35.46143') && dirHref.includes('-81.98244'),
    dirHref ?? 'no link'
  );
  check(
    'a venue with no site on file lists no site row',
    (await page.$('.loc-card .loc-link')) === null
  );

  // The directions row prints the address the venue publishes, and the button
  // beside it puts that address on the clipboard.
  const addr221 = await trackField('221-mx', 'address');
  check(
    'the directions row prints the venue\u2019s full address',
    Boolean(addr221) && (await page.textContent('.loc-line')).trim() === addr221.trim(),
    addr221 ?? 'no address on file'
  );
  await page.context().grantPermissions(['clipboard-read', 'clipboard-write']);
  await page.click('.loc-ico-btn');
  await page.waitForTimeout(200);
  check(
    'the copy button puts the address on the clipboard',
    (await page.evaluate(() => navigator.clipboard.readText())).trim() === String(addr221).trim()
  );
  check('the copy button reports that it copied', (await page.$('.loc-ico-btn.is-copied')) !== null);
  // Today's own line carries its state: a venue running today says so, and one
  // shut today says when the week opens again. One of the two is on the page
  // whichever day the suite runs.
  const runningToday = weekRows[todayAt].value !== 'Closed';
  check(
    'today carries its own state',
    runningToday
      ? (await page.textContent('.hours-row.is-today .status-pill')).trim().length > 0
      : (await page.$('.hours-reopen')) !== null &&
          /Reopens [A-Z][a-z]+day/.test(await page.textContent('.hours-reopen')),
    runningToday ? 'running today' : 'shut today'
  );
  // The schedule is a calendar, a month at a time: it opens on the venue's next
  // date, holds five dates to a page, and the months behind it keep what ran.
  const sched = await scheduleOf('221-mx');
  const opensOn = sched.next.startsAt.slice(0, 7);
  check(
    'the schedule opens on the month of the venue\u2019s next date',
    (await page.getAttribute('.event-cal', 'data-month')) === opensOn,
    `next date ${sched.next.startsAt.slice(0, 10)}`
  );
  check(
    'the calendar is a month: seven columns, six weeks',
    (await page.$$eval('.cal-dow span', (n) => n.length)) === 7 &&
      (await page.$$eval('.cal-days .cal-day', (n) => n.length)) === 42
  );
  const firstPage = await page.$$eval('.event-row', (r) =>
    r.map((x) => x.textContent.replace(/\s+/g, ' ').trim())
  );
  check('a page of the schedule holds at most five dates', firstPage.length <= 5, `${firstPage.length} rows`);
  check(
    'a date reads its kind',
    /* The seed's titles are sentence-case ("Open practice", "Saturday race day"),
       so the kind reads in lower case on the row — match it either way. */
    /practice|race|clinic|ride day/i.test(firstPage.join(' ')),
    firstPage.join(' | ').slice(0, 120)
  );

  // A reader who does not own the date can still open it: the row is a control
  // that opens the owner's own sheet with every field taken out of it.
  const firstTitle = await page.$eval('.event-row.has-open b', (b) => b.textContent.trim());
  const rowOpens = await page.$$eval('.event-row.has-open .event-open', (b) => b.length);
  check(
    'every date on the schedule is a control',
    rowOpens === firstPage.length && rowOpens > 0,
    `${rowOpens} of ${firstPage.length} rows`
  );
  await page.click('.event-row.has-open .event-open');
  await page.waitForTimeout(350);
  const openSheet = await page.evaluate(() => {
    const s = document.querySelector('.sheet.event-read');
    if (!s) return null;
    return {
      title: s.querySelector('.sheet-title')?.textContent.trim() ?? '',
      labels: [...s.querySelectorAll('.ev-label')].map((l) => l.textContent.trim()),
      readback: s.querySelector('.ev-readback')?.innerText.replace(/\n/g, ' ') ?? '',
      fields: s.querySelectorAll('input, select, textarea').length,
      writes: s.querySelectorAll('button.primary, button.danger').length,
      buttons: [...s.querySelectorAll('button')].map((b) => b.textContent.trim()).join('|'),
      focused: String(document.activeElement?.className ?? ''),
    };
  });
  check('a date opens the sheet it was clicked from', openSheet?.title === firstTitle, `${firstTitle} → ${openSheet?.title}`);
  check(
    'the sheet reads its date and hours back',
    !!openSheet && openSheet.labels.includes('Date') && openSheet.readback.length > 0,
    openSheet ? `${openSheet.labels.join(', ')} — ${openSheet.readback}` : 'no sheet'
  );
  check(
    'and there is nothing on it to write',
    !!openSheet && openSheet.fields === 0 && openSheet.writes === 0,
    openSheet ? `${openSheet.fields} fields, ${openSheet.writes} write buttons` : 'no sheet'
  );
  check('the read carries no Shown row', !!openSheet && !openSheet.labels.includes('Shown'), openSheet?.labels.join(', '));
  check('Close is the only thing it offers', openSheet?.buttons === 'Close', openSheet?.buttons ?? 'no sheet');
  check('the sheet takes the focus', !!openSheet?.focused.includes('event-read'), openSheet?.focused);
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);
  check('Escape puts the read sheet away', !(await page.$('.sheet.event-read')));

  // The month carrying the most dates is where the list runs past one page.
  const busiestPages = await pagesInMonth(page, sched.busiest[0]);
  const fullest = Math.max(...busiestPages.map((p) => p.length));
  const paged = busiestPages.reduce((n, p) => n + p.length, 0);
  check(
    'five dates is one page of the month',
    sched.busiest[1].length > 5 ? fullest === 5 : fullest === sched.busiest[1].length,
    `${sched.busiest[1].length} dates in ${sched.busiest[0]} over ${busiestPages.length} page(s), fullest ${fullest}`
  );
  check(
    'paging reaches every date in the month',
    paged === sched.busiest[1].length,
    `${paged} rows of ${sched.busiest[1].length}`
  );

  // A booked day is a control: it fills, and it pages the list to its own date.
  const lastDate = sched.busiest[1][sched.busiest[1].length - 1];
  const cells = await page.$$('.cal-days .cal-day.has-event:not(.is-out)');
  await cells[cells.length - 1].click();
  await page.waitForTimeout(250);
  const shownTitles = await page.$$eval('.event-row b', (b) => b.map((x) => x.textContent.trim()));
  const picked = (await page.textContent('.cal-day.is-picked')) ?? '';
  check(
    'clicking a booked day opens its own date',
    picked.trim() === String(Number(lastDate.startsAt.slice(8, 10))) &&
      shownTitles.includes(lastDate.title),
    `${shownTitles.join(' | ').slice(0, 100)}`
  );

  // And the months behind the venue still read, rather than emptying out.
  const pastKey = [...sched.byMonth.keys()].filter((k) => k < opensOn).sort().pop();
  const pastPages = await pagesInMonth(page, pastKey);
  check(
    'a month already run still lists its dates',
    pastPages.flat().length === sched.byMonth.get(pastKey).length && pastPages.flat().length > 0,
    `${pastKey}: ${pastPages.flat().length} date(s)`
  );
  // The venue's name is the way out to its own site, when it keeps one — 221 MX
  // has no website on file, so its name stays plain text.
  check(
    'a venue with no site on file keeps a plain name',
    (await page.$('.profile-head-text h1 a')) === null &&
      (await page.textContent('.profile-head-text h1')).trim() === '221 MX'
  );
  check('the profile links back to the network', (await page.$('.profile-back')) !== null);

  // "On the map" names the venue itself: the network page opens on that venue's
  // inspector with its own pin lit, the rail's list still beside it.
  await page.click('.profile-head-actions .track-links-btn');
  await page.waitForSelector('.track-panel', { timeout: 10000 });
  check(
    'the profile hands its own venue to the network page',
    (await page.textContent('.track-panel-body h2')).trim() === '221 MX'
  );
  check('the handed-over venue keeps its own pin lit', (await page.$$eval('.map-pin-wrap.dim', (n) => n.length)) === 24);

  // A venue that keeps a site: the head's own icon button opens that site, in a
  // new tab, with the globe glyph inside it. The name now opens the venue's
  // profile, so the site rides with the head's other actions.
  await page.goto(`${BASE}/tracks/east-bend-motorsports`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.profile-head', { timeout: 10000 });
  const siteHref = await page.getAttribute('.profile-head-actions a.track-links-icon', 'href');
  check('a venue with a site offers it from its head', siteHref !== null);
  check(
    'the site button points at the venue\u2019s own site',
    siteHref === 'https://eastbendmotorsports.com',
    siteHref ?? 'no href'
  );
  check(
    'the site button opens the site in a new tab',
    (await page.getAttribute('.profile-head-actions a.track-links-icon', 'target')) === '_blank'
  );
  check(
    'the site button carries the globe glyph',
    (await page.$$eval('.profile-head-actions a.track-links-icon svg', (n) => n.length)) === 1
  );
  check(
    'the contact card lists the venue\u2019s own site',
    (await page.textContent('.loc-card .loc-link')).trim() === 'eastbendmotorsports.com'
  );
  // The feeds ride as bare marks: one anchor per feed it keeps, a glyph inside
  // each, no printed label — the name lives on the anchor for a screen reader.
  const socialRow = await page.$$eval('.loc-socials a', (els) =>
    els.map((a) => ({
      label: a.getAttribute('aria-label') ?? '',
      text: a.textContent.trim(),
      glyphs: a.querySelectorAll('svg').length,
    }))
  );
  check(
    'the card lists the venue\u2019s feeds as icons alone',
    socialRow.length === 2 &&
      socialRow.every((s) => s.text === '' && s.glyphs === 1) &&
      socialRow[0].label.endsWith('on Instagram') &&
      socialRow[1].label.endsWith('on Facebook'),
    socialRow.map((s) => `${s.label}${s.text ? ` (${s.text})` : ''}`).join(' | ')
  );
  check(
    'a venue with a gallery opens on it',
    (await page.$eval('.photo-hero img', (i) => i.getAttribute('src'))) === '/tracks/photos/east-bend-motorsports/01.jpg'
  );

  // Every seeded venue carries a real gallery, so every profile opens on one.
  // The plain `.profile-banner-fallback` still exists for a venue with no photos
  // and no imageUrl, but no seeded track exercises it any more.
  await page.goto(`${BASE}/tracks/glen-helen-raceway`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.profile-head', { timeout: 10000 });
  check(
    'a venue with photos shows them, not a fallback',
    (await page.$('.photo-gallery')) !== null && (await page.$('.profile-banner-fallback')) === null
  );
  check(
    'a venue with no schedule says so',
    /Nothing posted yet/.test(await page.textContent('.profile-main'))
  );

  // A venue that is shut mid-week reads Closed on those days, never blank. The
  // motocross network's weekend-only venues (221 MX, SOBMX, RedBud, …) close
  // Monday–Thursday; RedBud MX stands in for the old off-road park here.
  await page.goto(`${BASE}/tracks/redbud-mx`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.hours-week-block', { timeout: 10000 });
  const midweekWeek = await weekOf('redbud-mx');
  const midweekRows = await readWeek(page);
  check(
    'a venue shut mid-week reads Closed on those days',
    midweekWeek?.mon === 'Closed' &&
      midweekWeek?.tue === 'Closed' &&
      midweekRows[0].value === 'Closed' &&
      midweekRows[1].value === 'Closed' &&
      midweekRows[5].value === midweekWeek.sat,
    midweekRows.map((r) => r.value).join(' | ')
  );
  check(
    'a shut day is styled as shut',
    (await page.$$eval('.hours-value.is-closed', (n) => n.length)) === 4,
    'Mon\u2013Thu'
  );

  // A venue that runs today reads its state on today's own line, as bare
  // coloured text. No venue in the motocross seed runs all seven days, so the
  // read is driven off a midweek venue (East Bend opens Wednesday–Sunday): on a
  // day it runs, today's line carries the bare green "Open now"; on a shut day
  // it carries the reopen line instead — the same two answers 221 MX already
  // proves above.
  await page.goto(`${BASE}/tracks/east-bend-motorsports`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.hours-week-block', { timeout: 10000 });
  const openWeek = await weekOf('east-bend-motorsports');
  const openRows = await readWeek(page);
  const openTodayRow = openRows[HOURS_WEEK_KEYS.indexOf(todayKey())];
  const venueRunsToday = Boolean(openWeek) && openTodayRow.value !== 'Closed';
  if (venueRunsToday) {
    const openState = await page.$eval('.hours-row.is-today .status-pill', (el) => {
      const cs = getComputedStyle(el);
      return {
        text: el.textContent.trim(),
        border: cs.borderTopWidth,
        shade: cs.paddingTop,
        color: cs.color,
      };
    });
    check('a venue running today says so on its own line', openState.text === 'Open now', openState.text);
    check(
      'the open state is bare text, with no chip around it',
      openState.border === '0px' && openState.shade === '0px',
      `border ${openState.border}, padding ${openState.shade}`
    );
    check(
      'the open state reads the app\u2019s ok green',
      openState.color === 'rgb(74, 222, 128)',
      openState.color
    );
  } else {
    check(
      'a venue shut today says when the week opens again',
      (await page.$('.hours-reopen')) !== null &&
        /Reopens [A-Z][a-z]+day/.test(await page.textContent('.hours-reopen')),
      openTodayRow.value
    );
  }

  // A slug that is not a track is a dead end with a way out, not a crash.
  await page.goto(`${BASE}/tracks/not-a-track`, { waitUntil: 'networkidle' });
  await page.waitForSelector('h1', { timeout: 10000 });
  check('an unknown slug reads as not found', /Track not found/.test(await page.textContent('h1')));
  check('the not-found page offers the network', (await page.$('a[href="/tracks"]')) !== null);

  // 390px: nothing drags sideways.
  await page.setViewportSize({ width: 390, height: 900 });
  await page.goto(`${BASE}/tracks/221-mx`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.profile-main', { timeout: 10000 });
  check(
    'no horizontal overflow at 390px',
    !(await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth + 1))
  );
  check(
    'the gallery stacks on a phone',
    (await page.evaluate(() => {
      const cols = getComputedStyle(document.querySelector('.photo-gallery')).gridTemplateColumns;
      return cols.split(' ').length === 1;
    }))
  );

  // ---- A free rider reads the venue, not the pass's terms ----------------
  await page.setViewportSize({ width: 1280, height: 1000 });
  await login(page, 'quinn@example.com');
  await page.goto(`${BASE}/tracks/221-mx`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.profile-head', { timeout: 10000 });
  const freeText = await page.textContent('.profile');
  check('a free rider reads the venue', /Union Mills, NC/.test(freeText) && /Open/.test(freeText));
  check('a free rider is shown no pass terms here', !/Included days/.test(freeText) && !/% off/.test(freeText));
  check('a free rider can follow from the profile', (await page.$('.follow-toggle')) !== null);
  await page.screenshot({ path: 'profile-free-tier.png', fullPage: true });

  // ---- The owner console customizes it -----------------------------------
  await login(page, 'ops@221mx.example.com');
  await page.goto(`${BASE}/operator/profile`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.profile-console', { timeout: 15000 });
  check('the operator console opens on the owner\u2019s own track', /221 MX/.test(await page.textContent('h1')));
  check('the console shows the live preview', (await page.$('.profile-preview')) !== null);
  check(
    'the console offers a banner and a logo slot',
    (await page.$$eval('.image-picker', (p) => p.length)) === 2
  );

  // ---- The gallery in the console ----------------------------------------
  // Order is the feature: the first frame is what the venue page opens on, so
  // moving a photo up has to show up there. The move is put back below.
  await page.waitForSelector('.gallery-manager', { timeout: 10000 });
  const photos221Console = await galleryOf('221-mx');
  const rowsBefore = await page.$$eval('.gallery-row', (r) => r.length);
  check(
    'the console lists the venue\u2019s seeded photos',
    rowsBefore === photos221Console.length,
    `${rowsBefore} rows, ${photos221Console.length} seeded`
  );
  check('the console marks the opening frame', /Opening frame/.test(await page.textContent('.gallery-row')));
  check(
    'the console offers a category and a caption per photo',
    (await page.$('.gallery-row select')) !== null && (await page.$('.gallery-row input[placeholder^="Caption"]')) !== null
  );
  // The operator can blow a frame up full screen without leaving the console —
  // the same viewer the public gallery uses, so a frame is judged at the size
  // the page shows it. Escape must put them back in the console.
  await page.click('.gallery-row >> nth=1 >> .gallery-thumb-open');
  await page.waitForSelector('.lightbox', { timeout: 5000 });
  check(
    'a console thumb opens the full-screen viewer',
    /^2 \/ \d+$/.test((await page.textContent('.lightbox-bar .small.muted')).trim())
  );
  await page.keyboard.press('Escape');
  await page.waitForSelector('.lightbox', { state: 'detached', timeout: 5000 });
  check('Escape returns to the console', true);
  // Order is also draggable: a grip on every row, and the viewer's strip turned
  // into an ordering control while the console owns it. Non-mutating — the
  // drag itself is exercised by hand, this only guards the wiring.
  const grips = await page.$$eval('.gallery-grip', (g) => g.length);
  check(
    'every row carries a drag grip',
    grips === rowsBefore && (await page.$eval('.gallery-grip', (g) => g.draggable === true)),
    `${grips} grips, ${rowsBefore} rows`
  );
  await page.click('.gallery-row >> nth=0 >> .gallery-thumb-open');
  await page.waitForSelector('.lightbox .lightbox-strip.reorderable', { timeout: 5000 });
  check(
    'the console viewer reorders by dragging a frame',
    await page.$eval('.lightbox-thumb', (t) => t.draggable === true)
  );
  await page.keyboard.press('Escape');
  await page.waitForSelector('.lightbox', { state: 'detached', timeout: 5000 });
  const orderBefore = await page.$$eval('.gallery-thumb img', (i) => i.map((x) => x.getAttribute('src')));
  await page.click('.gallery-row >> nth=1 >> button:has-text("↑")');
  await page.waitForTimeout(900);
  const orderAfter = await page.$$eval('.gallery-thumb img', (i) => i.map((x) => x.getAttribute('src')));
  check(
    'a photo moves up the gallery order',
    orderAfter[0] === orderBefore[1] && orderAfter[1] === orderBefore[0],
    orderAfter.slice(0, 2).join(' | ')
  );
  await page.goto(`${BASE}/tracks/221-mx`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.photo-hero', { timeout: 10000 });
  check(
    'the public page opens on the frame the owner moved up',
    (await page.$eval('.photo-hero img', (i) => i.getAttribute('src'))) === orderBefore[1]
  );
  await page.goto(`${BASE}/operator/profile`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.gallery-manager', { timeout: 15000 });
  await page.click('.gallery-row >> nth=0 >> button:has-text("↓")');
  await page.waitForTimeout(900);
  check(
    'the gallery order is back where the seed left it',
    (await page.$$eval('.gallery-thumb img', (i) => i.map((x) => x.getAttribute('src'))))[0] === orderBefore[0]
  );

  // Adding and removing a photo round-trips (the URL is one of the venue's own,
  // so nothing new is uploaded and the row goes away again below).
  await page.fill('.gallery-manager ~ .image-picker-controls .image-url', '/tracks/photos/221-mx/01.jpg');
  await page.click('.gallery-manager ~ .image-picker-controls button:has-text("Add from URL")');
  await page.waitForSelector('.banner.ok', { timeout: 10000 });
  await page.waitForTimeout(900);
  const rowsAdded = await page.$$eval('.gallery-row', (r) => r.length);
  check('the console adds a photo', rowsAdded === rowsBefore + 1, `${rowsAdded} rows`);
  await page.evaluate(() => {
    const rows = [...document.querySelectorAll('.gallery-manager .gallery-row')];
    const btn = [...rows[rows.length - 1].querySelectorAll('button')].find((b) => /Remove/.test(b.textContent));
    btn.click();
  });
  await page.waitForTimeout(1200);
  check(
    'the console drops the photo again',
    (await page.$$eval('.gallery-row', (r) => r.length)) === rowsBefore
  );

  // Edit the profile, save, and read it back on the public page. The venue's own
  // copy is read first so the restore at the end of this phase puts the seed's
  // words back: this used to fill the textarea with '', which left 221 MX with no
  // description at all and made the *next* run fail on a data state.
  const seededDescription = await descriptionOf('221-mx');
  const stamp = `Console check ${Date.now() % 100000}`;
  await page.fill('textarea', stamp);
  await page.fill('input[placeholder="Practice 9am–4pm"]', 'Practice 9am–4pm');
  // And one day of the week, which the console edits a field at a time.
  const seededWeek = await weekOf('221-mx');
  const editedMonday = `Practice ${Date.now() % 10000}am`;
  await page.fill('.week-editor input >> nth=0', editedMonday);
  await page.selectOption('select[aria-label="Status"]', 'CLOSED');
  await page.click('button:has-text("Save profile")');
  await page.waitForSelector('.banner.ok', { timeout: 10000 });
  check('saving the profile reports back', /Profile saved/.test(await page.textContent('.banner.ok')));

  await page.goto(`${BASE}/tracks/221-mx`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.profile-main', { timeout: 10000 });
  check('the public page shows the saved description', (await page.textContent('.profile-desc')).includes(stamp));
  check('the public page shows the saved status', /Closed/.test(await page.textContent('.profile-meta')));
  check(
    'the day the console edited reaches the public week',
    (await readWeek(page))[0].value === editedMonday,
    (await readWeek(page))[0].value
  );

  // ---- The season: read on the profile, written on the calendar page -------
  await page.goto(`${BASE}/operator/profile`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.profile-console', { timeout: 15000 });
  check(
    'the console reads the season in the schedule band',
    (await page.$('.profile-console ~ .card .event-cal')) !== null
  );
  check('the console writes no dates of its own', (await page.$('.event-edit-row')) === null);
  check(
    'the schedule band offers the calendar page',
    (await page.$('a[href="/operator/calendar"]')) !== null
  );
  const listedRows = await page.$$eval('.event-row.has-action', (r) => r.length);
  const editLinks = await page.$$eval('.event-row.has-action a[href^="/operator/calendar?event="]', (a) => a.length);
  check(
    'every date on the profile offers its own Edit',
    listedRows > 0 && editLinks === listedRows,
    `${editLinks} links / ${listedRows} rows`
  );
  const handedTitle = await page.$eval('.event-row.has-action b', (b) => b.textContent.trim());

  // The calendar page is where the season is written: a week of the season as a
  // time grid — an all-day row over an hour grid — with that week's dates as
  // cards underneath and an Add Event sheet the header button opens. It opens on
  // the week holding the venue's next date.
  await page.goto(`${BASE}/operator/calendar`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.cal-editor .wk-grid .event-edit-row, .cal-editor .wk-grid', { timeout: 15000 });
  await page.waitForSelector('.event-edit-row', { timeout: 15000 });
  check(
    'the calendar page draws the week: seven days over an hour grid',
    (await page.$$eval('.wk-dow', (n) => n.length)) === 7 &&
      (await page.$$eval('.wk-col', (n) => n.length)) === 7 &&
      (await page.$$eval('.wk-time', (n) => n.length)) >= 12
  );
  check(
    'adding a date is a button, not a form parked under the list',
    (await page.$('.sheet.event-sheet')) === null &&
      (await page.$('button:has-text("Add Event")')) !== null
  );
  const nextDate = await nextDateOf('221-mx');
  const openedOn = await page.getAttribute('.cal-editor', 'data-week');
  check(
    'the calendar opens on the week of the venue\u2019s next date',
    openedOn === weekStartOf(nextDate),
    `${openedOn} vs ${weekStartOf(nextDate)}`
  );
  check(
    'a date is drawn as a block naming its own hours',
    // Read as a pair of times rather than as one clock's spelling: the grid
    // prints its hours the way the rest of the app does, whatever register
    // that is, and a block that names no hours at all is what this catches.
    (await page.$$eval('.wk-chip', (c) => c.map((x) => x.innerText.replace(/\s+/g, ' ')))).every(
      (t) => {
        const pair = t.match(/(\d{1,2}(?::\d{2})?\s*(?:am|pm)?)\s*[–-]\s*(\d{1,2}(?::\d{2})?\s*(?:am|pm)?)/i);
        return !!pair;
      }
    ),
    (await page.$$eval('.wk-chip', (c) => c.length)) + ' blocks'
  );

  // A date on the grid narrows the cards to the dates that cover it, and the
  // label above them names it; `Show all events` puts the month back. The
  // cards are the month's, not the week's on the grid — that is what makes the
  // two columns worth having side by side.
  const gridCards = await page.$$eval('.event-editor .event-edit-row:not(.new)', (r) => r.length);
  const monthOf = await fetch(`${API}/api/tracks/221-mx`).then((r) => r.json());
  const monthCount = (monthOf.data.track.events ?? []).filter(
    (e) => e.startsAt.slice(0, 7) === nextDate.slice(0, 7)
  ).length;
  check(
    'the cards hold the month, not just the week on the grid',
    gridCards === monthCount,
    `${gridCards} cards vs ${monthCount} in the month`
  );

  // The card itself is the control: there is no separate Edit button, and a
  // click anywhere on the card opens the same field sheet.
  check(
    'a date card offers no separate Edit button',
    (await page.$('.event-editor .event-edit-row button:has-text("Edit")')) === null
  );
  const firstCard = await page.$('.event-editor .event-edit-row:not(.new)');
  await firstCard.$eval('.event-open', (b) => b.click());
  await page.waitForSelector('.sheet.event-sheet', { timeout: 5000 });
  check('clicking the card opens its field sheet', (await page.$('#edit-event-title')) !== null);
  check(
    'the sheet opens on the card it was clicked from',
    (await page.inputValue('.event-sheet input >> nth=0')) ===
      (await firstCard.$eval('.event-card-title', (t) => t.textContent.trim()))
  );
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);
  check('Escape drops the sheet the card opened', (await page.$('.sheet.event-sheet')) === null);
  // A date on the grid is a control for itself: clicking a chip opens that
  // date's own sheet and leaves the month's cards alone. The day head over a
  // column is the other control — that is the one that narrows the cards.
  const chipLabel = (await page.textContent('.wk-chip >> nth=0')).replace(/\s+/g, ' ').trim();
  await page.click('.wk-chip >> nth=0');
  await page.waitForTimeout(300);
  check('clicking a date on the grid opens its sheet', (await page.$('#edit-event-title')) !== null);
  check(
    'the chip opens the date it draws',
    chipLabel.startsWith((await page.inputValue('.event-sheet input >> nth=0')).trim()),
    `${chipLabel} -> ${await page.inputValue('.event-sheet input >> nth=0')}`
  );
  check('a chip on the grid leaves the month list alone', (await page.$('.event-filter')) === null);
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);

  await page.click('.wk-dow.has-event >> nth=0');
  await page.waitForTimeout(300);
  const dayRows = await page.$$eval('.event-editor .event-edit-row:not(.new)', (r) => r.length);
  const dayLabel = (await page.textContent('.event-filter .event-filter-day')).trim();
  check(
    'picking a date narrows the calendar list to it',
    dayRows > 0 && dayRows < gridCards,
    `${dayRows} of ${gridCards} cards`
  );
  check('the filter names the date it holds', /^\w{3}, \w{3} \d{1,2}$/.test(dayLabel), dayLabel);

  await page.click('.wk-dow.has-event >> nth=1');
  await page.waitForTimeout(300);
  const otherLabel = (await page.textContent('.event-filter .event-filter-day')).trim();
  check('picking another day moves the filter', otherLabel !== dayLabel, `${dayLabel} -> ${otherLabel}`);

  await page.click('.event-filter button:has-text("Show all events")');
  await page.waitForTimeout(300);
  check(
    'Show all events puts the month back',
    (await page.$$eval('.event-editor .event-edit-row:not(.new)', (r) => r.length)) === gridCards,
    `${gridCards} cards`
  );
  check('the filter row goes with the filter', (await page.$('.event-filter')) === null);

  // The chevrons step a week at a time, and Today lands on this week.
  const weekBefore = await page.getAttribute('.cal-editor', 'data-week');
  await page.click('.wk-bar .cal-nav >> nth=1');
  await page.waitForTimeout(300);
  const weekAfter = await page.getAttribute('.cal-editor', 'data-week');
  check(
    'the calendar steps a week at a time',
    new Date(`${weekAfter}T12:00:00Z`) - new Date(`${weekBefore}T12:00:00Z`) === 6048e5,
    `${weekBefore} -> ${weekAfter}`
  );
  await page.click('button:has-text("Today")');
  await page.waitForTimeout(300);
  const todayWeek = new Date().toISOString().slice(0, 10);
  check(
    'Today lands on this week',
    (await page.getAttribute('.cal-editor', 'data-week')) === weekStartOf(todayWeek),
    await page.getAttribute('.cal-editor', 'data-week')
  );

  const newEvent = `Night practice ${Date.now() % 100000}`;
  await page.click('button:has-text("Add Event")');
  await page.waitForSelector('.sheet.event-sheet', { timeout: 5000 });
  check('the button opens the Add Event sheet', (await page.$('[role="dialog"][aria-modal="true"]')) !== null);
  await page.fill('.event-sheet input >> nth=0', newEvent);
  await page.click('.event-sheet button:has-text("Add event")');
  await page.waitForTimeout(1200);
  check('the sheet closes once the date posts', (await page.$('.sheet.event-sheet')) === null);
  // The new card defaults a week out, so the date lands in the week a week from
  // today — the same day the seed would have dated it.
  const newDay = new Date(Date.now() + 6048e5).toISOString().slice(0, 10);
  const newKey = newDay.slice(0, 7);
  const listedTitles = await page.$$eval('.event-card-title', (t) => t.map((x) => x.textContent.trim()));
  check('the calendar lists the new event', listedTitles.includes(newEvent), `${listedTitles.length} cards`);
  check(
    'posting a date steps the calendar to its week',
    (await page.getAttribute('.cal-editor', 'data-week')) === weekStartOf(newDay),
    await page.getAttribute('.cal-editor', 'data-week')
  );

  await page.goto(`${BASE}/tracks/221-mx`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.event-cal', { timeout: 10000 });
  const publicTitles = (await pagesInMonth(page, newKey)).flat();
  check('the new event reaches the public profile', publicTitles.includes(newEvent), publicTitles.join(' | ').slice(0, 120));
  check('events read as dates, not instants', (await page.textContent('.event-cal')).indexOf('T12:00') === -1);

  // The profile's Edit hand-off is a shareable URL, and it lands on that date's
  // own card rather than on the calendar's opening week.
  await page.goto(`${BASE}/operator/profile`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.event-row.has-action', { timeout: 15000 });
  await page.click('.event-row.has-action a[href^="/operator/calendar?event="]');
  await page.waitForSelector('.event-edit-row.is-focused', { timeout: 15000 });
  check('the profile\u2019s Edit opens that date on the calendar page', page.url().includes('/operator/calendar?event='));
  check(
    'the hand-off brings the picked date into view',
    (await page.$eval('.event-edit-row.is-focused .event-card-title', (t) => t.textContent.trim())) === handedTitle,
    handedTitle
  );
  check(
    'the hand-off lands on the handed date\u2019s own week',
    (await page.getAttribute('.cal-editor', 'data-week')) === weekStartOf(nextDate),
    await page.getAttribute('.cal-editor', 'data-week')
  );

  // Remove it again, then put the profile back the way the seed left it. The
  // week lists its dates in date order, so the card is found by title and its
  // fields live in the Edit sheet.
  await page.goto(`${BASE}/operator/calendar`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.cal-editor .wk-grid', { timeout: 15000 });
  check('the calendar can be stepped to another week', await openCalendarWeek(page, newDay));
  const cards = await page.$$('.event-editor .event-edit-row:not(.new)');
  let target = null;
  for (const r of cards) {
    const v = await r.$eval('.event-card-title', (t) => t.textContent.trim());
    if (v === newEvent) target = r;
  }
  check('the new event is in the calendar list', target !== null, `${cards.length} cards`);
  await target.$eval('.event-open', (b) => b.click());
  await page.waitForSelector('.sheet.event-sheet', { timeout: 5000 });
  await page.click('.event-sheet button:has-text("Remove")');
  await page.waitForSelector('.confirm-sheet', { timeout: 5000 });
  await page.click('.confirm-sheet button.primary.danger');
  await page.waitForTimeout(1200);
  const afterDelete = await page.$$eval('.event-card-title', (t) => t.map((x) => x.textContent.trim()));
  check('removing a date drops it from the calendar page', !afterDelete.includes(newEvent));

  // ---- The week sets the hours: mark a slot, drag its ends -----------------
  // An owner says *when* on the week itself and names the date after: a click on
  // an empty hour marks a slot an hour long, a grip at either end moves that
  // end's hour, and the block's own body opens the Add sheet on that day and
  // those hours. The date is posted and removed again, so the demo data is left
  // the way the seed had it.
  const mark = await freeHour(page);
  check('the week offers an empty hour to mark', mark !== null, mark ? clockTime(mark.start) : 'none');
  if (!mark) throw new Error('no empty hour on the week to mark');

  await page.mouse.click(mark.x, mark.y);
  await page.waitForTimeout(250);
  const marked = (await page.textContent('.wk-slot-time')).trim();
  let [markStart, markEnd] = slotSpan(marked);
  check(
    'clicking an empty hour marks a slot',
    markStart != null && markEnd != null,
    marked
  );
  check(
    'the marked slot runs the hour that was clicked',
    markStart === mark.start && markEnd === mark.start + 60,
    `${marked} from a click at ${clockTime(mark.start)}`
  );

  // The bottom end is dragged two hours down; the start must not move with it.
  const slotBox = await (await page.$('.wk-slot')).boundingBox();
  await page.mouse.move(slotBox.x + slotBox.width / 2, slotBox.y + slotBox.height - 1);
  await page.mouse.down();
  await page.mouse.move(
    slotBox.x + slotBox.width / 2,
    slotBox.y + slotBox.height - 1 + 2 * WEEK_HOUR_H,
    { steps: 10 }
  );
  await page.mouse.up();
  await page.waitForTimeout(250);
  const dragged = (await page.textContent('.wk-slot-time')).trim();
  const [endStart, endEnd] = slotSpan(dragged);
  check(
    'dragging the bottom edge moves the end time alone',
    endStart === markStart && endEnd === markEnd + 120,
    `${marked} -> ${dragged}`
  );
  check('a drag leaves one slot behind, not two', (await page.$$eval('.wk-slot', (n) => n.length)) === 1);

  // And the top end one hour up, leaving the end where the last drag put it.
  const slotBox2 = await (await page.$('.wk-slot')).boundingBox();
  await page.mouse.move(slotBox2.x + slotBox2.width / 2, slotBox2.y + 1);
  await page.mouse.down();
  await page.mouse.move(slotBox2.x + slotBox2.width / 2, slotBox2.y + 1 - WEEK_HOUR_H, { steps: 10 });
  await page.mouse.up();
  await page.waitForTimeout(250);
  const dragged2 = (await page.textContent('.wk-slot-time')).trim();
  const [topStart, topEnd] = slotSpan(dragged2);
  check(
    'dragging the top edge moves the start time alone',
    topStart === endStart - 60 && topEnd === endEnd,
    `${dragged} -> ${dragged2}`
  );

  /* The block's own body carries it: the whole span slides to another hour with
     its length kept, and across to another day without losing it. Every carry
     here is answered with the opposite one, so the block is back on the day it
     was marked on when the Add sheet below opens on it. */
  const carry = async (dx, dy) => {
    const box = await (await page.$('.wk-slot')).boundingBox();
    const fromX = box.x + box.width / 2;
    const fromY = box.y + box.height / 2;
    await page.mouse.move(fromX, fromY);
    await page.mouse.down();
    await page.mouse.move(fromX + dx, fromY + dy, { steps: 12 });
    await page.mouse.up();
    await page.waitForTimeout(250);
    return (await page.textContent('.wk-slot-time')).trim();
  };

  /** The column the block is drawn in, 0–6 — the day it now sits on. */
  const slotCol = () =>
    page.evaluate(() => {
      const slot = document.querySelector('.wk-slot');
      if (!slot) return -1;
      const box = slot.getBoundingClientRect();
      const x = box.left + box.width / 2;
      return [...document.querySelectorAll('.wk-col')].findIndex((c) => {
        const r = c.getBoundingClientRect();
        return x >= r.left && x < r.right;
      });
    });

  const carriedDown = await carry(0, 2 * WEEK_HOUR_H);
  const [moveStart, moveEnd] = slotSpan(carriedDown);
  check(
    'dragging the block by its body slides it to another hour',
    moveStart === topStart + 120 && moveEnd === topEnd + 120,
    `${dragged2} -> ${carriedDown}`
  );
  check('and the block keeps its length while it is carried', moveEnd - moveStart === topEnd - topStart);

  const carriedBack = await carry(0, -2 * WEEK_HOUR_H);
  const [backStart, backEnd] = slotSpan(carriedBack);
  check(
    'carrying it back puts the hours where they were',
    backStart === topStart && backEnd === topEnd,
    `${carriedDown} -> ${carriedBack}`
  );

  // A column's width is what a carry has to travel to land on the next day.
  const colStep = await page.evaluate(() => {
    const cols = [...document.querySelectorAll('.wk-col')].map((c) => c.getBoundingClientRect());
    return cols[1].left - cols[0].left;
  });
  const markedCol = await slotCol();
  const carriedOver = await carry(colStep, 0);
  const overCol = await slotCol();
  check(
    'a block carried onto another column lands on that day',
    markedCol >= 0 && overCol === markedCol + 1,
    `column ${markedCol} -> ${overCol}`
  );
  check(
    'and it carries its own hours across, unchanged',
    carriedOver === dragged2,
    `${dragged2} -> ${carriedOver}`
  );
  check('the carry leaves one slot behind, not two', (await page.$$eval('.wk-slot', (n) => n.length)) === 1);
  await carry(-colStep, 0);
  // Past the window in which a carry swallows the click that ends it, so the
  // body below is a body at rest.
  await page.waitForTimeout(400);
  check(
    'carrying it back returns it to the day it was marked on',
    (await slotCol()) === markedCol,
    `column ${await slotCol()} vs ${markedCol}`
  );
  check('a carry never opens the sheet', !(await page.$('.sheet.event-sheet')));

  // The slot is the way in to the Add sheet, and it takes its own day with it.
  await page.click('.wk-slot-body');
  await page.waitForSelector('.sheet.event-sheet', { timeout: 5000 });
  check('the slot opens the Add sheet', (await page.$('#add-event-title')) !== null);
  const sheetFrom = await page.inputValue('#ev-from');
  const sheetTo = await page.inputValue('#ev-to');
  check(
    'the sheet opens on the slot\u2019s hours',
    toMinutes(sheetFrom) === topStart && toMinutes(sheetTo) === topEnd,
    `${sheetFrom}\u2013${sheetTo} vs ${dragged2}`
  );
  const markedDay = new Date(`${await page.getAttribute('.cal-editor', 'data-week')}T12:00:00Z`);
  markedDay.setUTCDate(markedDay.getUTCDate() + mark.col);
  check(
    'the sheet opens on the day the slot was marked on',
    (await page.inputValue('#ev-date')) === markedDay.toISOString().slice(0, 10),
    `${await page.inputValue('#ev-date')} vs ${markedDay.toISOString().slice(0, 10)} (column ${mark.col})`
  );

  const slotTitle = `Marked on the week ${Date.now() % 100000}`;
  await page.fill('.event-sheet input >> nth=0', slotTitle);
  await page.click('.event-sheet button:has-text("Add event")');
  await page.waitForTimeout(1400);
  check('the slot goes once its date is posted', (await page.$('.wk-slot')) === null);
  check(
    'the posted slot draws as a block on the week',
    (await page.$$eval('.wk-chip', (c) => c.map((x) => x.innerText.replace(/\s+/g, ' ')))).some(
      (t) => t.includes(slotTitle)
    )
  );
  // The hours the drag left are the hours the date was written with, read back
  // off the API rather than off a clock the app may print another way.
  const written = (
    (await (await fetch(`${API}/api/tracks/221-mx`)).json())?.data?.track?.events ?? []
  ).find((e) => e.title === slotTitle);
  check(
    'the dragged hours are the hours the posted date carries',
    !!written && written.startMinutes === topStart && written.endMinutes === topEnd,
    written ? `${written.startMinutes}\u2013${written.endMinutes} vs ${topStart}\u2013${topEnd}` : 'not found'
  );

  // Remove it through its card, the way the suite removes every date it posts.
  const slotCards = await page.$$('.event-editor .event-edit-row:not(.new)');
  let slotCard = null;
  for (const r of slotCards) {
    const v = await r.$eval('.event-card-title', (t) => t.textContent.trim());
    if (v === slotTitle) slotCard = r;
  }
  if (slotCard) {
    await slotCard.$eval('.event-open', (b) => b.click());
    await page.waitForSelector('.sheet.event-sheet', { timeout: 5000 });
    await page.click('.event-sheet button:has-text("Remove")');
    await page.waitForSelector('.confirm-sheet', { timeout: 5000 });
    await page.click('.confirm-sheet button.primary.danger');
    await page.waitForTimeout(1200);
  }
  check(
    'the marked date is removed again',
    !(await page.$$eval('.event-card-title', (t) => t.map((x) => x.textContent.trim()))).includes(slotTitle)
  );

  // Escape asks before a marked slot goes, the way every other gesture that
  // would drop one does: the question is put up with the draft still on the
  // week, and only Discard takes the hours away.
  const again = await freeHour(page);
  await page.mouse.click(again.x, again.y);
  await page.waitForTimeout(250);
  check('the week can be marked again once the date is posted', (await page.$('.wk-slot')) !== null);
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);
  check(
    'Escape asks before the marked slot is dropped',
    !!(await page.$('.confirm-sheet')) && !!(await page.$('.wk-slot')),
    (await page.$('.confirm-sheet')) ? 'the question is up with the draft still marked' : 'no question'
  );
  await page.click('.confirm-sheet button.primary.danger');
  await page.waitForTimeout(300);
  check('and Discard puts the marked slot down', (await page.$('.wk-slot')) === null);
  check('the question goes with it', !(await page.$('.confirm-sheet')));

  await page.goto(`${BASE}/tracks/221-mx`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.event-cal', { timeout: 10000 });
  const titlesNow = (await pagesInMonth(page, newKey)).flat();
  check('the removed event is gone from the public profile', !titlesNow.includes(newEvent), titlesNow.join(' | ').slice(0, 120));

  // Put the profile copy back the way the seed left it — the words this run read
  // off the API before it started editing.
  await page.goto(`${BASE}/operator/profile`, { waitUntil: 'networkidle' });
  await page.waitForSelector('textarea', { timeout: 15000 });
  await page.fill('textarea', seededDescription);
  await page.fill('.week-editor input >> nth=0', seededWeek.mon);
  await page.selectOption('select[aria-label="Status"]', 'OPEN');
  await page.click('button:has-text("Save profile")');
  await page.waitForSelector('.banner.ok', { timeout: 10000 });
  await page.waitForTimeout(600);
  await page.screenshot({ path: 'profile-console.png', fullPage: true });

  // ---- An admin gets a venue picker on the same console ------------------
  await login(page, 'admin@motopass.example.com');
  await page.goto(`${BASE}/operator/profile`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.profile-console', { timeout: 15000 });
  const options = await page.$$eval('select option', (o) => o.map((x) => x.textContent.trim()));
  check('an admin picks the venue to edit', options.length >= NET, `${options.length} options`);
  check('the admin console previews the picked venue', (await page.$('.profile-preview')) !== null);

  // The calendar page carries the same picker, so an admin writes a venue's
  // season the same way it edits its profile.
  await page.goto(`${BASE}/operator/calendar`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.cal-editor', { timeout: 15000 });
  const calOptions = await page.$$eval('select option', (o) => o.map((x) => x.textContent.trim()));
  check('an admin picks the venue on the calendar page too', calOptions.length >= NET, `${calOptions.length} options`);

  // ---- The venue's community --------------------------------------------
  // The operator reads who follows the venue — now the venue's community: the
  // pass each member holds, how much they have ridden here, and the photos
  // riders have shared from the track. Every number below is read off the page
  // and checked against another number on it, so the seed's follow list can
  // change without pinning a count here.
  //
  // The page is paused for now (COMMUNITY_ENABLED in web/src/lib/featureFlags.ts):
  // the tab is out of both navs and a straight URL lands on the dashboard, so
  // while it is off the checks below become the pause's checks instead. Flip the
  // flag to true and the member table and the wall come back as they were.
  if (!COMMUNITY_ENABLED) {
    const adminNav = await page.$$eval('header nav a', (a) => a.map((x) => x.textContent.trim()));
    check('a paused community page is out of the admin nav', !adminNav.includes('Community'), adminNav.join(' | '));
    await page.goto(`${BASE}/operator/community`, { waitUntil: 'networkidle' });
    check('a paused community page lands an admin on the dashboard', page.url().includes('/operator/dashboard'), page.url());

    await login(page, 'ops@221mx.example.com');
    const pausedNav = await page.$$eval('header nav a', (a) => a.map((x) => x.textContent.trim()));
    check('a paused community page is out of the operator nav', !pausedNav.includes('Community'), pausedNav.join(' | '));
    await page.goto(`${BASE}/operator/followers`, { waitUntil: 'networkidle' });
    check('the old followers path lands on the dashboard while paused', page.url().includes('/operator/dashboard'), page.url());
    console.log('  community page is paused (COMMUNITY_ENABLED = false) — the member table and photo wall checks are skipped');
  } else {
    await page.goto(`${BASE}/operator/community`, { waitUntil: 'networkidle' });
    await page.waitForSelector('.community-page', { timeout: 15000 });
    const folOptions = await page.$$eval('.community-page select option', (o) => o.length);
    check('an admin picks the venue on the community page too', folOptions >= NET, `${folOptions} options`);

    await login(page, 'ops@221mx.example.com');
    await page.goto(`${BASE}/operator/community`, { waitUntil: 'networkidle' });
    await page.waitForSelector('.community-page', { timeout: 15000 });
    const folHead = (await page.textContent('.community-page h1')).trim();
    check('the operator page is the venue\u2019s community', folHead === 'Community', folHead);
    check('the operator gets no venue picker on the community page', (await page.$('.community-page select')) === null);
    const folNav = await page.$$eval('header nav a', (a) => a.map((x) => x.textContent.trim()));
    check('the operator\u2019s nav offers the community page', folNav.includes('Community'), folNav.join(' | '));
    check('the old followers path lands on the community', page.url().includes('/operator/community'), page.url());

    // The pills carry the totals, and each one cuts the table to exactly that many
    // riders — a pill that miscounts, or a cut that does not cut, is the failure.
    const pillCount = async (label) =>
      Number(((await page.textContent(`.pill-toggle button:has-text("${label}")`)) ?? '').replace(/\D+/g, ''));
    const rowsShown = () => page.$$eval('.community-page tbody tr:not(:has(td[colspan]))', (r) => r.length);
    const folAll = await pillCount('All');
    const folPaying = await pillCount('Paying');
    const folFree = await pillCount('Free');
    check('the community split into paying and free adds up', folPaying + folFree === folAll, `${folPaying} + ${folFree} vs ${folAll}`);
    check('the All pill counts every row the page shows', (await rowsShown()) === folAll, `${await rowsShown()} vs ${folAll}`);

    await page.click('.pill-toggle button:has-text("Paying")');
    await page.waitForTimeout(200);
    check('the Paying pill cuts the table to the paying riders', (await rowsShown()) === folPaying);
    await page.click('.pill-toggle button:has-text("All")');
    await page.waitForTimeout(200);
    check('All puts the whole community back', (await rowsShown()) === folAll);

    // A row reads as a rider: a name with the account it belongs to, a home town,
    // and a pass — the tier they ride on, a status when it is not active, or free.
    if (folAll > 0) {
      const folRow = (await page.textContent('.community-page tbody tr')).replace(/\s+/g, ' ').trim();
      check('a community row names the rider and the account', /@/.test(folRow), folRow.slice(0, 90));
    } else {
      check('a community of nobody says so', /No riders in this community/.test(await page.textContent('.community-page tbody')));
    }

    // ---- The riders' photo wall --------------------------------------------
    // The photos riders share from the track, read on the venue's own console.
    const wall = await page.$$eval('.community-wall-grid li', (li) =>
      li.map((l) => ({
        hasShot: !!l.querySelector('img'),
        by: (l.querySelector('.community-wall-by')?.textContent ?? '').replace(/\s+/g, ' ').trim(),
        caption: (l.querySelector('.community-wall-caption')?.textContent ?? '').trim(),
        removable: !!l.querySelector('.community-wall-remove'),
      }))
    );
    const wallCount = Number(
      ((await page.textContent('.community-wall .section-head .muted')) ?? '').replace(/\D+/g, '')
    );
    check('the community page lists the riders\u2019 photos', wall.length === wallCount, `${wall.length} cards vs ${wallCount}`);
    check('every wall card is a photographed frame', wall.length > 0 && wall.every((w) => w.hasShot), JSON.stringify(wall.slice(0, 2)));
    check('a wall card names who posted it', wall.every((w) => /[A-Za-z]/.test(w.by)), JSON.stringify(wall[0] ?? null));
    check('a shared photo carries its caption', wall.some((w) => w.caption.length > 0));
    check('the venue may take a rider photo down', wall.every((w) => w.removable));
  }

  check('no JS errors on either surface', errors.length === 0, errors.join(' | '));

  await browser.close();
  console.log(`\n${fails === 0 ? 'ALL PROFILE CHECKS PASSED' : `${fails} PROFILE CHECK(S) FAILED`}`);
  process.exit(fails === 0 ? 0 : 1);
}

main().catch((e) => {
  console.error('harness error:', e);
  process.exit(1);
});

