/* Headless verification of column sorting, across every table in the app.
 *
 * For each table on each page it walks every sortable header and asserts that
 * clicking it permutes the rows without losing any, that a second click flips
 * the direction, and that aria-sort reports the state for assistive tech. When
 * the displayed values explain the order on their own it also asserts the exact
 * reversal, and when every value parses as a distinct number it asserts the
 * order is numeric rather than text. Columns whose sort key is not what the
 * cell shows (a count shown inside a sentence) are judged on the first two
 * properties only.
 *
 *   cd web && npm run verify:sorting     (dev server on :5180)
 *
 * Uses playwright-core with an explicit browser path so it works with the
 * browsers already in ~/.cache/ms-playwright and downloads nothing.
 */
const fs = require('fs');
const path = require('path');
const os = require('os');
const { chromium } = require('playwright-core');

const BASE = process.env.SORT_BASE || 'http://localhost:5180';
const PASSWORD = 'dialed123';

const PAGES = [
  // /tracks is the network page and carries no table on purpose — perks are
  // cards there, the per-track surface is day rows. The first entry is signed
  // out on purpose: the page is public. Only the pages below that own a table
  // are asserted.
  { url: '/tracks', name: 'network page', noTable: true, waitFor: '.day-grid' },
  { url: '/tracks/history', name: 'rider history', login: 'alex@example.com' },
  { url: '/admin/users', name: 'admin users', login: 'admin@motopass.example.com' },
  { url: '/admin/tracks', name: 'admin tracks', login: 'admin@motopass.example.com' },
  { url: '/admin/tiers', name: 'admin tiers', login: 'admin@motopass.example.com' },
  { url: '/admin/reports', name: 'admin reports', login: 'admin@motopass.example.com' },
  { url: '/admin/quickbooks', name: 'quickbooks preview', login: 'admin@motopass.example.com', preview: true },
  { url: '/operator/dashboard', name: 'operator dashboard', login: 'ops@221mx.example.com' },
];

function findBrowser() {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  if (!fs.existsSync(root)) return null;
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium_headless_shell-')) continue;
    const p = path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell');
    if (fs.existsSync(p)) return p;
    const alt = path.join(root, dir, 'chrome-linux', 'headless_shell');
    if (fs.existsSync(alt)) return alt;
  }
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium-')) continue;
    const p = path.join(root, dir, 'chrome-linux64', 'chrome');
    if (fs.existsSync(p)) return p;
  }
  return null;
}

let fails = 0;
let checks = 0;
function check(label, ok, detail = '') {
  checks++;
  if (!ok) fails++;
  console.log(`${ok ? 'OK  ' : 'FAIL'}  ${label}${detail ? ` — ${detail}` : ''}`);
}

/** Numbers, so currency and +N compare as values. Null when not all numeric. */
function asNumbers(values) {
  const nums = [];
  for (const v of values) {
    const m = /^[+]?\$?([\d,]+(?:\.\d+)?)%?$/.exec(v.replace(/\s/g, ''));
    if (!m) return null;
    nums.push(Number(m[1].replace(/,/g, '')));
  }
  return nums;
}

function cmp(a, b) {
  const [na, nb] = [asNumbers([a]), asNumbers([b])];
  if (na && nb) return na[0] - nb[0];
  return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
}

/** True when the displayed values alone explain a strict order. */
function strictlyOrdered(values) {
  return values.every((v, i) => i === 0 || cmp(values[i - 1], v) < 0);
}

async function login(page, email) {
  await page.goto(`${BASE}/login`, { waitUntil: 'networkidle' });
  await page.waitForSelector('form #email');
  await page.fill('#email', email);
  await page.fill('#password', PASSWORD);
  await Promise.all([
    page.waitForURL((u) => !u.pathname.startsWith('/login'), { timeout: 20000 }),
    page.click('form button.primary'),
  ]);
}

const sameRows = (a, b) => a.join('\u0000') === b.join('\u0000');

async function main() {
  const exe = findBrowser();
  if (!exe) {
    console.error('No Playwright Chromium found in ~/.cache/ms-playwright.');
    process.exit(1);
  }
  const browser = await chromium.launch({ executablePath: exe });
  const errors = [];

  for (const spec of PAGES) {
    // A fresh context per page: /login redirects away when already signed in.
    const ctx = await browser.newContext({ viewport: { width: 1440, height: 1000 } });
    const page = await ctx.newPage();
    page.on('pageerror', (e) => errors.push(`${spec.name}: ${e.message}`));

    if (spec.login) await login(page, spec.login);
    await page.goto(`${BASE}${spec.url}`, { waitUntil: 'networkidle' });
    if (spec.preview) {
      await page.waitForSelector('button:has-text("Preview")', { timeout: 15000 });
      await page.click('button:has-text("Preview")');
      await page.waitForSelector('table tbody tr', { timeout: 15000 });
    }
    if (spec.waitFor) await page.waitForSelector(spec.waitFor, { timeout: 15000 }).catch(() => {});
    else await page.waitForSelector('table', { timeout: 15000 }).catch(() => {});
    await page.waitForTimeout(400);

    const tables = await page.$$('table');
    if (!tables.length) {
      if (spec.noTable) {
        check(`${spec.name}: no table to sort (rows, as designed)`, true);
        await ctx.close();
        continue;
      }
      check(`${spec.name}: renders a table`, false, 'no table');
      await ctx.close();
      continue;
    }
    if (spec.noTable) {
      check(`${spec.name}: stays tableless`, false, `found ${tables.length} table(s)`);
    }

    for (let ti = 0; ti < tables.length; ti++) {
      const btns = await tables[ti].$$('thead th .sort-btn');
      const rowCount = await tables[ti].$$eval('tbody tr', (r) => r.length);
      if (!btns.length) {
        check(`${spec.name} table ${ti + 1}: exposes sortable headers`, false, `${rowCount} rows, 0 sortable`);
        continue;
      }

      for (let bi = 0; bi < btns.length; bi++) {
        const label = await btns[bi].evaluate((el) => el.textContent.trim());
        const col = await btns[bi].evaluate((el) => [...el.closest('tr').children].indexOf(el.closest('th')));
        const read = () =>
          tables[ti].$$eval(
            'tbody tr',
            (rows, ci) =>
              rows.map((r) => ({
                key: [...r.children].map((c) => c.textContent.trim()).join('|'),
                value: (r.children[ci]?.textContent || '').trim(),
              })),
            col
          );

        const base = await read();
        if (base.length < 2) continue;
        const baseKeys = base.map((r) => r.key).sort();

        await btns[bi].click();
        await page.waitForTimeout(120);
        const asc = await read();
        const ariaAsc = await btns[bi].evaluate((el) => el.closest('th').getAttribute('aria-sort'));

        await btns[bi].click();
        await page.waitForTimeout(120);
        const desc = await read();
        const ariaDesc = await btns[bi].evaluate((el) => el.closest('th').getAttribute('aria-sort'));

        const where = `${spec.name} › ${label}`;
        const ascVals = asc.map((r) => r.value);
        const descVals = desc.map((r) => r.value);
        const reasons = [];

        if (!sameRows(asc.map((r) => r.key).sort(), baseKeys) || !sameRows(desc.map((r) => r.key).sort(), baseKeys)) {
          reasons.push('row set changed');
        }
        if (ariaAsc !== 'ascending' || ariaDesc !== 'descending') reasons.push(`aria ${ariaAsc}/${ariaDesc}`);

        if (strictlyOrdered(ascVals)) {
          if (!sameRows(descVals, ascVals.slice().reverse())) reasons.push('direction did not flip');
        } else if (strictlyOrdered(descVals)) {
          if (!sameRows(ascVals, descVals.slice().reverse())) reasons.push('direction did not flip');
        }

        const nums = asNumbers(ascVals);
        if (nums && new Set(nums).size === nums.length) {
          const ascOk = nums.every((n, i) => i === 0 || nums[i - 1] < n);
          const descNums = asNumbers(descVals) ?? [];
          const descOk =
            descNums.length === nums.length && descNums.every((n, i) => i === 0 || descNums[i - 1] > n);
          if (!ascOk || !descOk) reasons.push('numeric order wrong');
        }

        check(
          `${where}: sorts both ways, ${base.length} rows`,
          reasons.length === 0,
          reasons.length ? `${reasons.join('; ')} — ${ascVals.join(', ')}` : ''
        );
      }
    }

    await ctx.close();
  }

  check('no JS errors while sorting', errors.length === 0, errors.slice(0, 3).join(' | '));

  await browser.close();
  console.log(`\n${fails === 0 ? `ALL ${checks} SORTING CHECKS PASSED` : `${fails} of ${checks} SORTING CHECK(S) FAILED`}`);
  process.exit(fails === 0 ? 0 : 1);
}

main().catch((e) => {
  console.error('harness error:', e);
  process.exit(1);
});

import { Navigate, Route, Routes, useLocation } from 'react-router-dom';
import { ReactNode } from 'react';
import { useAuth, homePathFor, Role } from './lib/auth';
import { COMMUNITY_ENABLED } from './lib/featureFlags';
import Layout from './components/Layout';
import Landing from './pages/Landing';
import Pricing from './pages/Pricing';
import TrackProfile from './pages/TrackProfile';
import Login from './pages/Login';
import Privacy from './pages/Privacy';
import Terms from './pages/Terms';
import RiderHome from './pages/rider/RiderHome';
import RiderHistory from './pages/rider/RiderHistory';
import RiderPerks from './pages/rider/RiderPerks';
import RiderCalendar from './pages/rider/RiderCalendar';
import UserProfile from './pages/user/UserProfile';
import OperatorDashboard from './pages/operator/OperatorDashboard';
import OperatorReports from './pages/operator/OperatorReports';
import OperatorProfile from './pages/operator/OperatorProfile';
import OperatorCalendar from './pages/operator/OperatorCalendar';
import OperatorCommunity from './pages/operator/OperatorCommunity';
import AdminHome from './pages/admin/AdminHome';
import AdminTracks from './pages/admin/AdminTracks';
import AdminUsers from './pages/admin/AdminUsers';
import AdminTiers from './pages/admin/AdminTiers';
import AdminReports from './pages/admin/AdminReports';
import AdminQuickBooks from './pages/admin/AdminQuickBooks';

function Guard({ roles, children }: { roles: Role[]; children: ReactNode }) {
  const { user, loading } = useAuth();
  const location = useLocation();
  if (loading) return <div className="muted" style={{ padding: 24 }}>Loading…</div>;
  if (!user) return <Navigate to="/login" state={{ from: location.pathname }} replace />;
  if (!roles.includes(user.role)) return <Navigate to={homePathFor(user.role)} replace />;
  return <>{children}</>;
}

/**
 * The marketing homepage at `/`. It belongs to visitors: a signed-out reader
 * gets the public landing, and a signed-in account is sent to its own home,
 * `/tracks` — the network page, which serves every role and reads the same for
 * a rider, an operator or an admin. The header's brand link points here, so it
 * still lands a signed-in reader somewhere real rather than back on the sales
 * copy.
 */
function Home() {
  const { user, loading } = useAuth();
  // Gate on the /auth/me read: rendering Landing while it resolves would flash
  // the marketing page at a signed-in visitor for a frame.
  if (loading) return null;
  // An operator's home is the dashboard, not the network page.
  if (user) return <Navigate to={user.role === 'OPERATOR' ? '/operator/dashboard' : '/tracks'} replace />;
  return <Landing />;
}

/**
 * The rider portal used to live under `/rider`; the network page is `/tracks`
 * now, so every old link lands on its new home: `/rider` → `/tracks`,
 * `/rider/history` → `/tracks/history`, and so on.
 */
function RiderRedirect() {
  const { pathname, search } = useLocation();
  return <Navigate to={pathname.replace(/^\/rider\b/, '/tracks') + search} replace />;
}

export default function App() {
  return (
    <Routes>
      <Route element={<Layout />}>
        <Route path="/" element={<Home />} />
        <Route path="/pricing" element={<Pricing />} />

        {/* The network page, for everyone: riders read their pass there, a
            visitor reads each venue's live status. */}
        <Route path="/tracks" element={<RiderHome />} />
        <Route path="/tracks/:slug" element={<TrackProfile />} />
        <Route path="/tracks/history" element={<Guard roles={['RIDER']}><RiderHistory /></Guard>} />
        {/* The rider's own calendar: the dates at the tracks they follow. Every
            rider gets it, free tier included — following is the free surface. */}
        <Route path="/tracks/calendar" element={<Guard roles={['RIDER']}><RiderCalendar /></Guard>} />
        <Route path="/tracks/perks" element={<Guard roles={['RIDER']}><RiderPerks /></Guard>} />

        {/* The rider's own profile — where the account menu's identity card lands. */}
        <Route path="/user" element={<Guard roles={['RIDER']}><UserProfile /></Guard>} />

        <Route path="/rider/*" element={<RiderRedirect />} />

        <Route path="/login" element={<Login />} />
        <Route path="/privacy" element={<Privacy />} />
        <Route path="/terms" element={<Terms />} />

        {/* The operator's home: the dashboard — the scanning station alone. */}
        <Route path="/operator/dashboard" element={<Guard roles={['OPERATOR', 'ADMIN']}><OperatorDashboard /></Guard>} />
        {/* The season's read and the activity log; split off the dashboard. */}
        <Route path="/operator/reports" element={<Guard roles={['OPERATOR', 'ADMIN']}><OperatorReports /></Guard>} />
        <Route path="/operator/profile" element={<Guard roles={['OPERATOR', 'ADMIN']}><OperatorProfile /></Guard>} />
        {/* Where the season is written; the profile page only reads it. */}
        <Route path="/operator/calendar" element={<Guard roles={['OPERATOR', 'ADMIN']}><OperatorCalendar /></Guard>} />
        {/* The venue's community — who rides here, and the photos they post.
            Paused: see COMMUNITY_ENABLED in lib/featureFlags.ts. A straight URL
            lands on the dashboard while it is off, so nothing dead-links. */}
        <Route
          path="/operator/community"
          element={
            COMMUNITY_ENABLED ? (
              <Guard roles={['OPERATOR', 'ADMIN']}><OperatorCommunity /></Guard>
            ) : (
              <Navigate to="/operator/dashboard" replace />
            )
          }
        />
        {/* The page was the followers view; old links land on the community. */}
        <Route
          path="/operator/followers"
          element={<Navigate to={COMMUNITY_ENABLED ? '/operator/community' : '/operator/dashboard'} replace />}
        />
        {/* The scanning station lived at /scan (and at /operator before that),
            so both land on the dashboard; the log has its own page again. */}
        <Route path="/scan" element={<Navigate to="/operator/dashboard" replace />} />
        <Route path="/operator" element={<Navigate to="/operator/dashboard" replace />} />
        <Route path="/operator/log" element={<Navigate to="/operator/reports" replace />} />

        <Route path="/admin" element={<Guard roles={['ADMIN']}><AdminHome /></Guard>} />
        <Route path="/admin/tracks" element={<Guard roles={['ADMIN']}><AdminTracks /></Guard>} />
        <Route path="/admin/users" element={<Guard roles={['ADMIN']}><AdminUsers /></Guard>} />
        <Route path="/admin/tiers" element={<Guard roles={['ADMIN']}><AdminTiers /></Guard>} />
        <Route path="/admin/reports" element={<Guard roles={['ADMIN']}><AdminReports /></Guard>} />
        <Route path="/admin/quickbooks" element={<Guard roles={['ADMIN']}><AdminQuickBooks /></Guard>} />

        <Route path="*" element={<div className="card">Not found.</div>} />
      </Route>
    </Routes>
  );
}

import { useEffect, useRef, useState } from 'react';

/**
 * TEMPORARY — accent colour picker.
 *
 * A throwaway floating control for trying out accents. It overrides the
 * `--accent` / `--accent-rgb` tokens on :root, so the whole app (buttons,
 * pills, meters, the map pins) recolours at once. The choice persists in
 * localStorage so it survives a reload while auditioning.
 *
 * Remove this file + its `.accent-switch*` SCSS block + the <AccentSwitcher />
 * line in Layout.tsx to take it back out.
 */

/**
 * TEMPORARY: the accent switcher is hidden. With `false` the component mounts
 * nothing — no floating button, no menu, no stored accent applied, so the app
 * sits on its real `--accent` token. Flip it to `true` to bring the picker
 * back exactly as it was; nothing else in this file, its `.accent-switch*`
 * SCSS block or the `<AccentSwitcher />` line in Layout.tsx has changed.
 */
const ACCENT_SWITCH_ENABLED = false;

type Preset = { key: string; label: string; accent: string };

/** The chosen accent is orange; index 0 is the app's real palette + reset. */
const PRESETS: Preset[] = [
  { key: 'orange', label: 'Orange', accent: '#ff8a3f' },
  { key: 'tangerine', label: 'Tangerine', accent: '#ff9f2e' },
  { key: 'pumpkin', label: 'Pumpkin', accent: '#ff7a1a' },
  { key: 'burnt', label: 'Burnt', accent: '#ff6b2c' },
  { key: 'amber', label: 'Amber', accent: '#ffb347' },
  { key: 'sunset', label: 'Sunset', accent: '#ff8c42' },
  { key: 'coral', label: 'Coral', accent: '#ff7043' },
  { key: 'copper', label: 'Copper', accent: '#e07b39' },
  { key: 'apricot', label: 'Apricot', accent: '#ffb27f' },
  { key: 'persimmon', label: 'Persimmon', accent: '#ff5e1a' },
];

const STORE_KEY = 'motopass.accent';
const DEFAULT_KEY = PRESETS[0].key;

/** '#d6ff3f' -> '214, 255, 63' for the soft-tint rgb() usages. */
function rgbTriple(hex: string): string {
  const h = hex.replace('#', '');
  const n = parseInt(h, 16);
  return `${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}`;
}

function apply(preset: Preset) {
  const root = document.documentElement;
  root.style.setProperty('--accent', preset.accent);
  root.style.setProperty('--accent-rgb', rgbTriple(preset.accent));
}

export default function AccentSwitcher() {
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(DEFAULT_KEY);
  const box = useRef<HTMLDivElement>(null);

  // Apply the stored choice on mount (before paint where possible).
  useEffect(() => {
    // TEMPORARY: hidden, not deleted — see ACCENT_SWITCH_ENABLED above.
    if (!ACCENT_SWITCH_ENABLED) return;
    const saved = localStorage.getItem(STORE_KEY);
    const preset = PRESETS.find((p) => p.key === saved) ?? PRESETS[0];
    setActive(preset.key);
    apply(preset);
  }, []);

  // Close on a click outside or Escape.
  useEffect(() => {
    if (!open) return;
    const onDown = (e: MouseEvent) => {
      if (box.current && !box.current.contains(e.target as Node)) setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setOpen(false);
    };
    document.addEventListener('mousedown', onDown);
    document.addEventListener('keydown', onKey);
    return () => {
      document.removeEventListener('mousedown', onDown);
      document.removeEventListener('keydown', onKey);
    };
  }, [open]);

  const pick = (preset: Preset) => {
    setActive(preset.key);
    apply(preset);
    try {
      if (preset.key === DEFAULT_KEY) localStorage.removeItem(STORE_KEY);
      else localStorage.setItem(STORE_KEY, preset.key);
    } catch {
      /* private mode — the choice just won't persist */
    }
  };

  const current = PRESETS.find((p) => p.key === active) ?? PRESETS[0];

  // TEMPORARY: renders nothing while the flag is off.
  if (!ACCENT_SWITCH_ENABLED) return null;

  return (
    <div className="accent-switch" ref={box}>
      {open && (
        <div className="accent-menu" role="menu" aria-label="Accent colour">
          <div className="accent-menu-head">
            <span>Accent colour</span>
            <span className="accent-menu-tag">temporary</span>
          </div>
          {PRESETS.map((p) => (
            <button
              key={p.key}
              type="button"
              role="menuitemradio"
              aria-checked={p.key === active}
              className={`accent-opt${p.key === active ? ' on' : ''}`}
              onClick={() => pick(p)}
            >
              <span className="accent-dots">
                <span className="accent-dot" style={{ background: p.accent }} />
              </span>
              {p.label}
            </button>
          ))}
        </div>
      )}
      <button
        type="button"
        className="accent-switch-btn"
        aria-haspopup="menu"
        aria-expanded={open}
        aria-label="Accent colour"
        title="Accent colour (temporary)"
        onClick={() => setOpen((v) => !v)}
      >
        <span className="accent-dot" style={{ background: current.accent }} />
      </button>
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import Avatar from './Avatar';
import PassQrSheet from './PassQrSheet';
import { api, dayStr } from '../lib/api';
import { useAuth } from '../lib/auth';

const SUPPORT_EMAIL = 'support@motopass.example.com';

interface PassInfo {
  status: string;
  tier: { name: string; slug: string };
  expiresAt: string;
}

const ROLE_LABEL: Record<string, string> = {
  OPERATOR: 'Scanning station',
  ADMIN: 'Organiser',
  RIDER: 'Rider',
};

/**
 * The signed-in identity in the top bar: a round portrait that opens the
 * account menu — the pass itself (photo, live QR, validity), Help and Sign out.
 * The pass is only fetched once the menu is opened.
 */
export default function AccountMenu() {
  const { user, operatorTrack, logout } = useAuth();
  const navigate = useNavigate();
  const [open, setOpen] = useState(false);
  const [pass, setPass] = useState<PassInfo | null>(null);
  const [qrOpen, setQrOpen] = useState(false);
  const wrap = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open || user?.role !== 'RIDER') return;
    api.get<{ pass: PassInfo | null }>('/me/pass').then((r) => setPass(r.data?.pass ?? null));
  }, [open, user]);

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setOpen(false);
    };
    const onDown = (e: MouseEvent) => {
      if (wrap.current && !wrap.current.contains(e.target as Node)) setOpen(false);
    };
    window.addEventListener('keydown', onKey);
    document.addEventListener('mousedown', onDown);
    return () => {
      window.removeEventListener('keydown', onKey);
      document.removeEventListener('mousedown', onDown);
    };
  }, [open]);

  if (!user) return null;

  const active = pass?.status === 'ACTIVE';
  const subtitle =
    user.role === 'RIDER' ? (pass?.tier.name ?? 'Rider') : (operatorTrack?.name ?? ROLE_LABEL[user.role] ?? user.role);

  /** Each role keeps its own profile page: the rider's, the venue console, the org console. */
  const profilePath =
    user.role === 'ADMIN' ? '/admin' : user.role === 'OPERATOR' ? '/operator/profile' : '/user';

  const signOut = async () => {
    setOpen(false);
    await logout();
    navigate('/');
  };

  return (
    <div className="acct-wrap" ref={wrap}>
      <button
        className="acct-btn"
        aria-haspopup="menu"
        aria-expanded={open}
        aria-label="Account menu"
        onClick={() => setOpen((o) => !o)}
      >
        <Avatar src={user.avatarUrl} name={user.name} className="acct-photo" />
      </button>

      {open && (
        <div className="acct-pop" role="menu" aria-label="Account">
          {/* The account's own profile, in the same compact card shape the rail
              gives a picked track: name + tier over the facts that identify it.
              The card is the link to that role's profile page. */}
          <Link className="profile-mini acct-profile" to={profilePath} onClick={() => setOpen(false)}>
            <div className="profile-mini-head">
              <span className="acct-profile-id">
                <Avatar src={user.avatarUrl} name={user.name} className="acct-profile-photo" />
                <span className="profile-mini-name">{user.name}</span>
              </span>
              <span className="row" style={{ gap: 6 }}>
                <span className="pass-id-tier">{subtitle}</span>
              </span>
            </div>

            <div className="profile-mini-hours">
              <span className="muted">Location</span>
              <b>{user.location || '—'}</b>
            </div>
          </Link>

          {user.role === 'RIDER' && (
            <div className="pass-id-inner">
              {pass ? (
                <>
                  <div className="pass-id-qr">
                    <button
                      className="primary pass-qr-btn"
                      onClick={() => {
                        setOpen(false);
                        setQrOpen(true);
                      }}
                    >
                      View QR Code
                    </button>
                  </div>
                  <div className="pass-id-foot">
                    <span>
                      Valid through <strong>{dayStr(pass.expiresAt)}</strong>
                      {!active && ` · ${pass.status.toLowerCase()}`}
                    </span>
                  </div>
                </>
              ) : (
                <span className="tiny muted">Loading your pass…</span>
              )}
            </div>
          )}

          <div className="acct-links">
            <a className="acct-link small" href={`mailto:${SUPPORT_EMAIL}`} onClick={() => setOpen(false)}>
              Help
            </a>
            <button className="ghost small acct-link" onClick={signOut}>
              Sign out
            </button>
          </div>
        </div>
      )}

      {qrOpen && pass && user.role === 'RIDER' && (
        <PassQrSheet
          active={active}
          expiresAt={pass.expiresAt}
          status={pass.status}
          onClose={() => setQrOpen(false)}
        />
      )}
    </div>
  );
}

import AvatarPattern from './AvatarPattern';

/** Holder photo, or a deterministic pixel pattern when the account has none on file. */
export default function Avatar({
  src,
  name,
  className,
}: {
  src?: string | null;
  name: string;
  className?: string;
}) {
  if (src) return <img className={className} src={src} alt={`${name} profile`} />;
  return (
    <div
      className={`${className ?? ''} avatar-fallback`}
      style={{ overflow: 'hidden' }}
      aria-label={`${name} profile`}
    >
      <AvatarPattern name={name} />
    </div>
  );
}

/**
 * Deterministic randomized pixel pattern — the default profile image for any
 * account with no photo on file. A horizontally mirrored 5x5 grid seeded from
 * the holder's name, so the same name always draws the same pattern while
 * different riders get different ones. Colors come from the app palette.
 */

const GRID = 5;
const SIZE = 100;
const CELL = SIZE / GRID;
const INSET = 1.5;
const RADIUS = 1.5;

const PALETTES = [
  { bg1: '#16242c', bg2: '#0d0f12', main: '#d6ff3f', hot: '#93ad2f' },
  { bg1: '#2d1519', bg2: '#0d0f12', main: '#ff5a5f', hot: '#ff8a8f' },
  { bg1: '#151f2f', bg2: '#0d0f12', main: '#4aa3ff', hot: '#7cc0ff' },
  { bg1: '#1b2a19', bg2: '#0d0f12', main: '#7bd85a', hot: '#a8e88c' },
  { bg1: '#2c2513', bg2: '#0d0f12', main: '#ffc63f', hot: '#ffe08a' },
  { bg1: '#251b2f', bg2: '#0d0f12', main: '#b479ff', hot: '#d3b0ff' },
  { bg1: '#132730', bg2: '#0d0f12', main: '#3fd6c4', hot: '#7ff0e2' },
  { bg1: '#2b1e15', bg2: '#0d0f12', main: '#ff8a3f', hot: '#ffb27f' },
  { bg1: '#1e2126', bg2: '#0d0f12', main: '#c9d1d9', hot: '#e6ebf0' },
];

function hash(str: string) {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h >>> 0;
}

// mulberry32
function rngFrom(seed: number) {
  let a = seed >>> 0;
  return function next() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export default function AvatarPattern({ name }: { name: string }) {
  const seed = hash(name || '—');
  const rnd = rngFrom(seed);
  const p = PALETTES[seed % PALETTES.length];

  const on: boolean[] = [];
  const hot: boolean[] = [];
  for (let row = 0; row < GRID; row++) {
    for (let col = 0; col < Math.ceil(GRID / 2); col++) {
      const filled = rnd() < 0.52;
      on[row * GRID + col] = filled;
      hot[row * GRID + col] = filled && rnd() < 0.3;
    }
  }
  for (let row = 0; row < GRID; row++) {
    for (let col = 0; col < Math.floor(GRID / 2); col++) {
      const src = row * GRID + (GRID - 1 - col);
      on[src] = on[row * GRID + col];
      hot[src] = hot[row * GRID + col];
    }
  }
  if (!on.some(Boolean)) on[Math.floor(rnd() * GRID) * GRID + 2] = true;

  const cells = [];
  for (let row = 0; row < GRID; row++) {
    for (let col = 0; col < GRID; col++) {
      const i = row * GRID + col;
      if (!on[i]) continue;
      cells.push(
        <rect
          key={i}
          x={col * CELL + INSET}
          y={row * CELL + INSET}
          width={CELL - INSET * 2}
          height={CELL - INSET * 2}
          rx={RADIUS}
          fill={hot[i] ? p.hot : p.main}
        />,
      );
    }
  }

  const gid = `av-${seed.toString(36)}`;
  return (
    <svg
      viewBox={`0 0 ${SIZE} ${SIZE}`}
      preserveAspectRatio="xMidYMid slice"
      style={{ width: '100%', height: '100%', display: 'block' }}
      aria-hidden="true"
    >
      <defs>
        <linearGradient id={gid} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor={p.bg1} />
          <stop offset="1" stopColor={p.bg2} />
        </linearGradient>
      </defs>
      <rect width={SIZE} height={SIZE} fill={`url(#${gid})`} />
      {cells}
    </svg>
  );
}

import { ReactNode, useEffect, useState } from 'react';

/** The exit animation's length (`toast-out` in global.scss). A floating notice
    runs it before it unmounts, so it fades down instead of blinking out. */
const EXIT_MS = 180;

/**
 * Notice banner. `close` adds a dismiss (×) button pinned to the right edge,
 * vertically centred; without it the banner is not dismissable.
 *
 * `floating` lifts the same banner out of the page flow into the bottom-right
 * toast layer, and `ms` retires it on its own after that many milliseconds
 * (dismiss by × does it sooner). Inline notices leave both off.
 *
 * `onDismiss` reports the ×, for a caller that owns the notice's lifetime (the
 * toast stack) instead of the banner's own `open` state.
 */
export default function Banner({
  tone = 'bare',
  small = true,
  close = false,
  floating = false,
  ms = 0,
  onDismiss,
  children,
}: {
  tone?: 'bare' | 'ok' | 'bad' | 'warn';
  small?: boolean;
  close?: boolean;
  floating?: boolean;
  ms?: number;
  onDismiss?: () => void;
  children: ReactNode;
}) {
  const [open, setOpen] = useState(true);
  const [closing, setClosing] = useState(false);

  // Retire on the timer by starting the exit, not by cutting the notice out.
  useEffect(() => {
    if (!open || !floating || ms <= 0) return;
    const timer = window.setTimeout(() => setClosing(true), ms);
    return () => window.clearTimeout(timer);
  }, [open, floating, ms]);

  // The exit runs for as long as the animation; then the notice is gone.
  useEffect(() => {
    if (!closing) return;
    const timer = window.setTimeout(() => setOpen(false), EXIT_MS);
    return () => window.clearTimeout(timer);
  }, [closing]);

  if (!open) return null;

  const notice = (
    <div
      className={`banner ${tone}${small ? ' small' : ''}${close ? ' closable' : ''}`}
    >
      <div className="banner-body">{children}</div>
      {close && (
        <button
          type="button"
          className="banner-x"
          aria-label="Dismiss"
          title="Dismiss"
          onClick={() => {
            // A caller that owns the lifetime animates it in its own layer.
            if (onDismiss) onDismiss();
            else setClosing(true);
          }}
        >
          {/* Drawn, not the × character: the font's glyph sits ~1px below the
              em-box centre, so the mark read low in its 22px button. Two lines
              in an SVG box centre geometrically, at any size. */}
          <svg viewBox="0 0 10 10" width="10" height="10" aria-hidden="true" focusable="false">
            <path
              d="M1.6 1.6 8.4 8.4M8.4 1.6 1.6 8.4"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.4"
              strokeLinecap="round"
            />
          </svg>
        </button>
      )}
    </div>
  );

  if (!floating) return notice;
  return (
    <div
      className={`toast${closing ? ' leaving' : ''}`}
      role="status"
      aria-live="polite"
    >
      {notice}
    </div>
  );
}

import { useEffect } from 'react';
import '../styles/cursor.scss';

/**
 * The site cursor, ported from the reference the user supplied (heronaiapp.com):
 * the native pointer stays exactly as it is and a canvas paints the layer around
 * it — a 6px accent square on the pointer, a faint tail that only gathers while
 * the pointer is actually moving, and a hairline square that desaturates what it
 * is over and snaps hollow on press.
 *
 * Off for coarse pointers and under `prefers-reduced-motion` (the reference's own
 * gate), and it is decoration: nothing here is needed to use the app.
 *
 * Mounted from main.tsx rather than Layout.tsx — it is a document-level effect
 * with no React state, and Layout is a hot file.
 */

/**
 * TEMPORARY: the site cursor is switched off. With `false` the layer never
 * mounts — no canvas, no hairline square, no listeners, the native pointer only.
 * Flip it to `true` to bring the cursor back exactly as it was; nothing else in
 * this file or cursor.scss changed.
 */
const CURSOR_ENABLED = false;

/** Samples kept for the tail. */
const TRAIL_LENGTH = 34;
/** Tail stroke width, in CSS px. */
const TRAIL_WIDTH = 1;
/** Side of the accent square on the pointer. */
const DOT_SIZE = 6;
/** Per-frame movement (px) below which the pointer counts as still. */
const TRAIL_MIN_MOVE = 0.05;
/** Per-frame speed (px) at which the tail reaches full strength. */
const TRAIL_MIN_SPEED = 1.5;
/** Anything nearer than this to its target is simply snapped onto it. */
const SNAP = 0.001;

/** How far each tracked value closes on its target per frame. */
const EASE = {
  position: 0.18,
  hover: 0.15,
  press: 0.2,
  visibility: 0.12,
};

const INTERACTIVE = [
  'a',
  'button',
  'input',
  'textarea',
  'select',
  '[role="button"]',
  '[data-cursor]:not([data-cursor="hidden"])',
].join(',');

const DARK_INK = '[data-cursor-theme="dark"]';
const HIDE = '[data-cursor="hidden"]';

/** Over a button the whole cursor reads fainter — see BUTTON_OPACITY. */
const BUTTON = 'button, [role="button"]';
/** What the cursor drops to at rest on a button. */
const BUTTON_OPACITY = 0.5;
/** What the cursor drops to while the button is down. */
const PRESS_OPACITY = 0.5;

/** The app's accent, or Moto Pass orange if the token reads empty. */
const ACCENT_FALLBACK = '#ff8a3f';

type Point = { x: number; y: number };
type Rgb = [number, number, number];

/** The reference's ease: a fixed fraction per frame with a snap floor. */
function approach(current: number, target: number, factor: number, snap = SNAP) {
  const next = current + (target - current) * factor;
  return Math.abs(target - next) <= snap ? target : next;
}

function hexToRgb(hex: string): Rgb {
  const v = /^#[0-9a-f]{6}$/i.test(hex) ? hex : ACCENT_FALLBACK;
  return [
    parseInt(v.slice(1, 3), 16),
    parseInt(v.slice(3, 5), 16),
    parseInt(v.slice(5, 7), 16),
  ];
}

/** Blend two rgb triples and print a canvas-ready colour. */
function mix(a: Rgb, b: Rgb, t: number) {
  const c = a.map((n, i) => Math.round(n + (b[i] - n) * t));
  return `rgb(${c[0]}, ${c[1]}, ${c[2]})`;
}

class CursorLayer {
  private canvas: HTMLCanvasElement | null = null;
  private hoverSquare: HTMLDivElement | null = null;
  private ctx: CanvasRenderingContext2D | null = null;
  private accentWatch: MutationObserver | null = null;
  private raf: number | null = null;

  private width = 0;
  private height = 0;
  private dpr = 1;

  private target: Point;
  private current: Point;
  private trail: Point[] = [];

  private isVisible = false;
  private isInteractive = false;
  private isPressed = false;
  private isDotHidden = false;
  private isDarkInk = false;
  private isOverButton = false;

  private hoverProgress = 0;
  private pressProgress = 0;
  private visibilityProgress = 0;
  private darkProgress = 0;
  private buttonProgress = 0;
  private speed = 0;

  private accentRgb: Rgb = hexToRgb(ACCENT_FALLBACK);
  /** The ink the reference swaps to over a black surface. */
  private darkRgb: Rgb = [22, 10, 5];

  constructor() {
    this.target = { x: window.innerWidth / 2, y: window.innerHeight / 2 };
    this.current = { ...this.target };
  }

  init() {
    // Anything left over from an earlier mount (StrictMode double-invokes) goes.
    document.querySelectorAll('#canvas-cursor, #canvas-cursor-hover').forEach((n) => n.remove());

    const canvas = document.createElement('canvas');
    canvas.id = 'canvas-cursor';
    canvas.className = 'canvas-cursor';
    document.body.appendChild(canvas);

    const square = document.createElement('div');
    square.id = 'canvas-cursor-hover';
    square.className = 'canvas-cursor-hover';
    document.body.appendChild(square);

    const ctx = canvas.getContext('2d');
    if (!ctx) {
      square.remove();
      canvas.remove();
      return;
    }
    this.canvas = canvas;
    this.hoverSquare = square;
    this.ctx = ctx;

    this.readAccent();
    this.resize();

    window.addEventListener('resize', this.resize);
    document.addEventListener('mousemove', this.onMouseMove, { passive: true });
    document.addEventListener('mouseleave', this.onMouseLeave);
    document.addEventListener('mousedown', this.onMouseDown);
    window.addEventListener('mouseup', this.onMouseUp);
    window.addEventListener('blur', this.onMouseUp);

    /* The accent is a live token — the temporary switcher rewrites it on :root,
       and the theme toggle repaints the palette — so the ink follows it. */
    this.accentWatch = new MutationObserver(() => this.readAccent());
    this.accentWatch.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ['style', 'data-theme'],
    });

    this.wake();
  }

  destroy() {
    if (this.raf !== null) cancelAnimationFrame(this.raf);
    this.raf = null;
    this.accentWatch?.disconnect();
    this.accentWatch = null;
    window.removeEventListener('resize', this.resize);
    document.removeEventListener('mousemove', this.onMouseMove);
    document.removeEventListener('mouseleave', this.onMouseLeave);
    document.removeEventListener('mousedown', this.onMouseDown);
    window.removeEventListener('mouseup', this.onMouseUp);
    window.removeEventListener('blur', this.onMouseUp);
    this.canvas?.remove();
    this.hoverSquare?.remove();
    this.canvas = null;
    this.hoverSquare = null;
    this.ctx = null;
  }

  private readAccent() {
    const styles = getComputedStyle(document.documentElement);
    const raw = styles.getPropertyValue('--accent').trim() || ACCENT_FALLBACK;
    this.accentRgb = hexToRgb(raw);
    /* The press outline is the accent lifted toward white, as in the reference;
       it lives on the element so the SCSS never needs the JS value. */
    const rgb = this.accentRgb;
    this.hoverSquare?.style.setProperty('--cursor-ink', `rgb(${rgb[0]}, ${rgb[1]}, ${rgb[2]})`);
    this.hoverSquare?.style.setProperty('--cursor-ink-soft', mix(rgb, [255, 255, 255], 0.3));
  }

  private resize = () => {
    if (!this.canvas || !this.ctx) return;
    this.width = window.innerWidth;
    this.height = window.innerHeight;
    this.dpr = Math.max(
      1,
      Math.min(2, window.devicePixelRatio || 1, 3072 / Math.max(1, this.width))
    );
    this.canvas.width = this.width * this.dpr;
    this.canvas.height = this.height * this.dpr;
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.wake();
  };

  private wake() {
    if (this.raf === null && this.ctx) this.raf = requestAnimationFrame(this.render);
  }

  private onMouseMove = (e: MouseEvent) => {
    this.target = { x: e.clientX, y: e.clientY };
    this.isVisible = true;

    const node = e.target as Element | null;
    const hidden = !!node?.closest?.(HIDE);
    if (this.isDotHidden !== hidden) {
      this.isDotHidden = hidden;
      const v = hidden ? 'hidden' : 'visible';
      if (this.canvas) this.canvas.style.visibility = v;
      if (this.hoverSquare) this.hoverSquare.style.visibility = v;
      if (hidden) this.isPressed = false;
    }

    this.isInteractive = !!node?.closest?.(INTERACTIVE);
    this.isDarkInk = !!node?.closest?.(DARK_INK);
    this.isOverButton = !!node?.closest?.(BUTTON);
    this.wake();
  };

  private onMouseLeave = () => {
    this.isVisible = false;
    this.isPressed = false;
    this.wake();
  };

  private onMouseDown = () => {
    this.pressProgress = 0;
    this.isPressed = true;
    this.hoverProgress = Math.max(this.hoverProgress, 0.6);
    this.wake();
  };

  private onMouseUp = () => {
    this.isPressed = false;
    this.wake();
  };

  private render = () => {
    this.raf = null;
    if (document.hidden || !this.ctx) return;

    const from = { ...this.current };
    const last = {
      hover: this.hoverProgress,
      press: this.pressProgress,
      visibility: this.visibilityProgress,
      dark: this.darkProgress,
      button: this.buttonProgress,
      speed: this.speed,
    };

    this.current.x = approach(this.current.x, this.target.x, EASE.position, 0.01);
    this.current.y = approach(this.current.y, this.target.y, EASE.position, 0.01);
    this.hoverProgress = approach(this.hoverProgress, this.isInteractive ? 1 : 0, EASE.hover);
    this.pressProgress = this.isPressed ? approach(this.pressProgress, 1, EASE.press) : 0;
    this.visibilityProgress = approach(
      this.visibilityProgress,
      this.isVisible ? 1 : 0,
      EASE.visibility
    );
    this.darkProgress = approach(this.darkProgress, this.isDarkInk ? 1 : 0, EASE.hover);
    this.buttonProgress = approach(this.buttonProgress, this.isOverButton ? 1 : 0, EASE.hover);

    const ink = mix(this.accentRgb, this.darkRgb, this.darkProgress);
    /* 1 everywhere, easing down to BUTTON_OPACITY while the pointer sits on a
       button — the whole cursor (square and canvas) fades together. */
    const fade = 1 - (1 - BUTTON_OPACITY) * this.buttonProgress;
    /* The same idea on the press: the cursor reads at PRESS_OPACITY while the
       button is down. Taken as the lower of the two, so a click that lands on a
       button stays at half rather than stacking to a quarter. */
    const pressFade = 1 - (1 - PRESS_OPACITY) * this.pressProgress;
    const cursorAlpha = Math.min(fade, pressFade);

    /* The hairline square: it grows as the pointer settles on something
       clickable, and snaps hollow and smaller while the button is down. Over a
       button it is dropped entirely, pressed included — the desaturating block
       reads as a grey rectangle stamped across the fill of a CTA, and the press
       stamped the same square (darker over a warm fill, blue over a cool one)
       right where the click landed. Links and bare canvas keep both reads. */
    const buttonFade = 1 - this.buttonProgress;
    if (this.hoverSquare) {
      const scale = this.isPressed ? 0.5 + this.pressProgress * 0.3 : (6 + this.hoverProgress * 8) / 14;
      this.hoverSquare.style.opacity = String(
        (this.isPressed ? 1 : this.hoverProgress) *
          this.visibilityProgress *
          cursorAlpha *
          buttonFade
      );
      this.hoverSquare.style.transform =
        `translate3d(${this.current.x.toFixed(2)}px, ${this.current.y.toFixed(2)}px, 0) ` +
        `translate(-50%, -50%) scale(${scale.toFixed(3)})`;
      this.hoverSquare.classList.toggle('pressed', this.isPressed);
    }

    const step = Math.hypot(this.current.x - from.x, this.current.y - from.y);
    this.speed += (step - this.speed) * 0.2;

    if (step > TRAIL_MIN_MOVE) {
      this.trail.push({ x: this.current.x, y: this.current.y });
      if (this.trail.length > TRAIL_LENGTH) this.trail.shift();
    }
    const moving = this.speed > TRAIL_MIN_SPEED || last.speed > TRAIL_MIN_SPEED;

    const settled =
      this.current.x === from.x &&
      this.current.y === from.y &&
      this.hoverProgress === last.hover &&
      this.pressProgress === last.press &&
      this.visibilityProgress === last.visibility &&
      this.darkProgress === last.dark &&
      this.buttonProgress === last.button &&
      (!moving || this.speed === last.speed);
    if (settled) return;

    const ctx = this.ctx;
    ctx.clearRect(0, 0, this.width, this.height);

    if (this.visibilityProgress > 0) {
      /* The tail: one hairline per sample, brightest at the pointer, and gone
         entirely while the pointer is still. */
      const strength = Math.min(1, Math.max(0, (this.speed - TRAIL_MIN_SPEED) / 6));
      if (strength > 0.02) {
        ctx.strokeStyle = ink;
        ctx.lineWidth = TRAIL_WIDTH;
        ctx.lineCap = 'round';
        for (let i = 1; i < this.trail.length; i++) {
          const t = i / this.trail.length;
          ctx.globalAlpha = t * t * 0.7 * this.visibilityProgress * strength * cursorAlpha;
          ctx.beginPath();
          ctx.moveTo(this.trail[i - 1].x, this.trail[i - 1].y);
          ctx.lineTo(this.trail[i].x, this.trail[i].y);
          ctx.stroke();
        }
      }

      /* The square: handed over to the hairline square once a target is settled
         on, and never drawn where the surface asked for no cursor. */
      if ((this.isPressed || this.hoverProgress < 0.99) && !this.isDotHidden) {
        ctx.globalAlpha =
          (this.isPressed ? 1 : 1 - this.hoverProgress) *
          this.visibilityProgress *
          cursorAlpha *
          buttonFade;
        ctx.fillStyle = ink;
        ctx.fillRect(
          this.current.x - DOT_SIZE / 2,
          this.current.y - DOT_SIZE / 2,
          DOT_SIZE,
          DOT_SIZE
        );
      }
    }
    ctx.globalAlpha = 1;

    if (!moving && step <= TRAIL_MIN_MOVE) this.trail = [{ ...this.current }];
    this.wake();
  };
}

export default function CanvasCursor() {
  useEffect(() => {
    if (!CURSOR_ENABLED) return;
    // The reference's own gate: fine pointers only, and never under reduced motion.
    const fine = window.matchMedia('(hover: hover) and (pointer: fine)').matches;
    const calm = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (!fine || calm) return;

    const cursor = new CursorLayer();
    cursor.init();
    return () => cursor.destroy();
  }, []);

  return null;
}

import { useEffect, useRef } from 'react';

/**
 * A small confirmation sheet — the one action a form cannot put back gets
 * asked about first. It reuses the app's sheet chrome, so it reads as another
 * layer over the sheet that opened it rather than a second kind of dialog.
 *
 * Escape and a click on the backdrop both cancel; the confirm button is the
 * only way through. The sheet underneath has its own Escape handler, so this
 * one listens in the capture phase and stops the key, letting Escape put the
 * question away instead of the form it was asked from.
 */
export default function ConfirmSheet({
  id,
  title,
  copy,
  confirmLabel,
  cancelLabel = 'Keep',
  onConfirm,
  onCancel,
}: {
  /** Namespaces the title/copy ids, so several sheets can sit on one page. */
  id: string;
  title: string;
  /** One line naming what is about to go. */
  copy?: string;
  confirmLabel: string;
  cancelLabel?: string;
  onConfirm: () => void;
  onCancel: () => void;
}) {
  const panel = useRef<HTMLDivElement>(null);

  useEffect(() => {
    panel.current?.focus();
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== 'Escape') return;
      e.stopPropagation();
      onCancel();
    };
    window.addEventListener('keydown', onKey, true);
    return () => window.removeEventListener('keydown', onKey, true);
  }, [onCancel]);

  return (
    <div className="sheet-backdrop" onClick={onCancel}>
      <div
        className="sheet confirm-sheet"
        role="alertdialog"
        aria-modal="true"
        aria-labelledby={`${id}-title`}
        aria-describedby={copy ? `${id}-copy` : undefined}
        tabIndex={-1}
        ref={panel}
        onClick={(e) => e.stopPropagation()}
      >
        <h4 className="sheet-title" id={`${id}-title`}>
          {title}
        </h4>
        {copy && (
          <p className="sheet-copy" id={`${id}-copy`}>
            {copy}
          </p>
        )}
        <div className="sheet-actions">
          <button className="ghost small" onClick={onCancel}>
            {cancelLabel}
          </button>
          <button className="primary small danger" onClick={onConfirm}>
            {confirmLabel}
          </button>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useRef, useState, type ReactNode } from 'react';
import { createPortal } from 'react-dom';
import DayMeter from './DayMeter';
import { SortMark, type SortDir } from './sortable';
import { useNetworkSearch, matchTracks } from '../lib/networkSearch';
import { useAuth } from '../lib/auth';
import { ACCESS_LABEL, isCovered, statusLabel, type MapTrack } from '../lib/trackAccess';

/** What the list sorts on: the days still available, or the track's name. */
type SortKey = 'days' | 'name';
const SORT_LABEL: Record<SortKey, string> = { days: 'Days left', name: 'Name' };

/**
 * Which slice of the network the rail lists. The three are one axis, so the
 * control is one pill: everything, the venues this rider follows, or the venues
 * their pass carries. `covered` is the only one the map answers to — the other
 * two leave its pins alone.
 */
export type RailView = 'all' | 'following' | 'covered';
const VIEW_LABEL: Record<RailView, string> = { all: 'All', following: 'Following', covered: 'Included' };

/** The click order: days low-to-high, days high-to-low, then A-Z, then Z-A. */
const SORT_CYCLE: { key: SortKey; dir: SortDir; label: string }[] = [
  { key: 'days', dir: 'asc', label: 'Days left · fewest' },
  { key: 'days', dir: 'desc', label: 'Days left · most' },
  { key: 'name', dir: 'asc', label: 'Name · A–Z' },
  { key: 'name', dir: 'desc', label: 'Name · Z–A' },
];
/**
 * The same control on a list with no days to rank by — the free tier and the
 * signed-out network: there is nothing to count, so it offers the name alone.
 */
const NAME_SORT_CYCLE = SORT_CYCLE.filter((o) => o.key === 'name');

/** The tick on the chosen order in the sort menu. Drawn, not a glyph. */
function CheckMark() {
  return (
    <svg width="12" height="12" viewBox="0 0 12 12" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M2.5 6.5 5 9l4.5-5.5" />
    </svg>
  );
}

/** The filter mark: a funnel, drawn at the sort chevron's weight. It opens the
 *  sheet the slices live in, so the head carries an icon rather than a band. */
function FilterIcon() {
  return (
    <svg width="13" height="13" viewBox="0 0 14 14" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M2 3.1h10L8.5 7.4v3.7L5.5 9.6V7.4L2 3.1Z" />
    </svg>
  );
}

export interface Entitlement {
  trackId: string;
  trackName: string;
  trackSlug: string;
  trackWebsite: string | null;
  trackImageUrl: string | null;
  includedDays: number;
  freeDaysUsed: number;
  freeDaysRemaining: number;
  discountDayEnabled: boolean;
  discountDayNumber: number;
  discountRate: number;
  extraDayPriceCents: number;
  discountPriceCents: number;
  discountDaysAllowed: number;
  discountDaysUsed: number;
  reservationRequired: boolean;
}

/** One line of the list: a partner track, and the pass's terms there if any. */
interface Row {
  track: MapTrack;
  ent?: Entitlement;
}

/**
 * The ladder the list is ordered by: rideable now, then thinner, then nothing —
 * a track the pass does not carry sinks below every track it does.
 */
function accessRank(r: Row, gated: boolean): number {
  if (gated || !r.ent) return 3;
  if (r.ent.freeDaysRemaining > 0) return 0;
  const discountLeft = r.ent.discountDayEnabled
    ? Math.max(r.ent.discountDaysAllowed - r.ent.discountDaysUsed, 0)
    : 0;
  return discountLeft > 0 ? 1 : 2;
}

/**
 * The venue's gate light: what the track is doing today — open, caution or
 * closed — and what it says about it. The operator's own post for the day is
 * the light's hover read; the generic line for that status stands in when the
 * operator has not made one.
 */
const STATUS_LIGHT: Record<string, { label: string; cls: string; generic: string }> = {
  OPEN: { label: 'Open', cls: 'is-open', generic: 'Open today.' },
  WEATHER_HOLD: {
    label: 'Caution',
    cls: 'is-caution',
    generic: 'Caution today. Check with the venue before you drive out.',
  },
  CLOSED: { label: 'Closed', cls: 'is-closed', generic: 'Closed today.' },
};

/**
 * One line of the rail: the venue's gate light, then the venue and where it is
 * — a venue that needs a booking says so, the walk-up default goes unsaid —
 * then what the pass leaves there — days left with its own meter, a discounted
 * day only, none left, or nothing at all. The light reads for everyone, the
 * terms of a gated list (free tier, visitor, lapsed pass) do not: those rows
 * end at the venue's name and location.
 *
 * The line is one target: an overlay button covers it so the whole line is one
 * click — the pick that opens the venue's inspector over the map. The gate
 * light rides above that button so it can be hovered for the day's read, and
 * takes the same pick. Following happens in that inspector and on the venue's
 * own profile, so a row carries no control of its own: a name, a location and
 * the pass's read, nothing else.
 */
function TrackRow({
  row,
  gated,
  selected,
  onSelect,
}: {
  row: Row;
  gated: boolean;
  selected: boolean;
  onSelect?: (trackId: string) => void;
}) {
  const { track, ent } = row;
  const covered = Boolean(ent) && !gated;
  const remaining = covered && ent ? Math.max(ent.freeDaysRemaining, 0) : 0;
  const discountLeft =
    covered && ent && ent.discountDayEnabled
      ? Math.max(ent.discountDaysAllowed - ent.discountDaysUsed, 0)
      : 0;
  const spent = covered && remaining === 0 && discountLeft === 0;
  const where = [track.city, track.region].filter(Boolean).join(', ');
  const sub = where;

  /** Today's gate read — the light, and the words it carries on hover. */
  const light = STATUS_LIGHT[track.status] ?? {
    label: statusLabel(track.status),
    cls: 'is-unknown',
    generic: '',
  };
  const message = (track.statusNote ?? '').trim() || light.generic;
  /**
   * Which way the read opens: under the dot, or above it on a line that sits
   * near the foot of the list's own scroller, where a read opening down would
   * be cut off. The flip is set on the node itself rather than held in state —
   * a re-render under the cursor makes the browser drop the element's `:hover`
   * until the mouse moves again, and the read would blink out just as it opened.
   */
  const openRead = (el: HTMLElement) => {
    const scroller = el.closest('.day-grid');
    if (!scroller) return;
    const foot = scroller.getBoundingClientRect().bottom;
    el.classList.toggle('tip-up', el.getBoundingClientRect().bottom + 78 > foot);
  };

  const cls = ['day-row', 'selectable'];
  if (spent) cls.push('spent');
  if (selected) cls.push('selected');
  if (!covered && !gated) cls.push('not-covered');

  return (
    <div className={cls.join(' ')} data-track-id={track.id}>
      <button
        type="button"
        className="day-open"
        aria-label={`${selected ? 'Close' : 'Open'} ${track.name}: ${light.label}${
          message ? `. ${message}` : ''
        }`}
        aria-pressed={selected}
        onClick={() => onSelect?.(track.id)}
      />

      <div className="day-body">
        <span
          className={`day-light ${light.cls}`}
          aria-hidden="true"
          onMouseEnter={(e) => openRead(e.currentTarget)}
          onMouseLeave={(e) => e.currentTarget.classList.remove('tip-up')}
          onClick={() => onSelect?.(track.id)}
        >
          <span className="day-light-dot" />
          <span className="day-light-tip">
            <b>{light.label}</b>
            {message && <span>{message}</span>}
          </span>
        </span>

        <span className="day-name">{track.name}</span>
        {sub && <span className="day-sub">{sub}</span>}

        {covered && ent ? (
          <DayMeter left={remaining} total={ent.includedDays} />
        ) : gated ? null : (
          <span className="small muted">{ACCESS_LABEL.notCovered}</span>
        )}
      </div>
    </div>
  );
}

/**
 * Every partner track in the network, most-depleted first, the ones the pass
 * does not carry last — narrowed to one slice of the network at a time by the
 * pill above it and by the header field's query. The map beside it badges the
 * same network, so the rail and the pins never disagree about what it holds.
 */
export default function DaysByTrack({
  identity,
  ents,
  tracks = [],
  gated = false,
  view = 'all',
  onView,
  canCover = false,
  selectedId = null,
  onSelect,
}: {
  /** Who is reading, drawn at the left of the rail's head — the page's own
   *  line, seat here because the head is one row: the identity, then the two
   *  controls that shape the list. */
  identity?: ReactNode;
  ents: Entitlement[];
  /** The network's tracks — the list is the whole network, not just the terms. */
  tracks?: MapTrack[];
  /** Free tier or a lapsed pass: no day terms at all, so the rows carry no
   *  pass read — the venue's own gate light stays, its terms do not. */
  gated?: boolean;
  /** Which slice of the network the rail is listing. */
  view?: RailView;
  /** The pill fired. The page holds the slice, because the map reads it too. */
  onView?: (view: RailView) => void;
  /** Whether the covered slice is worth offering at all — a running pass that
   *  leaves venues out. A visitor, the free tier and a lapsed pass never see it. */
  canCover?: boolean;
  /** The venue whose inspector is open, so its row reads as the picked one. */
  selectedId?: string | null;
  /** A row's overlay fired: the pick that opens (or closes) that venue. */
  onSelect?: (trackId: string) => void;
}) {
  const { user } = useAuth();
  const [sortIx, setSortIx] = useState(0);
  /** The order menu is open: the control names the sort, the menu picks one. */
  const [sortOpen, setSortOpen] = useState(false);
  const sortWrap = useRef<HTMLDivElement>(null);
  /** The slice sheet is open. The slices are one axis and they all fit in a
   *  sheet, so the head keeps its row and the pills live in here. */
  const [filterOpen, setFilterOpen] = useState(false);
  const filterPanel = useRef<HTMLDivElement>(null);
  /** The list's own scroller — the rail is only as tall as the window. */
  const gridRef = useRef<HTMLDivElement>(null);
  /** The header field's query — the rail is one of the surfaces it narrows. */
  const { q, setQ } = useNetworkSearch();
  const needle = q.trim().toLowerCase();

  // A gated list has no days to rank by, so its control offers the name alone.
  const cycle = gated ? NAME_SORT_CYCLE : SORT_CYCLE;
  const sort = cycle[sortIx % cycle.length];

  // The menu is a light popover: it closes on Escape or on a click anywhere
  // outside itself, the same shape the shell's account menu uses.
  useEffect(() => {
    if (!sortOpen) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setSortOpen(false);
    };
    const onDown = (e: MouseEvent) => {
      if (sortWrap.current && !sortWrap.current.contains(e.target as Node)) setSortOpen(false);
    };
    window.addEventListener('keydown', onKey);
    document.addEventListener('mousedown', onDown);
    return () => {
      window.removeEventListener('keydown', onKey);
      document.removeEventListener('mousedown', onDown);
    };
  }, [sortOpen]);

  // The slice sheet takes the caret when it opens and Escape puts it away; a
  // click on the backdrop does the same (the backdrop is the sheet's own).
  useEffect(() => {
    if (!filterOpen) return;
    filterPanel.current?.focus();
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setFilterOpen(false);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [filterOpen]);

  // The list is the network first; before it loads, the rider's own terms still
  // make a list rather than an empty rail.
  const rows = useMemo<Row[]>(() => {
    if (tracks.length) {
      const byId = new Map(ents.map((e) => [e.trackId, e]));
      return tracks.map((t) => ({ track: t, ent: byId.get(t.id) }));
    }
    return ents.map((e) => ({
      track: {
        id: e.trackId,
        slug: e.trackSlug,
        name: e.trackName,
        website: e.trackWebsite,
        instagram: null,
        facebook: null,
        imageUrl: e.trackImageUrl,
        description: null,
        city: null,
        region: null,
        lat: null,
        lng: null,
        status: 'OPEN',
        statusNote: null,
        hours: null,
        nextEvent: null,
        gated,
        includedDays: e.includedDays,
        discountDayEnabled: e.discountDayEnabled,
        discountDayNumber: e.discountDayNumber,
        discountRate: e.discountRate,
        extraDayPriceCents: e.extraDayPriceCents,
        reservationRequired: e.reservationRequired,
      },
      ent: e,
    }));
  }, [tracks, ents, gated]);

  // The slice runs first: the whole network, the tracks this rider follows, or
  // only what their pass carries. The header field's query then narrows
  // whatever that slice is, so a rider can search inside only what they follow.
  // A row survives when every token of the query lands on the venue.
  const base = useMemo(() => {
    if (view === 'following') return rows.filter((r) => r.track.following);
    if (view === 'covered') return rows.filter((r) => isCovered(r.ent));
    return rows;
  }, [rows, view]);

  const shown = useMemo(() => {
    if (!needle) return base;
    const hit = new Set(matchTracks(base.map((r) => r.track), needle).map((m) => m.track.id));
    return base.filter((r) => hit.has(r.track.id));
  }, [base, needle]);

  // Days left: fewest first, so the tracks nearest to running out sit at the
  // top — but a track with none left drops below the ones that still have days,
  // and a track the pass does not carry below those. Name: straight A-Z / Z-A.
  const ordered = useMemo(
    () =>
      [...shown].sort((a, b) => {
        if (sort.key === 'name') {
          const c = a.track.name.localeCompare(b.track.name);
          return sort.dir === 'asc' ? c : -c;
        }
        const ra = accessRank(a, gated);
        const rb = accessRank(b, gated);
        if (ra !== rb) return ra - rb;
        const da = a.ent ? a.ent.freeDaysRemaining : 0;
        const db = b.ent ? b.ent.freeDaysRemaining : 0;
        return (
          (da - db) * (sort.dir === 'asc' ? 1 : -1) || a.track.name.localeCompare(b.track.name)
        );
      }),
    [shown, sort, gated]
  );

  /**
   * A pick made on the map opens the venue's inspector — but the map carries the
   * whole network while the rail only shows as many rows as the window is tall,
   * so the picked venue's own line can sit off the list, and an inspector with no
   * visible row behind it reads as a pick that came from nowhere. Bring that row
   * in, and leave the list exactly where it is when the row is already on it
   * (a row pick, or a pin for a venue near the top).
   */
  useEffect(() => {
    if (!selectedId) return;
    const grid = gridRef.current;
    if (!grid) return;
    const row = Array.from(grid.children).find(
      (el) => (el as HTMLElement).dataset.trackId === selectedId
    ) as HTMLElement | undefined;
    // The slice or the search can leave the picked venue out of the list: there
    // is no row to bring in, so nothing moves.
    if (!row) return;
    const frame = grid.getBoundingClientRect();
    const line = row.getBoundingClientRect();
    if (line.top >= frame.top && line.bottom <= frame.bottom) return;
    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const behavior: ScrollBehavior = reduced ? 'auto' : 'smooth';
    // Narrow layouts let the rail grow and hand the scrolling to the page, so
    // there is no list scrollTop to move — the window is the scroller there.
    if (grid.scrollHeight <= grid.clientHeight + 1) {
      row.scrollIntoView({ block: 'nearest', behavior });
      return;
    }
    const delta = line.top < frame.top ? line.top - frame.top : line.bottom - frame.bottom;
    grid.scrollTo({ top: grid.scrollTop + delta, behavior });
  }, [selectedId, ordered]);

  /** The slices worth offering, left to right: the whole network, the venues
   *  the pass includes, then the ones this rider follows. The Following slice
   *  is a rider action, so it never stands for an operator; Included needs a
   *  pass that leaves venues out, so neither ever leaves the pill standing
   *  for one. */
  const canFollow = user?.role === 'RIDER';
  const slices: RailView[] = ['all', ...(canCover ? (['covered'] as RailView[]) : []), ...(canFollow ? (['following'] as RailView[]) : [])];

  return (
    <section className="day-rail">
      {/* The rail's head is one row: who is reading on the left, then the two
          controls that shape the list — the filter, which opens the sheet the
          slices live in, and the sort that names the order in force. The pills
          are off the band, so the head never needs a row of its own. */}
      <div className="rail-pass">
        {identity && <div className="rail-pass-id">{identity}</div>}

        <div className="rail-tools">
          {slices.length > 1 && (
            <button
              type="button"
              className={`rail-filter${view === 'all' ? '' : ' on'}`}
              title="Filter"
              aria-label={
                view === 'all'
                  ? 'Filter the network'
                  : `Filter the network, showing ${VIEW_LABEL[view]}`
              }
              aria-haspopup="dialog"
              aria-expanded={filterOpen}
              onClick={() => setFilterOpen(true)}
            >
              <FilterIcon />
            </button>
          )}

          {/* The stack is reorderable whenever there is more than one way in —
              days, or the name alone on a list with no days to rank by. */}
          {ordered.length > 1 && (
            <div className="day-sort-wrap" ref={sortWrap}>
              <button
                type="button"
                className="sort-btn day-sort"
                aria-haspopup="menu"
                aria-expanded={sortOpen}
                onClick={() => setSortOpen((o) => !o)}
              >
                <span>{SORT_LABEL[sort.key]}</span>
                <SortMark dir={sort.dir} />
              </button>

              {sortOpen && (
                <div className="day-sort-pop" role="menu" aria-label="Order the tracks">
                  {cycle.map((o, i) => {
                    const on = i === sortIx % cycle.length;
                    return (
                      <button
                        key={`${o.key}-${o.dir}`}
                        type="button"
                        role="menuitemradio"
                        aria-checked={on}
                        className="day-sort-item"
                        onClick={() => {
                          setSortIx(i);
                          setSortOpen(false);
                        }}
                      >
                        <span>{o.label}</span>
                        {on && <CheckMark />}
                      </button>
                    );
                  })}
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Which slice of the network the rail lists. One axis, so one choice:
          picking one applies it and puts the sheet away. Portalled to the body,
          the way the pass's QR sheet is — the rail is a scroller, and a dialog
          drawn inside it would be clipped by it. */}
      {filterOpen &&
        createPortal(
          <div className="sheet-backdrop" onClick={() => setFilterOpen(false)}>
            <div
              className="sheet rail-filter-sheet"
              role="dialog"
              aria-modal="true"
              aria-labelledby="rail-filter-title"
              tabIndex={-1}
              ref={filterPanel}
              onClick={(e) => e.stopPropagation()}
            >
              <h4 className="sheet-title" id="rail-filter-title">
                Filter
              </h4>
              <p className="sheet-copy">
                Which part of the network the list and the map show.
              </p>
              <div
                className="pill-toggle day-filter"
                role="group"
                aria-label="Which tracks to show"
              >
                {slices.map((v) => (
                  <button
                    key={v}
                    type="button"
                    aria-pressed={view === v}
                    onClick={() => {
                      onView?.(v);
                      setFilterOpen(false);
                    }}
                  >
                    {VIEW_LABEL[v]}
                  </button>
                ))}
              </div>
              <div className="sheet-actions">
                <button className="ghost" onClick={() => setFilterOpen(false)}>
                  Done
                </button>
              </div>
            </div>
          </div>,
          document.body
        )}

      {/* The header field's own read of the rail: how much of the network the
          typed search left. Only while a query is on and it found something —
          the field itself carries the way back to all of it. */}
      {needle && ordered.length > 0 && (
        <div className="day-search-note">
          <span className="day-search-count">
            {ordered.length} of {base.length}
          </span>
        </div>
      )}

      {ordered.length ? (
        <div className="day-grid" ref={gridRef}>
          {ordered.map((r) => (
            <TrackRow
              key={r.track.id}
              row={r}
              gated={gated}
              selected={r.track.id === selectedId}
              onSelect={onSelect}
            />
          ))}
        </div>
      ) : needle ? (
        <div className="muted small day-empty">
          No tracks match "{q.trim()}".{' '}
          <button className="ghost small" onClick={() => setQ('')}>
            Clear search
          </button>
        </div>
      ) : view === 'following' && !rows.some((r) => r.track.following) ? (
        <div className="muted small day-empty">
          Not following a track yet.{' '}
          <button className="ghost small" onClick={() => onView?.('all')}>
            Show every track
          </button>
        </div>
      ) : view === 'covered' ? (
        /* The slice is what emptied the rail — the way back is its own control
           rather than a trip to the head. */
        <div className="muted small day-empty">
          Every venue in the network is outside your pass.{' '}
          <button className="ghost small" onClick={() => onView?.('all')}>
            Show them
          </button>
        </div>
      ) : (
        <div className="muted small day-empty">No partner tracks yet.</div>
      )}
    </section>
  );
}

import { useMemo, useState } from 'react';
import Banner from './Banner';
import { api } from '../lib/api';
import { DAY_STATUS_LABEL, DAY_STATUS_OPTIONS, shiftDay, todayKey, type DayStatus } from '../lib/events';

/**
 * The gate per date: an operator posts Open, Caution or Closed for today,
 * tomorrow, or any date they pick — with that day's own note. When the day
 * arrives its read becomes the venue's live line, so tomorrow's caution is
 * scheduled today and flips the gate overnight.
 *
 * A day with no read follows the live line; clearing drops the day back to
 * it. Posting today also moves the live line at once, so the network, the
 * map and the venue profile agree immediately.
 */
export default function DayStatusEditor({
  trackId,
  rows,
  liveStatus,
  liveNote,
  onChange,
  onMessage,
}: {
  /** The venue's id for an admin editing on its behalf — omitted for the pinned owner. */
  trackId?: string;
  /** Every scheduled day from today on, as the owner read serves them. */
  rows: DayStatus[];
  /** The venue's live line, for the days no read covers. */
  liveStatus: string;
  liveNote: string | null;
  /** The saved rows, so the console's read stays current without a refetch. */
  onChange: (rows: DayStatus[]) => void;
  onMessage: (msg: string) => void;
}) {
  const today = todayKey();
  const tomorrow = useMemo(() => shiftDay(today, 1), [today]);
  const [which, setWhich] = useState<'today' | 'tomorrow' | 'custom'>('today');
  const [custom, setCustom] = useState(today);
  const [status, setStatus] = useState('OPEN');
  const [note, setNote] = useState('');
  const [saving, setSaving] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  const day = which === 'today' ? today : which === 'tomorrow' ? tomorrow : custom;
  const byDay = useMemo(() => new Map(rows.map((r) => [r.day, r])), [rows]);
  const existing = byDay.get(day);
  /** The next few scheduled days, so the operator sees what is already posted. */
  const upcoming = useMemo(() => rows.filter((r) => r.day >= today).slice(0, 5), [rows, today]);

  const pretty = (d: string) =>
    new Date(`${d}T12:00:00Z`).toLocaleDateString(undefined, {
      weekday: 'short',
      month: 'short',
      day: 'numeric',
      timeZone: 'UTC',
    });

  const save = async () => {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) {
      setErr('Pick a date.');
      return;
    }
    setSaving(true);
    setErr(null);
    const res = await api.post<{ dayStatus: { day: string; status: string; statusNote: string | null } }>(
      '/owner/track/day-status',
      { day, status, statusNote: note, ...(trackId ? { trackId } : {}) }
    );
    setSaving(false);
    if (!res.success || !res.data?.dayStatus) {
      setErr(res.message);
      return;
    }
    const saved: DayStatus = {
      day: res.data.dayStatus.day.slice(0, 10),
      status: res.data.dayStatus.status,
      statusNote: res.data.dayStatus.statusNote,
    };
    const next = [...rows.filter((r) => r.day !== saved.day), saved].sort((a, b) =>
      a.day < b.day ? -1 : 1
    );
    onChange(next);
    onMessage(saved.day === todayKey() ? 'Gate updated for today.' : `Gate posted for ${pretty(saved.day)}.`);
  };

  const clear = async (d: string) => {
    setSaving(true);
    setErr(null);
    const res = await api.del<{ day: string }>(
      `/owner/track/day-status?day=${d}${trackId ? `&trackId=${trackId}` : ''}`
    );
    setSaving(false);
    if (!res.success) {
      setErr(res.message);
      return;
    }
    onChange(rows.filter((r) => r.day !== d));
    onMessage(`${pretty(d)} follows the live gate again.`);
  };

  return (
    <section className="card stack" aria-label="Gate by day">
      <h3>Gate by day</h3>
      <div className="small muted">
        Post today, tomorrow, or any date. A day that arrives takes the live gate with it:{' '}
        {pretty(tomorrow)}&rsquo;s caution flips the page overnight.
      </div>

      <div className="pill-toggle day-filter" role="group" aria-label="Which day to set">
        {(
          [
            ['today', `Today · ${DAY_STATUS_LABEL[byDay.get(today)?.status ?? liveStatus] ?? liveStatus}`],
            ['tomorrow', `Tomorrow${byDay.get(tomorrow) ? ` · ${DAY_STATUS_LABEL[byDay.get(tomorrow)!.status]}` : ''}`],
            ['custom', 'Pick a date'],
          ] as const
        ).map(([key, label]) => (
          <button key={key} type="button" aria-pressed={which === key} onClick={() => setWhich(key)}>
            {label}
          </button>
        ))}
      </div>

      {which === 'custom' && (
        <div>
          <label>Date</label>
          <input type="date" aria-label="Date" value={custom} onChange={(e) => setCustom(e.target.value)} />
        </div>
      )}

      <div className="grid cols-2">
        <div>
          <label>Gate for {pretty(day)}</label>
          <select aria-label={`Gate for ${pretty(day)}`} value={status} onChange={(e) => setStatus(e.target.value)}>
            {DAY_STATUS_OPTIONS.map((o) => (
              <option key={o} value={o}>
                {DAY_STATUS_LABEL[o]}
              </option>
            ))}
          </select>
        </div>
        <div>
          <label>Note for the day</label>
          <input
            value={note}
            onChange={(e) => setNote(e.target.value)}
            placeholder={existing?.statusNote ?? liveNote ?? 'Rain overnight, so the gate opens once it dries'}
          />
        </div>
      </div>
      {existing && (
        <div className="small muted">
          {pretty(day)} reads {DAY_STATUS_LABEL[existing.status]}
          {existing.statusNote ? `: ${existing.statusNote}` : ''}. Saving replaces it.
        </div>
      )}

      {err && <Banner tone="bad">{err}</Banner>}

      <div className="row wrap">
        <button className="primary" onClick={save} disabled={saving}>
          {saving ? 'Saving…' : day === today ? 'Set today’s gate' : `Post ${pretty(day)}`}
        </button>
        {existing && (
          <button className="ghost" onClick={() => clear(day)} disabled={saving}>
            Clear back to the live gate
          </button>
        )}
      </div>

      {upcoming.length > 0 && (
        <ul className="event-list">
          {upcoming.map((r) => (
            <li key={r.day} className="event-row">
              <div className="event-date">
                <span className="event-month">
                  {new Date(`${r.day}T12:00:00Z`).toLocaleDateString(undefined, { month: 'short', timeZone: 'UTC' })}
                </span>
                <span className="event-day">
                  {new Date(`${r.day}T12:00:00Z`).toLocaleDateString(undefined, { day: 'numeric', timeZone: 'UTC' })}
                </span>
              </div>
              <div className="stack event-body">
                <div className="row wrap event-title-row">
                  <b>{r.day === today ? 'Today' : r.day === tomorrow ? 'Tomorrow' : pretty(r.day)}</b>
                  <span className="pill">{DAY_STATUS_LABEL[r.status] ?? r.status}</span>
                </div>
                {r.statusNote && <div className="small event-note">{r.statusNote}</div>}
              </div>
              <div className="event-actions">
                <button
                  type="button"
                  className="ghost small"
                  onClick={() => {
                    setWhich(r.day === today ? 'today' : r.day === tomorrow ? 'tomorrow' : 'custom');
                    setCustom(r.day);
                    setStatus(r.status);
                    setNote(r.statusNote ?? '');
                  }}
                >
                  Edit
                </button>
                <button type="button" className="ghost small" onClick={() => clear(r.day)} disabled={saving}>
                  Clear
                </button>
              </div>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

import { ReactNode, useMemo, useState } from 'react';
import type { DayStatus, ProfileEvent } from '../lib/events';
import { CAL_PER_PAGE, ampmLabel, dayKey, dayRange, daysOf, firstOfMonth, gridDays, monthKey } from '../lib/events';
import MonthGrid from './MonthGrid';

/**
 * The venue's schedule as a month you can walk through: the grid on the left,
 * that month's dates on the right. Past months read the same as future ones —
 * the page is a calendar, not a countdown — and five dates is one page.
 *
 * It reads, it does not write: the owner hands a per-row control in through
 * `renderAction` (the Edit link out to the calendar page) and everything else
 * on a row is the venue's own copy.
 */
export default function EventCalendar({
  events,
  dayStatuses = [],
  renderAction,
  onOpen,
}: {
  events: ProfileEvent[];
  /** The operator's posted gate reads — painted onto their dates. */
  dayStatuses?: DayStatus[];
  renderAction?: (ev: ProfileEvent) => ReactNode;
  /**
   * Opens the date's own sheet. Whoever reads a date without owning it (a
   * visitor, a rider) gets the read-only one; passing it in is what makes a
   * row a control, so the page that owns the sheet owns the click too.
   */
  onOpen?: (ev: ProfileEvent) => void;
}) {
  const today = dayKey(new Date().toISOString());

  // Open on the next date the venue has, or on this month when there is none.
  const open = useMemo(() => {
    const next = events.find((e) => dayKey(e.startsAt) >= today);
    const base = new Date(next ? next.startsAt : Date.now());
    return { year: base.getUTCFullYear(), month: base.getUTCMonth() };
  }, [events, today]);

  const [view, setView] = useState(open);
  const [page, setPage] = useState(0);
  const [picked, setPicked] = useState<string | null>(null);

  const days = useMemo(() => gridDays(view.year, view.month), [view]);
  const byDay = useMemo(() => {
    const map = new Map<string, ProfileEvent[]>();
    for (const ev of events) {
      for (const k of daysOf(ev)) {
        const list = map.get(k);
        if (list) list.push(ev);
        else map.set(k, [ev]);
      }
    }
    return map;
  }, [events]);
  /** The posted gate per date — what the grid paints onto its days. */
  const gateByDay = useMemo(() => {
    const map = new Map<string, DayStatus>();
    for (const r of dayStatuses) map.set(r.day.slice(0, 10), { ...r, day: r.day.slice(0, 10) });
    return map;
  }, [dayStatuses]);

  // A month holds the dates that start in it; the grid still marks a run that
  // began in the month before, so the row is never labelled with the wrong day.
  const key = monthKey(view);
  const inMonth = useMemo(() => events.filter((e) => dayKey(e.startsAt).startsWith(key)), [events, key]);
  const pageCount = Math.max(1, Math.ceil(inMonth.length / CAL_PER_PAGE));
  const shown = inMonth.slice(page * CAL_PER_PAGE, page * CAL_PER_PAGE + CAL_PER_PAGE);

  function step(delta: number) {
    setView((v) => {
      const d = firstOfMonth(v.year, v.month + delta);
      return { year: d.getUTCFullYear(), month: d.getUTCMonth() };
    });
    setPage(0);
    setPicked(null);
  }

  function pickDay(day: string) {
    const dayEvents = byDay.get(day) ?? [];
    if (dayEvents.length === 0) return;
    const lead = dayEvents[0];
    const at = inMonth.findIndex((e) => e.id === lead.id);
    if (at >= 0) setPage(Math.floor(at / CAL_PER_PAGE));
    setPicked(day);
  }

  const from = inMonth.length === 0 ? 0 : page * CAL_PER_PAGE + 1;
  const to = Math.min(inMonth.length, (page + 1) * CAL_PER_PAGE);

  return (
    <div className="event-cal" data-month={key}>
      <MonthGrid
        view={view}
        days={days}
        today={today}
        countFor={(day) => byDay.get(day)?.length ?? 0}
        statusFor={(day) => gateByDay.get(day)?.status ?? null}
        picked={picked}
        onStep={step}
        onPickDay={pickDay}
      />

      <div className="stack cal-side">
        {inMonth.length === 0 ? (
          <div className="small muted">Nothing on the calendar this month.</div>
        ) : (
          <ul className="event-list">
            {shown.map((ev) => {
              const d = new Date(ev.startsAt);
              const hours = ampmLabel(ev);
              return (
                <li
                  key={ev.id}
                  className={['event-row', renderAction ? 'has-action' : '', onOpen ? 'has-open' : '']
                    .filter(Boolean)
                    .join(' ')}
                >
                  {/* The row is the control when someone hands a sheet in: a
                      click anywhere on the date opens it, and its own copy
                      stays a read. */}
                  {onOpen && (
                    <button
                      type="button"
                      className="event-open"
                      aria-label={`View ${ev.title}`}
                      onClick={() => onOpen(ev)}
                    />
                  )}
                  <div className="event-date">
                    <span className="event-month">
                      {d.toLocaleDateString(undefined, { month: 'short', timeZone: 'UTC' })}
                    </span>
                    <span className="event-day">
                      {d.toLocaleDateString(undefined, { day: 'numeric', timeZone: 'UTC' })}
                    </span>
                  </div>
                  <div className="stack event-body">
                    <div className="row wrap event-title-row">
                      <b>{ev.title}</b>
                    </div>
                    <div className="small muted">
                      {hours ? `${dayRange(ev)} · ${hours}` : dayRange(ev)}
                    </div>
                  </div>
                  {renderAction && <div className="event-actions">{renderAction(ev)}</div>}
                </li>
              );
            })}
          </ul>
        )}

        {pageCount > 1 && (
          <div className="cal-pager">
            <button
              className="cal-nav"
              onClick={() => setPage((p) => Math.max(0, p - 1))}
              disabled={page === 0}
              aria-label="Previous dates"
            >
              ‹
            </button>
            <span className="cal-count">
              {from}–{to} of {inMonth.length}
            </span>
            <button
              className="cal-nav"
              onClick={() => setPage((p) => Math.min(pageCount - 1, p + 1))}
              disabled={page >= pageCount - 1}
              aria-label="More dates"
            >
              ›
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

import { useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import type { ProfileEvent } from '../lib/events';
import { ampmTime, dayRange } from '../lib/events';

/**
 * A date read, not written: the owner's event sheet with every control taken
 * out. A rider and a signed-out visitor both open it — neither one owns the
 * date — so it names what is on and stops. No Save, no Remove, no field to
 * type into: the values sit in the same wells the owner's own sheet uses, so
 * a reader sees the same modal, reading rather than editing.
 *
 * The one fact the owner's sheet keeps to itself is `isActive`: the public
 * reads serve active dates only, so there is no Shown row here to lie with.
 * Escape, the backdrop and the Close button all put it away.
 */
export default function EventReadSheet({
  event,
  venue,
  onClose,
}: {
  event: ProfileEvent;
  /**
   * The venue the date is at, when the reader is looking at more than one —
   * a rider's week holds every track they follow.
   */
  venue?: { name: string; slug: string } | null;
  onClose: () => void;
}) {
  const panel = useRef<HTMLDivElement>(null);

  useEffect(() => {
    panel.current?.focus();
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  const from = event.startMinutes;
  const to = event.endMinutes;
  // The hours are a pair, so a date either carries both or reads all-day — the
  // same read `ampmLabel` makes of it on a card.
  const timed = from != null || to != null;
  const length = from != null && to != null && to > from ? to - from : null;

  return (
    <div className="sheet-backdrop" onClick={onClose}>
      <div
        className="sheet event-sheet event-read"
        role="dialog"
        aria-modal="true"
        aria-labelledby="event-read-title"
        tabIndex={-1}
        ref={panel}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="row wrap spread event-read-head">
          <h4 className="sheet-title" id="event-read-title">
            {event.title}
          </h4>
        </div>

        {venue && (
          <Link className="event-read-venue" to={`/tracks/${venue.slug}`}>
            {venue.name}
          </Link>
        )}

        {/* The same fields the owner's sheet holds, read back with the values
            already in them: Date · From · To on one row, then the sentence
            they add up to, then the note. */}
        <div className="ev-form">
          <div className={timed ? 'ev-row-3' : undefined}>
            <div className="ev-field">
              <div className="ev-label">Date</div>
              <div className="ev-well">
                <div className="ev-value">{dayRange(event)}</div>
              </div>
            </div>
            {timed && (
              <div className="ev-field">
                <div className="ev-label">From</div>
                <div className="ev-well">
                  <div className="ev-value">{from != null ? ampmTime(from) : 'All day'}</div>
                </div>
              </div>
            )}
            {timed && (
              <div className="ev-field">
                <div className="ev-label">To</div>
                <div className="ev-well">
                  <div className="ev-value">{to != null ? ampmTime(to) : 'All day'}</div>
                </div>
              </div>
            )}
          </div>

          <div className="ev-readback">
            <p className="ev-note">{readSentence(event, timed, from, to)}</p>
            {length != null && <span className="ev-span">{spanLabel(length)}</span>}
          </div>

          {event.description && (
            <div className="ev-field">
              <div className="ev-label">Description</div>
              <div className="ev-well">
                <div className="ev-value">{event.description}</div>
              </div>
            </div>
          )}
        </div>

        <div className="row">
          <button className="ghost small" onClick={onClose}>
            Close
          </button>
        </div>
      </div>
    </div>
  );
}

/** `3h 45m`, `45m`, `2h` — how long a gate runs, the short way. */
function spanLabel(minutes: number) {
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return [h ? `${h}h` : '', m ? `${m}m` : ''].filter(Boolean).join(' ');
}

/** The date said the way the owner's own sheet says it, in a reader's words. */
function readSentence(ev: ProfileEvent, timed: boolean, from: number | null, to: number | null) {
  const when = dayRange(ev);
  if (!timed) return `All day on ${when}.`;
  if (from != null && to != null) return `From ${ampmTime(from)} until ${ampmTime(to)}, ${when}.`;
  if (from != null) return `Opens ${ampmTime(from)}, ${when}.`;
  return `Closes ${ampmTime(to!)}, ${when}.`;
}

import { useEffect, useRef, useState } from 'react';
import { api } from '../lib/api';

/** How long the click's one authored moment runs: the longest of the punch,
 *  the glyph draw and the ring, with a little headroom. */
const PULSE_MS = 700;

/**
 * The follow toggle. Following a track is what a free account does with the
 * network, so the control is live on every tier; the server is the source of
 * truth and this only mirrors the last response. The glyph is a rider and a
 * plus — a plus while the track is outside the list, a check once it is in it.
 * `iconOnly` drops the label and leaves the glyph, for a control that sits on
 * a photo's corner.
 *
 * A click also lands the control: `pulse` carries the class that fires the
 * punch and the glyph's draw-in, so a card the server already had followed
 * opens without animating and only the click moves. The class is restarted on
 * every click — off and back on — so a repeat fires it again.
 */
export default function FollowButton({
  trackId,
  name,
  following,
  onChange,
  compact = false,
  iconOnly = false,
}: {
  trackId: string;
  name: string;
  following: boolean;
  onChange?: (following: boolean) => void;
  compact?: boolean;
  iconOnly?: boolean;
}) {
  const [on, setOn] = useState(following);
  const [busy, setBusy] = useState(false);
  const [pulse, setPulse] = useState(false);
  const pulseTimer = useRef<number | undefined>(undefined);

  /**
   * The control outlives the venue it names: the inspector over the map keeps
   * one instance and re-points it at whichever venue is picked next, so the
   * flag mirrored from the last one would stand on every venue that follows —
   * a rider who follows one track would read every other track as followed
   * too. Mirror the prop again whenever the venue changes or the server's own
   * flag lands.
   */
  useEffect(() => {
    setOn(following);
  }, [trackId, following]);

  useEffect(() => () => window.clearTimeout(pulseTimer.current), []);

  const toggle = async () => {
    setBusy(true);
    const next = !on;
    const res = next
      ? await api.post<{ following: boolean }>(`/me/follows/${trackId}`)
      : await api.del<{ following: boolean }>(`/me/follows/${trackId}`);
    setBusy(false);
    if (!res.success) return;
    setOn(next);
    onChange?.(next);
    /* Drop the class, then re-add it on the next frame: the computed animation
       goes to `none` and back, so the moment runs even on a rapid repeat. */
    setPulse(false);
    window.clearTimeout(pulseTimer.current);
    window.requestAnimationFrame(() => {
      setPulse(true);
      pulseTimer.current = window.setTimeout(() => setPulse(false), PULSE_MS);
    });
  };

  return (
    <button
      type="button"
      className={`follow-toggle ${on ? 'on' : ''} ${pulse ? 'pulse' : ''} ${
        compact ? 'compact' : ''
      } ${iconOnly ? 'icon-only' : ''}`}
      aria-pressed={on}
      aria-label={on ? `Following ${name}` : `Follow ${name}`}
      title={on ? `Following ${name}` : `Follow ${name}`}
      disabled={busy}
      onClick={toggle}
    >
      <svg width="13" height="13" viewBox="0 0 16 16" aria-hidden="true">
        {/* The rider: a head over a shoulder line. */}
        <circle
          cx="4.8"
          cy="4.8"
          r="2.4"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.3"
        />
        <path
          d="M0.9 13.3c0-2.3 1.75-4 3.9-4s3.9 1.7 3.9 4"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.3"
          strokeLinecap="round"
        />
        {/* The action: add the track, or mark that it is already in the list. */}
        {on ? (
          <path
            d="M9.9 10.4l1.6 1.7 3.3-4"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        ) : (
          <path
            d="M12.5 7.8v5M10.1 10.3h5"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
          />
        )}
      </svg>
      {!iconOnly && <span>{on ? 'Following' : 'Follow'}</span>}
    </button>
  );
}

