import { useRef, useState, type DragEvent } from 'react';
import { api } from '../lib/api';
import PhotoLightbox from './PhotoLightbox';
import { dropSide, insertAt, reorder } from '../lib/dragReorder';

export interface OwnerPhoto {
  id: string;
  url: string;
  caption: string | null;
  category: string;
}

const CATEGORIES = ['TRACK', 'FACILITY', 'RACE_DAY'];
const CATEGORY_LABEL: Record<string, string> = {
  TRACK: 'Track',
  FACILITY: 'Facility',
  RACE_DAY: 'Race day',
};

const MAX_PHOTOS = 24;

/**
 * The venue's photo gallery in the owner console.
 *
 * The first photo is the one the public page opens on, so order is the whole
 * point of this panel: move a frame up and it moves up there. Order can be
 * changed three ways — the arrows on each row, dragging a row by its grip, and
 * dragging the frames in the full-screen viewer — and all of them save the same
 * way, by posting the whole id list.
 *
 * Adding accepts a file (read to a data URL and stored under /api/uploads) or a
 * URL to an image already hosted elsewhere, the same two ways the banner picker
 * works.
 */
export default function GalleryManager({
  photos,
  trackId,
  onChange,
  onMessage,
}: {
  photos: OwnerPhoto[];
  /** Only sent so an admin editing another venue resolves the right one. */
  trackId?: string;
  onChange: (photos: OwnerPhoto[]) => void;
  onMessage: (msg: string) => void;
}) {
  const fileRef = useRef<HTMLInputElement>(null);
  const [url, setUrl] = useState('');
  const [busy, setBusy] = useState(false);
  // Which frame the operator has opened full screen, if any.
  const [viewing, setViewing] = useState<number | null>(null);
  // Dragging a row: which one is in hand, and which gap it would land in.
  const [dragFrom, setDragFrom] = useState<number | null>(null);
  const [dropAt, setDropAt] = useState<{ index: number; side: 'before' | 'after' } | null>(null);

  const withTrack = (body: Record<string, unknown>) => (trackId ? { ...body, trackId } : body);

  const add = async (payload: { dataUrl?: string; url?: string }) => {
    setBusy(true);
    const res = await api.post<{ photo: OwnerPhoto }>('/owner/track/photos', withTrack(payload));
    setBusy(false);
    onMessage(res.message ?? (res.success ? 'Photo added.' : 'Could not add that photo.'));
    if (res.success && res.data?.photo) {
      onChange([...photos, res.data.photo]);
      setUrl('');
    }
  };

  const pickFile = async (file: File) => {
    const dataUrl = await new Promise<string>((resolve, reject) => {
      const fr = new FileReader();
      fr.onload = () => resolve(String(fr.result));
      fr.onerror = () => reject(new Error('Could not read that file.'));
      fr.readAsDataURL(file);
    }).catch(() => '');
    if (fileRef.current) fileRef.current.value = '';
    if (!dataUrl) {
      onMessage('Could not read that file.');
      return;
    }
    await add({ dataUrl });
  };

  const edit = async (id: string, patch: { category?: string; caption?: string }) => {
    onChange(photos.map((p) => (p.id === id ? { ...p, ...patch } : p)));
    const res = await api.patch(`/owner/track/photos/${id}`, withTrack(patch));
    if (!res.success) onMessage(res.message ?? 'Could not save that photo.');
  };

  /**
   * Put the frame at `from` into the gap at `toInsert` (0…length, in the list as
   * it stands now). The open frame in the viewer is followed across the move, so
   * a drag never swaps the photo out from under the operator.
   */
  const moveTo = async (from: number, toInsert: number) => {
    const { items: next, moved } = reorder(photos, from, toInsert);
    if (next.every((p, i) => p.id === photos[i].id)) return;
    onChange(next);
    setViewing((v) => (v === null ? v : moved[v] ?? v));
    const res = await api.post('/owner/track/photos/reorder', withTrack({ ids: next.map((p) => p.id) }));
    if (!res.success) onMessage(res.message ?? 'Could not reorder the gallery.');
  };

  const move = (index: number, by: number) => moveTo(index, index + (by > 0 ? 2 : -1));

  const endDrag = () => {
    setDragFrom(null);
    setDropAt(null);
  };

  const dragOver = (e: DragEvent<HTMLDivElement>, index: number) => {
    if (dragFrom === null) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    const side = dropSide(e, e.currentTarget.getBoundingClientRect());
    setDropAt((prev) => (prev && prev.index === index && prev.side === side ? prev : { index, side }));
  };

  const drop = (e: DragEvent<HTMLDivElement>) => {
    if (dragFrom === null || !dropAt) return;
    e.preventDefault();
    const to = insertAt(dropAt.index, dropAt.side);
    endDrag();
    // Dropping a frame onto either side of itself is a no-op, not a save.
    if (to !== dragFrom && to !== dragFrom + 1) moveTo(dragFrom, to);
  };

  const remove = async (id: string) => {
    const res = await api.del(`/owner/track/photos/${id}${trackId ? `?trackId=${trackId}` : ''}`);
    onMessage(res.message ?? (res.success ? 'Photo removed.' : 'Could not remove that photo.'));
    if (res.success) {
      onChange(photos.filter((p) => p.id !== id));
      setViewing(null);
    }
  };

  return (
    <section className="card stack">
      <h3>Photos</h3>
      <p className="small muted" style={{ margin: 0 }}>
        The first frame is what the venue page opens on. Drag a frame by its grip to reorder. {photos.length} of{' '}
        {MAX_PHOTOS}.
      </p>

      {photos.length === 0 && <div className="small muted">No photos yet. The page falls back to the banner.</div>}

      <div className="gallery-manager">
        {photos.map((p, i) => (
          <div
            key={p.id}
            className={[
              'gallery-row',
              dragFrom === i ? 'dragging' : '',
              dropAt && dropAt.index === i && dragFrom !== null ? `drop-${dropAt.side}` : '',
            ]
              .filter(Boolean)
              .join(' ')}
            onDragOver={(e) => dragOver(e, i)}
            onDragLeave={() => setDropAt((prev) => (prev && prev.index === i ? null : prev))}
            onDrop={drop}
          >
            <button
              type="button"
              className="gallery-grip"
              draggable
              onDragStart={(e) => {
                setDragFrom(i);
                e.dataTransfer.effectAllowed = 'move';
                // Firefox only starts a drag with some data set.
                e.dataTransfer.setData('text/plain', p.id);
              }}
              onDragEnd={endDrag}
              aria-label={`Drag photo ${i + 1} to reorder`}
              title="Drag to reorder"
            >
              <svg width="10" height="16" viewBox="0 0 10 16" aria-hidden="true" fill="currentColor">
                <circle cx="3" cy="4" r="1.2" />
                <circle cx="7" cy="4" r="1.2" />
                <circle cx="3" cy="8" r="1.2" />
                <circle cx="7" cy="8" r="1.2" />
                <circle cx="3" cy="12" r="1.2" />
                <circle cx="7" cy="12" r="1.2" />
              </svg>
            </button>
            <div className="gallery-thumb">
              <button
                type="button"
                className="gallery-thumb-open"
                onClick={() => setViewing(i)}
                aria-label={`Open photo ${i + 1} full screen`}
                title="Open full screen"
              >
                <img src={p.url} alt="" draggable={false} />
              </button>
            </div>
            <div className="gallery-fields">
              <select
                value={p.category}
                onChange={(e) => edit(p.id, { category: e.target.value })}
                aria-label="Photo category"
              >
                {CATEGORIES.map((c) => (
                  <option key={c} value={c}>
                    {CATEGORY_LABEL[c]}
                  </option>
                ))}
              </select>
              <input
                placeholder="Caption (optional)"
                defaultValue={p.caption ?? ''}
                onBlur={(e) => {
                  if ((e.target.value || '') !== (p.caption ?? '')) edit(p.id, { caption: e.target.value });
                }}
              />
            </div>
            <div className="row gallery-row-actions">
              {i === 0 && <span className="tiny muted">Opening frame</span>}
              <button type="button" className="ghost small" disabled={i === 0} onClick={() => move(i, -1)}>
                ↑
              </button>
              <button
                type="button"
                className="ghost small"
                disabled={i === photos.length - 1}
                onClick={() => move(i, 1)}
              >
                ↓
              </button>
              <button type="button" className="ghost small danger" onClick={() => remove(p.id)}>
                Remove
              </button>
            </div>
          </div>
        ))}
      </div>

      {viewing !== null && photos[viewing] && (
        <PhotoLightbox
          photos={photos}
          name="Gallery"
          index={viewing}
          onIndex={setViewing}
          onClose={() => setViewing(null)}
          onReorder={moveTo}
        />
      )}

      <div className="row wrap image-picker-controls">
        <input
          ref={fileRef}
          type="file"
          accept="image/png,image/jpeg,image/webp,image/gif,image/avif"
          style={{ display: 'none' }}
          onChange={(e) => {
            const f = e.target.files?.[0];
            if (f) pickFile(f);
          }}
        />
        <button
          type="button"
          className="ghost small"
          disabled={busy || photos.length >= MAX_PHOTOS}
          onClick={() => fileRef.current?.click()}
        >
          {busy ? 'Adding…' : 'Add a photo'}
        </button>
        <input
          className="image-url"
          placeholder="…or paste an image URL"
          value={url}
          onChange={(e) => setUrl(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && url.trim()) add({ url: url.trim() });
          }}
        />
        <button
          type="button"
          className="ghost small"
          disabled={busy || !url.trim() || photos.length >= MAX_PHOTOS}
          onClick={() => add({ url: url.trim() })}
        >
          Add from URL
        </button>
      </div>
    </section>
  );
}

import { ReactNode, useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../lib/auth';
import { useNetworkSearch } from '../lib/networkSearch';
import type { MapTrack } from '../lib/trackAccess';

/** How many matches the panel lists before it leaves the rest to the rail. */
const MAX_RESULTS = 8;

/** The parts of `text` the tokens landed on, drawn as one run each. */
function Highlight({ text, query }: { text: string; query: string }) {
  const marks = useMemo(() => {
    const flags = new Array<boolean>(text.length).fill(false);
    const lower = text.toLowerCase();
    for (const token of query.toLowerCase().split(/\s+/).filter(Boolean)) {
      let from = 0;
      let at = lower.indexOf(token, from);
      while (at !== -1) {
        for (let i = at; i < at + token.length; i += 1) flags[i] = true;
        from = at + token.length;
        at = lower.indexOf(token, from);
      }
    }
    return flags;
  }, [text, query]);

  if (!marks.some(Boolean)) return <>{text}</>;

  const parts: ReactNode[] = [];
  let i = 0;
  while (i < text.length) {
    const on = marks[i];
    let j = i;
    while (j < text.length && marks[j] === on) j += 1;
    const chunk = text.slice(i, j);
    parts.push(on ? <mark className="hs-hit" key={i}>{chunk}</mark> : chunk);
    i = j;
  }
  return <>{parts}</>;
}

/**
 * The network search, in the app header: one field that reaches every partner
 * venue from anywhere in the app, and that the network page's rail narrows by
 * too. The panel under it is the field's own read of what was typed — the
 * ranked matches, a name at a time, with where each one is — and picking one
 * opens that venue on the network page.
 *
 * A query is read as tokens that all have to land (see `matchTracks`), so the
 * field answers "top nc", "motocross" and "open" as readily as a name. Keyboard:
 * `/` reaches the field from anywhere, the arrows walk the matches, Enter opens
 * the one under the cursor, Escape empties the field then puts the panel away.
 * Riders and visitors read the network; the operator and admin consoles have
 * their own tables, so the field is not theirs.
 *
 * Collapsed, the search is one icon in the header — clicking it lays the field
 * out in its place and hands it the caret. Clicking away (or Escape on an empty
 * field) folds it back to the icon; a query that is still typed keeps the field
 * open, since the rail is narrowing by it.
 */
export default function HeaderSearch() {
  const { user } = useAuth();
  const { tracks, loading, ensure, q, setQ, results } = useNetworkSearch();
  const nav = useNavigate();
  const [expanded, setExpanded] = useState(false);
  const [open, setOpen] = useState(false);
  const [ix, setIx] = useState(0);
  const wrap = useRef<HTMLDivElement>(null);
  const field = useRef<HTMLInputElement>(null);
  const wantFocus = useRef(false);

  const needle = q.trim();
  const shown = results.slice(0, MAX_RESULTS);
  const listing = expanded && open && Boolean(needle);

  // A fresh query starts its cursor at the best match.
  useEffect(() => setIx(0), [q]);

  // Opening the field hands it the caret once it is actually on the page.
  useEffect(() => {
    if (!expanded || !wantFocus.current) return;
    wantFocus.current = false;
    field.current?.focus();
  }, [expanded]);

  /** Show the field (it is the one icon until then) and put the caret in it. */
  const reveal = () => {
    ensure();
    if (expanded) {
      setOpen(true);
      field.current?.focus();
      return;
    }
    wantFocus.current = true;
    setExpanded(true);
  };

  // A click outside puts the panel away — and, with nothing typed, the field
  // itself: the header goes back to the one icon the search collapsed to.
  useEffect(() => {
    if (!expanded) return;
    const away = (e: MouseEvent) => {
      if (wrap.current?.contains(e.target as Node)) return;
      setOpen(false);
      if (!q.trim()) setExpanded(false);
    };
    document.addEventListener('mousedown', away);
    return () => document.removeEventListener('mousedown', away);
  }, [expanded, q]);

  // "/" reaches the field from anywhere on the page, unless a field has it.
  useEffect(() => {
    const key = (e: KeyboardEvent) => {
      if (e.key !== '/' || e.metaKey || e.ctrlKey || e.altKey) return;
      const el = document.activeElement as HTMLElement | null;
      if (el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.isContentEditable)) return;
      e.preventDefault();
      reveal();
    };
    document.addEventListener('keydown', key);
    return () => document.removeEventListener('keydown', key);
  }, [ensure, expanded]);

  /** Open a venue on the network page; the query has done its job. */
  const openTrack = (track: MapTrack) => {
    setQ('');
    setOpen(false);
    setExpanded(false);
    nav(`/tracks?track=${track.slug}`);
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Escape') {
      if (needle) setQ('');
      else {
        setOpen(false);
        setExpanded(false);
      }
      return;
    }
    if (!needle || !shown.length) return;
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setIx((i) => Math.min(i + 1, shown.length - 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setIx((i) => Math.max(i - 1, 0));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      openTrack(shown[Math.min(ix, shown.length - 1)].track);
    }
  };

  if (user && user.role !== 'RIDER') return null;

  return (
    <div className={`header-search${expanded ? '' : ' collapsed'}`} ref={wrap}>
      {expanded ? (
        <>
          <svg className="hs-mark" viewBox="0 0 16 16" aria-hidden="true">
            <circle cx="7" cy="7" r="4.25" />
            <path d="M10.3 10.3 14 14" />
          </svg>

          <input
            ref={field}
            type="search"
            className="hs-field"
            value={q}
            placeholder="Search tracks"
            aria-label="Search tracks by name, location, type or status"
            role="combobox"
            aria-expanded={listing}
            aria-controls="hs-results"
            aria-autocomplete="list"
            aria-activedescendant={listing && shown[ix] ? `hs-opt-${shown[ix].track.id}` : undefined}
            onChange={(e) => {
              setQ(e.target.value);
              setOpen(true);
            }}
            onFocus={() => {
              ensure();
              setOpen(true);
            }}
            onKeyDown={onKeyDown}
          />

          {q && (
            <button
              type="button"
              className="hs-clear"
              aria-label="Clear search"
              onClick={() => {
                setQ('');
                field.current?.focus();
              }}
            >
              <svg viewBox="0 0 16 16" aria-hidden="true">
                <path d="M4.5 4.5 11.5 11.5M11.5 4.5 4.5 11.5" />
              </svg>
            </button>
          )}
        </>
      ) : (
        <button
          type="button"
          className="hs-trigger"
          aria-label="Search tracks"
          title="Search tracks"
          onClick={reveal}
        >
          <svg viewBox="0 0 16 16" aria-hidden="true">
            <circle cx="7" cy="7" r="4.25" />
            <path d="M10.3 10.3 14 14" />
          </svg>
        </button>
      )}

      {listing && (
        <div className="hs-panel" id="hs-results" role="listbox" aria-label="Matching tracks">
          {results.length > 0 && (
            <div className="hs-summary">
              {results.length} of {tracks.length}
            </div>
          )}

          {shown.length ? (
            shown.map((m, i) => (
              <button
                key={m.track.id}
                id={`hs-opt-${m.track.id}`}
                type="button"
                role="option"
                aria-selected={i === ix}
                className={`hs-row${i === ix ? ' on' : ''}`}
                onMouseEnter={() => setIx(i)}
                onClick={() => openTrack(m.track)}
              >
                <span className="hs-name">
                  <Highlight text={m.track.name} query={needle} />
                </span>
                <span className="hs-where">
                  <Highlight
                    text={[m.track.city, m.track.region].filter(Boolean).join(', ')}
                    query={needle}
                  />
                </span>
              </button>
            ))
          ) : (
            <div className="hs-empty">
              {loading ? 'Reading the network…' : `No tracks match "${needle}".`}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { api, dateTimeStr, dayStr, money } from '../lib/api';
import { SortTh, useSorted } from './sortable';
import TrackName from './TrackName';

interface Redemption {
  id: string;
  trackName: string;
  trackWebsite: string | null;
  kind: string;
  day: string;
  redeemedAt: string;
  amountChargedCents: number;
}

/**
 * The rider's redeemed days, as a table. Blocked scans are a gate-side surface:
 * they belong to the operator dashboard (`/operator/dashboard`), not the rider's pages,
 * so nothing here reads `/me/denied-scans`.
 *
 * On My Pass these same rows sit under their track inside the day-block grid
 * (`DaysByTrack`); this standalone section is what `/tracks/history` renders.
 */
export default function HistorySection() {
  const [redemptions, setRedemptions] = useState<Redemption[]>([]);
  const [loading, setLoading] = useState(true);

  const { sorted: days, sort: sortDays, toggle: toggleDays } = useSorted(redemptions, {
    day: (r) => r.day,
    track: (r) => r.trackName,
    type: (r) => r.kind,
    paid: (r) => r.amountChargedCents,
    redeemed: (r) => r.redeemedAt,
  });

  useEffect(() => {
    api
      .get<{ redemptions: Redemption[] }>('/me/history')
      .then((h) => setRedemptions(h.data?.redemptions ?? []))
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <div className="muted">Loading history…</div>;

  return (
    <div className="table-block">
      <div className="table-head">
        <h3>Redeemed days</h3>
        <span className="tiny muted">{redemptions.length} total</span>
      </div>
      <div className="card" style={{ padding: 0 }}>
      <div className="table-scroll">
        <table>
        <thead>
          <tr>
            <SortTh sortKey="day" sort={sortDays} onSort={toggleDays}>Day</SortTh>
            <SortTh sortKey="track" sort={sortDays} onSort={toggleDays}>Track</SortTh>
            <SortTh sortKey="type" sort={sortDays} onSort={toggleDays}>Type</SortTh>
            <SortTh sortKey="paid" sort={sortDays} onSort={toggleDays} className="right">Paid at track</SortTh>
            <SortTh sortKey="redeemed" sort={sortDays} onSort={toggleDays}>Redeemed</SortTh>
          </tr>
        </thead>
        <tbody>
          {days.map((r) => (
            <tr key={r.id}>
              <td>{dayStr(r.day)}</td>
              <td>
                <TrackName name={r.trackName} website={r.trackWebsite} />
              </td>
              <td>
                <span className={`pill ${r.kind === 'DISCOUNT' ? 'warn' : 'ok'}`}>
                  {r.kind}
                </span>
              </td>
              <td className="right">{r.amountChargedCents ? money(r.amountChargedCents) : '—'}</td>
              <td className="small muted">{dateTimeStr(r.redeemedAt)}</td>
            </tr>
          ))}
          {!redemptions.length && (
            <tr>
              <td colSpan={5} className="muted small">
                No redeemed days yet.
              </td>
            </tr>
          )}
        </tbody>
        </table>
      </div>
      </div>
    </div>
  );
}

import {
  HOURS_CLOSED,
  HOURS_WEEK_DAYS,
  todayHoursKey,
  type HoursWeek as Week,
} from '../lib/hoursWeek';
import { TRACK_STATUS_CLASS, statusLabel } from '../lib/trackAccess';

/**
 * The venue's week on its profile: one line per day, with the day the reader is
 * on marked, so "can I ride today" is answered without counting rows. The live
 * venue status rides on today's own line, and a shut today says when the week
 * opens again — both read off fields on file, never a computed open/close time
 * (the week is free text, so there is no time in it to count down from).
 *
 * A venue with no week on file falls back to the single hours line the network
 * rail already reads, rather than showing seven empty days.
 */
export default function HoursWeek({
  week,
  summary,
  status,
}: {
  week: Week | null;
  summary?: string | null;
  /** The venue's live status (OPEN / WEATHER_HOLD / CLOSED) — drawn on today. */
  status?: string | null;
}) {
  if (!week) {
    if (!summary) return null;
    return (
      <section className="stack hours-week-block">
        <h3>Hours</h3>
        <p className="hours-summary">{summary}</p>
      </section>
    );
  }

  const today = todayHoursKey();
  const todayIndex = HOURS_WEEK_DAYS.findIndex(({ key }) => key === today);
  const todayValue = week[today] || HOURS_CLOSED;
  const running = todayValue !== HOURS_CLOSED;

  // The next day the week runs, counting forward from today — the honest answer
  // to "when does it open again" while the week carries no times.
  let reopen: (typeof HOURS_WEEK_DAYS)[number] | null = null;
  if (!running) {
    for (let step = 1; step <= 7; step++) {
      const day = HOURS_WEEK_DAYS[(todayIndex + step) % 7];
      if ((week[day.key] || HOURS_CLOSED) !== HOURS_CLOSED) {
        reopen = day;
        break;
      }
    }
  }

  return (
    <section className="stack hours-week-block">
      <h3>Hours</h3>
      <dl className="hours-week">
        {HOURS_WEEK_DAYS.map(({ key, label, full }) => {
          const value = week[key] || HOURS_CLOSED;
          const isToday = key === today;
          return (
            <div key={key} className={isToday ? 'hours-row is-today' : 'hours-row'}>
              <dt>
                <abbr title={full}>{label}</abbr>
              </dt>
              <dd className={value === HOURS_CLOSED ? 'hours-value is-closed' : 'hours-value'}>
                {value}
              </dd>
              {/* The live status, on the one row it belongs to: a venue running
                  today says so, and the pill's own class carries the state. */}
              {isToday && running && status && (
                <span className={`status-pill ${TRACK_STATUS_CLASS[status] ?? 'status-open'}`}>
                  {status === 'OPEN' ? 'Open now' : statusLabel(status)}
                </span>
              )}
            </div>
          );
        })}
      </dl>
      {reopen && (
        <p className="hours-reopen small muted">
          Reopens {reopen.full} · {week[reopen.key]}
        </p>
      )}
    </section>
  );
}

import { useRef, useState } from 'react';
import { api } from '../lib/api';

/**
 * One image slot in the track-profile console — the banner or the logo.
 *
 * Two ways in, because an owner may have the art in either place: pick a file
 * (it is read to a data URL, POSTed to /owner/track/assets and comes back as a
 * path under /api/uploads) or paste a URL to an image already hosted elsewhere.
 * Either way the value that is kept on the track is a URL.
 */
export default function ImagePicker({
  label,
  kind,
  value,
  trackId,
  onChange,
  wide = false,
}: {
  label: string;
  kind: 'banner' | 'logo';
  value: string | null;
  /** Only sent so an admin editing another track resolves the right one. */
  trackId?: string;
  onChange: (url: string | null) => void;
  wide?: boolean;
}) {
  const fileRef = useRef<HTMLInputElement>(null);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  const upload = async (file: File) => {
    setErr(null);
    setBusy(true);
    try {
      const dataUrl = await new Promise<string>((resolve, reject) => {
        const fr = new FileReader();
        fr.onload = () => resolve(String(fr.result));
        fr.onerror = () => reject(new Error('Could not read that file.'));
        fr.readAsDataURL(file);
      });
      const res = await api.post<{ url: string }>('/owner/track/assets', {
        kind,
        dataUrl,
        ...(trackId ? { trackId } : {}),
      });
      if (!res.success || !res.data?.url) {
        setErr(res.message || 'Upload failed.');
        return;
      }
      onChange(res.data.url);
    } catch (e) {
      setErr(e instanceof Error ? e.message : 'Upload failed.');
    } finally {
      setBusy(false);
      if (fileRef.current) fileRef.current.value = '';
    }
  };

  return (
    <div className="stack image-picker">
      <label>{label}</label>
      <div className={`image-preview ${wide ? 'wide' : 'square'}`}>
        {value ? <img src={value} alt="" /> : <span className="tiny muted">No image</span>}
      </div>
      <div className="row wrap image-picker-controls">
        <input
          ref={fileRef}
          type="file"
          accept="image/png,image/jpeg,image/webp,image/gif,image/avif"
          style={{ display: 'none' }}
          onChange={(e) => {
            const f = e.target.files?.[0];
            if (f) upload(f);
          }}
        />
        <button type="button" className="ghost small" disabled={busy} onClick={() => fileRef.current?.click()}>
          {busy ? 'Uploading…' : 'Upload image'}
        </button>
        {value && (
          <button type="button" className="ghost small" onClick={() => onChange(null)}>
            Clear
          </button>
        )}
      </div>
      <input
        className="image-url"
        placeholder="…or paste an image URL"
        value={value ?? ''}
        onChange={(e) => onChange(e.target.value || null)}
      />
      {err && <div className="tiny bad-text">{err}</div>}
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import { NavLink, Outlet, useLocation } from 'react-router-dom';
import { useAuth } from '../lib/auth';
import { COMMUNITY_ENABLED } from '../lib/featureFlags';
import { NetworkSearchProvider } from '../lib/networkSearch';
import AccountMenu from './AccountMenu';
import AccentSwitcher from './AccentSwitcher';
import Footer from './Footer';
import HeaderSearch from './HeaderSearch';

export default function Layout() {
  const { user } = useAuth();
  const { pathname } = useLocation();

  /* The header rides over the page at rest and only takes on chrome once the
     page has moved under it — a bare scroll offset, so the read is the same on
     every route (ScrollToTop resets the offset on navigation, so each page
     opens transparent again). rAF-coalesced: scroll fires far more often than
     the browser paints. */
  const [scrolled, setScrolled] = useState(false);
  /* ...and while it is over the landing's hero it is over a *photograph*, which
     no palette can answer for: that one state takes light ink on a dark chrome
     in either theme (`--scrim-photo` / `.over-photo` in global.scss). */
  const [overHero, setOverHero] = useState(false);
  const headerRef = useRef<HTMLElement>(null);

  useEffect(() => {
    let frame = 0;
    const read = () => {
      frame = 0;
      setScrolled(window.scrollY > 8);
      /* The hero runs the whole first screen, so the header is over it until the
         page has scrolled clean past its foot. */
      const hero = pathname === '/' ? document.querySelector('.landing-hero') : null;
      const head = headerRef.current?.offsetHeight ?? 57;
      setOverHero(!!hero && hero.getBoundingClientRect().bottom >= head);
    };
    const onScroll = () => {
      if (!frame) frame = requestAnimationFrame(read);
    };
    read();
    /* A route opens at scroll 0, so nothing fires after the outgoing page's hero
       leaves and React mounts the next one — read again on a short ladder so the
       new page's own hero is seen. The band's height is a viewport unit, not a
       function of its data or its photograph, so a few beats is all it takes. */
    const ladder = [0, 150, 600, 1500].map((t) => setTimeout(read, t));
    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll);
    return () => {
      ladder.forEach(clearTimeout);
      window.removeEventListener('scroll', onScroll);
      window.removeEventListener('resize', onScroll);
      if (frame) cancelAnimationFrame(frame);
    };
  }, [pathname]);

  const links =
    user?.role === 'ADMIN'
      ? [
          { to: '/admin', label: 'Overview' },
          { to: '/admin/tracks', label: 'Tracks' },
          { to: '/admin/users', label: 'Users' },
          { to: '/admin/tiers', label: 'Tiers' },
          { to: '/admin/reports', label: 'Reports' },
          { to: '/admin/quickbooks', label: 'QuickBooks' },
          { to: '/operator/profile', label: 'Track profile' },
          { to: '/operator/calendar', label: 'Calendar' },
          ...(COMMUNITY_ENABLED ? [{ to: '/operator/community', label: 'Community' }] : []),
          { to: '/operator/dashboard', label: 'Dashboard' },
          { to: '/operator/reports', label: 'Reports' },
        ]
      : user?.role === 'OPERATOR'
        ? [
            { to: '/operator/dashboard', label: 'Dashboard' },
            { to: '/operator/reports', label: 'Reports' },
            { to: '/tracks', label: 'Tracks' },
            { to: '/operator/calendar', label: 'Calendar' },
            ...(COMMUNITY_ENABLED ? [{ to: '/operator/community', label: 'Community' }] : []),
          ]
        : user
          ? [
              { to: '/tracks', label: 'Tracks' },
              { to: '/tracks/calendar', label: 'Calendar' },
            ]
          : [
              { to: '/tracks', label: 'Tracks' },
              { to: '/pricing', label: 'Pricing' },
            ];

  return (
    <NetworkSearchProvider>
      <div style={{ minHeight: '100%', display: 'flex', flexDirection: 'column' }}>
        <header
          ref={headerRef}
          className={overHero ? 'app-header over-photo' : 'app-header'}
          style={{
            borderBottom: `1px solid ${
              scrolled ? (overHero ? 'var(--scrim-photo-line)' : 'var(--line)') : 'transparent'
            }`,
            position: 'sticky',
            top: 0,
            /* Transparent at rest; half-opacity surface + blur once the page
               has scrolled under it. Over the landing's photograph the chrome
               goes dark in either theme so the light ink keeps its contrast. */
            background: scrolled ? (overHero ? 'var(--scrim-photo)' : 'var(--scrim-half)') : 'transparent',
            backdropFilter: scrolled ? 'blur(12px)' : 'none',
            WebkitBackdropFilter: scrolled ? 'blur(12px)' : 'none',
            transition: 'background 200ms ease, border-color 200ms ease, backdrop-filter 200ms ease',
            /* Above the network map: Leaflet's panes (400) and controls (1000)
               are positioned with a z-index while the map pane is no stacking
               context, so they compete here at the root — the header's own
               dropdowns (the search panel, the account menu) have to clear
               them. Under the sheet (1200) and the toasts (1100). */
            zIndex: 1050,
          }}
        >
          <div
            className="row wrap"
            style={{ maxWidth: 1550, margin: '0 auto', padding: '10px 20px', gap: 16 }}
          >
            <div className="row" style={{ gap: 18, minWidth: 0 }}>
              <NavLink
                to="/"
                style={{ fontWeight: 700, letterSpacing: '-0.02em', whiteSpace: 'nowrap', color: 'var(--header-ink)' }}
              >
                Moto Pass
              </NavLink>
              <nav className="row wrap" style={{ gap: 14 }}>
                {links.map((l) => (
                  <NavLink
                    key={l.to}
                    to={l.to}
                    end
                    className="small"
                    style={({ isActive }) => ({
                      color: isActive ? 'var(--header-ink)' : 'var(--header-ink-muted)',
                      textDecoration: isActive ? 'underline' : 'none',
                      textUnderlineOffset: 4,
                    })}
                  >
                    {l.label}
                  </NavLink>
                ))}
              </nav>
            </div>

            {/* The network search rides in the shell, not the rail: one field
                answers for the whole app and narrows the network page with it.
                It sits on the brand's side of the row, not centred — only the
                account group is pushed over, so the row reads left to right. */}
            <HeaderSearch />

            <div className="row" style={{ gap: 10, whiteSpace: 'nowrap', marginLeft: 'auto' }}>
              {user ? (
                <AccountMenu />
              ) : (
                <NavLink to="/login">
                  <button className="small header-signin">Sign in</button>
                </NavLink>
              )}
            </div>
          </div>
        </header>

        {/* The page area always runs at least one screen past the header, so the
            footer starts exactly at the fold — out of sight until the reader
            scrolls for it. Short pages (the gate dashboard, a report with no
            rows) used to park the footer inside the first screen. */}
        <main
          style={{
            maxWidth: 1550,
            margin: '0 auto',
            padding: '22px 20px 60px',
            width: '100%',
            flex: 1,
            minHeight: 'calc(100svh - var(--header-h, 57px))',
          }}
        >
          <Outlet />
        </main>

        <footer>
          {/* .site-footer carries the rule and the tint; the shell just ends here. */}
          <Footer />
        </footer>

        {/* TEMPORARY: floating accent picker — remove with the component. */}
        <AccentSwitcher />
      </div>
    </NetworkSearchProvider>
  );
}

import { firstOfMonth } from '../lib/events';

/**
 * The month at the head of a schedule: six rows of days with a chevron either
 * side of the month's name.
 *
 * It keeps no state of its own — whoever draws it owns the month it is showing
 * — so the venue profile's read-only calendar and the owner's calendar page step
 * the same grid the same way. A day with dates on it fills and answers a pick;
 * every other day stays a quiet numeral.
 */
export interface CalDay {
  d: Date;
  key: string;
  inMonth: boolean;
}

interface Props {
  view: { year: number; month: number };
  days: CalDay[];
  /** Today, as `YYYY-MM-DD`, so a day can mark itself without a second clock. */
  today: string;
  /** How many dates fall on a day — `0` reads as a plain numeral. */
  countFor: (key: string) => number;
  /** The gate read posted for a day, when the operator set one. */
  statusFor?: (key: string) => string | null;
  /** The day the reader picked, or `null`. */
  picked?: string | null;
  onStep: (delta: number) => void;
  onPickDay: (key: string) => void;
}

const DOW = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];
const MONTH_FMT: Intl.DateTimeFormatOptions = { month: 'long', year: 'numeric', timeZone: 'UTC' };

export default function MonthGrid({ view, days, today, countFor, statusFor, picked, onStep, onPickDay }: Props) {
  return (
    <div className="cal">
      <div className="cal-head">
        <button className="cal-nav" onClick={() => onStep(-1)} aria-label="Previous month">
          ‹
        </button>
        <b className="cal-month">{firstOfMonth(view.year, view.month).toLocaleDateString(undefined, MONTH_FMT)}</b>
        <button className="cal-nav" onClick={() => onStep(1)} aria-label="Next month">
          ›
        </button>
      </div>

      <div className="cal-grid cal-dow" aria-hidden="true">
        {DOW.map((d, i) => (
          <span key={`${d}${i}`}>{d}</span>
        ))}
      </div>

      <div className="cal-grid cal-days">
        {days.map(({ d, key, inMonth }) => {
          const count = countFor(key);
          // The gate the operator posted for the day, when they posted one —
          // a scheduled Caution or Closed reads on the date itself.
          const gate = statusFor?.(key) ?? null;
          const label = d.toLocaleDateString(undefined, {
            weekday: 'long',
            month: 'long',
            day: 'numeric',
            timeZone: 'UTC',
          });
          const cls = [
            'cal-day',
            inMonth ? '' : 'is-out',
            key === today ? 'is-today' : '',
            key === picked ? 'is-picked' : '',
            gate ? `gate-${gate.toLowerCase()}` : '',
          ]
            .filter(Boolean)
            .join(' ');
          const gateWord = gate === 'OPEN' ? 'Open' : gate === 'CLOSED' ? 'Closed' : gate ? 'Caution' : '';
          return count > 0 ? (
            <button
              key={key}
              type="button"
              className={`${cls} has-event`}
              title={`${label}: ${count} ${count === 1 ? 'date' : 'dates'}${gateWord ? ` · ${gateWord}` : ''}`}
              aria-label={`${label}, ${count} ${count === 1 ? 'date' : 'dates'}${gateWord ? `, ${gateWord}` : ''}`}
              aria-pressed={key === picked}
              onClick={() => onPickDay(key)}
            >
              {d.getUTCDate()}
            </button>
          ) : gate ? (
            <span key={key} className={`${cls} has-gate`} title={`${label}: ${gateWord}`} aria-label={`${label}, ${gateWord}`}>
              {d.getUTCDate()}
            </span>
          ) : (
            <span key={key} className={cls}>
              {d.getUTCDate()}
            </span>
          );
        })}
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { api, money } from '../lib/api';

interface RangeSummary {
  checkins: number;
  riders: number;
  collectedCents: number;
  rideDays: number;
  perRideDay: number;
  repeatRiders: number;
  repeatRate: number;
  newRiders: number;
  avgVisits: number;
  scans: number;
  approved: number;
  denied: number;
  approvalRate: number | null;
}

interface TrackStats {
  trackName: string;
  trackSlug: string;
  seasonYear: number;
  asOf: string;
  range: { key: RangeKey; label: string; from: string; to: string };
  summary: RangeSummary;
  kinds: Record<string, number>;
  days: { day: string; checkins: number }[];
  weekday: { label: string; checkins: number }[];
  hours: { hour: number; checkins: number }[];
  topRiders: { name: string; visits: number; paidCents: number }[];
  denials: { code: string | null; reason: string | null; count: number }[];
  audience: {
    followers: number;
    upcoming: number;
    nextEvent: {
      title: string;
      kind: string;
      day: string;
      startMinutes: number | null;
      endMinutes: number | null;
    } | null;
  };
}

const KIND_LABEL: Record<string, string> = {
  FREE: 'included',
  DISCOUNT: 'discounted',
};

/** The timeframe pill: it owns the range every other option is read in. */
const RANGES = [
  { key: 'today', label: 'Today' },
  { key: 'season', label: 'Season' },
  { key: 'window', label: 'Last 30 days' },
] as const;
type RangeKey = (typeof RANGES)[number]['key'];

/** The view pill: the shape the selected range is read as. */
const VIEWS = [
  { key: 'summary', label: 'Overview' },
  { key: 'days', label: 'Busiest days' },
  { key: 'hours', label: 'Peak hours' },
  { key: 'riders', label: 'Riders' },
] as const;
type ViewKey = (typeof VIEWS)[number]['key'];

/** Gates open early: the fallback window the hourly read covers when a season
    has no check-ins yet, 6am through 6pm. */
const HOUR_FROM = 6;
const HOUR_TO = 18;

/** Hours of quiet kept around the venue's active window, at each end, so the
    gate's shape is read against the hours either side of it. */
const HOUR_PAD = 2;
/** The narrowest run worth drawing — a short working day of columns. */
const HOUR_MIN_SPAN = 8;

/**
 * The hours worth drawing: the venue's own active window, opened out by
 * HOUR_PAD hours at each end and never narrower than HOUR_MIN_SPAN columns. A
 * range with nothing at the gate falls back to the widened default.
 */
function hourWindow(hours: { hour: number; checkins: number }[]): { hour: number; checkins: number }[] {
  const active = hours.filter((h) => h.checkins > 0);
  if (!active.length) return hours.filter((h) => h.hour >= HOUR_FROM && h.hour <= HOUR_TO);
  let from = Math.max(0, active[0].hour - HOUR_PAD);
  let to = Math.min(23, active[active.length - 1].hour + HOUR_PAD);
  while (to - from + 1 < HOUR_MIN_SPAN) {
    if (to < 23) to += 1;
    else if (from > 0) from -= 1;
    else break;
  }
  return hours.filter((h) => h.hour >= from && h.hour <= to);
}

function hourLabel(h: number): string {
  if (h === 0) return '12a';
  if (h < 12) return `${h}a`;
  if (h === 12) return '12p';
  return `${h - 12}p`;
}

function shortDay(day: string): string {
  return new Date(`${day}T00:00:00Z`).toLocaleDateString(undefined, {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
    timeZone: 'UTC',
  });
}

/** How a range names itself under a card's heading. */
function rangeNote(range: { key: RangeKey; from: string; to: string }): string {
  if (range.key === 'today') return shortDay(range.to);
  if (range.key === 'season') return 'to date';
  return `${shortDay(range.from)} – ${shortDay(range.to)}`;
}

/** The range's own short name, for a card heading. */
function rangeHeading(key: RangeKey): string {
  return key === 'window' ? 'Last 30 days' : key === 'season' ? 'Season' : 'Today';
}

/** The range in the middle of a sentence. */
function rangeWords(key: RangeKey): string {
  return key === 'window' ? 'in the last 30 days' : key === 'season' ? 'this season' : 'today';
}

/** One labelled fact — the label left, the figure it names on the same line. */
function Fact({ label, value }: { label: string; value: string | number }) {
  return (
    <div>
      <dt>{label}</dt>
      <dd>{value}</dd>
    </div>
  );
}

/** A labelled column run: one column per bucket, the count over it and the
    bucket's name under it. A bucket with nothing keeps a stub so the gaps
    between the gate's busy hours stay legible. */
function ColumnRun({
  rows,
  max,
}: {
  rows: { key: string; label: string; count: number; title?: string }[];
  max: number;
}) {
  return (
    <div className="stat-vbars">
      {rows.map((r) => (
        <div
          key={r.key}
          className={`stat-vbar${r.count ? '' : ' is-empty'}`}
          title={r.title ?? `${r.label} · ${r.count}`}
        >
          <span className="stat-vbar-count">{r.count}</span>
          <span className="stat-vbar-track">
            <i style={{ height: r.count ? `${Math.max(4, (r.count / max) * 100)}%` : '3px' }} />
          </span>
          <span className="stat-vbar-label">{r.label}</span>
        </div>
      ))}
    </div>
  );
}

/**
 * The venue's operating read, on the operator's dashboard. Two pills: the
 * timeframe (today, the season, the trailing month) owns the range, and the
 * view beside it is read inside that range — so no figure on the right can
 * quote a season while the pill says a month. Every number is counted
 * server-side off the redemption + scan ledgers.
 */
export default function OperatorStats({
  trackId,
  reloadKey = 0,
}: {
  trackId?: string | null;
  reloadKey?: number;
}) {
  const [stats, setStats] = useState<TrackStats | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [range, setRange] = useState<RangeKey>('today');
  const [view, setView] = useState<ViewKey>('summary');

  useEffect(() => {
    let live = true;
    setLoadError(null);
    const q = new URLSearchParams({ range });
    if (trackId) q.set('trackId', trackId);
    api
      .get<TrackStats>(`/operator/stats?${q.toString()}`)
      .then((r) => {
        if (live && r.data) setStats(r.data);
      })
      .catch(() => {
        if (live) setLoadError('Could not load stats.');
      });
    return () => {
      live = false;
    };
  }, [trackId, reloadKey, range]);

  // A section that vanishes reads as a broken page; a quiet line keeps the
  // operator oriented while the read loads, or names the failure.
  if (!stats) {
    return (
      <section className="stats-section">
        <div className="stat-card small muted">{loadError ?? 'Loading track stats…'}</div>
      </section>
    );
  }

  const { summary } = stats;
  const maxWeekday = Math.max(1, ...stats.weekday.map((d) => d.checkins));
  const hourRows = hourWindow(stats.hours);
  const maxHour = Math.max(1, ...hourRows.map((h) => h.checkins));
  const maxDay = Math.max(1, ...stats.days.map((d) => d.checkins));
  const busiest = stats.days.length
    ? stats.days.reduce((a, b) => (b.checkins > a.checkins ? b : a), stats.days[0])
    : null;
  const kinds = Object.entries(stats.kinds).filter(([, n]) => n > 0);
  const note = rangeNote(stats.range);

  return (
    <section className="stats-section">
      <div className="stats-head">
        <div className="row wrap">
          <h2>Track stats</h2>
        </div>
        <div className="stats-pills">
          <div className="pill-toggle" role="group" aria-label="Timeframe">
            {RANGES.map((r) => (
              <button key={r.key} aria-pressed={range === r.key} onClick={() => setRange(r.key)}>
                {r.label}
              </button>
            ))}
          </div>
          <div className="pill-toggle" role="group" aria-label="View">
            {VIEWS.map((v) => (
              <button key={v.key} aria-pressed={view === v.key} onClick={() => setView(v.key)}>
                {v.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {view === 'summary' && (
        <div className="stat-card">
          <div className="stat-card-head">
            <h3>{rangeHeading(range)}</h3>
            <span className="tiny muted">{note}</span>
          </div>
          <dl className="fact-list">
            {range === 'today' ? (
              <>
                <Fact label="Riders in" value={summary.riders} />
                <Fact label="Check-ins" value={summary.checkins} />
                <Fact label="Collected at the window" value={money(summary.collectedCents)} />
                <Fact
                  label="Scans approved"
                  value={
                    summary.approvalRate == null
                      ? 'None yet'
                      : `${summary.approved} of ${summary.scans} · ${summary.approvalRate}%`
                  }
                />
                <Fact label="Turned away" value={summary.denied} />
              </>
            ) : (
              <>
                <Fact label="Check-ins" value={summary.checkins} />
                <Fact label="Riders" value={summary.riders} />
                <Fact
                  label="Came back"
                  value={`${summary.repeatRiders} of ${summary.riders} · ${summary.repeatRate}%`}
                />
                <Fact label="Riders a ride day" value={summary.perRideDay} />
                <Fact label="Collected at the window" value={money(summary.collectedCents)} />
                <Fact
                  label="First time here"
                  value={`${summary.newRiders} ${rangeWords(range)}`}
                />
              </>
            )}
          </dl>
          {range !== 'today' && !!kinds.length && (
            <div className="stat-mix tiny muted">
              {kinds.map(([k, n], i) => (
                <span key={k}>
                  {i > 0 && ' · '}
                  {n} {KIND_LABEL[k] ?? k.toLowerCase()}
                </span>
              ))}
            </div>
          )}
          {stats.days.length > 1 && busiest && (
            <>
              <div className="row spread tiny muted stat-day-run-head">
                <span>Busiest {busiest.checkins} on {shortDay(busiest.day)}</span>
                <span>{maxDay} in a day</span>
              </div>
              <div className="stat-cols">
                {stats.days.map((d) => (
                  <span
                    key={d.day}
                    className={`stat-col${d.checkins ? '' : ' is-empty'}`}
                    title={`${shortDay(d.day)} · ${d.checkins} check-ins`}
                  >
                    <i style={{ height: d.checkins ? `${Math.max(8, (d.checkins / maxDay) * 100)}%` : '3px' }} />
                  </span>
                ))}
              </div>
              <div className="stat-cols-axis tiny muted">
                <span>{shortDay(stats.days[0].day)}</span>
                <span>{shortDay(stats.days[Math.floor(stats.days.length / 2)].day)}</span>
                <span>{shortDay(stats.days[stats.days.length - 1].day)}</span>
              </div>
            </>
          )}
        </div>
      )}

      {view === 'days' && (
        <div className="stat-card">
          <div className="stat-card-head">
            <h3>Busiest days</h3>
            <span className="tiny muted">check-ins, {stats.range.label.toLowerCase()}</span>
          </div>
          <ColumnRun
            max={maxWeekday}
            rows={stats.weekday.map((d) => ({ key: d.label, label: d.label, count: d.checkins }))}
          />
        </div>
      )}

      {view === 'hours' && (
        <div className="stat-card">
          <div className="stat-card-head">
            <h3>Peak gate hours</h3>
            <span className="tiny muted">when riders arrive, {stats.range.label.toLowerCase()}</span>
          </div>
          <ColumnRun
            max={maxHour}
            rows={hourRows.map((h) => ({
              key: String(h.hour),
              label: hourLabel(h.hour),
              count: h.checkins,
            }))}
          />
        </div>
      )}

      {view === 'riders' && (
        <div className="stat-card">
          <div className="stat-card-head">
            <h3>Top riders</h3>
          </div>
          <div className="stat-rows">
            {stats.topRiders.map((r) => (
              <div className="stat-row" key={r.name}>
                <span className="stat-row-name">{r.name}</span>
                <span className="tiny muted">{r.paidCents ? money(r.paidCents) : '—'}</span>
                <span className="stat-bar-count">{r.visits}</span>
              </div>
            ))}
            {!stats.topRiders.length && (
              <div className="small muted">No riders {rangeWords(range)}.</div>
            )}
          </div>
        </div>
      )}
    </section>
  );
}

import { useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import QrPanel from './QrPanel';
import { dayStr } from '../lib/api';

/**
 * The pass QR on its own layer, so it can be held up at the gate without the
 * chrome that opened it — the account menu's, or the network rail's `Pass QR`
 * button. Escape or a click on the backdrop closes it.
 *
 * Portalled to the body on purpose: the app header carries `backdrop-filter`,
 * which makes it a containing block for fixed children, so an overlay rendered
 * in place would be trapped inside the header strip when opened from there.
 */
export default function PassQrSheet({
  active,
  expiresAt,
  status,
  onClose,
}: {
  active: boolean;
  expiresAt: string;
  status: string;
  onClose: () => void;
}) {
  const panel = useRef<HTMLDivElement>(null);

  useEffect(() => {
    panel.current?.focus();
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  return createPortal(
    <div className="sheet-backdrop" onClick={onClose}>
      <div
        className="sheet qr-sheet"
        role="dialog"
        aria-modal="true"
        aria-labelledby="pass-qr-title"
        tabIndex={-1}
        ref={panel}
        onClick={(e) => e.stopPropagation()}
      >
        <h2 className="sheet-title" id="pass-qr-title">
          Pass QR code
        </h2>
        <QrPanel active={active} bare />
        <div className="pass-id-foot">
          <span>
            Valid through <strong>{dayStr(expiresAt)}</strong>
            {!active && ` · ${status.toLowerCase()}`}
          </span>
        </div>
        <div className="sheet-actions">
          <button className="ghost" onClick={onClose}>
            Close
          </button>
        </div>
      </div>
    </div>,
    document.body
  );
}

import { useEffect, useRef, useState } from 'react';
import TrackName from './TrackName';

export interface SheetPerk {
  code: string;
  title: string;
  description: string | null;
  trackName: string | null;
  trackWebsite: string | null;
}

/**
 * How-to-redeem sheet for one offer: what the offer is, what the rider does with
 * it, the code to show, where it is good, and the single confirm that records the
 * redemption. Escape or a click on the backdrop closes it.
 */
export default function PerkSheet({
  perk,
  busy,
  onClose,
  onRedeem,
}: {
  perk: SheetPerk;
  busy: boolean;
  onClose: () => void;
  onRedeem: (code: string) => void;
}) {
  const [copied, setCopied] = useState(false);
  const panel = useRef<HTMLDivElement>(null);

  useEffect(() => {
    panel.current?.focus();
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(perk.code);
      setCopied(true);
      setTimeout(() => setCopied(false), 1600);
    } catch {
      /* Clipboard blocked — the code is still selectable in the box. */
    }
  };

  return (
    <div className="sheet-backdrop" onClick={onClose}>
      <div
        className="sheet"
        role="dialog"
        aria-modal="true"
        aria-labelledby="perk-sheet-title"
        tabIndex={-1}
        ref={panel}
        onClick={(e) => e.stopPropagation()}
      >
        <h2 className="sheet-title" id="perk-sheet-title">
          {perk.title}
        </h2>
        {perk.description && <p className="sheet-copy">{perk.description}</p>}

        <div className="sheet-code">
          <span className="sheet-code-value mono">{perk.code}</span>
          <button className="ghost small" onClick={copy}>
            {copied ? 'Copied' : 'Copy'}
          </button>
        </div>
        <div className="sheet-where small muted">
          Valid at{' '}
          {perk.trackName ? (
            <TrackName name={perk.trackName} website={perk.trackWebsite} />
          ) : (
            'any partner track or shop'
          )}
        </div>

        <div className="sheet-actions">
          <button className="ghost" onClick={onClose} disabled={busy}>
            Close
          </button>
          <button className="primary" onClick={() => onRedeem(perk.code)} disabled={busy}>
            {busy ? 'Redeeming…' : 'Redeem'}
          </button>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import Banner from './Banner';
import { api } from '../lib/api';
import PerkSheet from './PerkSheet';

interface Perk {
  id: string;
  code: string;
  title: string;
  description: string | null;
  discountType: string;
  value: number;
  trackName: string | null;
  trackWebsite: string | null;
  redeemed: boolean;
}

/**
 * Offers attached to the pass, one card per offer: the offer and a single redeem
 * action. Redeem opens a sheet carrying the how-to-redeem detail — the offer's
 * own description, the code, and where it is good — and the sheet's confirm
 * records the redemption.
 *
 * The section renders its own heading, so the heading can carry a pulsing marker
 * while any offer on the pass is still unredeemed. It lives on the network page;
 * the /tracks/perks route renders the same thing (as an h1, with a blurb).
 */
export default function PerksSection({
  titleAs: Heading = 'h2',
  blurb,
}: {
  titleAs?: 'h1' | 'h2';
  blurb?: string;
}) {
  const [perks, setPerks] = useState<Perk[]>([]);
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const [loading, setLoading] = useState(true);
  const [sheetPerk, setSheetPerk] = useState<Perk | null>(null);
  const [busy, setBusy] = useState(false);

  const load = async () => {
    const res = await api.get<{ perks: Perk[] }>('/me/perks');
    setPerks(res.data?.perks ?? []);
    setLoading(false);
  };

  useEffect(() => {
    load();
  }, []);

  const redeem = async (code: string) => {
    setBusy(true);
    const res = await api.post(`/me/perks/${code}/redeem`);
    setBusy(false);
    setSheetPerk(null);
    setMsg({ ok: res.success, text: res.message });
    load();
  };

  // Anything not yet redeemed is still sitting there to be claimed.
  const pending = perks.filter((p) => !p.redeemed).length;

  return (
    <section className="stack">
      <Heading className="perk-head">
        {pending > 0 && <span className="perk-ping" aria-hidden="true" />}
        <span>Perks &amp; discounts</span>
      </Heading>
      {blurb && <div className="perk-head-blurb small muted">{blurb}</div>}

      {msg && <Banner tone={msg.ok ? 'ok' : 'bad'} close>{msg.text}</Banner>}

      {loading ? (
        <div className="muted">Loading perks…</div>
      ) : (
        <div className="perk-grid">
          {perks.map((p) => (
            <div className={`perk-card ${p.redeemed ? 'redeemed' : ''}`} key={p.id}>
              <span className="perk-card-title">{p.title}</span>
              {p.redeemed ? (
                <span className="perk-cta done">Redeemed</span>
              ) : (
                <button className="perk-cta" onClick={() => setSheetPerk(p)}>
                  Redeem
                </button>
              )}
            </div>
          ))}
          {!perks.length && <div className="muted small">No perks on your pass yet.</div>}
        </div>
      )}

      {sheetPerk && (
        <PerkSheet
          perk={sheetPerk}
          busy={busy}
          onClose={() => setSheetPerk(null)}
          onRedeem={redeem}
        />
      )}
    </section>
  );
}

import { useCallback, useEffect, useRef, useState, type DragEvent } from 'react';
import { dropSide, insertAt } from '../lib/dragReorder';

export interface LightboxPhoto {
  id: string;
  url: string;
  caption: string | null;
}

/**
 * Full-screen viewer for a photo set.
 *
 * Shared by the public venue gallery and the owner console, so a frame the
 * operator is managing opens at the same size, with the same arrows, keys and
 * filmstrip, as it does on the page. The caller owns which frame is open; this
 * only reports movement back.
 *
 * The strip holds the whole set in one row, eight thumbs at a time on a wide
 * screen and fewer as the screen narrows, so the paging arrows are only there
 * when the row actually has somewhere to go.
 *
 * When the caller passes `onReorder`, the strip also becomes the ordering
 * control: drag a frame left or right and it reports the new place. The public
 * page leaves that off — a visitor viewing the gallery is not editing it.
 */
export default function PhotoLightbox({
  photos,
  name,
  index,
  onIndex,
  onClose,
  onReorder,
}: {
  photos: LightboxPhoto[];
  /** Used for the fallback alt text. */
  name: string;
  index: number;
  onIndex: (next: number) => void;
  onClose: () => void;
  /** `toInsert` is a gap index into the list as it stands (0…length). */
  onReorder?: (from: number, toInsert: number) => void;
}) {
  const close = onClose;
  const step = useCallback(
    (by: number) => onIndex((index + by + photos.length) % photos.length),
    [index, photos.length, onIndex]
  );

  // Dragging a thumb: which one is in hand, and which gap it would land in.
  const [dragFrom, setDragFrom] = useState<number | null>(null);
  const [dropAt, setDropAt] = useState<{ index: number; side: 'before' | 'after' } | null>(null);

  const endDrag = useCallback(() => {
    setDragFrom(null);
    setDropAt(null);
  }, []);

  const dragOver = (e: DragEvent<HTMLButtonElement>, i: number) => {
    if (dragFrom === null) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    const side = dropSide(e, e.currentTarget.getBoundingClientRect(), 'x');
    setDropAt((prev) => (prev && prev.index === i && prev.side === side ? prev : { index: i, side }));
  };

  const drop = (e: DragEvent<HTMLButtonElement>) => {
    if (dragFrom === null || !dropAt || !onReorder) return;
    e.preventDefault();
    const to = insertAt(dropAt.index, dropAt.side);
    if (to !== dragFrom && to !== dragFrom + 1) onReorder(dragFrom, to);
    endDrag();
  };

  const stripRef = useRef<HTMLDivElement | null>(null);
  const [canPage, setCanPage] = useState({ back: false, on: false });

  const syncStrip = useCallback(() => {
    const el = stripRef.current;
    if (!el) return;
    const max = el.scrollWidth - el.clientWidth;
    const next = { back: el.scrollLeft > 2, on: el.scrollLeft < max - 2 };
    // A scroll event fires many times over; keep the render off unless the
    // arrows would actually change.
    setCanPage((prev) => (prev.back === next.back && prev.on === next.on ? prev : next));
  }, []);

  const page = useCallback(
    (by: number) => {
      const el = stripRef.current;
      if (!el) return;
      el.scrollBy({ left: by * el.clientWidth });
      // The paging scroll is instant, so the position is already settled — read
      // it now rather than waiting on a scroll event to come back around.
      syncStrip();
    },
    [syncStrip]
  );

  useEffect(() => {
    const el = stripRef.current;
    if (!el) return;
    syncStrip();
    const ro = new ResizeObserver(syncStrip);
    ro.observe(el);
    // The observer covers the strip's own size; the window listener makes the
    // arrows land in the same frame as a resize rather than a beat later.
    window.addEventListener('resize', syncStrip);
    return () => {
      ro.disconnect();
      window.removeEventListener('resize', syncStrip);
    };
  }, [syncStrip]);

  // Keep the photo on screen in view as the viewer moves through the set. The
  // strip may have just shifted, so re-read the arrows rather than leaving them
  // a step behind.
  useEffect(() => {
    const el = stripRef.current;
    const active = el?.querySelector<HTMLElement>('.lightbox-thumb.active');
    if (!el || !active) return;
    const left = active.offsetLeft;
    const right = left + active.offsetWidth;
    if (left < el.scrollLeft) el.scrollTo({ left: left - 8 });
    else if (right > el.scrollLeft + el.clientWidth) {
      el.scrollTo({ left: right - el.clientWidth + 8 });
    }
    syncStrip();
  }, [index, syncStrip]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') close();
      if (e.key === 'ArrowRight') step(1);
      if (e.key === 'ArrowLeft') step(-1);
    };
    window.addEventListener('keydown', onKey);
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      window.removeEventListener('keydown', onKey);
      document.body.style.overflow = prev;
    };
  }, [close, step]);

  return (
    <div className="lightbox" role="dialog" aria-modal="true" onClick={close}>
      <div className="lightbox-bar">
        <span className="row" style={{ gap: 10, alignItems: 'baseline' }}>
          <span className="small muted">
            {index + 1} / {photos.length}
          </span>
          {onReorder && <span className="tiny muted">Drag a frame to reorder</span>}
        </span>
        <button type="button" className="lightbox-close" onClick={close} aria-label="Close viewer" title="Close">
          <svg width="15" height="15" viewBox="0 0 14 14" aria-hidden="true">
            <path
              d="M3.2 3.2l7.6 7.6M10.8 3.2l-7.6 7.6"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.5"
              strokeLinecap="round"
            />
          </svg>
        </button>
      </div>
      <div
        className="lightbox-stage"
        onClick={(e) => {
          // Clicks inside the stage never reach the backdrop; clicking the
          // letterboxing around the photo (the stage itself) closes.
          e.stopPropagation();
          if (e.target === e.currentTarget) close();
        }}
      >
        <button type="button" className="lightbox-nav prev" onClick={() => step(-1)} aria-label="Previous photo">
          ←
        </button>
        <img src={photos[index].url} alt={photos[index].caption ?? `${name} photo ${index + 1}`} />
        {photos[index].caption && <div className="lightbox-caption small">{photos[index].caption}</div>}
        <button type="button" className="lightbox-nav next" onClick={() => step(1)} aria-label="Next photo">
          →
        </button>
      </div>

      <div className="lightbox-strip-row" onClick={(e) => e.stopPropagation()}>
        <button
          type="button"
          className="lightbox-strip-nav"
          hidden={!canPage.back}
          onClick={() => page(-1)}
          aria-label="Earlier photos"
          title="Earlier"
        >
          ←
        </button>
        <div className={`lightbox-strip${onReorder ? ' reorderable' : ''}`} ref={stripRef} onScroll={syncStrip}>
          {photos.map((p, i) => (
            <button
              key={p.id}
              type="button"
              className={[
                'lightbox-thumb',
                i === index ? 'active' : '',
                dragFrom === i ? 'dragging' : '',
                dropAt && dropAt.index === i && dragFrom !== null ? `drop-${dropAt.side}` : '',
              ]
                .filter(Boolean)
                .join(' ')}
              onClick={() => onIndex(i)}
              aria-label={`Show ${name} photo ${i + 1}`}
              aria-current={i === index}
              draggable={!!onReorder}
              onDragStart={(e) => {
                if (!onReorder) return;
                setDragFrom(i);
                e.dataTransfer.effectAllowed = 'move';
                // Firefox only starts a drag with some data set.
                e.dataTransfer.setData('text/plain', p.id);
              }}
              onDragOver={(e) => dragOver(e, i)}
              onDragLeave={() => setDropAt((prev) => (prev && prev.index === i ? null : prev))}
              onDrop={drop}
              onDragEnd={endDrag}
            >
              <img src={p.url} alt="" draggable={false} />
            </button>
          ))}
        </div>
        <button
          type="button"
          className="lightbox-strip-nav"
          hidden={!canPage.on}
          onClick={() => page(1)}
          aria-label="Later photos"
          title="Later"
        >
          →
        </button>
      </div>
    </div>
  );
}

