 * follow control, and its hours today — the three things a rider checks without
 * opening the full panel. Pinned to the bottom of the rail so it stays in reach
 * while the rail shows the day list or the picked track's own panel.
 *
 * `onFollow` reports the toggle up to the rail, which is the one place the
 * network's follow flags are held.
 */
export default function ProfileMini({
  track,
  onFollow,
}: {
