import { useCallback, useEffect, useRef, useState } from 'react';
import Banner from './Banner';
import QRCode from 'qrcode';
import { api } from '../lib/api';

interface QrToken {
  token: string;
  expiresAt: string;
  nonce: string;
  passId: string;
}

/**
 * Live QR pass. The token is short-lived and signed server-side, so a
 * screenshot of an old code will not scan. Refreshes automatically.
 *
 * `bare` drops the outer card so the panel can sit inside the pass object
 * itself rather than as a separate tile beside it.
 */
export default function QrPanel({ active, bare = false }: { active: boolean; bare?: boolean }) {
  const [data, setData] = useState<QrToken | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [secondsLeft, setSecondsLeft] = useState(0);
  const [showToken, setShowToken] = useState(false);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const load = useCallback(async () => {
    const res = await api.get<QrToken>('/me/qr-token');
    if (!res.success || !res.data) {
      setErr(res.message);
      setData(null);
      return;
    }
    setErr(null);
    setData(res.data);
  }, []);

  useEffect(() => {
    if (!active) return;
    load();
    const id = setInterval(load, 25_000);
    return () => clearInterval(id);
  }, [active, load]);

  useEffect(() => {
    if (!data) return;
    const tick = () => {
      const left = Math.max(Math.round((new Date(data.expiresAt).getTime() - Date.now()) / 1000), 0);
      setSecondsLeft(left);
    };
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, [data]);

  useEffect(() => {
    if (!data || !canvasRef.current) return;
    QRCode.toCanvas(canvasRef.current, data.token, {
      width: 168,
      margin: 1,
      color: { dark: '#0d0f12', light: '#ffffff' },
    });
  }, [data]);

  const save = () => {
    if (!canvasRef.current) return;
    const link = document.createElement('a');
    link.download = 'moto-pass-qr.png';
    link.href = canvasRef.current.toDataURL('image/png');
    link.click();
  };

  if (!active) {
    return (
      <div className={bare ? 'pass-code' : 'card'}>
        <span className="small muted">An active pass is required to generate a code.</span>
      </div>
    );
  }

  const body = (
    <>
      <div style={{ background: '#fff', padding: 10, borderRadius: 6, lineHeight: 0 }}>
        <canvas ref={canvasRef} />
      </div>
      <div className="row" style={{ gap: 8, alignItems: 'center', flexWrap: 'wrap' }}>
        <span className="tiny muted">
          {secondsLeft > 0 ? `valid ${secondsLeft}s` : 'refreshing…'}
        </span>
      </div>
      <div className="row wrap" style={{ gap: 8 }}>
        <button className="ghost small" onClick={save} disabled={!data}>
          Save to device
        </button>
        <button className="ghost small" onClick={() => setShowToken((s) => !s)}>
          {showToken ? 'Hide code' : 'Show code'}
        </button>
      </div>
      {showToken && data && (
        <div style={{ width: '100%', maxWidth: 320 }}>
          <label>Scan code (paste at a station)</label>
          <textarea
            className="mono tiny"
            readOnly
            rows={3}
            value={data.token}
            onFocus={(e) => e.currentTarget.select()}
          />
        </div>
      )}
    </>
  );

  if (bare) {
    return (
      <div className="pass-code">
        {err && <Banner tone="bad" close>{err}</Banner>}
        {body}
      </div>
    );
  }

  return (
    <div className="card stack">
      <div className="row spread">
        <h3 style={{ margin: 0 }}>Pass QR code</h3>
        <span className={`pill ${secondsLeft > 0 ? 'ok' : 'bad'}`}>
          {secondsLeft > 0 ? `valid ${secondsLeft}s` : 'refreshing…'}
        </span>
      </div>
      {err && <Banner tone="bad" close>{err}</Banner>}
      <div className="row" style={{ gap: 18, alignItems: 'flex-start', flexWrap: 'wrap' }}>
        {body}
      </div>
    </div>
  );
}

import { ReactNode, useEffect, useRef, useState } from 'react';
import Banner from './Banner';
import Avatar from './Avatar';
import AvatarPattern from './AvatarPattern';
import { api, dayStr, money, timeStr } from '../lib/api';
import type { ApiResult } from '../lib/api';
import { LOOKUP_MAX, checkLookupInput, sanitizeLookupDraft } from '../lib/lookupInput';
import { reasonLabel } from '../lib/reasonLabels';
import type { ScanOutcome } from './Scanner';

/**
 * The rider's standing at this track, decided by the server off the same rules
 * the scan walks. It is what the panel shows *before* the operator taps: a
 * rider who already rode today, or whose day is blocked, reads it here rather
 * than as a denial after the tap.
 */
export interface GateStanding {
  ok: boolean;
  reasonCode: string | null;
  reason: string | null;
  kind: 'FREE' | 'DISCOUNT' | null;
  amountChargedCents: number | null;
  redeemedTodayAt: string | null;
  redeemedTodayKind: string | null;
  reservationRequired: boolean;
  reservationBooked: boolean;
  includedDays: number | null;
  freeDaysRemaining: number | null;
  discountDaysRemaining: number | null;
}

/** One redeemed day on the rider's record — what the gate view lists under
    the pass, so a spent day is visible at the window. */
export interface RiderRedemption {
  id: string;
  day: string;
  /** Sent by the API but not printed here: the operator works one track. */
  trackName: string;
  kind: string;
  amountChargedCents: number;
  redeemedAt: string;
}

/** One row of `GET /operator/riders` — a rider the gate could redeem for. */
export interface RiderHit {
  id: string;
  name: string;
  email: string;
  phone: string | null;
  avatarUrl: string | null;
  pass: {
    tierName: string;
    status: string;
    seasonYear: number;
    expiresAt: string;
    /** The default (free) tier: no days to redeem at any track. */
    freeTier?: boolean;
  } | null;
  includedDays: number | null;
  remainingFreeDays: number | null;
  standing: GateStanding | null;
  /** The rider's most recent redeemed days, newest first (six at most). */
  history?: RiderRedemption[];
  /** Every redeemed day at this track, so a capped list still says the total. */
  historyCount?: number;
}

interface Props {
  /** The search sheet is the second way in, beside the camera. */
  open?: boolean;
  /** The station's default surface: the same contents, sitting on the page. */
  inline?: boolean;
  onClose?: () => void;
  /** Rendered at the right of the head row (the QR camera's door, inline only). */
  action?: ReactNode;
  onResult: (o: ScanOutcome) => void;
  /**
   * A rider the gate already let through elsewhere — a scanned QR code. The
   * panel runs the same email search the operator could have typed and opens
   * the rider's card on the result, so a scan lands on the view a manual search
   * would have given. `key` changes per reveal, so the same rider can be
   * revealed twice.
   */
  reveal?: { riderId: string; email: string; key: string } | null;
}

/** The three keys a rider can be found by at the window — one per search. */
type LookupField = 'email' | 'name' | 'phone';

/**
 * The gate's memory, one tab wide. A reload in the middle of a transaction — a
 * hot update while the app is being worked on, a stray refresh between riders —
 * used to land the operator on an empty search with the rider gone, mid-shift.
 * The tab now remembers the search it ran and the card it had open.
 */
const GATE_KEY = 'motopass.gate';

interface GateMemory {
  field: LookupField;
  text: string;
  riderId: string | null;
}

function readGateMemory(): GateMemory | null {
  try {
    const raw = sessionStorage.getItem(GATE_KEY);
    if (!raw) return null;
    const v = JSON.parse(raw) as Partial<GateMemory>;
    if (!v || typeof v.text !== 'string' || v.text.length === 0) return null;
    if (v.field !== 'email' && v.field !== 'name' && v.field !== 'phone') return null;
    return {
      field: v.field,
      text: v.text,
      riderId: typeof v.riderId === 'string' ? v.riderId : null,
    };
  } catch {
    return null;
  }
}

function writeGateMemory(v: GateMemory): void {
  try {
    sessionStorage.setItem(GATE_KEY, JSON.stringify(v));
  } catch {
    /* Private mode or a full store: the gate still works, it just forgets. */
  }
}

const LOOKUP_FIELDS: {
  key: LookupField;
  label: string;
  placeholder: string;
  type: string;
  autoComplete: string;
}[] = [
  {
    key: 'email',
    label: 'Email',
    placeholder: 'riley@example.com',
    type: 'email',
    autoComplete: 'off',
  },
  {
    key: 'name',
    label: 'Name',
    placeholder: 'Riley',
    type: 'search',
    autoComplete: 'off',
  },
  {
    key: 'phone',
    label: 'Phone',
    placeholder: '828 555 0142',
    type: 'tel',
    autoComplete: 'off',
  },
];

/** `+182****0142` reads as `+1 828 555 0142`. */
function phoneStr(digits: string | null): string {
  if (!digits) return '';
  const d = digits.replace(/\D/g, '');
  if (d.length === 11) return `+${d[0]} ${d.slice(1, 4)} ${d.slice(4, 7)} ${d.slice(7)}`;
  if (d.length === 10) return `${d.slice(0, 3)} ${d.slice(3, 6)} ${d.slice(6)}`;
  return digits;
}

/** The gate's decision, in words: one state per rider, never a bare dot. */
function passWord(status: string): { label: string; tone: string } {
  switch (status) {
    case 'ACTIVE':
      return { label: 'Active', tone: 'ok' };
    case 'EXPIRED':
      return { label: 'Expired', tone: 'bad' };
    case 'SUSPENDED':
      return { label: 'Suspended', tone: 'bad' };
    default:
      return { label: status.charAt(0) + status.slice(1).toLowerCase(), tone: 'muted' };
  }
}

/** `$27.50` */
function moneyStr(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

/** What a redeemed day was, in the gate's own words — the same two kinds the
    history table on the rider's own pages prints. */
function kindWord(kind: string): string {
  return kind === 'DISCOUNT' ? 'Extra day' : 'Included';
}

async function copyText(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    /* The clipboard API needs a secure context; the field fallback still works. */
    try {
      const el = document.createElement('textarea');
      el.value = text;
      el.setAttribute('readonly', '');
      el.style.position = 'fixed';
      el.style.opacity = '0';
      document.body.appendChild(el);
      el.select();
      const ok = document.execCommand('copy');
      document.body.removeChild(el);
      return ok;
    } catch {
      return false;
    }
  }
}

/**
 * Redeem by finding the rider instead of scanning: email, name or phone —
 * three separate keys, one search at a time, run from a Search button. The
 * search only reads riders and their standing; the redemption itself goes
 * through the same `POST /operator/scan` the camera uses, by rider instead of
 * by token, so the server's rules decide the outcome either way.
 *
 * Picking a row opens the gate view: the rider's identity on the left, the pass
 * and the decision on the right, divided by one hairline. The list is the door
 * back to the other matches.
 *
 * It has two homes: the dashboard carries it inline (`inline`, always open, no
 * backdrop — the page *is* the panel), and the old sheet chrome is kept as the
 * fallback shape. The contents are the same either way.
 */
export default function RiderLookup({
  open = false,
  inline = false,
  onClose,
  action,
  onResult,
  reveal = null,
}: Props) {
  const panelRef = useRef<HTMLDivElement>(null);
  const seqRef = useRef(0);
  /** The last reveal this panel answered, so a re-render cannot re-run it. */
  const revealedRef = useRef<string | null>(null);
  /** The tab's stored transaction is read once, on mount, not on a re-render. */
  const restoredRef = useRef(false);
  /** Which of the three fields the operator is typing in. The three never hold
      text at once — one rider is found by one key. */
  const [field, setField] = useState<LookupField>('email');
  const [q, setQ] = useState('');
  /** The search that was actually run, so a redeem can re-read the same one. */
  const [submitted, setSubmitted] = useState<{ field: LookupField; text: string } | null>(null);
  const [hits, setHits] = useState<RiderHit[]>([]);
  const [searching, setSearching] = useState(false);
  const [searched, setSearched] = useState(false);
  const [busyId, setBusyId] = useState<string | null>(null);
  const [reentering, setReentering] = useState<string | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  /** The rider whose day this panel spent, on this visit. The spent-day button
      says "Redeemed" for that rider and "Already Redeemed Today" for one whose
      day was already on the ledger when the card opened — a reload, or a card
      the operator came back to. Cleared as soon as another rider is opened. */
  const [justRedeemed, setJustRedeemed] = useState<string | null>(null);
  /** The redemption record is the receipt, not the read: it opens on demand. */
  const [showHistory, setShowHistory] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const active = inline || open;
  const selected = hits.find((h) => h.id === selectedId) ?? null;
  /** The server's own read of this rider, refetched after every redeem. */
  const standing = selected?.standing ?? null;
  /** The button follows the standing — a blocked rider cannot tap and be
      denied. Without a standing (an older API) it falls back to the pass
      state, as before. */
  const canRedeem = selected?.pass?.status === 'ACTIVE' && (standing?.ok ?? true);
  /** The free tier snapshots no allotments, so it has no day to redeem at any
      track. The panel drops the button for it, and with the button goes the
      notice — its only denial would be "not valid at this track", which
      describes the tier, not this rider. */
  const freeTier = selected?.pass?.freeTier === true;
  /** The days already spent, newest first — the record behind the standing. */
  const history = selected?.history ?? [];
  /** Today's entry is already on this track's ledger: the day cannot be
      redeemed again, so the panel offers a logged re-entry instead. */
  const alreadyToday = standing?.reasonCode === 'ALREADY_USED_TODAY';
  /** The spent-day button names the tap the operator just made, and the reload
      wording for a day that was already spent when the card opened. */
  const spentLabel = selected && justRedeemed === selected.id ? 'Redeemed' : 'Already Redeemed Today';

  // A different rider's card starts folded, the same as a fresh one does.
  useEffect(() => {
    setShowHistory(false);
  }, [selectedId]);

  // Every visit starts on empty fields. Inline mounts once, so this runs on
  // mount and never again — the fields keep what was typed.
  useEffect(() => {
    if (!active) return;
    setField('email');
    setQ('');
    setSubmitted(null);
    setHits([]);
    setSelectedId(null);
    setJustRedeemed(null);
    setSearched(false);
    setError(null);
  }, [active]);

  // Escape and the focus handle belong to the sheet; on the page there is
  // nothing to dismiss.
  useEffect(() => {
    if (!open || inline || !onClose) return;
    panelRef.current?.focus();
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [open, inline, onClose]);

  // Nothing is searched while typing: the operator picks one field, fills it
  // and presses Search (or Enter). The sequence number drops a slow reply that
  // a newer search has already overtaken.
  const runSearch = async (f: LookupField, raw: string): Promise<RiderHit[]> => {
    /* The same rules the route runs: a key that fails here never reaches the
       API. An empty key is simply no search; a bad one says what is wrong. */
    const check = checkLookupInput(f, raw);
    if (!check.ok) {
      setHits([]);
      setSelectedId(null);
      setSearched(false);
      setSearching(false);
      if (check.text.length > 0) setError(check.message);
      return [];
    }
    const text = check.text;
    setError(null);
    const seq = ++seqRef.current;
    setSearching(true);
    setSelectedId(null);
    let res: ApiResult<{ q: string; riders: RiderHit[] }>;
    try {
      res = await api.get<{ q: string; riders: RiderHit[] }>(
        `/operator/riders?q=${encodeURIComponent(text)}&field=${f}`
      );
    } catch {
      /* A request that never reached the route — a dead API, a proxy error —
         comes back with no body at all, so the read throws. Say so and stop:
         the panel would otherwise sit on "Searching…" with a rejection in the
         console and nothing on screen. */
      if (seq === seqRef.current) {
        setSearching(false);
        setSearched(true);
        setError('The search could not reach the server. Try again.');
      }
      return [];
    }
    if (seq !== seqRef.current) return [];
    setSearching(false);
    setSearched(true);
    /* A 500 the route did answer carries its own message; the list is not
       the answer, so the error line is. */
    if (res.success === false) {
      setError(res.message || 'The search failed. Try again.');
      return [];
    }
    setSubmitted({ field: f, text });
    const riders = res.data?.riders ?? [];
    setHits(riders);
    setSelectedId(null);
    return riders;
  };

  // The copied note is a moment, not a state.
  useEffect(() => {
    if (!copied) return;
    const t = window.setTimeout(() => setCopied(false), 1600);
    return () => window.clearTimeout(t);
  }, [copied]);

  const openRider = (hit: RiderHit) => {
    /* Another rider's card forgets the tap that spent this one's day; the same
       rider reopened straight after its own redeem keeps it. */
    setJustRedeemed((cur) => (cur === hit.id ? cur : null));
    setSelectedId(hit.id);
    setCopied(false);
    setError(null);
  };

  /** Re-read the list in place: a redeem changes the rider's own standing
      (a day is gone, today is now on the ledger), so the panel has to follow
      it without dropping the rider open. */
  const refreshHits = async () => {
    if (!submitted) return;
    /* The stored key went through the same check when it was searched, but a
       refetch is still a request: it is re-checked rather than trusted. */
    const check = checkLookupInput(submitted.field, submitted.text);
    if (!check.ok) return;
    const res = await api.get<{ q: string; riders: RiderHit[] }>(
      `/operator/riders?q=${encodeURIComponent(check.text)}&field=${submitted.field}`
    );
    if (res.data?.riders) setHits(res.data.riders);
  };

  /* The transaction this tab was in the middle of, restored after a reload: the
     same search, run again, with the rider's card reopened on the same rider.
     Inline only — the sheet keeps its short-lived state, and its reset effect
     wipes it on every visit. */
  useEffect(() => {
    if (!inline || restoredRef.current) return;
    restoredRef.current = true;
    const saved = readGateMemory();
    if (!saved) return;
    (async () => {
      const riders = await runSearch(saved.field, saved.text);
      /* The fields are written after the search answers, not before: a second
         pass over the mount effects (StrictMode does one in dev) clears them,
         and the panel would come back with a card and an empty box. */
      setField(saved.field);
      setQ(saved.text);
      if (saved.riderId && riders.some((h) => h.id === saved.riderId)) {
        setSelectedId(saved.riderId);
      }
    })();
    // Mount only: the stored transaction is read once, and only the page has one.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [inline]);

  /* Every search and every open card is written back, so the next reload lands
     where this one left off. Nothing is written until a search has run. */
  useEffect(() => {
    if (!inline || !submitted) return;
    writeGateMemory({ field: submitted.field, text: submitted.text, riderId: selectedId });
  }, [inline, submitted, selectedId]);

  /* A scan that came back approved lands here. It runs the email search the
     operator could have typed, fills the fields with it, and opens the rider's
     card — the scan already spent the day, so the card reads it as spent and
     offers the re-entry. `revealedRef` keeps a re-render from repeating it. */
  useEffect(() => {
    if (!reveal || revealedRef.current === reveal.key) return;
    revealedRef.current = reveal.key;
    let cancelled = false;
    setField('email');
    setQ(reveal.email);
    (async () => {
      const riders = await runSearch('email', reveal.email);
      if (cancelled) return;
      const hit = riders.find((h) => h.id === reveal.riderId) ?? null;
      if (hit) {
        /* The scan itself spent the day, so this card's first read is the
           redemption the operator just made — it says Redeemed, not the
           reload wording. */
        setJustRedeemed(reveal.riderId);
        openRider(hit);
      }
    })();
    return () => {
      cancelled = true;
    };
    // The reveal object is rebuilt per scan; `key` is what makes it new.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reveal?.key]);

  const redeem = async (hit: RiderHit) => {
    if (busyId) return;
    setBusyId(hit.id);
    setError(null);
    const res = await api.post<ScanOutcome>('/operator/scan', { riderId: hit.id });
    setBusyId(null);
    const outcome: ScanOutcome =
      res.data ?? {
        approved: false,
        result: 'DENIED',
        reasonCode: 'CLIENT_ERROR',
        reason: res.message,
      };
    onResult(outcome);
    /* A day the server just spent reads as this visit's redemption; the card's
       next read (a reload, a return) says Already Redeemed Today instead. */
    if (outcome.approved) setJustRedeemed(hit.id);
    await refreshHits();
  };

  const reenter = async (hit: RiderHit) => {
    if (reentering) return;
    setReentering(hit.id);
    setError(null);
    const res = await api.post<ScanOutcome>('/operator/reenter', { riderId: hit.id });
    setReentering(null);
    const outcome: ScanOutcome =
      res.data ?? {
        approved: false,
        result: 'DENIED',
        reasonCode: 'CLIENT_ERROR',
        reason: res.message,
      };
    onResult(outcome);
    await refreshHits();
  };

  if (!active) return null;

  /* The search section: three keys, one at a time, and the button that runs it.
     What came back belongs to the results section below — the two are separate
     sections, never one block. */
  /* The button stays out of reach until the key has changed since the last
     search that ran: same field, same text means the results on screen already
     answer it. */
  const searchCheck = checkLookupInput(field, q);
  /* Bad text is named while it is typed, not after Search: the field says what
     is wrong and the button stays out of reach. Half a value — an address with
     no domain yet, a number still being typed — is not wrong, only unfinished:
     it says so quietly and still keeps the button out of reach. */
  const fieldBad = !searchCheck.ok && searchCheck.text.length > 0 ? searchCheck : null;
  const fieldError = fieldBad && !fieldBad.incomplete ? fieldBad.message : null;
  const fieldHint = fieldBad && fieldBad.incomplete ? fieldBad.message : null;
  const searchText = searchCheck.text;
  const searchChanged =
    !submitted || submitted.field !== field || submitted.text !== searchText;
  const canSearch = searchCheck.ok && !searching && searchChanged;
  const searchBlock = (
    <form
      className="lookup-field"
      /* The browser's own email check has nothing to add here: the shape is
         already checked as it is typed, and the button refuses to run until the
         address is whole. */
      noValidate
      onSubmit={(e) => {
        e.preventDefault();
        /* Enter obeys the button: an unchanged key is not searched twice. */
        if (!canSearch) return;
        runSearch(field, q);
      }}
    >
      <div className="lookup-field-grid">
        {LOOKUP_FIELDS.map((f) => {
          const isActive = field === f.key;
          const err = isActive ? fieldError : null;
          const hint = isActive ? fieldHint : null;
          const describedBy =
            [err ? `rider-search-${f.key}-error` : null, hint ? `rider-search-${f.key}-hint` : null]
              .filter(Boolean)
              .join(' ') || undefined;
          return (
            <div className="lookup-field-cell" key={f.key}>
              <label htmlFor={`rider-search-${f.key}`}>{f.label}</label>
              <input
                id={`rider-search-${f.key}`}
                type={f.type}
                autoComplete={f.autoComplete}
                placeholder={f.placeholder}
                /* What a field can hold, so the box cannot grow past what the
                   route accepts. A phone keeps room for its punctuation. */
                maxLength={f.key === 'phone' ? LOOKUP_MAX.phone * 2 : LOOKUP_MAX[f.key]}
                inputMode={f.key === 'phone' ? 'tel' : undefined}
                /* One key at a time: the other two read empty while this one is
                   in use, so what is on screen is always what gets searched. */
                value={isActive ? q : ''}
                className={isActive ? undefined : 'is-idle'}
                aria-invalid={err ? true : undefined}
                aria-describedby={describedBy}
                onChange={(e) => {
                  setField(f.key);
                  /* Controls and over-long pastes are removed as they land;
                     the shape checks run off the sanitised draft. */
                  setQ(sanitizeLookupDraft(f.key, e.target.value));
                  setError(null);
                }}
              />
              {err && (
                <div className="lookup-field-error" id={`rider-search-${f.key}-error`} role="alert">
                  {err}
                </div>
              )}
              {hint && (
                <div className="lookup-field-hint" id={`rider-search-${f.key}-hint`}>
                  {hint}
                </div>
              )}
            </div>
          );
        })}
        <button type="submit" className="primary lookup-search-btn" disabled={!canSearch}>
          {searching ? 'Searching…' : 'Search'}
        </button>
      </div>
    </form>
  );

  /* The results section exists only once there is something to report: a
     search under way, an answer, or a rider open. */
  const resultsVisible = searching || searched || hits.length > 0 || !!selected;

  const resultsBody = (
    <>
      {error && <Banner tone="warn">{error}</Banner>}

      {searching && <div className="small muted">Searching…</div>}

      {!searching && searched && hits.length === 0 && (
        <div className="small muted lookup-hint">
          No rider matches “{submitted?.text ?? q.trim()}”.
        </div>
      )}

      {selected ? (
        <div className="gate-view">
          <div className="gate-identity">
            <div className="gate-head">
              <Avatar src={selected.avatarUrl} name={selected.name} className="gate-photo" />
              <div className="gate-head-text">
                <h3 className="gate-name">{selected.name}</h3>
                <div className="gate-contact small">
                  {selected.email}
                  {selected.phone ? ` · ${phoneStr(selected.phone)}` : ''}
                </div>
              </div>
            </div>
            <dl className="gate-facts">
              <div>
                <dt>Rider ID</dt>
                {/* The id copies from a small glyph beside it rather than from
                    a text button in the action row: the string is what the
                    operator hands to support, so it sits with the id itself. */}
                <dd className="mono tiny gate-id">
                  <span className="gate-id-text">{selected.id}</span>
                  <button
                    type="button"
                    className={copied ? 'copy-id copied' : 'copy-id'}
                    aria-label={copied ? 'Copied' : 'Copy rider ID'}
                    title={copied ? 'Copied' : 'Copy rider ID'}
                    onClick={() => copyText(selected.id).then(setCopied)}
                  >
                    {copied ? (
                      <svg width="13" height="13" viewBox="0 0 16 16" aria-hidden="true"
                        fill="none" stroke="currentColor" strokeWidth="1.8"
                        strokeLinecap="round" strokeLinejoin="round">
                        <path d="M3.3 8.4 6.3 11.4 12.7 5" />
                      </svg>
                    ) : (
                      <svg width="13" height="13" viewBox="0 0 16 16" aria-hidden="true"
                        fill="none" stroke="currentColor" strokeWidth="1.5"
                        strokeLinejoin="round">
                        <rect x="5.6" y="5.6" width="8" height="8" rx="1.5" />
                        <path d="M10.6 3.4V3a1.5 1.5 0 0 0-1.5-1.5H3.5A1.5 1.5 0 0 0 2 3v5.6a1.5 1.5 0 0 0 1.5 1.5h.4" />
                      </svg>
                    )}
                  </button>
                </dd>
              </div>
            </dl>

            {/* The record behind the standing: the days already spent and the
                time each was scanned, without leaving the window. The venue is
                left out — the operator is working one track. Folded away by
                default: the standing above is the answer, this is the receipt.
                A rider with nothing spent has no record, so the fold is absent
                rather than opening onto an empty list. */}
            {history.length > 0 && (
            <div className="gate-history" data-open={showHistory}>
              <button
                type="button"
                className="gate-history-head"
                aria-expanded={showHistory}
                onClick={() => setShowHistory((v) => !v)}
              >
                <span className="gate-history-title">Redemption history</span>
                <svg
                  className="gate-history-arrow"
                  width="14"
                  height="14"
                  viewBox="0 0 16 16"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="1.6"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  aria-hidden="true"
                >
                  <path d="M6 3.5 10.5 8 6 12.5" />
                </svg>
              </button>
              {showHistory && history.length > 0 && (
                <ul className="gate-history-rows">
                  {history.map((r) => (
                    <li key={r.id}>
                      {/* A free day names its kind inline; only a day paid at
                          the window keeps a figure in the right-hand column. */}
                      <span className="gate-history-when">
                        {dayStr(r.day)} · {timeStr(r.redeemedAt)}
                        {!r.amountChargedCents && ` (${kindWord(r.kind)})`}
                      </span>
                      {r.amountChargedCents ? (
                        <span className="gate-history-kind">{money(r.amountChargedCents)}</span>
                      ) : null}
                    </li>
                  ))}
                </ul>
              )}
            </div>
            )}
          </div>

          <div className="gate-decision">
            <h4 className="gate-decision-title">Pass details</h4>
            {selected.pass ? (
              <dl className="gate-rows">
                <div>
                  <dt>{selected.pass.seasonYear} {selected.pass.tierName}</dt>
                  <dd className={passWord(selected.pass.status).tone}>
                    {passWord(selected.pass.status).label}
                  </dd>
                </div>
                {selected.remainingFreeDays != null && selected.includedDays != null && (
                  <div>
                    <dt>Days Remaining</dt>
                    <dd>
                      {selected.remainingFreeDays} of {selected.includedDays}
                    </dd>
                  </div>
                )}
                <div>
                  <dt>Expires</dt>
                  <dd>{new Date(selected.pass.expiresAt).toLocaleDateString()}</dd>
                </div>
              </dl>
            ) : (
              <div className="small muted">No pass on the account.</div>
            )}

            {canRedeem && standing?.kind === 'DISCOUNT' && standing.amountChargedCents ? (
              <div className="small muted gate-note">
                Next day is a paid extra day — {moneyStr(standing.amountChargedCents)} due at the
                window.
              </div>
            ) : null}
          </div>

          {/* Why the rider cannot be let through, said across the panel above
              the controls rather than inside the pass column: the reason
              belongs to the whole decision, not to the pass figures. */}
          {standing && !standing.ok && !freeTier && !alreadyToday && (
            <div className="gate-notice">
              <div className="row spread">
                <strong>Cannot redeem</strong>
                <span className="tiny muted">{reasonLabel(standing.reasonCode)}</span>
              </div>
              <div className="small">{standing.reason}</div>
            </div>
          )}

          {/* The actions close the panel under both columns: one line of
              controls across the full width rather than a stack inside the
              pass column. */}
          <div className="gate-actions">
            {/* Today's day is gone: no second redeem, but the rider can be
                let back through, which the server logs and charges nothing
                for. */}
            {alreadyToday ? (
              <>
                <button type="button" className="primary" disabled>
                  {spentLabel}
                </button>
                <button
                  type="button"
                  disabled={reentering === selected.id}
                  onClick={() => reenter(selected)}
                >
                  {reentering === selected.id ? 'Logging…' : 'Re-enter'}
                </button>
              </>
            ) : (
              !freeTier && (
                <button
                  type="button"
                  className="primary"
                  disabled={!canRedeem || busyId === selected.id}
                  onClick={() => redeem(selected)}
                >
                  {busyId === selected.id
                    ? 'Redeeming…'
                    : standing?.ok && standing.kind === 'DISCOUNT' && standing.amountChargedCents
                      ? `Redeem a day · ${moneyStr(standing.amountChargedCents)}`
                      : 'Redeem a day'}
                </button>
              )
            )}
          </div>
        </div>
      ) : (
        hits.length > 0 && (
          <ul className="lookup-hits">
            {hits.map((hit) => (
              <li key={hit.id} className="lookup-hit">
                <button type="button" className="lookup-hit-row" onClick={() => openRider(hit)}>
                  {/* The rider's own pattern stands in for a face; every seeded
                      account has one, the drawing covers any that doesn't. */}
                  <span className="lookup-hit-avatar">
                    {hit.avatarUrl ? (
                      <img src={hit.avatarUrl} alt="" />
                    ) : (
                      <AvatarPattern name={hit.name} />
                    )}
                  </span>
                  <span className="lookup-hit-main">
                    <strong>{hit.name}</strong>
                    {/* Email then the number the operator dials at the window. */}
                    <span className="small muted">
                      {hit.email}
                      {hit.phone ? ` · ${phoneStr(hit.phone)}` : ''}
                    </span>
                  </span>
                </button>
              </li>
            ))}
          </ul>
        )
      )}

    </>
  );

  /** The list is the door back from an open rider. */
  const backToResults = () => {
    setSelectedId(null);
    setCopied(false);
  };

  /* The results head is a label over the rows — the way back sits outside the
     card, above the list's upper-left corner. It belongs to the results
     section, not to the search field's. An open rider drops it: the card
     below already names who is open. */
  const resultsHead = (
    <div className="lookup-results-head">
      <h2 className="lookup-results-title" id="lookup-results-title">
        Results{hits.length > 1 ? ` (${hits.length})` : ''}
      </h2>
    </div>
  );

  /* The label names the section only while the rows are the read; a clicked
     rider's card is labelled by its own name. */
  const resultsLabel = selected ? undefined : 'lookup-results-title';

  /* The list is the door back from an open rider: one quiet line above the
     card, left-aligned, arrow pointing at the way out. */
  const backRow = selected ? (
    <div className="lookup-back-row">
      <button type="button" className="lookup-back" onClick={backToResults}>
        <svg viewBox="0 0 16 16" aria-hidden="true" focusable="false">
          <path
            d="M13 8H3m0 0 4-4M3 8l4 4"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.4"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
        Back to results
      </button>
    </div>
  ) : null;

  if (inline) {
    return (
      <>
        <section className="scan-lookup" aria-labelledby="lookup-title">
          <div className="row spread scan-lookup-head">
            <h2 className="scan-lookup-title" id="lookup-title">
              Find a rider
            </h2>
            <div className="row scan-lookup-actions">{action}</div>
          </div>
          {searchBlock}
        </section>

        {/* The way back sits outside the details card, so the card holds the
            rider alone. */}
        {resultsVisible && backRow}
        {resultsVisible && (
          /* An open rider's details are a card again — the read is a document,
             not a list row — while the bare hits list stays on the page. */
          <section
            className={`lookup-results${selected ? ' has-rider' : ''}`}
            aria-labelledby={resultsLabel}
          >
            {!selected && resultsHead}
            {resultsBody}
          </section>
        )}
      </>
    );
  }

  return (
    <div className="sheet-backdrop" onClick={onClose}>
      <div
        className="sheet lookup-sheet"
        role="dialog"
        aria-modal="true"
        aria-labelledby="lookup-sheet-title"
        tabIndex={-1}
        ref={panelRef}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="row spread">
          <h4 className="sheet-title" id="lookup-sheet-title">
            Find a rider
          </h4>
        </div>
        <div className="scan-lookup">{searchBlock}</div>
        {resultsVisible && (
          <div className="lookup-results">
            {backRow}
            {!selected && resultsHead}
            {resultsBody}
          </div>
        )}
        <div className="sheet-actions">
          <button className="ghost small" onClick={onClose}>
            Close
          </button>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useRef } from 'react';
import * as L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import {
  Access,
  Entitlement,
  MapTrack,
  accessFor,
  isCovered,
  venuePin,
} from '../lib/trackAccess';
import { US_CENTER, usMapOptions } from '../lib/usMap';
import { locateHintText, useRiderLocation, type GeoState } from '../lib/geo';

/**
 * An ask for a position can come back empty-handed five ways, and the control
 * carries every word of it: three on its label, and the sentence that says what to
 * do about it in the hint that opens under it while the pointer is over the
 * control (`GEO_FAIL_COPY` for a failed ask, the hint a live control has always
 * had otherwise). Nothing is written to the page around the map — an ask for a
 * position is the map's own business, and a reader who wants to know why has the
 * control under their pointer.
 */

/**
 * The scale a pick comes in to — about a metro area, so the venue it opens sits
 * under a little of the country it lives in rather than alone.
 *
 * A pick cannot simply pan: the network is framed at the country scale, where
 * the viewport is wider than the US bounds `usMapOptions()` pins the map to, and
 * Leaflet answers that by holding the view on the middle of the country — no pan
 * would move anything at all. A reader already in closer than this keeps their
 * own zoom; this is only a floor.
 */
const PICK_ZOOM = 9;

/**
 * The rider's own map of the network: one dot per partner track, filled with
 * the accent; a venue the pass is not on today wears a dashed outline instead.
 * Hovering a dot names its venue in
 * a tooltip. Rendered as the wide
 * right-hand half of My Pass, so it fills its container rather than setting its own height —
 * imported lazily by the page, because Leaflet is heavy and this is the only
 * surface in the app that needs it alongside a signed-in rider.
 *
 * The one other dot it draws is the rider's own fix (lib/geo.ts): asked for as
 * the page and the map arrive, carried by the top-right control, and never
 * fitted — the map goes on framing the network.
 */

function dotIcon(t: MapTrack, state: Access, gated: boolean) {
  const c = venuePin();
  // Coverage is the one non-colour cue: a free account sees a venue that is shut
  // dashed, a rider sees one the pass does not carry dashed. Everything else is
  // spelled out in the rail, so the fill stays a pure accent read.
  const dashed = gated ? t.status === 'CLOSED' : state === 'notCovered';
  // The dot is the whole marker; the venue's name arrives as a tooltip. A Leaflet
  // tooltip only reaches the DOM once it is opened, so the name also rides on the
  // marker as `data-name` — that is what a check or a probe reads a pin by.
  const name = t.name.replace(/&/g, '&amp;').replace(/"/g, '&quot;');
  // The dot is the accent, held a step short of solid: its fill is mixed to 85%
  // opacity here so a sliver of tile still reads through, and its shape rides on
  // the hairline outline set by .map-pin-dot (global.scss). Mixing instead of
  // hard-coding a colour keeps the venue-type token on the inline style, which is
  // what a check reads a pin by.
  return L.divIcon({
    className: 'map-pin-wrap',
    html:
      `<span class="map-pin-dot" data-name="${name}" ` +
      `style="background:color-mix(in srgb, ${c.bg} 85%, transparent);` +
      `${dashed ? 'border-style:dashed;' : ''}"></span>`,
    iconSize: [0, 0],
    iconAnchor: [0, 0],
  });
}

/**
 * The rider's own fix, drawn as the map's one dot that is not a venue: a
 * neutral core, because the accent pair is spoken for by what a venue is. Its
 * name rides on `data-name` the way a venue dot's does, since a Leaflet tooltip
 * only reaches the DOM once it is opened.
 */
function meIcon() {
  return L.divIcon({
    className: 'map-me-wrap',
    html: '<span class="map-me-dot" data-name="Your location"></span>',
    iconSize: [0, 0],
    iconAnchor: [0, 0],
  });
}

/** What the locate control says, per state: `idle` and `on` share a word, since
 *  the pin itself says which of the two it is. */
const LOCATE_LABEL: Record<GeoState, string> = {
  idle: 'My location',
  asking: 'Locating…',
  on: 'My location',
  outside: 'Outside the map',
  denied: 'Location blocked',
  unavailable: 'Location unavailable',
  insecure: 'Needs HTTPS',
  unsupported: '',
};

/** Why the control reads the way it does, for the pointer. */
function locateTitle(state: GeoState, shown: boolean): string {
  switch (state) {
    case 'asking':
      return 'Reading your position';
    case 'on':
      return shown ? 'Hide your position' : 'Show your position on the map';
    case 'outside':
      return 'Your position is outside the map frame';
    case 'denied':
      return 'Allow location for this site in your browser';
    case 'insecure':
      return 'A browser only shares a position on a secure page';
    case 'unavailable':
      return 'Your position could not be read. Try again';
    default:
      return 'Show your position on the map';
  }
}

export default function RiderTrackMap({
  tracks,
  ents,
  selectedId = null,
  gated = false,
  hideUncovered = false,
  onSelect,
  onClear,
}: {
  tracks: MapTrack[];
  /** The rider's entitlements keyed by trackId; empty when the pass is inactive. */
  ents: Record<string, Entitlement>;
  /** Free tier: colour the pins by what each venue is doing, not by days left. */
  gated?: boolean;
  /** The rail's "hide not covered" filter, mirrored here: the venues the pass
   *  does not carry are dropped from the pins too, so the map and the list beside
   *  it hold the same network. The page owns the state and feeds both. */
  hideUncovered?: boolean;
  /** The track picked in the rail; every other pin steps back while it is set. */
  selectedId?: string | null;
  /** Open a track's panel in the rail — the same pick a row in the list makes. */
  onSelect?: (trackId: string) => void;
  /** A bare click on the map: the open pick goes away and the network comes
   *  back. A pin's own click never reaches this — Leaflet does not bubble a
   *  marker's click to the map. */
  onClear?: () => void;
}) {
  const mapEl = useRef<HTMLDivElement>(null);
  const mapRef = useRef<L.Map | null>(null);
  const layerRef = useRef<L.LayerGroup | null>(null);
  /** Live marker per trackId, so a pick can restyle the pins in place. */
  const marksRef = useRef<Record<string, L.Marker>>({});
  /** Latest pick handler, so binding a pin never re-draws the layer. */
  const onSelectRef = useRef(onSelect);
  onSelectRef.current = onSelect;
  /** Latest clear handler, and the pick itself, for the map's own click: only a
   *  click that lands on an open pick clears anything. */
  const onClearRef = useRef(onClear);
  onClearRef.current = onClear;
  const selectedRef = useRef(selectedId);
  selectedRef.current = selectedId;
  /** The frame the whole network was fitted to — what a cleared pick returns to. */
  const frameRef = useRef<L.LatLngBounds | null>(null);
  /** What the drawn pins are made of, last time they were drawn: a redraw is
   *  asked for by a change in that read, not by a new `tracks` identity (a
   *  follow patches the array the map never draws). */
  const drawnRef = useRef<string | null>(null);
  /** The points the view was last fitted to — a redraw that draws the same
   *  places leaves the reader's own frame alone. */
  const fittedRef = useRef<string | null>(null);
  /** The pick whose fly has already run — a pick that has not moved is not a
   *  move. */
  const flownRef = useRef<string | null>(null);
  /** The rider's own pin rides its own layer, so redrawing the network leaves it. */
  const meLayerRef = useRef<L.LayerGroup | null>(null);
  /** The browser's answer on landing: the fix, where it stands, the put-away toggle. */
  const { fix, state, shown, toggle } = useRiderLocation();
  /** The sentence under the control on hover: why the ask failed, or what the
   *  control does now — the whole of what used to be a `title` and a notice. */
  const hint = locateHintText(state) ?? locateTitle(state, shown);

  useEffect(() => {
    if (!mapEl.current || mapRef.current) return;
    // The chrome lives at the map's own corners, and the rail and the venue
    // inspector float over two of them: both bottom corners are pinned right of
    // the rail's column instead (below, in the canvas CSS), which is why the
    // zoom bar and the attribution are asked for rather than left to default.
    const map = L.map(mapEl.current, { ...usMapOptions(), zoomControl: false, attributionControl: false });
    L.control.zoom({ position: 'bottomleft' }).addTo(map);
    L.control.attribution({ position: 'bottomleft', prefix: false }).addTo(map);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
      subdomains: 'abc',
      referrerPolicy: 'origin',
      attribution:
        '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
    }).addTo(map);
    layerRef.current = L.layerGroup().addTo(map);
    meLayerRef.current = L.layerGroup().addTo(map);
    // A fresh map carries a fresh, empty layer, so the memos that guard the
    // draw against a no-op re-render have to go with it: under `StrictMode`
    // every effect runs twice, and a guard left standing across the second pass
    // would find its own key already set and leave the new layer bare — no pins
    // at all. Reset here, where the layer they describe is made.
    drawnRef.current = null;
    fittedRef.current = null;
    flownRef.current = null;
    // A bare click on the map is the third way out of a pick, beside the picked
    // row's second click and the inspector's close control: the pick goes away
    // and the map comes back out to the network (the effect below). A pin's own
    // click never arrives here — Leaflet does not bubble a marker's click to the
    // map — and the zoom control and the attribution stop their own clicks, so
    // the chrome over the canvas is not a way out either.
    map.on('click', () => {
      if (selectedRef.current) onClearRef.current?.();
    });
    mapRef.current = map;
    const t = setTimeout(() => map.invalidateSize(), 200);
    return () => {
      clearTimeout(t);
      map.remove();
      mapRef.current = null;
      layerRef.current = null;
      meLayerRef.current = null;
    };
  }, []);

  // Draw markers whenever the network or the rider's entitlements change.
  useEffect(() => {
    const layer = layerRef.current;
    const map = mapRef.current;
    if (!layer || !map) return;

    // What a pin is drawn *from*, in order — the venue's coordinates, its name,
    // its live status and how the pass covers it. A follow rides on the track
    // but is not on the map at all, and the rail patches the `tracks` array on
    // every follow: keyed on the array itself, the layer would clear, rebuild
    // and re-fit the country under a reader who only toggled a flag the map
    // never showed. `?` marks a venue with no pin, so one that gains or loses
    // coordinates still counts as a change.
    const drawn = tracks
      .map((t) =>
        t.lat == null || t.lng == null
          ? `${t.id}?`
          : `${t.id}~${t.lat}~${t.lng}~${t.name}~${t.status}~${accessFor(t, ents[t.id])}`
      )
      .join('|');
    const key = `${gated ? 'g' : '-'}${hideUncovered ? 'h' : '-'}${drawn}`;
    if (key === drawnRef.current) return;
    drawnRef.current = key;

    layer.clearLayers();
    marksRef.current = {};
    const pts: L.LatLngExpression[] = [];
    const ptKeys: string[] = [];

    for (const t of tracks) {
      if (t.lat == null || t.lng == null) continue;
      const e = ents[t.id];
      // A venue the pass does not carry has no pin to draw while the filter is
      // on: `pts` fills from what is actually drawn, so the frame refits to the
      // network the rider can still ride.
      if (hideUncovered && !isCovered(e)) continue;
      const state = accessFor(t, e);
      const mk = L.marker([t.lat, t.lng], {
        icon: dotIcon(t, state, gated),
        riseOnHover: true,
      });
      // Hovering the dot names the venue in a tooltip on the app's own card
      // material; a click still picks it, opening the same rail panel a row in
      // the day list opens.
      mk.bindTooltip(t.name, {
        direction: 'top',
        offset: [0, -11],
        className: 'map-tip',
        opacity: 1,
      });
      mk.on('click', () => {
        onSelectRef.current?.(t.id);
      });
      layer.addLayer(mk);
      marksRef.current[t.id] = mk;
      pts.push([t.lat, t.lng]);
      ptKeys.push(`${t.lat},${t.lng}`);
    }

    if (pts.length) {
      // The frame the network is fitted to is kept: a pick that goes away gives
      // the country back by returning to exactly this one.
      const frame = L.latLngBounds(pts).pad(0.25);
      frameRef.current = frame;
      // The view is refitted only when the places drawn actually changed. A
      // redraw that draws the same country leaves a reader's own pan and zoom
      // where they put them — a status tick, or the pass landing, is no reason
      // to pull the map back out from under them.
      const frameKey = ptKeys.join('|');
      if (frameKey !== fittedRef.current) {
        fittedRef.current = frameKey;
        map.fitBounds(frame, { maxZoom: 11 });
      }
    } else {
      frameRef.current = null;
      fittedRef.current = null;
      map.setView(US_CENTER, 8);
    }
  }, [tracks, ents, gated, hideUncovered]);

  // A picked track keeps the map: its own dot lifts and every other dot steps
  // back, so the rail's choice reads on the map before anything is clicked. The
  // name itself is not pinned open — Leaflet closes a tooltip on mouseout, and
  // the rail panel that a pick opens names the venue anyway.
  useEffect(() => {
    for (const [id, mk] of Object.entries(marksRef.current)) {
      const el = mk.getElement();
      if (!el) continue;
      const lit = id === selectedId;
      el.classList.toggle('dim', !!selectedId && !lit);
      el.classList.toggle('on', lit);
    }
  }, [selectedId, tracks, ents]);

  // A pick also *brings its venue to the middle of the canvas*: the rail floats
  // over the left edge and the inspector over the right, and the two are near
  // enough the same width that the container's own centre is the centre of the
  // map a reader can see. It has to come in to `PICK_ZOOM` to do anything: at the
  // country scale the network is framed at, the viewport is wider than the US
  // bounds themselves, so Leaflet's `maxBounds` clamp pins the view to the middle
  // of the country and a pan is a no-op. A reader who has already come in closer
  // keeps their own scale — a pick asks for the venue, not for a particular zoom.
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !selectedId) {
      // No pick: the next one is a new one, and it flies.
      flownRef.current = null;
      return;
    }
    const t = tracks.find((x) => x.id === selectedId);
    if (!t || t.lat == null || t.lng == null) return;
    // Only a *new* pick asks for the fly. The rail patches the `tracks` array on
    // a follow too, and repeating the fly for the venue already open is not a
    // move: it would re-centre and re-zoom under a reader who had panned or
    // scaled the map themselves after picking.
    const key = `${selectedId}~${t.lat}~${t.lng}`;
    if (flownRef.current === key) return;
    flownRef.current = key;
    map.flyTo([t.lat, t.lng], Math.max(map.getZoom(), PICK_ZOOM), { duration: 0.5 });
  }, [selectedId, tracks]);

  // A pick that goes away gives the country back: the map returns to the frame
  // the network was fitted to, so a reader who came in to one venue is not left
  // at metro scale with the rest of the network out of sight. A pin's click and
  // a bare click on the map both land here, as does the inspector's close — a
  // clear is a clear, whichever control made it. Only a change of pick animates
  // it; the page's own first paint is already that frame.
  const wasPicked = useRef(false);
  useEffect(() => {
    const map = mapRef.current;
    if (selectedId) {
      wasPicked.current = true;
      return;
    }
    if (!map || !wasPicked.current) return;
    wasPicked.current = false;
    if (frameRef.current) map.flyToBounds(frameRef.current, { maxZoom: 11, duration: 0.6 });
  }, [selectedId]);

  // The rider's own pin: its own layer, above every venue dot, so a redraw of
  // the network leaves it standing. It never moves the view — the map keeps
  // framing the network, and the pin simply sits where the fix is.
  useEffect(() => {
    const layer = meLayerRef.current;
    if (!layer) return;
    layer.clearLayers();
    if (!fix || !shown) return;
    const mk = L.marker([fix.lat, fix.lng], {
      icon: meIcon(),
      zIndexOffset: 400,
      keyboard: false,
      alt: 'Your location',
    });
    mk.bindTooltip('Your location', {
      direction: 'top',
      offset: [0, -13],
      className: 'map-tip',
      opacity: 1,
    });
    layer.addLayer(mk);
  }, [fix, shown]);

  return (
    <div className="map-pane">
      <div ref={mapEl} className="map-dark" />

      {/* The map's own chrome, floating over the middle of the canvas — the
          rail and the inspector own the two edges: the position control, and
          the key to the dots. */}
      <div className="map-chrome">
        {/* The network is public and the position pin is the one thing a visitor
            and a rider share, so the ask goes out with the page and this control
            only reports where it got to. */}
        {state !== 'unsupported' && (
          <div className="map-locate-wrap">
            <button
              type="button"
              className="map-locate"
              aria-pressed={shown}
              aria-describedby="map-locate-hint"
              disabled={state === 'asking' || state === 'denied' || state === 'insecure'}
              onClick={toggle}
            >
              {/* A point on four ticks — the centre fills once the pin is down. */}
              <svg width="13" height="13" viewBox="0 0 16 16" aria-hidden="true">
                <circle
                  cx="8"
                  cy="8"
                  r="2.5"
                  fill={shown ? 'currentColor' : 'none'}
                  stroke="currentColor"
                  strokeWidth="1.4"
                />
                <path
                  d="M8 0.8v3M8 12.2v3M0.8 8h3M12.2 8h3"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="1.4"
                  strokeLinecap="round"
                />
              </svg>
              <span>{LOCATE_LABEL[state]}</span>
            </button>
            {/* What the label has no room for. Held at zero opacity rather than
                display:none, so `aria-describedby` still reaches it: the control
                is disabled in every state that needs this text, and a disabled
                control cannot take focus. */}
            <span className="map-locate-hint" id="map-locate-hint" role="tooltip">
              {hint}
            </span>
          </div>
        )}

      </div>
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from 'react';
import Banner from './Banner';
import RiderLookup from './RiderLookup';
import jsQR from 'jsqr';
import { api } from '../lib/api';
import { reasonLabel } from '../lib/reasonLabels';

export interface ScanOutcome {
  approved: boolean;
  result: 'APPROVED' | 'DENIED';
  reasonCode: string;
  reason: string;
  kind?: string;
  amountChargedCents?: number;
  rider?: { id: string; name: string; email: string };
  track?: { id: string; name: string };
  pass?: { tierName: string; seasonYear: number; expiresAt: string };
  remainingFreeDays?: number;
  includedDays?: number;
  discountDaysRemaining?: number;
}

interface Props {
  onResult: (o: ScanOutcome) => void;
  /** The station's last outcome, read back inside the open camera sheet. */
  result?: ScanOutcome | null;
}

/**
 * The scanning station: two ways in at the gate — find the rider (phone, email,
 * account id) and redeem their pass from the list, or scan the rider's QR code.
 * Finding is the default: the search sits on the page, always open. The camera
 * is the one door that is still a sheet, because it asks for the lens. Only the
 * raw token is read from the camera; every pass/fail decision is made by the
 * server, and a lookup redemption asks the same endpoint with a rider id
 * instead of a token.
 *
 * The band carries nothing but the search and the camera's button: no preview,
 * no code field, no pass picker on the page. Closing the camera sheet stops the
 * stream — nothing keeps the lens.
 */
export default function Scanner({ onResult, result }: Props) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const rafRef = useRef<number>();
  const lastRef = useRef<{ token: string; at: number }>({ token: '', at: 0 });
  const panelRef = useRef<HTMLDivElement>(null);
  // Read through refs so the scan loop keeps one identity: a re-render (a busy
  // flip) must not tear down the stream it is drawing from.
  const busyRef = useRef(false);
  const onResultRef = useRef(onResult);
  onResultRef.current = onResult;

  const [open, setOpen] = useState(false);
  const [cameraOn, setCameraOn] = useState(false);
  const [camErr, setCamErr] = useState<string | null>(null);
  const [manual, setManual] = useState('');
  const [showManual, setShowManual] = useState(false);
  const [busy, setBusy] = useState(false);
  /** The rider a scan just let through, handed to the lookup panel so it opens
      their card. A pass at the gate is not the end of the transaction — the
      operator still has a rider in front of them, and their record is what the
      manual search would have shown. */
  const [reveal, setReveal] = useState<{ riderId: string; email: string; key: string } | null>(
    null
  );

  const submit = useCallback(async (token: string) => {
    if (!token || busyRef.current) return;
    busyRef.current = true;
    setBusy(true);
    const res = await api.post<ScanOutcome>('/operator/scan', { token });
    busyRef.current = false;
    setBusy(false);
    if (res.data) {
      onResultRef.current(res.data);
      // A valid code opens the rider's card; a denial stays in the sheet with
      // its reason, because there is nothing to look up afterwards.
      if (res.data.approved && res.data.rider?.email) {
        setReveal({
          riderId: res.data.rider.id,
          email: res.data.rider.email,
          key: `${res.data.rider.id}:${Date.now()}`,
        });
      }
    } else
      onResultRef.current({
        approved: false,
        result: 'DENIED',
        reasonCode: 'CLIENT_ERROR',
        reason: res.message,
      });
  }, []);

  const scanFrame = useCallback(() => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    if (video && canvas && video.readyState === video.HAVE_ENOUGH_DATA) {
      const w = video.videoWidth;
      const h = video.videoHeight;
      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext('2d', { willReadFrequently: true });
      if (ctx && w && h) {
        ctx.drawImage(video, 0, 0, w, h);
        const image = ctx.getImageData(0, 0, w, h);
        const code = jsQR(image.data, image.width, image.height, { inversionAttempts: 'dontInvert' });
        if (code?.data) {
          const now = Date.now();
          // Debounce: ignore the same token re-read within 4s.
          if (code.data !== lastRef.current.token || now - lastRef.current.at > 4000) {
            lastRef.current = { token: code.data, at: now };
            submit(code.data);
          }
        }
      }
    }
    rafRef.current = requestAnimationFrame(scanFrame);
  }, [submit]);

  const stopCamera = useCallback(() => {
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    rafRef.current = undefined;
    const stream = videoRef.current?.srcObject as MediaStream | null;
    stream?.getTracks().forEach((t) => t.stop());
    if (videoRef.current) videoRef.current.srcObject = null;
    setCameraOn(false);
  }, []);

  const close = useCallback(() => {
    stopCamera();
    setCamErr(null);
    setOpen(false);
  }, [stopCamera]);

  // The lens has done its job: a passed scan puts the rider's card on the page,
  // so the camera sheet steps aside rather than covering it.
  useEffect(() => {
    if (reveal) close();
  }, [reveal, close]);

  // The button is the whole action; every visit starts with the manual field
  // collapsed.
  const redeem = () => {
    setShowManual(false);
    setManual('');
    setOpen(true);
  };

  // The stream follows the sheet: opening it asks for the lens, closing it (or
  // unmounting the station) hands it back.
  useEffect(() => {
    if (!open) return;
    let cancelled = false;
    setCamErr(null);
    (async () => {
      // A blocked lens is a dead end for the stream, not a slow start: say what
      // blocked it and leave the manual line as the way through.
      if (cancelled) return;
      if (!navigator.mediaDevices?.getUserMedia) {
        setCamErr(
          'Camera unavailable. This page needs a secure connection. Tap “Manually enter QR code” below.'
        );
        return;
      }
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: 'environment' },
        });
        const video = videoRef.current;
        if (cancelled || !video) {
          stream.getTracks().forEach((t) => t.stop());
          return;
        }
        video.srcObject = stream;
        await video.play();
        if (cancelled) return;
        setCameraOn(true);
        rafRef.current = requestAnimationFrame(scanFrame);
      } catch (err) {
        // No lens: point at the manual line, but leave it collapsed. The field
        // stays hidden until the operator asks for it.
        if (!cancelled) {
          const name = (err as DOMException)?.name;
          setCamErr(
            name === 'NotAllowedError' || name === 'SecurityError'
              ? 'Camera permission blocked. Allow camera access in the browser, or tap “Manually enter QR code” below.'
              : name === 'NotFoundError' || name === 'OverconstrainedError'
                ? 'No camera found on this device. Tap “Manually enter QR code” below.'
                : name === 'NotReadableError'
                  ? 'Camera is in use by another app. Close it, or tap “Manually enter QR code” below.'
                  : 'Camera unavailable. Grant camera permission, or tap “Manually enter QR code” below.'
          );
        }
      }
    })();
    return () => {
      cancelled = true;
      stopCamera();
    };
  }, [open, scanFrame, stopCamera]);

  useEffect(() => {
    if (!open) return;
    panelRef.current?.focus();
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') close();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [open, close]);

  const runManual = () => {
    submit(manual.trim());
    setManual('');
  };

  return (
    <div className="scan-band">
      <RiderLookup
        inline
        onResult={(o) => onResultRef.current(o)}
        reveal={reveal}
        action={
          <button type="button" className="scan-qr" onClick={redeem}>
            {/* The gate's lens: three finder squares and two code modules. */}
            <svg
              width="14"
              height="14"
              viewBox="0 0 16 16"
              aria-hidden="true"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.5"
            >
              <rect x="1.4" y="1.4" width="4.6" height="4.6" rx="0.8" />
              <rect x="10" y="1.4" width="4.6" height="4.6" rx="0.8" />
              <rect x="1.4" y="10" width="4.6" height="4.6" rx="0.8" />
              <rect x="3.05" y="3.05" width="1.3" height="1.3" fill="currentColor" stroke="none" />
              <rect x="11.65" y="3.05" width="1.3" height="1.3" fill="currentColor" stroke="none" />
              <rect x="3.05" y="11.65" width="1.3" height="1.3" fill="currentColor" stroke="none" />
              <rect x="10" y="10" width="1.6" height="1.6" fill="currentColor" stroke="none" />
              <rect x="12.9" y="12.9" width="1.6" height="1.6" fill="currentColor" stroke="none" />
            </svg>
            Scan QR code
          </button>
        }
      />

      {open && (
        <div className="sheet-backdrop" onClick={close}>
          <div
            className="sheet scan-sheet"
            role="dialog"
            aria-modal="true"
            aria-labelledby="scan-sheet-title"
            tabIndex={-1}
            ref={panelRef}
            onClick={(e) => e.stopPropagation()}
          >
            <div className="row spread">
              <h4 className="sheet-title" id="scan-sheet-title">
                Camera scan
              </h4>
              <div className="row scan-head">
                {cameraOn ? (
                  <span className="pill ok">camera live</span>
                ) : camErr ? null : (
                  <span className="pill">starting</span>
                )}
                {/* Same dismissal as the backdrop, given a face so the sheet is
                    closable without reading to the bottom. */}
                <button
                  type="button"
                  className="scan-close"
                  onClick={close}
                  aria-label="Close camera scan"
                  title="Close"
                >
                  <svg width="14" height="14" viewBox="0 0 14 14" aria-hidden="true">
                    <path
                      d="M3.2 3.2l7.6 7.6M10.8 3.2l-7.6 7.6"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="1.5"
                      strokeLinecap="round"
                    />
                  </svg>
                </button>
              </div>
            </div>

            {camErr && <Banner tone="warn">{camErr}</Banner>}

            <div className="scan-frame">
              <video ref={videoRef} playsInline muted />
              {!cameraOn && !camErr && (
                <div className="scan-frame-note small muted">Starting camera…</div>
              )}
            </div>
            <canvas ref={canvasRef} style={{ display: 'none' }} />

            {/* An approval and a re-entry are announced by the page's toast, not
                read back here; only a denial has to stay in the sheet, because
                the sheet is where the operator still is. */}
            {result && !result.approved && result.reasonCode !== 'RE_ENTRY' && (
              <div className={`scan-read ${result.approved ? 'ok' : 'bad'}`}>
                <div className="row spread">
                  <strong>{result.approved ? 'APPROVED' : 'DENIED'}</strong>
                  <span className="tiny muted">{reasonLabel(result.reasonCode)}</span>
                </div>
                <div className="small">{result.reason}</div>
                {result.rider && (
                  <div className="tiny">
                    {result.rider.name}
                    {result.remainingFreeDays != null && result.includedDays != null
                      ? ` · ${result.remainingFreeDays} of ${result.includedDays} free days left`
                      : ''}
                    {result.amountChargedCents ? ` · collect at the window` : ''}
                  </div>
                )}
              </div>
            )}

            <div className="manual-entry scan-manual">
              <button
                type="button"
                className="manual-toggle"
                aria-expanded={showManual}
                onClick={() => setShowManual((v) => !v)}
              >
                Manually enter QR code #
              </button>
              {showManual && (
                <div>
                  <label htmlFor="manual">Manual scan code</label>
                  <div className="row">
                    <input
                      id="manual"
                      className="mono small"
                      placeholder="paste pass code"
                      value={manual}
                      onChange={(e) => setManual(e.target.value)}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter' && manual.trim()) runManual();
                      }}
                    />
                    <button disabled={!manual.trim() || busy} onClick={runManual}>
                      Validate
                    </button>
                  </div>
                </div>
              )}
            </div>

          </div>
        </div>
      )}
    </div>
  );
}

import { useEffect } from 'react';
import { useLocation } from 'react-router-dom';

/**
 * Reset the window scroll on every route change.
 *
 * A React Router navigation is a `pushState` — the browser keeps the scroll
 * offset it had on the outgoing page, so a link near the foot of a long page
 * (the landing's "Compare all tiers", which points at `/pricing`) dropped the
 * reader into the middle of the new page. Mounted once, inside the router, so
 * every page opens at its head.
 *
 * The `hash` guard leaves in-page anchors (`/tracks#…`) alone: a hash is a
 * request to land *somewhere* down that page, so the default scroll wins.
 */
export default function ScrollToTop() {
  const { pathname, hash } = useLocation();

  useEffect(() => {
    if (!hash) window.scrollTo(0, 0);
  }, [pathname, hash]);

  return null;
}

import { useCallback, useMemo, useState, type CSSProperties, type ReactNode } from 'react';

export type SortDir = 'asc' | 'desc';
export interface SortState {
  key: string | null;
  dir: SortDir;
}

/** Per-column value getters. Return the underlying value, not the label. */
export type Accessors<T> = Record<string, (row: T) => string | number | null | undefined>;

/**
 * Column sorting for a table: click a header to sort ascending, click again to
 * flip. Rows with no value in the sorted column always sink to the bottom, in
 * both directions, so a click never buries the data you can act on.
 */
export function useSorted<T>(
  rows: T[],
  accessors: Accessors<T>,
  initial: SortState = { key: null, dir: 'asc' }
) {
  const [sort, setSort] = useState<SortState>(initial);

  const toggle = useCallback((key: string) => {
    setSort((s) => (s.key === key ? { key, dir: s.dir === 'asc' ? 'desc' : 'asc' } : { key, dir: 'asc' }));
  }, []);

  const sorted = useMemo(() => {
    const get = sort.key ? accessors[sort.key] : undefined;
    if (!get) return rows;
    const blank = (v: unknown) => v === null || v === undefined || v === '';
    return rows.slice().sort((a, b) => {
      const av = get(a);
      const bv = get(b);
      if (blank(av) && blank(bv)) return 0;
      if (blank(av)) return 1;
      if (blank(bv)) return -1;
      const cmp =
        typeof av === 'number' && typeof bv === 'number'
          ? av - bv
          : String(av).localeCompare(String(bv), undefined, { numeric: true, sensitivity: 'base' });
      return sort.dir === 'asc' ? cmp : -cmp;
    });
  }, [rows, sort, accessors]);

  return { sorted, sort, toggle };
}

/** The sort indicator: two shallow chevrons when unsorted, one when sorted. */
export function SortMark({ dir }: { dir: SortDir | null }) {
  // Drawn, not a glyph: two shallow chevrons when unsorted, one when sorted.
  return (
    <svg width="12" height="12" viewBox="0 0 12 12" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      {dir !== 'desc' && <path d="M3 7 6 4l3 3" />}
      {dir !== 'asc' && <path d="M3 5.5 6 8.5l3-3" />}
    </svg>
  );
}

/** A header cell that sorts its column. `children` is the column label. */
export function SortTh({
  sortKey,
  sort,
  onSort,
  className,
  style,
  children,
}: {
  sortKey: string;
  sort: SortState;
  onSort: (key: string) => void;
  className?: string;
  style?: CSSProperties;
  children: ReactNode;
}) {
  const active = sort.key === sortKey;
  const dir = active ? sort.dir : null;
  return (
    <th
      className={className}
      style={style}
      aria-sort={active ? (dir === 'asc' ? 'ascending' : 'descending') : 'none'}
    >
      <button type="button" className="sort-btn" onClick={() => onSort(sortKey)}>
        <span>{children}</span>
        <SortMark dir={dir} />
      </button>
    </th>
  );
}

import { useEffect, useState } from 'react';

/**
 * Theme toggle — dark (default) / light.
 *
 * Flips the whole app by setting `data-theme` on <html>: every surface reads the
 * `--bg` / `--bg-2` / `--text` / `--line` tokens, and the light palette is just a
 * second set of those tokens in global.scss. The choice persists in localStorage
 * (`motopass.theme`); the pre-paint script in index.html applies the stored value
 * before React mounts so the dark palette never flashes first.
 */

type Theme = 'dark' | 'light';

const STORE_KEY = 'motopass.theme';

function stored(): Theme {
  try {
    return localStorage.getItem(STORE_KEY) === 'light' ? 'light' : 'dark';
  } catch {
    return 'dark';
  }
}

function apply(theme: Theme) {
  const root = document.documentElement;
  if (theme === 'light') root.dataset.theme = 'light';
  else delete root.dataset.theme;
  // Keep the mobile browser chrome in step with the surface behind it.
  const meta = document.querySelector('meta[name="theme-color"]');
  if (meta) meta.setAttribute('content', theme === 'light' ? '#f5f6f8' : '#0d0f12');
}

export default function ThemeToggle() {
  const [theme, setTheme] = useState<Theme>(stored);

  useEffect(() => {
    apply(theme);
    try {
      if (theme === 'dark') localStorage.removeItem(STORE_KEY);
      else localStorage.setItem(STORE_KEY, theme);
    } catch {
      /* private mode — the choice just won't persist */
    }
  }, [theme]);

  const next = theme === 'dark' ? 'light' : 'dark';

  return (
    <button
      type="button"
      className="theme-toggle"
      aria-pressed={theme === 'light'}
      aria-label={`Switch to ${next} theme`}
      title={`Switch to ${next} theme`}
      onClick={() => setTheme(next)}
    >
      {/* A track with a round knob: dark parks it right under a moon, light
          parks it left under a sun. */}
      <span className="tt-track">
        <span className="tt-thumb">
          {theme === 'dark' ? (
            /* Moon: the app is dark, clicking goes light. */
            <svg width="9" height="9" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <path
                d="M20 14.5A8.5 8.5 0 0 1 9.5 4a8.5 8.5 0 1 0 10.5 10.5Z"
                stroke="currentColor"
                strokeWidth="1.9"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          ) : (
            /* Sun: the app is light, clicking goes dark. */
            <svg width="10" height="10" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <circle cx="12" cy="12" r="4" stroke="currentColor" strokeWidth="1.9" />
              <path
                d="M12 2.6v2.1M12 19.3v2.1M2.6 12h2.1M19.3 12h2.1M5.4 5.4l1.5 1.5M17.1 17.1l1.5 1.5M18.6 5.4l-1.5 1.5M6.9 17.1l-1.5 1.5"
                stroke="currentColor"
                strokeWidth="1.9"
                strokeLinecap="round"
              />
            </svg>
          )}
        </span>
      </span>
    </button>
  );
}

import { useCallback, useEffect, useRef, useState } from 'react';
import Banner from './Banner';

/** One notice in flight. `id` is the stack's own key, never the server's. */
export interface Toast {
  id: number;
  tone: 'ok' | 'bad' | 'warn' | 'bare';
  title: string;
  detail?: string;
  /** Override the stack's default stay for this one notice. A confirmation the
      reader has to act on (figures to collect at the window) needs longer than
      a plain "saved". */
  ms?: number;
  /** Set once the notice is on its way out; it keeps its row until the exit runs. */
  leaving?: boolean;
}

/** How long a notice stays up. Short on purpose: it is a confirmation, not a
    record — the log holds the record. */
const TOAST_MS = 4000;
/** More than this never fits the corner, and the oldest has already been read. */
const MAX_TOASTS = 3;
/** The exit animation's length (`toast-out` in global.scss). The row is cut
    only after it, so a notice fades down instead of blinking out mid-read. */
const EXIT_MS = 180;

/**
 * The toasts in flight, oldest first. Each one retires on its own timer, so two
 * notices raised a second apart leave a second apart. `push` is stable, which is
 * what lets a caller hand it to a child without tearing that child down.
 */
export function useToasts(ms = TOAST_MS) {
  const seq = useRef(0);
  const timers = useRef(new Map<number, number>());
  const exits = useRef(new Map<number, number>());
  const [toasts, setToasts] = useState<Toast[]>([]);

  const dismiss = useCallback((id: number) => {
    const timer = timers.current.get(id);
    if (timer) {
      window.clearTimeout(timer);
      timers.current.delete(id);
    }
    if (exits.current.has(id)) return;
    // Start the exit, then cut the row when the animation ends.
    setToasts((list) => list.map((t) => (t.id === id ? { ...t, leaving: true } : t)));
    exits.current.set(
      id,
      window.setTimeout(() => {
        exits.current.delete(id);
        setToasts((list) => list.filter((t) => t.id !== id));
      }, EXIT_MS),
    );
  }, []);

  const push = useCallback(
    (toast: Omit<Toast, 'id' | 'leaving'>) => {
      const id = ++seq.current;
      setToasts((list) => [...list, { ...toast, id }].slice(-MAX_TOASTS));
      timers.current.set(
        id,
        window.setTimeout(() => dismiss(id), toast.ms ?? ms),
      );
    },
    [dismiss, ms],
  );

  // An unmount hands every pending timer back.
  useEffect(() => {
    const pending = timers.current;
    const pendingExits = exits.current;
    return () => {
      pending.forEach((timer) => window.clearTimeout(timer));
      pending.clear();
      pendingExits.forEach((timer) => window.clearTimeout(timer));
      pendingExits.clear();
    };
  }, []);

  return { toasts, push, dismiss };
}

/**
 * The bottom-right toast layer. Newest at the corner, older notices standing
 * above it, one gap apart — never overlapping, never pushing the page.
 */
export default function ToastStack({
  toasts,
  onDismiss,
}: {
  toasts: Toast[];
  onDismiss: (id: number) => void;
}) {
  if (toasts.length === 0) return null;
  return (
    <div className="toast-stack" role="status" aria-live="polite">
      {toasts.map((toast) => (
        <div
          className={`toast-item${toast.leaving ? ' leaving' : ''}`}
          key={toast.id}
        >
          <Banner tone={toast.tone} close onDismiss={() => onDismiss(toast.id)}>
            <strong>{toast.title}</strong>
            {toast.detail && <div className="small">{toast.detail}</div>}
          </Banner>
        </div>
      ))}
    </div>
  );
}

import { useState } from 'react';
import PhotoLightbox from './PhotoLightbox';

export interface GalleryPhoto {
  id: string;
  url: string;
  caption: string | null;
  category: string;
}

/**
 * A venue's photo gallery: one frame opening the page, the rest beside it in a
 * grid, and the full set behind a lightbox. A venue the owner has not shot yet
 * has an empty list and never reaches here — the profile falls back to its
 * banner photo instead.
 *
 * The grid is 1 + 6: the first photo is the hero (it is what the page is about)
 * and up to six more fill the 2×3 block beside it. When the gallery is longer
 * than that, the last tile is the way into the rest, carrying the count — the
 * only place the total appears.
 *
 * The viewer itself lives in PhotoLightbox, which the owner console shares.
 */
export default function TrackGallery({ name, photos }: { name: string; photos: GalleryPhoto[] }) {
  const [open, setOpen] = useState<number | null>(null);
  // The grid beside the hero holds up to six. Whatever the rest is, it fills
  // the block evenly: when the extras are odd the last tile is the way in.
  const rest = photos.length - 1;
  const showMore = rest > 6 || rest % 2 === 1;
  const thumbs = photos.slice(1, 1 + (rest > 6 ? 5 : rest));
  const slots = thumbs.length + (showMore ? 1 : 0);

  if (photos.length === 0) return null;

  return (
    <div className={`photo-gallery ${slots > 0 ? '' : 'solo'}`}>
      <button
        type="button"
        className="photo-hero"
        onClick={() => setOpen(0)}
        aria-label={`Open ${name} photos`}
      >
        <img src={photos[0].url} alt={`${name} track`} />
        <span className="photo-tag">Featured</span>
      </button>

      {slots > 0 && (
        <div className="photo-grid">
          {thumbs.map((p, i) => (
            <button
              key={p.id}
              type="button"
              className="photo-tile"
              onClick={() => setOpen(i + 1)}
              aria-label={`Open ${name} photo ${i + 2}`}
            >
              <img src={p.url} alt="" loading="lazy" />
            </button>
          ))}
          {showMore && (
            <button
              type="button"
              className="photo-tile photo-more"
              onClick={() => setOpen(photos.length - 1)}
            >
              <img src={thumbs[thumbs.length - 1].url} alt="" loading="lazy" />
              <span className="photo-more-label">All Photos ({photos.length})</span>
            </button>
          )}
        </div>
      )}

      {open !== null && (
        <PhotoLightbox
          photos={photos}
          name={name}
          index={open}
          onIndex={setOpen}
          onClose={() => setOpen(null)}
        />
      )}
    </div>
  );
}

import AvatarPattern from './AvatarPattern';

/**
 * A venue's square mark on a profile — its uploaded logo when one is on file,
 * otherwise the same deterministic pixel pattern the rider avatars use, seeded
 * from the track name. Keeps a logo-less venue from rendering as a hole.
 */
export default function TrackLogo({
  name,
  logoUrl,
  size = 40,
}: {
  name: string;
  logoUrl?: string | null;
  size?: number;
}) {
  return (
    <span className="track-logo" style={{ width: size, height: size }}>
      {logoUrl ? <img src={logoUrl} alt={`${name} logo`} /> : <AvatarPattern name={name} />}
    </span>
  );
}

import { Link } from 'react-router-dom';

/**
 * A track's name in a table cell.
 *
 * Two shapes:
 *  - With `to` (the network directory): the name is an internal link to that
 *    track's profile page, and the venue's own site stays beside it as the
 *    external-link glyph — the profile is the hub, the site is one of its links.
 *  - Without `to` (operator log, history, perks, admin): the name itself is the
 *    link out to the track's site, as before.
 *
 * A track with no site on file renders as plain text in either shape.
 */
function ExternalLinkIcon() {
  return (
    <svg
      width="12"
      height="12"
      viewBox="0 0 12 12"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.4"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      <path d="M5 3H3.5A1.5 1.5 0 0 0 2 4.5v4A1.5 1.5 0 0 0 3.5 10h4A1.5 1.5 0 0 0 9 8.5V7" />
      <path d="M7 2h3v3" />
      <path d="M6.2 5.8 10 2" />
    </svg>
  );
}

export default function TrackName({
  name,
  website,
  to,
}: {
  name: string;
  website?: string | null;
  /** Route to the track's own profile page — the directory passes it. */
  to?: string;
}) {
  if (!to) {
    if (!website) return <>{name}</>;
    return (
      <a
        className="track-link"
        href={website}
        target="_blank"
        rel="noopener noreferrer"
        title={`${name}: opens their site in a new tab`}
      >
        {name}
        <ExternalLinkIcon />
      </a>
    );
  }

  return (
    <>
      <Link className="track-name-link" to={to} title={`${name}: track profile`}>
        {name}
      </Link>
      {website && (
        <a
          className="track-site"
          href={website}
          target="_blank"
          rel="noopener noreferrer"
          title={`${name}: opens their site in a new tab`}
        >
          <ExternalLinkIcon />
        </a>
      )}
    </>
  );
}

import type { ReactNode } from 'react';
import { Link } from 'react-router-dom';
import Banner from './Banner';
import DayMeter from './DayMeter';
import FollowButton from './FollowButton';
import type { Entitlement } from './DaysByTrack';
import { hoursWeekLine } from '../lib/hoursWeek';
import { money } from '../lib/api';
import { useAuth } from '../lib/auth';
import type { TrackPerk } from '../lib/trackOffers';
import { TRACK_STATUS_CLASS, statusLabel, type MapTrack } from '../lib/trackAccess';

/** `2026-11-14` → `Sat, Nov 14` — the race's own day, read without a timezone. */
function raceDay(day: string): string {
  const [y, m, d] = day.split('-').map(Number);
  if (!y || !m || !d) return day;
  return new Date(y, m - 1, d).toLocaleDateString(undefined, {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
  });
}

/**
 * What one partner track is, from the rider's seat: the venue, where it is,
 * then the pass's own terms there — the discounted day and the member rate —
 * before the ways out: the track's own profile, site and
 * feeds. It rides over the map's right edge as the picked venue's inspector,
 * beside the rail the pick came from — the list is never swapped out for it —
 * so the × is the way back to the bare map rather than to a list.
 */
export default function TrackPanel({
  track,
  ent,
  gated = false,
  lapsed = false,
  onClose,
  onFollow,
}: {
  track: MapTrack;
  ent: Entitlement | undefined;
  /** The track's perks and whether the pass is active: still accepted from the
   *  rail so its call site stays as it was, but the panel no longer reads the
   *  offers off them. */
  perks: TrackPerk[];
  active: boolean;
  /** Free tier or a lapsed pass: the pass's own terms are withheld, so hide the
   *  day facts. */
  gated?: boolean;
  /** The terms are missing because the pass on this account has expired, not
   *  because the tier does not carry them — the note below says which. */
  lapsed?: boolean;
  /** Put the inspector away. */
  onClose: () => void;
  /** Reports the follow toggle up to the rail that renders this panel. */
  onFollow?: (trackId: string, following: boolean) => void;
}) {
  const { user } = useAuth();
  const remaining = ent ? Math.max(ent.freeDaysRemaining, 0) : 0;
  const where = [track.city, track.region].filter(Boolean).join(', ');
  // The Hours row answers "which days", not what runs on them: the venue's week
  // is the source, so the panel and the profile's own Hours card agree.
  const hoursLine = hoursWeekLine(track.hoursWeek, track.hours);
  // The race notice leads with whatever already says "race" — the seeded titles
  // do ("Saturday race day") — so the banner never prints the word twice.
  const race = track.nextRace;
  const raceTitleSaysRace = Boolean(race && /race/i.test(race.title));
  // Following is a rider action — an operator owns a venue rather than
  // following it, so the control never renders for one.

  // The ways out, after the profile: the venue's own site and feeds ride as
  // icon buttons so the row stays one line at the panel's 356px. Each keeps its
  // name as the anchor's label — for a screen reader, and as the tooltip.
  const links: { label: string; href: string; icon: ReactNode }[] = [];
  if (track.website)
    links.push({
      label: 'Website',
      href: track.website,
      icon: (
        <svg viewBox="0 0 16 16" aria-hidden="true" focusable="false">
          <circle cx="8" cy="8" r="6.1" fill="none" stroke="currentColor" strokeWidth="1.4" />
          <path d="M1.9 8h12.2M8 1.9c1.7 1.8 2.6 3.9 2.6 6.1S9.7 12.3 8 14.1C6.3 12.3 5.4 10.2 5.4 8S6.3 3.7 8 1.9z"
            fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" />
        </svg>
      ),
    });
  if (track.instagram)
    links.push({
      label: 'Instagram',
      href: track.instagram,
      icon: (
        <svg viewBox="0 0 16 16" aria-hidden="true" focusable="false">
          <rect x="1.9" y="1.9" width="12.2" height="12.2" rx="3.6" fill="none" stroke="currentColor" strokeWidth="1.4" />
          <circle cx="8" cy="8" r="3" fill="none" stroke="currentColor" strokeWidth="1.4" />
          <circle cx="11.85" cy="4.15" r="0.95" fill="currentColor" />
        </svg>
      ),
    });
  if (track.facebook)
    links.push({
      label: 'Facebook',
      href: track.facebook,
      icon: (
        <svg viewBox="0 0 16 16" aria-hidden="true" focusable="false">
          {/* The wordmark's own path is taller than the two line glyphs beside
              it, so it is scaled into the same optical box. */}
          <path d="M9.9 15V8.7h2.1l.35-2.5H9.9V4.6c0-.72.2-1.21 1.23-1.21h1.32V1.15A17.6 17.6 0 0 0 10.53 1C8.62 1 7.32 2.16 7.32 4.3v1.9H5.2v2.5h2.12V15z"
            fill="currentColor" transform="translate(0.27 0.96) scale(0.88)" />
        </svg>
      ),
    });

  return (
    <section className="stack track-panel">
      <button type="button" className="track-close" onClick={onClose} aria-label="Close the venue details">
        <svg width="13" height="13" viewBox="0 0 14 14" aria-hidden="true">
          <path d="M3.2 3.2l7.6 7.6M10.8 3.2l-7.6 7.6" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
        </svg>
      </button>

      {track.imageUrl && <img className="track-panel-photo" src={track.imageUrl} alt="" />}

      <div className="stack track-panel-body">
        <div className="row track-panel-head">
          {/* The name is the second way into the venue's own profile — the
              head reads as the venue, so clicking it should go where the
              Track profile button goes. */}
          <h2>
            <Link
              className="track-name-link"
              to={`/tracks/${track.slug}`}
              title={`${track.name}: track profile`}
            >
              {track.name}
            </Link>
          </h2>
          {/* Today's gate, and tomorrow's when the operator has scheduled it —
              the venue's status reads beside its name, not as a row of its
              own below the description. */}
          <div className="track-panel-status">
            <span className={`status-pill ${TRACK_STATUS_CLASS[track.status] ?? 'status-open'}`}>
              {statusLabel(track.status)}
            </span>
            {track.tomorrowStatus && (
              <span className={`status-pill ${TRACK_STATUS_CLASS[track.tomorrowStatus.status] ?? 'status-open'}`}>
                Tomorrow · {statusLabel(track.tomorrowStatus.status)}
              </span>
            )}
          </div>
          {/* Following belongs to a rider account: a visitor gets the panel
              without it, and so does an operator. */}
          {user && user.role === 'RIDER' && (
            <FollowButton
              trackId={track.id}
              name={track.name}
              following={Boolean(track.following)}
              onChange={(f) => onFollow?.(track.id, f)}
              compact
            />
          )}
        </div>
        {where && <div className="small muted">{where}</div>}
        {track.description && <p className="small track-panel-desc">{track.description}</p>}

        {track.statusNote && <div className="small muted">{track.statusNote}</div>}

        {/* The operator's own word to riders — a standing note about the venue
            (gate times, parking, a work day) rather than today's gate read, so
            it rides on its own line above the facts whenever they left one. */}
        {track.riderMessage && (
          <div className="operator-message">
            <span className="muted">From the operator</span>
            <p className="small">{track.riderMessage}</p>
          </div>
        )}

        {/* A race on the venue's own schedule is the one thing that changes the
            day a rider was planning, so it rides above the facts as a notice. */}
        {race && (
          <Banner tone="warn">
            {raceTitleSaysRace ? (
              <>
                <b>{race.title}</b> · {raceDay(race.day)}
              </>
            ) : (
              <>
                <b>Race day</b> {raceDay(race.day)} · {race.title}
              </>
            )}
          </Banner>
        )}

        <div className="fact-list">
          {hoursLine && (
            <div>
              <span className="muted">Hours</span>
              <b>{hoursLine}</b>
            </div>
          )}
          {ent && !gated && (
            <div>
              <span className="muted">Discounted day</span>
              <b>
                {ent.discountDayEnabled
                  ? `${Math.round(ent.discountRate * 100)}% off · ${money(ent.discountPriceCents)} (day ${ent.discountDayNumber})`
                  : '—'}
              </b>
            </div>
          )}
          {ent && !gated && (
            <div>
              <span className="muted">Extra days</span>
              <b>{money(ent.extraDayPriceCents)} member rate</b>
            </div>
          )}
        </div>

        {ent && !gated && (
          <div className="track-panel-days">
            <span className="day-meter-label">Days Remaining</span>
            <DayMeter left={remaining} total={ent.includedDays} />
          </div>
        )}
        {gated && lapsed && (
          <div className="small muted">
            No active pass this season. Included days and member discounts come with a paid pass.
          </div>
        )}
      </div>

      <div className="stack track-panel-actions">
        <div className="row wrap track-panel-links">
          <Link className="track-links-btn" to={`/tracks/${track.slug}`}>
            Track profile
          </Link>
          {links.length > 0 && (
            <div className="row track-panel-socials">
              {links.map((l) => (
                <a
                  key={l.label}
                  className="track-links-btn track-links-icon"
                  href={l.href}
                  target="_blank"
                  rel="noreferrer"
                  aria-label={l.label}
                  title={l.label}
                >
                  {l.icon}
                </a>
              ))}
            </div>
          )}
        </div>
      </div>
    </section>
  );
}

import { useEffect, useRef, useState } from 'react';
import Avatar from './Avatar';
import PhotoLightbox from './PhotoLightbox';
import { api } from '../lib/api';

/** One frame attached to a review. */
export interface ReviewPhoto {
  id: string;
  url: string;
  caption: string | null;
}

/** A rider's review of a venue, as `/tracks/:slug` returns it. */
export interface TrackReview {
  id: string;
  rating: number;
  body: string;
  createdAt: string;
  updatedAt: string;
  userId: string;
  riderName: string;
  riderAvatarUrl: string | null;
  photos: ReviewPhoto[];
}

/** The frame a review is opened on in the lightbox. */
interface Viewing {
  review: TrackReview;
  index: number;
}

const MAX_PHOTOS = 6;

/** Five stars, the filled ones picking the rating. */
function Stars({ rating }: { rating: number }) {
  return (
    <span className="track-review-stars" aria-label={`${rating} out of 5`}>
      {[1, 2, 3, 4, 5].map((n) => (
        <span key={n} aria-hidden className={n <= rating ? 'on' : 'off'}>
          ★
        </span>
      ))}
    </span>
  );
}

/** Read a picked file into a base64 data URL. */
function readFile(file: File): Promise<string> {
  return new Promise((resolve) => {
    const fr = new FileReader();
    fr.onload = () => resolve(String(fr.result));
    fr.onerror = () => resolve('');
    fr.readAsDataURL(file);
  });
}

/**
 * The riders' side of a venue's page: their reviews of the place — the account
 * they wrote, the stars they gave it, and the frames they shot there.
 *
 * This is the counterpart to the venue's own gallery above it: the gallery is
 * the owner's curated art, this is the crowd's considered account. A signed-in
 * rider writes **one** review per venue and then edits that same review — its
 * words, its stars, and the photos attached to it — from the same card. Everyone
 * else reads. The venue can pull a review from its own community page.
 */
export default function TrackReviews({
  trackId,
  trackName,
  reviews,
  onChange,
  onMessage,
  onRefresh,
  currentUserId,
}: {
  trackId: string;
  trackName: string;
  reviews: TrackReview[];
  onChange: (reviews: TrackReview[]) => void;
  /** A line for the page's notice. `ok` is true for a confirmation — it floats
   *  and retires on its own — and false (default) for a refusal, which the
   *  caller keeps up longer. */
  onMessage: (msg: string, ok?: boolean) => void;
  /** Re-read the page after an edit, so the frames and the counts agree with
   *  the server without the component rebuilding the whole review by hand. */
  onRefresh?: () => void | Promise<void>;
  /** The signed-in rider, when there is one — decides the form and the edit
   *  control on their own review. */
  currentUserId?: string;
}) {
  const fileRef = useRef<HTMLInputElement>(null);
  const [open, setOpen] = useState(false);
  const [rating, setRating] = useState(5);
  const [body, setBody] = useState('');
  const [files, setFiles] = useState<File[]>([]);
  const [keep, setKeep] = useState<string[]>([]);
  const [busy, setBusy] = useState(false);
  const [viewing, setViewing] = useState<Viewing | null>(null);

  const mine = reviews.find((r) => r.userId === currentUserId);

  // Open the composer pre-filled with the review this rider already wrote.
  useEffect(() => {
    if (!open) return;
    setRating(mine?.rating ?? 5);
    setBody(mine?.body ?? '');
    setFiles([]);
    setKeep(mine?.photos.map((p) => p.id) ?? []);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  const pickFiles = (list: FileList | null) => {
    const next = Array.from(list ?? []);
    const room = MAX_PHOTOS - (mine ? keep.length : 0);
    setFiles(next.slice(0, Math.max(0, room)));
  };

  const save = async () => {
    const trimmed = body.trim();
    if (!trimmed && !files.length && !(mine && keep.length)) {
      onMessage('Write a few words or attach a photo before posting.');
      return;
    }
    setBusy(true);
    try {
      const dataUrls: string[] = [];
      for (const file of files) {
        const dataUrl = await readFile(file);
        if (!dataUrl) {
          onMessage('Could not read one of those files.');
          return;
        }
        dataUrls.push(dataUrl);
      }

      if (!mine) {
        const res = await api.post<{ review: TrackReview }>('/me/track-reviews', {
          trackId,
          rating,
          body: trimmed,
          dataUrls,
        });
        if (!res.success || !res.data?.review) {
          onMessage(res.message ?? 'Could not post your review.');
          return;
        }
        onChange([res.data.review, ...reviews]);
        setOpen(false);
        onMessage('Review posted.', true);
        return;
      }

      // An edit: the words and stars first, then the frames added and removed.
      const res = await api.patch<{ review: TrackReview }>(`/me/track-reviews/${mine.id}`, {
        rating,
        body: trimmed,
      });
      if (!res.success) {
        onMessage(res.message ?? 'Could not update your review.');
        return;
      }

      const removed = mine.photos.filter((p) => !keep.includes(p.id));
      for (const photo of removed) {
        const del = await api.del(`/me/track-reviews/${mine.id}/photos/${photo.id}`);
        if (!del.success) {
          onMessage(del.message ?? 'Could not remove one of your photos.');
          return;
        }
      }
      for (const dataUrl of dataUrls) {
        const add = await api.post(`/me/track-reviews/${mine.id}/photos`, { dataUrl });
        if (!add.success) {
          onMessage(add.message ?? 'Could not add one of your photos.');
          return;
        }
      }

      setOpen(false);
      onMessage('Review updated.', true);
      if (onRefresh) await onRefresh();
    } finally {
      setBusy(false);
      if (fileRef.current) fileRef.current.value = '';
    }
  };

  const allPhotos = (review: TrackReview) =>
    review.photos.map((p) => ({ id: p.id, url: p.url, caption: p.caption }));

  const cards = reviews.map((review) => {
    const isMine = currentUserId === review.userId;
    const edited = review.updatedAt !== review.createdAt;
    return (
      <li key={review.id} className={`track-review-card${isMine ? ' is-mine' : ''}`}>
        <div className="track-review-head">
          <Avatar src={review.riderAvatarUrl} name={review.riderName} className="track-review-face" />
          <div className="track-review-who">
            <b>{review.riderName}</b>
            <span className="tiny muted">
              {new Date(review.createdAt).toLocaleDateString()}
              {edited ? ' · edited' : ''}
            </span>
          </div>
          <Stars rating={review.rating} />
        </div>

        {review.body && <p className="track-review-body">{review.body}</p>}

        {review.photos.length > 0 && (
          <div className="track-review-shots">
            {review.photos.map((photo, i) => (
              <button
                key={photo.id}
                type="button"
                className="track-review-shot"
                onClick={() => setViewing({ review, index: i })}
                aria-label={photo.caption || `Photo by ${review.riderName}`}
              >
                <img src={photo.url} alt={photo.caption || `${trackName} by ${review.riderName}`} loading="lazy" />
              </button>
            ))}
          </div>
        )}

        {isMine && (
          <div className="track-review-actions">
            <button type="button" className="small" onClick={() => setOpen((v) => !v)}>
              {open ? 'Close editor' : 'Edit your review'}
            </button>
          </div>
        )}
      </li>
    );
  });

  return (
    <section className="card stack track-reviews">
      <div className="section-head">
        <h3>Reviews{reviews.length > 1 ? ` (${reviews.length})` : ''}</h3>
      </div>

      {currentUserId && !mine && !open && (
        <div className="track-reviews-callout">
          <p className="small muted">Ridden here? Write the one review you get on this venue.</p>
          <button type="button" className="primary small" onClick={() => setOpen(true)}>
            Write a review
          </button>
        </div>
      )}

      {currentUserId && open && (
        <div className="track-reviews-form">
          <div className="track-reviews-rating">
            <span className="small muted">Your rating</span>
            <div className="track-reviews-stars" role="radiogroup" aria-label="Rating out of five">
              {[1, 2, 3, 4, 5].map((n) => (
                <button
                  key={n}
                  type="button"
                  role="radio"
                  aria-checked={rating === n}
                  aria-label={`${n} star${n === 1 ? '' : 's'}`}
                  className={n <= rating ? 'on' : 'off'}
                  onClick={() => setRating(n)}
                >
                  ★
                </button>
              ))}
            </div>
          </div>

          <textarea
            className="track-reviews-body"
            value={body}
            onChange={(e) => setBody(e.target.value.slice(0, 2000))}
            placeholder="How was the track? Prep, layout, the crew, the day."
            maxLength={2000}
            rows={4}
            aria-label="Your review"
          />

          {mine && keep.length > 0 && (
            <div className="track-reviews-keep">
              <span className="small muted">Photos on your review</span>
              <div className="track-reviews-keep-row">
                {mine.photos.map((photo) => (
                  <label key={photo.id} className={`track-reviews-keep-item${keep.includes(photo.id) ? '' : ' off'}`}>
                    <img src={photo.url} alt={photo.caption || 'Your photo'} />
                    <input
                      type="checkbox"
                      checked={keep.includes(photo.id)}
                      onChange={(e) =>
                        setKeep((prev) =>
                          e.target.checked ? [...prev, photo.id] : prev.filter((id) => id !== photo.id)
                        )
                      }
                    />
                    <span className="tiny">{keep.includes(photo.id) ? 'Keep' : 'Remove'}</span>
                  </label>
                ))}
              </div>
            </div>
          )}

          <div className="track-reviews-form-row">
            <label className="track-reviews-pick">
              <input
                ref={fileRef}
                type="file"
                multiple
                accept="image/png,image/jpeg,image/webp,image/gif,image/avif"
                onChange={(e) => pickFiles(e.target.files)}
              />
              {files.length
                ? `${files.length} photo${files.length === 1 ? '' : 's'} chosen`
                : 'Attach photos'}
            </label>
            <span className="tiny muted">
              {keep.length + files.length}/{MAX_PHOTOS} photos
            </span>
            <button type="button" className="primary small" onClick={save} disabled={busy}>
              {busy ? 'Saving…' : mine ? 'Save changes' : 'Post review'}
            </button>
            <button type="button" className="small" onClick={() => setOpen(false)} disabled={busy}>
              Cancel
            </button>
          </div>
        </div>
      )}

      {reviews.length === 0 ? (
        <div className="small muted">
          No rider reviews here yet.
          {currentUserId ? ' Yours would be the first.' : ' Sign in to write one from a day at the track.'}
        </div>
      ) : (
        <ul className="track-reviews-list">{cards}</ul>
      )}

      {viewing && (
        <PhotoLightbox
          photos={allPhotos(viewing.review)}
          name={trackName}
          index={viewing.index}
          onIndex={(i) => setViewing({ review: viewing.review, index: i })}
          onClose={() => setViewing(null)}
        />
      )}
    </section>
  );
}

import { useRef, useState } from 'react';
import Avatar from './Avatar';
import PhotoLightbox from './PhotoLightbox';
import { api } from '../lib/api';

export interface RiderPhoto {
  id: string;
  url: string;
  caption: string | null;
  createdAt: string;
  userId: string;
  riderName: string;
  riderAvatarUrl: string | null;
}

/**
 * The riders' wall on a venue's page — the photographs riders have shot there,
 * each with the one line they wrote about it.
 *
 * This is the counterpart to the venue's own gallery above it: the gallery is
 * the owner's curated art, this is the crowd's. A signed-in rider gets the
 * upload row (a file, a caption, one button) and may take their own frame back
 * down; everyone else reads it. The venue can pull any frame from its own
 * community page.
 */
export default function TrackRiderPhotos({
  trackId,
  trackName,
  photos,
  onChange,
  onMessage,
  currentUserId,
}: {
  trackId: string;
  trackName: string;
  photos: RiderPhoto[];
  onChange: (photos: RiderPhoto[]) => void;
  /** A line for the page's notice. `ok` is true for a confirmation — it floats
   *  and retires on its own — and false (default) for a refusal, which the
   *  caller keeps up longer. */
  onMessage: (msg: string, ok?: boolean) => void;
  /** The signed-in rider, when there is one — decides the upload row and the
   *  take-it-down control on their own frames. */
  currentUserId?: string;
}) {
  const fileRef = useRef<HTMLInputElement>(null);
  const [caption, setCaption] = useState('');
  const [file, setFile] = useState<File | null>(null);
  const [busy, setBusy] = useState(false);
  const [viewing, setViewing] = useState<number | null>(null);

  const upload = async () => {
    if (!file) {
      fileRef.current?.click();
      return;
    }
    setBusy(true);
    const dataUrl = await new Promise<string>((resolve) => {
      const fr = new FileReader();
      fr.onload = () => resolve(String(fr.result));
      fr.onerror = () => resolve('');
      fr.readAsDataURL(file);
    });
    if (!dataUrl) {
      setBusy(false);
      onMessage('Could not read that file.');
      return;
    }
    const res = await api.post<{ photo: RiderPhoto }>('/me/track-photos', {
      trackId,
      dataUrl,
      caption: caption.trim() || undefined,
    });
    setBusy(false);
    if (!res.success || !res.data?.photo) {
      onMessage(res.message ?? 'Could not share that photo.');
      return;
    }
    onChange([res.data.photo, ...photos]);
    setCaption('');
    setFile(null);
    if (fileRef.current) fileRef.current.value = '';
    onMessage('Photo shared on the track page.', true);
  };

  const remove = async (photo: RiderPhoto) => {
    const res = await api.del(`/me/track-photos/${photo.id}`);
    if (!res.success) {
      onMessage(res.message ?? 'Could not remove that photo.');
      return;
    }
    onChange(photos.filter((p) => p.id !== photo.id));
    onMessage('Photo removed.', true);
  };

  return (
    <section className="card stack rider-photos">
      <div className="section-head">
        <h3>Photos from riders</h3>
        <span className="small muted">
          {photos.length} {photos.length === 1 ? 'photo' : 'photos'}
        </span>
      </div>

      {currentUserId && (
        <div className="rider-photos-form">
          <label className="rider-photos-pick">
            <input
              ref={fileRef}
              type="file"
              accept="image/png,image/jpeg,image/webp,image/gif,image/avif"
              onChange={(e) => setFile(e.target.files?.[0] ?? null)}
            />
            {file ? file.name : 'Choose a photo'}
          </label>
          <input
            className="rider-photos-caption"
            value={caption}
            onChange={(e) => setCaption(e.target.value.slice(0, 140))}
            placeholder="One line about the day"
            maxLength={140}
            aria-label="Photo caption"
          />
          <button className="primary small" onClick={upload} disabled={busy}>
            {busy ? 'Sharing…' : file ? 'Share photo' : 'Pick a photo'}
          </button>
        </div>
      )}

      {photos.length === 0 ? (
        <div className="small muted">
          No rider photos here yet.
          {currentUserId ? ' Yours would be the first.' : ' Sign in to add one from a day at the track.'}
        </div>
      ) : (
        <ul className="rider-photos-grid">
          {photos.map((p, i) => (
            <li key={p.id} className="rider-photos-card">
              <button
                type="button"
                className="rider-photos-shot"
                onClick={() => setViewing(i)}
                aria-label={p.caption || `Photo by ${p.riderName}`}
              >
                <img src={p.url} alt={p.caption || `${trackName} by ${p.riderName}`} loading="lazy" />
              </button>
              {p.caption && <p className="rider-photos-line">{p.caption}</p>}
              <div className="rider-photos-by">
                <Avatar src={p.riderAvatarUrl} name={p.riderName} className="rider-photos-face" />
                <span className="tiny muted">{p.riderName}</span>
                {currentUserId === p.userId && (
                  <button
                    type="button"
                    className="rider-photos-remove"
                    onClick={() => remove(p)}
                    title="Take your photo down"
                  >
                    Remove
                  </button>
                )}
              </div>
            </li>
          ))}
        </ul>
      )}

      {viewing !== null && (
        <PhotoLightbox
          photos={photos.map((p) => ({ id: p.id, url: p.url, caption: p.caption }))}
          name={trackName}
          index={viewing}
          onIndex={setViewing}
          onClose={() => setViewing(null)}
        />
      )}
    </section>
  );
}

import { Suspense, lazy, useState } from 'react';
import HoursWeek from './HoursWeek';
import type { HoursWeek as Week } from '../lib/hoursWeek';

const VenueMap = lazy(() => import('./VenueMap'));

/**
 * The venue's Location & Hours block: where it is, when it runs, and the ways
 * to reach it — read off the fields the venue keeps on file and nothing else.
 *
 * Two columns: the venue on its map, then the ways to reach it with the week it
 * runs stacked beneath, so the contacts and the hours read as one rail beside
 * the map. Everything a rider reads off the venue (where it is, how to reach
 * it) is in one column.
 *
 * The directions row carries the venue's full published street address, with a
 * button that copies it — that pair is the whole point of the row, since a rider
 * on a phone wants the address in their maps app, not the venue's homepage. What
 * "on file and nothing else" means: the address is the venue's own published
 * line when the row has one and the city and region when it does not, the map is
 * drawn from the coordinates, and the card lists only the contacts that exist —
 * a venue with a website gets that row, one with a phone gets that row, and one
 * with neither gets neither rather than a blank line.
 */
export interface VenueLocationTrack {
  name: string;
  city: string | null;
  region: string | null;
  /** The venue's published street address, when it keeps one on file. */
  address: string | null;
  country?: string | null;
  lat: number | null;
  lng: number | null;
  website: string | null;
  instagram: string | null;
  facebook: string | null;
  youtube: string | null;
  tiktok: string | null;
  email: string | null;
  phone: string | null;
  status: string;
  hours: string | null;
  hoursWeek: Week | null;
}

/** The site without its scheme, so the row reads as the place's address online. */
function siteLabel(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, '');
  } catch {
    return url.replace(/^https?:\/\//, '').replace(/\/+$/, '');
  }
}

