/** One row per venue: the mark's name, its icon, and the field it reads. */
const SOCIALS: {
  key: keyof VenueLocationTrack;
  label: string;
  glyph: () => JSX.Element;
}[] = [
  { key: 'instagram', label: 'Instagram', glyph: InstagramGlyph },
  { key: 'facebook', label: 'Facebook', glyph: FacebookGlyph },
  { key: 'youtube', label: 'YouTube', glyph: YouTubeGlyph },
  { key: 'tiktok', label: 'TikTok', glyph: TikTokGlyph },
];

export default function VenueLocation({ track }: { track: VenueLocationTrack }) {
  const [copied, setCopied] = useState(false);

  const where = [track.city, track.region].filter(Boolean).join(', ');
  const country = track.country && track.country !== 'US' ? track.country : '';
  // The full address the row prints and copies: the venue's own published line,
  // or the city and region it does keep on file. Never a made-up street.
  const fullAddress = track.address?.trim() || [where, country].filter(Boolean).join(' ');
  const hasFix = track.lat != null && track.lng != null;
  // The venue's own coordinates go the reader's way; without a fix the name and
  // place still find it, and a venue with neither offers no directions at all.
  const directions = hasFix
    ? `https://www.google.com/maps/dir/?api=1&destination=${track.lat},${track.lng}`
    : where
      ? `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(`${track.name}, ${where}`)}`
      : null;
  const socials = SOCIALS.map((s) => ({ ...s, url: track[s.key] })).filter(
    (s): s is typeof s & { url: string } => typeof s.url === 'string' && s.url.length > 0
  );

  /**
   * Copying goes through the async clipboard when the page has one. Served over
   * plain http (a phone on the tailnet, say) it does not, so the selection trick
   * is the fallback — the button has to work wherever the app is served from.
   */
  const copyAddress = async () => {
    try {
      await navigator.clipboard.writeText(fullAddress);
    } catch {
      const scratch = document.createElement('textarea');
      scratch.value = fullAddress;
      scratch.setAttribute('readonly', '');
      scratch.style.position = 'fixed';
      scratch.style.top = '-1000px';
      scratch.style.opacity = '0';
      document.body.appendChild(scratch);
      scratch.select();
      try {
        document.execCommand('copy');
      } catch {
        /* nothing else to try — the button simply reports nothing was copied */
      }
      document.body.removeChild(scratch);
    }
    setCopied(true);
    window.setTimeout(() => setCopied(false), COPIED_MS);
  };

  return (
    <section className="stack loc" aria-label="Location and hours">
      <div className="loc-grid">
        <div className="loc-where">
          {hasFix ? (
            <Suspense fallback={<div className="loc-map muted small" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}>Loading map…</div>}>
              <VenueMap name={track.name} lat={track.lat as number} lng={track.lng as number} />
            </Suspense>
          ) : (
            <div className="loc-map loc-map-blank small muted">No coordinates on file</div>
          )}
        </div>

        {/* The contact card and the week share one column — the ways in sit over
            the hours, so only the map stands beside them. */}
        <div className="loc-side">
          <div className="card loc-card">
            {track.website && (
              <div className="loc-row">
                <a className="loc-link" href={track.website} target="_blank" rel="noopener noreferrer">
                  {siteLabel(track.website)}
                </a>
                <span className="loc-ico">
                  <ExternalGlyph />
                </span>
              </div>
            )}

            {track.phone && (
              <div className="loc-row">
                <a className="loc-link" href={`tel:${track.phone.replace(/[^\d+]/g, '')}`}>
                  {track.phone}
                </a>
                <span className="loc-ico">
                  <PhoneGlyph />
                </span>
              </div>
            )}

            {track.email && (
              <div className="loc-row">
                <a className="loc-link" href={`mailto:${track.email}`}>
                  {track.email}
                </a>
                <span className="loc-ico">
                  <MailGlyph />
                </span>
              </div>
            )}

            <div className="loc-row">
              <span className="loc-sub">
                <span className="loc-label">Get Directions</span>
                {fullAddress && <span className="loc-line">{fullAddress}</span>}
              </span>
              <span className="loc-acts">
                {fullAddress && (
                  <button
                    type="button"
                    className={copied ? 'loc-ico-btn is-copied' : 'loc-ico-btn'}
                    onClick={copyAddress}
                    title={copied ? 'Address copied' : 'Copy the address'}
                    aria-label={copied ? 'Address copied' : 'Copy the address'}
                  >
                    {copied ? <CheckGlyph /> : <CopyGlyph />}
                  </button>
                )}
                {directions && (
                  <a
                    className="loc-dir-btn"
                    href={directions}
                    target="_blank"
                    rel="noopener noreferrer"
                    title={`Directions to ${track.name}`}
                    aria-label={`Directions to ${track.name}`}
                  >
                    <RouteGlyph />
                  </a>
                )}
              </span>
            </div>

            {socials.length > 0 && (
              <div className="loc-row">
                <span className="loc-socials">
                  {socials.map(({ label, url, glyph: Glyph }) => (
                    <a
                      key={label}
                      href={url}
                      target="_blank"
                      rel="noopener noreferrer"
                      title={label}
                      aria-label={`${track.name} on ${label}`}
                    >
                      <Glyph />
                    </a>
                  ))}
                </span>
              </div>
            )}

            {/* The copy's outcome, for a screen reader — the glyph says it to
                everyone else. */}
            <span className="loc-status" role="status" aria-live="polite">
              {copied ? 'Address copied to clipboard' : ''}
            </span>
          </div>

          <div className="loc-week">
            <HoursWeek week={track.hoursWeek} summary={track.hours} status={track.status} />
          </div>
        </div>
      </div>
    </section>
  );
}

import { useEffect, useRef } from 'react';
import * as L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import { venuePin } from '../lib/trackAccess';
import { US_BOUNDS, US_MIN_ZOOM } from '../lib/usMap';

/**
 * One venue on a map of its own, for the profile's Location & Hours block: a
 * single dot in the venue's own colour, centred on the coordinates on file.
 *
 * There is no network and no rider pin here — the venue is the whole map — so it
 * opens close in rather than framing the country. The wheel is left to the page
 * (an embedded map that swallows the scroll is a trap); the drag, the zoom
 * buttons and the venue's name on hover all still work.
 */
export default function VenueMap({
  name,
  lat,
  lng,
}: {
  name: string;
  lat: number;
  lng: number;
}) {
  const el = useRef<HTMLDivElement>(null);
  const mapRef = useRef<L.Map | null>(null);

  useEffect(() => {
    if (!el.current || mapRef.current) return;
    const c = venuePin();
    const map = L.map(el.current, {
      center: [lat, lng],
      zoom: 12,
      minZoom: US_MIN_ZOOM,
      maxBounds: US_BOUNDS,
      maxBoundsViscosity: 1.0,
      scrollWheelZoom: false,
      attributionControl: true,
      zoomControl: true,
    });
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
      subdomains: 'abc',
      referrerPolicy: 'origin',
      attribution:
        '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
    }).addTo(map);

    // The same dot the network map draws, mixed to 85% the same way, so the
    // venue's colour is one read across both maps.
    const safe = name.replace(/&/g, '&amp;').replace(/"/g, '&quot;');
    const mk = L.marker([lat, lng], {
      icon: L.divIcon({
        className: 'map-pin-wrap',
        html:
          `<span class="map-pin-dot" data-name="${safe}" ` +
          `style="background:color-mix(in srgb, ${c.bg} 85%, transparent)"></span>`,
        iconSize: [0, 0],
        iconAnchor: [0, 0],
      }),
      riseOnHover: true,
      alt: name,
    });
    mk.bindTooltip(name, { direction: 'top', offset: [0, -11], className: 'map-tip', opacity: 1 });
    mk.addTo(map);
    mapRef.current = map;

    const t = setTimeout(() => map.invalidateSize(), 200);
    return () => {
      clearTimeout(t);
      map.remove();
      mapRef.current = null;
    };
  }, [name, lat, lng]);

  return <div ref={el} className="map-dark loc-map" aria-label={`${name} on the map`} />;
}

import { useEffect, useRef, useState } from 'react';
import type { ProfileEvent } from '../lib/events';
import {
  EVENT_KIND_LABEL,
  ampmLabel,
  ampmTime,
  daysOf,
  isTimed,
  weekDays,
  weekStart,
} from '../lib/events';

/**
 * A week of the venue's season as a time grid: an all-day row over an hour
 * grid, one column a day, a date drawn where its own hours put it.
 *
 * It keeps no state of its own — whoever draws it owns the week it is showing,
 * the way `MonthGrid` owns its month — so the owner's calendar page is the only
 * thing that decides what "now" and "picked" mean. A chip is the control for
 * the date it draws — a click on one opens that date, never the day it sits
 * on — while the day header over a column is what picks a day for the page.
 *
 * Everything here is UTC about *days* (a date sits on the day its `startsAt`
 * falls on, so a Saturday never slides to Friday) and local about the *clock*
 * (the now-line is the reader's own time). Do not mix the two.
 *
 * It draws a read as readily as an edit: the page that writes hands in the
 * three slot controls, and a page that only reads leaves them off — nothing on
 * a column then takes a mark and no slot is ever drawn. `venueOf` names the
 * venue on every chip, for a week that holds more than one.
 *
 * A marked slot is worked three ways: the body dragged to move the whole block
 * — along its own day or onto another column, its length kept — and either end
 * dragged to change one time. A body that only took a click opens the sheet.
 */
const HOUR_H = 46;
const GUTTER_FROM = 8 * 60;
const GUTTER_TO = 20 * 60;

/** A slot is marked on the quarter hour, and never shorter than half of one. */
const SLOT_SNAP = 15;
const SLOT_MIN = 30;

/** The hours the owner has marked on the grid but not yet posted. */
export interface SlotDraft {
  day: string;
  start: number;
  end: number;
}

export type SlotEdge = 'start' | 'end';

/** The nearest quarter hour, so a drag lands on a time a venue would name. */
const snapTo = (minutes: number) => Math.round(minutes / SLOT_SNAP) * SLOT_SNAP;

interface Props {
  /** The venue's whole season — the grid picks the week's own dates out of it. */
  events: ProfileEvent[];
  /** Any day of the week on screen; its Monday is the column the week starts on. */
  anchor: string;
  today: string;
  picked: string | null;
  /**
   * The slot the owner has marked out, if any — a stretch of one day's clock
   * the page holds while the date is being written.
   */
  slot?: SlotDraft | null;
  onStep: (weeks: number) => void;
  onToday: () => void;
  onPickDay: (day: string) => void;
  /** A date's own chip was clicked: open that date, not the day under it. */
  onPickEvent: (ev: ProfileEvent) => void;
  /**
   * The venue a date belongs to, when a column can hold more than one — a
   * rider's calendar draws every track they follow, so a chip has to say where
   * it is. The owner's own page has one venue and nothing to say. */
  venueOf?: (ev: ProfileEvent) => string | null;
  /**
   * The three writing controls. Leave them off and the grid is a read: no hour
   * of a column takes a mark, and no slot is ever drawn — which is how the
   * rider's calendar reads the owner's own week without an editor behind it.
   */
  /** An empty hour of a column was clicked: mark that slot off. */
  onSelectSlot?: (day: string, start: number, end: number) => void;
  /** A slot's edge was dragged: the new minute it landed on, already clamped. */
  onResizeSlot?: (edge: SlotEdge, minutes: number) => void;
  /**
   * The slot's body was dragged: the day it landed on and the start it slid to,
   * its own length kept — the block moves as one, so the two times are never
   * named apart.
   */
  onMoveSlot?: (day: string, start: number, end: number) => void;
  /** The slot's own body was clicked: open the fields for it. */
  onOpenSlot?: () => void;
}

const rangeLabel = (monday: string, sunday: string) => {
  const a = new Date(`${monday}T12:00:00Z`);
  const b = new Date(`${sunday}T12:00:00Z`);
  const monthDay = (d: Date) =>
    d.toLocaleDateString(undefined, { month: 'short', day: 'numeric', timeZone: 'UTC' });
  return `${monthDay(a)} – ${monthDay(b)}, ${b.getUTCFullYear()}`;
};

export default function WeekGrid({
  events,
  anchor,
  today,
  picked,
  slot = null,
  onStep,
  onToday,
  onPickDay,
  onPickEvent,
  venueOf,
  onSelectSlot,
  onResizeSlot,
  onMoveSlot,
  onOpenSlot,
}: Props) {
  const monday = (() => {
    return weekStart(anchor);
  })();
  const days = weekDays(monday);
  const week = days.map((d) => d.key);

  /** The week's dates, each on every day it covers, so a chip lands on its day. */
  const byDay = new Map<string, ProfileEvent[]>();
  for (const ev of events) {
    for (const k of daysOf(ev)) {
      if (!week.includes(k)) continue;
      const list = byDay.get(k);
      if (list) list.push(ev);
      else byDay.set(k, [ev]);
    }
  }
  const inWeek = [...new Set(week.flatMap((k) => byDay.get(k) ?? []))].sort((a, b) =>
    a.startsAt.localeCompare(b.startsAt)
  );

  // The window the grid draws: wide enough for the week's own hours, never
  // narrower than a working day, and never off the clock. A marked slot is
  // held inside it while it is dragged, so the window never moves under the
  // pointer mid-drag.
  const timed = inWeek.filter(isTimed);
  const from = Math.max(
    0,
    Math.min(GUTTER_FROM, ...timed.map((e) => Math.floor((e.startMinutes ?? 0) / 60) * 60))
  );
  const to = Math.min(
    24 * 60,
    Math.max(
      GUTTER_TO,
      ...timed.map((e) => Math.ceil((e.endMinutes ?? 0) / 60) * 60)
    )
  );
  const hours = Array.from({ length: (to - from) / 60 + 1 }, (_, i) => from + i * 60);

  const span = (to - from) / 60;
  const top = (minutes: number) => ((minutes - from) / 60) * HOUR_H;

  // The now-line is the reader's own clock, and it only appears when today is
  // one of the columns — a hairline with no column under it reads as a mistake.
  const now = new Date();
  const nowMin = now.getHours() * 60 + now.getMinutes();
  const nowOn = week.includes(today) && nowMin > from && nowMin < to;

  /**
   * The edge being dragged, with the column's own top and the far edge it has
   * to stay clear of — read once on the way down, so the mapping from the
   * pointer to a minute never shifts while the drag is running.
   */
  const [drag, setDrag] = useState<{ edge: SlotEdge; colTop: number; other: number } | null>(null);
  const resize = useRef(onResizeSlot);
  resize.current = onResizeSlot;

  /**
   * The marked block being carried, if any. Read once on the way down — the
   * columns it may land on, the gap between the pointer and the block's own
   * start, the length it keeps — so nothing about the mapping shifts under the
   * pointer while the drag is running.
   */
  const [move, setMove] = useState(false);
  const carrying = useRef<{
    day: string;
    colTop: number;
    cols: { day: string; left: number; right: number }[];
    offset: number;
    dur: number;
    downX: number;
    downY: number;
    moved: boolean;
  } | null>(null);
  const moveSlot = useRef(onMoveSlot);
  moveSlot.current = onMoveSlot;

  /**
   * When a grip was last taken hold of, or a block last carried. Lifting the
   * pointer off either can land the click on the column underneath, which would
   * mark a fresh slot where the gesture ended — so a click arriving on the
   * heels of one is ignored.
   */
  const gripAt = useRef(0);

  /**
   * When the block was last carried anywhere. A carry ends in a click on the
   * body it was carried by, which must not also open the sheet — only a body
   * that stayed where it was put is the control that opens the fields.
   */
  const carriedAt = useRef(0);

  useEffect(() => {
    if (!drag) return;
    const move = (e: PointerEvent) => {
      const raw = from + ((e.clientY - drag.colTop) / HOUR_H) * 60;
      const at = snapTo(raw);
      if (drag.edge === 'start') {
        resize.current?.('start', Math.max(from, Math.min(at, drag.other - SLOT_MIN)));
      } else {
        resize.current?.('end', Math.min(to, Math.max(at, drag.other + SLOT_MIN)));
      }
    };
    const up = () => setDrag(null);
    document.body.style.userSelect = 'none';
    window.addEventListener('pointermove', move);
    window.addEventListener('pointerup', up);
    window.addEventListener('pointercancel', up);
    return () => {
      document.body.style.userSelect = '';
      window.removeEventListener('pointermove', move);
      window.removeEventListener('pointerup', up);
      window.removeEventListener('pointercancel', up);
    };
  }, [drag, from, to]);

  /**
   * Carrying the marked block. The minute under the pointer is read against the
   * column's own top, snapped to the quarter hour, and the block is held inside
   * the drawn window with its length kept; the column the pointer is over names
   * the day, so the block crosses to another day mid-drag. Nothing is handed
   * over until the pointer has actually travelled a few pixels, so a sloppy
   * click on the body still opens the sheet instead of nudging the slot.
   */
  useEffect(() => {
    if (!move) return;
    const at = (e: PointerEvent) => {
      const c = carrying.current;
      if (!c) return;
      if (!c.moved) {
        if (Math.abs(e.clientX - c.downX) + Math.abs(e.clientY - c.downY) < 4) return;
        c.moved = true;
      }
      const raw = from + ((e.clientY - c.colTop) / HOUR_H) * 60;
      const start = Math.max(from, Math.min(snapTo(raw - c.offset), Math.max(from, to - c.dur)));
      const over = c.cols.find((col) => e.clientX >= col.left && e.clientX < col.right);
      moveSlot.current?.(over?.day ?? c.day, start, start + c.dur);
    };
    const up = () => {
      // The gesture was a carry, not a click: the sheet stays shut.
      if (carrying.current?.moved) {
        carriedAt.current = Date.now();
        gripAt.current = Date.now();
      }
      carrying.current = null;
      setMove(false);
    };
    document.body.style.userSelect = 'none';
    window.addEventListener('pointermove', at);
    window.addEventListener('pointerup', up);
    window.addEventListener('pointercancel', up);
    return () => {
      document.body.style.userSelect = '';
      window.removeEventListener('pointermove', at);
      window.removeEventListener('pointerup', up);
      window.removeEventListener('pointercancel', up);
    };
  }, [move, from, to]);

  /** The column's empty hours are the control: a click marks off that hour —
   *  on a page that writes. A read-only week has no mark to take. */
  const selectAt = (e: React.MouseEvent<HTMLDivElement>, day: string) => {
    if (!onSelectSlot) return;
    // A date's own chip, or the slot already marked, answers its own clicks.
    if ((e.target as HTMLElement).closest('.wk-chip, .wk-slot, .wk-now')) return;
    if (Date.now() - gripAt.current < 300) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const at = snapTo(from + ((e.clientY - rect.top) / HOUR_H) * 60);
    const start = Math.max(from, Math.min(at, to - 60));
    onSelectSlot(day, start, Math.min(start + 60, to));
  };

  const beginDrag = (e: React.PointerEvent<HTMLSpanElement>, edge: SlotEdge) => {
    if (!slot) return;
    const col = e.currentTarget.closest('.wk-col') as HTMLElement | null;
    if (!col) return;
    e.preventDefault();
    e.stopPropagation();
    gripAt.current = Date.now();
    e.currentTarget.setPointerCapture?.(e.pointerId);
    setDrag({
      edge,
      colTop: col.getBoundingClientRect().top,
      other: edge === 'start' ? slot.end : slot.start,
    });
  };

  /**
   * The block itself was taken hold of. The pointer's own minute at the moment
   * down is what the block's start is measured against, so it never jumps under
   * the hand; the columns are read here, once, since none of them moves while
   * the block is being carried.
   */
  const beginMove = (e: React.PointerEvent<HTMLButtonElement>) => {
    if (!slot || !onMoveSlot) return;
    const block = e.currentTarget.closest('.wk-slot') as HTMLElement | null;
    const grid = block?.closest('.wk-grid') as HTMLElement | null;
    if (!block || !grid) return;
    e.preventDefault();
    e.stopPropagation();
    gripAt.current = Date.now();
    e.currentTarget.setPointerCapture?.(e.pointerId);
    const colTop = grid.getBoundingClientRect().top;
    carrying.current = {
      day: slot.day,
      colTop,
      cols: ([...grid.querySelectorAll('.wk-col')] as HTMLElement[]).map((el, i) => {
        const r = el.getBoundingClientRect();
        return { day: week[i], left: r.left, right: r.right };
      }),
      offset: from + ((e.clientY - colTop) / HOUR_H) * 60 - slot.start,
      dur: slot.end - slot.start,
      downX: e.clientX,
      downY: e.clientY,
      moved: false,
    };
    setMove(true);
  };

  const slotTall = slot ? top(slot.end) - top(slot.start) >= 44 : false;

  return (
    <div className="wk">
      <div className="wk-bar">
        <button className="cal-nav" onClick={() => onStep(-1)} aria-label="Previous week">
          ‹
        </button>
        <b className="wk-range">{rangeLabel(monday, days[6].key)}</b>
        <button className="cal-nav" onClick={() => onStep(1)} aria-label="Next week">
          ›
        </button>
        <button className="ghost small wk-today" onClick={onToday}>
          Today
        </button>
      </div>

      <div className="wk-grid" style={{ ['--wk-hours' as string]: String(span) }}>
        <div className="wk-corner" aria-hidden="true" />

        {days.map(({ key, dow, d }) => (
          <button
            key={key}
            type="button"
            className={[
              'wk-dow',
              key === today ? 'is-today' : '',
              key === picked ? 'is-picked' : '',
              (byDay.get(key)?.length ?? 0) > 0 ? 'has-event' : '',
            ]
              .filter(Boolean)
              .join(' ')}
            aria-pressed={key === picked}
            onClick={() => onPickDay(key)}
          >
            <span className="wk-dow-name">{dow}</span>
            <span className="wk-dow-num">{d.getUTCDate()}</span>
          </button>
        ))}

        <div className="wk-allday-label">All day</div>
        {days.map(({ key }) => (
          <div key={key} className={`wk-allday-cell${key === today ? ' is-today' : ''}`}>
            {(byDay.get(key) ?? [])
              .filter((ev) => !isTimed(ev))
              .map((ev) => (
                <button
                  key={ev.id}
                  type="button"
                  className={`wk-aday kind-${ev.kind.toLowerCase()}`}
                  title={`${venueOf?.(ev) ? `${venueOf(ev)} — ` : ''}${ev.title}: ${EVENT_KIND_LABEL[ev.kind] ?? ev.kind}`}
                  onClick={() => onPickEvent(ev)}
                >
                  <span className="wk-aday-ring" aria-hidden="true" />
                  <span className="wk-aday-title">{ev.title}</span>
                  {venueOf?.(ev) && <span className="wk-aday-venue">{venueOf(ev)}</span>}
                  <span className="wk-aday-kind">{EVENT_KIND_LABEL[ev.kind] ?? ev.kind}</span>
                </button>
              ))}
          </div>
        ))}

        <div className="wk-times" style={{ height: span * HOUR_H }}>
          {hours.map((m) => (
            <span key={m} className="wk-time" style={{ top: top(m) }}>
              {ampmTime(m)}
            </span>
          ))}
        </div>

        {days.map(({ key }) => (
          <div
            key={key}
            className={`wk-col${key === today ? ' is-today' : ''}${
              (drag && slot?.day === key) || (move && slot?.day === key) ? ' is-dragging' : ''
            }${move && slot?.day === key ? ' is-carrying' : ''}`}
            style={{ height: span * HOUR_H, backgroundSize: `100% ${HOUR_H}px` }}
            onClick={(e) => selectAt(e, key)}
          >
            {key === today && nowOn && (
              <span className="wk-now" style={{ top: top(nowMin) }} aria-hidden="true" />
            )}
            {(byDay.get(key) ?? [])
              .filter(isTimed)
              .map((ev) => {
                const start = ev.startMinutes ?? from;
                const end = Math.max(ev.endMinutes ?? start + 30, start + 30);
                return (
                  <button
                    key={`${ev.id}-${key}`}
                    type="button"
                    className={`wk-chip kind-${ev.kind.toLowerCase()}${ev.isActive === false ? ' is-hidden' : ''}`}
                    style={{ top: top(start), height: Math.max(24, top(end) - top(start)) }}
                    title={`${venueOf?.(ev) ? `${venueOf(ev)} — ` : ''}${ev.title}: ${ampmLabel(ev) ?? ''}`}
                    onClick={() => onPickEvent(ev)}
                  >
                    <span className="wk-chip-title">{ev.title}</span>
                    <span className="wk-chip-time">{ampmLabel(ev)}</span>
                    {venueOf?.(ev) && <span className="wk-chip-venue">{venueOf(ev)}</span>}
                  </button>
                );
              })}

            {/* The slot marked off but not posted yet: an outline rather than a
                kind — nothing is on the calendar until the fields are saved —
                with a grip at either end to move its hours, and a body that
                carries the whole block to another hour or another day. */}
            {slot && slot.day === key && (
              <div
                className={`wk-slot${drag || move ? ' is-dragging' : ''}${move ? ' is-carrying' : ''}`}
                style={{ top: top(slot.start), height: top(slot.end) - top(slot.start) }}
              >
                <button
                  type="button"
                  className="wk-slot-body"
                  title={
                    onMoveSlot
                      ? 'Drag to another hour or day, or click to name this date'
                      : 'Name this date and add it to the calendar'
                  }
                  onPointerDown={beginMove}
                  onClick={() => {
                    // The click that ends a carry is not the control that opens
                    // the sheet: only a body left where it was put opens it.
                    if (Date.now() - carriedAt.current < 300) return;
                    onOpenSlot?.();
                  }}
                >
                  <span className="wk-slot-time">
                    {ampmTime(slot.start)}–{ampmTime(slot.end)}
                  </span>
                  {slotTall && <span className="wk-slot-add">Add event</span>}
                </button>
                <span
                  className="wk-slot-grip is-top"
                  role="separator"
                  aria-label="Drag to change the start time"
                  onPointerDown={(e) => beginDrag(e, 'start')}
                />
                <span
                  className="wk-slot-grip is-bottom"
                  role="separator"
                  aria-label="Drag to change the end time"
                  onPointerDown={(e) => beginDrag(e, 'end')}
                />
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

const BASE = '/api';

export interface ApiResult<T> {
  success: boolean;
  message: string;
  data?: T;
  pagination?: { page: number; limit: number; total: number; totalPages: number };
  errors?: unknown;
}

async function request<T>(path: string, init: RequestInit = {}): Promise<ApiResult<T>> {
  const res = await fetch(`${BASE}${path}`, {
    credentials: 'include',
    headers: { 'Content-Type': 'application/json', ...(init.headers ?? {}) },
    ...init,
  });
  const text = await res.text();
  let json: ApiResult<T>;
  try {
    json = JSON.parse(text);
  } catch {
    throw new Error(`Unexpected response (${res.status})`);
  }
  if (!res.ok && json.success !== false) {
    return { success: false, message: `Request failed (${res.status})` };
  }
  return json;
}

export const api = {
  get: <T>(path: string) => request<T>(path),
  post: <T>(path: string, body?: unknown) =>
    request<T>(path, { method: 'POST', body: body ? JSON.stringify(body) : undefined }),
  patch: <T>(path: string, body?: unknown) =>
    request<T>(path, { method: 'PATCH', body: body ? JSON.stringify(body) : undefined }),
  put: <T>(path: string, body?: unknown) =>
    request<T>(path, { method: 'PUT', body: body ? JSON.stringify(body) : undefined }),
  del: <T>(path: string) => request<T>(path, { method: 'DELETE' }),
};

export function money(cents: number | null | undefined): string {
  if (cents == null) return '—';
  return `$${(cents / 100).toFixed(2)}`;
}

export function dayStr(d: string | Date | null | undefined): string {
  if (!d) return '—';
  return new Date(d).toISOString().slice(0, 10);
}

export function dateTimeStr(d: string | Date | null | undefined): string {
  if (!d) return '—';
  return new Date(d).toLocaleString();
}

/** Clock time alone, 24-hour: `09:41` — the gate's read of a timestamp.
    `hourCycle` is pinned so the read never flips to AM/PM by locale. */
export function timeStr(d: string | Date | null | undefined): string {
  if (!d) return '—';
  return new Date(d).toLocaleTimeString([], {
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  });
}

import { createContext, useCallback, useContext, useEffect, useMemo, useState, ReactNode } from 'react';
import { api } from './api';

export type Role = 'RIDER' | 'OPERATOR' | 'ADMIN';

export interface CurrentUser {
  id: string;
  name: string;
  email: string;
  role: Role;
  location: string | null;
  avatarUrl: string | null;
  operatorTrackId: string | null;
}

interface AuthState {
  user: CurrentUser | null;
  operatorTrack: { id: string; name: string; slug: string } | null;
  loading: boolean;
  refresh: () => Promise<void>;
  login: (email: string, password: string) => Promise<string | null>;
  register: (name: string, email: string, password: string) => Promise<string | null>;
  logout: () => Promise<void>;
}

const AuthContext = createContext<AuthState | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<CurrentUser | null>(null);
  const [operatorTrack, setOperatorTrack] = useState<AuthState['operatorTrack']>(null);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    const res = await api.get<{ user: CurrentUser | null; operatorTrack: AuthState['operatorTrack'] }>(
      '/auth/me'
    );
    setUser(res.data?.user ?? null);
    setOperatorTrack(res.data?.operatorTrack ?? null);
  }, []);

  useEffect(() => {
    refresh().finally(() => setLoading(false));
  }, [refresh]);

  const login = useCallback(
    async (email: string, password: string) => {
      const res = await api.post('/auth/login', { email, password });
      if (!res.success) return res.message;
      await refresh();
      return null;
    },
    [refresh]
  );

  const register = useCallback(
    async (name: string, email: string, password: string) => {
      const res = await api.post('/auth/register', { name, email, password });
      if (!res.success) return res.message;
      await refresh();
      return null;
    },
    [refresh]
  );

  const logout = useCallback(async () => {
    await api.post('/auth/logout');
    setUser(null);
    setOperatorTrack(null);
  }, []);

  const value = useMemo(
    () => ({ user, operatorTrack, loading, refresh, login, register, logout }),
    [user, operatorTrack, loading, refresh, login, register, logout]
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth(): AuthState {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used inside AuthProvider');
  return ctx;
}

export function homePathFor(role: Role | undefined): string {
  if (role === 'ADMIN') return '/admin';
  if (role === 'OPERATOR') return '/operator/dashboard';
  return '/tracks';
}

