/**
 * Helpers for dragging a photo to a new place in the gallery.
 *
 * Insertion is expressed the way the pointer sees it: "put it before this one"
 * or "put it after this one", with `toInsert` the gap index into the list as it
 * stands (0…length). Taking the dragged item out first shifts every gap after
 * it down one, so the same arithmetic lives here for both the console list and
 * the lightbox filmstrip — and for anything that has to follow a frame that
 * moved, like the open photo.
 */

export function reorder<T>(items: T[], from: number, toInsert: number): { items: T[]; moved: number[] } {
  const n = items.length;
  if (from < 0 || from >= n) return { items, moved: items.map((_, i) => i) };
  const at = Math.max(0, Math.min(n, toInsert));
  const insertAt = from < at ? at - 1 : at;

  const positions = items.map((_, i) => i);
  const next = items.slice();

  const [item] = next.splice(from, 1);
  next.splice(insertAt, 0, item);
  const [oldIndex] = positions.splice(from, 1);
  positions.splice(insertAt, 0, oldIndex);

  // moved[oldIndex] = where that item sits now.
  const moved: number[] = [];
  positions.forEach((old, now) => {
    moved[old] = now;
  });

  return { items: next, moved };
}

/** Which side of the element the pointer is on — top/left half, or bottom/right. */
export function dropSide(
  event: { clientX: number; clientY: number },
  rect: { top: number; left: number; width: number; height: number },
  axis: 'x' | 'y' = 'y'
): 'before' | 'after' {
  if (axis === 'x') return event.clientX < rect.left + rect.width / 2 ? 'before' : 'after';
  return event.clientY < rect.top + rect.height / 2 ? 'before' : 'after';
}

/** Gap index for a drop onto item `index` on the given side. */
export function insertAt(index: number, side: 'before' | 'after'): number {
  return side === 'before' ? index : index + 1;
}

/**
 * A venue's dated schedule, shared by the profile page and its calendar.
 *
 * An event is a calendar day, stored at noon UTC (see the owner controller's
 * `toDate`), so every read of it here goes through UTC. Formatting it in the
 * viewer's own zone is what puts a Saturday practice on the Friday column.
 */
export interface ProfileEvent {
  id: string;
  title: string;
  description: string | null;
  kind: string;
  startsAt: string;
  endsAt: string | null;
  /**
   * The hours the date runs, as minutes past midnight on its own day, or `null`
   * for an all-day date (which the calendar draws in its all-day row). The day
   * and the hours are kept apart on purpose: the day is UTC, the hours are
   * venue-local, and neither reads the other's clock.
   */
  startMinutes: number | null;
  endMinutes: number | null;
  /**
   * The owner's own read. The public profile serves active dates only, so this
   * is what the owner's calendar dims a hidden date with.
   */
  isActive?: boolean;
}

export const EVENT_KIND_LABEL: Record<string, string> = {
  PRACTICE: 'Practice',
  RACE: 'Race',
  CLINIC: 'Clinic',
  RIDE_DAY: 'Ride day',
  OTHER: 'Event',
};

/**
 * One day's posted gate read: Open, Caution or Closed on a calendar date,
 * with the operator's note for that day. A day with no read follows the
 * venue's live line.
 */
export interface DayStatus {
  day: string;
  status: string;
  statusNote: string | null;
}

/** The gate reads an owner may post, in the order the editor offers them. */
export const DAY_STATUS_OPTIONS = ['OPEN', 'WEATHER_HOLD', 'CLOSED'] as const;

/** What a gate read is called in the editor and on the calendar. */
export const DAY_STATUS_LABEL: Record<string, string> = {
  OPEN: 'Open',
  WEATHER_HOLD: 'Caution',
  CLOSED: 'Closed',
};

/** Today on the venue's own clock, as `YYYY-MM-DD`. The gate's day rolls over at
 *  local midnight, so this must not read the UTC date — at 9 PM Eastern the UTC
 *  clock already reads tomorrow. */
export function todayKey(): string {
  const now = new Date();
  const m = String(now.getMonth() + 1).padStart(2, '0');
  const d = String(now.getDate()).padStart(2, '0');
  return `${now.getFullYear()}-${m}-${d}`;
}

/** `YYYY-MM-DD` shifted by `delta` days, through noon UTC like the rows. */
export function shiftDay(day: string, delta: number): string {
  const d = new Date(`${day}T12:00:00Z`);
  d.setUTCDate(d.getUTCDate() + delta);
  return d.toISOString().slice(0, 10);
}

/** The kinds an owner may post, in the order an editor offers them. */
export const EVENT_KINDS = ['PRACTICE', 'RACE', 'CLINIC', 'RIDE_DAY', 'OTHER'];

/**
 * What a kind reads as in the owner's editor. Separate from
 * `EVENT_KIND_LABEL`, which is the pill a reader sees: an unclassified date is
 * an `Other` to post and an `Event` to read.
 */
export const EVENT_KIND_OPTION: Record<string, string> = {
  PRACTICE: 'Practice',
  RACE: 'Race',
  CLINIC: 'Clinic',
  RIDE_DAY: 'Ride day',
  OTHER: 'Other',
};

/** The calendar day an event's instant falls on. */
export function dayKey(iso: string) {
  return new Date(iso).toISOString().slice(0, 10);
}

/** `Sat, Oct 17`, or a span when the event runs more than one day. */
export function dayRange(ev: ProfileEvent) {
  const start = new Date(ev.startsAt);
  const label = start.toLocaleDateString(undefined, {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
    timeZone: 'UTC',
  });
  if (!ev.endsAt) return label;
  const end = new Date(ev.endsAt);
  if (dayKey(ev.endsAt) === dayKey(ev.startsAt)) return label;
  return `${label} – ${end.toLocaleDateString(undefined, {
    month: 'short',
    day: 'numeric',
    timeZone: 'UTC',
  })}`;
}

/* ---- Calendar math ---------------------------------------------------- */

/** Five dates to a page, as the venue profile's schedule pages them. */
export const CAL_PER_PAGE = 5;

/** The first of `month`, stepping whole months without a timezone in the way. */
export function firstOfMonth(year: number, month: number) {
  return new Date(Date.UTC(year, month, 1));
}

/**
 * Every day of the six-week grid that holds the month, starting on Sunday. A
 * month's grid is always 42 cells so the reader's chevrons never move the rows.
 */
export function gridDays(year: number, month: number) {
  const first = firstOfMonth(year, month);
  const lead = first.getUTCDay();
  const start = new Date(Date.UTC(year, month, 1 - lead));
  return Array.from({ length: 42 }, (_, i) => {
    const d = new Date(start.getTime());
    d.setUTCDate(start.getUTCDate() + i);
    return { d, key: d.toISOString().slice(0, 10), inMonth: d.getUTCMonth() === month };
  });
}

/** An event sits on every day it runs, so a weekend reads on both days. */
export function daysOf(ev: ProfileEvent): string[] {
  const start = dayKey(ev.startsAt);
  const end = ev.endsAt ? dayKey(ev.endsAt) : start;
  if (end <= start) return [start];
  const out: string[] = [];
  const d = new Date(`${start}T12:00:00Z`);
  const last = new Date(`${end}T12:00:00Z`).getTime();
  while (d.getTime() <= last && out.length < 60) {
    out.push(d.toISOString().slice(0, 10));
    d.setUTCDate(d.getUTCDate() + 1);
  }
  return out;
}

/** The month an event starts in, as `YYYY-MM` — the key a month's view holds. */
export function monthKey(date: { year: number; month: number }) {
  return `${date.year}-${String(date.month + 1).padStart(2, '0')}`;
}

/* ---- The hours a date runs -------------------------------------------- */

/** `09:00` — 24-hour, the value a time field holds and posts. */
export function clockTime(minutes: number) {
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

/**
 * `9:15am` — the same clock read the way a sign outside a venue reads it.
 * Lower case and tight, so it reads the same in a grid row and in prose. A
 * whole hour drops its minutes, so the gutter reads `4pm` rather than `4:00pm`.
 */
export function ampmTime(minutes: number) {
  const h24 = Math.floor(minutes / 60) % 24;
  const m = minutes % 60;
  const h = h24 % 12 || 12;
  return `${h}${m ? `:${String(m).padStart(2, '0')}` : ''}${h24 < 12 ? 'am' : 'pm'}`;
}

/** `HH:MM` back to minutes past midnight — `null` for an empty field. */
export function minutesOf(value: string): number | null {
  if (!value) return null;
  const [h, m] = value.split(':').map(Number);
  return Number.isFinite(h) && Number.isFinite(m) ? h * 60 + m : null;
}

/** What a time input holds: `HH:MM`, or an empty field for an all-day date. */
export function timeValue(minutes: number | null | undefined) {
  return typeof minutes === 'number' ? clockTime(minutes) : '';
}

/**
 * The same hours in am/pm — `9am–4pm` — the reading a date card and a grid row
 * share, so the calendar never shows a clock two ways. A date with a start and
 * no end reads its start alone rather than an open-ended dash.
 */
export function ampmLabel(ev: ProfileEvent): string | null {
  const from = ev.startMinutes;
  const to = ev.endMinutes;
  if (from == null && to == null) return null;
  if (from == null) return ampmTime(to!);
  if (to == null) return ampmTime(from);
  return `${ampmTime(from)}–${ampmTime(to)}`;
}

/**
 * A date earns the hour grid only when it is both timed and single-day: a run
 * across days is a bar in the all-day row, however its first day is timed —
 * drawing it in one column would hide the days it covers.
 */
export function isTimed(ev: ProfileEvent) {
  return ev.startMinutes != null && dayKey(ev.startsAt) === dayKey(ev.endsAt ?? ev.startsAt);
}

/* ---- The week a day falls in ----------------------------------------- */

const WEEKDAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

/** The Monday of the week a day falls in, as `YYYY-MM-DD`. */
export function weekStart(day: string) {
  const d = new Date(`${day}T12:00:00Z`);
  const back = (d.getUTCDay() + 6) % 7;
  d.setUTCDate(d.getUTCDate() - back);
  return d.toISOString().slice(0, 10);
}

/** Seven days from a week's Monday — the columns a week view draws. */
export function weekDays(monday: string) {
  const start = new Date(`${monday}T12:00:00Z`);
  return Array.from({ length: 7 }, (_, i) => {
    const d = new Date(start.getTime());
    d.setUTCDate(start.getUTCDate() + i);
    return { d, key: d.toISOString().slice(0, 10), dow: WEEKDAYS[i] };
  });
}

/** The Monday `weeks` weeks either side of one — a week view's own stepping. */
export function stepWeek(monday: string, weeks: number) {
  const d = new Date(`${monday}T12:00:00Z`);
  d.setUTCDate(d.getUTCDate() + weeks * 7);
  return d.toISOString().slice(0, 10);
}

/** The month a week's Monday falls in, as `YYYY-MM` — what the head is called. */
export function weekMonth(monday: string) {
  return monday.slice(0, 7);
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { US_BOUNDS } from './usMap';

/**
 * The rider's own position, for the one pin on the network map that is not a
 * venue. Nothing is stored or sent anywhere: the browser's geolocation API is
 * asked once per page load, and the answer is held in module scope so it
 * survives the map being torn down by a route change and rebuilt. Landing on
 * `/tracks` asks by default — that is the point of the pin — and a site the
 * browser has already refused is not asked again; the control reports it.
 */

export type Fix = { lat: number; lng: number; accuracy: number };

/**
 * `on` means a fix is in hand; `outside` means it is off the map's US frame;
 * `insecure` means the page is not a secure context, where a browser will not
 * hand a position over at all — the tailnet link is served over plain http.
 */
export type GeoState =
  | 'idle'
  | 'asking'
  | 'on'
  | 'outside'
  | 'denied'
  | 'unavailable'
  | 'insecure'
  | 'unsupported';

/** The states an ask can end on without a fix: every way it comes back empty-handed. */
export type GeoFailKind = Exclude<GeoState, 'idle' | 'asking' | 'on'>;

/**
 * The copy for each of those states. The control carries all of it: the three
 * words on the label, and this sentence in the hint that opens under the control
 * while the pointer is over it. Nothing is put on the page for them — a notice in
 * the flow, or a toast over the map, is a second telling of a fact the control
 * the reader is already looking at can say itself.
 */
export const GEO_FAIL_COPY: Record<GeoFailKind, string> = {
  denied: 'Location is blocked for this site. Allow it in your browser, then try the location button again.',
  unavailable: 'Your position could not be read. Try the location button again.',
  insecure: 'Location needs a secure page. Open the https address to place your pin.',
  unsupported: 'This browser cannot share a position.',
  outside: 'Your position is outside the map, so no pin was placed.',
};

let fix: Fix | null = null;
/** The rider can put the pin away; that choice rides the session with the fix. */
let putAway = false;
/** One ask per page load, whichever way a remount or StrictMode replays it. */
let askedOnLanding = false;

const inFrame = (f: Fix) => US_BOUNDS.contains([f.lat, f.lng]);

/** What the browser already decided about this origin, without prompting it. */
async function permissionState(): Promise<PermissionState | null> {
  try {
    const s = await navigator.permissions?.query({ name: 'geolocation' as PermissionName });
    return s?.state ?? null;
  } catch {
    return null; // Safari does not carry geolocation in the permissions API.
  }
}

/**
 * The sentence for a failed ask, or null while an ask is still its own business
 * (nothing to explain when the pin lands, or before it is asked for). The map
 * shows it in the control's hint; nothing else has to know which state says what.
 */
export function locateHintText(state: GeoState): string | null {
  return state in GEO_FAIL_COPY ? GEO_FAIL_COPY[state as GeoFailKind] : null;
}

export function useRiderLocation() {
  const [state, setState] = useState<GeoState>(() => {
    const f = fix;
    if (!f) return 'idle';
    return inFrame(f) ? 'on' : 'outside';
  });
  const [shown, setShown] = useState(() => {
    const f = fix;
    if (!f) return false;
    return inFrame(f) && !putAway;
  });
  const asking = useRef(false);

  /** Every way an ask comes back empty-handed lands on the control's own label. */
  const fail = useCallback((kind: GeoFailKind) => setState(kind), []);

  const locate = useCallback(async () => {
    if (asking.current) return;
    if (typeof window !== 'undefined' && !window.isSecureContext) {
      fail('insecure');
      return;
    }
    if (typeof navigator === 'undefined' || !('geolocation' in navigator)) {
      fail('unsupported');
      return;
    }
    asking.current = true;
    setState('asking');
    if ((await permissionState()) === 'denied') {
      asking.current = false;
      fail('denied');
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (p) => {
        asking.current = false;
        const next: Fix = {
          lat: p.coords.latitude,
          lng: p.coords.longitude,
          accuracy: p.coords.accuracy,
        };
        fix = next;
        const ok = inFrame(next);
        // A fix off the map's frame is no pin: the control says so, like the rest.
        if (ok) setState('on');
        else fail('outside');
        setShown(ok);
      },
      (e) => {
        asking.current = false;
        fail(e.code === e.PERMISSION_DENIED ? 'denied' : 'unavailable');
      },
      { enableHighAccuracy: false, timeout: 12000, maximumAge: 300000 },
    );
  }, [fail]);

  useEffect(() => {
    if (fix || askedOnLanding) return;
    askedOnLanding = true;
    void locate();
  }, [locate]);

  const toggle = useCallback(() => {
    if (state === 'asking' || state === 'denied' || state === 'insecure' || state === 'unsupported') return;
    if (state === 'on') {
      putAway = shown;
      setShown(!shown);
      return;
    }
    void locate(); // idle, unavailable or off the frame: ask again.
  }, [state, shown, locate]);

  return { fix, state, shown, toggle };
}

/**
 * The venue week, as the API serves it: `{ mon: 'Practice 9am–4pm', … }` for
 * Mon..Sun, with `Closed` on a day the venue does not run.
 *
 * The owner console posts the same shape back as JSON on `hoursWeek`; the
 * helpers here are the only place that string is built or read, so a day the
 * venue clears reads `Closed` everywhere rather than blank on one surface.
 */

export const HOURS_WEEK_DAYS = [
  { key: 'mon', label: 'Mon', full: 'Monday' },
  { key: 'tue', label: 'Tue', full: 'Tuesday' },
  { key: 'wed', label: 'Wed', full: 'Wednesday' },
  { key: 'thu', label: 'Thu', full: 'Thursday' },
  { key: 'fri', label: 'Fri', full: 'Friday' },
  { key: 'sat', label: 'Sat', full: 'Saturday' },
  { key: 'sun', label: 'Sun', full: 'Sunday' },
] as const;

export type HoursWeekKey = (typeof HOURS_WEEK_DAYS)[number]['key'];
export type HoursWeek = Record<HoursWeekKey, string>;

/** The label a day with no hours on file reads as. */
export const HOURS_CLOSED = 'Closed';

/** A week off the API (or off the owner row's JSON string) — null when there is none. */
export function parseHoursWeek(raw: string | HoursWeek | null | undefined): HoursWeek | null {
  if (!raw) return null;
  let parsed: unknown = raw;
  if (typeof raw === 'string') {
    try {
      parsed = JSON.parse(raw);
    } catch {
      return null;
    }
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;
  const src = parsed as Record<string, unknown>;
  const week = {} as HoursWeek;
  for (const { key } of HOURS_WEEK_DAYS) {
    const value = src[key];
    if (typeof value !== 'string') return null;
    week[key] = value.trim() === '' ? HOURS_CLOSED : value.trim();
  }
  return week;
}

/** Wednesday reads 'wed' — the order JS hands back starts on Sunday. */
export function todayHoursKey(date: Date = new Date()): HoursWeekKey {
  const byWeekday: HoursWeekKey[] = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
  return byWeekday[date.getDay()];
}

/**
 * The console's seven fields → the JSON string the API stores. A day left blank
 * is a day the venue is shut, and a week with nothing in it at all clears the
 * field rather than saving seven `Closed` lines over a venue that never set one.
 */
export function serializeHoursWeek(days: Partial<Record<HoursWeekKey, string>>): string {
  const filled = HOURS_WEEK_DAYS.map(({ key }) => [key, (days[key] ?? '').trim()] as const);
  if (filled.every(([, value]) => value === '')) return '';
  const week = Object.fromEntries(filled.map(([key, value]) => [key, value || HOURS_CLOSED]));
  return JSON.stringify(week);
}

/** The word a venue's line opens with — what runs there, not when it runs. The
 *  panel's Hours row answers "which days", so the label comes off. */
const LEAD_LABEL = /^(?:open\s+practice|practice|gate)\b[\s·:–-]*/i;

/** A line that already names its own days needs no prefix from the week. */
const NAMES_DAYS = /\b(?:mon|tue|wed|thu|fri|sat|sun|weekend|weekday|daily)s?\b/i;

function stripLabel(value: string): string {
  return value.replace(LEAD_LABEL, '').trim() || value.trim();
}

/** `['Wed','Thu','Fri','Sat','Sun']` → `Wed–Sun`; one day reads as itself. */
function runLabel(labels: string[]): string {
  return labels.length === 1 ? labels[0] : `${labels[0]}–${labels[labels.length - 1]}`;
}

/**
 * The panel's one-line read of a venue's week: the days it runs, then the hours
 * it runs them — `Wed–Sun · 8am–3pm`. Most partner tracks are weekend venues, so
 * the days are the part a rider is actually asking for; the seeded line's own
 * label ("Practice 9am–4pm") never told them.
 *
 * Days are grouped into runs that share a line, so a venue with one midweek
 * evening and a weekend window prints both (`Wed 3pm–dark · Sat–Sun 8am–4pm`),
 * and a line that already names its days is printed as it stands. No week on
 * file falls back to the venue's summary line, minus its label.
 */
export function hoursWeekLine(week: HoursWeek | null | undefined, summary?: string | null): string | null {
  const fallback = summary ? stripLabel(summary) : '';
  if (!week) return fallback || null;

  const open = HOURS_WEEK_DAYS.map(({ key, label }, index) => ({
    index,
    label,
    time: (week[key] ?? '').trim(),
  })).filter(({ time }) => time !== '' && time !== HOURS_CLOSED);
  if (!open.length) return fallback || HOURS_CLOSED;

  const groups: { labels: string[]; time: string }[] = [];
  let previousIndex = -2;
  for (const day of open) {
    const last = groups[groups.length - 1];
    if (last && last.time === day.time && previousIndex === day.index - 1) {
      last.labels.push(day.label);
    } else {
      groups.push({ labels: [day.label], time: day.time });
    }
    previousIndex = day.index;
  }

  const parts = groups.map(({ labels, time }) => {
    const clean = stripLabel(time);
    return NAMES_DAYS.test(clean) ? clean : `${runLabel(labels)} · ${clean}`;
  });
  return [...new Set(parts)].join(' · ');
}

/**
 * The gate's search rules, kept identical to the server's copy in
 * `server/src/utils/lookupInput.ts`: the panel refuses to send a bad key, and
 * the route refuses one that arrives anyway, so neither side trusts the other.
 *
 * Two of the three keys must be complete values: an address is submitted whole
 * (local part @ domain with a real TLD), and a number is submitted with every
 * digit it has. A name still answers on part of one.
 */

export type LookupField = 'email' | 'name' | 'phone';

/** The shortest key each field takes. A name answers on its first letter, so
    the gate can search a rider off one keystroke. */
export const LOOKUP_MIN: Record<LookupField, number> = {
  email: 2,
  name: 1,
  phone: 2,
};

/** What each field can hold, in characters. A phone's cap is on digits. */
export const LOOKUP_MAX: Record<LookupField, number> = {
  email: 254,
  name: 80,
  phone: 15,
};

/** The part before the @, at most. */
const EMAIL_LOCAL_MAX = 64;

/** Control characters, zero-width joiners and bidi overrides: never part of a
    name, an address or a number typed at a window. */
const CONTROL = /[\u0000-\u001F\u007F-\u009F\u00AD\u200B-\u200F\u202A-\u202E\u2060-\u206F\uFEFF]/g;

export function sanitizeLookupText(raw: unknown): string {
  return String(raw ?? '')
    .replace(CONTROL, '')
    .replace(/\s+/g, ' ')
    .trim();
}

/* A whole address: a local part, an @, a dotted domain, and a two-letter or
   longer TLD. `riley@x`, `riley@example` and bare `riley` are all incomplete. */
const EMAIL =
  /^[A-Za-z0-9_%+-]+(?:\.[A-Za-z0-9_%+-]+)*@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\.)+[A-Za-z]{2,}$/;
/* The characters an address is typed with, so half of one is not called wrong
   while it is still being typed. At most one @. */
const EMAIL_TYPING = /^[A-Za-z0-9._%+-]*(@[A-Za-z0-9.-]*)?$/;
const NAME = /^[\p{L}\p{M}][\p{L}\p{M}\s'’.-]*$/u;
const PHONE_CHARS = /^[\d\s()+.-]+$/;

export type LookupCheck =
  | { ok: true; field: LookupField; text: string }
  | { ok: false; field: LookupField; text: string; message: string; incomplete?: boolean };

export function checkLookupInput(field: LookupField, raw: unknown): LookupCheck {
  const text = sanitizeLookupText(raw);
  /* `incomplete` marks a key that is the start of a good value — half an
     address, a number still being typed. The panel keeps the button out of
     reach and says so quietly instead of calling it wrong. */
  const fail = (message: string, incomplete = false): LookupCheck =>
    incomplete
      ? { ok: false, field, text, message, incomplete }
      : { ok: false, field, text, message };

  if (field === 'phone') {
    if (!text) return fail('Enter a phone number.', true);
    if (!PHONE_CHARS.test(text)) return fail('Phone can hold digits, spaces, and + ( ) - . only.');
    const digits = text.replace(/\D/g, '');
    if (digits.length > LOOKUP_MAX.phone) return fail('That is longer than a phone number.');
    const international = text.startsWith('+');
    const complete =
      international
        ? digits.length >= 8
        : digits.length === 10 || (digits.length === 11 && digits[0] === '1');
    if (complete) return { ok: true, field, text };
    if (international || digits.length < 10) {
      return fail(
        international
          ? 'Enter the full number, country code and all.'
          : 'Enter the full 10-digit phone number.',
        true
      );
    }
    /* Ten digits plus a stray one, and no leading 1: nothing to wait for. */
    return fail('Enter a 10-digit phone number, or 11 digits with a leading 1.');
  }

  if (field === 'email') {
    if (!text) return fail('Enter an email address.', true);
    if (text.length > LOOKUP_MAX.email) return fail('That is longer than an email address.');
    if (!EMAIL.test(text)) {
      if (EMAIL_TYPING.test(text) && text.split('@').length <= 2) {
        return fail('Enter the whole address, like riley@example.com.', true);
      }
      return fail('Enter a whole email address: letters, digits and . _ % + - , one @, and a domain.');
    }
    if (text.split('@')[0].length > EMAIL_LOCAL_MAX) {
      return fail('The part before the @ is too long.');
    }
    return { ok: true, field, text };
  }

  if (text.length < LOOKUP_MIN[field]) return fail('Type a name to search.', true);

  if (text.length > LOOKUP_MAX[field]) return fail('That is longer than a name.');

  if (!NAME.test(text)) {
    return fail('Name can hold letters, spaces, hyphens and apostrophes only.');
  }
  return { ok: true, field, text };
}

/** Trim + strip controls on every keystroke, and cap the length so a paste
    cannot put more in the box than the route will accept. */
export function sanitizeLookupDraft(field: LookupField, raw: string): string {
  const clean = String(raw ?? '').replace(CONTROL, '');
  if (field === 'phone') {
    const formatted = clean.replace(/[^\d\s()+.-]/g, '');
    const digits = formatted.replace(/\D/g, '');
    if (digits.length <= LOOKUP_MAX.phone) return formatted;
    /* Over-long: keep only the first 15 digits, formatting and all. */
    let kept = '';
    let n = 0;
    for (const ch of formatted) {
      if (/\d/.test(ch)) {
        if (n >= LOOKUP_MAX.phone) continue;
        n += 1;
      }
      kept += ch;
    }
    return kept;
  }
  return clean.slice(0, LOOKUP_MAX[field]);
}

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type Dispatch,
  type ReactNode,
  type SetStateAction,
} from 'react';
import { useLocation } from 'react-router-dom';
import { api } from './api';
import { useAuth } from './auth';
import { statusLabel, type MapTrack } from './trackAccess';

/** A venue's type, spelled the way the app labels it beside a track's name. */
export const CATEGORY_LABEL: Record<string, string> = {
  MX: 'Motocross track',
};

export function categoryLabel(): string {
  return CATEGORY_LABEL.MX;
}

/**
 * How strongly one field answers one token. An exact field beats a field that
 * opens with it, which beats a word inside it, which beats a mere substring —
 * and the name carries four times the weight of the region, so a venue called
 * "Valley" sorts above one merely sitting in Valley County.
 */
function fieldScore(field: string | null | undefined, token: string, weight: number): number {
  if (!field) return 0;
  const f = field.toLowerCase();
  if (f === token) return weight * 4;
  if (f.startsWith(token)) return weight * 3;
  if (f.split(/[\s,]+/).some((word) => word.startsWith(token))) return weight * 2;
  return f.includes(token) ? weight : 0;
}

export interface TrackMatch {
  track: MapTrack;
  score: number;
  /** The query reached the venue's own name, not only where it is. */
  byName: boolean;
}

/**
 * The ranked answer to a typed query, or `[]` for an empty one.
 *
 * Every token has to land somewhere, so "top nc" finds Top Gun in North
 * Carolina while "top wa" finds nothing — a query is read as a set of
 * requirements rather than one substring. Matching runs over the name, the
 * city, the region, the venue type and the live status, so "motocross",
 * "open" and "az" each find their set. The best answer sorts first: a venue whose own
 * name answers the query outranks one that answers only with its location, and
 * ties fall back to the alphabet so the list never reshuffles between renders.
 */
export function matchTracks(tracks: MapTrack[], query: string): TrackMatch[] {
  const tokens = query.trim().toLowerCase().split(/\s+/).filter(Boolean);
  if (!tokens.length) return [];

  const out: TrackMatch[] = [];
  for (const track of tracks) {
    let score = 0;
    let byName = false;
    let whole = true;
    for (const token of tokens) {
      const name = fieldScore(track.name, token, 6);
      const best = Math.max(
        name,
        fieldScore(track.city, token, 3),
        fieldScore(track.region, token, 2),
        fieldScore(categoryLabel(), token, 2),
        fieldScore(statusLabel(track.status), token, 1)
      );
      if (!best) {
        whole = false;
        break;
      }
      if (name) byName = true;
      score += best;
    }
    if (whole) out.push({ track, score, byName });
  }

  return out.sort((a, b) => b.score - a.score || a.track.name.localeCompare(b.track.name));
}

interface NetworkSearchValue {
  /** The partner network, once it has been asked for; empty until then. */
  tracks: MapTrack[];
  /** Replaces the network in place — a follow control moves it without a refetch. */
  setTracks: Dispatch<SetStateAction<MapTrack[]>>;
  /** True until the network has landed, or while it is being refetched. */
  loading: boolean;
  /** Bring the network in. The header field calls this when it is reached into. */
  ensure: () => void;
  /** What was typed into the header field. */
  q: string;
  setQ: (q: string) => void;
  /** The ranked matches for `q`; empty when nothing is typed. */
  results: TrackMatch[];
}

const NetworkSearchContext = createContext<NetworkSearchValue | null>(null);

/**
 * One copy of the network for the whole shell: the header field and the network
 * page's rail read the same query and the same tracks, so the two never
 * disagree about what is on screen.
 *
 * The fetch is deferred until something actually needs it — the network page on
 * open, or the header field the moment it is reached into — so the landing and
 * pricing pages do not pay for a list they never show.
 */
export function NetworkSearchProvider({ children }: { children: ReactNode }) {
  const { user, loading: authLoading } = useAuth();
  const { pathname } = useLocation();
  const [tracks, setTracks] = useState<MapTrack[]>([]);
  const [loading, setLoading] = useState(true);
  const [requested, setRequested] = useState(false);
  const [q, setQ] = useState('');

  const ensure = useCallback(() => setRequested(true), []);

  /** The network page is the list's own home: it asks for it as it opens. */
  useEffect(() => {
    if (pathname === '/tracks') setRequested(true);
  }, [pathname]);

  useEffect(() => {
    if (!requested || authLoading) return;
    let live = true;
    setLoading(true);
    api.get<{ tracks: MapTrack[] }>('/tracks').then((t) => {
      if (!live) return;
      setTracks(t.data?.tracks ?? []);
      setLoading(false);
    });
    return () => {
      live = false;
    };
  }, [requested, user, authLoading]);

  const results = useMemo(() => matchTracks(tracks, q), [tracks, q]);

  const value = useMemo(
    () => ({ tracks, setTracks, loading, ensure, q, setQ, results }),
    [tracks, loading, ensure, q, results]
  );

  return <NetworkSearchContext.Provider value={value}>{children}</NetworkSearchContext.Provider>;
}

export function useNetworkSearch(): NetworkSearchValue {
  const ctx = useContext(NetworkSearchContext);
  if (!ctx) throw new Error('useNetworkSearch must be used inside NetworkSearchProvider');
  return ctx;
}

/**
 * Server reason codes, in English.
 *
 * The API's `reasonCode` is the validator's own identifier (`NO_DAYS_REMAINING`,
 * `PASS_EXPIRED`, …) and stays on the wire — the suites assert it. The gate
 * reads them, so the surfaces print a plain label instead, one per code, and
 * anything unmapped falls back to a de-underscored sentence so a new code can
 * never show up on a screen as SHOUTING_SNAKE_CASE.
 */
export const REASON_LABELS: Record<string, string> = {
  // Gate decisions
  APPROVED: 'Approved',
  APPROVED_DISCOUNT: 'Approved, extra day',
  DENIED: 'Denied',
  NO_PASS: 'No pass on the account',
  PASS_CANCELLED: 'Pass cancelled',
  PASS_NOT_ACTIVATED: 'Pass not activated',
  PASS_EXPIRED: 'Pass expired',
  ALREADY_USED_TODAY: 'Already rode today',
  NOT_REDEEMED_TODAY: 'No ride today',
  RE_ENTRY: 'Re-entry',
  TRACK_NOT_PARTICIPATING: 'Not valid at this track',
  RESERVATION_REQUIRED: 'Reservation required',
  NO_DAYS_REMAINING: 'No days left this season',
  // Pass codes read off a QR
  MALFORMED: 'Unreadable pass code',
  BAD_SIGNATURE: 'Invalid pass code',
  EXPIRED: 'Pass code expired',
  // The request never reached the server
  CLIENT_ERROR: 'Could not reach the server',
};

/** `NO_DAYS_REMAINING` → `No days left this season`; unknown codes read as a sentence. */
export function reasonLabel(code: string | null | undefined): string {
  if (!code) return '';
  const known = REASON_LABELS[code];
  if (known) return known;
  const words = code.replace(/_/g, ' ').toLowerCase().trim();
  return words.charAt(0).toUpperCase() + words.slice(1);
}

/** Shared access model for the map tab and any other per-track view. */

import type { HoursWeek } from './hoursWeek';

export interface MapTrack {
  id: string;
  slug: string;
  name: string;
  website: string | null;
  instagram: string | null;
  facebook: string | null;
  imageUrl: string | null;
  description: string | null;
  city: string | null;
  region: string | null;
  lat: number | null;
  lng: number | null;
  /** What the venue is doing right now: OPEN | WEATHER_HOLD | CLOSED. */
  status: string;
  statusNote: string | null;
  /** The operator's own message to riders, when they left one — null otherwise. */
  riderMessage?: string | null;
  /** Tomorrow's posted gate read, when the operator has scheduled one. */
  tomorrowStatus?: { day: string; status: string; statusNote: string | null } | null;
  hours: string | null;
  /** The venue's week behind that line — null when none is on file. */
  hoursWeek?: HoursWeek | null;
  nextEvent: string | null;
  /** The venue's next race on file — the inspector calls it out. */
  nextRace?: {
    title: string;
    /** The race's own day, `YYYY-MM-DD`. */
    day: string;
    startMinutes: number | null;
    endMinutes: number | null;
  } | null;
  /** True when the pass's own terms are withheld from this viewer (free tier). */
  gated: boolean;
  /** Only present on the directory; the rider map uses entitlements instead. */
  following?: boolean;
  /** Null for a free-tier viewer — the contract terms are withheld server-side. */
  includedDays: number | null;
  discountDayEnabled: boolean;
  discountDayNumber: number | null;
  discountRate: number | null;
  extraDayPriceCents: number | null;
  reservationRequired: boolean;
}

/** Display labels for the live venue status. */
export const TRACK_STATUS_LABEL: Record<string, string> = {
  OPEN: 'Open',
  WEATHER_HOLD: 'Caution',
  CLOSED: 'Closed',
};

/** Pill class per status — only Open reads as rideable. */
export const TRACK_STATUS_CLASS: Record<string, string> = {
  OPEN: 'status-open',
  WEATHER_HOLD: 'status-hold',
  CLOSED: 'status-closed',
};

export function statusLabel(status: string): string {
  return TRACK_STATUS_LABEL[status] ?? status;
}

export interface Entitlement {
  trackId: string;
  includedDays: number;
  freeDaysUsed: number;
  freeDaysRemaining: number;
  discountDayEnabled: boolean;
  discountDayNumber: number;
  discountRate: number;
  discountPriceCents: number;
  discountDaysAllowed: number;
  discountDaysUsed: number;
  reservationRequired: boolean;
}

export type Access = 'days' | 'discountOnly' | 'exhausted' | 'notCovered';

/**
 * The map's pin fill. The network is motocross only, so every pin is the
 * accent; whether the pass covers the venue rides on the outline instead
 * (dashed), and the days left per track stay in the rail, where they are
 * spelled out.
 */
export const VENUE_PIN: Record<string, { bg: string }> = {
  MX: { bg: 'var(--accent)' },
};

/** The pin fill for a venue — every venue is an MX track. */
export function venuePin() {
  return VENUE_PIN.MX;
}

export const ACCESS_LABEL: Record<Access, string> = {
  days: 'Days left',
  discountOnly: 'Discounted day only',
  exhausted: 'No days left',
  notCovered: 'Not covered by your pass',
};

/**
 * Whether the pass carries the venue at all — the rail's filter, and the map's,
 * which ride the same toggle, drop these and nothing else. Coverage lives in the
 * allotment ledger, so an entitlement row *is* the coverage: its absence is
 * exactly what the scan refuses and what `notCovered` reads as. A venue with no
 * days left is still covered; only a venue the tier never carried is not.
 */
export function isCovered(ent: Entitlement | undefined): ent is Entitlement {
  return Boolean(ent);
}

export function accessFor(_track: MapTrack, ent: Entitlement | undefined): Access {
  if (!isCovered(ent)) return 'notCovered';
  if (ent.freeDaysRemaining > 0) return 'days';
  const discountLeft = ent.discountDayEnabled ? ent.discountDaysAllowed - ent.discountDaysUsed : 0;
  return discountLeft > 0 ? 'discountOnly' : 'exhausted';
}

/** Total rideable days left (included free days + any discounted days). */
export function daysLeft(ent: Entitlement | undefined): number {
  if (!ent) return 0;
  const discountLeft = ent.discountDayEnabled
    ? Math.max(ent.discountDaysAllowed - ent.discountDaysUsed, 0)
    : 0;
  return Math.max(ent.freeDaysRemaining, 0) + discountLeft;
}

import { money } from './api';
import type { Entitlement } from '../components/DaysByTrack';

/** A perk pinned to one track (network-wide perks stay in PerksSection). */
export interface TrackPerk {
  id: string;
  title: string;
  trackId: string | null;
  redeemed: boolean;
}

/** One offer at one track, with the state it is in right now. */
export interface Offer {
  key: string;
  text: string;
  on: boolean;
  /** Set on the offers that are gone, so the bullet reads as invalidated. */
  tag?: string;
}

/**
 * Every offer the pass carries at one track — the discounted day, the member
 * rate on extra days, and any perk pinned to that track — each flagged with
 * whether it is still live. Shared by the day row and the track panel, so the
 * two can never disagree about what is spent.
 */
export function offersFor(e: Entitlement, perks: TrackPerk[], active: boolean): Offer[] {
  const discountLeft = e.discountDayEnabled
    ? Math.max(e.discountDaysAllowed - e.discountDaysUsed, 0)
    : 0;
  const offers: Offer[] = [];

  if (e.discountDayEnabled) {
    const pct = Math.round(e.discountRate * 100);
    const left = active && discountLeft > 0;
    offers.push({
      key: 'discount',
      text: `Day ${e.discountDayNumber} · ${pct}% off · ${money(e.discountPriceCents)}`,
      on: left,
      tag: left ? undefined : active ? 'used' : 'expired',
    });
  }
  offers.push({
    key: 'extra',
    text: `Extra days · ${money(e.extraDayPriceCents)} member rate`,
    on: active,
    tag: active ? undefined : 'expired',
  });
  for (const p of perks) {
    const available = active && !p.redeemed;
    offers.push({
      key: p.id,
      text: p.title,
      on: available,
      tag: available ? undefined : p.redeemed ? 'redeemed' : 'expired',
    });
  }
  return offers;
}

import * as L from 'leaflet';

/**
 * The one place the app's maps are pinned to the United States. Every partner
 * track is a US venue, so both the public tracks map and the rider's My Pass
 * map refuse to pan or zoom away from the country: `maxBounds` clamps the view
 * centre and `US_MIN_ZOOM` stops the user zooming out to a world view.
 */
export const US_BOUNDS = L.latLngBounds([24.396308, -125.0], [49.384358, -66.93457]);

/** Country-scale floor — the network spans the States, so zooming out stops
 *  just past a full continental-US view rather than at a world view. */
export const US_MIN_ZOOM = 4;

/** Roughly the centre of the continental US — the network's own centre of mass. */
export const US_CENTER: L.LatLngExpression = [39.5, -98.35];

/** Options shared by every Leaflet map in the app. */
export function usMapOptions(): L.MapOptions {
  return {
    center: US_CENTER,
    zoom: 4,
    minZoom: US_MIN_ZOOM,
    maxBounds: US_BOUNDS,
    maxBoundsViscosity: 1.0,
    scrollWheelZoom: true,
    attributionControl: true,
    zoomControl: true,
  };
}

