import { useEffect, useState } from 'react';
import { api } from '../../lib/api';
import { SortTh, useSorted } from '../../components/sortable';

interface Manifest {
  generatedAt: string;
  exports: { kind: string; label: string; rowCount: number; columns: string[] }[];
}

export default function AdminQuickBooks() {
  const [manifest, setManifest] = useState<Manifest | null>(null);
  const [preview, setPreview] = useState<{ kind: string; rows: Record<string, string>[] } | null>(null);
  const [loading, setLoading] = useState(true);

  const load = () =>
    api.get<Manifest>('/admin/quickbooks/manifest').then((r) => {
      setManifest(r.data ?? null);
      setLoading(false);
    });

  useEffect(() => {
    load();
  }, []);

  const previewKind = async (kind: string) => {
    const res = await api.get<{ rows: Record<string, string>[] }>(
      `/admin/quickbooks/export?type=${kind}&format=json`
    );
    setPreview({ kind, rows: res.data?.rows ?? [] });
  };

  const previewRows = preview?.rows ?? [];
  const { sorted, sort, toggle } = useSorted(
    previewRows,
    Object.fromEntries(
      Object.keys(previewRows[0] ?? {}).map((c) => [c, (row: Record<string, string>) => row[c]])
    )
  );
  const { sorted: exports, sort: sortExports, toggle: toggleExports } = useSorted(
    manifest?.exports ?? [],
    {
      export: (e) => e.label,
      rows: (e) => e.rowCount,
      columns: (e) => e.columns.length,
    }
  );

  if (loading) return <div className="muted">Loading exports…</div>;

  return (
    <div className="stack">
      <div>
        <h1>QuickBooks export</h1>
        <div className="small muted">
          Importable CSV for Customers, Subscriptions (Invoices) and Payments (Sales Receipts). Each
          row carries an external key so a live API sync can be layered on later without re-keying.
          Generated {manifest ? new Date(manifest.generatedAt).toLocaleString() : '—'}.
        </div>
      </div>

      <div className="card" style={{ padding: 0 }}>
        <table>
          <thead>
            <tr>
              <SortTh sortKey="export" sort={sortExports} onSort={toggleExports}>Export</SortTh>
              <SortTh sortKey="rows" sort={sortExports} onSort={toggleExports} className="right">Rows</SortTh>
              <SortTh sortKey="columns" sort={sortExports} onSort={toggleExports}>Columns</SortTh>
              <th className="right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {exports.map((e) => (
              <tr key={e.kind}>
                <td>{e.label}</td>
                <td className="right">{e.rowCount}</td>
                <td className="tiny muted mono">
                  {e.columns.slice(0, 6).join(' · ')}
                  {e.columns.length > 6 ? ' …' : ''}
                </td>
                <td className="right">
                  <span className="row" style={{ justifyContent: 'flex-end' }}>
                    <a href={`/api/admin/quickbooks/export?type=${e.kind}&format=csv`}>
                      <button className="ghost small">CSV</button>
                    </a>
                    <button className="ghost small" onClick={() => previewKind(e.kind)}>
                      Preview
                    </button>
                  </span>
                </td>
              </tr>
            ))}
            {!manifest?.exports.length && (
              <tr>
                <td colSpan={4} className="muted small">
                  No exports configured.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {preview && (
        <div className="table-block">
          <div className="table-head">
            <h3 style={{ margin: 0 }}>Preview: {preview.kind}</h3>
            <button className="ghost small" onClick={() => setPreview(null)}>
              Close
            </button>
          </div>
          <div className="card" style={{ padding: 0 }}>
          <div style={{ overflowX: 'auto' }}>
            <table>
              <thead>
                <tr>
                  {Object.keys(preview.rows[0] ?? {}).map((c) => (
                    <SortTh key={c} sortKey={c} sort={sort} onSort={toggle}>{c}</SortTh>
                  ))}
                </tr>
              </thead>
              <tbody>
                {sorted.slice(0, 25).map((row, i) => (
                  <tr key={i}>
                    {Object.values(row).map((v, j) => (
                      <td key={j} className="small">
                        {v}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          </div>
        </div>
      )}
    </div>
  );
}

