          <span className="fig-label">day redemptions</span>
        </div>
        <div>
          <span className="fig-value">{data?.totals.activePasses ?? 0}</span>
          <span className="fig-label">active passes</span>
        </div>
        <div>
          <span className="fig-value">{money(data?.totals.revenueCents)}</span>
          <span className="fig-label">pass revenue</span>
        </div>
        <div>
          <span className="fig-value">
            {money(data?.perTrack.reduce((s, t) => s + t.trackRevenueCents, 0) ?? 0)}
