  priceCents: number;
  earlyBirdPriceCents: number | null;
  twoYearPriceCents: number | null;
  extraDaysPerTrack: number;
  /** The monthly alternative to the annual price — display only. */
  monthlyPriceCents: number | null;
  isActive: boolean;
  sortOrder: number;
}

