  );
}

import { useEffect, useState } from 'react';
import Banner from '../../components/Banner';
import { api, money } from '../../lib/api';
import { SortTh, useSorted } from '../../components/sortable';
import TrackName from '../../components/TrackName';

interface Contract {
  id: string;
  seasonId: string;
  includedDays: number;
  discountDayEnabled: boolean;
  discountDayNumber: number;
  discountRate: number;
  discountDaysAllowed: number;
  extraDayPriceCents: number;
  reservationRequired: boolean;
  dayConsumePolicy: string;
  isActive: boolean;
  notes: string | null;
  season: { id: string; year: number };
}

interface TrackRow {
  id: string;
  name: string;
  slug: string;
  website: string | null;
  /** The venue's type — 'MX' (the network is motocross only). */
  category: string;
  isActive: boolean;
  contracts: Contract[];
  _count: { reservations: number; redemptions: number };
}

interface Season {
  id: string;
  year: number;
  isActive: boolean;
}

const blankContract = (seasonId: string): Contract => ({
  id: '',
  seasonId,
  includedDays: 2,
  discountDayEnabled: true,
  discountDayNumber: 3,
  discountRate: 0.5,
  discountDaysAllowed: 1,
  extraDayPriceCents: 4500,
  reservationRequired: false,
  dayConsumePolicy: 'ON_CHECKIN',
  isActive: true,
  notes: '',
  season: { id: seasonId, year: new Date().getUTCFullYear() },
});

export default function AdminTracks() {
  const [tracks, setTracks] = useState<TrackRow[]>([]);
  const [seasons, setSeasons] = useState<Season[]>([]);
  const [seasonId, setSeasonId] = useState('');
  const [editing, setEditing] = useState<{ track: TrackRow; contract: Contract } | null>(null);
  const [msg, setMsg] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  const load = async () => {
    const [t, s] = await Promise.all([
      api.get<{ tracks: TrackRow[] }>('/admin/tracks'),
      api.get<{ seasons: Season[] }>('/admin/seasons'),
    ]);
    setTracks(t.data?.tracks ?? []);
    const list = s.data?.seasons ?? [];
    setSeasons(list);
    setSeasonId((prev) => prev || list.find((x) => x.isActive)?.id || list[0]?.id || '');
    setLoading(false);
  };

  useEffect(() => {
    load();
  }, []);

  const openEditor = (track: TrackRow) => {
    const existing = track.contracts.find((c) => c.seasonId === seasonId);
    setEditing({ track, contract: existing ? { ...existing } : blankContract(seasonId) });
    setMsg(null);
  };

  const save = async () => {
    if (!editing) return;
    const c = editing.contract;
    const res = await api.put(`/admin/tracks/${editing.track.id}/contract`, {
      seasonId,
      includedDays: Number(c.includedDays),
      discountDayEnabled: c.discountDayEnabled,
      discountDayNumber: Number(c.discountDayNumber),
      discountRate: Number(c.discountRate),
      discountDaysAllowed: Number(c.discountDaysAllowed),
      extraDayPriceCents: Number(c.extraDayPriceCents),
      reservationRequired: c.reservationRequired,
      dayConsumePolicy: c.dayConsumePolicy,
      isActive: c.isActive,
      notes: c.notes ?? undefined,
    });
    setMsg(res.message);
    if (res.success) {
      setEditing(null);
      load();
    }
  };

  const syncAllotments = async () => {
    const res = await api.post<{ updated: number }>(`/admin/seasons/${seasonId}/sync-allotments`);
    setMsg(res.success ? `Re-snapshotted ${res.data?.updated ?? 0} allotments.` : res.message);
  };

  const seasonYear = seasons.find((s) => s.id === seasonId)?.year ?? new Date().getUTCFullYear();

  const contractOf = (t: TrackRow) => t.contracts.find((x) => x.seasonId === seasonId);
  const { sorted, sort, toggle } = useSorted(tracks, {
    track: (t) => t.name,
    days: (t) => contractOf(t)?.includedDays ?? null,
    discount: (t) => (contractOf(t)?.discountDayEnabled ? contractOf(t)!.discountDayNumber : null),
    reservation: (t) => (contractOf(t)?.reservationRequired ? 1 : 0),
    spent: (t) => contractOf(t)?.dayConsumePolicy ?? null,
    counts: (t) => t._count.reservations,
  });

  if (loading) return <div className="muted">Loading tracks…</div>;

  return (
    <div className="stack">
      <div className="row spread wrap">
        <div>
          <h1>Tracks &amp; contracts</h1>
          <div className="small muted">
            Allotment, discount rate and reservation rule are set per track, per season.
          </div>
        </div>
        <div className="row wrap">
          <select value={seasonId} onChange={(e) => setSeasonId(e.target.value)} style={{ width: 130 }}>
            {seasons.map((s) => (
              <option key={s.id} value={s.id}>
                {s.year} season
              </option>
            ))}
          </select>
          <button className="ghost small" onClick={syncAllotments}>
            Re-snapshot allotments
          </button>
        </div>
      </div>

      {msg && <Banner tone="ok" close>{msg}</Banner>}

      <div className="card" style={{ padding: 0 }}>
        <table>
          <thead>
            <tr>
              <SortTh sortKey="track" sort={sort} onSort={toggle}>Track</SortTh>
              <SortTh sortKey="days" sort={sort} onSort={toggle} className="right">Included days</SortTh>
              <SortTh sortKey="discount" sort={sort} onSort={toggle}>Discounted day</SortTh>
              <SortTh sortKey="reservation" sort={sort} onSort={toggle}>Reservation</SortTh>
              <SortTh sortKey="spent" sort={sort} onSort={toggle}>Day spent</SortTh>
              <SortTh sortKey="counts" sort={sort} onSort={toggle} className="right">Res / Redemptions</SortTh>
              <th className="right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {sorted.map((t) => {
              const c = t.contracts.find((x) => x.seasonId === seasonId);
              return (
                <tr key={t.id}>
                  <td>
                    <div className="track-cell">
                      <TrackName name={t.name} website={t.website} />{' '}
                      {!t.isActive && <span className="pill bad">inactive</span>}
                    </div>
                    <div className="tiny muted">{t.slug}</div>
                  </td>
                  <td className="right">{c?.includedDays ?? <span className="muted">—</span>}</td>
                  <td className="small muted">
                    {c?.discountDayEnabled ? (
                      <>
                        day {c.discountDayNumber} · {Math.round(c.discountRate * 100)}% off ·{' '}
                        {money(Math.round(c.extraDayPriceCents * (1 - c.discountRate)))} (
                        {c.discountDaysAllowed} allowed)
                      </>
                    ) : (
                      'none'
                    )}
                  </td>
                  <td>
                    {c?.reservationRequired ? <span className="pill warn">Required</span> : ''}
                  </td>
                  <td className="small muted">{c?.dayConsumePolicy.replace('_', ' ').toLowerCase() ?? '—'}</td>
                  <td className="right muted small">
                    {t._count.reservations} / {t._count.redemptions}
                  </td>
                  <td className="right">
                    <button className="ghost small" onClick={() => openEditor(t)}>
                      {c ? 'Edit contract' : 'Set contract'}
                    </button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {editing && (
        <div className="card stack">
          <div className="row spread">
            <h3 style={{ margin: 0 }}>
              {editing.track.name} · {seasonYear} contract
            </h3>
            <button className="ghost small" onClick={() => setEditing(null)}>
              Close
            </button>
          </div>

          <div className="grid cols-4">
            <div>
              <label>Included days per pass</label>
              <input
                type="number"
                min={0}
                value={editing.contract.includedDays}
                onChange={(e) =>
                  setEditing({
                    ...editing,
                    contract: { ...editing.contract, includedDays: Number(e.target.value) },
                  })
                }
              />
            </div>
            <div>
              <label>Discounted day number</label>
              <input
                type="number"
                min={1}
                value={editing.contract.discountDayNumber}
                onChange={(e) =>
                  setEditing({
                    ...editing,
                    contract: { ...editing.contract, discountDayNumber: Number(e.target.value) },
                  })
                }
              />
            </div>
            <div>
              <label>Discount rate (0–1, e.g. 0.5 = 50% off)</label>
              <input
                type="number"
                step="0.05"
                min={0}
                max={1}
                value={editing.contract.discountRate}
                onChange={(e) =>
                  setEditing({
                    ...editing,
                    contract: { ...editing.contract, discountRate: Number(e.target.value) },
                  })
                }
              />
            </div>
            <div>
              <label>Discounted days allowed</label>
              <input
                type="number"
                min={0}
                value={editing.contract.discountDaysAllowed}
                onChange={(e) =>
                  setEditing({
                    ...editing,
                    contract: { ...editing.contract, discountDaysAllowed: Number(e.target.value) },
                  })
                }
              />
            </div>
            <div>
              <label>Sticker price, extra day (cents)</label>
              <input
                type="number"
                min={0}
                value={editing.contract.extraDayPriceCents}
                onChange={(e) =>
                  setEditing({
                    ...editing,
                    contract: { ...editing.contract, extraDayPriceCents: Number(e.target.value) },
                  })
                }
              />
            </div>
            <div>
              <label>Discounted day price</label>
              <input
                readOnly
                value={money(
                  Math.round(editing.contract.extraDayPriceCents * (1 - editing.contract.discountRate))
                )}
              />
            </div>
            <div>
              <label>Reservation required</label>
              <select
                value={editing.contract.reservationRequired ? 'yes' : 'no'}
                onChange={(e) =>
                  setEditing({
                    ...editing,
                    contract: { ...editing.contract, reservationRequired: e.target.value === 'yes' },
                  })
                }
              >
                <option value="no">No, walk-up</option>
                <option value="yes">Yes, book ahead</option>
              </select>
            </div>
            <div>
              <label>Day spent</label>
              <select
                value={editing.contract.dayConsumePolicy}
                onChange={(e) =>
                  setEditing({
                    ...editing,
                    contract: { ...editing.contract, dayConsumePolicy: e.target.value },
                  })
                }
              >
                <option value="ON_CHECKIN">At check-in</option>
                <option value="ON_CONFIRM">When reservation is confirmed</option>
                <option value="NEVER">Never (informational)</option>
              </select>
            </div>
            <div>
              <label>Discount day enabled</label>
              <select
                value={editing.contract.discountDayEnabled ? 'yes' : 'no'}
                onChange={(e) =>
                  setEditing({
                    ...editing,
                    contract: { ...editing.contract, discountDayEnabled: e.target.value === 'yes' },
                  })
                }
              >
                <option value="yes">Enabled</option>
                <option value="no">Disabled</option>
              </select>
            </div>
            <div>
              <label>Contract active</label>
              <select
                value={editing.contract.isActive ? 'yes' : 'no'}
                onChange={(e) =>
                  setEditing({
                    ...editing,
                    contract: { ...editing.contract, isActive: e.target.value === 'yes' },
                  })
                }
              >
                <option value="yes">Active</option>
                <option value="no">Inactive</option>
              </select>
            </div>
            <div style={{ gridColumn: 'span 2' }}>
              <label>Notes</label>
              <input
                value={editing.contract.notes ?? ''}
                onChange={(e) =>
                  setEditing({
                    ...editing,
                    contract: { ...editing.contract, notes: e.target.value },
                  })
                }
              />
            </div>
          </div>

          <div className="row wrap">
            <button className="primary" onClick={save}>
              Save contract
            </button>
            <span className="tiny muted">
              Existing allotments keep their snapshot. Use “Re-snapshot allotments” to push changes
              to riders already holding a pass.
            </span>
          </div>
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import Banner from '../../components/Banner';
import { api, dayStr } from '../../lib/api';
import { SortTh, useSorted } from '../../components/sortable';

interface UserRow {
  id: string;
  name: string;
  email: string;
  role: string;
  isActive: boolean;
  operatorTrack: { id: string; name: string } | null;
  latestPass: {
    id: string;
    status: string;
    seasonYear: number;
    tierName: string;
    expiresAt: string;
  } | null;
}

export default function AdminUsers() {
  const [users, setUsers] = useState<UserRow[]>([]);
  const [search, setSearch] = useState('');
  const [role, setRole] = useState('');
  const [total, setTotal] = useState(0);
  const [msg, setMsg] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const { sorted, sort, toggle } = useSorted(users, {
    name: (u) => u.name,
    email: (u) => u.email,
    role: (u) => u.role,
    pass: (u) => u.latestPass?.tierName ?? null,
    expires: (u) => u.latestPass?.expiresAt ?? null,
    status: (u) => (u.isActive ? 1 : 0),
  });

  const load = async () => {
    setLoading(true);
    const q = new URLSearchParams();
    if (search) q.set('search', search);
    if (role) q.set('role', role);
    const res = await api.get<UserRow[]>(`/admin/users?${q.toString()}`);
    setUsers(res.data ?? []);
    setTotal(res.pagination?.total ?? (res.data?.length ?? 0));
    setLoading(false);
  };

  useEffect(() => {
    const id = setTimeout(load, 250);
    return () => clearTimeout(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [search, role]);

  const setUserRole = async (u: UserRow, nextRole: string) => {
    const res = await api.patch(`/admin/users/${u.id}`, { role: nextRole });
    setMsg(res.message);
    load();
  };

  const toggleActive = async (u: UserRow) => {
    const res = await api.patch(`/admin/users/${u.id}`, { isActive: !u.isActive });
    setMsg(res.message);
    load();
  };

  return (
    <div className="stack">
      <div className="row spread wrap">
        <div>
          <h1>Users</h1>
          <div className="small muted">{total} accounts</div>
        </div>
        <div className="row wrap">
          <input
            placeholder="Search name or email"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            style={{ width: 220 }}
          />
          <select value={role} onChange={(e) => setRole(e.target.value)} style={{ width: 150 }}>
            <option value="">All roles</option>
            <option value="RIDER">Riders</option>
            <option value="OPERATOR">Operators</option>
            <option value="ADMIN">Admins</option>
          </select>
        </div>
      </div>

      {msg && <Banner tone="ok" close>{msg}</Banner>}

      <div className="card" style={{ padding: 0 }}>
        <table>
          <thead>
            <tr>
              <SortTh sortKey="name" sort={sort} onSort={toggle}>Name</SortTh>
              <SortTh sortKey="email" sort={sort} onSort={toggle}>Email</SortTh>
              <SortTh sortKey="role" sort={sort} onSort={toggle}>Role</SortTh>
              <SortTh sortKey="pass" sort={sort} onSort={toggle}>Pass</SortTh>
              <SortTh sortKey="expires" sort={sort} onSort={toggle}>Expires</SortTh>
              <SortTh sortKey="status" sort={sort} onSort={toggle}>Status</SortTh>
              <th className="right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {sorted.map((u) => (
              <tr key={u.id}>
                <td>
                  {u.name}
                  {u.operatorTrack && <div className="tiny muted">at {u.operatorTrack.name}</div>}
                </td>
                <td className="small muted">{u.email}</td>
                <td>
                  <select
                    value={u.role}
                    onChange={(e) => setUserRole(u, e.target.value)}
                    style={{ width: 120, padding: '4px 6px' }}
                  >
                    <option value="RIDER">RIDER</option>
                    <option value="OPERATOR">OPERATOR</option>
                    <option value="ADMIN">ADMIN</option>
                  </select>
                </td>
                <td className="small">
                  {u.latestPass ? (
                    <>
                      <div>{u.latestPass.tierName}</div>
                      <div className="tiny muted">
                        {u.latestPass.seasonYear} · {u.latestPass.status}
                      </div>
                    </>
                  ) : (
                    <span className="muted">—</span>
                  )}
                </td>
                <td className="small muted">{u.latestPass ? dayStr(u.latestPass.expiresAt) : '—'}</td>
                <td>
                  {!u.isActive && <span className="pill bad">disabled</span>}
                </td>
                <td className="right">
                  <span className="row" style={{ justifyContent: 'flex-end' }}>
                    <button className="ghost small" onClick={() => toggleActive(u)}>
                      {u.isActive ? 'Disable' : 'Enable'}
                    </button>
                  </span>
                </td>
              </tr>
            ))}
            {!users.length && !loading && (
              <tr>
                <td colSpan={7} className="muted small">
                  No users match.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { type CSSProperties, useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import { api } from '../lib/api';
import { PARTNER_AUDIENCE_ENABLED } from '../lib/featureFlags';

interface TrackLite {
  slug: string;
  name: string;
  city: string;
  region: string;
  imageUrl: string | null;
  status: string;
  statusNote: string | null;
  /** What is on next at the venue — the offer band's calendar reads this. */
  nextEvent: string | null;
  includedDays: number | null;
  reservationRequired: boolean;
}

/** The landing opener. Served at native size from `web/public/hero/`. */
const HERO_IMAGE = '/hero/moto-pass-hero.png';

/**
 * Short display name for a venue on the network wall, so long facility
 * suffixes don't force ellipses on the narrow tiles.
 */
function shortTrackName(name: string): string {
  return name
    .replace(' Motocross Park', '')
    .replace(' Motor Sports Park', '')
    .replace(' Raceway', '')
    .replace(' MX Park', '')
    .replace(' SVRA', '')
    .replace(/^The /, '');
}

/**
 * How many frames sit across the wall at a given viewport width. The window on
 * the network is always exactly two rows deep, so this is what decides how many
 * venues it shows and how many are counted into the last, faded tile.
 */
function wallColumnsFor(width: number): number {
  if (width >= 1100) return 8;
  if (width >= 860) return 6;
  if (width >= 560) return 4;
  return 3;
}

function viewportWidth(): number {
  return typeof window === 'undefined' ? 1280 : window.innerWidth;
}

/**
 * How many rows the offer band's calendar lists. Deliberately short: it is a
 * window on what is coming up, the way the wall below is a window on the
 * network, and it has to stay level with the offer beside it.
 */
const CAL_ROWS = 5;

export default function Landing() {
  const [tracks, setTracks] = useState<TrackLite[]>([]);
  // Which FAQ row is open. One at a time; the first answer is open on arrival
  // so the band never reads as a wall of closed questions. Clicking the head of
  // an already-open row closes it (null = every row closed).
  const [openFaq, setOpenFaq] = useState<number | null>(0);

  useEffect(() => {
    // `terms=public`: the front door reads the anonymous marketing copy, so a
    // signed-out visitor sees the included days each venue actually carries.
    // The payload also carries `seasonYear`; nothing on the page prints the
    // year any more, so it is not held in state.
    api.get<{ seasonYear: number; tracks: TrackLite[] }>('/tracks?terms=public').then((r) => {
      setTracks(r.data?.tracks ?? []);
    });
  }, []);

  /** The live read of the network. Everything here is counted, never typed. */
  const net = useMemo(() => {
    const count = tracks.length;
    const open = tracks.filter((t) => t.status === 'OPEN').length;
    const states = new Set(tracks.map((t) => t.region)).size;
    const reserving = tracks.filter((t) => t.reservationRequired).length;
    const days = tracks.map((t) => t.includedDays ?? 0).filter((n) => n > 0);
    const scheduled = tracks.filter((t) => t.nextEvent).length;
    return {
      count,
      open,
      states,
      reserving,
      scheduled,
      dayMin: days.length ? Math.min(...days) : null,
      dayMax: days.length ? Math.max(...days) : null,
    };
  }, [tracks]);

  /**
   * The questions a pass buyer actually asks, answered with the live network
   * rather than a policy page — every figure here is counted from the API.
   * Each row is a real question in the buyer's own words, not a section label.
   */
  const faqs = useMemo(() => {
    const span =
      net.dayMin == null
        ? ''
        : net.dayMin === net.dayMax
          ? `, ${net.dayMin} across the network.`
          : `, ${net.dayMin} to ${net.dayMax} across the network.`;
    return [
      { q: 'How many ride days do I get?', a: `Included days at every partner track${span}` },
      {
        q: 'Where can I ride with it?',
        a: `${net.count} partner tracks across ${net.states} states, all on one pass.`,
      },
      {
        q: 'Do I have to reserve a day?',
        a: `${net.reserving} of ${net.count} tracks require a reservation. The rest are walk-up.`,
      },
      {
        q: 'What happens when I run out of days?',
        a: 'Extra days are sold at the track at the member rate, discounted from its sticker price.',
      },
      {
        q: 'Can I share my pass?',
        a: 'No. One rider only, non-transferable, and valid for the calendar year.',
      },
      { q: 'How long is the pass good for?', a: 'January 1 through December 31.' },
      {
        q: 'How do I use it at the gate?',
        a: "The ticket window scans your pass, the app validates it, and the day comes off that track's remaining days. One redemption per track per day.",
      },
      {
        q: 'What do I get without paying?',
        a: 'The network: every partner track, its live status and hours, and the venues you follow. Included days come with the pass.',
      },
      {
        q: 'Do unused days carry over?',
        a: 'No. Days are counted per track, and the pass expires on December 31.',
      },
      {
        q: 'Can I cancel or get a refund?',
        a: "Cancellation and refunds follow the pass agreement. Contact us from the footer and we'll confirm what applies to your purchase.",
      },
    ];
  }, [net]);

  /**
   * The wall's running order: the tracks carrying the most included days first,
   * open venues ahead of the rest, then by name. Nothing here rotates and
   * nothing here is sampled — every partner track is on the wall at once.
   */
  const wallTracks = useMemo(() => {
    const open = (t: TrackLite) => (t.status === 'OPEN' ? 0 : 1);
    return [...tracks].sort(
      (a, b) =>
        (b.includedDays ?? 0) - (a.includedDays ?? 0) ||
        open(a) - open(b) ||
        a.name.localeCompare(b.name),
    );
  }, [tracks]);

  /**
   * The offer band's calendar: the next thing on at the venues, in the
   * network's own running order. A venue with nothing booked is counted in the
   * note under the list rather than listed as a blank row, so the column never
   * reads longer than the offer beside it.
   */
  const upcoming = useMemo(
    () => tracks.filter((t) => t.nextEvent).slice(0, CAL_ROWS),
    [tracks],
  );

  /**
   * The wall inside the offer band is a window on the network, not the whole of
   * it: two rows of frames, the last of which stands in for the rest and counts
   * them. The frames across a row follow the viewport, so the window is always
   * exactly two rows deep.
   */
  const [wallCols, setWallCols] = useState(() => wallColumnsFor(viewportWidth()));
  useEffect(() => {
    const onResize = () => setWallCols(wallColumnsFor(viewportWidth()));
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, []);
  const wallWindow = wallCols * 2;
  const wallShown = wallTracks.slice(0, Math.max(0, wallWindow - 1));
