export default function Login() {
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [err, setErr] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [infoFor, setInfoFor] = useState<string | null>(null);
  const { login, register, user } = useAuth();
  const navigate = useNavigate();
  const location = useLocation() as { state?: { from?: string } };

  const [redirect, setRedirect] = useState<string | null>(null);

  useEffect(() => {
    if (user) setRedirect(homePathFor(user.role));
  }, [user]);

  if (redirect) return <Navigate to={redirect} replace />;

  const submit = async (e: FormEvent) => {
    e.preventDefault();
    setBusy(true);
    setErr(null);
    const error =
      mode === 'login' ? await login(email, password) : await register(name, email, password);
    setBusy(false);
    if (error) return setErr(error);
    // A deep link wins; otherwise the role's own home takes over below
    // (an operator's is /scan, a rider's /tracks) — never a hardcoded path.
    const from = location.state?.from;
    if (from) navigate(from, { replace: true });
  };

  const quick = (e: string) => {
    setMode('login');
    setEmail(e);
    setPassword('dialed123');
  };

  return (
    <div style={{ maxWidth: 520, margin: '0 auto' }} className="stack">
      <div className="card stack">
        <div>
          <h1 style={{ fontSize: 22 }}>{mode === 'login' ? 'Sign in' : 'Create account'}</h1>
        </div>

        {err && <Banner tone="bad" close>{err}</Banner>}

        <form onSubmit={submit} className="stack">
          {mode === 'register' && (
            <div>
              <label htmlFor="name">Name</label>
              <input id="name" value={name} onChange={(e) => setName(e.target.value)} required />
            </div>
          )}
          <div>
            <label htmlFor="email">Email</label>
            <input
              id="email"
              type="email"
              autoComplete="username"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>
          <div>
            <label htmlFor="password">Password</label>
            <input
              id="password"
              type="password"
              autoComplete={mode === 'login' ? 'current-password' : 'new-password'}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>
          <button className="primary" disabled={busy}>
            {busy ? 'Working…' : mode === 'login' ? 'Sign in' : 'Create account'}
          </button>
        </form>

        <button
          className="ghost small"
          onClick={() => {
            setMode(mode === 'login' ? 'register' : 'login');
            setErr(null);
          }}
        >
          {mode === 'login' ? 'Need an account? Register' : 'Already have an account? Sign in'}
        </button>
      </div>

      <div className="card">
        <div className="row spread" style={{ marginBottom: 10 }}>
          <h3 style={{ margin: 0 }}>Demo accounts</h3>
          <span className="tiny muted">
            password <span className="mono">dialed123</span>
          </span>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
          {signupDemoAccounts.map((acct) => {
            const open = infoFor === acct.email;
            return (
              <div
                key={acct.email}
                style={{
                  border: `1px solid ${open ? 'var(--accent-2)' : 'var(--line)'}`,
                  borderRadius: 'var(--radius)',
                  background: 'var(--bg-3)',
                }}
              >
                <div className="row" style={{ gap: 4, alignItems: 'stretch' }}>
                  <button
                    className="ghost small"
                    style={{ flex: 1, textAlign: 'left', border: 0, padding: '8px 10px' }}
                    onClick={() => quick(acct.email)}
                    title={`Fill the form with ${acct.email}`}
                  >
                    <div>{acct.label}</div>
                    <div className="tiny muted mono">{acct.email}</div>
                  </button>
                  <button
                    className="ghost"
                    style={{ border: 0, padding: '8px 10px', color: open ? 'var(--accent-2)' : 'var(--muted)' }}
                    aria-label={`What differs about the ${acct.label} demo account`}
                    aria-expanded={open}
                    title="What differs about this account"
                    onClick={() => setInfoFor(open ? null : acct.email)}
                  >
                    <InfoIcon />
                  </button>
                </div>
                {open && (
                  <div
                    style={{
                      padding: '8px 10px 10px',
                      borderTop: '1px solid var(--line)',
                    }}
                  >
                    <div className="tiny" style={{ color: 'var(--text)' }}>
                      {acct.summary}
                    </div>
                    <ul
                      className="tiny muted"
                      style={{ margin: '6px 0 0', paddingLeft: 15, listStyleType: 'disc' }}
                    >
                      {acct.points.map((p) => (
                        <li key={p} style={{ marginTop: 3 }}>
                          {p}
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

import { ReactNode, MouseEvent as ReactMouseEvent, useEffect, useMemo, useRef, useState } from 'react';
