import WeekGrid, { SlotDraft, SlotEdge } from '../../components/WeekGrid';
import { api } from '../../lib/api';
import { useAuth } from '../../lib/auth';
import {
  EVENT_KINDS,
  EVENT_KIND_OPTION,
  ampmLabel,
  ampmTime,
  clockTime,
  dayKey,
  dayRange,
  daysOf,
  minutesOf,
  stepWeek,
