  weekStart,
} from '../../lib/events';

/**
 * The owner's calendar page — where a venue's season is actually written.
 *
 * The profile page reads the schedule; this page edits it, and it reads as a
 * week: an all-day row over an hour grid, a date drawn where its own hours put
 * it, and that week's dates as cards underneath — each card a line of text that
 * opens the fields in a sheet when it is clicked. The calendar used to be a
 * month grid, so the page kept a month of dates in front of the owner; a week
 * is what an owner actually looks at when a weekend is what they are filling.
 *
 * The owner is the OPERATOR pinned to the venue, so the page reads and writes
 * only that track; an ADMIN has no pinned track, so it gets a venue picker and
 * edits on the venue's behalf through `?trackId=` — the same shape as the
 * profile console.
 */
interface TrackEvent {
  id: string;
  title: string;
  description: string | null;
  kind: string;
  startsAt: string;
  endsAt: string | null;
  startMinutes: number | null;
  endMinutes: number | null;
  isActive: boolean;
}

interface OwnerTrack {
  id: string;
  slug: string;
  name: string;
  events: TrackEvent[];
}

/** A new date opens a week out, and reads as a gate day until it is timed. */
const blankEvent = () => ({
  title: '',
  kind: 'PRACTICE',
  startsAt: new Date(Date.now() + 6048e5).toISOString().slice(0, 10),
  endsAt: '',
  startTime: '09:00',
  endTime: '16:00',
  description: '',
  isActive: true,
});

const dayValue = (iso: string | null) => (iso ? iso.slice(0, 10) : '');

/**
 * The fields Save posts, normalised the way the API reads them. Two events
 * with the same shape send the same request, so comparing the shapes is how
 * the Edit sheet knows the owner has actually changed something.
 */
const eventShape = (e: TrackEvent) =>
  JSON.stringify({
    title: e.title,
    kind: e.kind,
    startsAt: dayValue(e.startsAt),
    endsAt: e.endsAt ? dayValue(e.endsAt) : '',
    startMinutes: e.startMinutes ?? null,
    endMinutes: e.endMinutes ?? null,
    description: e.description ?? '',
    isActive: e.isActive,
  });

/**
 * The Add sheet's fields, normalised the same way, so "the owner typed
 * something" is a comparison against the state the sheet opened on.
 */
const addShape = (e: ReturnType<typeof blankEvent>) =>
  JSON.stringify({
    title: e.title,
    kind: e.kind,
    startsAt: e.startsAt,
    endsAt: e.endsAt,
    startTime: e.startTime,
    endTime: e.endTime,
    description: e.description,
    isActive: e.isActive,
  });

/* ---- The sheet's own furniture ---------------------------------------- */

/** `3h 45m`, `45m`, `2h` — how long a gate runs, the short way. */
function spanLabel(minutes: number) {
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return [h ? `${h}h` : '', m ? `${m}m` : ''].filter(Boolean).join(' ');
}

/** The length a pair of hours adds up to, or `null` when it carries none. */
function eventSpan(from: number | null, to: number | null) {
  return from != null && to != null && to > from ? to - from : null;
}

/**
 * What the description toggle reads — one action, named for the state the field
 * is in: a note that is out is put away, a note that only lives on the date is
 * called up, and an empty one is asked for.
 */
function descToggleLabel(open: boolean, hasText: boolean) {
  if (open) return 'Hide description';
  return hasText ? 'Show description' : 'Add description';
}

/** `May 15, 2023` — a day as the sheet's own sentence names it. */
function longDay(day: string) {
  return new Date(`${day}T12:00:00Z`).toLocaleDateString(undefined, {
    month: 'long',
    day: 'numeric',
    year: 'numeric',
    timeZone: 'UTC',
  });
}

/**
 * The fields read back as one sentence — the owner's own words for what the
 * date, the hour and the length add up to, so a wrong duration is visible
 * before it posts rather than on the calendar afterwards.
 */
function eventSentence(day: string, through: string, from: number | null, to: number | null) {
  if (!day) return 'Pick a date to put this event on the calendar.';
  if (through && through > day) {
    return (
      <>
        This event runs from <b>{longDay(day)}</b> until <b>{longDay(through)}</b>
        {from != null && to != null && to > from ? (
          <>
            , <b>{ampmTime(from)}–{ampmTime(to)}</b>
          </>
        ) : null}
        .
      </>
    );
  }
  if (from == null || to == null) {
    return (
      <>
        This event will take place on <b>{longDay(day)}</b>, all day.
      </>
    );
  }
  return (
    <>
      This event will take place on <b>{longDay(day)}</b> from <b>{ampmTime(from)}</b> until{' '}
      <b>{ampmTime(to)}</b>.
    </>
  );
}

