export default function OperatorCalendar() {
  const { user } = useAuth();
  const isAdmin = user?.role === 'ADMIN';
  const [params] = useSearchParams();
  /** The date the console's Edit button handed over. */
  const focusParam = params.get('event');

  const [trackList, setTrackList] = useState<{ id: string; name: string; slug: string }[]>([]);
  const [trackId, setTrackId] = useState('');
  const [track, setTrack] = useState<OwnerTrack | null>(null);
  const [loading, setLoading] = useState(true);
  // Calendar feedback rides the toast layer, so it carries its own tone and an
  // id: two identical sentences in a row (add, add again) must remount the
  // Banner, which retires on its own timer and would otherwise stay closed.
  const [msg, setMsg] = useState<{ id: number; ok: boolean; text: string } | null>(null);
  const msgSeq = useRef(0);
  const notice = (ok: boolean, text: string) => setMsg({ id: ++msgSeq.current, ok, text });
  const [newEvent, setNewEvent] = useState(blankEvent);

  /**
   * The new date as the Add sheet opened it. A sheet the owner has typed in
   * asks before its fields are thrown away; one they only opened closes
   * without a word.
   */
  const [newPristine, setNewPristine] = useState<ReturnType<typeof blankEvent> | null>(null);

  /** The Add sheet's discard question — up only while there is typing to lose. */
  const [discarding, setDiscarding] = useState(false);

  /** The Add Event sheet — closed until the header button opens it. */
  const [adding, setAdding] = useState(false);

  /**
   * Whether the Add sheet has its description field out. An owner with a note
   * to write asks for it; a bare practice never carries the empty field.
   */
  const [descOpen, setDescOpen] = useState(false);

  /**
   * The same for the Edit sheet: a date's note is called up when the owner
   * wants it, and the field is out only for as long as that sheet is open.
   */
  const [editDescOpen, setEditDescOpen] = useState(false);

  /**
   * The remove confirmation — a second sheet over the edit sheet, since a
   * deleted date is the one thing an edit cannot put back. Cancel, Escape and
   * the backdrop all put it away; only the confirm button goes through.
   */
  const [confirming, setConfirming] = useState(false);

  /**
   * The card whose Edit sheet is open. Held as a working copy, so typing in the
   * sheet leaves the card behind it alone and Cancel drops the lot — only Save
   * posts the change.
   */
  const [draft, setDraft] = useState<TrackEvent | null>(null);

  /**
   * The event as the sheet opened it. Save is held disabled until the working
   * copy differs from this, so a no-op edit cannot post.
   */
  const [pristine, setPristine] = useState<TrackEvent | null>(null);

  /** Any day of the week on screen; the grid draws that day's own week. */
  const [anchor, setAnchor] = useState(() => dayKey(new Date().toISOString()));
  const [picked, setPicked] = useState<string | null>(null);
  const [focusId, setFocusId] = useState<string | null>(null);

  /**
   * The hours marked off on the grid but not posted yet. Marking a slot is how
   * an owner says *when* first — the day and its hours are set on the week
   * itself, by clicking an empty hour and dragging the block's edges — and the
   * Add sheet opens on that slot to take the name.
   */
  const [slot, setSlot] = useState<SlotDraft | null>(null);

  /**
   * A gesture that would throw the marked slot away, held back until the owner
   * answers. Clicking a different hour, stepping the week, Today, Escape and
   * the header's Add Event all land here, so a draft is never dropped without a
   * word; the gesture itself is what is kept, and it runs on confirm.
   *
   * `marks` says the gesture would only put a fresh draft where the click
   * landed. Discarding must leave the week empty — answering the question must
   * not draw a new draft in the same breath, or the discard reads as a mark.
   */
  const [dropping, setDropping] = useState<{ run: () => void; marks?: boolean } | null>(null);

  const rows = useRef<Record<string, HTMLDivElement | null>>({});
  const addPanel = useRef<HTMLDivElement>(null);
  const editPanel = useRef<HTMLDivElement>(null);

  const today = dayKey(new Date().toISOString());

  /**
   * Whether the Add sheet holds typing worth keeping — the state it opened on
   * (a bare blank, or one a slot seeded) against the fields as they stand.
   * Nothing is asked until the two differ.
   */
  const addDirty = !!newPristine && addShape(newEvent) !== addShape(newPristine);

  /** The marked slot as the discard question names it: its day and its hours. */
  const slotLabel = slot
    ? `${new Date(`${slot.day}T12:00:00Z`).toLocaleDateString(undefined, DAY_FMT)} · ${ampmTime(
        slot.start
      )}–${ampmTime(slot.end)}`
    : '';

  /**
   * Runs a gesture that drops the marked slot — through the question first when
   * there is a slot to lose. With nothing marked there is nothing to ask about,
   * so the gesture runs straight away.
   */
  function askFirst(run: () => void, marks = false) {
    if (slot) setDropping({ run, marks });
    else run();
  }

  // Escape closes the Add Event sheet, the same as the other sheets on the site
  // — unless there is typing to lose, in which case it asks first.
  useEffect(() => {
    if (!adding) return;
    addPanel.current?.focus();
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') requestCloseAdd();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [adding, addDirty]);

  // The Edit sheet answers Escape the same way — the card stays as it was.
  useEffect(() => {
    if (!draft) return;
    editPanel.current?.focus();
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') closeDraft();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [draft]);

  // A slot marked off but not posted answers Escape too, as long as neither
  // sheet is up: the sheets own the key while they are open. Dropping the
  // draft is a discard, so it goes through the same question.
  useEffect(() => {
    if (!slot || adding || draft) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') askFirst(() => setSlot(null));
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [slot, adding, draft]);

  // An admin picks the venue; an operator is pinned to one, so the picker is
  // only fetched for the admin.
  useEffect(() => {
    if (!isAdmin) return;
    api.get<{ tracks: { id: string; name: string; slug: string }[] }>('/tracks?terms=public').then((r) => {
      const list = r.data?.tracks ?? [];
      setTrackList(list);
      setTrackId((prev) => prev || list[0]?.id || '');
    });
  }, [isAdmin]);

  const load = async (id: string) => {
    setMsg(null);
    setSlot(null);
    const res = await api.get<{ track: OwnerTrack }>(`/owner/track${id ? `?trackId=${id}` : ''}`);
    const t = res.data?.track ?? null;
    setTrack(t);
    setLoading(false);
    if (!t) return;
    // Open on the week the console handed over, or on the venue's next date —
    // the week the owner is most likely to be working in.
    const handed = focusParam ? t.events.find((e) => e.id === focusParam) : undefined;
    const anchorDay = handed ?? t.events.find((e) => dayKey(e.startsAt) >= today);
    if (anchorDay) {
      setAnchor(dayKey(anchorDay.startsAt));
      if (handed) {
        setFocusId(handed.id);
        setPicked(dayKey(handed.startsAt));
      }
    }
  };

  useEffect(() => {
    if (isAdmin && !trackId) return;
    load(isAdmin ? trackId : '');
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isAdmin, trackId, focusParam]);

  // The handed-over card is scrolled to once it is on the page — a card in a
  // week the reader had to step to is off screen otherwise.
  useEffect(() => {
    if (!focusId) return;
    rows.current[focusId]?.scrollIntoView({ block: 'center' });
  }, [focusId, anchor]);

  const step = (weeks: number) =>
    askFirst(() => {
      setAnchor((a) => stepWeek(a, weeks));
      setPicked(null);
      setSlot(null);
    });

  const goToday = () =>
    askFirst(() => {
      setAnchor(today);
      setPicked(null);
      setFocusId(null);
      setSlot(null);
    });

  /**
   * An empty hour of the grid was clicked: mark that slot off, an hour long to
   * begin with. A second click elsewhere on the week moves the slot rather than
   * adding a second one — a venue is filling one gate at a time — so a click
   * that would move the mark asks first, since the hours already set are lost
   * with it.
   */
  const selectSlot = (day: string, start: number, end: number) =>
    askFirst(() => setSlot({ day, start, end }), true);

  /**
   * A grip was dragged. The grid has already snapped the minute and held it
   * inside the drawn window and clear of the other edge, so this only moves the
   * one end the pointer owns.
   */
  const resizeSlot = (edge: SlotEdge, minutes: number) =>
    setSlot((s) => (s ? { ...s, [edge]: minutes } : s));

  /**
   * The marked block was carried: it lands on the day the pointer is over and
   * the hour it slid to, with its length kept. The draft is only being moved,
   * not thrown away, so nothing is asked first — the marker follows the drag.
   */
  const moveSlot = (day: string, start: number, end: number) =>
    setSlot((s) => (s ? { ...s, day, start, end } : s));

  /**
   * The marked slot opens the Add sheet with its day and hours already in, so
   * the week is where the *when* is set and the sheet only asks what the date
   * is called.
   */
  const openSlot = () => {
    if (!slot) return;
    openAdd({
      ...blankEvent(),
      startsAt: slot.day,
      startTime: clockTime(slot.start),
      endTime: clockTime(slot.end),
    });
  };

  /**
   * Opens the Add sheet on a fresh date, remembering those fields as the
   * untouched ones — the comparison every "you have typing to lose" ask is
   * read off.
   */
  function openAdd(seed: ReturnType<typeof blankEvent>) {
    setNewEvent(seed);
    setNewPristine(seed);
    setAdding(true);
  }

  function pickDay(day: string) {
    // A second click on the day already picked puts it down again: the list goes
    // back to the week and no card keeps its ring.
    if (day === picked) {
      setPicked(null);
      setFocusId(null);
      return;
    }
    const lead = byDay.get(day)?.[0];
    setPicked(day);
    setFocusId(lead?.id ?? null);
  }

  /**
   * A date already in hand — never a fresh write, which is not in `track` until
   * the state lands, so the write paths hand the event itself to `showDate`.
   * A grid pick narrows the cards to that date; posting or saving one keeps the
   * whole week in front of the owner, so `narrow` is off there.
   */
  function showDate(ev: { id: string; startsAt: string }, narrow = true) {
    setAnchor(dayKey(ev.startsAt));
    setPicked(narrow ? dayKey(ev.startsAt) : null);
    setFocusId(ev.id);
  }

  /** Every day the season covers, so a run that started last week still marks
   *  its days on this week's grid. */
  const byDay = useMemo(() => {
    const map = new Map<string, TrackEvent[]>();
    for (const ev of track?.events ?? []) {
      for (const k of daysOf(ev)) {
        const list = map.get(k);
        if (list) list.push(ev);
        else map.set(k, [ev]);
      }
    }
    return map;
  }, [track]);

  const monday = weekStart(anchor);
  const month = anchor.slice(0, 7);
  /**
   * The right column is a week; the left one is the month it sits in, so the
   * owner sees the whole month's dates and the week they are looking at at the
   * same time. A date that starts in the month is the month's, the way the
   * venue's own calendar pages a season.
   */
  const inMonth = useMemo(
    () => (track?.events ?? []).filter((e) => dayKey(e.startsAt).startsWith(month)),
    [track, month]
  );
  /**
   * The cards the page draws. A picked date narrows them to the dates that cover
   * it — read off every event, not the month's, so a run that began the month
   * before still shows under the day the grid marked.
   */
  const shown = useMemo(
    () => (picked ? (track?.events ?? []).filter((e) => daysOf(e).includes(picked)) : inMonth),
    [picked, track, inMonth]
  );
  const pickedLabel = picked
    ? new Date(`${picked}T12:00:00Z`).toLocaleDateString(undefined, DAY_FMT)
    : '';

  const monthLabel = new Date(`${anchor}T12:00:00Z`).toLocaleDateString(undefined, {
    month: 'long',
    year: 'numeric',
    timeZone: 'UTC',
  });

  /** The fields the Edit sheet writes to its working copy. */
  const editDraft = (patch: Partial<TrackEvent>) =>
    setDraft((d) => {
      if (!d) return d;
      const merged = { ...d, ...patch };
      // Moving a start past the end drops the end rather than leaving the two
      // crossed — the server refuses a crossed pair.
      if (patch.startsAt && merged.endsAt && merged.endsAt.slice(0, 10) < patch.startsAt) {
        merged.endsAt = null;
      }
      // Clearing one hour clears the pair: a date is timed or all-day, never
      // half of each, and the server writes the two together.
      if (patch.startMinutes === null || patch.endMinutes === null) {
        merged.startMinutes = null;
        merged.endMinutes = null;
      }
      return merged;
    });

  /**
   * Opens the Edit sheet on a copy, remembering the untouched event. A date
   * that already carries a note opens with it out — there is something to
   * read, so the sheet does not make the owner ask for it.
   */
  const openDraft = (ev: TrackEvent) => {
    setDraft({ ...ev });
    setPristine({ ...ev });
    setEditDescOpen(!!ev.description?.trim());
  };

  /**
   * A chip on the grid is the date it draws, so clicking one opens that date's
   * own sheet — the week edits what is on it. The day header over a column is
   * the other control: it narrows the month's list to a day.
   */
  const openEvent = (ev: { id: string }) => {
    const full = (track?.events ?? []).find((e) => e.id === ev.id);
    if (full) openDraft(full);
  };

  /** Drops the working copy — Cancel, Escape and the backdrop all land here. */
  const closeDraft = () => {
    setDraft(null);
    setPristine(null);
    setEditDescOpen(false);
  };

  /** Nothing to post until a field moves off the event the sheet opened on. */
  const draftDirty = !!draft && (!pristine || eventShape(draft) !== eventShape(pristine));

  /** The length the date in the Edit sheet currently runs, as the select reads it. */
  const editSpan = draft ? eventSpan(draft.startMinutes, draft.endMinutes) : null;

  /**
   * Puts the Add sheet away with the description folded back down, so the next
   * date opens on the form's own three fields rather than on the last one's.
   */
  function closeAdd() {
    setAdding(false);
    setDescOpen(false);
    setNewPristine(null);
    setDiscarding(false);
  }

  /**
   * The Add sheet's one way out. A sheet the owner has typed in asks first —
   * those fields are the only copy of the date they were writing. A sheet they
   * only opened (or one a slot seeded and they never touched) just closes.
   */
  function requestCloseAdd() {
    if (addDirty) setDiscarding(true);
    else closeAdd();
  }

  /**
   * The Date and Time wells' own glyph is the picker: the native mark is hidden
   * so the row reads as one line, which leaves a click anywhere on the field to
   * open the calendar. A browser that refuses the call still focuses the input.
   */
  const openPicker = (e: ReactMouseEvent<HTMLDivElement>) => {
    const input = e.currentTarget.querySelector('input') as
      | (HTMLInputElement & { showPicker?: () => void })
      | null;
    try {
      input?.showPicker?.();
    } catch {
      /* No user activation, or a browser that does not carry it — the field still focuses. */
    }
  };

  /** The Add sheet's own read of its hours, as the fields hold them. */
  const addFrom = minutesOf(newEvent.startTime);
  const addTo = minutesOf(newEvent.endTime);
  const addSpan = eventSpan(addFrom, addTo);

  /**
   * The hours are one pair — a date opens and closes, or carries no hours at
   * all — so moving one end keeps the other. Clearing either end makes the date
   * an all-day one; an hour typed on its own takes the other end of a seven-hour
   * gate for the owner to move. The server refuses a crossed single day, so
   * nothing here leaves one behind.
   */
  const setAddStart = (value: string) => {
    setNewEvent((n) => {
      const start = minutesOf(value);
      if (start == null) return { ...n, startTime: '', endTime: '' };
      const end = minutesOf(n.endTime);
      return {
        ...n,
        startTime: value,
        endTime: clockTime(end != null && end > start ? end : Math.min(start + 420, 1439)),
      };
    });
  };

  const setAddEnd = (value: string) => {
    setNewEvent((n) => {
      const end = minutesOf(value);
      if (end == null) return { ...n, startTime: '', endTime: '' };
      const start = minutesOf(n.startTime);
      return {
        ...n,
        startTime: clockTime(start != null && start < end ? start : Math.max(end - 420, 0)),
        endTime: value,
      };
    });
  };

  const addEvent = async () => {
    const res = await api.post<{ event: TrackEvent }>('/owner/track/events', {
      title: newEvent.title,
      kind: newEvent.kind,
      startsAt: newEvent.startsAt,
      endsAt: newEvent.endsAt || undefined,
      startMinutes: minutesOf(newEvent.startTime),
      endMinutes: minutesOf(newEvent.endTime),
      description: newEvent.description || undefined,
      isActive: newEvent.isActive,
      ...(isAdmin ? { trackId } : {}),
    });
    notice(res.success, res.message);
    if (res.success && res.data?.event) {
      const added = res.data.event;
      setTrack((t) => (t ? { ...t, events: sortEvents([...t.events, added]) } : t));
      setNewEvent(blankEvent());
      setSlot(null);
      closeAdd();
      showDate(added, false);
    }
  };

  const saveEvent = async (ev: TrackEvent) => {
    const res = await api.patch<{ event: TrackEvent }>(`/owner/track/events/${ev.id}`, {
      title: ev.title,
      kind: ev.kind,
      startsAt: dayValue(ev.startsAt),
      endsAt: ev.endsAt ? dayValue(ev.endsAt) : '',
      startMinutes: ev.startMinutes,
      endMinutes: ev.endMinutes,
      description: ev.description ?? '',
      isActive: ev.isActive,
      ...(isAdmin ? { trackId } : {}),
    });
    notice(res.success, res.message);
    if (res.success && res.data?.event) {
      const saved = res.data.event;
      setTrack((t) => (t ? { ...t, events: sortEvents(t.events.map((e) => (e.id === ev.id ? saved : e))) } : t));
      closeDraft();
      showDate(saved, false);
    }
  };

  const deleteEvent = async (id: string) => {
    const res = await api.del(`/owner/track/events/${id}${isAdmin ? `?trackId=${trackId}` : ''}`);
    notice(res.success, res.message);
    if (res.success) {
      setTrack((t) => (t ? { ...t, events: t.events.filter((e) => e.id !== id) } : t));
      if (focusId === id) setFocusId(null);
    }
  };

  if (loading) return <div className="muted">Loading calendar…</div>;
  if (!track) {
    return (
      <div className="stack cal-page">
        <Banner tone="warn">
          No track is pinned to this account. Ask an admin to pin your operator account to a venue.
        </Banner>
      </div>
    );
  }

  return (
    <div className="stack cal-page">
      <div className="row spread wrap cal-top">
        <div className="cal-title-spacer" aria-hidden="true" />
        <div className="row wrap">
          {isAdmin && (
            // Picking another venue reloads the page's season, which drops the
            // marked slot with it — so it goes through the same question.
            <select
              value={trackId}
              onChange={(e) => askFirst(() => setTrackId(e.target.value))}
              style={{ minWidth: 200 }}
            >
              {trackList.map((t) => (
                <option key={t.id} value={t.id}>
                  {t.name}
                </option>
              ))}
            </select>
          )}
          <button
            className="primary small"
            onClick={() =>
              askFirst(() => {
                // The header's own form starts blank, so a slot marked on the
                // grid is put down rather than left behind it.
                setSlot(null);
                openAdd(blankEvent());
              })
            }
          >
            Add Event
          </button>
        </div>
      </div>

      {msg && (
        <Banner key={msg.id} tone={msg.ok ? 'ok' : 'bad'} floating close ms={msg.ok ? 4000 : 8000}>
          {msg.text}
        </Banner>
      )}

      <div className="cal-editor" data-week={monday} data-month={anchor.slice(0, 7)}>
        {/* The month's dates on the left, the week they sit in on the right —
            the two read together: a date picked on the grid rings its card
            here, and the card is where it is edited. */}
        <div className="stack event-editor">
          {/* What the cards hold: the whole month, or the one date a pick
              narrowed them to — with the way back to the month beside it. */}
          <div className="row spread wrap event-list-head">
            <span className="row event-list-title">
              <b className="small">{monthLabel}</b>
              {!picked && <span className="tiny muted">{shown.length} dates</span>}
            </span>
            {picked && (
              <div className="event-filter">
                <span className="small event-filter-day">{pickedLabel}</span>
                <button className="ghost small" onClick={() => setPicked(null)}>
                  Show all events
                </button>
              </div>
            )}
          </div>

          {shown.length === 0 && (
            <div className="small muted">
              {picked
                ? 'Nothing on this date. Show all events puts the month back.'
                : 'Nothing on the calendar this month. Add a date above.'}
            </div>
          )}

          {shown.map((ev) => {
            const hours = ampmLabel(ev);
            return (
              <div
                key={ev.id}
                ref={(el) => {
                  rows.current[ev.id] = el;
                }}
                className={[
                  'event-edit-row',
                  ev.isActive ? '' : 'is-hidden',
                  focusId === ev.id ? 'is-focused' : '',
                ]
                  .filter(Boolean)
                  .join(' ')}
              >
                {/* The card reads: the date, its hours and what is on it — and the
                    card itself is the control. A click anywhere on it opens the
                    field sheet; `event-open` is the button that covers it, so the
                    text keeps its markup and a keyboard reader still reaches it. */}
                <button
                  type="button"
                  className="event-open"
                  aria-label={`Edit ${ev.title}`}
                  onClick={() => openDraft(ev)}
                />
                <div className="row wrap event-title-row">
                  <h4 className="event-card-title">{ev.title}</h4>
                  {!ev.isActive && <span className="pill warn">Hidden</span>}
                </div>
                <div className="small muted event-card-when">
                  {dayRange(ev)}
                  {hours && <span className="event-card-hours"> · {hours}</span>}
                </div>
              </div>
            );
          })}
        </div>

        <WeekGrid
          events={track.events}
          anchor={anchor}
          today={today}
          picked={picked}
          slot={slot}
          onStep={step}
          onToday={goToday}
          onPickDay={pickDay}
          onPickEvent={openEvent}
          onSelectSlot={selectSlot}
          onResizeSlot={resizeSlot}
          onMoveSlot={moveSlot}
          onOpenSlot={openSlot}
        />
      </div>

      {/* Adding a date is a sheet, not a row in the list: the week stays in
          front of the owner and the form closes itself once the date posts. */}
      {adding && (
        <div className="sheet-backdrop" onClick={requestCloseAdd}>
          <div
            className="sheet event-sheet"
            role="dialog"
            aria-modal="true"
            aria-labelledby="add-event-title"
            tabIndex={-1}
            ref={addPanel}
            onClick={(e) => e.stopPropagation()}
          >
            <h4 className="sheet-title" id="add-event-title">
              Add an event
            </h4>
            {/* The date's own fields, in the order an owner says them: what it
                is called, the day it runs, the hour it opens and the hour it
                closes — the length between the two is worked out for them, not
                asked for. The description rides beside the name until it is
                asked for, and everything else a date carries waits under the
                read-back. */}
            <div className="ev-form">
              <div className="ev-field">
                <label className="ev-label" htmlFor="ev-name">
                  Event name
                </label>
                <div className="ev-well">
                  <input
                    id="ev-name"
                    className="ev-control"
                    value={newEvent.title}
                    onChange={(e) => setNewEvent({ ...newEvent, title: e.target.value })}
                    placeholder="Enter event name"
                  />
                  <button
                    type="button"
                    className="ev-desc-add"
                    aria-expanded={descOpen}
                    aria-controls="ev-note"
                    onClick={() => setDescOpen((open) => !open)}
                  >
                    {descToggleLabel(descOpen, !!newEvent.description)}
                  </button>
                </div>
              </div>

              {descOpen && (
                <div className="ev-field">
                  <label className="ev-label" htmlFor="ev-note">
                    Description
                  </label>
                  <div className="ev-well">
                    <input
                      id="ev-note"
                      className="ev-control"
                      value={newEvent.description}
                      onChange={(e) => setNewEvent({ ...newEvent, description: e.target.value })}
                      placeholder="Gates open an hour before the first moto"
                    />
                  </div>
                </div>
              )}

              <div className="ev-row-3">
                <div className="ev-field">
                  <label className="ev-label" htmlFor="ev-date">
                    Date
                  </label>
                  <div className="ev-well" onClick={openPicker}>
                    <input
                      id="ev-date"
                      type="date"
                      className="ev-control"
                      value={newEvent.startsAt}
                      onChange={(e) =>
                        setNewEvent((n) => ({
                          ...n,
                          startsAt: e.target.value,
                          endsAt: n.endsAt && n.endsAt < e.target.value ? '' : n.endsAt,
                        }))
                      }
                    />
                    <IconCalendar />
                  </div>
                </div>
                <div className="ev-field">
                  <label className="ev-label" htmlFor="ev-from">
                    From
                  </label>
                  <div className="ev-well" onClick={openPicker}>
                    <input
                      id="ev-from"
                      type="time"
                      className="ev-control"
                      value={newEvent.startTime}
                      onChange={(e) => setAddStart(e.target.value)}
                    />
                    <IconClock />
                  </div>
                </div>
                <div className="ev-field">
                  <label className="ev-label" htmlFor="ev-to">
                    To
                  </label>
                  <div className="ev-well" onClick={openPicker}>
                    <input
                      id="ev-to"
                      type="time"
                      className="ev-control"
                      value={newEvent.endTime}
                      onChange={(e) => setAddEnd(e.target.value)}
                    />
                    <IconClock />
                  </div>
                </div>
              </div>

              {/* The fields said back as a sentence, with the length they add
                  up to beside it: a gate that ends at the wrong hour is visible
                  before it posts. */}
              <div className="ev-readback">
                <p className="ev-note">{eventSentence(newEvent.startsAt, newEvent.endsAt, addFrom, addTo)}</p>
                {addSpan != null && <span className="ev-span">{spanLabel(addSpan)}</span>}
              </div>

              {/* What else a date carries — its type, a run past the day, and
                  whether riders see it yet — reads quieter than the three
                  above, and quieter than the sentence that answers them. */}
              <div className="ev-row-3 ev-extra">
                <div className="ev-field">
                  <label className="ev-label ev-label-quiet" htmlFor="ev-kind">
                    Type
                  </label>
                  <div className="ev-well ev-well-select">
                    <select
                      id="ev-kind"
                      className="ev-control"
                      value={newEvent.kind}
                      onChange={(e) => setNewEvent({ ...newEvent, kind: e.target.value })}
                    >
                      {EVENT_KINDS.map((k) => (
                        <option key={k} value={k}>
                          {EVENT_KIND_OPTION[k]}
                        </option>
                      ))}
                    </select>
                    <IconUpDown />
                  </div>
                </div>
                <div className="ev-field">
                  <label className="ev-label ev-label-quiet" htmlFor="ev-ends">
                    Runs until
                  </label>
                  <div className="ev-well" onClick={openPicker}>
                    <input
                      id="ev-ends"
                      type="date"
                      className="ev-control"
                      value={newEvent.endsAt}
                      onChange={(e) => setNewEvent({ ...newEvent, endsAt: e.target.value })}
                    />
                    <IconCalendar />
                  </div>
                </div>
                <div className="ev-field">
                  <label className="ev-label ev-label-quiet" htmlFor="ev-shown">
                    Shown
                  </label>
                  <div className="ev-well ev-well-select">
                    <select
                      id="ev-shown"
                      className="ev-control"
                      value={newEvent.isActive ? 'yes' : 'no'}
                      onChange={(e) => setNewEvent({ ...newEvent, isActive: e.target.value === 'yes' })}
                    >
                      <option value="yes">Visible</option>
                      <option value="no">Hidden</option>
                    </select>
                    <IconUpDown />
                  </div>
                </div>
              </div>
            </div>
            <div className="row">
              <button className="primary small" onClick={addEvent} disabled={newEvent.title.trim().length < 2}>
                Add event
              </button>
              <button className="ghost small" onClick={requestCloseAdd}>
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Clicking away from a new date does not throw the typing away without a
          word: the fields are the only copy of it, so the sheet asks first. */}
      {adding && discarding && (
        <ConfirmSheet
          id="discard-event"
          title="Discard this event?"
          copy={`${newEvent.title.trim() || 'Untitled event'} · ${
            newEvent.startsAt ? longDay(newEvent.startsAt) : 'no date yet'
          }`}
          confirmLabel="Discard"
          cancelLabel="Keep editing"
          onCancel={() => setDiscarding(false)}
          onConfirm={() => closeAdd()}
        />
      )}

      {/* The week's own draft is dropped by whatever gesture takes its place —
          another hour, another week, Today, the blank Add form — so those
          gestures ask first, the way the Add sheet asks over its fields. */}
      {dropping && (
        <ConfirmSheet
          id="discard-slot"
          title="Discard this draft?"
          copy={slotLabel}
          confirmLabel="Discard"
          cancelLabel="Keep draft"
          onCancel={() => setDropping(null)}
          onConfirm={() => {
            const { run, marks } = dropping;
            setDropping(null);
            // An answered discard leaves the week empty: the click that asked
            // is spent on the question, not on drawing a new draft behind it.
            if (marks) setSlot(null);
            else run();
          }}
        />
      )}

      {/* Editing a date is the same sheet shape as adding one, opened by a click
          on the card itself: the fields post on Save, and anything else
          (Cancel, Escape, the backdrop) drops the working copy. */}
      {draft && (
        <div className="sheet-backdrop" onClick={() => closeDraft()}>
          <div
            className="sheet event-sheet"
            role="dialog"
            aria-modal="true"
            aria-labelledby="edit-event-title"
            tabIndex={-1}
            ref={editPanel}
            onClick={(e) => e.stopPropagation()}
          >
            <h4 className="sheet-title" id="edit-event-title">
              Edit event
            </h4>
            {/* The same fields as the Add sheet, in the same order — a date is
                read and written the one way, whether it is new or an old one. */}
            <div className="ev-form">
              <div className="ev-field">
                <label className="ev-label" htmlFor="ed-name">
                  Event name
                </label>
                <div className="ev-well">
                  <input
                    id="ed-name"
                    className="ev-control"
                    value={draft.title}
                    onChange={(e) => editDraft({ title: e.target.value })}
                  />
                  <button
                    type="button"
                    className="ev-desc-add"
                    aria-expanded={editDescOpen}
                    aria-controls="ed-note"
                    onClick={() => setEditDescOpen((open) => !open)}
                  >
                    {descToggleLabel(editDescOpen, !!draft.description)}
                  </button>
                </div>
              </div>

              {editDescOpen && (
                <div className="ev-field">
                  <label className="ev-label" htmlFor="ed-note">
                    Description
                  </label>
                  <div className="ev-well">
                    <input
                      id="ed-note"
                      className="ev-control"
                      value={draft.description ?? ''}
                      onChange={(e) => editDraft({ description: e.target.value })}
                      placeholder="Gates open an hour before the first moto"
                    />
                  </div>
                </div>
              )}

              <div className="ev-row-3">
                <div className="ev-field">
                  <label className="ev-label" htmlFor="ed-date">
                    Date
                  </label>
                  <div className="ev-well" onClick={openPicker}>
                    <input
                      id="ed-date"
                      type="date"
                      className="ev-control"
                      value={dayValue(draft.startsAt)}
                      onChange={(e) => editDraft({ startsAt: e.target.value })}
                    />
                    <IconCalendar />
                  </div>
                </div>
                <div className="ev-field">
                  <label className="ev-label" htmlFor="ed-from">
                    From
                  </label>
                  <div className="ev-well" onClick={openPicker}>
                    <input
                      id="ed-from"
                      type="time"
                      className="ev-control"
                      value={timeValue(draft.startMinutes)}
                      onChange={(e) => {
                        const start = minutesOf(e.target.value);
                        if (start == null) {
                          editDraft({ startMinutes: null, endMinutes: null });
                          return;
                        }
                        // The pair stays whole: an open hour keeps the length it
                        // had, or takes the day's own seven-hour gate.
                        const end =
                          draft.endMinutes != null && draft.endMinutes > start
                            ? draft.endMinutes
                            : Math.min(start + 420, 1439);
                        editDraft({ startMinutes: start, endMinutes: end });
                      }}
                    />
                    <IconClock />
                  </div>
                </div>
                <div className="ev-field">
                  <label className="ev-label" htmlFor="ed-to">
                    To
                  </label>
                  <div className="ev-well" onClick={openPicker}>
                    <input
                      id="ed-to"
                      type="time"
                      className="ev-control"
                      value={timeValue(draft.endMinutes)}
                      onChange={(e) => {
                        const end = minutesOf(e.target.value);
                        if (end == null) {
                          editDraft({ startMinutes: null, endMinutes: null });
                          return;
                        }
                        const start =
                          draft.startMinutes != null && draft.startMinutes < end
                            ? draft.startMinutes
                            : Math.max(end - 420, 0);
                        editDraft({ startMinutes: start, endMinutes: end });
                      }}
                    />
                    <IconClock />
                  </div>
                </div>
              </div>

              {/* The same read-back as the Add sheet: the sentence, with the
                  length it names beside it. */}
              <div className="ev-readback">
                <p className="ev-note">
                  {eventSentence(
                    dayValue(draft.startsAt),
                    dayValue(draft.endsAt),
                    draft.startMinutes,
                    draft.endMinutes
                  )}
                </p>
                {editSpan != null && <span className="ev-span">{spanLabel(editSpan)}</span>}
              </div>

              <div className="ev-row-3 ev-extra">
                <div className="ev-field">
                  <label className="ev-label ev-label-quiet" htmlFor="ed-kind">
                    Type
                  </label>
                  <div className="ev-well ev-well-select">
                    <select
                      id="ed-kind"
                      className="ev-control"
                      value={draft.kind}
                      onChange={(e) => editDraft({ kind: e.target.value })}
                    >
                      {EVENT_KINDS.map((k) => (
                        <option key={k} value={k}>
                          {EVENT_KIND_OPTION[k]}
                        </option>
                      ))}
                    </select>
                    <IconUpDown />
                  </div>
                </div>
                <div className="ev-field">
                  <label className="ev-label ev-label-quiet" htmlFor="ed-ends">
                    Runs until
                  </label>
                  <div className="ev-well" onClick={openPicker}>
                    <input
                      id="ed-ends"
                      type="date"
                      className="ev-control"
                      value={dayValue(draft.endsAt)}
                      onChange={(e) => editDraft({ endsAt: e.target.value || null })}
                    />
                    <IconCalendar />
                  </div>
                </div>
                <div className="ev-field">
                  <label className="ev-label ev-label-quiet" htmlFor="ed-shown">
                    Shown
                  </label>
                  <div className="ev-well ev-well-select">
                    <select
                      id="ed-shown"
                      className="ev-control"
                      value={draft.isActive ? 'yes' : 'no'}
                      onChange={(e) => editDraft({ isActive: e.target.value === 'yes' })}
                    >
                      <option value="yes">Visible</option>
                      <option value="no">Hidden</option>
                    </select>
                    <IconUpDown />
                  </div>
                </div>
              </div>
            </div>
            <div className="row">
              <button
                className="primary small"
                onClick={() => saveEvent(draft)}
                disabled={draft.title.trim().length < 2 || !draftDirty}
                title={draftDirty ? undefined : 'No changes yet'}
              >
                Save event
              </button>
              <button className="ghost small danger" onClick={() => setConfirming(true)}>
                Remove
              </button>
              <button className="ghost small" onClick={() => closeDraft()}>
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Removing a date is the one thing this form cannot put back, so it asks
          first — a small sheet over the edit sheet, naming what is about to go. */}
      {draft && confirming && (
        <ConfirmSheet
          id="remove-event"
          title="Remove this date?"
          copy={`${draft.title} · ${dayRange(draft)}`}
          confirmLabel="Remove"
          onCancel={() => setConfirming(false)}
          onConfirm={() => {
            setConfirming(false);
            deleteEvent(draft.id);
            closeDraft();
          }}
        />
      )}
    </div>
  );
}

function sortEvents(events: TrackEvent[]) {
  return [...events].sort((a, b) => a.startsAt.localeCompare(b.startsAt));
}

import { useEffect, useMemo, useState } from 'react';
import Banner from '../../components/Banner';
import Avatar from '../../components/Avatar';
import ConfirmSheet from '../../components/ConfirmSheet';
import PhotoLightbox from '../../components/PhotoLightbox';
import { api, dayStr } from '../../lib/api';
import { useAuth } from '../../lib/auth';
import { SortTh, useSorted } from '../../components/sortable';

/** One member of the venue's community, as `GET /owner/followers` returns them. */
interface Member {
  id: string;
  userId: string;
  name: string;
  email: string;
  location: string | null;
  avatarUrl: string | null;
  followedAt: string;
  tierName: string | null;
  paid: boolean;
  passStatus: string | null;
  visits: number;
  lastRideDay: string | null;
}

/** One frame attached to a review. */
interface ReviewPhoto {
  id: string;
  url: string;
  caption: string | null;
}

/** A rider's review of the venue, as `GET /owner/followers` returns it. */
interface TrackReview {
  id: string;
  rating: number;
  body: string;
  createdAt: string;
  updatedAt: string;
  userId: string;
  riderName: string;
  riderAvatarUrl: string | null;
  photos: ReviewPhoto[];
}

interface Payload {
  track: { id: string; name: string; slug: string };
  summary: {
    total: number;
    newLast30: number;
    paying: number;
    free: number;
    riddenHere: number;
    reviews: number;
  };
  followers: Member[];
  reviews: TrackReview[];
}

/** The audience cut the owner reads it by: paying or not. */
type Filter = 'all' | 'paying' | 'free';

const FILTERS: { key: Filter; label: string }[] = [
  { key: 'all', label: 'All' },
  { key: 'paying', label: 'Paying' },
  { key: 'free', label: 'Free' },
];

/** Five stars, the filled ones picking the rating. */
function Stars({ rating }: { rating: number }) {
  return (
    <span className="community-stars" aria-label={`${rating} out of 5`}>
      {[1, 2, 3, 4, 5].map((n) => (
        <span key={n} aria-hidden className={n <= rating ? 'on' : 'off'}>
          ★
        </span>
      ))}
    </span>
  );
}

/**
 * The venue's community: every account following the track, the pass each one
 * holds, how much it has ridden here, and the reviews riders have written about
 * the track.
 *
 * An operator is pinned to one venue, so the page reads only that track; an
 * admin has none, so it gets a venue picker and reads on the venue's behalf
 * through `?trackId=` — the same shape as the profile console and the calendar.
 *
 * The member list is read-only: a follow is the rider's to give and take. The
 * review wall is not — a rider's review sits on the venue's page, so the venue
 * can pull one (asked first, through the same confirm sheet as a date). A rider
 * writes one review per venue and edits that same review afterwards; the venue
 * sees the edited account, not a feed.
 */
export default function OperatorCommunity() {
  const { user } = useAuth();
  const isAdmin = user?.role === 'ADMIN';

  const [trackList, setTrackList] = useState<{ id: string; name: string; slug: string }[]>([]);
  const [trackId, setTrackId] = useState('');
  const [data, setData] = useState<Payload | null>(null);
  const [filter, setFilter] = useState<Filter>('all');
  const [msg, setMsg] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [viewing, setViewing] = useState<{ review: TrackReview; index: number } | null>(null);
  const [removing, setRemoving] = useState<TrackReview | null>(null);

  // An admin picks the venue; an operator is pinned to one, so the picker is
  // only fetched for the admin.
  useEffect(() => {
    if (!isAdmin) return;
    api.get<{ tracks: { id: string; name: string; slug: string }[] }>('/tracks?terms=public').then((r) => {
      const list = r.data?.tracks ?? [];
      setTrackList(list);
      setTrackId((prev) => prev || list[0]?.id || '');
    });
  }, [isAdmin]);

  const load = async (id: string) => {
    setMsg(null);
    const res = await api.get<Payload>(`/owner/followers${id ? `?trackId=${id}` : ''}`);
    setData(res.data ?? null);
    if (!res.success) setMsg(res.message);
    setLoading(false);
  };

  useEffect(() => {
    if (isAdmin && !trackId) return;
    load(isAdmin ? trackId : '');
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isAdmin, trackId]);

  const members = data?.followers ?? [];
  const reviews = data?.reviews ?? [];

  const counts: Record<Filter, number> = {
    all: data?.summary.total ?? 0,
    paying: data?.summary.paying ?? 0,
    free: data?.summary.free ?? 0,
  };

  // The cut is client-side: the whole audience arrives in one read, so a filter
  // never costs a round trip.
  const shown = useMemo(
    () =>
      members.filter((f) =>
        filter === 'paying'
          ? f.paid
          : filter === 'free'
            ? !f.paid
            : true
      ),
    [members, filter]
  );

  const { sorted, sort, toggle } = useSorted(shown, {
    rider: (f) => f.name,
    from: (f) => f.location,
    pass: (f) => (f.paid ? 1 : 0),
    rides: (f) => f.visits,
    since: (f) => f.followedAt,
  });

  const removeReview = async (review: TrackReview) => {
    setRemoving(null);
    const res = await api.del(`/owner/reviews/${review.id}${isAdmin && trackId ? `?trackId=${trackId}` : ''}`);
    if (!res.success) {
      setMsg(res.message ?? 'Could not remove that review.');
      return;
    }
    setData((prev) =>
      prev
        ? {
            ...prev,
            reviews: prev.reviews.filter((r) => r.id !== review.id),
            summary: { ...prev.summary, reviews: Math.max(0, prev.summary.reviews - 1) },
          }
        : prev
    );
    setMsg('Review removed from the venue page.');
  };

  if (loading) return <div className="muted">Loading community…</div>;
  if (!data) {
    return (
      <div className="stack">
        <h1>Community</h1>
        <Banner tone="warn">
          {msg || 'No track is pinned to this account. Ask an admin to pin your operator account to a venue.'}
        </Banner>
      </div>
    );
  }

  /** A member's standing at the gate: the tier they ride on, or why they are
   *  not on one yet — a lapsed or pending pass is not a member. */
  const passCell = (f: Member) => {
    if (f.paid) {
      return (
        <span className="row community-pass">
          <span className="pill ok">{f.tierName}</span>
        </span>
      );
    }
    if (f.passStatus && f.passStatus !== 'ACTIVE') {
      return <span className="pill warn">{f.passStatus.toLowerCase()}</span>;
    }
    return <span className="small muted">{f.tierName ?? 'No pass'}</span>;
  };

  return (
    <div className="stack community-page">
      <div className="row spread wrap">
        <div>
          <h1>Community</h1>
        </div>
        {isAdmin && (
          <div className="row wrap">
            <select value={trackId} onChange={(e) => setTrackId(e.target.value)} style={{ minWidth: 200 }}>
              {trackList.map((t) => (
                <option key={t.id} value={t.id}>
                  {t.name}
                </option>
              ))}
            </select>
          </div>
        )}
      </div>

      {msg && <Banner tone="bad" close>{msg}</Banner>}

      <div className="table-block">
        <div className="table-head">
          <h3>Riders here</h3>
          <div className="pill-toggle">
            {FILTERS.map((f) => (
              <button key={f.key} aria-pressed={filter === f.key} onClick={() => setFilter(f.key)}>
                {f.label} <span className="community-count">{counts[f.key]}</span>
              </button>
            ))}
          </div>
        </div>

        <div className="card" style={{ padding: 0 }}>
          <div className="table-scroll">
            <table>
              <thead>
                <tr>
                  <SortTh sortKey="rider" sort={sort} onSort={toggle}>Rider</SortTh>
                  <SortTh sortKey="from" sort={sort} onSort={toggle}>From</SortTh>
                  <SortTh sortKey="pass" sort={sort} onSort={toggle}>Pass</SortTh>
                  <SortTh sortKey="rides" sort={sort} onSort={toggle} className="right">Rides here</SortTh>
                  <SortTh sortKey="since" sort={sort} onSort={toggle}>In the community since</SortTh>
                </tr>
              </thead>
              <tbody>
                {sorted.map((f) => (
                  <tr key={f.id}>
                    <td>
                      <div className="community-cell">
                        <Avatar src={f.avatarUrl} name={f.name} className="community-photo" />
                        <div className="community-who">
                          <b>{f.name}</b>
                          <span className="tiny muted">{f.email}</span>
                        </div>
                      </div>
                    </td>
                    <td className="small muted">{f.location || '—'}</td>
                    <td>{passCell(f)}</td>
                    <td className="right">
                      {f.visits ? (
                        <>
                          <b>{f.visits}</b>
                          {f.lastRideDay && <div className="tiny muted">{dayStr(f.lastRideDay)}</div>}
                        </>
                      ) : (
                        <span className="muted">—</span>
                      )}
                    </td>
                    <td className="small muted">{dayStr(f.followedAt)}</td>
                  </tr>
                ))}
                {!members.length && (
                  <tr>
                    <td colSpan={5} className="muted small">
                      No riders in this community yet.
                    </td>
                  </tr>
                )}
                {!!members.length && !shown.length && (
                  <tr>
                    <td colSpan={5} className="muted small">
                      No riders match this cut.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* What riders have written about the venue. A review sits on the venue's
          page, so the venue can pull one — asked first, because it is the
          rider's account of the place. */}
      <section className="card stack community-wall">
        <div className="section-head">
          <h3>Reviews{reviews.length > 1 ? ` (${reviews.length})` : ''}</h3>
        </div>

        {reviews.length === 0 ? (
          <div className="small muted">
            No rider reviews yet. Riders write theirs from the venue's own page.
          </div>
        ) : (
          <ul className="community-wall-grid">
            {reviews.map((r) => (
              <li key={r.id} className="community-wall-card">
                <div className="community-wall-head">
                  <Avatar src={r.riderAvatarUrl} name={r.riderName} className="community-wall-face" />
                  <div className="community-wall-who">
                    <b>{r.riderName}</b>
                    <span className="tiny muted">{dayStr(r.createdAt)}</span>
                  </div>
                  <Stars rating={r.rating} />
                </div>
                {r.body && <p className="community-wall-body">{r.body}</p>}
                {r.photos.length > 0 && (
                  <div className="community-wall-shots">
                    {r.photos.map((p, i) => (
                      <button
                        key={p.id}
                        type="button"
                        className="community-wall-shot"
                        onClick={() => setViewing({ review: r, index: i })}
                        aria-label={p.caption || `Photo by ${r.riderName}`}
                      >
                        <img src={p.url} alt={p.caption || `${data.track.name} by ${r.riderName}`} loading="lazy" />
                      </button>
                    ))}
                  </div>
                )}
                <div className="community-wall-by">
                  <button
                    type="button"
                    className="community-wall-remove"
                    onClick={() => setRemoving(r)}
                    title="Take this review off the venue page"
                  >
                    Remove
                  </button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </section>

      <p className="tiny muted">
        A follow is the rider's to give and take; this page only reads the list. Riders who hold
        the free tier can follow a venue; a pass is what puts them through the gate.
      </p>

      {viewing && (
        <PhotoLightbox
          photos={viewing.review.photos.map((p) => ({ id: p.id, url: p.url, caption: p.caption }))}
          name={data.track.name}
          index={viewing.index}
          onIndex={(i) => setViewing({ review: viewing.review, index: i })}
          onClose={() => setViewing(null)}
        />
      )}

      {removing && (
        <ConfirmSheet
          id="remove-rider-review"
          title="Remove this review?"
          copy={`${removing.rating}-star review by ${removing.riderName}`}
          confirmLabel="Remove review"
          onConfirm={() => removeReview(removing)}
          onCancel={() => setRemoving(null)}
        />
      )}
    </div>
  );
}

import { useState } from 'react';
import Banner from '../../components/Banner';
import { money } from '../../lib/api';
import { reasonLabel } from '../../lib/reasonLabels';
import Scanner, { ScanOutcome } from '../../components/Scanner';
import ToastStack, { useToasts } from '../../components/ToastStack';
/** An approval carries figures the operator repeats to the rider at the window
    (what to collect, days left), so it outlasts a plain confirmation. */
const APPROVAL_TOAST_MS = 8000;

/**
 * The operator's home: the scanning station at the gate. The season's read and
 * the activity log moved to `/operator/reports` — this page stays the one
 * surface an operator uses with a rider standing in front of them.
 */
export default function OperatorDashboard() {
  const [result, setResult] = useState<ScanOutcome | null>(null);
  /** Approvals and re-entries in flight: one notice each, stacking while they live. */
  const { toasts, push, dismiss } = useToasts();
  /** Letting a rider through is a confirmation, not a gate decision: the day is
      spent either way, so it reads as a toast. A denial is the one outcome that
      keeps the page's band — its reason is what the operator has to say out
      loud to the rider in front of them. */
  const denied = !!result && !result.approved && result.reasonCode !== 'RE_ENTRY';

  /** One landing for both doors — the camera and the lookup. */
  const handleResult = (o: ScanOutcome) => {
    if (o.reasonCode === 'RE_ENTRY') {
      push({
        tone: 'ok',
        ms: APPROVAL_TOAST_MS,
        title: o.rider?.name ? `Re-entry approved for ${o.rider.name}` : 'Re-entry approved',
      });
    } else if (o.approved) {
      /** What the window still has to do, then what the rider has left — the
          two figures the band used to carry. */
      const facts: string[] = [];
      if (o.amountChargedCents) facts.push(`Collect ${money(o.amountChargedCents)} at the window`);
      if (o.remainingFreeDays != null && o.includedDays != null && o.includedDays > 0) {
        facts.push(`${o.remainingFreeDays} of ${o.includedDays} free days left`);
      }
      push({
        tone: 'ok',
        ms: APPROVAL_TOAST_MS,
        title: o.rider?.name ? `Day redeemed for ${o.rider.name}` : 'Day redeemed',
        detail: facts.length > 0 ? facts.join(' · ') : undefined,
      });
    }
    setResult(o);
  };

  return (
    <div className="stack">
      <Scanner onResult={handleResult} result={result} />

      {denied && result && (
        <Banner tone="bad" small={false} close>
          <div className="row spread">
            <strong style={{ fontSize: 18 }}>DENIED</strong>
            {/* An approval's code is the same word as its headline; only a
                denial's code carries anything extra. */}
            {result.reasonCode !== 'DENIED' && (
              <span className="tiny muted">{reasonLabel(result.reasonCode)}</span>
            )}
          </div>
          <div className="small" style={{ marginTop: 6 }}>
            {result.reason}
          </div>
          {result.rider && (
            <div className="small" style={{ marginTop: 10 }}>
              <div>
                <span className="muted">Rider </span>
                {result.rider.name}
              </div>
              <div className="tiny muted">{result.rider.email}</div>
              {result.pass && (
                <div className="tiny muted">
                  {result.pass.tierName} · {result.pass.seasonYear} · expires{' '}
                  {result.pass.expiresAt.slice(0, 10)}
                </div>
              )}
            </div>
          )}
          {result.includedDays != null && (
            <div className="row spread small" style={{ marginTop: 10 }}>
              <span className="muted">Free days remaining at this track</span>
              <strong>
                {result.remainingFreeDays} / {result.includedDays}
              </strong>
            </div>
          )}
          {result.discountDaysRemaining != null && result.discountDaysRemaining > 0 && (
            <div className="row spread small">
              <span className="muted">Discounted extra days left</span>
              <span>{result.discountDaysRemaining}</span>
            </div>
          )}
          {result.amountChargedCents ? (
            <div className="row spread small">
              <span className="muted">Collect at the window</span>
              <strong className="warn">{money(result.amountChargedCents)}</strong>
            </div>
          ) : null}
        </Banner>
      )}

      <ToastStack toasts={toasts} onDismiss={dismiss} />
    </div>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import Banner from '../../components/Banner';
import ImagePicker from '../../components/ImagePicker';
import TrackLogo from '../../components/TrackLogo';
import GalleryManager, { type OwnerPhoto } from '../../components/GalleryManager';
import EventCalendar from '../../components/EventCalendar';
import DayStatusEditor from '../../components/DayStatusEditor';
import { api } from '../../lib/api';
import { useAuth } from '../../lib/auth';
import { statusLabel } from '../../lib/trackAccess';
import { HOURS_WEEK_DAYS, parseHoursWeek, serializeHoursWeek } from '../../lib/hoursWeek';
import type { DayStatus, ProfileEvent } from '../../lib/events';

/**
 * The track owner's own console: the profile their venue page is built from.
 *
 * The owner is the OPERATOR pinned to the venue (see the owner controller), so
 * the page reads and writes only that track. An ADMIN has no pinned track, so
 * it gets a venue picker and edits on their behalf through `?trackId=` — the
 * org's Tracks page still owns contracts, this page owns the profile.
 *
 * The season is not written here: the dates read the way a rider reads them, and
 * both hand-offs to the calendar page are links — `Open calendar` for the
 * venue's month, `Edit` on a date for that date's own row.
 */

interface OwnerTrack {
  id: string;
  slug: string;
  name: string;
  description: string | null;
  city: string | null;
  region: string | null;
  address: string | null;
  website: string | null;
  instagram: string | null;
  facebook: string | null;
  youtube: string | null;
  tiktok: string | null;
  email: string | null;
  phone: string | null;
  bannerUrl: string | null;
  logoUrl: string | null;
  imageUrl: string | null;
  hours: string | null;
  /** The venue's week as the API stores it — a JSON string, or null. */
  hoursWeek: string | null;
  status: string;
  statusNote: string | null;
  /** The operator's own message to riders — read in the network panel. */
  riderMessage: string | null;
  nextEvent: string | null;
  category: string;
  events: ProfileEvent[];
  dayStatuses: DayStatus[];
  photos: OwnerPhoto[];
}

export default function OperatorProfile() {
  const { user } = useAuth();
  const isAdmin = user?.role === 'ADMIN';

  const [trackList, setTrackList] = useState<{ id: string; name: string; slug: string }[]>([]);
  const [trackId, setTrackId] = useState('');
  const [track, setTrack] = useState<OwnerTrack | null>(null);
  const [form, setForm] = useState<Record<string, string>>({});
  const [msg, setMsg] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  // An admin picks the venue; an operator is pinned to one, so the picker is
  // only fetched for the admin.
  useEffect(() => {
    if (!isAdmin) return;
    api.get<{ tracks: { id: string; name: string; slug: string }[] }>('/tracks?terms=public').then((r) => {
      const list = r.data?.tracks ?? [];
      setTrackList(list);
      setTrackId((prev) => prev || list[0]?.id || '');
    });
  }, [isAdmin]);

  const load = async (id: string) => {
    setMsg(null);
    const res = await api.get<{ track: OwnerTrack }>(`/owner/track${id ? `?trackId=${id}` : ''}`);
    const t = res.data?.track ?? null;
    // Day reads arrive as full timestamps — the editor works in bare dates.
    if (t && Array.isArray(t.dayStatuses)) {
      t.dayStatuses = t.dayStatuses.map((r) => ({ ...r, day: r.day.slice(0, 10) }));
    }
    setTrack(t);
    // The week arrives as one JSON string; the console edits it a day at a time,
    // so it is spread into `hoursWeek.<day>` keys and reassembled on save.
    const week = parseHoursWeek(t?.hoursWeek);
    setForm({
      description: t?.description ?? '',
      city: t?.city ?? '',
      region: t?.region ?? '',
      address: t?.address ?? '',
      hours: t?.hours ?? '',
      ...Object.fromEntries(
        HOURS_WEEK_DAYS.map(({ key }) => [`hoursWeek.${key}`, week?.[key] ?? ''])
      ),
      status: t?.status ?? 'OPEN',
      statusNote: t?.statusNote ?? '',
      riderMessage: t?.riderMessage ?? '',
      nextEvent: t?.nextEvent ?? '',
      website: t?.website ?? '',
      instagram: t?.instagram ?? '',
      facebook: t?.facebook ?? '',
      youtube: t?.youtube ?? '',
      tiktok: t?.tiktok ?? '',
      email: t?.email ?? '',
      phone: t?.phone ?? '',
    });
    setLoading(false);
  };

  useEffect(() => {
    if (isAdmin && !trackId) return;
    load(isAdmin ? trackId : '');
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isAdmin, trackId]);

  const set = (key: string, value: string) => setForm((f) => ({ ...f, [key]: value }));

  const saveProfile = async () => {
    setSaving(true);
    setMsg(null);
    const { hoursWeek: _week, ...fields } = form;
    const res = await api.patch<{ track: OwnerTrack }>('/owner/track', {
      ...fields,
      // A blank day saves as Closed; seven blank days clear the week entirely.
      hoursWeek: serializeHoursWeek(
        Object.fromEntries(HOURS_WEEK_DAYS.map(({ key }) => [key, form[`hoursWeek.${key}`] ?? '']))
      ),
      ...(isAdmin ? { trackId } : {}),
      bannerUrl: track?.bannerUrl ?? '',
      logoUrl: track?.logoUrl ?? '',
    });
    if (res.success && res.data?.track) {
      const saved = res.data.track;
      // Day reads arrive as full timestamps — the editor works in bare dates.
      if (Array.isArray(saved.dayStatuses)) {
        saved.dayStatuses = saved.dayStatuses.map((r) => ({ ...r, day: r.day.slice(0, 10) }));
      }
      setTrack((t) => (t ? { ...t, ...saved } : saved));
      // The saved week comes back normalized ('Closed', trimmed hours) — read it
      // back into the fields so the console shows what was stored, not what was typed.
      const week = parseHoursWeek(saved.hoursWeek);
      setForm((f) => ({
        ...f,
        ...Object.fromEntries(HOURS_WEEK_DAYS.map(({ key }) => [`hoursWeek.${key}`, week?.[key] ?? ''])),
      }));
      setMsg('Profile saved.');
    } else {
      setMsg(res.message);
    }
    setSaving(false);
  };

  /** Art saves on its own — the picker already has the URL when it changes. */
  const saveArt = async (kind: 'banner' | 'logo', url: string | null) => {
    setTrack((t) => (t ? { ...t, [`${kind}Url`]: url } : t));
    const res = await api.patch('/owner/track', {
      [kind === 'banner' ? 'bannerUrl' : 'logoUrl']: url ?? '',
      ...(isAdmin ? { trackId } : {}),
    });
    setMsg(res.success ? `${kind === 'banner' ? 'Banner' : 'Logo'} saved.` : res.message);
  };

  const preview = useMemo(
    () => (
      <div className="stack card profile-preview">
        <div className="profile-banner small">
          {track?.photos?.[0]?.url || track?.bannerUrl || track?.imageUrl ? (
            <img src={track.photos?.[0]?.url || track.bannerUrl || track.imageUrl || ''} alt="" />
          ) : (
            <div className="profile-banner-fallback" aria-hidden="true" />
          )}
        </div>
        <div className="row" style={{ gap: 12 }}>
          <TrackLogo name={track?.name ?? ''} logoUrl={track?.logoUrl} size={48} />
          <div className="stack">
            <b>{track?.name}</b>
            <span className="small muted">
              {([form.city, form.region].filter(Boolean).join(', ') || 'No location') +
                ' · ' +
                statusLabel(form.status || 'OPEN')}
            </span>
          </div>
        </div>
      </div>
    ),
    [track, form.city, form.region, form.status]
  );

  if (loading) return <div className="muted">Loading track…</div>;
  if (!track) {
    return (
      <div className="stack">
        <h1>Track profile</h1>
        <Banner tone="warn">
          No track is pinned to this account. Ask an admin to pin your operator account to a venue.
        </Banner>
      </div>
    );
  }

  return (
    <div className="stack">
      <div className="row spread wrap">
        <div>
          <h1>{track.name}</h1>
          <div className="small muted">
            This is the venue page riders see. Everything here is yours to keep current.
          </div>
        </div>
        <div className="row wrap">
          {isAdmin && (
            <select value={trackId} onChange={(e) => setTrackId(e.target.value)} style={{ minWidth: 200 }}>
              {trackList.map((t) => (
                <option key={t.id} value={t.id}>
                  {t.name}
                </option>
              ))}
            </select>
          )}
          <Link className="track-links-btn" to={`/tracks/${track.slug}`}>
            View public page
          </Link>
        </div>
      </div>

      {msg && <Banner tone="ok" close>{msg}</Banner>}

      <div className="profile-console">
        <div className="stack">
          <section className="card stack">
            <h3>Profile art</h3>
            <ImagePicker
              label="Banner"
              kind="banner"
              wide
              value={track.bannerUrl}
              trackId={isAdmin ? trackId : undefined}
              onChange={(url) => saveArt('banner', url)}
            />
            <ImagePicker
              label="Logo"
              kind="logo"
              value={track.logoUrl}
              trackId={isAdmin ? trackId : undefined}
              onChange={(url) => saveArt('logo', url)}
            />
          </section>

          <GalleryManager
            photos={track.photos ?? []}
            trackId={isAdmin ? trackId : undefined}
            onMessage={setMsg}
            onChange={(photos) => setTrack((t) => (t ? { ...t, photos } : t))}
          />

          <section className="card stack">
            <h3>About the venue</h3>
            <div>
              <label>Description</label>
              <textarea
                rows={4}
                value={form.description}
                onChange={(e) => set('description', e.target.value)}
                placeholder="What the track is, how many tracks it runs, who it suits."
              />
            </div>
            <div className="grid cols-2">
              <div>
                <label>City</label>
                <input value={form.city} onChange={(e) => set('city', e.target.value)} />
              </div>
              <div>
                <label>Region</label>
                <input value={form.region} onChange={(e) => set('region', e.target.value)} />
              </div>
            </div>
            <div>
              <label>Street address</label>
              <input
                value={form.address}
                onChange={(e) => set('address', e.target.value)}
                placeholder="2621 US-221, Union Mills, NC 28167"
              />
            </div>
            <div className="grid cols-2">
              <div>
                <label>Website</label>
                <input value={form.website} onChange={(e) => set('website', e.target.value)} placeholder="https://" />
              </div>
              <div>
                <label>Email</label>
                <input value={form.email} onChange={(e) => set('email', e.target.value)} />
              </div>
              <div>
                <label>Phone</label>
                <input value={form.phone} onChange={(e) => set('phone', e.target.value)} />
              </div>
            </div>
          </section>

          <section className="card stack">
            <h3>Social</h3>
            <div className="grid cols-2">
              {(
                [
                  ['instagram', 'Instagram'],
                  ['facebook', 'Facebook'],
                  ['youtube', 'YouTube'],
                  ['tiktok', 'TikTok'],
                ] as const
              ).map(([key, label]) => (
                <div key={key}>
                  <label>{label}</label>
                  <input
                    value={form[key]}
                    onChange={(e) => set(key, e.target.value)}
                    placeholder="https://"
                  />
                </div>
              ))}
            </div>
          </section>

          <section className="card stack">
            <h3>At the gate</h3>
            <div className="grid cols-2">
              <div>
                <label>Status</label>
                <select
                  aria-label="Status"
                  value={form.status}
                  onChange={(e) => set('status', e.target.value)}
                >
                  <option value="OPEN">Open</option>
                  <option value="WEATHER_HOLD">Caution</option>
                  <option value="CLOSED">Closed</option>
                </select>
              </div>
              <div>
                <label>Hours</label>
                <input value={form.hours} onChange={(e) => set('hours', e.target.value)} placeholder="Practice 9am–4pm" />
              </div>
              <div>
                <label>Now (status note)</label>
                <input
                  value={form.statusNote}
                  onChange={(e) => set('statusNote', e.target.value)}
                  placeholder="Rain overnight, so the gate opens once it dries"
                />
              </div>
              <div>
                <label>Next up</label>
                <input value={form.nextEvent} onChange={(e) => set('nextEvent', e.target.value)} />
              </div>
            </div>

            {/* The venue's own word to riders: a standing note that reads in the
                network page's panel, apart from today's gate line above. */}
            <div>
              <label>Message to riders</label>
              <textarea
                rows={3}
                value={form.riderMessage}
                onChange={(e) => set('riderMessage', e.target.value)}
                placeholder="Gate closes at 5. Park in the lower lot, not along the drive."
              />
            </div>

            {/* The gate per date — today, tomorrow, or any date picked. Days
                save on their own; the profile form below stays the live line. */}
            <DayStatusEditor
              trackId={isAdmin ? trackId : undefined}
              rows={track.dayStatuses ?? []}
              liveStatus={form.status || 'OPEN'}
              liveNote={form.statusNote || null}
              onChange={(rows) => setTrack((t) => (t ? { ...t, dayStatuses: rows } : t))}
              onMessage={setMsg}
            />

            {/* The week behind that Hours line — what the venue profile lays out,
                a day at a time. */}
            <div className="stack week-editor">
              <div className="small muted">
                The regular week, Mon to Sun. This is what the venue profile reads; the Hours line
                above stays the one-line summary. Leave a day blank for one the venue is shut.
              </div>
              <div className="grid cols-2">
                {HOURS_WEEK_DAYS.map(({ key, label }) => (
                  <div key={key}>
                    <label>{label}</label>
                    <input
                      value={form[`hoursWeek.${key}`] ?? ''}
                      onChange={(e) => set(`hoursWeek.${key}`, e.target.value)}
                      placeholder="9am–4pm"
                    />
                  </div>
                ))}
              </div>
            </div>
          </section>
        </div>

        <div className="stack">{preview}</div>
      </div>

      {/* The season as a rider reads it, in the band the venue page gives it:
          read-only here, with the calendar page a click away for every date. */}
      <section className="card stack">
        <div className="section-head">
          <h3>Schedule</h3>
          <div className="section-tools">
            <Link className="track-links-btn" to="/operator/calendar">
              Open calendar
            </Link>
          </div>
        </div>
        {track.events.length === 0 ? (
          <div className="small muted">No events yet. Open the calendar to post the season.</div>
        ) : (
          <EventCalendar
            events={track.events}
            renderAction={(ev) => (
              <Link className="track-links-btn" to={`/operator/calendar?event=${ev.id}`}>
                Edit
              </Link>
            )}
          />
        )}
      </section>

      <div className="row wrap profile-save">
        <button className="primary" onClick={saveProfile} disabled={saving}>
          {saving ? 'Saving…' : 'Save profile'}
        </button>
        <span className="tiny muted">
          Banner and logo save as soon as they change; the season is written on the calendar page.
          Everything else saves here.
        </span>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { api, dateTimeStr, dayStr, money, timeStr } from '../../lib/api';
import { reasonLabel } from '../../lib/reasonLabels';
import { useAuth } from '../../lib/auth';
import { SortTh, useSorted } from '../../components/sortable';
import TrackName from '../../components/TrackName';
import OperatorStats from '../../components/OperatorStats';

interface Redemption {
  id: string;
  riderName: string;
  riderEmail: string;
  trackName: string;
  trackWebsite: string | null;
  kind: string;
  day: string;
  redeemedAt: string;
  amountChargedCents: number;
}

interface ScanEvent {
  id: string;
  riderName: string | null;
  trackName: string;
  trackWebsite: string | null;
  result: 'APPROVED' | 'DENIED';
  reasonCode: string | null;
  reason: string | null;
  kind: string | null;
  createdAt: string;
}

/**
 * The venue's reports: the season's read, and one activity band that carries
 * today's check-ins, every scan and the denials together. Split off the
 * dashboard, which keeps the scanning station itself.
 */
export default function OperatorReports() {
  const { operatorTrack } = useAuth();
  const [redemptions, setRedemptions] = useState<Redemption[]>([]);
  const [scans, setScans] = useState<ScanEvent[]>([]);
  const [tab, setTab] = useState<'checkins' | 'scans' | 'denials'>('checkins');
  const [scope, setScope] = useState<'today' | 'season'>('today');
  const [logLoading, setLogLoading] = useState(true);
  // The server's own day key for today, read back with the log so the activity
  // filter lines up with the server's counts.
  const [today, setToday] = useState<string>('');

  const query = operatorTrack ? `?trackId=${operatorTrack.id}` : '';

  const load = useCallback(async () => {
    const l = await api.get<{ date: string; redemptions: Redemption[]; scans: ScanEvent[] }>(
      `/operator/log${query}`
    );
    if (l.data?.date) setToday(dayStr(l.data.date));
    setRedemptions(l.data?.redemptions ?? []);
    setScans(l.data?.scans ?? []);
    setLogLoading(false);
  }, [query]);

  useEffect(() => {
    load();
  }, [load]);

  const todayKey = today || dayStr(new Date());
  const scopedReds = useMemo(
    () => (scope === 'today' ? redemptions.filter((r) => dayStr(r.day) === todayKey) : redemptions),
    [redemptions, scope, todayKey]
  );
  const scopedScans = useMemo(
    () => (scope === 'today' ? scans.filter((s) => dayStr(s.createdAt) === todayKey) : scans),
    [scans, scope, todayKey]
  );
  // Admins without a track see every venue's log; the track column only earns
  // its width when more than one track is actually in the rows.
  const redsMultiTrack = useMemo(
    () => new Set(scopedReds.map((r) => r.trackName)).size > 1,
    [scopedReds]
  );
  const scansMultiTrack = useMemo(
    () => new Set(scopedScans.map((s) => s.trackName)).size > 1,
    [scopedScans]
  );

  const { sorted: reds, sort: sortReds, toggle: toggleReds } = useSorted(scopedReds, {
    day: (r) => r.day,
    rider: (r) => r.riderName,
    track: (r) => r.trackName,
    paid: (r) => r.amountChargedCents,
    redeemed: (r) => r.redeemedAt,
  });
  const { sorted: scanRows, sort: sortScans, toggle: toggleScans } = useSorted(scopedScans, {
    when: (s) => s.createdAt,
    rider: (s) => s.riderName,
    track: (s) => s.trackName,
    result: (s) => s.result,
    reason: (s) => s.reason,
  });
  // Denials are the scan ledger's DENIED rows, so the tab narrows the same read
  // the All scans tab lists rather than asking the server for a second shape.
  const deniedScans = useMemo(() => scanRows.filter((s) => s.result === 'DENIED'), [scanRows]);

  const shownCount =
    tab === 'checkins' ? reds.length : tab === 'denials' ? deniedScans.length : scanRows.length;

  return (
    <div className="stack">
      <OperatorStats trackId={operatorTrack?.id} />

      <div className="table-block">
        <div className="table-head">
          <div className="row wrap">
            <h3>Activity</h3>
            <span className="tiny muted">{shownCount}</span>
          </div>
          <div className="row wrap" style={{ gap: 12 }}>
            <div className="pill-toggle">
              <button aria-pressed={scope === 'today'} onClick={() => setScope('today')}>
                Today
              </button>
              <button aria-pressed={scope === 'season'} onClick={() => setScope('season')}>
                Season
              </button>
            </div>
            <div className="pill-toggle">
              <button aria-pressed={tab === 'checkins'} onClick={() => setTab('checkins')}>
                Check-ins
              </button>
              <button aria-pressed={tab === 'scans'} onClick={() => setTab('scans')}>
                All scans
              </button>
              <button aria-pressed={tab === 'denials'} onClick={() => setTab('denials')}>
                Denials
              </button>
            </div>
          </div>
        </div>

        <div className="card" style={{ padding: 0 }}>
          <div className="table-scroll">
            {logLoading ? (
              <div className="muted small" style={{ padding: 16 }}>
                Loading log…
              </div>
            ) : tab === 'checkins' ? (
              <table>
                <thead>
                  <tr>
                    {scope === 'season' && (
                      <SortTh sortKey="day" sort={sortReds} onSort={toggleReds}>Day</SortTh>
                    )}
                    <SortTh sortKey="rider" sort={sortReds} onSort={toggleReds}>Rider</SortTh>
                    {redsMultiTrack && (
                      <SortTh sortKey="track" sort={sortReds} onSort={toggleReds}>Track</SortTh>
                    )}
                    <SortTh sortKey="paid" sort={sortReds} onSort={toggleReds} className="right">Paid</SortTh>
                    <SortTh sortKey="redeemed" sort={sortReds} onSort={toggleReds}>Time</SortTh>
                  </tr>
                </thead>
                <tbody>
                  {reds.map((r) => (
                    <tr key={r.id}>
                      {scope === 'season' && <td>{dayStr(r.day)}</td>}
                      <td>
                        <div>{r.riderName}</div>
                        <div className="tiny muted">{r.riderEmail}</div>
                      </td>
                      {redsMultiTrack && (
                        <td className="small muted">
                          <TrackName name={r.trackName} website={r.trackWebsite} />
                        </td>
                      )}
                      <td className="right">{r.amountChargedCents ? money(r.amountChargedCents) : '—'}</td>
                      <td className="small muted">
                        {scope === 'season' ? dateTimeStr(r.redeemedAt) : timeStr(r.redeemedAt)}
                      </td>
                    </tr>
                  ))}
                  {!reds.length && (
                    <tr>
                      <td
                        colSpan={3 + (scope === 'season' ? 1 : 0) + (redsMultiTrack ? 1 : 0)}
                        className="muted small"
                      >
                        {scope === 'today' ? 'No check-ins yet today.' : 'No check-ins yet.'}
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            ) : tab === 'scans' ? (
              <table>
                <thead>
                  <tr>
                    <SortTh sortKey="when" sort={sortScans} onSort={toggleScans}>When</SortTh>
                    <SortTh sortKey="rider" sort={sortScans} onSort={toggleScans}>Rider</SortTh>
                    {scansMultiTrack && (
                      <SortTh sortKey="track" sort={sortScans} onSort={toggleScans}>Track</SortTh>
                    )}
                    <SortTh sortKey="result" sort={sortScans} onSort={toggleScans}>Result</SortTh>
                    <SortTh sortKey="reason" sort={sortScans} onSort={toggleScans}>Reason</SortTh>
                  </tr>
                </thead>
                <tbody>
                  {scanRows.map((s) => (
                    <tr key={s.id}>
                      <td className="small muted">{dateTimeStr(s.createdAt)}</td>
                      <td>{s.riderName ?? '—'}</td>
                      {scansMultiTrack && (
                        <td className="small muted">
                          <TrackName name={s.trackName} website={s.trackWebsite} />
                        </td>
                      )}
                      <td>
                        <span className={`pill ${s.result === 'APPROVED' ? 'ok' : 'bad'}`}>{s.result}</span>
                      </td>
                      <td className="small muted">
                        {s.reason || reasonLabel(s.reasonCode) || '—'}
                      </td>
                    </tr>
                  ))}
                  {!scanRows.length && (
                    <tr>
                      <td colSpan={scansMultiTrack ? 5 : 4} className="muted small">
                        {scope === 'today' ? 'No scans today.' : 'No scan events yet.'}
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            ) : (
              <table>
                <thead>
                  <tr>
                    <SortTh sortKey="when" sort={sortScans} onSort={toggleScans}>When</SortTh>
                    <SortTh sortKey="rider" sort={sortScans} onSort={toggleScans}>Rider</SortTh>
                    {scansMultiTrack && (
                      <SortTh sortKey="track" sort={sortScans} onSort={toggleScans}>Track</SortTh>
                    )}
                    <SortTh sortKey="reason" sort={sortScans} onSort={toggleScans}>Reason</SortTh>
                  </tr>
                </thead>
                <tbody>
                  {deniedScans.map((s) => (
                    <tr key={s.id}>
                      <td className="small muted">{dateTimeStr(s.createdAt)}</td>
                      <td>{s.riderName ?? '—'}</td>
                      {scansMultiTrack && (
                        <td className="small muted">
                          <TrackName name={s.trackName} website={s.trackWebsite} />
                        </td>
                      )}
                      <td>
                        {s.reason || reasonLabel(s.reasonCode) || '—'}
                      </td>
                    </tr>
                  ))}
                  {!deniedScans.length && (
                    <tr>
                      <td colSpan={scansMultiTrack ? 4 : 3} className="muted small">
                        {scope === 'today' ? 'Nothing turned away today.' : 'Nothing turned away yet.'}
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useState } from 'react';
import Banner from '../components/Banner';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
import { api, money } from '../lib/api';
import { useAuth } from '../lib/auth';
import { PARTNER_AUDIENCE_ENABLED } from '../lib/featureFlags';

interface Tier {
  id: string;
  slug: string;
  name: string;
  tagline: string | null;
  description: string | null;
  priceCents: number;
  /** The monthly alternative to the annual price — display only. */
  monthlyPriceCents: number | null;
  earlyBirdPriceCents: number | null;
  earlyBirdStartsAt: string | null;
  earlyBirdEndsAt: string | null;
  twoYearPriceCents: number | null;
  extraDaysPerTrack: number;
  /** The free default a new account lands on. */
  isDefault: boolean;
}

interface TrackLite {
  includedDays: number;
  discountDayEnabled: boolean;
  discountRate: number | null;
  reservationRequired: boolean;
}

type Audience = 'riders' | 'tracks';

/** Whole-dollar label for the headline price; falls back to cents when needed. */
function priceLabel(cents: number): string {
  return Number.isInteger(cents / 100) ? `$${cents / 100}` : money(cents);
}

function Check() {
  return (
    <svg
      width="16"
      height="16"
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      <path d="M3.5 8.5 6.5 11.5 12.5 4.5" />
    </svg>
  );
}

/** Bullets each tier adds on top of the one below it. */
const ADDED: Record<string, string[]> = {
  free: [
    'Every partner track, with its live status and hours',
    'Follow the tracks you ride, and unfollow any time',
    'Upgrade mid-season, with the days applying right away',
  ],
  base: [
    '2 included days at every partner track',
    'A third day at half price where the track offers one',
    'Advance reservations where a track requires them',
  ],
};

/** The levers a partner track sets in its own contract. */
const CONTROLS: { term: string; def: string }[] = [
  { term: 'Included days per pass', def: 'Per contract, per season.' },
  { term: 'Discounted extra day', def: 'Which day, and the rate.' },
  { term: 'Extra-day price', def: 'Your sticker price before discount.' },
  { term: 'Reservation rule', def: 'Walk-up, or book ahead.' },
  { term: 'When the day is spent', def: 'At booking, at check-in, or never.' },
];

/** The checks the server walks, in order, on every scan. */
const SCAN_ORDER = [
  'Code signature valid',
  'Code not expired',
  'Pass belongs to the rider',
  'Pass active and in season',
  'Not already redeemed here today',
  'Your track participates',
  'Your reservation rule met',
  'Free day, then discounted, then out of days',
];

export default function Pricing() {
  const [tiers, setTiers] = useState<Tier[]>([]);
  const [tracks, setTracks] = useState<TrackLite[]>([]);
  // `?for=tracks` opens straight on the partner sheet, so a track arriving from
  // the landing page's invitation doesn't land on the rider tiers first.
  const [params] = useSearchParams();
  const [audience, setAudience] = useState<Audience>(
    params.get('for') === 'tracks' ? 'tracks' : 'riders',
  );
  // Annual or monthly headline price on the rider cards; annual is the saving.
  const [billing, setBilling] = useState<'annual' | 'monthly'>('annual');
  const [busy, setBusy] = useState<string | null>(null);
  const [note, setNote] = useState<string | null>(null);
  const { user } = useAuth();
  const navigate = useNavigate();

  useEffect(() => {
    api.get<{ tiers: Tier[] }>('/tiers').then((r) => setTiers(r.data?.tiers ?? []));
    // `terms=public`: this page's figures are the anonymous marketing copy, so
    // a free-tier rider reading it still sees the full day totals.
    api.get<{ tracks: TrackLite[] }>('/tracks?terms=public').then((r) => setTracks(r.data?.tracks ?? []));
  }, []);

  const buy = async (tier: Tier) => {
    // The free tier is granted at sign-up, never bought.
    if (tier.isDefault) return navigate(user ? '/tracks' : '/login');
    if (!user) return navigate('/login', { state: { from: '/pricing' } });
    setBusy(tier.id);
    setNote(null);
    const res = await api.post<{
      url?: string;
      devMode?: boolean;
      paymentId?: string;
      message?: string;
    }>('/payments/checkout', { tierId: tier.id });
    setBusy(null);
    if (!res.success) return setNote(res.message);
    const d = res.data;
    if (d?.url) {
      window.location.href = d.url;
      return;
    }
    if (d?.devMode && d.paymentId) {
      const sim = await api.post(`/payments/dev/simulate/${d.paymentId}`);
      setNote(sim.message);
      if (sim.success) setTimeout(() => navigate('/tracks'), 900);
      return;
    }
    setNote(res.message);
  };

  const sellable = tiers;

  /**
   * Rideable days for one tier: the sum of the included days at every partner
   * track, plus its extra days at each of them.
   */
  const daysFor = (t: Tier) =>
    tracks.reduce((sum, x) => sum + (x.includedDays ?? 0), 0) + t.extraDaysPerTrack * tracks.length;

  /** Whether the presale rate is live right now. */
  const presaleActive = (t: Tier) =>
    t.earlyBirdPriceCents != null &&
    (!t.earlyBirdStartsAt || new Date(t.earlyBirdStartsAt) <= new Date()) &&
    (!t.earlyBirdEndsAt || new Date(t.earlyBirdEndsAt) > new Date());

  /** Whether the presale is announced but not open yet. */
  const presaleUpcoming = (t: Tier) =>
    t.earlyBirdPriceCents != null &&
    t.earlyBirdStartsAt != null &&
    new Date(t.earlyBirdStartsAt) > new Date();

  /** The headline annual price a rider pays now — the presale rate while it runs. */
  const annualPrice = (t: Tier) => (presaleActive(t) ? t.earlyBirdPriceCents! : t.priceCents);

  /**
   * What the billing pill names on its Annual side: the saving the annual price
   * carries against twelve monthly payments, counted off the one paid tier that
   * sells monthly (never hard-coded — the pill follows the contracts).
   */
  const annualSavePct = (() => {
    const t = sellable.find((x) => !x.isDefault && x.monthlyPriceCents != null);
    if (!t) return 0;
    const year = t.monthlyPriceCents! * 12;
    const pct = Math.round((1 - annualPrice(t) / year) * 100);
    return pct > 0 ? pct : 0;
  })();

  /**
   * One row per capability, one column per plan — every capability that differs
   * between the plans and every one they share, so the table is the whole pass
   * model rather than a highlights reel. `true` draws the mark, `false` the
   * quiet dash, a string is the value the plan actually carries. Listed in the
   * order the table reads below: shared rows first, then the deltas.
   */
  const compareRows: { label: string; cell: (t: Tier) => boolean | string }[] = [
    { label: 'Price per year', cell: (t) => (t.isDefault ? 'Free' : priceLabel(annualPrice(t))) },
    { label: 'Rideable days across the network', cell: (t) => (t.isDefault ? '0' : String(daysFor(t))) },
    { label: 'Included days at every track', cell: (t) => !t.isDefault },
    { label: 'Member price on extra days', cell: (t) => !t.isDefault },
    { label: 'Advance reservations where required', cell: (t) => !t.isDefault },
    {
      label: 'Extra days at every track',
      cell: (t) => (t.extraDaysPerTrack > 0 ? `+${t.extraDaysPerTrack}` : false),
    },
    { label: 'Live venue status and hours', cell: () => true },
    { label: 'Follow the tracks you ride', cell: () => true },
  ];

  /**
   * The rows every plan carries a mark on lead the table: what the pass always
   * gives sits above what the higher plans add. Derived from the live plans and
   * the capabilities themselves, so it holds when either changes.
   */
  const markedByEveryPlan = (row: { cell: (t: Tier) => boolean | string }) =>
    sellable.length > 0 && sellable.every((t) => row.cell(t) === true);
  const orderedCompareRows = [
    ...compareRows.filter(markedByEveryPlan),
    ...compareRows.filter((row) => !markedByEveryPlan(row)),
  ];

  /** Live figures quoted in the partner notes — never hard-coded. */
  const network = useMemo(() => {
    const count = tracks.length;
    const days = tracks.map((t) => t.includedDays);
    const rates = tracks
      .filter((t) => t.discountDayEnabled && t.discountRate != null)
      .map((t) => Math.round((t.discountRate ?? 0) * 100));
    const reserving = tracks.filter((t) => t.reservationRequired).length;
    return {
      count,
      reserving,
      dayMin: count ? Math.min(...days) : null,
      dayMax: count ? Math.max(...days) : null,
      rateMin: rates.length ? Math.min(...rates) : null,
      rateMax: rates.length ? Math.max(...rates) : null,
    };
  }, [tracks]);

  const controlRows = CONTROLS.map((row) => {
    if (row.term === 'Included days per pass' && network.dayMin != null) {
      return {
        ...row,
        def: `${row.def} ${network.dayMin} to ${network.dayMax} across the network.`,
      };
    }
    if (row.term === 'Discounted extra day' && network.rateMin != null) {
      const range =
        network.rateMin === network.rateMax
          ? `${network.rateMin}%`
          : `${network.rateMin}% to ${network.rateMax}%`;
      return { ...row, def: `${row.def} ${range} off today.` };
    }
    if (row.term === 'Reservation rule' && network.count > 0) {
      return {
        ...row,
        def: `${row.def} ${network.reserving} of ${network.count} tracks require one.`,
      };
    }
    return row;
  });

  const gives: { term: string; def: string }[] = [
    { term: 'Gate station', def: "Scan, today's check-ins, and the attempt log." },
    { term: 'Reporting', def: 'Per-track redemptions and revenue; QuickBooks CSV or JSON.' },
    { term: 'Frozen counts', def: 'Rider days snapshot at activation; changes need a re-snapshot.' },
  ];

  const forTracks = audience === 'tracks';

  return (
    <div className="stack">
      <section className="pricing-band">
        <h1>{forTracks ? 'For partner tracks' : 'Pick your pass'}</h1>
        <p className="lede">
          {forTracks
            ? 'Brings riders to your gate, on terms you set.'
            : 'The free pass covers the network: every track, its live status, and the tracks you follow. The Moto Pass adds the included days at each track and member pricing once those run out.'}
        </p>

        {PARTNER_AUDIENCE_ENABLED && (
          <div className="pill-toggle" role="group" aria-label="Who this page is for">
            <button aria-pressed={!forTracks} onClick={() => setAudience('riders')}>
              Riders
            </button>
            <button aria-pressed={forTracks} onClick={() => setAudience('tracks')}>
              Tracks
            </button>
          </div>
        )}
      </section>

      {forTracks ? (
        <>
          <section className="card track-sheet">
            <p className="sheet-lead">You collect the member price at the window.</p>

            <div className="sheet-cols">
              <div className="sheet-col">
                <section>
                  <h2>What you control</h2>
                  <dl className="spec-list">
                    {controlRows.map((row) => (
                      <div key={row.term}>
                        <dt>{row.term}</dt>
                        <dd>{row.def}</dd>
                      </div>
                    ))}
                  </dl>
                </section>

                <section>
                  <h2>What you get</h2>
                  <dl className="spec-list">
                    {gives.map((row) => (
                      <div key={row.term}>
                        <dt>{row.term}</dt>
                        <dd>{row.def}</dd>
                      </div>
                    ))}
                  </dl>
                </section>
              </div>

              <section>
                <h2>What the station checks</h2>
                <p className="note">In this order, every scan.</p>
                <ol className="step-list">
                  {SCAN_ORDER.map((step, i) => (
                    <li key={step}>
                      <span className="n" aria-hidden="true">
                        {i + 1}
                      </span>
                      {step}
                    </li>
                  ))}
                </ol>
              </section>
            </div>
          </section>

          <div className="row wrap">
            <Link to="/tracks">
              <button className="ghost">See the network</button>
            </Link>
            <Link to="/login">
              <button className="ghost">Operator sign in</button>
            </Link>
          </div>
        </>
      ) : (
        <>
          {/* The billing term reads as a switch: one label either side of a
              track, the thumb sitting on the term in force. Annual leads on the
              right because it is the default and the saving. */}
          <div className="billing-toggle billing-switch" role="group" aria-label="Billing period">
            <button
              className="bs-opt"
              aria-pressed={billing === 'monthly'}
              onClick={() => setBilling('monthly')}
            >
              <span className="pill-label">Monthly</span>
            </button>
            {/* The track is a real control too: a switch that flips the term,
                so pointing at the thing that *shows* the state also moves it. */}
            <button
              type="button"
              className="bs-track"
              role="switch"
              aria-checked={billing === 'annual'}
              aria-label="Bill annually"
              data-side={billing}
              onClick={() => setBilling(billing === 'annual' ? 'monthly' : 'annual')}
            >
              <span className="bs-thumb" aria-hidden="true" />
            </button>
            <button
              className="bs-opt"
              aria-pressed={billing === 'annual'}
              onClick={() => setBilling('annual')}
            >
              <span className="pill-label">Annual</span>
              {annualSavePct > 0 && <span className="pill-save">Save {annualSavePct}%</span>}
            </button>
          </div>

          <div className="pricing-grid">
            {sellable.map((t) => {
              const earlyActive = presaleActive(t);
              const upcoming = presaleUpcoming(t);
              const popular = t.slug === 'base';
              const monthly = billing === 'monthly' && !t.isDefault && t.monthlyPriceCents != null;
              const priceCents = monthly ? t.monthlyPriceCents! : annualPrice(t);
              const annualSaving =
                !t.isDefault && t.monthlyPriceCents != null ? t.monthlyPriceCents * 12 - t.priceCents : 0;
              const added = ADDED[t.slug] ?? [];
              const lowerTier = sellable[sellable.indexOf(t) - 1];
              const baseName = lowerTier?.name.replace(/\s*Pass$/, '');
              const freeTier = t.isDefault;

              return (
                <div
                  className={popular ? 'tier-card popular' : freeTier ? 'tier-card free' : 'tier-card'}
                  key={t.id}
                >
                  <div className="tier-body">
                    <div className="tier-head">
                      <h2>{t.name}</h2>
                      <p className="tier-audience">{t.description}</p>
                    </div>

                    <div className="tier-price">
                      <div className="price-row">
                        <span className="amount">{freeTier ? 'Free' : priceLabel(priceCents)}</span>
                        <span className="unit">{monthly ? 'per month' : 'per year'}</span>
                      </div>
                      {!freeTier && earlyActive && !monthly && (
                        <div className="unit">
                          <span className="ok">Presale, 25% off</span>. Was {priceLabel(t.priceCents)}
                        </div>
                      )}
                      {!freeTier && upcoming && !monthly && (
                        <div className="unit">Presale Nov 16, 25% off. Full price Dec 2.</div>
                      )}
                      {!freeTier && monthly && annualSaving > 0 && (
                        <div className="unit">
                          <span className="ok">Annual saves {priceLabel(annualSaving)}</span> a year
                        </div>
                      )}
                      <div className="capacity">
                        {freeTier
                          ? 'The network, with no included days'
                          : `${daysFor(t)} rideable days across the network`}
                      </div>
                    </div>

                    <button
                      className={popular && !freeTier ? 'primary tier-cta' : 'ghost tier-cta'}
                      disabled={busy === t.id}
                      onClick={() => buy(t)}
                    >
                      {busy === t.id
                        ? 'Starting checkout…'
                        : freeTier
                          ? user && user.role === 'RIDER'
                            ? 'Go to my pass'
                            : 'Create free account'
                          : 'Buy pass'}
                    </button>

                    {/* The rule the reference draws between the action and the
                        list: the button belongs to the price above it, the
                        bullets to the label below it. */}
                    <div className="tier-rule" aria-hidden="true" />

                    <div className="tier-includes">
                      {baseName ? `Everything in ${baseName} +` : 'Free plan includes:'}
                    </div>

                    <ul className="tier-list">
                      {added.map((item) => (
                        <li key={item}>
                          <span className="tick" aria-hidden="true">
                            <Check />
                          </span>
                          <span>{item}</span>
                        </li>
                      ))}
                    </ul>
                  </div>
                </div>
              );
            })}
          </div>

          <section className="compare-block">
            <h2>Compare</h2>
            <div className="table-scroll">
              <table className="compare-table">
                <thead>
                  <tr>
                    <th scope="col">Capability</th>
                    {sellable.map((t) => (
                      <th scope="col" key={t.id}>
                        {t.name}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {orderedCompareRows.map((row) => (
                    <tr key={row.label}>
                      <th scope="row">{row.label}</th>
                      {sellable.map((t) => {
                        const v = row.cell(t);
                        return (
                          <td key={t.id}>
                            {v === true ? (
                              <Check />
                            ) : v === false ? (
                              <span className="cmp-none" aria-label="Not included">
                                —
                              </span>
                            ) : (
                              <span className="cmp-val">{v}</span>
                            )}
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>

          {note && <Banner tone="warn" close>{note}</Banner>}

          <p className="small muted">
            Discounted extra days are paid at the track when you ride; the pass only validates
            eligibility and records the redemption.
          </p>
        </>
      )}
    </div>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import { api } from '../../lib/api';
import type { ProfileEvent } from '../../lib/events';
import { ampmLabel, dayKey, dayRange, daysOf, stepWeek, weekStart } from '../../lib/events';
import WeekGrid from '../../components/WeekGrid';
import EventReadSheet from '../../components/EventReadSheet';

/** A track the account follows, as `/me/calendar` serves it. */
interface FollowLite {
  trackId: string;
  slug: string;
  name: string;
  city: string | null;
  region: string | null;
  status: string;
  statusNote: string | null;
  hours: string | null;
  nextEvent: string | null;
  followedAt: string;
}

/** A date at a followed track — the venue rides on it, so a week of several
 *  tracks still reads which venue each date is at. */
interface RiderEvent extends ProfileEvent {
  trackId: string;
  trackSlug: string;
  trackName: string;
  trackCategory: string | null;
}

const DAY_FMT: Intl.DateTimeFormatOptions = {
  weekday: 'short',
  month: 'short',
  day: 'numeric',
  timeZone: 'UTC',
};

/**
 * The rider's calendar: the dates at the tracks this account follows, read as
 * the venue's own week.
 *
 * It reads exactly the way the owner's calendar page reads — the same week,
 * the same hour grid, the same cards under the same month heading — and it is
 * the same shell deliberately: what a rider sees of a season should not be a
 * second design. What it does not carry is the editor: no Add Event, no sheet
 * behind a card, no hour of the week that takes a mark. Following is the whole
 * of a free-tier account's surface, so this page comes with the free tier.
 *
 * A week here holds more than one venue, so every chip and every card names
 * the track it is at.
 */
export default function RiderCalendar() {
  const [follows, setFollows] = useState<FollowLite[]>([]);
  const [events, setEvents] = useState<RiderEvent[]>([]);
  const [loading, setLoading] = useState(true);
  /** The track filter, when there is more than one to filter between. */
  const [trackId, setTrackId] = useState('');

  useEffect(() => {
    let live = true;
    api
      .get<{ follows: FollowLite[]; events: RiderEvent[] }>('/me/calendar')
      .then((r) => {
        if (!live) return;
        setFollows(r.data?.follows ?? []);
        setEvents(r.data?.events ?? []);
      })
      .finally(() => live && setLoading(false));
    return () => {
      live = false;
    };
  }, []);

  const shown = useMemo(
    () => (trackId ? events.filter((e) => e.trackId === trackId) : events),
    [events, trackId]
  );

  if (loading) return <div className="stack cal-page"><div className="muted">Loading calendar…</div></div>;

  return (
    <div className="stack cal-page rider-cal">
      <div className="row spread wrap cal-top">
        <div className="cal-title-spacer" aria-hidden="true" />
        {follows.length > 1 && (
          <div className="row wrap">
            <select
              value={trackId}
              onChange={(e) => setTrackId(e.target.value)}
              style={{ minWidth: 200 }}
              aria-label="Which followed tracks to show"
            >
              <option value="">All tracks</option>
              {follows.map((f) => (
                <option key={f.trackId} value={f.trackId}>
                  {f.name}
                </option>
              ))}
            </select>
          </div>
        )}
      </div>

      {/* The week is the page, so it is drawn whether or not a date lands on
          it: a rider who follows nothing still reads a season, with the prompt
          to fill it in the column beside it. The filter is a different
          calendar, not a narrower list — `key` re-opens the week on the next
          date of what it is now showing. */}
      <RiderWeek key={trackId || 'all'} events={shown} empty={follows.length === 0} />
    </div>
  );
}

/**
 * One week of the read, with that month's dates beside it — the owner's page
 * with the editor taken out. It keeps the week, the page's own month and the
 * picked day, and nothing else: the week cannot be written, so there is no
 * slot to hold — every chip and every card only opens the date it draws, as a
 * read.
 *
 * It draws even with nothing in it — an account that follows no track still
 * gets the month, the week and the column, and the column carries the one
 * control that fills them (`empty`).
 */
function RiderWeek({ events, empty = false }: { events: RiderEvent[]; empty?: boolean }) {
  const today = dayKey(new Date().toISOString());

  // Open on the week of the next date ahead — the week a rider is most likely
  // to be looking at — or on this one when the tracks have nothing coming.
  const open = useMemo(() => {
    const next = events.find((e) => dayKey(e.startsAt) >= today);
    return dayKey(next ? next.startsAt : new Date().toISOString());
  }, [events, today]);

  const [anchor, setAnchor] = useState(open);
  const [picked, setPicked] = useState<string | null>(null);
  const [focusId, setFocusId] = useState<string | null>(null);
  /** The date whose sheet is open, read-only: a rider reads, and nothing here
   *  writes, so the sheet behind a card is the owner's with the editor gone. */
  const [openEvent, setOpenEvent] = useState<RiderEvent | null>(null);

  /** Every day the season covers, so a run that began last week still marks
   *  its days on this week's grid. */
  const byDay = useMemo(() => {
    const map = new Map<string, RiderEvent[]>();
    for (const ev of events) {
      for (const k of daysOf(ev)) {
        const list = map.get(k);
        if (list) list.push(ev);
        else map.set(k, [ev]);
      }
    }
    return map;
  }, [events]);

  const monday = weekStart(anchor);
  const month = anchor.slice(0, 7);
  const inMonth = useMemo(
    () => events.filter((e) => dayKey(e.startsAt).startsWith(month)),
    [events, month]
  );
  /** A picked day narrows the cards to the dates that cover it — read off
   *  every date, not the month's. */
  const shown = useMemo(
    () => (picked ? events.filter((e) => daysOf(e).includes(picked)) : inMonth),
    [picked, events, inMonth]
  );

  const monthLabel = new Date(`${anchor}T12:00:00Z`).toLocaleDateString(undefined, {
    month: 'long',
    year: 'numeric',
    timeZone: 'UTC',
  });
  const pickedLabel = picked ? new Date(`${picked}T12:00:00Z`).toLocaleDateString(undefined, DAY_FMT) : '';

  const step = (weeks: number) => {
    setAnchor((a) => stepWeek(a, weeks));
    setPicked(null);
    setFocusId(null);
  };

  const goToday = () => {
    setAnchor(today);
    setPicked(null);
    setFocusId(null);
  };

  /** A second pick on the same day puts it down again; a day pick rings the
   *  first card on it, the way the owner's own page does. */
  function pickDay(day: string) {
    if (day === picked) {
      setPicked(null);
      setFocusId(null);
      return;
    }
    setPicked(day);
    setFocusId((byDay.get(day) ?? [])[0]?.id ?? null);
  }

  /** A chip is the date it draws, so a click opens that date's own read —
   *  the same sheet the card's cover opens — and the month's cards stay put,
   *  exactly as they read on the owner's own calendar. The chip carries the
   *  shared shape, not this page's row, so the id lookup is what keeps the
   *  sheet on a card the page knows (and the venue the sheet names). */
  const pickEvent = (ev: ProfileEvent) => {
    const full = events.find((e) => e.id === ev.id);
    if (full) setOpenEvent(full);
  };

  return (
    <div className="cal-editor" data-week={monday} data-month={month}>
      {/* The month's dates on the left, the week they sit in on the right —
          the two read together, exactly as they do for the venue's owner. */}
      <div className="stack event-editor">
        <div className="row spread wrap event-list-head">
          <span className="row event-list-title">
            <b className="small">{monthLabel}</b>
            {!picked && <span className="tiny muted">{shown.length} dates</span>}
          </span>
          {picked && (
            <div className="event-filter">
              <span className="small event-filter-day">{pickedLabel}</span>
              <button
                className="ghost small"
                onClick={() => {
                  setPicked(null);
                  setFocusId(null);
                }}
              >
                Show all events
              </button>
            </div>
          )}
        </div>

        {/* Nothing to list is not nothing to say: an account that follows no
            track gets the prompt to follow one, in the column it would
            otherwise fill with cards. */}
        {shown.length === 0 &&
          (empty ? (
            <div className="rider-cal-empty">
              <b>No tracks followed yet</b>
              <p className="small muted">
                Follow a track on the network page and its dates land here.
              </p>
              <Link to="/tracks">
                <button className="primary small">Browse the network</button>
              </Link>
            </div>
          ) : (
            <div className="small muted">
              {picked
                ? 'Nothing from your tracks on this date. Show all events puts the month back.'
                : 'Nothing from your tracks this month.'}
            </div>
          ))}

        {shown.map((ev) => {
          const hours = ampmLabel(ev);
          return (
            <div
              key={ev.id}
              className={['event-edit-row', 'is-read', focusId === ev.id ? 'is-focused' : '']
                .filter(Boolean)
                .join(' ')}
            >
              {/* The card is the venue's, then what is on, and the card is
                  the control: where the owner's card opens the editor, this
                  one opens the same sheet with nothing left to write. The
                  venue keeps its own way out to the track. */}
              <button
                type="button"
                className="event-open"
                aria-label={`View ${ev.title}`}
                onClick={() => setOpenEvent(ev)}
              />
              <Link className="event-card-venue" to={`/tracks/${ev.trackSlug}`}>
                {ev.trackName}
              </Link>
              <div className="row wrap event-title-row">
                <h4 className="event-card-title">{ev.title}</h4>
              </div>
              <div className="small muted event-card-when">
                {dayRange(ev)}
                {hours && <span className="event-card-hours"> · {hours}</span>}
              </div>
            </div>
          );
        })}
      </div>

      <WeekGrid
        events={events}
        anchor={anchor}
        today={today}
        picked={picked}
        onStep={step}
        onToday={goToday}
        onPickDay={pickDay}
        onPickEvent={pickEvent}
        venueOf={(ev) => (ev as RiderEvent).trackName}
      />

      {/* The date a rider opened, read-only — the owner's sheet, without the
          editor: no field posts from here, so the sheet is all read. */}
      {openEvent && (
        <EventReadSheet
          event={openEvent}
          venue={{ name: openEvent.trackName, slug: openEvent.trackSlug }}
          onClose={() => setOpenEvent(null)}
        />
      )}
    </div>
  );
}

