import { Suspense, lazy, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import Banner from '../../components/Banner';
import { Link, useSearchParams } from 'react-router-dom';
import { api } from '../../lib/api';
import { useAuth } from '../../lib/auth';
import DaysByTrack, { type Entitlement, type RailView } from '../../components/DaysByTrack';
import TrackPanel from '../../components/TrackPanel';
import { useNetworkSearch } from '../../lib/networkSearch';
import type { TrackPerk } from '../../lib/trackOffers';
import type { Entitlement as MapEntitlement } from '../../lib/trackAccess';

/** Leaflet is heavy: load it with the map it belongs to. */
const RiderTrackMap = lazy(() => import('../../components/RiderTrackMap'));

/**
 * The warn notice floats over the network as a toast and retires itself after
 * this; its × dismisses it sooner. Long enough to read the two links it offers.
 */
const WARN_TOAST_MS = 8000;

interface PassInfo {
  id: string;
  status: string;
  seasonYear: number;
  tier: { name: string; slug: string; isDefault: boolean };
  activatedAt: string | null;
  expiresAt: string;
  daysUntilExpiry: number;
  /** True on the free tier: the network, the statuses and the follows list. */
  gated: boolean;
}

/**
 * The network page, at `/tracks`, for everyone. The map and the rail of every
 * partner track are public — a visitor reads each venue's live status — while
 * the pass's own terms (days left, discounts, offers) are what a signed-in
 * rider adds to them. Following and booking are the signed-in-only parts.
 *
 * The map owns the viewport: the rail of venues floats over its left edge and
 * never unmounts, and a pick — from a row or from a pin — opens the venue's
 * inspector over its right edge, so inspecting a venue never costs the reader
 * the list they were reading it in.
 */
export default function RiderHome() {
  const { user, loading: authLoading } = useAuth();
  const [params, setParams] = useSearchParams();
  const [pass, setPass] = useState<PassInfo | null>(null);
  const [ents, setEnts] = useState<Entitlement[]>([]);
  const [perks, setPerks] = useState<TrackPerk[]>([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState<string | null>(null);
  /** The venue whose inspector is open over the map; null leaves the map bare. */
  const [selectedId, setSelectedId] = useState<string | null>(null);
  /** Which slice of the network the rail lists: all of it, only the venues the
   *  pass includes, or the ones this rider follows. One state, two surfaces —
   *  the map dashes only what the rail leaves out. */
  const [view, setView] = useState<RailView>('all');
  /** The pill has been clicked: the opening slice is a default, not a fixture,
   *  so a rider's own choice outranks it from then on. */
  const slicePicked = useRef(false);
  /** The network itself comes from the shell — the header field reads the same
   *  copy, so the two surfaces can never disagree about what is on screen. */
  const { tracks, setTracks, loading: networkLoading } = useNetworkSearch();

  /** The track picked in the rail — what the inspector over the map shows. */
  const picked = selectedId ? tracks.find((t) => t.id === selectedId) : undefined;

  useEffect(() => {
    if (authLoading) return;
    let live = true;
    (async () => {
      // The pass is this account's own; the network arrives from the shell.
      if (user) {
        const p = await api.get<{ pass: PassInfo | null; entitlements: Entitlement[] }>('/me/pass');
        if (!live) return;
        if (!p.success) setErr(p.message);
        setPass(p.data?.pass ?? null);
        setEnts(p.data?.entitlements ?? []);
        // Offers are a pass's own: nothing to ask for until someone is signed in.
        const k = await api.get<{ perks: TrackPerk[] }>('/me/perks');
        if (!live) return;
        setPerks((k.data?.perks ?? []).filter((x) => x.trackId));
      } else {
        setPass(null);
        setEnts([]);
        setPerks([]);
      }
      setLoading(false);
    })();
    return () => {
      live = false;
    };
  }, [user, authLoading]);

  // The map keys its badges by trackId, the same shape the pass endpoint returns.
  const entMap = useMemo(() => {
    const map: Record<string, MapEntitlement> = {};
    for (const e of ents) map[e.trackId] = e;
    return map;
  }, [ents]);

  /** The pass's terms per track, keyed the same way — what the inspector reads. */
  const entById = useMemo(() => {
    const map: Record<string, Entitlement> = {};
    for (const e of ents) map[e.trackId] = e;
    return map;
  }, [ents]);

  /**
   * A venue profile's "On the map" hands its own track over as `?track=<slug>`:
   * the rail opens on that venue's inspector and its pin stays lit, the same
   * pick a click in the list makes.
   */
  useEffect(() => {
    const wanted = params.get('track');
    if (!wanted || selectedId) return;
    const t = tracks.find((x) => x.slug === wanted);
    if (t) setSelectedId(t.id);
  }, [params, tracks, selectedId]);

  /**
   * A follow control — in the rail or in the inspector — moves the network
   * itself: the flag is held on the track, so every row, the slice pills and
   * the map beside them agree the moment one is clicked rather than on the next
   * load.
   */
  const setFollow = useCallback((trackId: string, following: boolean) => {
    setTracks((prev) => prev.map((t) => (t.id === trackId ? { ...t, following } : t)));
  }, []);

  /**
   * Put the inspector away. A pick that arrived on `?track=<slug>` also has to
   * retire that param, or the effect above reopens the same venue the moment it
   * comes back.
   */
  const closePick = useCallback(() => {
    setSelectedId(null);
    if (!params.has('track')) return;
    const next = new URLSearchParams(params);
    next.delete('track');
    setParams(next, { replace: true });
  }, [params, setParams]);

  /**
   * A row's overlay or a pin: one click means one pick, and a second click on
   * the same venue puts the inspector away again. A bare click on the map is the
   * third way out: the map asks for `closePick` itself, which puts the inspector
   * away and lets the map come back out to the whole network.
   */
  const pick = useCallback(
    (trackId: string) => {
      if (trackId === selectedId) {
        closePick();
        return;
      }
      setSelectedId(trackId);
    },
    [selectedId, closePick]
  );

  /**
   * Whether the rail can be narrowed to what the pass carries at all: only a
   * running pass leaves a venue out. A visitor, the free tier and a lapsed pass
   * read every venue as live status rather than as terms, so the slice would
   * have nothing to say.
   */
  const canCover = pass?.status === 'ACTIVE' && !Boolean(pass?.tier.isDefault) && tracks.some((t) => !entMap[t.id]);

  /**
   * The rail opens on Included — the venues the pass carries — because that is
   * the slice a rider's pass actually speaks to. Only a running pass that
   * leaves venues out has one, and that is not known until the pass lands, so
   * the default is applied on that first arrival; a click on the pill retires
   * it, and a visitor or the free tier keeps the whole network.
   */
  useEffect(() => {
    if (slicePicked.current || !canCover) return;
    setView('covered');
  }, [canCover]);

  /**
   * The slice's one control fires this. A venue the covered slice leaves out
   * loses its pin, so an inspector open on one of them would outlive the thing
   * it belongs to: the pick is dropped with it rather than left standing on
   * nothing.
   */
  const setSlice = useCallback(
    (v: RailView) => {
      slicePicked.current = true;
      setView(v);
      if (v === 'covered' && selectedId && !entMap[selectedId]) setSelectedId(null);
    },
    [selectedId, entMap]
  );

  if (loading || authLoading || networkLoading) return <div className="muted">Loading the network…</div>;

  const active = pass?.status === 'ACTIVE';
  const free = Boolean(pass?.tier.isDefault);
  /** A pass is on the account but not running — expired, or never activated. */
  const lapsed = Boolean(pass) && !active && !free;
  /**
   * Nothing to count: a visitor, an account with no pass, the free tier, or a
   * lapsed pass. All four read the same network — each venue's live status —
   * so a rider whose pass has run out is not left with the whole page greyed
   * out; the notice above says why the terms are missing.
   */
  const gated = !pass || free || lapsed;
  /** The slice the rail is listing is the covered one — and only while a
   *  running pass leaves venues out, so the map's pins follow it. */
  const hiding = canCover && view === 'covered';

  return (
    <div className="stack pass-page">
      {err && <Banner tone="bad" close>{err}</Banner>}

      {free && (
        <Banner tone="warn" close floating ms={WARN_TOAST_MS}>
          You are on the free pass: every partner track and its live status, plus the tracks you
          follow. Included days and member discounts come with a paid pass.{' '}
          <Link className="inline" to="/pricing">
            See the tiers
          </Link>
          .
        </Banner>
      )}

      {pass && !active && !free && (
        <Banner tone="warn" close floating ms={WARN_TOAST_MS}>
          No active pass on this account, so the network is listed without terms.{' '}
          <Link className="inline" to="/pricing">
            See pass tiers
          </Link>
          .
        </Banner>
      )}

      <section className="pass-layout with-map">
        <div className={`pass-map${picked ? ' picked' : ''}`}>
          <Suspense fallback={<div className="muted" style={{ padding: 16 }}>Loading map…</div>}>
            <RiderTrackMap
              tracks={tracks}
              ents={entMap}
              gated={gated}
              hideUncovered={hiding}
              selectedId={selectedId}
              onSelect={pick}
              onClear={closePick}
            />
          </Suspense>

          {/* The rail lists the whole network for everyone — a visitor and a
              free rider read each venue's live status, a paid rider the days
              the pass leaves. It floats over the map's left edge and stays
              put: a pick opens the inspector, never a swap. */}
          <aside className="pass-aux">
            {/* The rail's head names who is reading and carries the list's own
                two controls in the same row — the filter and the sort ride
                inside DaysByTrack, so the head is one band, not two. */}
            <DaysByTrack
              identity={
                <span className="rail-pass-name">
                  {pass ? `${user?.name ?? 'Rider'} · ${pass.tier.name}` : 'The network'}
                </span>
              }
              ents={ents}
              tracks={tracks}
              gated={gated}
              view={view}
              onView={setSlice}
              canCover={canCover}
              selectedId={selectedId}
              onSelect={pick}
            />
          </aside>

          {/* The picked venue, attached to the map's right edge: the same facts
              the rail used to swap itself for, without giving up the list. */}
          {picked && (
            <aside className="venue-float" aria-label={`${picked.name}: venue details`}>
              <TrackPanel
                track={picked}
                ent={entById[picked.id]}
                perks={entById[picked.id] ? perks.filter((p) => p.trackId === entById[picked.id]?.trackId) : []}
                active={active}
                gated={gated}
                lapsed={lapsed}
                onClose={closePick}
                onFollow={setFollow}
              />
            </aside>
          )}
        </div>
      </section>
    </div>
  );
}

